#[derive(Clone)]
struct CoachMutationReplayEntry {
    request_fingerprint: String,
    response_json: Value,
    stored_at_epoch_ms: u128,
}

type CoachMutationReplayMap = HashMap<String, CoachMutationReplayEntry>;

fn coach_shamell_pay_fee_minor_units(gross_minor_units: i64) -> i64 {
    if gross_minor_units <= 0 {
        return 0;
    }
    (gross_minor_units * COACH_SHAMELL_PAY_FEE_BPS + 5_000) / 10_000
}

