const CHAT_MESSAGE_KEY_ID_MAX_LEN: usize = 64;
const CHAT_MESSAGE_EXPIRE_AFTER_SECONDS_MIN: i64 = 10;
const CHAT_MESSAGE_EXPIRE_AFTER_SECONDS_MAX: i64 = 7 * 24 * 3600;
