const CHAT_SIGNED_PREKEY_MAX_LEN: usize = 8192;
const CHAT_PREKEY_BATCH_MIN_ITEMS: usize = 1;
const CHAT_PREKEY_BATCH_MAX_ITEMS: usize = 500;
const CHAT_PREKEY_KEY_B64_MIN_LEN: usize = 16;
const CHAT_PREKEY_KEY_B64_MAX_LEN: usize = 8192;
const CHAT_SIGNED_PREKEY_SIG_ALG_ED25519: &str = "ed25519";
const CHAT_MAILBOX_TOKEN_MIN_LEN: usize = 32;
const CHAT_MAILBOX_TOKEN_MAX_LEN: usize = 256;
const CHAT_MAILBOX_ENVELOPE_B64_MIN_LEN: usize = 16;
const CHAT_MAILBOX_ENVELOPE_B64_MAX_LEN: usize = 131_072;
const CHAT_MAILBOX_SENDER_HINT_MAX_LEN: usize = 64;
const CHAT_MAILBOX_EXPIRE_AFTER_SECONDS_MIN: i64 = 60;
const CHAT_MAILBOX_EXPIRE_AFTER_SECONDS_MAX: i64 = 7 * 24 * 3600;
const CHAT_MAILBOX_POLL_LIMIT_MIN: i64 = 1;
const CHAT_MAILBOX_POLL_LIMIT_MAX: i64 = 200;
const CHAT_GROUP_NAME_MAX_CHARS: usize = 120;
const CHAT_GROUP_MEMBER_IDS_MAX_ITEMS: usize = 200;
const CHAT_GROUP_AVATAR_MAX_BYTES: usize = 256 * 1024;
const CHAT_GROUP_AVATAR_MAX_B64_LEN: usize = CHAT_GROUP_AVATAR_MAX_BYTES.div_ceil(3) * 4;
const CHAT_GROUP_KEY_FP_MAX_LEN: usize = 128;
const CONTACT_INVITE_TOKEN_HEX_LEN: usize = 64;
