fn chat_device_id_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^[A-Za-z0-9_-]{4,24}$").expect("valid regex"))
}

fn is_reserved_chat_device_id(device_id: &str) -> bool {
    const RESERVED: &[&str] = &["register"];
    RESERVED
        .iter()
        .any(|word| device_id.trim().eq_ignore_ascii_case(word))
}

fn is_valid_chat_device_id(device_id: &str) -> bool {
    chat_device_id_re().is_match(device_id) && !is_reserved_chat_device_id(device_id)
}

fn chat_group_id_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^[A-Za-z0-9_-]{4,36}$").expect("valid regex"))
}

fn is_valid_chat_group_id(group_id: &str) -> bool {
    chat_group_id_re().is_match(group_id.trim())
}

fn chat_push_platform_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^[A-Za-z0-9._-]{1,30}$").expect("valid push platform regex"))
}

fn chat_mailbox_token_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^[A-Za-z0-9_-]{32,256}$").expect("valid mailbox token regex"))
}

fn is_valid_chat_push_token(token: &str) -> bool {
    let value = token.trim();
    if value.len() < CHAT_PUSH_TOKEN_MIN_LEN || value.len() > CHAT_PUSH_TOKEN_MAX_LEN {
        return false;
    }
    value.chars().all(|ch| ch.is_ascii_graphic())
}

fn is_valid_chat_push_platform(platform: &str) -> bool {
    let value = platform.trim();
    if value.is_empty() || value.len() > CHAT_PUSH_PLATFORM_MAX_LEN {
        return false;
    }
    chat_push_platform_re().is_match(value)
}

fn validate_chat_mailbox_token(token: &str) -> ApiResult<()> {
    if token.len() < CHAT_MAILBOX_TOKEN_MIN_LEN || token.len() > CHAT_MAILBOX_TOKEN_MAX_LEN {
        return Err(ApiError::bad_request("invalid mailbox_token"));
    }
    if !chat_mailbox_token_re().is_match(token) {
        return Err(ApiError::bad_request("invalid mailbox_token"));
    }
    Ok(())
}

fn validate_chat_mailbox_sender_hint(sender_hint: &str) -> ApiResult<()> {
    if sender_hint.len() > CHAT_MAILBOX_SENDER_HINT_MAX_LEN
        || sender_hint.chars().any(|ch| ch.is_ascii_control())
    {
        return Err(ApiError::bad_request("invalid sender_hint"));
    }
    Ok(())
}

fn normalize_contact_invite_token(raw: &str) -> ApiResult<String> {
    let token = raw.trim().to_ascii_lowercase();
    if token.len() != CONTACT_INVITE_TOKEN_HEX_LEN {
        return Err(ApiError::bad_request("invalid token"));
    }
    if !token.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err(ApiError::bad_request("invalid token"));
    }
    Ok(token)
}

fn is_valid_chat_key_material(value: &str, min_len: usize, max_len: usize) -> bool {
    if value.len() < min_len || value.len() > max_len {
        return false;
    }
    value.bytes().all(|byte| {
        byte.is_ascii_alphanumeric() || matches!(byte, b'+' | b'/' | b'=' | b'-' | b'_')
    })
}

fn validate_chat_key_material(
    value: &str,
    field_name: &'static str,
    min_len: usize,
    max_len: usize,
) -> ApiResult<()> {
    if !is_valid_chat_key_material(value, min_len, max_len) {
        return Err(ApiError::bad_request(format!("invalid {field_name}")));
    }
    Ok(())
}

fn validate_chat_direct_box_b64(value: &str) -> ApiResult<()> {
    if value.len() > CHAT_MESSAGE_BOX_B64_MAX_LEN {
        return Err(ApiError::bad_request("direct message too large"));
    }
    validate_chat_key_material(
        value,
        "box_b64",
        CHAT_MESSAGE_BOX_B64_MIN_LEN,
        CHAT_MESSAGE_BOX_B64_MAX_LEN,
    )
}

