#[derive(Debug, Clone)]
struct StoredRidePricingPolicy {
    ride_class: String,
    rule: RidePricingRule,
    updated_at: String,
    updated_by_account_id: Option<String>,
}

fn default_ride_pricing_rule(ride_class: &str) -> Option<RidePricingRule> {
    match ride_class {
        "economy" => Some(RidePricingRule {
            base_fare_minor_units: 700,
            per_km_minor_units: 130,
            per_minute_minor_units: 35,
            traffic_delay_per_minute_minor_units: 18,
            booking_fee_minor_units: 150,
            minimum_fare_minor_units: 1_100,
            driver_share_bps: 8_200,
        }),
        "xl" => Some(RidePricingRule {
            base_fare_minor_units: 1_100,
            per_km_minor_units: 180,
            per_minute_minor_units: 50,
            traffic_delay_per_minute_minor_units: 28,
            booking_fee_minor_units: 220,
            minimum_fare_minor_units: 1_800,
            driver_share_bps: 8_400,
        }),
        "premium" => Some(RidePricingRule {
            base_fare_minor_units: 1_600,
            per_km_minor_units: 260,
            per_minute_minor_units: 70,
            traffic_delay_per_minute_minor_units: 40,
            booking_fee_minor_units: 320,
            minimum_fare_minor_units: 2_600,
            driver_share_bps: 8_650,
        }),
        "delivery" => Some(RidePricingRule {
            base_fare_minor_units: 900,
            per_km_minor_units: 150,
            per_minute_minor_units: 40,
            traffic_delay_per_minute_minor_units: 22,
            booking_fee_minor_units: 180,
            minimum_fare_minor_units: 1_400,
            driver_share_bps: 8_000,
        }),
        "corporate" => Some(RidePricingRule {
            base_fare_minor_units: 1_900,
            per_km_minor_units: 300,
            per_minute_minor_units: 85,
            traffic_delay_per_minute_minor_units: 48,
            booking_fee_minor_units: 360,
            minimum_fare_minor_units: 3_200,
            driver_share_bps: 8_850,
        }),
        _ => None,
    }
}

fn ride_pricing_policy_json(policy: &StoredRidePricingPolicy) -> Value {
    json!({
        "ride_class": policy.ride_class,
        "base_fare_minor_units": policy.rule.base_fare_minor_units,
        "per_km_minor_units": policy.rule.per_km_minor_units,
        "per_minute_minor_units": policy.rule.per_minute_minor_units,
        "traffic_delay_per_minute_minor_units": policy.rule.traffic_delay_per_minute_minor_units,
        "booking_fee_minor_units": policy.rule.booking_fee_minor_units,
        "minimum_fare_minor_units": policy.rule.minimum_fare_minor_units,
        "driver_share_bps": policy.rule.driver_share_bps,
        "updated_at": policy.updated_at,
        "updated_by_account_id": policy.updated_by_account_id,
    })
}

fn parse_ride_pricing_policy_row(row: &PgRow) -> ApiResult<StoredRidePricingPolicy> {
    let ride_class: String = row
        .try_get("ride_class")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let base_fare_minor_units: i64 = row
        .try_get("base_fare_minor_units")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let per_km_minor_units: i64 = row
        .try_get("per_km_minor_units")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let per_minute_minor_units: i64 = row
        .try_get("per_minute_minor_units")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let traffic_delay_per_minute_minor_units: i64 = row
        .try_get("traffic_delay_per_minute_minor_units")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let booking_fee_minor_units: i64 = row
        .try_get("booking_fee_minor_units")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let minimum_fare_minor_units: i64 = row
        .try_get("minimum_fare_minor_units")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let driver_share_bps: i64 = row
        .try_get("driver_share_bps")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let updated_at: String = row
        .try_get("updated_at")
        .map_err(|_| ApiError::internal("ride pricing policy unavailable"))?;
    let updated_by_account_id = row.try_get("updated_by_account_id").ok().flatten();
    Ok(StoredRidePricingPolicy {
        ride_class,
        rule: RidePricingRule {
            base_fare_minor_units,
            per_km_minor_units,
            per_minute_minor_units,
            traffic_delay_per_minute_minor_units,
            booking_fee_minor_units,
            minimum_fare_minor_units,
            driver_share_bps,
        },
        updated_at,
        updated_by_account_id,
    })
}

async fn load_ride_pricing_policy(
    state: &AppState,
    ride_class: &str,
) -> ApiResult<StoredRidePricingPolicy> {
    if let Some(auth_runtime) = state.auth.as_ref() {
        let row = sqlx::query(
            r#"
            SELECT
              ride_class,
              base_fare_minor_units,
              per_km_minor_units,
              per_minute_minor_units,
              traffic_delay_per_minute_minor_units,
              booking_fee_minor_units,
              minimum_fare_minor_units,
              driver_share_bps,
              updated_by_account_id,
              to_char(updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS updated_at
            FROM auth_ride_pricing_policies
            WHERE ride_class = $1
            LIMIT 1
            "#,
        )
        .bind(ride_class)
        .fetch_optional(auth_runtime.pool())
        .await
        .map_err(|error| {
            tracing::error!(%error, ride_class, "ride pricing policy lookup failed");
            ApiError::internal("ride pricing policy unavailable")
        })?;
        if let Some(row) = row {
            return parse_ride_pricing_policy_row(&row);
        }
    }
    let rule = default_ride_pricing_rule(ride_class)
        .ok_or_else(|| ApiError::bad_request("invalid ride_class"))?;
    Ok(StoredRidePricingPolicy {
        ride_class: ride_class.to_string(),
        rule,
        updated_at: now_rfc3339(),
        updated_by_account_id: Some("default".to_string()),
    })
}

async fn load_all_ride_pricing_policies(
    state: &AppState,
) -> ApiResult<Vec<StoredRidePricingPolicy>> {
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let rows = sqlx::query(
        r#"
        SELECT
          ride_class,
          base_fare_minor_units,
          per_km_minor_units,
          per_minute_minor_units,
          traffic_delay_per_minute_minor_units,
          booking_fee_minor_units,
          minimum_fare_minor_units,
          driver_share_bps,
          updated_by_account_id,
          to_char(updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS updated_at
        FROM auth_ride_pricing_policies
        ORDER BY ride_class ASC
        "#,
    )
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, "ride pricing policies lookup failed");
        ApiError::internal("ride pricing policy unavailable")
    })?;
    rows.into_iter()
        .map(|row| parse_ride_pricing_policy_row(&row))
        .collect()
}

fn div_ceil_i64(value: i64, divisor: i64) -> i64 {
    if value <= 0 {
        return 0;
    }
    ((value - 1) / divisor) + 1
}

fn round_div_i64(value: i64, divisor: i64) -> i64 {
    if value <= 0 {
        return 0;
    }
    (value + (divisor / 2)) / divisor
}

fn driver_ride_platform_fee_cents(fare_estimate_cents: i64) -> i64 {
    div_ceil_i64(
        fare_estimate_cents.saturating_mul(DRIVER_RIDE_PLATFORM_FEE_BPS),
        10_000,
    )
}

fn build_ride_pricing_preview_with_rule(
    ride_class: &str,
    rule: RidePricingRule,
    distance_m: i64,
    eta_s: i64,
    traffic_delay_s: i64,
) -> Value {
    let distance_component_minor_units =
        div_ceil_i64(distance_m.saturating_mul(rule.per_km_minor_units), 1_000);
    let time_component_minor_units =
        div_ceil_i64(eta_s.saturating_mul(rule.per_minute_minor_units), 60);
    let traffic_surcharge_minor_units = div_ceil_i64(
        traffic_delay_s.saturating_mul(rule.traffic_delay_per_minute_minor_units),
        60,
    );
    let subtotal_before_minimum = rule
        .base_fare_minor_units
        .saturating_add(distance_component_minor_units)
        .saturating_add(time_component_minor_units)
        .saturating_add(traffic_surcharge_minor_units);
    let minimum_fare_lift_minor_units =
        (rule.minimum_fare_minor_units - subtotal_before_minimum).max(0);
    let subtotal_after_minimum =
        subtotal_before_minimum.saturating_add(minimum_fare_lift_minor_units);
    let total_fare_minor_units =
        subtotal_after_minimum.saturating_add(rule.booking_fee_minor_units);
    let suggested_driver_payout_minor_units = round_div_i64(
        subtotal_after_minimum.saturating_mul(rule.driver_share_bps),
        10_000,
    );
    let platform_margin_minor_units =
        total_fare_minor_units.saturating_sub(suggested_driver_payout_minor_units);

    json!({
        "ride_class": ride_class,
        "currency": "SYP",
        "distance_m": distance_m,
        "eta_s": eta_s,
        "traffic_delay_s": traffic_delay_s,
        "breakdown": {
            "base_fare_minor_units": rule.base_fare_minor_units,
            "distance_component_minor_units": distance_component_minor_units,
            "time_component_minor_units": time_component_minor_units,
            "traffic_surcharge_minor_units": traffic_surcharge_minor_units,
            "booking_fee_minor_units": rule.booking_fee_minor_units,
            "minimum_fare_lift_minor_units": minimum_fare_lift_minor_units,
        },
        "total_fare_minor_units": total_fare_minor_units,
        "suggested_driver_payout_minor_units": suggested_driver_payout_minor_units,
        "platform_margin_minor_units": platform_margin_minor_units,
    })
}

#[cfg(test)]
fn build_ride_pricing_preview(
    ride_class: &str,
    distance_m: i64,
    eta_s: i64,
    traffic_delay_s: i64,
) -> Option<Value> {
    let rule = default_ride_pricing_rule(ride_class)?;
    Some(build_ride_pricing_preview_with_rule(
        ride_class,
        rule,
        distance_m,
        eta_s,
        traffic_delay_s,
    ))
}

fn json_no_store_response(value: Value) -> Response {
    let mut resp = axum::Json(value).into_response();
    resp.headers_mut().insert(
        header::CACHE_CONTROL,
        axum::http::HeaderValue::from_static("no-store"),
    );
    resp
}

fn bytes_no_store_attachment_response(
    content_type: &'static str,
    disposition: &'static str,
    body: Vec<u8>,
) -> Response {
    let mut resp = Response::new(Body::from(body));
    let headers = resp.headers_mut();
    headers.insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
    headers.insert(CONTENT_TYPE, HeaderValue::from_static(content_type));
    headers.insert(
        header::CONTENT_DISPOSITION,
        HeaderValue::from_static(disposition),
    );
    resp
}

fn active_trip_json_response(active: Option<Value>) -> Response {
    json_no_store_response(json!({
        "active": active,
    }))
}

fn contact_invite_create_response(token: &str, expires_at: &str, max_uses: i64) -> Response {
    json_no_store_response(json!({
        "token": token,
        "expires_at": expires_at,
        "max_uses": max_uses,
    }))
}

fn contact_device_id_response(device_id: &str) -> Response {
    json_no_store_response(json!({
        "device_id": device_id,
    }))
}

fn normalize_group_visibility_error(err: ApiError) -> ApiError {
    let hides_group_visibility = (err.status == StatusCode::NOT_FOUND
        && err.detail.eq_ignore_ascii_case("unknown group"))
        || (err.status == StatusCode::FORBIDDEN
            && (err.detail.eq_ignore_ascii_case("not a member")
                || err.detail.eq_ignore_ascii_case("admin required")));
    if hides_group_visibility {
        ApiError::new(StatusCode::NOT_FOUND, "not found")
    } else {
        err
    }
}

fn sanitize_geo_accept_language(headers: &HeaderMap) -> &'static str {
    let lang = headers
        .get(header::ACCEPT_LANGUAGE)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .unwrap_or_default()
        .to_ascii_lowercase();
    if lang.starts_with("ar") {
        "ar"
    } else {
        "en"
    }
}

fn sanitize_tomtom_language(headers: &HeaderMap) -> &'static str {
    let lang = headers
        .get(header::ACCEPT_LANGUAGE)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .unwrap_or_default()
        .to_ascii_lowercase();
    if lang.starts_with("ar") {
        // TomTom accepts `ar` (while several other 2-letter tags return 400).
        "ar"
    } else if lang.starts_with("de") {
        "de-DE"
    } else if lang.starts_with("fr") {
        "fr-FR"
    } else if lang.starts_with("es") {
        "es-ES"
    } else if lang.starts_with("it") {
        "it-IT"
    } else if lang.starts_with("tr") {
        "tr-TR"
    } else {
        // `en` is rejected by TomTom search; use regioned English.
        "en-US"
    }
}

fn round_nominatim_coordinate(value: f64) -> f64 {
    (value * 10000.0).round() / 10000.0
}

fn sanitize_reverse_geocode_payload(value: &Value) -> Value {
    let mut out = serde_json::Map::new();
    if let Some(name) = value
        .get("name")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        out.insert("name".to_string(), Value::String(name.to_string()));
    }
    if let Some(display_name) = value
        .get("display_name")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        out.insert(
            "display_name".to_string(),
            Value::String(display_name.to_string()),
        );
    }
    Value::Object(out)
}

fn sanitize_search_geocode_payload(value: &Value) -> Value {
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    if let Some(items) = value.as_array() {
        for item in items {
            let Some(display_name) = item
                .get("display_name")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            else {
                continue;
            };
            if !seen.insert(display_name.to_string()) {
                continue;
            }
            out.push(json!({ "display_name": display_name }));
            if out.len() >= NOMINATIM_RESULT_LIMIT {
                break;
            }
        }
    }
    Value::Array(out)
}

fn parse_nominatim_position(item: &Value) -> Option<(f64, f64)> {
    let lat = item.get("lat").and_then(|value| {
        value
            .as_f64()
            .or_else(|| value.as_str()?.trim().parse().ok())
    })?;
    let lon = item.get("lon").and_then(|value| {
        value
            .as_f64()
            .or_else(|| value.as_str()?.trim().parse().ok())
    })?;
    if !lat.is_finite() || !lon.is_finite() {
        return None;
    }
    if !(-90.0..=90.0).contains(&lat) || !(-180.0..=180.0).contains(&lon) {
        return None;
    }
    Some((round_tomtom_coordinate(lat), round_tomtom_coordinate(lon)))
}

fn sanitize_nominatim_ride_search_payload(
    value: &Value,
    limit: usize,
    near: Option<(f64, f64)>,
) -> Value {
    let Some(items) = value.as_array() else {
        return Value::Array(Vec::new());
    };
    let mut ranked = Vec::new();
    let mut seen = HashSet::new();
    for item in items {
        let Some(display_name) = item
            .get("display_name")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|text| !text.is_empty())
        else {
            continue;
        };
        let Some((lat, lon)) = parse_nominatim_position(item) else {
            continue;
        };
        let key = format!("{display_name}|{lat:.6}|{lon:.6}");
        if !seen.insert(key) {
            continue;
        }
        let distance_score = near.map(|(near_lat, near_lon)| {
            let lat_delta = lat - near_lat;
            let lon_delta = lon - near_lon;
            (lat_delta * lat_delta) + (lon_delta * lon_delta)
        });
        ranked.push((
            distance_score,
            json!({
                "display_name": display_name,
                "lat": lat,
                "lon": lon,
            }),
        ));
    }
    if near.is_some() {
        ranked.sort_by(|left, right| {
            match (left.0, right.0) {
                (Some(a), Some(b)) => a.total_cmp(&b),
                (Some(_), None) => std::cmp::Ordering::Less,
                (None, Some(_)) => std::cmp::Ordering::Greater,
                (None, None) => std::cmp::Ordering::Equal,
            }
            .then_with(|| {
                left.1["display_name"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(right.1["display_name"].as_str().unwrap_or_default())
            })
            .then_with(|| {
                left.1["lat"]
                    .as_f64()
                    .unwrap_or_default()
                    .total_cmp(&right.1["lat"].as_f64().unwrap_or_default())
            })
            .then_with(|| {
                left.1["lon"]
                    .as_f64()
                    .unwrap_or_default()
                    .total_cmp(&right.1["lon"].as_f64().unwrap_or_default())
            })
        });
    }
    Value::Array(
        ranked
            .into_iter()
            .take(limit)
            .map(|(_, item)| item)
            .collect(),
    )
}

fn geo_lookup_cache_key(path: &str, query: &[(&str, String)], accept_language: &str) -> String {
    let mut key = format!("path={path}|lang={accept_language}");
    for (query_key, query_value) in query {
        key.push('|');
        key.push_str(query_key);
        key.push('=');
        key.push_str(query_value.trim());
    }
    key
}

async fn fetch_nominatim_json(
    state: &AppState,
    path: &str,
    query: &[(&str, String)],
    accept_language: &'static str,
) -> ApiResult<Value> {
    let cache_key = geo_lookup_cache_key(path, query, accept_language);
    if let Some(cached) = state.cached_geo_lookup_json(&cache_key).await {
        return Ok(cached);
    }

    let base_url = state.geo_lookup_base_url.trim();
    let upstream_base = if base_url.is_empty() {
        DEFAULT_GEO_LOOKUP_BASE_URL
    } else {
        base_url
    };
    let path_hash = auth::hash_prefix(path);
    let mut url = reqwest::Url::parse(&format!("{}{path}", upstream_base.trim_end_matches('/')))
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream_base,
                "invalid nominatim url"
            );
            ApiError::internal("location lookup unavailable")
        })?;
    {
        let mut pairs = url.query_pairs_mut();
        for (key, value) in query {
            pairs.append_pair(key, value);
        }
    }

    let resp = state
        .http
        .request(Method::GET, url)
        .header(header::ACCEPT, "application/json")
        .header(header::ACCEPT_LANGUAGE, accept_language)
        .send()
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream_base,
                "nominatim upstream call failed"
            );
            ApiError::internal("location lookup unavailable")
        })?;
    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let bytes =
        read_response_body_limited(resp, state.max_upstream_body_bytes, "geo", path).await?;
    if !status.is_success() {
        tracing::warn!(
            status = %status,
            path_hash,
            upstream_base,
            "nominatim upstream returned non-success"
        );
        return Err(ApiError::upstream(
            StatusCode::BAD_GATEWAY,
            "location lookup unavailable",
        ));
    }

    let payload = serde_json::from_slice(&bytes).map_err(|e| {
        tracing::error!(
            error = %e,
            path_hash,
            upstream_base,
            "nominatim upstream returned invalid json"
        );
        ApiError::internal("location lookup unavailable")
    })?;
    state
        .remember_geo_lookup_json(
            &cache_key,
            &payload,
            Duration::from_secs(GEO_LOOKUP_CACHE_TTL_SECS),
            GEO_LOOKUP_CACHE_MAX_ENTRIES,
        )
        .await;
    Ok(payload)
}

fn tomtom_base_url() -> String {
    let raw = std::env::var("BFF_TOMTOM_BASE_URL")
        .unwrap_or_else(|_| TOMTOM_BASE_URL_DEFAULT.to_string());
    let trimmed = raw.trim().trim_end_matches('/');
    if trimmed.is_empty() {
        TOMTOM_BASE_URL_DEFAULT.to_string()
    } else {
        trimmed.to_string()
    }
}

fn tomtom_api_key() -> Option<String> {
    std::env::var("BFF_TOMTOM_API_KEY")
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn normalize_tomtom_tile_selector(
    raw: Option<&str>,
    field: &'static str,
    default: &'static str,
) -> ApiResult<String> {
    let trimmed = raw.unwrap_or(default).trim();
    if trimmed.is_empty() {
        return Ok(default.to_string());
    }
    if trimmed.len() > TOMTOM_TILE_SELECTOR_MAX_LEN
        || !trimmed
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
    {
        return Err(ApiError::bad_request(format!("invalid {field}")));
    }
    Ok(trimmed.to_ascii_lowercase())
}

fn normalize_tomtom_tile_view(raw: Option<&str>) -> ApiResult<String> {
    let trimmed = raw.unwrap_or("Unified").trim();
    if trimmed.is_empty() {
        return Ok("Unified".to_string());
    }
    if trimmed.len() > TOMTOM_TILE_VIEW_MAX_LEN
        || !trimmed
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
    {
        return Err(ApiError::bad_request("invalid view"));
    }
    Ok(trimmed.to_string())
}

fn normalize_tomtom_tile_language(raw: Option<&str>) -> ApiResult<String> {
    let trimmed = raw.unwrap_or("en-US").trim();
    if trimmed.is_empty() {
        return Ok("en-US".to_string());
    }
    if trimmed.len() > TOMTOM_TILE_LANGUAGE_MAX_LEN
        || !trimmed
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-')
    {
        return Err(ApiError::bad_request("invalid language"));
    }
    Ok(trimmed.to_string())
}

fn normalize_tomtom_tile_size(raw: Option<u16>) -> ApiResult<u16> {
    match raw.unwrap_or(256) {
        256 | 512 => Ok(raw.unwrap_or(256)),
        _ => Err(ApiError::bad_request("tileSize must be 256 or 512")),
    }
}

fn validate_tomtom_tile_coordinates(z: u8, x: u32, y: u32) -> ApiResult<()> {
    if z > TOMTOM_TILE_ZOOM_MAX {
        return Err(ApiError::bad_request("z must be between 0 and 22"));
    }
    let max_index = 1u64 << u32::from(z);
    if u64::from(x) >= max_index {
        return Err(ApiError::bad_request("x is out of range for z"));
    }
    if u64::from(y) >= max_index {
        return Err(ApiError::bad_request("y is out of range for z"));
    }
    Ok(())
}

fn clamp_ride_search_limit(raw: Option<usize>) -> usize {
    let value = raw.unwrap_or(5);
    value.clamp(TOMTOM_SEARCH_LIMIT_MIN, TOMTOM_SEARCH_LIMIT_MAX)
}

const COACH_SYRIA_ONLY_SEARCH_DETAIL: &str =
    "coach mini program currently supports Syria routes between Damascus, Homs, Aleppo, and Latakia only";

fn normalize_coach_location_text(raw: &str, field_name: &'static str) -> ApiResult<String> {
    let normalized = raw.split_whitespace().collect::<Vec<_>>().join(" ");
    let len = normalized.chars().count();
    if len < 2 {
        return Err(ApiError::bad_request(format!(
            "{field_name} must be at least 2 characters"
        )));
    }
    if len > 80 {
        return Err(ApiError::bad_request(format!(
            "{field_name} must be at most 80 characters"
        )));
    }
    Ok(normalized)
}

fn coach_search_location_scope_key(raw: &str) -> String {
    raw.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

fn coach_location_allowed_for_syria_passenger_search(normalized: &str) -> bool {
    matches!(
        coach_search_location_scope_key(normalized).as_str(),
        "damascus"
            | "damascus central"
            | "damascus bus station"
            | "دمشق"
            | "محطة دمشق المركزية"
            | "homs"
            | "homs gateway"
            | "homs bus station"
            | "حمص"
            | "aleppo"
            | "aleppo terminal"
            | "aleppo central bus terminal"
            | "حلب"
            | "محطة حلب المركزية"
            | "latakia"
            | "latakia bus station"
            | "اللاذقية"
    )
}

fn validate_coach_passenger_search_location(
    raw: &str,
    field_name: &'static str,
) -> ApiResult<String> {
    let normalized = normalize_coach_location_text(raw, field_name)?;
    if !coach_location_allowed_for_syria_passenger_search(&normalized) {
        return Err(ApiError::bad_request(COACH_SYRIA_ONLY_SEARCH_DETAIL));
    }
    Ok(normalized)
}

fn validate_coach_departure_date(raw: &str) -> ApiResult<String> {
    let normalized = raw.trim();
    let date = chrono::NaiveDate::parse_from_str(normalized, "%Y-%m-%d")
        .map_err(|_| ApiError::bad_request("departure_date must use YYYY-MM-DD"))?;
    Ok(date.format("%Y-%m-%d").to_string())
}

fn validate_coach_passenger_count(raw: Option<u8>) -> ApiResult<u8> {
    let passengers = raw.unwrap_or(1);
    if passengers == 0 || passengers > 9 {
        return Err(ApiError::bad_request("passengers must be between 1 and 9"));
    }
    Ok(passengers)
}

fn coach_identifier_is_valid(normalized: &str, min_len: usize, max_len: usize) -> bool {
    if normalized.len() < min_len || normalized.len() > max_len {
        return false;
    }
    normalized
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
}

fn validate_coach_resource_id(raw: &str, field_name: &'static str) -> ApiResult<String> {
    let normalized = raw.trim();
    if !coach_identifier_is_valid(normalized, 3, 64) {
        return Err(ApiError::bad_request(format!("invalid {field_name}")));
    }
    Ok(normalized.to_string())
}

fn validate_coach_passenger_ids(
    raw: Option<Vec<String>>,
    passengers: u8,
) -> ApiResult<Vec<String>> {
    let ids = raw.unwrap_or_else(|| {
        (1..=usize::from(passengers))
            .map(|index| format!("pax_{}", index))
            .collect()
    });
    if ids.len() != usize::from(passengers) {
        return Err(ApiError::bad_request(
            "passenger_ids must match passenger count",
        ));
    }
    let mut normalized = Vec::with_capacity(ids.len());
    let mut seen = HashSet::new();
    for value in ids {
        let trimmed = value.trim();
        if !coach_identifier_is_valid(trimmed, 3, 32) {
            return Err(ApiError::bad_request("invalid passenger_ids"));
        }
        if !seen.insert(trimmed.to_ascii_lowercase()) {
            return Err(ApiError::bad_request("passenger_ids must be unique"));
        }
        normalized.push(trimmed.to_string());
    }
    Ok(normalized)
}

fn validate_coach_preferred_seat_numbers(
    raw: Option<Vec<String>>,
    passengers: u8,
) -> ApiResult<Vec<String>> {
    let Some(values) = raw else {
        return Ok(Vec::new());
    };
    if values.is_empty() {
        return Ok(Vec::new());
    }
    if values.len() > usize::from(passengers) {
        return Err(ApiError::bad_request(
            "preferred_seat_numbers cannot exceed passenger count",
        ));
    }
    let mut normalized = Vec::with_capacity(values.len());
    let mut seen = HashSet::new();
    for value in values {
        let trimmed = value.trim().to_ascii_uppercase();
        if trimmed.is_empty()
            || trimmed.len() > 8
            || !trimmed
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '-')
        {
            return Err(ApiError::bad_request("invalid preferred_seat_numbers"));
        }
        if !seen.insert(trimmed.clone()) {
            return Err(ApiError::bad_request(
                "preferred_seat_numbers must be unique",
            ));
        }
        normalized.push(trimmed);
    }
    Ok(normalized)
}

#[derive(Clone)]
struct CoachPassengerManifestNormalized {
    passenger_id: String,
    given_name: String,
    family_name: String,
    rider_category: String,
    nationality_code: Option<String>,
}

#[derive(Clone)]
struct CoachStoredBookingAggregate {
    account_id: String,
    booking: Value,
    offer: Option<Value>,
    hold: Option<Value>,
    journey: Option<Value>,
    passengers_manifest: Value,
    tickets: Vec<Value>,
}

#[derive(Clone)]
struct CoachStoredMutationReplayEntry {
    command: String,
    idempotency_key: String,
    response_json: Value,
    created_at: String,
}

#[derive(Default)]
struct CoachMutationReplayIndex {
    booking_creates: HashMap<String, CoachStoredMutationReplayEntry>,
    ticket_issues: HashMap<String, Vec<CoachStoredMutationReplayEntry>>,
    refund_requests: HashMap<String, Vec<CoachStoredMutationReplayEntry>>,
    change_requests: HashMap<String, Vec<CoachStoredMutationReplayEntry>>,
}

fn normalize_coach_person_name(raw: &str, field_name: &'static str) -> ApiResult<String> {
    let normalized = raw.split_whitespace().collect::<Vec<_>>().join(" ");
    let len = normalized.chars().count();
    if !(1..=80).contains(&len) || normalized.chars().any(char::is_control) {
        return Err(ApiError::bad_request(format!("invalid {field_name}")));
    }
    Ok(normalized)
}

fn canonical_coach_rider_category(raw: &str) -> ApiResult<&'static str> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "adult" => Ok("adult"),
        "child" => Ok("child"),
        "student" => Ok("student"),
        "senior" => Ok("senior"),
        _ => Err(ApiError::bad_request("invalid rider_category")),
    }
}

fn validate_coach_nationality_code(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    if value.len() != 2 || !value.chars().all(|ch| ch.is_ascii_alphabetic()) {
        return Err(ApiError::bad_request("invalid nationality_code"));
    }
    Ok(Some(value.to_ascii_uppercase()))
}

fn validate_coach_passenger_manifests(
    raw: Option<Vec<CoachPassengerManifestIn>>,
    passengers: u8,
) -> ApiResult<Vec<CoachPassengerManifestNormalized>> {
    let Some(values) = raw else {
        return Ok(Vec::new());
    };
    if values.len() != usize::from(passengers) {
        return Err(ApiError::bad_request(
            "passengers_manifest must match passenger count",
        ));
    }
    let mut normalized = Vec::with_capacity(values.len());
    let mut seen = HashSet::new();
    for value in values {
        let passenger_id = validate_coach_resource_id(&value.passenger_id, "passenger_id")?;
        if !seen.insert(passenger_id.clone()) {
            return Err(ApiError::bad_request(
                "passengers_manifest passenger_id must be unique",
            ));
        }
        normalized.push(CoachPassengerManifestNormalized {
            passenger_id,
            given_name: normalize_coach_person_name(&value.given_name, "given_name")?,
            family_name: normalize_coach_person_name(&value.family_name, "family_name")?,
            rider_category: canonical_coach_rider_category(&value.rider_category)?.to_string(),
            nationality_code: validate_coach_nationality_code(value.nationality_code.as_deref())?,
        });
    }
    Ok(normalized)
}

fn coach_passenger_manifest_ids(values: &[CoachPassengerManifestNormalized]) -> Vec<String> {
    values
        .iter()
        .map(|value| value.passenger_id.clone())
        .collect::<Vec<_>>()
}

fn validate_coach_passenger_manifest_alignment(
    passenger_ids: &[String],
    passengers_manifest: &[CoachPassengerManifestNormalized],
) -> ApiResult<()> {
    if passengers_manifest.is_empty() {
        return Ok(());
    }
    let manifest_ids = coach_passenger_manifest_ids(passengers_manifest);
    if manifest_ids != passenger_ids {
        return Err(ApiError::bad_request(
            "passengers_manifest passenger_id must match passenger_ids",
        ));
    }
    Ok(())
}

fn validate_coach_ticket_ids(raw: Option<Vec<String>>) -> ApiResult<Vec<String>> {
    let Some(values) = raw else {
        return Ok(Vec::new());
    };
    if values.is_empty() {
        return Err(ApiError::bad_request("ticket_ids must not be empty"));
    }
    let mut normalized = Vec::with_capacity(values.len());
    let mut seen = HashSet::new();
    for value in values {
        let ticket_id = validate_coach_resource_id(&value, "ticket_id")?;
        if !seen.insert(ticket_id.clone()) {
            return Err(ApiError::bad_request("ticket_ids must be unique"));
        }
        normalized.push(ticket_id);
    }
    Ok(normalized)
}

fn canonical_coach_payment_method(raw: Option<&str>) -> ApiResult<String> {
    let normalized = raw.unwrap_or("card").trim().to_ascii_lowercase();
    match normalized.as_str() {
        "card" | "wallet_credit" | "split_tender" => Ok(normalized),
        _ => Err(ApiError::bad_request("invalid payment_method")),
    }
}

fn validate_coach_contact_email(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    if value.len() > 160 || !value.contains('@') {
        return Err(ApiError::bad_request("invalid contact_email"));
    }
    let Some((local, domain)) = value.split_once('@') else {
        return Err(ApiError::bad_request("invalid contact_email"));
    };
    if local.is_empty()
        || domain.is_empty()
        || !domain.contains('.')
        || value.chars().any(|ch| ch.is_ascii_control() || ch == ' ')
    {
        return Err(ApiError::bad_request("invalid contact_email"));
    }
    Ok(Some(value.to_string()))
}

fn canonical_coach_refund_kind(raw: &str) -> ApiResult<&'static str> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "original_payment" => Ok("original_payment"),
        "refund_credit" => Ok("refund_credit"),
        _ => Err(ApiError::bad_request("invalid refund_kind")),
    }
}

fn validate_coach_refund_reason(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let normalized = value.split_whitespace().collect::<Vec<_>>().join(" ");
    let len = normalized.chars().count();
    if !(5..=240).contains(&len) || normalized.chars().any(char::is_control) {
        return Err(ApiError::bad_request("invalid reason"));
    }
    Ok(Some(normalized))
}

fn validate_coach_change_reason(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let normalized = value.split_whitespace().collect::<Vec<_>>().join(" ");
    let len = normalized.chars().count();
    if !(5..=240).contains(&len) || normalized.chars().any(char::is_control) {
        return Err(ApiError::bad_request("invalid reason"));
    }
    Ok(Some(normalized))
}

fn coach_operator_queue_limit(raw: Option<i64>) -> usize {
    raw.unwrap_or(20).clamp(1, 50) as usize
}

fn normalize_coach_support_case_search_query(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let normalized = value.split_whitespace().collect::<Vec<_>>().join(" ");
    let len = normalized.chars().count();
    if len > COACH_SUPPORT_CASE_SEARCH_MAX_CHARS || normalized.chars().any(char::is_control) {
        return Err(ApiError::bad_request("invalid q"));
    }
    Ok(Some(normalized.to_ascii_lowercase()))
}

