fn normalize_coach_payout_import_preview_status_filter(
    raw: Option<&str>,
) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let normalized = value.to_ascii_lowercase();
    match normalized.as_str() {
        "all" => Ok(None),
        COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE
        | COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED
        | COACH_PAYOUT_IMPORT_PREVIEW_STATUS_EXPIRED
        | COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED => Ok(Some(normalized)),
        _ => Err(ApiError::bad_request(
            "status must be one of: all, active, consumed, expired, invalidated",
        )),
    }
}

fn normalize_coach_payout_import_preview_saved_view_operator_id(raw: &str) -> ApiResult<String> {
    let normalized = raw.trim();
    if normalized.is_empty() || normalized.eq_ignore_ascii_case("all") {
        return Ok("all".to_string());
    }
    validate_coach_resource_id(normalized, "operator_id")
}

fn parse_coach_payout_import_preview_filters(
    q: &CoachOperatorPayoutImportPreviewQuery,
) -> ApiResult<CoachOperatorPayoutImportPreviewFilters> {
    let status = normalize_coach_payout_import_preview_status_filter(q.status.as_deref())?;
    let from_created_at = q
        .from_created_at
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| {
            chrono::DateTime::parse_from_rfc3339(value)
                .map_err(|_| ApiError::bad_request("invalid from_created_at"))
        })
        .transpose()?;
    let to_created_at = q
        .to_created_at
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| {
            chrono::DateTime::parse_from_rfc3339(value)
                .map_err(|_| ApiError::bad_request("invalid to_created_at"))
        })
        .transpose()?;
    if let (Some(from), Some(to)) = (from_created_at.as_ref(), to_created_at.as_ref()) {
        if from > to {
            return Err(ApiError::bad_request(
                "from_created_at must be <= to_created_at",
            ));
        }
    }
    let cursor = q
        .cursor
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(parse_coach_payout_import_preview_cursor)
        .transpose()?;
    Ok(CoachOperatorPayoutImportPreviewFilters {
        status,
        from_created_at,
        to_created_at,
        cursor,
    })
}

