fn canonical_coach_operator_review_decision(raw: &str) -> ApiResult<&'static str> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "approve" | "approved" => Ok("approve"),
        "reject" | "rejected" => Ok("reject"),
        _ => Err(ApiError::bad_request("decision must be approve or reject")),
    }
}

fn validate_coach_operator_review_note(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let normalized = value.split_whitespace().collect::<Vec<_>>().join(" ");
    if normalized.chars().count() > 280 || normalized.chars().any(char::is_control) {
        return Err(ApiError::bad_request("invalid review note"));
    }
    Ok(Some(normalized))
}

fn validate_coach_settlement_statement_ids(raw: Vec<String>) -> ApiResult<Vec<String>> {
    if raw.is_empty() {
        return Err(ApiError::bad_request("statement_ids required"));
    }
    let mut normalized = Vec::with_capacity(raw.len());
    let mut seen = HashSet::new();
    for value in raw {
        let statement_id = validate_coach_resource_id(&value, "statement_id")?;
        if !seen.insert(statement_id.clone()) {
            return Err(ApiError::bad_request("statement_ids must be unique"));
        }
        normalized.push(statement_id);
    }
    normalized.sort();
    Ok(normalized)
}

fn coach_sorted_nonempty_strings(values: &[String]) -> Vec<String> {
    let mut normalized = values
        .iter()
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>();
    normalized.sort();
    normalized.dedup();
    normalized
}

fn coach_normalize_settlement_payout_run_entry(
    mut entry: CoachSettlementPayoutRunEntry,
) -> CoachSettlementPayoutRunEntry {
    entry.statement_ids = coach_sorted_nonempty_strings(&entry.statement_ids);
    entry.operator_ids = coach_sorted_nonempty_strings(&entry.operator_ids);
    entry.operator_names = coach_sorted_nonempty_strings(&entry.operator_names);
    entry.statement_count = entry.statement_ids.len() as i64;
    entry
}

