fn validate_coach_download_artifact_name(raw: &str) -> ApiResult<String> {
    let value = raw.trim();
    if value.is_empty()
        || value.len() > 180
        || value.contains('/')
        || value.contains('\\')
        || value.contains("..")
        || !value
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-'))
    {
        return Err(ApiError::bad_request("invalid export artifact name"));
    }
    Ok(value.to_string())
}

