fn canonical_coach_payout_import_status_for_source(
    import_source: &str,
    raw: &str,
) -> ApiResult<&'static str> {
    let normalized = raw.trim().to_ascii_lowercase();
    let profile = coach_payout_import_profile_spec(import_source);
    for mapping in profile.status_mappings {
        if mapping
            .accepted_values
            .iter()
            .any(|value| normalized == *value)
        {
            return Ok(mapping.normalized_status);
        }
    }
    Err(ApiError::bad_request(format!(
        "external_status not supported for {}",
        profile.import_source
    )))
}

fn coach_required_payout_import_fields_for_status(
    import_source: &str,
    normalized_status: &str,
) -> &'static [&'static str] {
    coach_payout_import_profile_spec(import_source)
        .status_mappings
        .iter()
        .find(|mapping| mapping.normalized_status == normalized_status)
        .map(|mapping| mapping.required_fields)
        .unwrap_or(&[])
}

fn coach_validate_required_payout_import_fields(
    import_source: &str,
    normalized_status: &str,
    payment_reference: Option<&str>,
    external_reference: Option<&str>,
) -> ApiResult<()> {
    for field in coach_required_payout_import_fields_for_status(import_source, normalized_status) {
        match *field {
            "payment_reference" if payment_reference.is_none() => {
                return Err(ApiError::bad_request(format!(
                    "payment_reference required when {} import is {}",
                    import_source, normalized_status
                )));
            }
            "external_reference" if external_reference.is_none() => {
                return Err(ApiError::bad_request(format!(
                    "external_reference required when {} import is {}",
                    import_source, normalized_status
                )));
            }
            _ => {}
        }
    }
    Ok(())
}

