fn coach_csv_delimiter_label(delimiter: char) -> &'static str {
    match delimiter {
        ',' => "comma",
        ';' => "semicolon",
        '\t' => "tab",
        _ => "custom",
    }
}

fn coach_detect_payout_import_delimiter(
    profile: &CoachPayoutImportProfileSpec,
    line: &str,
) -> char {
    profile
        .supported_delimiters
        .iter()
        .copied()
        .max_by_key(|delimiter| line.matches(*delimiter).count())
        .unwrap_or(',')
}

fn coach_parse_csv_line(line: &str, delimiter: char) -> ApiResult<Vec<String>> {
    let mut values = Vec::new();
    let mut current = String::new();
    let mut chars = line.chars().peekable();
    let mut in_quotes = false;
    while let Some(ch) = chars.next() {
        match ch {
            '"' => {
                if in_quotes && chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    in_quotes = !in_quotes;
                }
            }
            value if value == delimiter && !in_quotes => {
                values.push(current.trim().to_string());
                current.clear();
            }
            _ => current.push(ch),
        }
    }
    if in_quotes {
        return Err(ApiError::bad_request("invalid report_body"));
    }
    values.push(current.trim().to_string());
    Ok(values)
}

fn coach_parse_payout_import_batch_csv(
    import_source: &str,
    report_body: &str,
) -> ApiResult<Vec<CoachPayoutImportBatchParsedLine>> {
    let profile = coach_payout_import_profile_spec(import_source);
    let mut non_empty_lines = report_body
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty());
    let Some(header_line) = non_empty_lines.next() else {
        return Err(ApiError::bad_request(
            "report_body must include a header row",
        ));
    };
    let normalized_header_line = header_line.trim_start_matches('\u{feff}');
    let delimiter = coach_detect_payout_import_delimiter(profile, normalized_header_line);
    let header_values = coach_parse_csv_line(normalized_header_line, delimiter)?;
    let normalized_headers = header_values
        .into_iter()
        .map(|value| value.trim().to_ascii_lowercase())
        .collect::<Vec<_>>();
    let field_index = |key: &str| -> ApiResult<Option<usize>> {
        let Some(field) = profile.fields.iter().find(|field| field.key == key) else {
            return Ok(None);
        };
        let index = normalized_headers
            .iter()
            .position(|value| field.aliases.iter().any(|alias| value == alias));
        if field.required && index.is_none() {
            return Err(ApiError::bad_request(format!(
                "report_body missing {} column for {}",
                key, profile.import_source
            )));
        }
        Ok(index)
    };
    let payout_run_index = field_index("payout_run_id")?
        .ok_or_else(|| ApiError::bad_request("report_body missing payout_run_id column"))?;
    let external_status_index = field_index("external_status")?
        .ok_or_else(|| ApiError::bad_request("report_body missing external_status column"))?;
    let payment_reference_index = field_index("payment_reference")?;
    let external_reference_index = field_index("external_reference")?;
    let imported_at_index = field_index("imported_at")?;
    let note_index = field_index("note")?;
    let expected_columns = normalized_headers.len();

    let mut rows = Vec::new();
    for (row_offset, line) in non_empty_lines.enumerate() {
        if rows.len() >= COACH_PAYOUT_IMPORT_BATCH_MAX_ROWS {
            return Err(ApiError::bad_request("report_body has too many rows"));
        }
        let row_values = coach_parse_csv_line(line, delimiter)?;
        if row_values.len() > expected_columns {
            return Err(ApiError::bad_request(
                "report_body contains too many columns",
            ));
        }
        let row = |index: usize| -> Option<String> {
            row_values
                .get(index)
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty())
        };
        rows.push(CoachPayoutImportBatchParsedLine {
            line_number: (row_offset + 2) as i64,
            payout_run_id: row(payout_run_index).unwrap_or_default(),
            external_status: row(external_status_index).unwrap_or_default(),
            payment_reference: payment_reference_index.and_then(&row),
            external_reference: external_reference_index.and_then(&row),
            imported_at: imported_at_index.and_then(&row),
            note: note_index.and_then(row),
        });
    }
    if rows.is_empty() {
        return Err(ApiError::bad_request(
            "report_body must include at least one row",
        ));
    }
    Ok(rows)
}

fn coach_resolve_payout_import_rework_origin_batch_id(
    rework_of_batch_id: Option<&str>,
    batch_map: &CoachSettlementPayoutImportBatchMap,
) -> Option<String> {
    let mut current = rework_of_batch_id.map(str::to_string);
    let mut origin = current.clone();
    let mut seen = HashSet::new();
    while let Some(batch_id) = current.clone() {
        if !seen.insert(batch_id.clone()) {
            break;
        }
        origin = Some(batch_id.clone());
        let Some(parent) = batch_map.get(batch_id.as_str()) else {
            break;
        };
        current = parent.rework_of_batch_id.clone();
    }
    origin
}

fn coach_collect_payout_import_follow_up_batch_ids(
    batch_id: &str,
    batch_map: &CoachSettlementPayoutImportBatchMap,
) -> Vec<String> {
    fn walk(
        batch_id: &str,
        batch_map: &CoachSettlementPayoutImportBatchMap,
        seen: &mut HashSet<String>,
        follow_up_batch_ids: &mut Vec<String>,
    ) {
        let mut children = batch_map
            .values()
            .filter(|entry| entry.rework_of_batch_id.as_deref() == Some(batch_id))
            .cloned()
            .collect::<Vec<_>>();
        children.sort_by(|left, right| {
            left.created_at
                .cmp(&right.created_at)
                .then_with(|| left.batch_id.cmp(&right.batch_id))
        });
        for child in children {
            if !seen.insert(child.batch_id.clone()) {
                continue;
            }
            follow_up_batch_ids.push(child.batch_id.clone());
            walk(
                child.batch_id.as_str(),
                batch_map,
                seen,
                follow_up_batch_ids,
            );
        }
    }

    let mut seen = HashSet::new();
    let mut follow_up_batch_ids = Vec::new();
    walk(batch_id, batch_map, &mut seen, &mut follow_up_batch_ids);
    follow_up_batch_ids
}

fn coach_validate_payout_import_rework_source_batch(
    batch_map: &CoachSettlementPayoutImportBatchMap,
    rework_of_batch_id: Option<&str>,
    import_source: &str,
    report_format: &str,
) -> ApiResult<Option<String>> {
    let Some(rework_of_batch_id) = rework_of_batch_id else {
        return Ok(None);
    };
    let source_batch = batch_map
        .get(rework_of_batch_id)
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    if source_batch.failed_rows <= 0 {
        return Err(ApiError::bad_request(
            "rework_of_batch_id must reference a batch with failed rows",
        ));
    }
    if source_batch.import_source != import_source {
        return Err(ApiError::bad_request(
            "rework_of_batch_id import_source must match import_source",
        ));
    }
    if source_batch.report_format != report_format {
        return Err(ApiError::bad_request(
            "rework_of_batch_id report_format must match report_format",
        ));
    }
    Ok(Some(source_batch.batch_id.clone()))
}

fn coach_queue_status_for_review_decision(decision: &str) -> &'static str {
    if decision == "approve" {
        "approved"
    } else {
        "rejected"
    }
}

fn coach_operator_request_status_from_queue_status(queue_status: &str) -> &'static str {
    match queue_status {
        "approved" => "approved",
        "rejected" => "rejected",
        "payment_failed" => "payment_failed",
        _ => "requested",
    }
}

fn coach_operator_refund_suggested_action(
    queue_status: &str,
    pending_suggested_action: &str,
) -> String {
    if queue_status == "pending_review" {
        pending_suggested_action.to_string()
    } else if queue_status == "approved" {
        "Customer notification is queued.".to_string()
    } else {
        "Escalate to support if customer disputes the rejection.".to_string()
    }
}

fn coach_operator_change_suggested_action(
    queue_status: &str,
    total_due_minor_units: i64,
    pending_suggested_action: &str,
) -> String {
    if queue_status == "pending_review" {
        pending_suggested_action.to_string()
    } else if queue_status == "payment_failed" {
        "Retry collection or raise a support recovery case.".to_string()
    } else if queue_status == "approved" && total_due_minor_units > 0 {
        "Customer payment collection is queued.".to_string()
    } else if queue_status == "approved" {
        "Ticket reissue is queued without additional collection.".to_string()
    } else {
        "Keep the original ticket active and notify support.".to_string()
    }
}

fn canonical_coach_boarding_scan_status(raw: &str) -> ApiResult<&'static str> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "scanned" => Ok("scanned"),
        "denied" => Ok("denied"),
        "no_show" => Ok("no_show"),
        _ => Err(ApiError::bad_request(
            "scan_status must be scanned, denied, or no_show",
        )),
    }
}

fn validate_coach_device_id(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(value) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    if !coach_identifier_is_valid(value, 3, 64) {
        return Err(ApiError::bad_request("invalid device_id"));
    }
    Ok(Some(value.to_string()))
}

fn validate_coach_boarding_note(raw: Option<&str>) -> ApiResult<Option<String>> {
    validate_coach_operator_review_note(raw)
}

fn validate_coach_delivery_channels(raw: Option<Vec<String>>) -> ApiResult<Vec<String>> {
    let values = raw.unwrap_or_else(|| vec!["wallet_pass".to_string(), "pdf".to_string()]);
    if values.is_empty() {
        return Err(ApiError::bad_request("delivery_channels required"));
    }
    let mut normalized = Vec::with_capacity(values.len());
    let mut seen = HashSet::new();
    for value in values {
        let trimmed = value.trim().to_ascii_lowercase();
        match trimmed.as_str() {
            "wallet_pass" | "pdf" | "email" => {}
            _ => return Err(ApiError::bad_request("invalid delivery_channels")),
        }
        if seen.insert(trimmed.clone()) {
            normalized.push(trimmed);
        }
    }
    Ok(normalized)
}

fn parse_coach_bool_field(raw: &str, field_name: &'static str) -> ApiResult<bool> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "true" | "1" | "yes" => Ok(true),
        "false" | "0" | "no" | "" => Ok(false),
        _ => Err(ApiError::bad_request(format!("invalid {field_name}"))),
    }
}

fn normalize_coach_uploaded_csv_text(bytes: Vec<u8>) -> ApiResult<String> {
    if bytes.is_empty() {
        return Err(ApiError::bad_request("uploaded report file is empty"));
    }
    if bytes.len() > COACH_PAYOUT_IMPORT_BATCH_UPLOAD_MAX_BYTES {
        return Err(ApiError::bad_request("uploaded report file is too large"));
    }
    let mut text = String::from_utf8(bytes)
        .map_err(|_| ApiError::bad_request("uploaded report file must be utf-8 csv"))?;
    if text.starts_with('\u{feff}') {
        text = text.trim_start_matches('\u{feff}').to_string();
    }
    validate_coach_payout_import_report_body(&text)
}

fn coach_scoped_resource_id(prefix: &str, seed: &str) -> String {
    let digest = sha256_hex(seed);
    let mut normalized = seed
        .trim()
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-') {
                ch.to_ascii_lowercase()
            } else {
                '_'
            }
        })
        .collect::<String>();
    let reserved = prefix.len() + 1 + 1 + 10;
    let max_seed_len = 64usize.saturating_sub(reserved);
    if normalized.len() > max_seed_len {
        normalized.truncate(max_seed_len);
    }
    if normalized.is_empty() {
        format!("{prefix}_{}", &digest[..10])
    } else {
        format!("{prefix}_{normalized}_{}", &digest[..10])
    }
}

fn coach_command_request_fingerprint(command: &str, payload: &Value) -> String {
    sha256_hex(&format!("{command}|{payload}"))
}

fn coach_new_payout_import_preview_timestamps() -> (String, String) {
    let created_at = chrono::DateTime::<chrono::Utc>::from(SystemTime::now());
    let expires_at = created_at + chrono::Duration::seconds(COACH_PAYOUT_IMPORT_PREVIEW_TTL_SECS);
    (
        created_at.to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
        expires_at.to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
    )
}

fn coach_new_payout_import_preview_token(
    principal_account_id: &str,
    preview_request_fingerprint: &str,
    report_checksum_sha256: &str,
) -> String {
    let nonce = Alphanumeric.sample_string(&mut rand::thread_rng(), 12);
    coach_scoped_resource_id(
        "previewtoken",
        &format!(
            "{principal_account_id}-{preview_request_fingerprint}-{report_checksum_sha256}-{nonce}"
        ),
    )
}

fn coach_preview_entry_is_expired(entry: &CoachSettlementPayoutImportPreviewEntry) -> bool {
    if entry.preview_status != COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE {
        return false;
    }
    chrono::DateTime::parse_from_rfc3339(entry.expires_at.as_str())
        .map(|value| value <= chrono::DateTime::<chrono::Utc>::from(SystemTime::now()))
        .unwrap_or(true)
}

#[derive(Clone, Copy)]
struct CoachPayoutImportBatchCommand<'a> {
    import_source: &'a str,
    report_name: &'a str,
    report_format: &'a str,
    rework_of_batch_id: Option<&'a str>,
    report_checksum_sha256: &'a str,
    total_rows: usize,
    dry_run: bool,
    note: Option<&'a str>,
}

#[derive(Clone, Copy)]
struct CoachPayoutImportPreviewBuild<'a> {
    principal_account_id: &'a str,
    operator_ids: &'a [String],
    request_fingerprint: &'a str,
    command: CoachPayoutImportBatchCommand<'a>,
}

#[derive(Clone, Copy)]
struct CoachPayoutImportBatchResponseContext<'a> {
    idempotency_key: &'a str,
    request_fingerprint: &'a str,
    batch: &'a CoachSettlementPayoutImportBatchEntry,
    preview_entry: Option<&'a CoachSettlementPayoutImportPreviewEntry>,
    report_artifact: Option<&'a CoachSettlementPayoutImportReportArtifactEntry>,
    rework_artifact: Option<&'a CoachSettlementPayoutImportReportArtifactEntry>,
    rework_origin_batch_id: Option<&'a str>,
    imports: &'a [CoachSettlementPayoutImportEntry],
    failed_rows: &'a [CoachPayoutImportBatchFailure],
    next_action: &'static str,
}

fn coach_build_payout_import_preview_entry(
    preview: &CoachPayoutImportPreviewBuild<'_>,
) -> CoachSettlementPayoutImportPreviewEntry {
    let (created_at, expires_at) = coach_new_payout_import_preview_timestamps();
    CoachSettlementPayoutImportPreviewEntry {
        preview_token: coach_new_payout_import_preview_token(
            preview.principal_account_id,
            preview.request_fingerprint,
            preview.command.report_checksum_sha256,
        ),
        account_id: preview.principal_account_id.trim().to_ascii_lowercase(),
        import_source: preview.command.import_source.to_string(),
        report_name: preview.command.report_name.to_string(),
        report_format: preview.command.report_format.to_string(),
        rework_of_batch_id: preview.command.rework_of_batch_id.map(ToString::to_string),
        operator_ids: preview.operator_ids.to_vec(),
        report_checksum_sha256: preview.command.report_checksum_sha256.to_string(),
        request_fingerprint: preview.request_fingerprint.to_string(),
        preview_status: COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE.to_string(),
        created_at,
        expires_at,
        consumed_at: None,
        invalidated_at: None,
    }
}

fn coach_payout_import_operator_ids_for_rows(
    parsed_rows: &[CoachPayoutImportBatchParsedLine],
    payout_run_map: &CoachSettlementPayoutRunMap,
    allowed_operator_ids: &HashSet<String>,
) -> Vec<String> {
    let mut operator_ids = parsed_rows
        .iter()
        .filter_map(|row| payout_run_map.get(row.payout_run_id.trim()))
        .flat_map(|entry| entry.operator_ids.iter().cloned())
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty())
        .collect::<BTreeSet<_>>();
    if operator_ids.is_empty() && !allowed_operator_ids.is_empty() {
        operator_ids.extend(allowed_operator_ids.iter().cloned());
    }
    operator_ids.into_iter().collect()
}

fn coach_payout_import_batch_command_payload(command: &CoachPayoutImportBatchCommand<'_>) -> Value {
    json!({
        "import_source": command.import_source,
        "report_name": command.report_name,
        "report_format": command.report_format,
        "rework_of_batch_id": command.rework_of_batch_id,
        "report_checksum_sha256": command.report_checksum_sha256,
        "total_rows": command.total_rows,
        "dry_run": command.dry_run,
        "note": command.note,
    })
}

async fn coach_validate_payout_import_apply_preview_binding(
    state: &AppState,
    dry_run: bool,
    expected_preview_token: Option<&str>,
    principal_account_id: &str,
    actual_preview_request_fingerprint: &str,
    actual_preview_report_checksum_sha256: &str,
) -> ApiResult<Option<CoachSettlementPayoutImportPreviewEntry>> {
    if dry_run {
        return Ok(None);
    }
    let Some(expected_preview_token) = expected_preview_token else {
        return Err(ApiError::bad_request(
            "preview confirmation required before applying payout report",
        ));
    };
    let Some(preview_entry) = coach_find_settlement_payout_import_preview_entry(
        state,
        principal_account_id,
        expected_preview_token,
    )
    .await?
    else {
        return Err(ApiError::bad_request(
            "payout import preview token is stale; run preview again before apply",
        ));
    };
    if coach_preview_entry_is_expired(&preview_entry) {
        let transitioned = coach_transition_settlement_payout_import_preview_status(
            state,
            principal_account_id,
            expected_preview_token,
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE,
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_EXPIRED,
            None,
            None,
        )
        .await?;
        if transitioned {
            return Err(ApiError::bad_request(
                "payout import preview expired; run preview again before apply",
            ));
        }
        let current_preview_entry = coach_find_settlement_payout_import_preview_entry(
            state,
            principal_account_id,
            expected_preview_token,
        )
        .await?;
        return Err(coach_payout_import_apply_preview_error(
            current_preview_entry.as_ref(),
        ));
    }
    if preview_entry.preview_status == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_EXPIRED
        || preview_entry.preview_status == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED
        || preview_entry.preview_status == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED
    {
        return Err(coach_payout_import_apply_preview_error(Some(
            &preview_entry,
        )));
    }
    if preview_entry.preview_status != COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE
        || preview_entry.request_fingerprint != actual_preview_request_fingerprint
        || preview_entry.report_checksum_sha256 != actual_preview_report_checksum_sha256
    {
        return Err(ApiError::bad_request(
            "payout import preview token is stale; run preview again before apply",
        ));
    }
    Ok(Some(preview_entry))
}

fn coach_offer_is_night_service(offer_id: &str) -> bool {
    offer_id.trim().to_ascii_lowercase().contains("night")
}

fn coach_offer_operator_id(offer_id: &str) -> &'static str {
    if coach_offer_is_night_service(offer_id) {
        "op_northern_connector"
    } else {
        "op_demo_express"
    }
}

fn coach_offer_itinerary_id(offer_id: &str) -> &'static str {
    if coach_offer_is_night_service(offer_id) {
        "iti_night_connector"
    } else {
        "iti_demo_direct"
    }
}

fn coach_offer_total_minor_units(offer_id: &str, passengers: u8) -> i64 {
    if coach_offer_is_night_service(offer_id) {
        i64::from(passengers) * 3_990
    } else {
        i64::from(passengers) * 4_590
    }
}

fn coach_catalog_offer_id(fare_product_id: &str) -> String {
    format!("{COACH_CATALOG_OFFER_PREFIX}{}", fare_product_id.trim())
}

fn coach_catalog_offer_fare_product_id(offer_id: &str) -> Option<&str> {
    let normalized = offer_id.trim();
    normalized
        .strip_prefix(COACH_CATALOG_OFFER_PREFIX)
        .filter(|value| coach_identifier_is_valid(value, 3, 64))
}

fn coach_catalog_itinerary_id(trip_id: &str) -> String {
    coach_scoped_resource_id("iti", trip_id)
}

fn coach_catalog_journey_id(trip_id: &str) -> String {
    coach_scoped_resource_id("journey", trip_id)
}

fn coach_catalog_low_availability(seats_available: i32, passengers: u8) -> bool {
    seats_available <= i32::from(passengers) + 2
}

fn coach_catalog_departure_arrival_iso(
    departure_date: &str,
    departure_time_local: &str,
    duration_minutes: i32,
) -> Option<(String, String)> {
    let departure_date =
        chrono::NaiveDate::parse_from_str(departure_date.trim(), "%Y-%m-%d").ok()?;
    let departure_time =
        chrono::NaiveTime::parse_from_str(departure_time_local.trim(), "%H:%M").ok()?;
    let departure_naive = departure_date.and_time(departure_time);
    let arrival_naive = departure_naive + chrono::Duration::minutes(i64::from(duration_minutes));
    Some((
        departure_naive
            .and_utc()
            .to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
        arrival_naive
            .and_utc()
            .to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
    ))
}

fn coach_future_expiry_iso(ttl_seconds: i64) -> String {
    (chrono::DateTime::<chrono::Utc>::from(SystemTime::now())
        + chrono::Duration::seconds(ttl_seconds))
    .to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
}

fn coach_offer_source_kind(offer_id: &str) -> &'static str {
    if coach_catalog_offer_fare_product_id(offer_id).is_some() {
        "catalog"
    } else {
        "seeded"
    }
}

fn coach_offer_source_reference(offer_id: &str) -> Option<String> {
    coach_catalog_offer_fare_product_id(offer_id)
        .map(str::to_string)
        .or_else(|| Some(offer_id.trim().to_string()))
}

async fn coach_persist_offer_payload_best_effort(
    state: &AppState,
    account_id: &str,
    offer_id: &str,
    passengers: u8,
    offer_payload: &Value,
    journey_payload: Option<&Value>,
) -> Result<(), sqlx::Error> {
    let Some(auth) = &state.auth else {
        return Ok(());
    };
    let expires_at = offer_payload
        .get("expires_at")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| coach_future_expiry_iso(COACH_OFFER_TTL_SECS));
    let source_reference = coach_offer_source_reference(offer_id);
    let repo = CoachCatalogRepository::new(auth.pool().clone());
    repo.upsert_offer_snapshot(&CoachOfferSnapshotUpsert {
        account_id,
        offer_id,
        seats_requested: i16::from(passengers),
        source_kind: coach_offer_source_kind(offer_id),
        source_reference: source_reference.as_deref(),
        expires_at_iso: expires_at.as_str(),
        offer_payload,
        journey_payload,
    })
    .await
}

async fn coach_persist_search_offer_snapshots_best_effort(
    state: &AppState,
    account_id: &str,
    passengers: u8,
    payload: &Value,
) {
    let Some(journeys) = payload.get("journeys").and_then(Value::as_array) else {
        return;
    };
    for journey in journeys {
        let Some(offer_payload) = journey.get("best_offer") else {
            continue;
        };
        let Some(offer_id) = offer_payload.get("offer_id").and_then(Value::as_str) else {
            continue;
        };
        if let Err(error) = coach_persist_offer_payload_best_effort(
            state,
            account_id,
            offer_id,
            passengers,
            offer_payload,
            Some(journey),
        )
        .await
        {
            tracing::warn!(%error, offer_id, "coach offer snapshot persistence skipped");
        }
    }
}

fn coach_catalog_offer_payload_from_basis(
    offer_id: &str,
    basis: &CoachCatalogOfferBasis,
    passengers: u8,
) -> Value {
    let baggage_rule = basis
        .baggage_rule
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("Standard baggage policy applies");
    json!({
        "offer_id": offer_id.trim(),
        "operator_id": basis.operator_id.as_str(),
        "itinerary_id": coach_catalog_itinerary_id(&basis.trip_id),
        "currency": basis.currency.as_str(),
        "total_minor_units": basis.price_minor_units * i64::from(passengers),
        "seats_requested": passengers,
        "hold_supported": basis.hold_supported,
        "changeable": basis.changeable,
        "refundable": basis.refundable,
        "expires_at": coach_future_expiry_iso(COACH_OFFER_TTL_SECS),
        "seat_map_available": basis.seats_available > 0,
        "baggage_rule": baggage_rule,
    })
}

#[derive(Debug, Clone, Copy, Default)]
struct CoachOperatorRealtimeFreshness {
    trip_updates_fresh: bool,
    vehicle_positions_fresh: bool,
    service_alerts_fresh: bool,
}

fn coach_operator_realtime_freshness_map(
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> HashMap<String, CoachOperatorRealtimeFreshness> {
    let mut out = HashMap::<String, CoachOperatorRealtimeFreshness>::new();
    for entry in feed_health {
        let is_fresh = coach_operator_feed_sync_is_healthy(&entry.sync_status)
            && entry.freshness_status == "fresh";
        let operator = out.entry(entry.operator_id.clone()).or_default();
        match entry.feed_kind.as_str() {
            "gtfs_rt_trip_updates" => operator.trip_updates_fresh = is_fresh,
            "gtfs_rt_vehicle_positions" => operator.vehicle_positions_fresh = is_fresh,
            "gtfs_rt_service_alerts" | "siri" => operator.service_alerts_fresh = is_fresh,
            _ => {}
        }
    }
    out
}

fn coach_catalog_journey_payload(
    departure_date: &str,
    passengers: u8,
    journey: &CoachCatalogDirectJourney,
    realtime: CoachOperatorRealtimeFreshness,
) -> Value {
    let (departure_at, arrival_at) = coach_catalog_departure_arrival_iso(
        departure_date,
        &journey.departure_time_local,
        journey.duration_minutes,
    )
    .unwrap_or_else(|| {
        (
            format!(
                "{}T{}:00Z",
                departure_date.trim(),
                journey.departure_time_local.trim()
            ),
            format!(
                "{}T{}:00Z",
                departure_date.trim(),
                journey.arrival_time_local.trim()
            ),
        )
    });
    let amenities = if journey.amenities.is_empty() {
        vec!["standard_seating".to_string()]
    } else {
        journey.amenities.clone()
    };
    let offer_id = coach_catalog_offer_id(&journey.fare_product_id);
    json!({
        "journey_id": coach_catalog_journey_id(&journey.trip_id),
        "operator_id": journey.operator_id.as_str(),
        "operator_name": journey.operator_name.as_str(),
        "operator_integration_mode": journey.operator_integration_mode.as_str(),
        "departure_at": departure_at,
        "arrival_at": arrival_at,
        "duration_minutes": journey.duration_minutes,
        "transfer_count": 0,
        "seats_available": journey.seats_available,
        "low_availability": coach_catalog_low_availability(journey.seats_available, passengers),
        "currency": journey.currency.as_str(),
        "price_from_minor_units": journey.price_minor_units * i64::from(passengers),
        "amenities": amenities.clone(),
        "changeable": journey.changeable,
        "refundable": journey.refundable,
        "best_offer": coach_catalog_offer_payload_from_basis(
            &offer_id,
            &CoachCatalogOfferBasis {
                fare_product_id: journey.fare_product_id.clone(),
                trip_id: journey.trip_id.clone(),
                operator_id: journey.operator_id.clone(),
                operator_name: journey.operator_name.clone(),
                operator_integration_mode: journey.operator_integration_mode.clone(),
                currency: journey.currency.clone(),
                price_minor_units: journey.price_minor_units,
                hold_supported: journey.hold_supported,
                changeable: journey.changeable,
                refundable: journey.refundable,
                baggage_rule: journey.baggage_rule.clone(),
                seats_available: journey.seats_available,
                amenities,
            },
            passengers,
        ),
        "realtime": {
            "delay_minutes": 0,
            "trip_updates_fresh": realtime.trip_updates_fresh,
            "vehicle_positions_fresh": realtime.vehicle_positions_fresh,
            "service_alerts_fresh": realtime.service_alerts_fresh
        }
    })
}

async fn coach_search_results_payload_for_request(
    state: &AppState,
    from: &str,
    to: &str,
    departure_date: &str,
    passengers: u8,
) -> Value {
    if let Some(auth) = &state.auth {
        let repo = CoachCatalogRepository::new(auth.pool().clone());
        match repo
            .find_direct_journeys_by_city_names(from, to, departure_date, i32::from(passengers))
            .await
        {
            Ok(journeys) if !journeys.is_empty() => {
                let feed_health = repo.list_operator_feed_health().await.unwrap_or_default();
                let realtime_by_operator = coach_operator_realtime_freshness_map(&feed_health);
                return json!({
                    "query": {
                        "from": from,
                        "to": to,
                        "departure_date": departure_date,
                        "passengers": passengers
                    },
                    "journeys": journeys
                        .iter()
                        .map(|journey| {
                            let realtime = realtime_by_operator
                                .get(journey.operator_id.as_str())
                                .copied()
                                .unwrap_or_default();
                            coach_catalog_journey_payload(
                                departure_date,
                                passengers,
                                journey,
                                realtime,
                            )
                        })
                        .collect::<Vec<_>>(),
                    "source": "catalog"
                });
            }
            Ok(_) | Err(_) => {}
        }
    }

    coach_search_results_payload(from, to, departure_date, passengers)
}

fn coach_default_seat_number(index: usize) -> String {
    let row = 4 + (index / 4);
    let letter = char::from(b'A' + (index % 4) as u8);
    format!("{row}{letter}")
}

fn coach_hold_payload_for_offer(
    hold_id: &str,
    offer_id: &str,
    passenger_ids: &[String],
    preferred_seat_numbers: &[String],
    status: &str,
) -> Value {
    let normalized_hold_id = hold_id.trim();
    json!({
        "hold_id": normalized_hold_id,
        "offer_id": offer_id.trim(),
        "operator_reference": format!("operator-{normalized_hold_id}"),
        "expires_at": coach_future_expiry_iso(COACH_HOLD_TTL_SECS),
        "status": status,
        "seat_assignments": passenger_ids
            .iter()
            .enumerate()
            .map(|(index, passenger_id)| {
                json!({
                    "passenger_id": passenger_id,
                    "seat_number": preferred_seat_numbers
                        .get(index)
                        .cloned()
                        .unwrap_or_else(|| coach_default_seat_number(index))
                })
            })
            .collect::<Vec<_>>()
    })
}

fn coach_demo_passenger_manifest(
    values: &[(&str, &str, &str, &str, Option<&str>)],
) -> Vec<CoachPassengerManifestNormalized> {
    values
        .iter()
        .map(
            |(passenger_id, given_name, family_name, rider_category, nationality_code)| {
                CoachPassengerManifestNormalized {
                    passenger_id: (*passenger_id).to_string(),
                    given_name: (*given_name).to_string(),
                    family_name: (*family_name).to_string(),
                    rider_category: (*rider_category).to_string(),
                    nationality_code: nationality_code.map(|value| value.to_string()),
                }
            },
        )
        .collect::<Vec<_>>()
}

