fn coach_ticket_payload_with_boarding_state(ticket_payload: &Value, boarding_state: &str) -> Value {
    let Some(mut object) = ticket_payload.as_object().cloned() else {
        return ticket_payload.clone();
    };
    object.insert(
        "boarding_state".to_string(),
        Value::String(boarding_state.to_string()),
    );
    Value::Object(object)
}

fn coach_runtime_departure_sort_key(aggregates: &[CoachStoredBookingAggregate]) -> String {
    let trip_id = aggregates
        .iter()
        .find_map(|aggregate| {
            aggregate
                .journey
                .as_ref()
                .and_then(|payload| payload.get("trip_id"))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
        })
        .unwrap_or_default();
    coach_runtime_trip_group_journey_payload(aggregates, &trip_id)
        .get("departure_at")
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_default()
}

async fn coach_runtime_trip_groups_for_request(
    state: &AppState,
    aggregates: Vec<CoachStoredBookingAggregate>,
) -> Result<Vec<(String, Vec<CoachStoredBookingAggregate>)>, sqlx::Error> {
    let mut grouped = HashMap::<String, Vec<CoachStoredBookingAggregate>>::new();
    for aggregate in aggregates {
        let trip_id = coach_runtime_trip_id_for_aggregate(state, &aggregate).await?;
        grouped.entry(trip_id).or_default().push(aggregate);
    }
    let mut groups = grouped.into_iter().collect::<Vec<_>>();
    groups.sort_by(
        |(left_trip_id, left_aggregates), (right_trip_id, right_aggregates)| {
            coach_runtime_departure_sort_key(left_aggregates)
                .cmp(&coach_runtime_departure_sort_key(right_aggregates))
                .then_with(|| left_trip_id.cmp(right_trip_id))
        },
    );
    Ok(groups)
}

fn coach_find_runtime_trip_group_matching_aggregate<F>(
    trip_groups: &[(String, Vec<CoachStoredBookingAggregate>)],
    mut predicate: F,
) -> Option<(
    &str,
    &[CoachStoredBookingAggregate],
    &CoachStoredBookingAggregate,
)>
where
    F: FnMut(&CoachStoredBookingAggregate) -> bool,
{
    trip_groups.iter().find_map(|(trip_id, aggregates)| {
        aggregates
            .iter()
            .filter(|aggregate| predicate(aggregate))
            .min_by(|left, right| {
                let left_booking_id = left
                    .booking
                    .get("booking_id")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .unwrap_or("booking_runtime");
                let right_booking_id = right
                    .booking
                    .get("booking_id")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .unwrap_or("booking_runtime");
                let left_ticket_id = left
                    .tickets
                    .iter()
                    .filter_map(|ticket| ticket.get("ticket_id").and_then(Value::as_str))
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .min()
                    .unwrap_or("");
                let right_ticket_id = right
                    .tickets
                    .iter()
                    .filter_map(|ticket| ticket.get("ticket_id").and_then(Value::as_str))
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .min()
                    .unwrap_or("");
                left_booking_id
                    .cmp(right_booking_id)
                    .then_with(|| left.account_id.cmp(&right.account_id))
                    .then_with(|| left_ticket_id.cmp(right_ticket_id))
            })
            .map(|aggregate| (trip_id.as_str(), aggregates.as_slice(), aggregate))
    })
}

fn coach_group_runtime_trip_groups_by_operator_for_settlement(
    trip_groups: Vec<(String, Vec<CoachStoredBookingAggregate>)>,
) -> BTreeMap<String, Vec<(String, CoachStoredBookingAggregate)>> {
    let mut grouped = BTreeMap::<String, Vec<(String, CoachStoredBookingAggregate)>>::new();
    for (trip_id, aggregates) in trip_groups {
        let operator_id = coach_runtime_trip_group_operator_id(&aggregates, &trip_id);
        for aggregate in aggregates {
            grouped
                .entry(operator_id.clone())
                .or_default()
                .push((trip_id.clone(), aggregate));
        }
    }
    for entries in grouped.values_mut() {
        entries.sort_by(|left, right| {
            let left_departure_at = left
                .1
                .journey
                .as_ref()
                .and_then(|payload| payload.get("departure_at"))
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or_default();
            let right_departure_at = right
                .1
                .journey
                .as_ref()
                .and_then(|payload| payload.get("departure_at"))
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or_default();
            let left_booking_id = left
                .1
                .booking
                .get("booking_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or_default();
            let right_booking_id = right
                .1
                .booking
                .get("booking_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .unwrap_or_default();
            left_departure_at
                .cmp(right_departure_at)
                .then_with(|| left.0.cmp(&right.0))
                .then_with(|| left_booking_id.cmp(right_booking_id))
                .then_with(|| left.1.account_id.cmp(&right.1.account_id))
        });
    }
    grouped
}

async fn coach_group_runtime_aggregates_by_operator_for_settlement(
    state: &AppState,
    runtime_aggregates: Vec<CoachStoredBookingAggregate>,
) -> Result<BTreeMap<String, Vec<(String, CoachStoredBookingAggregate)>>, sqlx::Error> {
    let trip_groups = coach_runtime_trip_groups_for_request(state, runtime_aggregates).await?;
    Ok(coach_group_runtime_trip_groups_by_operator_for_settlement(
        trip_groups,
    ))
}

fn coach_runtime_operator_name_from_grouped_settlement_entries(
    entries: &[(String, CoachStoredBookingAggregate)],
    operator_id: &str,
) -> String {
    if let Some(display_name) = coach_operator_display_name_from_id(operator_id) {
        return display_name;
    }
    let aggregates = entries
        .iter()
        .map(|(_, aggregate)| aggregate.clone())
        .collect::<Vec<_>>();
    let seed = coach_runtime_trip_group_operator_seed(&aggregates);
    seed.journey
        .as_ref()
        .and_then(|payload| payload.get("operator_name"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty() && *value != "Coach service")
        .map(str::to_string)
        .or_else(|| {
            let fallback = coach_runtime_operator_name_from_aggregate(seed);
            (fallback != "Coach service").then_some(fallback)
        })
        .unwrap_or_else(|| operator_id.to_string())
}

fn coach_passenger_manifest_payload(
    passengers_manifest: &[CoachPassengerManifestNormalized],
) -> Value {
    Value::Array(
        passengers_manifest
            .iter()
            .map(|passenger| {
                json!({
                    "passenger_id": passenger.passenger_id,
                    "given_name": passenger.given_name,
                    "family_name": passenger.family_name,
                    "rider_category": passenger.rider_category,
                    "nationality_code": passenger.nationality_code,
                })
            })
            .collect::<Vec<_>>(),
    )
}

fn coach_passenger_manifest_normalized_from_payload(
    payload: &Value,
) -> Vec<CoachPassengerManifestNormalized> {
    payload
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|passenger| {
            let passenger_id = passenger
                .get("passenger_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())?;
            let given_name = passenger
                .get("given_name")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())?;
            let family_name = passenger
                .get("family_name")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())?;
            let rider_category = passenger
                .get("rider_category")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())?;
            let nationality_code = passenger
                .get("nationality_code")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_ascii_uppercase);
            Some(CoachPassengerManifestNormalized {
                passenger_id: passenger_id.to_string(),
                given_name: given_name.to_string(),
                family_name: family_name.to_string(),
                rider_category: rider_category.to_string(),
                nationality_code,
            })
        })
        .collect::<Vec<_>>()
}

fn coach_booking_payload_for_offer(
    booking_id: &str,
    offer_id: &str,
    hold_id: Option<&str>,
    passenger_count: u8,
    state: &str,
) -> Value {
    let normalized_booking_id = booking_id.trim();
    json!({
        "booking_id": normalized_booking_id,
        "offer_id": offer_id.trim(),
        "hold_id": hold_id,
        "operator_booking_reference": format!("operator-booking-{normalized_booking_id}"),
        "state": state,
        "currency": "EUR",
        "total_minor_units": coach_offer_total_minor_units(offer_id, passenger_count),
        "passenger_count": passenger_count,
        "created_at": now_rfc3339()
    })
}

#[derive(Clone, Copy)]
struct CoachBookedJourneySummaryContext<'a> {
    trip_id: Option<&'a str>,
    journey_id: &'a str,
    operator_name: &'a str,
    from: &'a str,
    to: &'a str,
    departure_at: &'a str,
    arrival_at: &'a str,
    status_label: &'a str,
}

fn coach_booked_journey_summary_payload_with_trip(
    context: &CoachBookedJourneySummaryContext<'_>,
) -> Value {
    let mut payload = json!({
        "journey_id": context.journey_id,
        "operator_name": context.operator_name,
        "from": context.from,
        "to": context.to,
        "departure_at": context.departure_at,
        "arrival_at": context.arrival_at,
        "status_label": context.status_label,
    });
    if let Some(trip_id) = context
        .trip_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        payload["trip_id"] = Value::String(trip_id.to_string());
    }
    payload
}

fn coach_booked_journey_summary_payload(
    journey_id: &str,
    operator_name: &str,
    from: &str,
    to: &str,
    departure_at: &str,
    arrival_at: &str,
    status_label: &str,
) -> Value {
    coach_booked_journey_summary_payload_with_trip(&CoachBookedJourneySummaryContext {
        trip_id: None,
        journey_id,
        operator_name,
        from,
        to,
        departure_at,
        arrival_at,
        status_label,
    })
}

fn coach_ticket_payload_for_booking(
    ticket_id: &str,
    booking_id: &str,
    passenger_id: &str,
    ticket_index: usize,
) -> Value {
    let normalized_ticket_id = ticket_id.trim();
    json!({
        "ticket_id": normalized_ticket_id,
        "booking_id": booking_id.trim(),
        "coupon_id": format!("coupon-{normalized_ticket_id}"),
        "passenger_id": passenger_id,
        "segment_ids": [format!("seg_{}_{}", booking_id.trim(), ticket_index + 1)],
        "status": "active",
        "operator_ticket_reference": format!("operator-ticket-{normalized_ticket_id}"),
        "qr_payload_ref": format!("object://coach/tickets/{normalized_ticket_id}/qr"),
        "issued_at": now_rfc3339(),
        "boarding_state": "not_boarded"
    })
}

fn coach_ticket_artifact_payload(
    ticket_id: &str,
    booking_id: &str,
    artifact_kind: &str,
    delivery_channel: &str,
) -> Value {
    let normalized_ticket_id = ticket_id.trim();
    let normalized_booking_id = booking_id.trim();
    let normalized_kind = artifact_kind.trim().to_ascii_lowercase();
    let artifact_id = coach_scoped_resource_id(
        "ticketartifact",
        &format!("{normalized_booking_id}|{normalized_ticket_id}|{normalized_kind}"),
    );
    let (extension, mime_type, file_name, content_length_bytes) = match normalized_kind.as_str() {
        "pdf" => (
            "pdf",
            "application/pdf",
            format!("{normalized_ticket_id}.pdf"),
            32_768_i64,
        ),
        "wallet_pass" => (
            "pkpass",
            "application/vnd.apple.pkpass",
            format!("{normalized_ticket_id}.pkpass"),
            8_192_i64,
        ),
        _ => (
            "svg",
            "image/svg+xml",
            format!("{normalized_ticket_id}-qr.svg"),
            2_048_i64,
        ),
    };
    json!({
        "artifact_id": artifact_id.clone(),
        "ticket_id": normalized_ticket_id,
        "booking_id": normalized_booking_id,
        "artifact_kind": normalized_kind,
        "delivery_channel": delivery_channel.trim().to_ascii_lowercase(),
        "status": "ready",
        "file_name": file_name,
        "mime_type": mime_type,
        "content_length_bytes": content_length_bytes,
        "download_path": format!("/downloads/coach/tickets/{artifact_id}.{extension}"),
    })
}

fn coach_ticket_artifacts_payload_for_ticket(
    ticket_id: &str,
    booking_id: &str,
    delivery_channels: &[String],
) -> Vec<Value> {
    let mut artifacts = vec![coach_ticket_artifact_payload(
        ticket_id, booking_id, "qr", "qr",
    )];
    let mut emitted = std::collections::BTreeSet::new();
    for channel in delivery_channels {
        let normalized = channel.trim().to_ascii_lowercase();
        if !matches!(normalized.as_str(), "wallet_pass" | "pdf")
            || !emitted.insert(normalized.clone())
        {
            continue;
        }
        artifacts.push(coach_ticket_artifact_payload(
            ticket_id,
            booking_id,
            normalized.as_str(),
            normalized.as_str(),
        ));
    }
    artifacts
}

fn coach_ticket_payload_with_artifacts(
    ticket_payload: &Value,
    delivery_channels: &[String],
) -> Value {
    let Some(mut out) = ticket_payload.as_object().cloned() else {
        return ticket_payload.clone();
    };
    let ticket_id = out
        .get("ticket_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let booking_id = out
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    out.insert(
        "artifacts".to_string(),
        Value::Array(coach_ticket_artifacts_payload_for_ticket(
            ticket_id,
            booking_id,
            delivery_channels,
        )),
    );
    Value::Object(out)
}

fn coach_demo_booking_tickets_payload(seed: &CoachDemoBookingSeed) -> Vec<Value> {
    if seed.booking_state != "ticketed" && seed.booking_state != "refund_requested" {
        return Vec::new();
    }
    coach_passenger_manifest_ids(&seed.passengers_manifest)
        .iter()
        .enumerate()
        .map(|(index, passenger_id)| {
            coach_ticket_payload_for_booking(
                &format!("ticket_{}_{}", seed.booking_id, index + 1),
                seed.booking_id,
                passenger_id,
                index,
            )
        })
        .collect::<Vec<_>>()
}

fn coach_demo_booking_shelf_entry_payload(seed: &CoachDemoBookingSeed) -> Value {
    let passenger_ids = coach_passenger_manifest_ids(&seed.passengers_manifest);
    json!({
        "journey": coach_booked_journey_summary_payload(
            seed.journey_id,
            seed.operator_name,
            seed.from,
            seed.to,
            seed.departure_at,
            seed.arrival_at,
            seed.status_label,
        ),
        "offer": coach_offer_payload(seed.offer_id, passenger_ids.len() as u8),
        "hold": coach_hold_payload_for_offer(
            seed.hold_id,
            seed.offer_id,
            &passenger_ids,
            &seed.seat_numbers,
            "converted",
        ),
        "booking": coach_booking_payload_for_offer(
            seed.booking_id,
            seed.offer_id,
            Some(seed.hold_id),
            passenger_ids.len() as u8,
            seed.booking_state,
        ),
        "passengers_manifest": coach_passenger_manifest_payload(&seed.passengers_manifest),
        "tickets": coach_demo_booking_tickets_payload(seed),
    })
}

fn coach_booking_status_label(state: &str) -> &'static str {
    match state.trim() {
        "ticketed" => "Boarding pass ready",
        "partially_ticketed" => "Ticketing still in progress",
        "refund_requested" => "Refund review pending",
        "refund_approved" => "Refund approved",
        "refunded" => "Refund completed",
        "cancelled" => "Booking cancelled",
        "payment_pending" | "payment_authorized" | "booking_pending" => {
            "Payment confirmed, ticket issue pending"
        }
        _ => "Booking updated",
    }
}

fn coach_placeholder_passenger_manifest_payload(passenger_ids: &[String]) -> Value {
    Value::Array(
        passenger_ids
            .iter()
            .map(|passenger_id| {
                json!({
                    "passenger_id": passenger_id,
                    "given_name": "Passenger",
                    "family_name": passenger_id,
                    "rider_category": "adult",
                    "nationality_code": Value::Null,
                })
            })
            .collect::<Vec<_>>(),
    )
}

fn coach_booking_passenger_manifest_payload(aggregate: &CoachStoredBookingAggregate) -> Value {
    let manifest = aggregate.passengers_manifest.clone();
    if manifest
        .as_array()
        .map(|entries| !entries.is_empty())
        .unwrap_or(false)
    {
        return manifest;
    }
    let ticket_passenger_ids = aggregate
        .tickets
        .iter()
        .filter_map(|ticket| ticket.get("passenger_id").and_then(Value::as_str))
        .map(str::to_string)
        .collect::<Vec<_>>();
    if !ticket_passenger_ids.is_empty() {
        return coach_placeholder_passenger_manifest_payload(ticket_passenger_ids.as_slice());
    }
    let fallback_count = aggregate
        .booking
        .get("passenger_count")
        .and_then(Value::as_u64)
        .unwrap_or(1) as usize;
    let fallback_ids = (1..=fallback_count)
        .map(|index| format!("pax_{index}"))
        .collect::<Vec<_>>();
    coach_placeholder_passenger_manifest_payload(fallback_ids.as_slice())
}

fn coach_booking_offer_payload_from_aggregate(aggregate: &CoachStoredBookingAggregate) -> Value {
    if let Some(payload) = aggregate.offer.as_ref() {
        return payload.clone();
    }
    let offer_id = aggregate
        .booking
        .get("offer_id")
        .and_then(Value::as_str)
        .unwrap_or("offer_demo_express_direct");
    let passengers = aggregate
        .booking
        .get("passenger_count")
        .and_then(Value::as_u64)
        .and_then(|value| u8::try_from(value).ok())
        .unwrap_or(1);
    coach_offer_payload(offer_id, passengers)
}

fn coach_booking_hold_payload_from_aggregate(
    aggregate: &CoachStoredBookingAggregate,
) -> Option<Value> {
    if let Some(payload) = aggregate.hold.as_ref() {
        return Some(payload.clone());
    }
    let hold_id = aggregate.booking.get("hold_id").and_then(Value::as_str)?;
    let offer_id = aggregate
        .booking
        .get("offer_id")
        .and_then(Value::as_str)
        .unwrap_or("offer_demo_express_direct");
    let manifest = coach_booking_passenger_manifest_payload(aggregate);
    let passenger_ids = manifest
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|entry| entry.get("passenger_id").and_then(Value::as_str))
        .map(str::to_string)
        .collect::<Vec<_>>();
    let status = match aggregate
        .booking
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("booking_pending")
    {
        "ticketed" | "partially_ticketed" | "refund_requested" | "refund_approved" | "refunded" => {
            "converted"
        }
        "cancelled" => "released",
        _ => "active",
    };
    Some(coach_hold_payload_for_offer(
        hold_id,
        offer_id,
        passenger_ids.as_slice(),
        &[],
        status,
    ))
}

fn coach_seat_numbers_from_hold_payload(
    hold_payload: Option<&Value>,
    passenger_ids: &[String],
) -> Vec<String> {
    let mut by_passenger_id = HashMap::<String, String>::new();
    if let Some(entries) = hold_payload
        .and_then(|payload| payload.get("seat_assignments"))
        .and_then(Value::as_array)
    {
        for entry in entries {
            let Some(passenger_id) = entry
                .get("passenger_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            else {
                continue;
            };
            let Some(seat_number) = entry
                .get("seat_number")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            else {
                continue;
            };
            by_passenger_id.insert(passenger_id.to_string(), seat_number.to_string());
        }
    }
    passenger_ids
        .iter()
        .enumerate()
        .map(|(index, passenger_id)| {
            by_passenger_id
                .get(passenger_id)
                .cloned()
                .unwrap_or_else(|| coach_default_seat_number(index))
        })
        .collect::<Vec<_>>()
}

fn coach_reissue_hold_id(booking_id: &str, target_offer_id: &str) -> String {
    coach_scoped_resource_id("hold", &format!("{booking_id}|reissue|{target_offer_id}"))
}

fn coach_generic_journey_summary_payload(
    booking_id: &str,
    offer_id: &str,
    booking_state: &str,
) -> Value {
    let departure_at =
        chrono::DateTime::<chrono::Utc>::from(SystemTime::now()) + chrono::Duration::hours(24);
    let arrival_at = departure_at + chrono::Duration::hours(4);
    let trip_id = coach_scoped_resource_id("trip", &format!("{booking_id}|{offer_id}"));
    let journey_id = coach_scoped_resource_id("journey", &format!("{booking_id}|{offer_id}"));
    let departure_at = departure_at.to_rfc3339();
    let arrival_at = arrival_at.to_rfc3339();
    coach_booked_journey_summary_payload_with_trip(&CoachBookedJourneySummaryContext {
        trip_id: Some(trip_id.as_str()),
        journey_id: &journey_id,
        operator_name: "Coach service",
        from: "Selected origin",
        to: "Selected destination",
        departure_at: &departure_at,
        arrival_at: &arrival_at,
        status_label: coach_booking_status_label(booking_state),
    })
}

#[derive(Clone, Copy)]
struct CoachPersistBookingPayloadRequest<'a> {
    account_id: &'a str,
    booking_id: &'a str,
    offer_id: &'a str,
    hold_id: Option<&'a str>,
    request_fingerprint: &'a str,
    booking_payload: &'a Value,
    offer_payload: Option<&'a Value>,
    hold_payload: Option<&'a Value>,
    journey_summary_payload: Option<&'a Value>,
    passengers_manifest_payload: Option<&'a Value>,
}

async fn coach_persist_booking_payload(
    state: &AppState,
    request: &CoachPersistBookingPayloadRequest<'_>,
) -> Result<(), sqlx::Error> {
    let Some(auth) = &state.auth else {
        return Ok(());
    };
    let booking_state = request
        .booking_payload
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("booking_pending");
    let repo = CoachCatalogRepository::new(auth.pool().clone());
    repo.upsert_booking_payload(&CoachBookingPayloadUpsert {
        account_id: request.account_id,
        booking_id: request.booking_id,
        offer_id: request.offer_id,
        hold_id: request.hold_id,
        state: booking_state,
        request_fingerprint: request.request_fingerprint,
        booking_payload: request.booking_payload,
        offer_payload: request.offer_payload,
        hold_payload: request.hold_payload,
        journey_summary_payload: request.journey_summary_payload,
        passengers_manifest_payload: request.passengers_manifest_payload,
    })
    .await
}

fn coach_booking_journey_payload_from_aggregate(aggregate: &CoachStoredBookingAggregate) -> Value {
    let booking_id = aggregate
        .booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or("booking_demo_express_direct");
    let offer_id = aggregate
        .booking
        .get("offer_id")
        .and_then(Value::as_str)
        .unwrap_or("offer_demo_express_direct");
    let booking_state = aggregate
        .booking
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("booking_pending");
    let mut payload = aggregate.journey.clone().unwrap_or_else(|| {
        coach_generic_journey_summary_payload(booking_id, offer_id, booking_state)
    });
    if let Some(object) = payload.as_object_mut() {
        let operator_name_missing = object
            .get("operator_name")
            .and_then(Value::as_str)
            .map(str::trim)
            .is_none_or(|value| value.is_empty() || value == "Coach service");
        if operator_name_missing {
            object.insert(
                "operator_name".to_string(),
                Value::String(coach_runtime_operator_name_from_aggregate(aggregate)),
            );
        }
        object.insert(
            "status_label".to_string(),
            Value::String(coach_booking_status_label(booking_state).to_string()),
        );
    }
    payload
}

fn coach_stored_booking_shelf_entry_payload(aggregate: &CoachStoredBookingAggregate) -> Value {
    let mut entry = Map::new();
    entry.insert(
        "journey".to_string(),
        coach_booking_journey_payload_from_aggregate(aggregate),
    );
    entry.insert(
        "offer".to_string(),
        coach_booking_offer_payload_from_aggregate(aggregate),
    );
    if let Some(hold_payload) = coach_booking_hold_payload_from_aggregate(aggregate) {
        entry.insert("hold".to_string(), hold_payload);
    }
    entry.insert("booking".to_string(), aggregate.booking.clone());
    entry.insert(
        "passengers_manifest".to_string(),
        coach_booking_passenger_manifest_payload(aggregate),
    );
    entry.insert(
        "tickets".to_string(),
        Value::Array(aggregate.tickets.clone()),
    );
    Value::Object(entry)
}

fn coach_booking_shelf_payload_from_aggregates(
    aggregates: &[CoachStoredBookingAggregate],
) -> Value {
    let ticketed_count = aggregates
        .iter()
        .filter(|aggregate| {
            matches!(
                aggregate.booking.get("state").and_then(Value::as_str),
                Some("ticketed" | "partially_ticketed")
            )
        })
        .count();
    let needs_action_count = aggregates
        .iter()
        .filter(|aggregate| {
            matches!(
                aggregate.booking.get("state").and_then(Value::as_str),
                Some(
                    "booking_pending"
                        | "payment_pending"
                        | "payment_authorized"
                        | "refund_requested"
                )
            )
        })
        .count();
    json!({
        "summary": {
            "upcoming_count": aggregates.len(),
            "ticketed_count": ticketed_count,
            "needs_action_count": needs_action_count,
        },
        "bookings": aggregates
            .iter()
            .map(coach_stored_booking_shelf_entry_payload)
            .collect::<Vec<_>>(),
    })
}

fn coach_journey_live_payload_from_aggregate(
    aggregate: &CoachStoredBookingAggregate,
    trip_aggregates: &[CoachStoredBookingAggregate],
    journey: &Value,
    trip_id: &str,
    operator_id: &str,
    event_map: &CoachBoardingEventMap,
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> Value {
    let (offer, hold, booking) = if trip_aggregates.len() == 1 {
        (
            coach_booking_offer_payload_from_aggregate(aggregate),
            coach_booking_hold_payload_from_aggregate(aggregate).unwrap_or(Value::Null),
            aggregate.booking.clone(),
        )
    } else {
        (Value::Null, Value::Null, Value::Null)
    };
    json!({
        "journey": journey,
        "offer": offer,
        "hold": hold,
        "booking": booking,
        "passengers_manifest": coach_runtime_trip_group_passengers_manifest_payload(trip_aggregates),
        "tickets": coach_runtime_trip_group_ticket_payloads(trip_aggregates, trip_id, event_map),
        "trip": coach_runtime_crew_trip_payload(trip_aggregates, trip_id, event_map),
        "recent_events": coach_recent_boarding_events_payload(trip_id, event_map),
        "operator_feed_health": coach_filter_operator_feed_health_for_operator_id(feed_health, operator_id)
            .iter()
            .map(coach_operator_feed_health_payload)
            .collect::<Vec<_>>(),
    })
}

fn coach_journey_live_payload_from_seed(
    seed: &CoachDemoBookingSeed,
    event_map: &CoachBoardingEventMap,
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> Value {
    let trip = coach_demo_or_generic_trip_payload(seed, event_map);
    let trip_id = trip
        .get("trip_id")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let operator_id = coach_demo_booking_operator_id(seed);
    json!({
        "journey": coach_booked_journey_summary_payload(
            seed.journey_id,
            seed.operator_name,
            seed.from,
            seed.to,
            seed.departure_at,
            seed.arrival_at,
            seed.status_label,
        ),
        "offer": coach_offer_payload(seed.offer_id, seed.passengers_manifest.len() as u8),
        "hold": coach_hold_payload_for_offer(
            seed.hold_id,
            seed.offer_id,
            &coach_passenger_manifest_ids(&seed.passengers_manifest),
            &seed.seat_numbers,
            "converted",
        ),
        "booking": coach_booking_payload_for_offer(
            seed.booking_id,
            seed.offer_id,
            Some(seed.hold_id),
            seed.passengers_manifest.len() as u8,
            seed.booking_state,
        ),
        "passengers_manifest": coach_passenger_manifest_payload(&seed.passengers_manifest),
        "tickets": coach_ticket_payloads_with_boarding_state(
            &coach_demo_booking_tickets_payload(seed),
            &trip_id,
            event_map,
        ),
        "trip": trip,
        "recent_events": coach_recent_boarding_events_payload(&trip_id, event_map),
        "operator_feed_health": coach_filter_operator_feed_health_for_operator_id(feed_health, operator_id)
            .iter()
            .map(coach_operator_feed_health_payload)
            .collect::<Vec<_>>(),
    })
}

async fn coach_list_stored_mutation_replays_global_for_request(
    state: &AppState,
) -> Result<Vec<CoachStoredMutationReplayEntry>, sqlx::Error> {
    let Some(auth_runtime) = state.auth.as_ref() else {
        return Ok(Vec::new());
    };
    let rows = sqlx::query(
        "SELECT command, idempotency_key, response_json::text AS response_json_text, created_at::text AS created_at \
         FROM auth_coach_mutation_replays \
         ORDER BY created_at ASC, command ASC, idempotency_key ASC",
    )
    .fetch_all(auth_runtime.pool())
    .await?;

    let mut entries = Vec::with_capacity(rows.len());
    for row in rows {
        let command: String = row.try_get("command")?;
        if !matches!(
            command.as_str(),
            "coach_booking_create"
                | "coach_ticket_issue"
                | "coach_ticket_reissue"
                | "coach_ticket_reissue_recovery"
                | "coach_ticket_reissue_recovery_admin"
                | "coach_refund_request"
                | "coach_rebook_request"
        ) {
            continue;
        }
        let response_json_text: String = row.try_get("response_json_text")?;
        let Ok(response_json) = serde_json::from_str::<Value>(response_json_text.trim()) else {
            tracing::error!("coach support replay payload decode failed");
            continue;
        };
        entries.push(CoachStoredMutationReplayEntry {
            command,
            idempotency_key: row.try_get::<String, _>("idempotency_key")?,
            response_json,
            created_at: row.try_get::<String, _>("created_at")?,
        });
    }
    Ok(entries)
}

fn coach_stored_mutation_replay_booking_id(
    entry: &CoachStoredMutationReplayEntry,
) -> Option<String> {
    entry.response_json["booking"]["booking_id"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn coach_stored_mutation_replay_cmp(
    left: &CoachStoredMutationReplayEntry,
    right: &CoachStoredMutationReplayEntry,
) -> std::cmp::Ordering {
    left.created_at
        .cmp(&right.created_at)
        .then_with(|| left.idempotency_key.cmp(&right.idempotency_key))
        .then_with(|| left.command.cmp(&right.command))
}

fn coach_build_mutation_replay_index(
    entries: &[CoachStoredMutationReplayEntry],
) -> CoachMutationReplayIndex {
    let mut index = CoachMutationReplayIndex::default();
    for entry in entries {
        let Some(booking_id) = coach_stored_mutation_replay_booking_id(entry) else {
            continue;
        };
        match entry.command.as_str() {
            "coach_booking_create" => {
                let replace = index
                    .booking_creates
                    .get(&booking_id)
                    .map(|existing| coach_stored_mutation_replay_cmp(existing, entry).is_le())
                    .unwrap_or(true);
                if replace {
                    index.booking_creates.insert(booking_id, entry.clone());
                }
            }
            "coach_ticket_issue" => index
                .ticket_issues
                .entry(booking_id)
                .or_default()
                .push(entry.clone()),
            "coach_ticket_reissue" => {
                index
                    .ticket_issues
                    .entry(booking_id.clone())
                    .or_default()
                    .push(entry.clone());
                index
                    .change_requests
                    .entry(booking_id)
                    .or_default()
                    .push(entry.clone());
            }
            "coach_ticket_reissue_recovery" | "coach_ticket_reissue_recovery_admin" => {
                index
                    .ticket_issues
                    .entry(booking_id.clone())
                    .or_default()
                    .push(entry.clone());
                index
                    .change_requests
                    .entry(booking_id)
                    .or_default()
                    .push(entry.clone());
            }
            "coach_refund_request" => index
                .refund_requests
                .entry(booking_id)
                .or_default()
                .push(entry.clone()),
            "coach_rebook_request" => index
                .change_requests
                .entry(booking_id)
                .or_default()
                .push(entry.clone()),
            _ => {}
        }
    }
    index
}

fn coach_latest_stored_mutation_replay(
    entries: &[CoachStoredMutationReplayEntry],
) -> Option<&CoachStoredMutationReplayEntry> {
    entries
        .iter()
        .max_by(|left, right| coach_stored_mutation_replay_cmp(left, right))
}

fn coach_replay_nested_payload(entry: &CoachStoredMutationReplayEntry, key: &str) -> Option<Value> {
    entry.response_json.get(key).cloned()
}

fn coach_latest_replay_nested_payload(
    entries: &[CoachStoredMutationReplayEntry],
    key: &str,
) -> Option<Value> {
    coach_latest_stored_mutation_replay(entries)
        .and_then(|entry| coach_replay_nested_payload(entry, key))
}

fn coach_latest_change_request_replay(
    entries: &[CoachStoredMutationReplayEntry],
) -> Option<&CoachStoredMutationReplayEntry> {
    coach_latest_stored_mutation_replay(entries)
}

fn coach_change_request_payload_from_replay(
    entry: &CoachStoredMutationReplayEntry,
) -> Option<Value> {
    coach_replay_nested_payload(entry, "change_request")
}

fn coach_change_request_status_from_replay(
    entry: &CoachStoredMutationReplayEntry,
) -> Option<String> {
    coach_change_request_payload_from_replay(entry).and_then(|payload| {
        payload
            .get("status")
            .and_then(Value::as_str)
            .map(str::to_string)
    })
}

fn coach_replay_delivery_channels(entry: &CoachStoredMutationReplayEntry) -> Vec<String> {
    entry.response_json["delivery_channels"]
        .as_array()
        .map(|values| {
            values
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .filter(|values| !values.is_empty())
        .unwrap_or_else(|| vec!["wallet_pass".to_string(), "pdf".to_string()])
}

fn coach_support_passenger_display_name(passengers_manifest: &Value) -> String {
    passengers_manifest
        .as_array()
        .into_iter()
        .flatten()
        .enumerate()
        .filter_map(|(index, passenger)| {
            let given_name = passenger
                .get("given_name")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .trim();
            let family_name = passenger
                .get("family_name")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .trim();
            let display_name = [given_name, family_name]
                .into_iter()
                .filter(|value| !value.is_empty())
                .collect::<Vec<_>>()
                .join(" ");
            if display_name.is_empty() {
                return None;
            }
            let canonical_passenger_id = passenger
                .get("passenger_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
                .unwrap_or_else(|| format!("~{index:08}"));
            Some((canonical_passenger_id, display_name))
        })
        .min_by(|left, right| left.0.cmp(&right.0).then_with(|| left.1.cmp(&right.1)))
        .map(|(_, display_name)| display_name)
        .unwrap_or_else(|| "Passenger".to_string())
}

fn coach_support_passenger_count(passengers_manifest: &Value, booking: &Value) -> usize {
    passengers_manifest
        .as_array()
        .map(|entries| entries.len())
        .filter(|count| *count > 0)
        .unwrap_or_else(|| {
            booking
                .get("passenger_count")
                .and_then(Value::as_u64)
                .unwrap_or(1) as usize
        })
}

fn coach_support_ticket_ids(tickets: &[Value]) -> Vec<String> {
    tickets
        .iter()
        .filter_map(|ticket| ticket.get("ticket_id").and_then(Value::as_str))
        .map(str::to_string)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>()
}

fn coach_support_operator_ticket_references(tickets: &[Value]) -> Vec<String> {
    tickets
        .iter()
        .filter_map(|ticket| {
            ticket
                .get("operator_ticket_reference")
                .and_then(Value::as_str)
        })
        .map(str::to_string)
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>()
}

fn coach_support_request_review_entry<'a>(
    request_payload: Option<&Value>,
    request_id_field: &str,
    review_map: &'a CoachOpsReviewMap,
) -> Option<&'a CoachOpsReviewEntry> {
    let request_id = request_payload?
        .get(request_id_field)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    review_map.get(request_id)
}

fn coach_support_case_has_attention(tickets: &[Value], recent_events: &[Value]) -> bool {
    tickets.iter().any(|ticket| {
        matches!(
            ticket.get("boarding_state").and_then(Value::as_str),
            Some("denied" | "revoked" | "no_show")
        )
    }) || recent_events.iter().any(|event| {
        matches!(
            event.get("scan_status").and_then(Value::as_str),
            Some("duplicate" | "denied" | "revoked" | "no_show")
        )
    })
}

fn coach_support_case_needs_attention(
    tickets: &[Value],
    change_request: Option<&Value>,
    change_review: Option<&CoachOpsReviewEntry>,
    recent_events: &[Value],
) -> bool {
    coach_support_case_has_attention(tickets, recent_events)
        || matches!(
            coach_support_change_resolution_state(change_request, change_review),
            Some("payment_failed")
        )
}

fn coach_support_case_all_boarded(tickets: &[Value]) -> bool {
    !tickets.is_empty()
        && tickets
            .iter()
            .all(|ticket| ticket.get("boarding_state").and_then(Value::as_str) == Some("boarded"))
}

fn coach_support_change_resolution_state(
    change_request: Option<&Value>,
    change_review: Option<&CoachOpsReviewEntry>,
) -> Option<&'static str> {
    let change_request = change_request?;
    match change_review.map(|entry| entry.queue_status.as_str()) {
        Some("approved") => Some("approved"),
        Some("rejected") => Some("rejected"),
        Some("payment_failed") => Some("payment_failed"),
        _ if change_request.get("status").and_then(Value::as_str) == Some("payment_failed") => {
            Some("payment_failed")
        }
        _ if change_request.get("status").and_then(Value::as_str) == Some("reissued") => {
            Some("reissued")
        }
        _ => Some("pending_review"),
    }
}

fn coach_support_case_open_request_kinds(
    refund_request: Option<&Value>,
    refund_review: Option<&CoachOpsReviewEntry>,
    change_request: Option<&Value>,
    change_review: Option<&CoachOpsReviewEntry>,
) -> Vec<String> {
    let mut out = Vec::new();
    if refund_request.is_some()
        && !matches!(
            refund_review.map(|entry| entry.queue_status.as_str()),
            Some("approved" | "rejected")
        )
    {
        out.push("refund_request".to_string());
    }
    if change_request.is_some()
        && matches!(
            coach_support_change_resolution_state(change_request, change_review),
            Some("pending_review" | "payment_failed")
        )
    {
        out.push("change_request".to_string());
    }
    out
}

fn coach_support_case_status(
    booking_state: &str,
    tickets: &[Value],
    refund_request: Option<&Value>,
    refund_review: Option<&CoachOpsReviewEntry>,
    change_request: Option<&Value>,
    change_review: Option<&CoachOpsReviewEntry>,
    recent_events: &[Value],
) -> String {
    if coach_support_case_has_attention(tickets, recent_events) {
        return "attention_required".to_string();
    }
    let change_state = coach_support_change_resolution_state(change_request, change_review);
    if change_state == Some("payment_failed") {
        return "change_payment_failed".to_string();
    }
    if refund_request.is_some() {
        return match refund_review.map(|entry| entry.queue_status.as_str()) {
            Some("approved") => "refund_approved".to_string(),
            Some("rejected") => "refund_rejected".to_string(),
            _ => "refund_requested".to_string(),
        };
    }
    if change_request.is_some() {
        return match change_state {
            Some("approved") => "change_approved".to_string(),
            Some("rejected") => "change_rejected".to_string(),
            Some("reissued") => "change_reissued".to_string(),
            Some("payment_failed") => "change_payment_failed".to_string(),
            _ => "change_requested".to_string(),
        };
    }
    if coach_support_case_all_boarded(tickets) {
        return "boarded".to_string();
    }
    if booking_state.trim().is_empty() {
        "unknown".to_string()
    } else {
        booking_state.trim().to_string()
    }
}

fn coach_support_case_priority(
    tickets: &[Value],
    refund_request: Option<&Value>,
    change_request: Option<&Value>,
    recent_events: &[Value],
) -> &'static str {
    let change_reissued = change_request
        .and_then(|payload| payload.get("status").and_then(Value::as_str))
        == Some("reissued");
    if coach_support_case_has_attention(tickets, recent_events) {
        return "high";
    }
    if refund_request.and_then(|payload| payload.get("selected_kind").and_then(Value::as_str))
        == Some("original_payment")
    {
        return "high";
    }
    if change_request
        .and_then(|payload| payload.get("total_due_minor_units").and_then(Value::as_i64))
        .unwrap_or_default()
        > 0
        && !change_reissued
    {
        return "high";
    }
    if refund_request.is_some() || (change_request.is_some() && !change_reissued) {
        return "medium";
    }
    "low"
}

fn coach_support_case_latest_activity_at(
    booking: &Value,
    tickets: &[Value],
    refund_request: Option<&Value>,
    refund_review: Option<&CoachOpsReviewEntry>,
    change_request: Option<&Value>,
    change_review: Option<&CoachOpsReviewEntry>,
    recent_events: &[Value],
) -> String {
    let mut candidates = Vec::<String>::new();
    if let Some(created_at) = booking.get("created_at").and_then(Value::as_str) {
        candidates.push(created_at.to_string());
    }
    for ticket in tickets {
        if let Some(issued_at) = ticket.get("issued_at").and_then(Value::as_str) {
            candidates.push(issued_at.to_string());
        }
    }
    if let Some(created_at) =
        refund_request.and_then(|payload| payload.get("created_at").and_then(Value::as_str))
    {
        candidates.push(created_at.to_string());
    }
    if let Some(reviewed_at) = refund_review.map(|entry| entry.reviewed_at.as_str()) {
        candidates.push(reviewed_at.to_string());
    }
    if let Some(created_at) =
        change_request.and_then(|payload| payload.get("created_at").and_then(Value::as_str))
    {
        candidates.push(created_at.to_string());
    }
    if let Some(reviewed_at) = change_review.map(|entry| entry.reviewed_at.as_str()) {
        candidates.push(reviewed_at.to_string());
    }
    for event in recent_events {
        if let Some(captured_at) = event.get("captured_at").and_then(Value::as_str) {
            candidates.push(captured_at.to_string());
        }
    }
    candidates.into_iter().max().unwrap_or_else(now_rfc3339)
}

#[derive(Clone, Copy)]
struct CoachSupportCaseSummaryContext<'a> {
    booking: &'a Value,
    journey: &'a Value,
    operator_name: &'a str,
    passengers_manifest: &'a Value,
    tickets: &'a [Value],
    payment_authorization_reference: Option<&'a str>,
    refund_request: Option<&'a Value>,
    refund_review: Option<&'a CoachOpsReviewEntry>,
    change_request: Option<&'a Value>,
    change_review: Option<&'a CoachOpsReviewEntry>,
    recent_events: &'a [Value],
}

#[derive(Clone, Copy)]
struct CoachSupportCaseTimelineContext<'a> {
    booking: &'a Value,
    payment_payload: Option<&'a Value>,
    compensation_payload: Option<&'a Value>,
    tickets: &'a [Value],
    refund_request: Option<&'a Value>,
    refund_review: Option<&'a CoachOpsReviewEntry>,
    change_request: Option<&'a Value>,
    latest_change_replay: Option<&'a CoachStoredMutationReplayEntry>,
    change_review: Option<&'a CoachOpsReviewEntry>,
    recent_events: &'a [Value],
}

#[derive(Clone, Copy)]
struct CoachSupportCaseDetailContext<'a> {
    state: &'a AppState,
    aggregate: &'a CoachStoredBookingAggregate,
    trip_id: &'a str,
    journey: &'a Value,
    operator_id: &'a str,
    replay_index: &'a CoachMutationReplayIndex,
    review_map: &'a CoachOpsReviewMap,
    event_map: &'a CoachBoardingEventMap,
    feed_health: &'a [CoachCatalogOperatorFeedHealth],
}

fn coach_support_case_summary_payload(context: &CoachSupportCaseSummaryContext<'_>) -> Value {
    let booking = context.booking;
    let journey = context.journey;
    let operator_name = context.operator_name;
    let passengers_manifest = context.passengers_manifest;
    let tickets = context.tickets;
    let payment_authorization_reference = context.payment_authorization_reference;
    let refund_request = context.refund_request;
    let refund_review = context.refund_review;
    let change_request = context.change_request;
    let change_review = context.change_review;
    let recent_events = context.recent_events;
    let booking_id = booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let booking_state = booking
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let ticket_ids = coach_support_ticket_ids(tickets);
    let operator_ticket_references = coach_support_operator_ticket_references(tickets);
    let open_request_kinds = coach_support_case_open_request_kinds(
        refund_request,
        refund_review,
        change_request,
        change_review,
    );
    let needs_attention =
        coach_support_case_needs_attention(tickets, change_request, change_review, recent_events);
    let case_status = coach_support_case_status(
        booking_state,
        tickets,
        refund_request,
        refund_review,
        change_request,
        change_review,
        recent_events,
    );
    let priority =
        coach_support_case_priority(tickets, refund_request, change_request, recent_events);
    json!({
        "case_id": booking_id,
        "booking_id": booking_id,
        "journey_id": journey.get("journey_id").and_then(Value::as_str).unwrap_or_default(),
        "operator_name": operator_name,
        "from": journey.get("from").and_then(Value::as_str).unwrap_or("Selected origin"),
        "to": journey.get("to").and_then(Value::as_str).unwrap_or("Selected destination"),
        "departure_at": journey.get("departure_at").and_then(Value::as_str).unwrap_or_default(),
        "arrival_at": journey.get("arrival_at").and_then(Value::as_str).unwrap_or_default(),
        "booking_state": booking_state,
        "case_status": case_status,
        "priority": priority,
        "passenger_display_name": coach_support_passenger_display_name(passengers_manifest),
        "passenger_count": coach_support_passenger_count(passengers_manifest, booking),
        "contact_email": booking.get("contact_email").and_then(Value::as_str),
        "operator_booking_reference": booking.get("operator_booking_reference").and_then(Value::as_str),
        "payment_authorization_reference": payment_authorization_reference,
        "ticket_ids": ticket_ids,
        "operator_ticket_references": operator_ticket_references,
        "open_request_kinds": open_request_kinds,
        "needs_attention": needs_attention,
        "latest_activity_at": coach_support_case_latest_activity_at(
            booking,
            tickets,
            refund_request,
            refund_review,
            change_request,
            change_review,
            recent_events,
        ),
    })
}

fn coach_support_case_matches_query(summary: &Value, query: Option<&str>) -> bool {
    let Some(query) = query else {
        return true;
    };
    let mut haystacks = Vec::<String>::new();
    for key in [
        "case_id",
        "booking_id",
        "journey_id",
        "operator_name",
        "from",
        "to",
        "booking_state",
        "case_status",
        "priority",
        "passenger_display_name",
        "contact_email",
        "operator_booking_reference",
        "payment_authorization_reference",
    ] {
        if let Some(value) = summary.get(key).and_then(Value::as_str) {
            haystacks.push(value.to_ascii_lowercase());
        }
    }
    for key in [
        "ticket_ids",
        "operator_ticket_references",
        "open_request_kinds",
    ] {
        if let Some(values) = summary.get(key).and_then(Value::as_array) {
            haystacks.extend(
                values
                    .iter()
                    .filter_map(Value::as_str)
                    .map(|value| value.to_ascii_lowercase()),
            );
        }
    }
    haystacks.into_iter().any(|value| value.contains(query))
}

fn coach_support_timeline_event_payload(
    event_id: &str,
    event_type: &str,
    title: &str,
    occurred_at: &str,
    status_label: &str,
    detail_lines: Vec<String>,
) -> Value {
    json!({
        "event_id": event_id,
        "event_type": event_type,
        "title": title,
        "occurred_at": occurred_at,
        "status_label": status_label,
        "detail_lines": detail_lines,
    })
}

fn coach_support_refund_outcome_event_title(refund_state: &str, selected_kind: &str) -> String {
    match (refund_state, selected_kind) {
        ("approved", "refund_credit") => "Refund approved as travel credit".to_string(),
        ("approved", "original_payment") => "Cash refund approved".to_string(),
        ("rejected", "refund_credit") => "Travel credit refund rejected".to_string(),
        ("rejected", "original_payment") => "Cash refund rejected".to_string(),
        ("approved", _) => "Refund approved".to_string(),
        ("rejected", _) => "Refund rejected".to_string(),
        _ => "Refund requested".to_string(),
    }
}

fn coach_support_change_payment_failed_event_copy(
    recovery_reference: Option<&str>,
    resolution_audit: Option<&Value>,
) -> (&'static str, &'static str) {
    let has_recovery_follow_up = recovery_reference
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .is_some()
        || resolution_audit.is_some();
    if has_recovery_follow_up {
        ("Change recovery follow-up", "recovery_follow_up")
    } else {
        ("Change payment failed", "payment_failed")
    }
}

fn coach_support_booking_created_status_label() -> &'static str {
    "created"
}

fn coach_support_boarding_event_title(scan_status: &str) -> &'static str {
    match scan_status {
        "scanned" => "Passenger boarded",
        "duplicate" => "Duplicate boarding scan",
        "revoked" => "Revoked ticket scanned",
        "denied" => "Boarding denied",
        "no_show" => "Passenger no-show",
        _ => "Boarding updated",
    }
}

fn coach_support_timeline_event_sort_rank(event_type: &str) -> u8 {
    match event_type {
        "refund_approved"
        | "refund_rejected"
        | "change_payment_failed"
        | "change_reissued"
        | "change_approved"
        | "change_rejected" => 2,
        "refund_reviewed" | "change_reviewed" => 1,
        _ => 0,
    }
}

fn coach_sort_support_timeline_events(mut events: Vec<Value>) -> Vec<Value> {
    events.sort_by(|left, right| {
        right
            .get("occurred_at")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .cmp(
                left.get("occurred_at")
                    .and_then(Value::as_str)
                    .unwrap_or_default(),
            )
            .then_with(|| {
                coach_support_timeline_event_sort_rank(
                    right
                        .get("event_type")
                        .and_then(Value::as_str)
                        .unwrap_or_default(),
                )
                .cmp(&coach_support_timeline_event_sort_rank(
                    left.get("event_type")
                        .and_then(Value::as_str)
                        .unwrap_or_default(),
                ))
            })
            .then_with(|| {
                right
                    .get("event_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .cmp(
                        left.get("event_id")
                            .and_then(Value::as_str)
                            .unwrap_or_default(),
                    )
            })
    });
    events
}

fn coach_support_case_list_summary_payload(cases: &[Value]) -> Value {
    let urgent_cases = cases
        .iter()
        .filter(|case| case.get("priority").and_then(Value::as_str) == Some("high"))
        .count() as i64;
    let refund_cases = cases
        .iter()
        .filter(|case| {
            case.get("open_request_kinds")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(Value::as_str)
                .any(|kind| kind == "refund_request")
                || case
                    .get("case_status")
                    .and_then(Value::as_str)
                    .is_some_and(|status| status.starts_with("refund_"))
        })
        .count() as i64;
    let change_cases = cases
        .iter()
        .filter(|case| {
            case.get("open_request_kinds")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(Value::as_str)
                .any(|kind| kind == "change_request")
                || case
                    .get("case_status")
                    .and_then(Value::as_str)
                    .is_some_and(|status| status.starts_with("change_"))
        })
        .count() as i64;
    let attention_cases = cases
        .iter()
        .filter(|case| case.get("needs_attention").and_then(Value::as_bool) == Some(true))
        .count() as i64;
    let boarded_cases = cases
        .iter()
        .filter(|case| case.get("case_status").and_then(Value::as_str) == Some("boarded"))
        .count() as i64;
    json!({
        "total_cases": cases.len(),
        "urgent_cases": urgent_cases,
        "refund_cases": refund_cases,
        "change_cases": change_cases,
        "attention_cases": attention_cases,
        "boarded_cases": boarded_cases,
    })
}

fn coach_sort_support_cases(mut cases: Vec<Value>) -> Vec<Value> {
    cases.sort_by(|left, right| {
        right["latest_activity_at"]
            .as_str()
            .unwrap_or_default()
            .cmp(left["latest_activity_at"].as_str().unwrap_or_default())
            .then_with(|| {
                right["booking_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(left["booking_id"].as_str().unwrap_or_default())
            })
            .then_with(|| {
                right["case_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(left["case_id"].as_str().unwrap_or_default())
            })
    });
    cases
}

fn coach_support_payment_payload_from_replay(
    booking_create_replay: Option<&CoachStoredMutationReplayEntry>,
) -> Option<Value> {
    booking_create_replay.and_then(|entry| coach_replay_nested_payload(entry, "payment"))
}

fn coach_support_latest_payment_payload(
    booking_create_replay: Option<&CoachStoredMutationReplayEntry>,
    change_replays: &[CoachStoredMutationReplayEntry],
) -> Option<Value> {
    let mut candidates = Vec::<&CoachStoredMutationReplayEntry>::new();
    if let Some(entry) = booking_create_replay {
        if entry.response_json.get("payment").is_some() {
            candidates.push(entry);
        }
    }
    if let Some(entry) = coach_latest_stored_mutation_replay(change_replays) {
        if entry.response_json.get("payment").is_some() {
            candidates.push(entry);
        }
    }
    candidates
        .into_iter()
        .max_by(|left, right| coach_stored_mutation_replay_cmp(left, right))
        .and_then(|entry| coach_replay_nested_payload(entry, "payment"))
}

fn coach_support_payment_reference_from_payload(payment_payload: Option<&Value>) -> Option<String> {
    payment_payload?
        .get("authorization_reference")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn coach_support_latest_compensation_payload(
    booking_create_replay: Option<&CoachStoredMutationReplayEntry>,
    ticket_issue_replays: &[CoachStoredMutationReplayEntry],
    refund_replays: &[CoachStoredMutationReplayEntry],
    change_replays: &[CoachStoredMutationReplayEntry],
) -> Option<Value> {
    let mut candidates = Vec::<&CoachStoredMutationReplayEntry>::new();
    if let Some(entry) = booking_create_replay {
        if entry.response_json.get("compensation").is_some() {
            candidates.push(entry);
        }
    }
    for entries in [ticket_issue_replays, refund_replays, change_replays] {
        if let Some(entry) = coach_latest_stored_mutation_replay(entries) {
            if entry.response_json.get("compensation").is_some() {
                candidates.push(entry);
            }
        }
    }
    candidates
        .into_iter()
        .max_by(|left, right| coach_stored_mutation_replay_cmp(left, right))
        .and_then(|entry| coach_replay_nested_payload(entry, "compensation"))
}

