fn coach_support_case_timeline_from_runtime(
    context: &CoachSupportCaseTimelineContext<'_>,
) -> Vec<Value> {
    let booking = context.booking;
    let payment_payload = context.payment_payload;
    let compensation_payload = context.compensation_payload;
    let tickets = context.tickets;
    let refund_request = context.refund_request;
    let refund_review = context.refund_review;
    let change_request = context.change_request;
    let latest_change_replay = context.latest_change_replay;
    let change_review = context.change_review;
    let recent_events = context.recent_events;
    let booking_id = booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or("booking");
    let mut timeline = Vec::new();
    let booking_created_at = booking
        .get("created_at")
        .and_then(Value::as_str)
        .unwrap_or_else(|| {
            compensation_payload
                .and_then(|payload| payload.get("created_at").and_then(Value::as_str))
                .unwrap_or_default()
        });
    if !booking_created_at.is_empty() {
        let mut detail_lines = vec![format!("Booking {booking_id}")];
        if let Some(operator_reference) = booking
            .get("operator_booking_reference")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            detail_lines.push(format!("Operator reference {operator_reference}"));
        }
        if let Some(payment) = payment_payload {
            if let Some(reference) = payment
                .get("authorization_reference")
                .and_then(Value::as_str)
            {
                let method = payment
                    .get("method")
                    .and_then(Value::as_str)
                    .unwrap_or("payment");
                detail_lines.push(format!("Payment {reference} via {method}"));
            }
        }
        detail_lines.push(format!(
            "Total {} {}",
            booking
                .get("total_minor_units")
                .and_then(Value::as_i64)
                .unwrap_or_default(),
            booking
                .get("currency")
                .and_then(Value::as_str)
                .unwrap_or("EUR"),
        ));
        timeline.push(coach_support_timeline_event_payload(
            &format!("{booking_id}|booking_created"),
            "booking_created",
            "Booking created",
            booking_created_at,
            coach_support_booking_created_status_label(),
            detail_lines,
        ));
    }
    if !tickets.is_empty() {
        let issued_at = tickets
            .iter()
            .filter_map(|ticket| ticket.get("issued_at").and_then(Value::as_str))
            .max()
            .unwrap_or_default();
        if !issued_at.is_empty() {
            let ticket_ids = coach_support_ticket_ids(tickets);
            let mut detail_lines = vec![format!("{} ticket(s) active", ticket_ids.len())];
            if !ticket_ids.is_empty() {
                detail_lines.push(format!("Ticket ids {}", ticket_ids.join(", ")));
            }
            let delivery_channels = tickets
                .iter()
                .filter_map(|ticket| ticket.get("artifacts").and_then(Value::as_array))
                .flat_map(|artifacts| artifacts.iter())
                .filter_map(|artifact| artifact.get("delivery_channel").and_then(Value::as_str))
                .map(str::to_string)
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            if !delivery_channels.is_empty() {
                detail_lines.push(format!("Delivery {}", delivery_channels.join(", ")));
            }
            timeline.push(coach_support_timeline_event_payload(
                &format!("{booking_id}|tickets_issued"),
                "tickets_issued",
                "Tickets issued",
                issued_at,
                "Ticketed",
                detail_lines,
            ));
        }
    }
    if let Some(refund_request) = refund_request {
        let created_at = refund_request
            .get("created_at")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if !created_at.is_empty() {
            let mut detail_lines = vec![format!(
                "{} {} requested",
                refund_request
                    .get("requested_minor_units")
                    .and_then(Value::as_i64)
                    .unwrap_or_default(),
                refund_request
                    .get("currency")
                    .and_then(Value::as_str)
                    .unwrap_or("EUR"),
            )];
            if let Some(reason) = refund_request
                .get("reason")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            {
                detail_lines.push(format!("Reason {reason}"));
            }
            let selected_kind = refund_request
                .get("selected_kind")
                .and_then(Value::as_str)
                .unwrap_or("refund");
            detail_lines.push(format!("Kind {selected_kind}"));
            let refund_state = refund_review
                .map(|entry| entry.queue_status.as_str())
                .unwrap_or("pending_review");
            let event_occurred_at = if refund_state != "pending_review" {
                refund_review
                    .map(|entry| entry.reviewed_at.as_str())
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or(created_at)
            } else {
                created_at
            };
            if refund_state != "pending_review" {
                if let Some(review) = refund_review {
                    detail_lines.push(format!("Decision {}", review.decision));
                    detail_lines.push(format!("Reviewer {}", review.reviewed_by_account_id));
                    if let Some(note) = review
                        .review_note
                        .as_deref()
                        .map(str::trim)
                        .filter(|value| !value.is_empty())
                    {
                        detail_lines.push(format!("Ops note {note}"));
                    }
                }
            }
            let (event_kind, event_title) = match refund_state {
                "approved" => (
                    "refund_approved",
                    coach_support_refund_outcome_event_title(refund_state, selected_kind),
                ),
                "rejected" => (
                    "refund_rejected",
                    coach_support_refund_outcome_event_title(refund_state, selected_kind),
                ),
                _ => ("refund_requested", "Refund requested".to_string()),
            };
            timeline.push(coach_support_timeline_event_payload(
                &format!("{booking_id}|{event_kind}"),
                event_kind,
                &event_title,
                event_occurred_at,
                refund_state,
                detail_lines,
            ));
        }
    }
    if let Some(review) = refund_review {
        timeline.push(coach_support_timeline_event_payload(
            &format!("{booking_id}|refund_reviewed"),
            "refund_reviewed",
            "Refund reviewed",
            &review.reviewed_at,
            &review.queue_status,
            vec![
                format!("Decision {}", review.decision),
                format!("Reviewer {}", review.reviewed_by_account_id),
                review
                    .review_note
                    .clone()
                    .unwrap_or_else(|| "No review note".to_string()),
            ],
        ));
    }
    if let Some(change_request) = change_request {
        let created_at = change_request
            .get("created_at")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if !created_at.is_empty() {
            let mut detail_lines = vec![format!(
                "Target offer {}",
                change_request
                    .get("target_offer_id")
                    .and_then(Value::as_str)
                    .unwrap_or("offer"),
            )];
            detail_lines.push(format!(
                "Total due {} {}",
                change_request
                    .get("total_due_minor_units")
                    .and_then(Value::as_i64)
                    .unwrap_or_default(),
                change_request
                    .get("currency")
                    .and_then(Value::as_str)
                    .unwrap_or("EUR"),
            ));
            if let Some(reason) = change_request
                .get("reason")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            {
                detail_lines.push(format!("Reason {reason}"));
            }
            let change_state =
                coach_support_change_resolution_state(Some(change_request), change_review)
                    .unwrap_or("pending_review");
            let recovery_reference = compensation_payload
                .and_then(|payload| payload.get("recovery_reference").and_then(Value::as_str))
                .map(str::trim)
                .filter(|value| !value.is_empty());
            if change_state == "payment_failed" {
                if let Some(reason) = compensation_payload
                    .and_then(|payload| payload.get("reason").and_then(Value::as_str))
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                {
                    detail_lines.push(format!("Failure reason {reason}"));
                }
                if let Some(recovery_reference) = recovery_reference {
                    detail_lines.push(format!("Recovery {recovery_reference}"));
                }
            }
            let resolution_audit = latest_change_replay
                .filter(|entry| {
                    matches!(
                        entry.command.as_str(),
                        "coach_ticket_reissue_recovery" | "coach_ticket_reissue_recovery_admin"
                    )
                })
                .and_then(|entry| entry.response_json.get("resolution_audit"));
            if let Some(resolution_audit) = resolution_audit {
                if let Some(payment_method) = resolution_audit
                    .get("payment_method")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                {
                    detail_lines.push(format!("Recovery method {payment_method}"));
                }
                if let Some(actor_account_id) = resolution_audit
                    .get("resolved_by_account_id")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                {
                    detail_lines.push(format!("Actor {actor_account_id}"));
                }
                if let Some(note) = resolution_audit
                    .get("note")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                {
                    detail_lines.push(format!("Ops note {note}"));
                }
            }
            let event_occurred_at = if change_state != "pending_review" {
                change_review
                    .map(|entry| entry.reviewed_at.as_str())
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or(created_at)
            } else {
                created_at
            };
            if change_state != "pending_review" {
                if let Some(review) = change_review {
                    detail_lines.push(format!("Decision {}", review.decision));
                    detail_lines.push(format!("Reviewer {}", review.reviewed_by_account_id));
                    if let Some(note) = review
                        .review_note
                        .as_deref()
                        .map(str::trim)
                        .filter(|value| !value.is_empty())
                    {
                        detail_lines.push(format!("Ops note {note}"));
                    }
                }
            }
            let (event_kind, event_title) = match change_state {
                "approved" => ("change_approved", "Change approved"),
                "rejected" => ("change_rejected", "Change rejected"),
                "reissued" => ("change_reissued", "Change reissued"),
                "payment_failed" => {
                    let (title, _) = coach_support_change_payment_failed_event_copy(
                        recovery_reference,
                        resolution_audit,
                    );
                    ("change_payment_failed", title)
                }
                _ => ("change_requested", "Change requested"),
            };
            let status_label = match change_state {
                "payment_failed" => {
                    coach_support_change_payment_failed_event_copy(
                        recovery_reference,
                        resolution_audit,
                    )
                    .1
                }
                _ => change_state,
            };
            timeline.push(coach_support_timeline_event_payload(
                &format!("{booking_id}|{event_kind}"),
                event_kind,
                event_title,
                event_occurred_at,
                status_label,
                detail_lines,
            ));
        }
    }
    if let Some(review) = change_review {
        timeline.push(coach_support_timeline_event_payload(
            &format!("{booking_id}|change_reviewed"),
            "change_reviewed",
            "Change reviewed",
            &review.reviewed_at,
            &review.queue_status,
            vec![
                format!("Decision {}", review.decision),
                format!("Reviewer {}", review.reviewed_by_account_id),
                review
                    .review_note
                    .clone()
                    .unwrap_or_else(|| "No review note".to_string()),
            ],
        ));
    }
    for event in recent_events {
        let event_id = event
            .get("boarding_event_id")
            .and_then(Value::as_str)
            .unwrap_or("boarding");
        let captured_at = event
            .get("captured_at")
            .and_then(Value::as_str)
            .unwrap_or_default();
        if captured_at.is_empty() {
            continue;
        }
        let scan_status = event
            .get("scan_status")
            .and_then(Value::as_str)
            .unwrap_or("recorded");
        let mut detail_lines = vec![format!(
            "Ticket {}",
            event
                .get("ticket_id")
                .and_then(Value::as_str)
                .unwrap_or("ticket")
        )];
        if event.get("offline_captured").and_then(Value::as_bool) == Some(true) {
            detail_lines.push("Captured offline".to_string());
        }
        if let Some(device_id) = event
            .get("device_id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            detail_lines.push(format!("Device {device_id}"));
        }
        if let Some(note) = event
            .get("note")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            detail_lines.push(note.to_string());
        }
        timeline.push(coach_support_timeline_event_payload(
            event_id,
            "boarding_event",
            coach_support_boarding_event_title(scan_status),
            captured_at,
            scan_status,
            detail_lines,
        ));
    }
    coach_sort_support_timeline_events(timeline)
}

async fn coach_support_case_detail_payload_from_aggregate(
    context: &CoachSupportCaseDetailContext<'_>,
) -> Result<Value, sqlx::Error> {
    let state = context.state;
    let aggregate = context.aggregate;
    let trip_id = context.trip_id;
    let journey = context.journey;
    let operator_id = context.operator_id;
    let replay_index = context.replay_index;
    let review_map = context.review_map;
    let event_map = context.event_map;
    let feed_health = context.feed_health;
    let booking_id = aggregate
        .booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let offer = coach_booking_offer_payload_from_aggregate(aggregate);
    let hold = coach_booking_hold_payload_from_aggregate(aggregate);
    let passengers_manifest = coach_booking_passenger_manifest_payload(aggregate);
    let tickets = coach_ticket_payloads_with_boarding_state(&aggregate.tickets, trip_id, event_map);
    let ticket_ids = coach_support_ticket_ids(tickets.as_slice());
    let recent_events =
        coach_recent_boarding_events_payload_for_tickets(trip_id, ticket_ids.as_slice(), event_map);
    let booking_create_replay = replay_index.booking_creates.get(&booking_id);
    let ticket_issue_replays = replay_index
        .ticket_issues
        .get(&booking_id)
        .cloned()
        .unwrap_or_default();
    let refund_replays = replay_index
        .refund_requests
        .get(&booking_id)
        .cloned()
        .unwrap_or_default();
    let change_replays = replay_index
        .change_requests
        .get(&booking_id)
        .cloned()
        .unwrap_or_default();
    let latest_change_replay = coach_latest_change_request_replay(change_replays.as_slice());
    let payment =
        coach_support_latest_payment_payload(booking_create_replay, change_replays.as_slice());
    let payment_reference = coach_support_payment_reference_from_payload(payment.as_ref());
    let compensation = coach_support_latest_compensation_payload(
        booking_create_replay,
        ticket_issue_replays.as_slice(),
        refund_replays.as_slice(),
        change_replays.as_slice(),
    );
    let refund_request =
        coach_latest_replay_nested_payload(refund_replays.as_slice(), "refund_request");
    let change_request =
        coach_latest_replay_nested_payload(change_replays.as_slice(), "change_request");
    let refund_review = coach_support_request_review_entry(
        refund_request.as_ref(),
        "refund_request_id",
        review_map,
    );
    let change_review = coach_support_request_review_entry(
        change_request.as_ref(),
        "change_request_id",
        review_map,
    );
    let operator_name = coach_operator_display_name_from_id(operator_id).unwrap_or_else(|| {
        journey
            .get("operator_name")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty() && *value != "Coach service")
            .map(str::to_string)
            .unwrap_or_else(|| "Coach service".to_string())
    });
    let summary = coach_support_case_summary_payload(&CoachSupportCaseSummaryContext {
        booking: &aggregate.booking,
        journey,
        operator_name: &operator_name,
        passengers_manifest: &passengers_manifest,
        tickets: tickets.as_slice(),
        payment_authorization_reference: payment_reference.as_deref(),
        refund_request: refund_request.as_ref(),
        refund_review,
        change_request: change_request.as_ref(),
        change_review,
        recent_events: recent_events.as_slice(),
    });
    let stored_artifacts = coach_list_ticket_artifact_payloads_for_booking_request(
        state,
        &aggregate.account_id,
        &booking_id,
    )
    .await?;
    let ticket_artifacts = if stored_artifacts.is_empty() {
        coach_collect_ticket_artifact_payloads(tickets.as_slice())
    } else {
        stored_artifacts
    };
    Ok(json!({
        "generated_at": now_rfc3339(),
        "support_case": summary,
        "journey": journey,
        "offer": offer,
        "hold": hold,
        "booking": aggregate.booking.clone(),
        "payment": payment,
        "compensation": compensation,
        "passengers_manifest": passengers_manifest,
        "tickets": tickets,
        "ticket_artifacts": ticket_artifacts,
        "refund_request": refund_request,
        "change_request": change_request,
        "recent_boarding_events": recent_events,
        "operator_feed_health": coach_filter_operator_feed_health_for_operator_id(feed_health, operator_id)
            .iter()
            .map(coach_operator_feed_health_payload)
            .collect::<Vec<_>>(),
        "timeline": coach_support_case_timeline_from_runtime(&CoachSupportCaseTimelineContext {
            booking: &aggregate.booking,
            payment_payload: payment.as_ref(),
            compensation_payload: compensation.as_ref(),
            tickets: tickets.as_slice(),
            refund_request: refund_request.as_ref(),
            refund_review,
            change_request: change_request.as_ref(),
            latest_change_replay,
            change_review,
            recent_events: recent_events.as_slice(),
        }),
    }))
}

fn coach_support_case_detail_payload_from_seed(
    seed: &CoachDemoBookingSeed,
    review_map: &CoachOpsReviewMap,
    event_map: &CoachBoardingEventMap,
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> Value {
    let booking = coach_booking_payload_for_offer(
        seed.booking_id,
        seed.offer_id,
        Some(seed.hold_id),
        seed.passengers_manifest.len() as u8,
        seed.booking_state,
    );
    let journey = coach_booked_journey_summary_payload(
        seed.journey_id,
        seed.operator_name,
        seed.from,
        seed.to,
        seed.departure_at,
        seed.arrival_at,
        seed.status_label,
    );
    let passengers_manifest = coach_passenger_manifest_payload(&seed.passengers_manifest);
    let trip_id = coach_demo_trip_id_for_booking_seed(seed);
    let tickets = coach_ticket_payloads_with_boarding_state(
        &coach_demo_booking_tickets_payload(seed),
        &trip_id,
        event_map,
    );
    let ticket_ids = coach_support_ticket_ids(tickets.as_slice());
    let recent_events = coach_recent_boarding_events_payload_for_tickets(
        &trip_id,
        ticket_ids.as_slice(),
        event_map,
    );
    let refund_queue_entry = coach_demo_refund_queue_entries_payload(review_map)
        .into_iter()
        .find(|entry| entry["booking_id"].as_str() == Some(seed.booking_id));
    let change_queue_entry = coach_demo_change_queue_entries_payload(review_map)
        .into_iter()
        .find(|entry| entry["booking_id"].as_str() == Some(seed.booking_id));
    let refund_request = refund_queue_entry
        .as_ref()
        .and_then(coach_support_demo_refund_request_payload);
    let change_request = change_queue_entry
        .as_ref()
        .and_then(coach_support_demo_change_request_payload);
    let refund_review = coach_support_request_review_entry(
        refund_request.as_ref(),
        "refund_request_id",
        review_map,
    );
    let change_review = coach_support_request_review_entry(
        change_request.as_ref(),
        "change_request_id",
        review_map,
    );
    let payment = Some(coach_payment_authorization_payload(
        seed.booking_id,
        "card",
        coach_offer_total_minor_units(seed.offer_id, seed.passengers_manifest.len() as u8),
    ));
    let payment_reference = coach_support_payment_reference_from_payload(payment.as_ref());
    let summary = coach_support_case_summary_payload(&CoachSupportCaseSummaryContext {
        booking: &booking,
        journey: &journey,
        operator_name: journey
            .get("operator_name")
            .and_then(Value::as_str)
            .unwrap_or("Coach service"),
        passengers_manifest: &passengers_manifest,
        tickets: tickets.as_slice(),
        payment_authorization_reference: payment_reference.as_deref(),
        refund_request: refund_request.as_ref(),
        refund_review,
        change_request: change_request.as_ref(),
        change_review,
        recent_events: recent_events.as_slice(),
    });
    json!({
        "generated_at": now_rfc3339(),
        "support_case": summary,
        "journey": journey,
        "offer": coach_offer_payload(seed.offer_id, seed.passengers_manifest.len() as u8),
        "hold": coach_hold_payload_for_offer(
            seed.hold_id,
            seed.offer_id,
            &coach_passenger_manifest_ids(&seed.passengers_manifest),
            &seed.seat_numbers,
            "converted",
        ),
        "booking": booking,
        "payment": payment,
        "compensation": Value::Null,
        "passengers_manifest": passengers_manifest,
        "tickets": tickets.clone(),
        "ticket_artifacts": coach_collect_ticket_artifact_payloads(tickets.as_slice()),
        "refund_request": refund_request,
        "change_request": change_request,
        "recent_boarding_events": recent_events.clone(),
        "operator_feed_health": coach_filter_operator_feed_health_for_operator_id(
            feed_health,
            coach_demo_booking_operator_id(seed),
        )
        .iter()
        .map(coach_operator_feed_health_payload)
        .collect::<Vec<_>>(),
        "timeline": coach_support_case_timeline_from_runtime(&CoachSupportCaseTimelineContext {
            booking: &booking,
            payment_payload: payment.as_ref(),
            compensation_payload: None,
            tickets: tickets.as_slice(),
            refund_request: refund_request.as_ref(),
            refund_review,
            change_request: change_request.as_ref(),
            latest_change_replay: None,
            change_review,
            recent_events: recent_events.as_slice(),
        }),
    })
}

fn coach_admin_risk_route_from_detail_lines(risk: &Value) -> Option<(String, String)> {
    risk["detail_lines"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .find_map(|line| {
            let (from, to) = line.split_once("->")?;
            let from = from.trim();
            let to = to.trim();
            if from.is_empty() || to.is_empty() {
                None
            } else {
                Some((from.to_string(), to.to_string()))
            }
        })
}

fn coach_admin_risk_support_case_priority(severity: &str) -> &'static str {
    match severity {
        "critical" | "high" => "high",
        "medium" => "medium",
        _ => "low",
    }
}

fn coach_admin_risk_support_case_priority_rank(priority: &str) -> u8 {
    match priority {
        "high" => 2,
        "medium" => 1,
        _ => 0,
    }
}

fn coach_admin_risk_support_case_status(base_summary: Option<&Value>) -> String {
    let Some(case_status) = base_summary
        .and_then(|value| value["case_status"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return "risk_follow_up".to_string();
    };
    if case_status == "attention_required"
        || case_status.starts_with("refund_")
        || case_status.starts_with("change_")
    {
        case_status.to_string()
    } else {
        "risk_follow_up".to_string()
    }
}

fn coach_admin_risk_booking_state_wire(risk: &Value) -> &'static str {
    if risk["risk_id"]
        .as_str()
        .unwrap_or_default()
        .starts_with("risk_refund_")
    {
        "refund_requested"
    } else {
        "ticketed"
    }
}

fn coach_admin_risk_support_case_summary_payload(
    risk: &Value,
    base_summary: Option<&Value>,
) -> Option<Value> {
    let case_id = risk["auto_case_id"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let route = coach_admin_risk_route_from_detail_lines(risk);
    let booking_id = base_summary
        .and_then(|value| value["booking_id"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .or_else(|| {
            risk["booking_id"]
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
        })
        .unwrap_or(case_id);
    let journey_id = base_summary
        .and_then(|value| value["journey_id"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| {
            risk["trip_id"]
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(|value| coach_scoped_resource_id("journey", value))
        })
        .unwrap_or_else(|| coach_scoped_resource_id("journey", case_id));
    let operator_name = base_summary
        .and_then(|value| value["operator_name"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .or_else(|| {
            risk["operator_name"]
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
        })
        .unwrap_or("Coach support")
        .to_string();
    let from = base_summary
        .and_then(|value| value["from"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| route.as_ref().map(|(from, _)| from.clone()))
        .unwrap_or_else(|| "Risk".to_string());
    let to = base_summary
        .and_then(|value| value["to"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| route.as_ref().map(|(_, to)| to.clone()))
        .unwrap_or_else(|| "Follow-up".to_string());
    let latest_activity_at = risk["workflow_updated_at"]
        .as_str()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| {
            risk["sla_due_at"]
                .as_str()
                .filter(|value| !value.trim().is_empty())
        })
        .or_else(|| {
            risk["detected_at"]
                .as_str()
                .filter(|value| !value.trim().is_empty())
        })
        .map(str::to_string)
        .unwrap_or_else(now_rfc3339);
    let departure_at = base_summary
        .and_then(|value| value["departure_at"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .or_else(|| {
            risk["sla_due_at"]
                .as_str()
                .filter(|value| !value.trim().is_empty())
        })
        .or_else(|| {
            risk["detected_at"]
                .as_str()
                .filter(|value| !value.trim().is_empty())
        })
        .map(str::to_string)
        .unwrap_or_else(|| latest_activity_at.clone());
    let arrival_at = base_summary
        .and_then(|value| value["arrival_at"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| departure_at.clone());
    let passenger_display_name = base_summary
        .and_then(|value| value["passenger_display_name"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("Risk follow-up")
        .to_string();
    let passenger_count = base_summary
        .and_then(|value| value["passenger_count"].as_i64())
        .filter(|value| *value > 0)
        .unwrap_or(1);
    let mut open_request_kinds = base_summary
        .and_then(|value| value["open_request_kinds"].as_array().cloned())
        .unwrap_or_default();
    if !open_request_kinds
        .iter()
        .filter_map(Value::as_str)
        .any(|kind| kind == "risk_follow_up")
    {
        open_request_kinds.push(Value::String("risk_follow_up".to_string()));
    }
    let case_status = coach_admin_risk_support_case_status(base_summary);
    let risk_priority =
        coach_admin_risk_support_case_priority(risk["severity"].as_str().unwrap_or_default());
    let base_priority = base_summary
        .and_then(|value| value["priority"].as_str())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_default();
    let priority = if coach_admin_risk_support_case_priority_rank(base_priority)
        > coach_admin_risk_support_case_priority_rank(risk_priority)
    {
        base_priority
    } else {
        risk_priority
    };
    Some(json!({
        "case_id": case_id,
        "booking_id": booking_id,
        "journey_id": journey_id,
        "operator_name": operator_name,
        "from": from,
        "to": to,
        "departure_at": departure_at,
        "arrival_at": arrival_at,
        "booking_state": base_summary
            .and_then(|value| value["booking_state"].as_str())
            .unwrap_or_else(|| coach_admin_risk_booking_state_wire(risk)),
        "case_status": case_status,
        "priority": priority,
        "passenger_display_name": passenger_display_name,
        "passenger_count": passenger_count,
        "contact_email": base_summary.and_then(|value| value["contact_email"].as_str()),
        "operator_booking_reference": base_summary
            .and_then(|value| value["operator_booking_reference"].as_str()),
        "payment_authorization_reference": base_summary
            .and_then(|value| value["payment_authorization_reference"].as_str()),
        "ticket_ids": base_summary
            .and_then(|value| value["ticket_ids"].as_array().cloned())
            .unwrap_or_default(),
        "operator_ticket_references": base_summary
            .and_then(|value| value["operator_ticket_references"].as_array().cloned())
            .unwrap_or_default(),
        "open_request_kinds": open_request_kinds,
        "needs_attention": true,
        "latest_activity_at": latest_activity_at,
    }))
}

fn coach_admin_risk_support_timeline_event_payload(risk: &Value) -> Value {
    let occurred_at = risk["sla_due_at"]
        .as_str()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| {
            risk["detected_at"]
                .as_str()
                .filter(|value| !value.trim().is_empty())
        })
        .map(str::to_string)
        .unwrap_or_else(now_rfc3339);
    let mut detail_lines = vec![
        format!("Risk {}", risk["risk_id"].as_str().unwrap_or("risk")),
        risk["title"]
            .as_str()
            .unwrap_or("Overdue operational risk")
            .to_string(),
    ];
    if let Some(reason) = risk["routing_reason"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        detail_lines.push(reason.to_string());
    }
    if let Some(task) = risk["follow_up_task_detail"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        detail_lines.push(format!("Follow-up: {task}"));
    }
    coach_support_timeline_event_payload(
        risk["auto_case_id"].as_str().unwrap_or("risk_follow_up"),
        "risk_follow_up_auto_case",
        "Risk follow-up auto-case created",
        &occurred_at,
        risk["sla_status"].as_str().unwrap_or("overdue"),
        detail_lines,
    )
}

async fn coach_admin_risk_support_case_detail_payload(
    state: &AppState,
    risk: &Value,
    replay_index: &CoachMutationReplayIndex,
    review_map: &CoachOpsReviewMap,
    event_map: &CoachBoardingEventMap,
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> Result<Value, sqlx::Error> {
    let booking_id = risk["booking_id"]
        .as_str()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let base_detail = if let Some(booking_id) = booking_id {
        let aggregates = coach_list_booking_aggregates_global_for_request(state).await?;
        let runtime_trip_groups = coach_runtime_trip_groups_for_request(state, aggregates).await?;
        if let Some((trip_id, trip_aggregates, aggregate)) =
            coach_find_runtime_trip_group_matching_aggregate(&runtime_trip_groups, |candidate| {
                candidate.booking.get("booking_id").and_then(Value::as_str) == Some(booking_id)
            })
        {
            let operator_id = coach_runtime_trip_group_operator_id(trip_aggregates, trip_id);
            let journey = coach_runtime_trip_group_journey_payload(trip_aggregates, trip_id);
            Some(
                coach_support_case_detail_payload_from_aggregate(&CoachSupportCaseDetailContext {
                    state,
                    aggregate,
                    trip_id,
                    journey: &journey,
                    operator_id: &operator_id,
                    replay_index,
                    review_map,
                    event_map,
                    feed_health,
                })
                .await?,
            )
        } else {
            coach_demo_booking_seed(booking_id).map(|seed| {
                coach_support_case_detail_payload_from_seed(
                    &seed,
                    review_map,
                    event_map,
                    feed_health,
                )
            })
        }
    } else {
        None
    };

    let support_case = coach_admin_risk_support_case_summary_payload(
        risk,
        base_detail.as_ref().map(|value| &value["support_case"]),
    )
    .unwrap_or_else(|| {
        let fallback_detected_at = risk["detected_at"]
            .as_str()
            .map(str::to_string)
            .unwrap_or_else(now_rfc3339);
        json!({
            "case_id": risk["auto_case_id"].as_str().unwrap_or_default(),
            "booking_id": risk["auto_case_id"].as_str().unwrap_or_default(),
            "journey_id": coach_scoped_resource_id("journey", risk["risk_id"].as_str().unwrap_or_default()),
            "operator_name": risk["operator_name"].as_str().unwrap_or("Coach support"),
            "from": "Risk",
            "to": "Follow-up",
            "departure_at": fallback_detected_at.clone(),
            "arrival_at": fallback_detected_at,
            "booking_state": coach_admin_risk_booking_state_wire(risk),
            "case_status": "risk_follow_up",
            "priority": coach_admin_risk_support_case_priority(risk["severity"].as_str().unwrap_or_default()),
            "passenger_display_name": "Risk follow-up",
            "passenger_count": 1,
            "contact_email": Value::Null,
            "operator_booking_reference": Value::Null,
            "payment_authorization_reference": Value::Null,
            "ticket_ids": [],
            "operator_ticket_references": [],
            "open_request_kinds": ["risk_follow_up"],
            "needs_attention": true,
            "latest_activity_at": risk["detected_at"].as_str().map(str::to_string).unwrap_or_else(now_rfc3339),
        })
    });

    let auto_timeline_event = coach_admin_risk_support_timeline_event_payload(risk);
    if let Some(mut detail) = base_detail {
        let mut timeline = detail["timeline"].as_array().cloned().unwrap_or_default();
        timeline.push(auto_timeline_event);
        detail["generated_at"] = Value::String(now_rfc3339());
        detail["support_case"] = support_case;
        detail["timeline"] = Value::Array(coach_sort_support_timeline_events(timeline));
        return Ok(detail);
    }

    let case_id = support_case["case_id"].as_str().unwrap_or("risk_follow_up");
    let booking_id = support_case["booking_id"].as_str().unwrap_or(case_id);
    let journey_id = support_case["journey_id"]
        .as_str()
        .unwrap_or("journey_risk_follow_up");
    let operator_name = support_case["operator_name"]
        .as_str()
        .unwrap_or("Coach support");
    let from = support_case["from"].as_str().unwrap_or("Risk");
    let to = support_case["to"].as_str().unwrap_or("Follow-up");
    let departure_at = support_case["departure_at"]
        .as_str()
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string)
        .unwrap_or_else(now_rfc3339);
    let arrival_at = support_case["arrival_at"]
        .as_str()
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| departure_at.clone());
    let offer_id = coach_scoped_resource_id("offer", case_id);
    Ok(json!({
        "generated_at": now_rfc3339(),
        "support_case": support_case,
        "journey": coach_booked_journey_summary_payload(
            journey_id,
            operator_name,
            from,
            to,
            &departure_at,
            &arrival_at,
            risk["title"].as_str().unwrap_or("Risk follow-up"),
        ),
        "offer": coach_offer_payload(&offer_id, 1),
        "hold": Value::Null,
        "booking": coach_booking_payload_for_offer(
            booking_id,
            &offer_id,
            None,
            1,
            coach_admin_risk_booking_state_wire(risk),
        ),
        "payment": Value::Null,
        "compensation": Value::Null,
        "passengers_manifest": [],
        "tickets": [],
        "ticket_artifacts": [],
        "refund_request": Value::Null,
        "change_request": Value::Null,
        "recent_boarding_events": [],
        "operator_feed_health": [],
        "timeline": [auto_timeline_event],
    }))
}

