fn coach_booking_total_minor_units(aggregate: &CoachStoredBookingAggregate) -> i64 {
    coach_booking_offer_payload_from_aggregate(aggregate)
        .get("total_minor_units")
        .and_then(Value::as_i64)
        .or_else(|| {
            aggregate
                .booking
                .get("total_minor_units")
                .and_then(Value::as_i64)
        })
        .unwrap_or_default()
}

fn coach_refund_credit_expiry_iso() -> String {
    (chrono::DateTime::<chrono::Utc>::from(SystemTime::now()) + chrono::Duration::days(365))
        .to_rfc3339()
}

fn coach_refund_eligibility_payload_from_aggregate(
    aggregate: &CoachStoredBookingAggregate,
) -> Value {
    let booking_id = aggregate
        .booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let booking_state = aggregate
        .booking
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("booking_pending");
    let offer_payload = coach_booking_offer_payload_from_aggregate(aggregate);
    let currency = offer_payload
        .get("currency")
        .and_then(Value::as_str)
        .unwrap_or("EUR");
    let total_minor_units = coach_booking_total_minor_units(aggregate);
    let original_payment_fee_minor_units = coach_shamell_pay_fee_minor_units(total_minor_units);
    let original_payment_minor_units =
        (total_minor_units - original_payment_fee_minor_units).max(0);
    let refundable = offer_payload
        .get("refundable")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        && matches!(
            booking_state,
            "ticketed" | "partially_ticketed" | "refund_requested"
        )
        && !aggregate.tickets.is_empty();
    let reason = if refundable {
        Value::Null
    } else if aggregate.tickets.is_empty() {
        Value::String("tickets must be issued before a self-service refund".to_string())
    } else if !matches!(
        booking_state,
        "ticketed" | "partially_ticketed" | "refund_requested"
    ) {
        Value::String("booking is not eligible for self-service refunds".to_string())
    } else {
        Value::String("fare is not eligible for self-service refunds".to_string())
    };
    let refund_cutoff_at = coach_booking_journey_payload_from_aggregate(aggregate)
        .get("departure_at")
        .cloned()
        .unwrap_or(Value::Null);
    let options = if refundable {
        vec![
            json!({
                "kind": "refund_credit",
                "label": "Travel credit",
                "currency": currency,
                "refund_minor_units": total_minor_units,
                "fee_minor_units": 0,
                "expires_at": coach_refund_credit_expiry_iso(),
            }),
            json!({
                "kind": "original_payment",
                "label": "Original payment",
                "currency": currency,
                "refund_minor_units": original_payment_minor_units,
                "fee_minor_units": original_payment_fee_minor_units,
                "expires_at": Value::Null,
            }),
        ]
    } else {
        Vec::new()
    };
    json!({
        "booking_id": booking_id,
        "booking_state": booking_state,
        "refundable": refundable,
        "currency": currency,
        "reason": reason,
        "refund_cutoff_at": refund_cutoff_at,
        "recommended_kind": if refundable { Value::String("refund_credit".to_string()) } else { Value::Null },
        "tickets_void_required": !aggregate.tickets.is_empty(),
        "options": options,
    })
}

fn coach_shifted_rfc3339(raw: &str, hours: i64) -> Option<String> {
    chrono::DateTime::parse_from_rfc3339(raw.trim())
        .ok()
        .map(|value| (value + chrono::Duration::hours(hours)).to_rfc3339())
}

fn coach_change_options_from_aggregate(aggregate: &CoachStoredBookingAggregate) -> Vec<Value> {
    let booking_id = aggregate
        .booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if let Some(seed) = coach_demo_booking_seed(booking_id) {
        return coach_change_options_for_seed(&seed);
    }

    let booking_state = aggregate
        .booking
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("booking_pending");
    let offer_payload = coach_booking_offer_payload_from_aggregate(aggregate);
    let changeable = offer_payload
        .get("changeable")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        && matches!(booking_state, "ticketed" | "partially_ticketed");
    if !changeable {
        return Vec::new();
    }

    let journey = coach_booking_journey_payload_from_aggregate(aggregate);
    let departure_at = journey.get("departure_at").and_then(Value::as_str);
    let arrival_at = journey.get("arrival_at").and_then(Value::as_str);
    let base_departure = departure_at
        .and_then(|value| coach_shifted_rfc3339(value, 4))
        .unwrap_or_else(|| coach_future_expiry_iso(4 * 3600));
    let base_arrival = arrival_at
        .and_then(|value| coach_shifted_rfc3339(value, 4))
        .unwrap_or_else(|| coach_future_expiry_iso(8 * 3600));
    let later_departure = departure_at
        .and_then(|value| coach_shifted_rfc3339(value, 24))
        .unwrap_or_else(|| coach_future_expiry_iso(24 * 3600));
    let later_arrival = arrival_at
        .and_then(|value| coach_shifted_rfc3339(value, 24))
        .unwrap_or_else(|| coach_future_expiry_iso(28 * 3600));

    vec![
        coach_change_option_payload(
            &coach_scoped_resource_id("offer", &format!("{booking_id}|change|1")),
            &coach_scoped_resource_id("journey", &format!("{booking_id}|change|1")),
            &base_departure,
            &base_arrival,
            800,
            500,
            1_300,
        ),
        coach_change_option_payload(
            &coach_scoped_resource_id("offer", &format!("{booking_id}|change|2")),
            &coach_scoped_resource_id("journey", &format!("{booking_id}|change|2")),
            &later_departure,
            &later_arrival,
            -300,
            250,
            0,
        ),
    ]
}

fn coach_change_eligibility_payload_from_aggregate(
    aggregate: &CoachStoredBookingAggregate,
) -> Value {
    let booking_id = aggregate
        .booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let booking_state = aggregate
        .booking
        .get("state")
        .and_then(Value::as_str)
        .unwrap_or("booking_pending");
    let options = coach_change_options_from_aggregate(aggregate);
    let changeable = !options.is_empty();
    json!({
        "booking_id": booking_id,
        "booking_state": booking_state,
        "changeable": changeable,
        "reason": if changeable {
            Value::Null
        } else {
            Value::String("self-service rebooking is unavailable for this booking".to_string())
        },
        "change_cutoff_at": if changeable {
            coach_booking_journey_payload_from_aggregate(aggregate)
                .get("departure_at")
                .cloned()
                .unwrap_or(Value::Null)
        } else {
            Value::Null
        },
        "options": options,
    })
}

