fn coach_refund_request_response_from_aggregate(
    aggregate: &CoachStoredBookingAggregate,
    idempotency_key: &str,
    request_fingerprint: &str,
    refund_kind: &str,
    ticket_ids: &[String],
    reason: Option<&str>,
) -> Value {
    let refund_eligibility = coach_refund_eligibility_payload_from_aggregate(aggregate);
    let requested_minor_units = refund_eligibility
        .get("options")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .find(|option| option.get("kind").and_then(Value::as_str) == Some(refund_kind))
        .and_then(|option| option.get("refund_minor_units").and_then(Value::as_i64))
        .unwrap_or_default();
    let fee_minor_units = refund_eligibility
        .get("options")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .find(|option| option.get("kind").and_then(Value::as_str) == Some(refund_kind))
        .and_then(|option| option.get("fee_minor_units").and_then(Value::as_i64))
        .unwrap_or_default();
    let booking = coach_booking_payload_with_state(&aggregate.booking, "refund_requested");
    json!({
        "command": "refund_request",
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            "coach_refund_request",
            request_fingerprint,
            &[
                (
                    "refund_authorize",
                    derived_internal_idempotency_key(idempotency_key, "coach_refund_authorize"),
                ),
                (
                    "ledger_posting",
                    derived_internal_idempotency_key(idempotency_key, "coach_refund_ledger_posting"),
                ),
            ],
        ),
        "booking": booking,
        "refund_request": coach_refund_request_payload(
            booking.get("booking_id").and_then(Value::as_str).unwrap_or_default(),
            refund_kind,
            ticket_ids,
            reason,
            requested_minor_units,
            fee_minor_units,
        ),
        "compensation": coach_compensation_payload(
            "armed",
            "issue_refund_credit_or_raise_finance_case",
            "coach_refund_queue",
            false,
            None,
            None,
        ),
        "next_action": "await_refund_review",
    })
}

fn coach_rebook_request_response_from_aggregate(
    aggregate: &CoachStoredBookingAggregate,
    idempotency_key: &str,
    request_fingerprint: &str,
    target_offer_id: &str,
    reason: Option<&str>,
) -> ApiResult<Value> {
    let Some(option) = coach_change_options_from_aggregate(aggregate)
        .into_iter()
        .find(|option| option["target_offer_id"].as_str() == Some(target_offer_id))
    else {
        return Err(ApiError::bad_request(
            "target_offer_id is not available for this booking",
        ));
    };
    let fare_difference_minor_units = option["fare_difference_minor_units"]
        .as_i64()
        .unwrap_or_default();
    let change_fee_minor_units = option["change_fee_minor_units"]
        .as_i64()
        .unwrap_or_default();
    let total_due_minor_units = option["total_due_minor_units"].as_i64().unwrap_or_default();
    Ok(json!({
        "command": "rebook_request",
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            "coach_rebook_request",
            request_fingerprint,
            &[
                (
                    "change_authorize",
                    derived_internal_idempotency_key(idempotency_key, "coach_change_authorize"),
                ),
                (
                    "reissue_tickets",
                    derived_internal_idempotency_key(idempotency_key, "coach_reissue_tickets"),
                ),
            ],
        ),
        "booking": aggregate.booking.clone(),
        "change_request": coach_change_request_payload(
            aggregate
                .booking
                .get("booking_id")
                .and_then(Value::as_str)
                .unwrap_or_default(),
            target_offer_id,
            fare_difference_minor_units,
            change_fee_minor_units,
            total_due_minor_units,
            reason,
        ),
        "compensation": coach_compensation_payload(
            "armed",
            "reissue_tickets_or_raise_support_case",
            "coach_rebook_queue",
            false,
            None,
            None,
        ),
        "next_action": "await_reissue",
    }))
}

fn coach_demo_ticket_ids(seed: &CoachDemoBookingSeed) -> Vec<String> {
    coach_demo_booking_tickets_payload(seed)
        .iter()
        .filter_map(|ticket| {
            ticket
                .get("ticket_id")
                .and_then(Value::as_str)
                .map(|value| value.to_string())
        })
        .collect::<Vec<_>>()
}

fn coach_demo_refund_queue_entries_payload(review_map: &CoachOpsReviewMap) -> Vec<Value> {
    let refund_requests = vec![
        (
            coach_demo_booking_seed("booking_demo_express_direct")
                .expect("demo express refund queue seed available"),
            "refund_credit",
            Some("customer changed plans"),
            "2026-04-07T13:00:00Z",
            "Travel credit can be approved immediately.",
        ),
        (
            coach_demo_booking_seed("booking_demo_border_runner")
                .expect("border runner refund queue seed available"),
            "original_payment",
            Some("service was cancelled by operator"),
            "2026-04-07T13:20:00Z",
            "Verify cancellation evidence before cash refund.",
        ),
    ];
    refund_requests
        .into_iter()
        .map(
            |(seed, refund_kind, reason, created_at, pending_suggested_action)| {
                let ticket_ids = coach_demo_ticket_ids(&seed);
                let base_request = coach_refund_request_payload(
                    seed.booking_id,
                    refund_kind,
                    ticket_ids.as_slice(),
                    reason,
                    if refund_kind == "refund_credit" {
                        seed.refund_credit_minor_units
                    } else {
                        seed.original_payment_minor_units
                    },
                    if refund_kind == "refund_credit" {
                        0
                    } else {
                        seed.original_payment_fee_minor_units
                    },
                );
                let refund_request_id = base_request["refund_request_id"]
                    .as_str()
                    .unwrap_or_default()
                    .to_string();
                let review = review_map.get(refund_request_id.as_str());
                let queue_status = review
                    .map(|value| value.queue_status.as_str())
                    .unwrap_or("pending_review");
                let request_status = coach_operator_request_status_from_queue_status(queue_status);
                let suggested_action =
                    coach_operator_refund_suggested_action(queue_status, pending_suggested_action);
                json!({
                    "refund_request_id": refund_request_id,
                    "booking_id": seed.booking_id,
                    "journey_id": seed.journey_id,
                    "operator_name": seed.operator_name,
                    "from": seed.from,
                    "to": seed.to,
                    "departure_at": seed.departure_at,
                    "arrival_at": seed.arrival_at,
                    "booking_state": seed.booking_state,
                    "request_status": request_status,
                    "selected_kind": refund_kind,
                    "currency": "EUR",
                    "requested_minor_units": if refund_kind == "refund_credit" {
                        seed.refund_credit_minor_units
                    } else {
                        seed.original_payment_minor_units
                    },
                    "fee_minor_units": if refund_kind == "refund_credit" {
                        0
                    } else {
                        seed.original_payment_fee_minor_units
                    },
                    "ticket_ids": ticket_ids,
                    "reason": reason,
                    "requested_at": created_at,
                    "queue_status": queue_status,
                    "urgency": if refund_kind == "original_payment" { "high" } else { "medium" },
                    "suggested_action": suggested_action,
                    "reviewed_at": review.map(|value| value.reviewed_at.clone()),
                    "reviewed_by_account_id": review.map(|value| value.reviewed_by_account_id.clone()),
                    "review_note": review.and_then(|value| value.review_note.clone()),
                })
            },
        )
        .collect::<Vec<_>>()
}

fn coach_demo_change_queue_entries_payload(review_map: &CoachOpsReviewMap) -> Vec<Value> {
    let change_requests = vec![
        (
            coach_demo_booking_seed("booking_demo_express_direct")
                .expect("demo express change queue seed available"),
            "offer_demo_express_midday",
            Some("move to midday departure"),
            "2026-04-07T13:05:00Z",
            "Collect the fare difference before reissuing tickets.",
        ),
        (
            coach_demo_booking_seed("booking_demo_border_runner")
                .expect("border runner change queue seed available"),
            "offer_demo_border_runner_later",
            Some("reaccommodate after operator delay"),
            "2026-04-07T13:25:00Z",
            "This reaccommodation can be approved without extra collection.",
        ),
    ];
    change_requests
        .into_iter()
        .filter_map(
            |(seed, target_offer_id, reason, created_at, pending_suggested_action)| {
                let option = coach_change_options_for_seed(&seed)
                    .into_iter()
                    .find(|value| value["target_offer_id"].as_str() == Some(target_offer_id))?;
                let change_request = coach_change_request_payload(
                    seed.booking_id,
                    target_offer_id,
                    option["fare_difference_minor_units"]
                        .as_i64()
                        .unwrap_or_default(),
                    option["change_fee_minor_units"].as_i64().unwrap_or_default(),
                    option["total_due_minor_units"].as_i64().unwrap_or_default(),
                    reason,
                );
                let change_request_id = change_request["change_request_id"]
                    .as_str()
                    .unwrap_or_default()
                    .to_string();
                let review = review_map.get(change_request_id.as_str());
                let queue_status = review
                    .map(|value| value.queue_status.as_str())
                    .unwrap_or("pending_review");
                let request_status = coach_operator_request_status_from_queue_status(queue_status);
                let total_due_minor_units = option["total_due_minor_units"].as_i64().unwrap_or_default();
                let suggested_action = coach_operator_change_suggested_action(
                    queue_status,
                    total_due_minor_units,
                    pending_suggested_action,
                );
                Some(json!({
                    "change_request_id": change_request_id,
                    "booking_id": seed.booking_id,
                    "journey_id": seed.journey_id,
                    "operator_name": seed.operator_name,
                    "from": seed.from,
                    "to": seed.to,
                    "departure_at": seed.departure_at,
                    "arrival_at": seed.arrival_at,
                    "booking_state": seed.booking_state,
                    "request_status": request_status,
                    "target_offer_id": target_offer_id,
                    "target_journey_id": option["journey_id"].as_str().unwrap_or_default(),
                    "currency": "EUR",
                    "fare_difference_minor_units": option["fare_difference_minor_units"]
                        .as_i64()
                        .unwrap_or_default(),
                    "change_fee_minor_units": option["change_fee_minor_units"].as_i64().unwrap_or_default(),
                    "total_due_minor_units": total_due_minor_units,
                    "reason": reason,
                    "requested_at": created_at,
                    "queue_status": queue_status,
                    "urgency": if total_due_minor_units > 0 { "high" } else { "medium" },
                    "suggested_action": suggested_action,
                    "reviewed_at": review.map(|value| value.reviewed_at.clone()),
                    "reviewed_by_account_id": review.map(|value| value.reviewed_by_account_id.clone()),
                    "review_note": review.and_then(|value| value.review_note.clone()),
                }))
            },
        )
        .collect::<Vec<_>>()
}

fn coach_operator_refund_queue_payload(limit: usize, review_map: &CoachOpsReviewMap) -> Value {
    let requests = coach_demo_refund_queue_entries_payload(review_map);
    let open_requests = requests.len() as i64;
    let pending_review = requests
        .iter()
        .filter(|item| item["queue_status"].as_str() == Some("pending_review"))
        .count() as i64;
    let approved = requests
        .iter()
        .filter(|item| item["queue_status"].as_str() == Some("approved"))
        .count() as i64;
    let rejected = requests
        .iter()
        .filter(|item| item["queue_status"].as_str() == Some("rejected"))
        .count() as i64;
    let credit_requests = requests
        .iter()
        .filter(|item| item["selected_kind"].as_str() == Some("refund_credit"))
        .count() as i64;
    let cash_requests = requests
        .iter()
        .filter(|item| item["selected_kind"].as_str() == Some("original_payment"))
        .count() as i64;
    json!({
        "generated_at": now_rfc3339(),
        "totals": {
            "open_requests": open_requests,
            "pending_review": pending_review,
            "approved": approved,
            "rejected": rejected,
            "credit_requests": credit_requests,
            "cash_requests": cash_requests,
        },
        "requests": requests.into_iter().take(limit).collect::<Vec<_>>(),
    })
}

fn coach_operator_change_queue_payload(limit: usize, review_map: &CoachOpsReviewMap) -> Value {
    let requests = coach_demo_change_queue_entries_payload(review_map);
    let open_requests = requests.len() as i64;
    let pending_review = requests
        .iter()
        .filter(|item| item["queue_status"].as_str() == Some("pending_review"))
        .count() as i64;
    let approved = requests
        .iter()
        .filter(|item| item["queue_status"].as_str() == Some("approved"))
        .count() as i64;
    let rejected = requests
        .iter()
        .filter(|item| item["queue_status"].as_str() == Some("rejected"))
        .count() as i64;
    let payment_failed = requests
        .iter()
        .filter(|item| item["queue_status"].as_str() == Some("payment_failed"))
        .count() as i64;
    let collection_required_requests = requests
        .iter()
        .filter(|item| item["total_due_minor_units"].as_i64().unwrap_or_default() > 0)
        .count() as i64;
    let zero_due_requests = requests
        .iter()
        .filter(|item| item["total_due_minor_units"].as_i64().unwrap_or_default() == 0)
        .count() as i64;
    json!({
        "generated_at": now_rfc3339(),
        "totals": {
            "open_requests": open_requests,
            "pending_review": pending_review,
            "approved": approved,
            "rejected": rejected,
            "payment_failed": payment_failed,
            "collection_required_requests": collection_required_requests,
            "zero_due_requests": zero_due_requests,
        },
        "requests": requests.into_iter().take(limit).collect::<Vec<_>>(),
    })
}

