fn coach_operator_settlement_effect_payload(
    kind: &str,
    currency: &str,
    amount_minor_units: i64,
) -> Value {
    json!({
        "kind": kind,
        "currency": currency,
        "amount_minor_units": amount_minor_units,
    })
}

fn coach_operator_refund_settlement_effect(request: &Value) -> Option<Value> {
    let queue_status = request["queue_status"].as_str().unwrap_or_default();
    let selected_kind = request["selected_kind"].as_str().unwrap_or_default();
    if queue_status != "approved" {
        return None;
    }
    Some(coach_operator_settlement_effect_payload(
        if selected_kind == "original_payment" {
            "operator_payable_deduction"
        } else {
            "travel_credit_liability"
        },
        request["currency"].as_str().unwrap_or("EUR"),
        request["requested_minor_units"]
            .as_i64()
            .unwrap_or_default(),
    ))
}

fn coach_operator_refund_next_action(queue_status: &str) -> &'static str {
    if queue_status == "approved" {
        "customer_notification_queued"
    } else {
        "support_follow_up_required"
    }
}

fn coach_operator_change_settlement_effect(request: &Value) -> Option<Value> {
    let queue_status = request["queue_status"].as_str().unwrap_or_default();
    let total_due_minor_units = request["total_due_minor_units"]
        .as_i64()
        .unwrap_or_default();
    if queue_status == "approved" && total_due_minor_units > 0 {
        return Some(coach_operator_settlement_effect_payload(
            "customer_collection_required",
            request["currency"].as_str().unwrap_or("EUR"),
            total_due_minor_units,
        ));
    }
    None
}

fn coach_operator_change_next_action(
    queue_status: &str,
    total_due_minor_units: i64,
) -> &'static str {
    if queue_status == "payment_failed" {
        "resolve_payment_failure"
    } else if queue_status == "approved" && total_due_minor_units > 0 {
        "customer_payment_collection_queued"
    } else if queue_status == "approved" {
        "ticket_reissue_queued"
    } else {
        "keep_original_booking"
    }
}

fn coach_operator_refund_review_response(
    idempotency_key: &str,
    request_fingerprint: &str,
    request: Value,
) -> Value {
    let queue_status = request["queue_status"].as_str().unwrap_or_default();
    let settlement_effect = coach_operator_refund_settlement_effect(&request);
    json!({
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            "coach_operator_refund_review",
            request_fingerprint,
            &[],
        ),
        "request": request,
        "settlement_effect": settlement_effect,
        "next_action": coach_operator_refund_next_action(queue_status),
    })
}

fn coach_operator_change_review_response(
    idempotency_key: &str,
    request_fingerprint: &str,
    request: Value,
) -> Value {
    let queue_status = request["queue_status"].as_str().unwrap_or_default();
    let total_due_minor_units = request["total_due_minor_units"]
        .as_i64()
        .unwrap_or_default();
    let settlement_effect = coach_operator_change_settlement_effect(&request);
    json!({
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            "coach_operator_change_review",
            request_fingerprint,
            &[],
        ),
        "request": request,
        "settlement_effect": settlement_effect,
        "next_action": coach_operator_change_next_action(queue_status, total_due_minor_units),
    })
}

fn coach_operator_reconciliation_trip_snapshot_payload(
    crew_trip_seed: &CoachDemoCrewTripSeed,
    booking_seed: &CoachDemoBookingSeed,
    event_map: &CoachBoardingEventMap,
) -> Value {
    let manifest =
        coach_demo_crew_manifest_entries_payload(booking_seed, crew_trip_seed.trip_id, event_map);
    let pending_ticket_ids = manifest
        .iter()
        .filter(|entry| entry["boarding_state"].as_str() == Some("not_boarded"))
        .filter_map(|entry| {
            entry["ticket"]["ticket_id"]
                .as_str()
                .map(|value| value.to_string())
        })
        .collect::<Vec<_>>();
    let needs_attention_count = manifest
        .iter()
        .filter(|entry| entry["needs_attention"].as_bool().unwrap_or(false))
        .count() as i64;
    json!({
        "trip": coach_demo_crew_trip_payload(crew_trip_seed, booking_seed, event_map),
        "recent_events": coach_recent_boarding_events_payload(crew_trip_seed.trip_id, event_map)
            .into_iter()
            .take(5)
            .collect::<Vec<_>>(),
        "pending_ticket_ids": pending_ticket_ids,
        "needs_attention_count": needs_attention_count,
    })
}

