fn coach_filter_operator_request_entries_by_scope_and_booking_ids(
    requests: Vec<Value>,
    allowed_operator_ids: &HashSet<String>,
    booking_ids: Option<&HashSet<String>>,
) -> Vec<Value> {
    requests
        .into_iter()
        .filter(|request| {
            let Some(booking_id) = request
                .get("booking_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            else {
                return false;
            };
            if let Some(booking_ids) = booking_ids {
                if !booking_ids.contains(booking_id) {
                    return false;
                }
            }
            let Some(seed) = coach_demo_booking_seed(booking_id) else {
                return false;
            };
            coach_operator_scope_allows_demo_booking_seed(&seed, allowed_operator_ids)
        })
        .collect::<Vec<_>>()
}

fn coach_operator_review_history_payload_from_requests(
    limit: usize,
    refund_requests: &[Value],
    change_requests: &[Value],
) -> Vec<Value> {
    let mut history = refund_requests
        .iter()
        .filter_map(coach_operator_refund_history_entry_payload)
        .chain(
            change_requests
                .iter()
                .filter_map(coach_operator_change_history_entry_payload),
        )
        .collect::<Vec<_>>();
    coach_sort_operator_review_history_entries(&mut history);
    history.into_iter().take(limit).collect::<Vec<_>>()
}

fn coach_sort_operator_review_history_entries(history: &mut [Value]) {
    history.sort_by(|left, right| {
        right["reviewed_at"]
            .as_str()
            .unwrap_or_default()
            .cmp(left["reviewed_at"].as_str().unwrap_or_default())
            .then_with(|| {
                right["request_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(left["request_id"].as_str().unwrap_or_default())
            })
            .then_with(|| {
                right["request_kind"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(left["request_kind"].as_str().unwrap_or_default())
            })
    });
}

fn coach_runtime_operator_name_from_aggregate(aggregate: &CoachStoredBookingAggregate) -> String {
    aggregate
        .journey
        .as_ref()
        .and_then(|payload| payload.get("operator_name"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| {
            coach_operator_id_from_booking_aggregate(aggregate)
                .and_then(|operator_id| coach_operator_display_name_from_id(&operator_id))
        })
        .unwrap_or_else(|| "Coach service".to_string())
}

fn coach_runtime_booking_gross_minor_units(aggregate: &CoachStoredBookingAggregate) -> i64 {
    aggregate
        .booking
        .get("total_minor_units")
        .and_then(Value::as_i64)
        .or_else(|| {
            aggregate
                .offer
                .as_ref()
                .and_then(|payload| payload.get("total_minor_units"))
                .and_then(Value::as_i64)
        })
        .unwrap_or_default()
        .max(0)
}

fn coach_runtime_booking_commission_minor_units(gross_minor_units: i64) -> i64 {
    coach_shamell_pay_fee_minor_units(gross_minor_units)
}

fn coach_runtime_booking_chargeback_reserve_minor_units(gross_minor_units: i64) -> i64 {
    if gross_minor_units <= 0 {
        return 0;
    }
    ((gross_minor_units * 2 + 50) / 100).max(100)
}

fn coach_runtime_booking_settlement_basis(
    aggregate: &CoachStoredBookingAggregate,
    trip_id: &str,
    event_map: &CoachBoardingEventMap,
) -> &'static str {
    if aggregate.tickets.iter().any(|ticket| {
        let ticket_id = ticket
            .get("ticket_id")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let event = event_map.get(&coach_boarding_event_store_key(trip_id, ticket_id));
        coach_boarding_state_from_ticket_or_event(ticket, event) == "boarded"
    }) {
        "boarded"
    } else {
        "ticketed"
    }
}

fn coach_operator_reconciliation_trip_snapshot_payload_from_runtime_aggregates(
    aggregates: &[CoachStoredBookingAggregate],
    trip_id: &str,
    event_map: &CoachBoardingEventMap,
) -> Value {
    let mut trip = coach_runtime_crew_trip_payload(aggregates, trip_id, event_map);
    if aggregates.len() > 1 {
        if let Some(object) = trip.as_object_mut() {
            object.insert("booking_id".to_string(), Value::Null);
        }
    }
    let manifest = coach_runtime_crew_manifest_entries_payload(aggregates, trip_id, event_map);
    let pending_ticket_ids = manifest
        .iter()
        .filter(|entry| entry["boarding_state"].as_str() == Some("not_boarded"))
        .filter_map(|entry| {
            entry["ticket"]["ticket_id"]
                .as_str()
                .map(|value| value.to_string())
        })
        .collect::<Vec<_>>();
    let needs_attention_count = manifest
        .iter()
        .filter(|entry| entry["needs_attention"].as_bool().unwrap_or(false))
        .count() as i64;
    json!({
        "trip": trip,
        "recent_events": coach_recent_boarding_events_payload(trip_id, event_map)
            .into_iter()
            .take(5)
            .collect::<Vec<_>>(),
        "pending_ticket_ids": pending_ticket_ids,
        "needs_attention_count": needs_attention_count,
    })
}

fn coach_runtime_settlement_line_payload(
    settlement_id: &str,
    operator_id: &str,
    aggregate: &CoachStoredBookingAggregate,
    trip_id: &str,
    review_map: &CoachOpsReviewMap,
    event_map: &CoachBoardingEventMap,
) -> Value {
    let booking_id = aggregate
        .booking
        .get("booking_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let gross_minor_units = coach_runtime_booking_gross_minor_units(aggregate);
    let commission_minor_units = coach_runtime_booking_commission_minor_units(gross_minor_units);
    let refund_minor_units = coach_operator_booking_refund_minor_units(booking_id, review_map);
    let chargeback_reserve_minor_units =
        coach_runtime_booking_chargeback_reserve_minor_units(gross_minor_units);
    let manual_adjustment_minor_units =
        coach_operator_booking_manual_adjustment_minor_units(booking_id, review_map);
    let net_payable_minor_units = gross_minor_units
        - commission_minor_units
        - refund_minor_units
        - chargeback_reserve_minor_units
        + manual_adjustment_minor_units;
    json!({
        "settlement_id": settlement_id,
        "operator_id": operator_id,
        "booking_id": booking_id,
        "basis": coach_runtime_booking_settlement_basis(aggregate, trip_id, event_map),
        "currency": aggregate
            .booking
            .get("currency")
            .and_then(Value::as_str)
            .or_else(|| aggregate.offer.as_ref().and_then(|payload| payload.get("currency")).and_then(Value::as_str))
            .unwrap_or("EUR"),
        "gross_minor_units": gross_minor_units,
        "commission_minor_units": commission_minor_units,
        "refund_minor_units": refund_minor_units,
        "chargeback_reserve_minor_units": chargeback_reserve_minor_units,
        "manual_adjustment_minor_units": manual_adjustment_minor_units,
        "net_payable_minor_units": net_payable_minor_units,
    })
}

