fn coach_operator_settlement_statements_payload(
    limit: usize,
    _all_statements: &[Value],
    page_source_statements: &[Value],
) -> Value {
    let page = page_source_statements
        .iter()
        .take(limit)
        .collect::<Vec<_>>();
    let next_cursor = if page_source_statements.len() > limit {
        page.last()
            .and_then(|entry| encode_coach_settlement_statement_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "next_cursor": next_cursor,
        "statements": page.into_iter().cloned().collect::<Vec<_>>(),
    })
}

fn coach_filter_settlement_statements(
    statements: &[Value],
    cursor: Option<&CoachOperatorSettlementStatementCursor>,
) -> Vec<Value> {
    let mut filtered = statements
        .iter()
        .filter(|entry| {
            let Some(cursor) = cursor else {
                return true;
            };
            let Some(period_end_raw) = entry["period_end"].as_str() else {
                return false;
            };
            let Some(statement_id) = entry["statement_id"].as_str() else {
                return false;
            };
            let Ok(period_end) = chrono::DateTime::parse_from_rfc3339(period_end_raw.trim()) else {
                return false;
            };
            if period_end > cursor.period_end {
                return false;
            }
            if period_end == cursor.period_end && statement_id >= cursor.statement_id.as_str() {
                return false;
            }
            true
        })
        .cloned()
        .collect::<Vec<_>>();
    filtered.sort_by(|left, right| {
        right["period_end"]
            .as_str()
            .cmp(&left["period_end"].as_str())
            .then_with(|| {
                right["statement_id"]
                    .as_str()
                    .cmp(&left["statement_id"].as_str())
            })
    });
    filtered
}

fn coach_statement_values_by_id_from_values(values: Vec<Value>) -> HashMap<String, Value> {
    values
        .into_iter()
        .filter_map(|statement| {
            let statement_id = statement["statement_id"].as_str()?.to_string();
            Some((statement_id, statement))
        })
        .collect()
}

fn coach_operator_statement_values_by_id(
    review_map: &CoachOpsReviewMap,
    event_map: &CoachBoardingEventMap,
    payout_run_map: &CoachSettlementPayoutRunMap,
) -> HashMap<String, Value> {
    coach_statement_values_by_id_from_values(coach_operator_settlement_statement_values(
        review_map,
        event_map,
        payout_run_map,
    ))
}

fn coach_overlay_statement_values_by_id(
    mut statement_map: HashMap<String, Value>,
    overlay_values: Vec<Value>,
) -> HashMap<String, Value> {
    for (statement_id, statement) in coach_statement_values_by_id_from_values(overlay_values) {
        statement_map.insert(statement_id, statement);
    }
    statement_map
}

async fn coach_operator_statement_values_by_id_for_request(
    state: &AppState,
    principal_account_id: &str,
    review_map: &CoachOpsReviewMap,
    event_map: &CoachBoardingEventMap,
    payout_run_map: &CoachSettlementPayoutRunMap,
) -> Result<HashMap<String, Value>, sqlx::Error> {
    let statement_map =
        coach_operator_statement_values_by_id(review_map, event_map, payout_run_map);
    if let Some(runtime_statements) =
        coach_operator_runtime_settlement_statement_values_for_request(
            state,
            principal_account_id,
            review_map,
            event_map,
            payout_run_map,
        )
        .await?
    {
        Ok(coach_overlay_statement_values_by_id(
            statement_map,
            runtime_statements,
        ))
    } else {
        Ok(statement_map)
    }
}

fn coach_operator_payout_run_available_export_formats(
    entry: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
) -> Vec<String> {
    let mut formats = BTreeSet::new();
    for statement_id in &entry.statement_ids {
        let Some(statement) = statement_map.get(statement_id.as_str()) else {
            continue;
        };
        let Some(download_formats) = statement["download_formats"].as_array() else {
            continue;
        };
        for format in download_formats {
            let Some(value) = format
                .as_str()
                .map(str::trim)
                .filter(|value| !value.is_empty())
            else {
                continue;
            };
            formats.insert(value.to_string());
        }
    }
    formats.into_iter().collect()
}

fn coach_operator_payout_export_payload(entry: &CoachSettlementExportEntry) -> Value {
    json!({
        "export_id": entry.export_id.clone(),
        "payout_run_id": entry.payout_run_id.clone(),
        "export_format": entry.export_format.clone(),
        "status": entry.status.clone(),
        "file_name": entry.file_name.clone(),
        "mime_type": entry.mime_type.clone(),
        "download_path": entry.download_path.clone(),
        "checksum_sha256": entry.checksum_sha256.clone(),
        "content_length_bytes": entry.content_length_bytes,
        "created_at": entry.created_at.clone(),
        "created_by_account_id": entry.created_by_account_id.clone(),
        "statement_ids": entry.statement_ids.clone(),
        "operator_ids": entry.operator_ids.clone(),
        "note": entry.note.clone(),
    })
}

fn coach_operator_payout_run_export_values(
    payout_run_id: &str,
    export_map: &CoachSettlementExportMap,
) -> Vec<Value> {
    let mut exports = export_map
        .values()
        .filter(|entry| entry.payout_run_id == payout_run_id)
        .cloned()
        .collect::<Vec<_>>();
    exports.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| right.export_id.cmp(&left.export_id))
    });
    exports
        .into_iter()
        .map(|entry| coach_operator_payout_export_payload(&entry))
        .collect()
}

fn coach_settlement_export_entry_by_download_name(
    download_name: &str,
    export_map: &CoachSettlementExportMap,
) -> Option<CoachSettlementExportEntry> {
    export_map
        .values()
        .find(|entry| {
            entry
                .download_path
                .rsplit('/')
                .next()
                .map(|value| value == download_name)
                .unwrap_or(false)
        })
        .cloned()
}

