fn coach_operator_payout_run_payload(
    entry: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> Value {
    json!({
        "payout_run_id": entry.payout_run_id.clone(),
        "status": entry.status.clone(),
        "currency": entry.currency.clone(),
        "statement_ids": entry.statement_ids.clone(),
        "operator_ids": entry.operator_ids.clone(),
        "operator_names": entry.operator_names.clone(),
        "statement_count": entry.statement_count,
        "gross_minor_units": entry.gross_minor_units,
        "reserve_minor_units": entry.reserve_minor_units,
        "net_payable_minor_units": entry.net_payable_minor_units,
        "created_at": entry.created_at.clone(),
        "paid_at": entry.paid_at.clone(),
        "created_by_account_id": entry.created_by_account_id.clone(),
        "paid_by_account_id": entry.paid_by_account_id.clone(),
        "payment_reference": entry.payment_reference.clone(),
        "note": entry.note.clone(),
        "available_export_formats": coach_operator_payout_run_available_export_formats(
            entry,
            statement_map,
        ),
        "exports": coach_operator_payout_run_export_values(entry.payout_run_id.as_str(), export_map),
    })
}

fn coach_operator_payout_run_ready_export_formats(
    payout_run_id: &str,
    export_map: &CoachSettlementExportMap,
) -> Vec<String> {
    let mut formats = BTreeSet::new();
    for entry in export_map.values() {
        if entry.payout_run_id != payout_run_id || entry.status != "ready" {
            continue;
        }
        let value = entry.export_format.trim();
        if value.is_empty() {
            continue;
        }
        formats.insert(value.to_string());
    }
    formats.into_iter().collect()
}

fn coach_operator_payout_run_missing_export_formats(
    entry: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> Vec<String> {
    let ready_formats =
        coach_operator_payout_run_ready_export_formats(entry.payout_run_id.as_str(), export_map)
            .into_iter()
            .map(|value| value.trim().to_ascii_lowercase())
            .collect::<HashSet<_>>();
    coach_operator_payout_run_available_export_formats(entry, statement_map)
        .into_iter()
        .filter(|value| !ready_formats.contains(&value.trim().to_ascii_lowercase()))
        .collect()
}

fn coach_operator_payout_run_reconciliation_status(
    entry: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> &'static str {
    match entry.status.as_str() {
        "failed" => "payout_failed",
        "queued" => "awaiting_bank_execution",
        _ => {
            let payment_reference = entry
                .payment_reference
                .as_deref()
                .unwrap_or_default()
                .trim();
            let available_formats =
                coach_operator_payout_run_available_export_formats(entry, statement_map);
            let missing_formats =
                coach_operator_payout_run_missing_export_formats(entry, statement_map, export_map);
            if payment_reference.is_empty() {
                "missing_payment_reference"
            } else if !available_formats.is_empty()
                && missing_formats.len() == available_formats.len()
            {
                "missing_exports"
            } else if !missing_formats.is_empty() {
                "partial_exports"
            } else {
                "balanced"
            }
        }
    }
}

fn coach_operator_payout_run_attention_reasons(
    entry: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> Vec<String> {
    let missing_formats =
        coach_operator_payout_run_missing_export_formats(entry, statement_map, export_map);
    match coach_operator_payout_run_reconciliation_status(entry, statement_map, export_map) {
        "payout_failed" => vec!["Payout execution failed in the banking rail.".to_string()],
        "missing_payment_reference" => {
            vec!["Bank payment reference is missing for this paid run.".to_string()]
        }
        "missing_exports" => {
            vec!["No settlement export artifact has been generated yet.".to_string()]
        }
        "partial_exports" => vec![format!(
            "Missing export artifacts: {}.",
            missing_formats.join(", ")
        )],
        _ => Vec::new(),
    }
}

fn coach_operator_payout_run_next_action(
    entry: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> &'static str {
    match coach_operator_payout_run_reconciliation_status(entry, statement_map, export_map) {
        "payout_failed" => "Requeue the payout or escalate the failed bank transfer.",
        "awaiting_bank_execution" => {
            "Wait for Shamell Pay or bank execution to confirm the transfer."
        }
        "missing_payment_reference" => {
            "Attach the bank payout reference before closing reconciliation."
        }
        "missing_exports" => "Generate the required settlement export artifacts for finance.",
        "partial_exports" => {
            "Generate the missing export formats before publishing the statement pack."
        }
        _ => "No further reconciliation action required.",
    }
}

fn coach_operator_payout_reconciliation_run_payload(
    entry: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> Value {
    let available_export_formats =
        coach_operator_payout_run_available_export_formats(entry, statement_map);
    let ready_export_formats =
        coach_operator_payout_run_ready_export_formats(entry.payout_run_id.as_str(), export_map);
    let missing_export_formats =
        coach_operator_payout_run_missing_export_formats(entry, statement_map, export_map);
    let reconciliation_status =
        coach_operator_payout_run_reconciliation_status(entry, statement_map, export_map);
    let attention_reasons =
        coach_operator_payout_run_attention_reasons(entry, statement_map, export_map);
    let needs_attention = !attention_reasons.is_empty();
    json!({
        "payout_run_id": entry.payout_run_id.clone(),
        "run_status": entry.status.clone(),
        "reconciliation_status": reconciliation_status,
        "currency": entry.currency.clone(),
        "operator_names": entry.operator_names.clone(),
        "statement_ids": entry.statement_ids.clone(),
        "payment_reference": entry.payment_reference.clone(),
        "net_payable_minor_units": entry.net_payable_minor_units,
        "available_export_formats": available_export_formats,
        "ready_export_formats": ready_export_formats,
        "missing_export_formats": missing_export_formats,
        "created_at": entry.created_at.clone(),
        "paid_at": entry.paid_at.clone(),
        "needs_attention": needs_attention,
        "attention_reasons": attention_reasons,
        "next_action": coach_operator_payout_run_next_action(entry, statement_map, export_map),
    })
}

#[cfg(test)]
fn coach_operator_payout_reconciliation_payload(
    limit: usize,
    all_runs: &[CoachSettlementPayoutRunEntry],
    page_source_runs: &[CoachSettlementPayoutRunEntry],
    review_map: &CoachOpsReviewMap,
    event_map: &CoachBoardingEventMap,
    payout_run_map: &CoachSettlementPayoutRunMap,
    export_map: &CoachSettlementExportMap,
) -> Value {
    let statement_map =
        coach_operator_statement_values_by_id(review_map, event_map, payout_run_map);
    coach_operator_payout_reconciliation_payload_with_statement_map(
        limit,
        all_runs,
        page_source_runs,
        &statement_map,
        export_map,
    )
}

fn coach_operator_payout_reconciliation_payload_with_statement_map(
    limit: usize,
    all_runs: &[CoachSettlementPayoutRunEntry],
    page_source_runs: &[CoachSettlementPayoutRunEntry],
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> Value {
    let all_reconciliation_runs = all_runs
        .iter()
        .map(|entry| {
            coach_operator_payout_reconciliation_run_payload(entry, statement_map, export_map)
        })
        .collect::<Vec<_>>();
    let run_count = all_reconciliation_runs.len() as i64;
    let balanced_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["reconciliation_status"].as_str() == Some("balanced"))
        .count() as i64;
    let attention_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["needs_attention"].as_bool().unwrap_or(false))
        .count() as i64;
    let queued_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["run_status"].as_str() == Some("queued"))
        .count() as i64;
    let failed_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["run_status"].as_str() == Some("failed"))
        .count() as i64;
    let awaiting_bank_execution_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["reconciliation_status"].as_str() == Some("awaiting_bank_execution"))
        .count() as i64;
    let payout_failed_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["reconciliation_status"].as_str() == Some("payout_failed"))
        .count() as i64;
    let missing_payment_reference_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["reconciliation_status"].as_str() == Some("missing_payment_reference"))
        .count() as i64;
    let missing_exports_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["reconciliation_status"].as_str() == Some("missing_exports"))
        .count() as i64;
    let partial_export_runs = all_reconciliation_runs
        .iter()
        .filter(|run| run["reconciliation_status"].as_str() == Some("partial_exports"))
        .count() as i64;
    let paid_net_payable_minor_units = all_reconciliation_runs
        .iter()
        .filter(|run| run["run_status"].as_str() == Some("paid"))
        .map(|run| run["net_payable_minor_units"].as_i64().unwrap_or_default())
        .sum::<i64>();
    let attention_net_payable_minor_units = all_reconciliation_runs
        .iter()
        .filter(|run| run["needs_attention"].as_bool().unwrap_or(false))
        .map(|run| run["net_payable_minor_units"].as_i64().unwrap_or_default())
        .sum::<i64>();
    let page = page_source_runs
        .iter()
        .map(|entry| {
            coach_operator_payout_reconciliation_run_payload(entry, statement_map, export_map)
        })
        .take(limit)
        .collect::<Vec<_>>();
    let next_cursor = if page_source_runs.len() > limit {
        page_source_runs
            .iter()
            .take(limit)
            .next_back()
            .map(encode_coach_payout_run_cursor)
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "summary": {
            "currency": "EUR",
            "run_count": run_count,
            "balanced_runs": balanced_runs,
            "attention_runs": attention_runs,
            "queued_runs": queued_runs,
            "failed_runs": failed_runs,
            "awaiting_bank_execution_runs": awaiting_bank_execution_runs,
            "payout_failed_runs": payout_failed_runs,
            "missing_payment_reference_runs": missing_payment_reference_runs,
            "missing_exports_runs": missing_exports_runs,
            "partial_export_runs": partial_export_runs,
            "paid_net_payable_minor_units": paid_net_payable_minor_units,
            "attention_net_payable_minor_units": attention_net_payable_minor_units,
        },
        "next_cursor": next_cursor,
        "runs": page,
    })
}

