fn coach_operator_payout_runs_payload_with_statement_map(
    limit: usize,
    all_runs: &[CoachSettlementPayoutRunEntry],
    page_source_runs: &[CoachSettlementPayoutRunEntry],
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
) -> Value {
    let queued_runs = all_runs.iter().filter(|run| run.status == "queued").count() as i64;
    let paid_runs = all_runs.iter().filter(|run| run.status == "paid").count() as i64;
    let failed_runs = all_runs.iter().filter(|run| run.status == "failed").count() as i64;
    let queued_statement_count = all_runs
        .iter()
        .filter(|run| run.status == "queued")
        .map(|run| run.statement_count)
        .sum::<i64>();
    let queued_net_payable_minor_units = all_runs
        .iter()
        .filter(|run| run.status == "queued")
        .map(|run| run.net_payable_minor_units)
        .sum::<i64>();
    let paid_net_payable_minor_units = all_runs
        .iter()
        .filter(|run| run.status == "paid")
        .map(|run| run.net_payable_minor_units)
        .sum::<i64>();
    let page = page_source_runs.iter().take(limit).collect::<Vec<_>>();
    let next_cursor = if page_source_runs.len() > limit {
        page.last()
            .map(|entry| encode_coach_payout_run_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "summary": {
            "currency": "EUR",
            "queued_runs": queued_runs,
            "paid_runs": paid_runs,
            "failed_runs": failed_runs,
            "queued_statement_count": queued_statement_count,
            "queued_net_payable_minor_units": queued_net_payable_minor_units,
            "paid_net_payable_minor_units": paid_net_payable_minor_units,
        },
        "next_cursor": next_cursor,
        "runs": page
            .into_iter()
            .map(|run| coach_operator_payout_run_payload(run, statement_map, export_map))
            .collect::<Vec<_>>(),
    })
}

fn coach_operator_payout_run_response(
    command: &'static str,
    idempotency_key: &str,
    request_fingerprint: &str,
    payout_run: &CoachSettlementPayoutRunEntry,
    statement_map: &HashMap<String, Value>,
    export_map: &CoachSettlementExportMap,
    next_action: &'static str,
) -> Value {
    let derived_scope = if command == "payout_run_create" {
        "coach_payout_transfer"
    } else {
        "coach_settlement_export"
    };
    json!({
        "command": command,
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            &format!("coach_operator_{command}"),
            request_fingerprint,
            &[(
                "derived_action",
                derived_internal_idempotency_key(idempotency_key, derived_scope),
            )],
        ),
        "payout_run": coach_operator_payout_run_payload(payout_run, statement_map, export_map),
        "next_action": next_action,
    })
}

fn coach_operator_payout_export_response(
    idempotency_key: &str,
    request_fingerprint: &str,
    export: &CoachSettlementExportEntry,
    next_action: &'static str,
) -> Value {
    json!({
        "command": "payout_run_export_create",
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            "coach_operator_payout_run_export_create",
            request_fingerprint,
            &[(
                "derived_action",
                derived_internal_idempotency_key(idempotency_key, "coach_settlement_export"),
            )],
        ),
        "export": coach_operator_payout_export_payload(export),
        "next_action": next_action,
    })
}

