fn coach_catalog_import_run_cmp(
    left: &CoachCatalogImportRun,
    right: &CoachCatalogImportRun,
) -> std::cmp::Ordering {
    left.started_at_iso
        .cmp(&right.started_at_iso)
        .then_with(|| left.import_run_id.cmp(&right.import_run_id))
}

fn coach_operator_catalog_import_run_replay_lineage_summary_payload(
    entry: &CoachCatalogImportRun,
    all_import_runs: &[CoachCatalogImportRun],
) -> Option<Value> {
    let replay_runs = all_import_runs
        .iter()
        .filter(|candidate| {
            candidate.replayed_from_import_run_id.as_deref() == Some(entry.import_run_id.as_str())
        })
        .collect::<Vec<_>>();
    if replay_runs.is_empty() {
        return None;
    }
    let latest_replay_run = replay_runs
        .iter()
        .max_by(|left, right| coach_catalog_import_run_cmp(left, right))?;
    Some(json!({
        "replay_run_count": replay_runs.len(),
        "latest_replay_run_id": latest_replay_run.import_run_id,
        "latest_replay_started_at": latest_replay_run.started_at_iso,
    }))
}

fn coach_operator_catalog_import_run_payload(
    entry: &CoachCatalogImportRun,
    replay_lineage_summary: Option<Value>,
) -> Value {
    json!({
        "import_run_id": entry.import_run_id.clone(),
        "feed_kind": entry.feed_kind.clone(),
        "source_kind": entry.source_kind.clone(),
        "trigger_kind": entry.trigger_kind.clone(),
        "feed_locator": entry.feed_locator.clone(),
        "operator_ids": entry.operator_ids.clone(),
        "replayed_from_import_run_id": entry.replayed_from_import_run_id.clone(),
        "replay_lineage_summary": replay_lineage_summary,
        "source_artifact_id": entry.source_artifact_id.clone(),
        "source_artifact": entry
            .source_artifact
            .as_ref()
            .map(coach_operator_catalog_source_artifact_payload),
        "status": entry.status.clone(),
        "started_at": entry.started_at_iso.clone(),
        "finished_at": entry.finished_at_iso.clone(),
        "counts": entry.counts.as_json(),
        "total_records": entry.counts.total_records(),
        "error_message": entry.error_message.clone(),
        "issue_count": entry.issues.len(),
        "issues": entry
            .issues
            .iter()
            .map(coach_operator_catalog_import_run_issue_payload)
            .collect::<Vec<_>>(),
    })
}

