fn coach_latest_nonempty_rfc3339_iso<'a, I>(values: I) -> Option<String>
where
    I: IntoIterator<Item = &'a str>,
{
    values
        .into_iter()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .max()
        .map(str::to_string)
}

