fn coach_operator_catalog_import_run_detail_payload(
    limit: usize,
    entry: &CoachCatalogImportRun,
    all_issues: &[CoachCatalogImportRunIssue],
    filtered_issues: &[CoachCatalogImportRunIssue],
    page_issues: &[CoachCatalogImportRunIssue],
    filters: &CoachOperatorCatalogImportRunIssueFilters,
) -> Value {
    let page = page_issues.iter().take(limit).collect::<Vec<_>>();
    let next_cursor = if page_issues.len() > limit {
        page.last()
            .map(|issue| encode_coach_catalog_import_run_issue_cursor(issue))
    } else {
        None
    };
    let error_issues = filtered_issues
        .iter()
        .filter(|issue| issue.severity.eq_ignore_ascii_case("error"))
        .count();
    let warning_issues = filtered_issues
        .iter()
        .filter(|issue| issue.severity.eq_ignore_ascii_case("warning"))
        .count();
    let mut available_severities = all_issues
        .iter()
        .map(|issue| issue.severity.trim())
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>();
    available_severities.sort_by(|left, right| {
        coach_catalog_import_run_issue_severity_rank(left)
            .cmp(&coach_catalog_import_run_issue_severity_rank(right))
            .then_with(|| left.cmp(right))
    });
    available_severities.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    let mut available_stages = all_issues
        .iter()
        .map(|issue| issue.stage.trim())
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>();
    available_stages.sort();
    available_stages.dedup();
    let import_run = CoachCatalogImportRun {
        issues: page.into_iter().cloned().collect(),
        ..entry.clone()
    };
    json!({
        "generated_at": now_rfc3339(),
        "issues_summary": {
            "total_issues": all_issues.len(),
            "filtered_issues": filtered_issues.len(),
            "error_issues": error_issues,
            "warning_issues": warning_issues,
        },
        "issues_filters": {
            "severity": filters.severity.clone(),
            "stage": filters.stage.clone(),
            "available_severities": available_severities,
            "available_stages": available_stages,
        },
        "issues_next_cursor": next_cursor,
        "import_run": coach_operator_catalog_import_run_payload(&import_run, None),
    })
}

fn coach_operator_catalog_import_run_lineage_payload(
    limit: usize,
    entry: &CoachCatalogImportRun,
    all_replay_runs: &[CoachCatalogImportRun],
    page_replay_runs: &[CoachCatalogImportRun],
) -> Value {
    let failed_runs = all_replay_runs
        .iter()
        .filter(|entry| entry.status == "failed")
        .count();
    let succeeded_runs = all_replay_runs
        .iter()
        .filter(|entry| entry.status == "succeeded")
        .count();
    let running_runs = all_replay_runs
        .iter()
        .filter(|entry| entry.status == "running")
        .count();
    let latest_started_at = coach_latest_nonempty_rfc3339_iso(
        all_replay_runs
            .iter()
            .map(|entry| entry.started_at_iso.as_str()),
    );
    let page = page_replay_runs.iter().take(limit).collect::<Vec<_>>();
    let next_cursor = if page_replay_runs.len() > limit {
        page.last()
            .map(|entry| encode_coach_catalog_import_run_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "import_run": coach_operator_catalog_import_run_payload(entry, None),
        "replay_runs_summary": {
            "total_runs": all_replay_runs.len(),
            "failed_runs": failed_runs,
            "succeeded_runs": succeeded_runs,
            "running_runs": running_runs,
            "latest_started_at": latest_started_at,
        },
        "replay_runs_next_cursor": next_cursor,
        "replay_runs": page
            .into_iter()
            .map(|entry| coach_operator_catalog_import_run_payload(entry, None))
            .collect::<Vec<_>>(),
    })
}

fn coach_operator_catalog_import_config_payload(
    config: &CoachGtfsFeedConfig,
    persisted_config: Option<&CoachCatalogImportConfig>,
    latest_import_run: Option<&CoachCatalogImportRun>,
) -> Value {
    json!({
        "generated_at": now_rfc3339(),
        "source_kind": config.source_kind,
        "configured": config.configured,
        "feed_locator": config.feed_locator,
        "status": config.status,
        "detail": config.detail,
        "config_origin": config.config_origin,
        "source_artifact": persisted_config
            .and_then(|entry| entry.source_artifact.as_ref())
            .map(coach_operator_catalog_source_artifact_payload),
        "updated_at": persisted_config.map(|entry| entry.updated_at_iso.clone()),
        "updated_by_account_id": persisted_config.map(|entry| entry.updated_by_account_id.clone()),
        "latest_import_run": latest_import_run
            .map(|entry| coach_operator_catalog_import_run_payload(entry, None)),
    })
}

fn coach_operator_catalog_import_config_payload_for_scope(
    config: &CoachGtfsFeedConfig,
    persisted_config: Option<&CoachCatalogImportConfig>,
    latest_import_run: Option<&CoachCatalogImportRun>,
    allowed_operator_ids: &HashSet<String>,
) -> Value {
    if allowed_operator_ids.is_empty() {
        return coach_operator_catalog_import_config_payload(
            config,
            persisted_config,
            latest_import_run,
        );
    }
    let scoped_persisted_config = persisted_config.filter(|entry| {
        entry
            .source_artifact
            .as_ref()
            .map(|source_artifact| {
                coach_operator_scope_allows_operator_ids(
                    &source_artifact.operator_ids,
                    allowed_operator_ids,
                )
            })
            .unwrap_or(false)
    });
    let scoped_latest_import_run = latest_import_run.filter(|entry| {
        coach_operator_scope_allows_operator_ids(&entry.operator_ids, allowed_operator_ids)
    });
    match scoped_persisted_config {
        Some(scoped_persisted_config) => coach_operator_catalog_import_config_payload(
            config,
            Some(scoped_persisted_config),
            scoped_latest_import_run,
        ),
        None => json!({
            "generated_at": now_rfc3339(),
            "source_kind": config.source_kind,
            "configured": false,
            "feed_locator": Value::Null,
            "status": "missing",
            "detail": "Scoped source artifact required for this operator account.",
            "config_origin": "operator_scope",
            "source_artifact": Value::Null,
            "updated_at": Value::Null,
            "updated_by_account_id": Value::Null,
            "latest_import_run": Value::Null,
        }),
    }
}

fn coach_operator_catalog_import_config_mutation_payload(
    idempotency_key: &str,
    request_fingerprint: &str,
    config: &CoachGtfsFeedConfig,
    persisted_config: Option<&CoachCatalogImportConfig>,
    latest_import_run: Option<&CoachCatalogImportRun>,
    allowed_operator_ids: &HashSet<String>,
    next_action: &'static str,
) -> Value {
    json!({
        "command": "catalog_import_config_update",
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            "coach_operator_catalog_import_config_update",
            request_fingerprint,
            &[],
        ),
        "config": coach_operator_catalog_import_config_payload_for_scope(
            config,
            persisted_config,
            latest_import_run,
            allowed_operator_ids,
        ),
        "next_action": next_action,
    })
}

fn coach_catalog_saved_view_can_manage(view_account_id: &str, viewer_account_id: &str) -> bool {
    !viewer_account_id.trim().is_empty() && view_account_id.trim() == viewer_account_id.trim()
}

fn coach_find_catalog_import_run_saved_view_name_conflict<'a>(
    saved_views: &'a [CoachCatalogImportRunSavedView],
    view_id: &str,
    name: &str,
    visibility_scope: &str,
) -> Option<&'a CoachCatalogImportRunSavedView> {
    let normalized_view_id = view_id.trim();
    let normalized_name = name.trim();
    let normalized_visibility_scope = visibility_scope.trim();
    saved_views.iter().find(|entry| {
        entry.view_id != normalized_view_id
            && entry
                .visibility_scope
                .eq_ignore_ascii_case(normalized_visibility_scope)
            && entry.name.eq_ignore_ascii_case(normalized_name)
    })
}

