fn coach_allowed_saved_view_operator_scope(operator_ids: &[String]) -> HashSet<String> {
    operator_ids
        .iter()
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty())
        .collect()
}

fn coach_sorted_saved_view_operator_scope(operator_ids: &HashSet<String>) -> Vec<String> {
    let mut sorted_operator_ids = operator_ids.iter().cloned().collect::<Vec<_>>();
    sorted_operator_ids.sort_unstable();
    sorted_operator_ids
}

fn coach_operator_scope_allows_operator_ids(
    operator_ids: &[String],
    allowed_operator_ids: &HashSet<String>,
) -> bool {
    if allowed_operator_ids.is_empty() {
        return true;
    }
    let scoped_operator_ids = operator_ids
        .iter()
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty())
        .collect::<HashSet<_>>();
    if scoped_operator_ids.is_empty() {
        return false;
    }
    scoped_operator_ids
        .iter()
        .any(|operator_id| allowed_operator_ids.contains(operator_id))
}

fn coach_shared_saved_view_falls_within_operator_scope(
    operator_ids: &[String],
    allowed_operator_ids: &HashSet<String>,
) -> bool {
    coach_operator_scope_allows_operator_ids(operator_ids, allowed_operator_ids)
}

fn coach_payout_saved_view_operator_scope_ids(operator_id: &str) -> Vec<String> {
    let normalized_operator_id = operator_id.trim();
    if normalized_operator_id.is_empty() || normalized_operator_id.eq_ignore_ascii_case("all") {
        return Vec::new();
    }
    vec![normalized_operator_id.to_string()]
}

#[derive(Clone, Copy)]
struct CoachSavedViewSortKey<'a> {
    is_default: bool,
    visibility_scope: &'a str,
    updated_at_iso: &'a str,
    view_id: &'a str,
}

fn coach_saved_view_cmp(
    left: &CoachSavedViewSortKey<'_>,
    right: &CoachSavedViewSortKey<'_>,
) -> std::cmp::Ordering {
    right
        .is_default
        .cmp(&left.is_default)
        .then_with(|| left.visibility_scope.cmp(right.visibility_scope))
        .then_with(|| right.updated_at_iso.cmp(left.updated_at_iso))
        .then_with(|| right.view_id.cmp(left.view_id))
}

fn coach_sort_catalog_import_run_saved_views(saved_views: &mut [CoachCatalogImportRunSavedView]) {
    saved_views.sort_by(|left, right| {
        coach_saved_view_cmp(
            &CoachSavedViewSortKey {
                is_default: left.is_default,
                visibility_scope: left.visibility_scope.as_str(),
                updated_at_iso: left.updated_at_iso.as_str(),
                view_id: left.view_id.as_str(),
            },
            &CoachSavedViewSortKey {
                is_default: right.is_default,
                visibility_scope: right.visibility_scope.as_str(),
                updated_at_iso: right.updated_at_iso.as_str(),
                view_id: right.view_id.as_str(),
            },
        )
    });
}

