fn coach_filter_catalog_import_run_saved_views_by_operator_scope(
    saved_views: &[CoachCatalogImportRunSavedView],
    allowed_operator_ids: &HashSet<String>,
) -> Vec<CoachCatalogImportRunSavedView> {
    let mut filtered = if allowed_operator_ids.is_empty() {
        saved_views.to_vec()
    } else {
        saved_views
            .iter()
            .filter(|entry| {
                entry.visibility_scope != "shared_ops"
                    || coach_shared_saved_view_falls_within_operator_scope(
                        &entry.operator_ids,
                        allowed_operator_ids,
                    )
            })
            .cloned()
            .collect()
    };
    coach_sort_catalog_import_run_saved_views(&mut filtered);
    filtered
}

