fn coach_restrict_saved_view_operator_ids_to_scope(
    operator_ids: &[String],
    allowed_operator_ids: &HashSet<String>,
) -> ApiResult<Vec<String>> {
    if allowed_operator_ids.is_empty() {
        return Ok(operator_ids.to_vec());
    }
    if operator_ids.is_empty() {
        return Ok(coach_sorted_saved_view_operator_scope(allowed_operator_ids));
    }
    let requested_operator_ids = coach_allowed_saved_view_operator_scope(operator_ids);
    if requested_operator_ids
        .iter()
        .any(|operator_id| !allowed_operator_ids.contains(operator_id))
    {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "coach catalog saved view operator scope exceeds operator privileges",
        ));
    }
    Ok(coach_sorted_saved_view_operator_scope(
        &requested_operator_ids,
    ))
}

fn coach_require_catalog_resource_operator_scope(
    resource_label: &str,
    operator_ids: &[String],
    allowed_operator_ids: &HashSet<String>,
) -> ApiResult<()> {
    if allowed_operator_ids.is_empty() {
        return Ok(());
    }
    let scoped_operator_ids = coach_allowed_saved_view_operator_scope(operator_ids);
    if scoped_operator_ids.is_empty() {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            format!("{resource_label} operator scope unavailable for restricted operator account"),
        ));
    }
    if !scoped_operator_ids
        .iter()
        .any(|operator_id| allowed_operator_ids.contains(operator_id))
    {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            format!("{resource_label} exceeds operator privileges"),
        ));
    }
    Ok(())
}

fn coach_filter_catalog_import_runs_by_operator_scope(
    import_runs: &[CoachCatalogImportRun],
    allowed_operator_ids: &HashSet<String>,
) -> Vec<CoachCatalogImportRun> {
    if allowed_operator_ids.is_empty() {
        return import_runs.to_vec();
    }
    import_runs
        .iter()
        .filter(|entry| {
            coach_operator_scope_allows_operator_ids(&entry.operator_ids, allowed_operator_ids)
        })
        .cloned()
        .collect()
}

