fn coach_filter_gtfs_feed_source_options_by_operator_scope(
    sources: &[CoachGtfsFeedSourceOption],
    artifacts: &[CoachCatalogSourceArtifact],
    allowed_operator_ids: &HashSet<String>,
) -> Vec<CoachGtfsFeedSourceOption> {
    if allowed_operator_ids.is_empty() {
        return sources.to_vec();
    }
    let allowed_feed_locators = artifacts
        .iter()
        .filter(|entry| {
            coach_operator_scope_allows_operator_ids(&entry.operator_ids, allowed_operator_ids)
        })
        .map(|entry| entry.feed_locator.trim().to_string())
        .collect::<HashSet<_>>();
    sources
        .iter()
        .filter(|entry| allowed_feed_locators.contains(entry.feed_locator.trim()))
        .cloned()
        .collect()
}

fn coach_latest_catalog_import_run_for_operator_scope(
    import_runs: &[CoachCatalogImportRun],
    allowed_operator_ids: &HashSet<String>,
) -> Option<CoachCatalogImportRun> {
    import_runs
        .iter()
        .filter(|entry| {
            allowed_operator_ids.is_empty()
                || coach_operator_scope_allows_operator_ids(
                    &entry.operator_ids,
                    allowed_operator_ids,
                )
        })
        .max_by(|left, right| coach_catalog_import_run_cmp(left, right))
        .cloned()
}

const COACH_COLLECTION_CATALOG_IMPORT_RUN_SAVED_VIEWS: &str = "catalog_import_run_saved_views";
const COACH_COLLECTION_CATALOG_IMPORT_RUN_ISSUE_SAVED_VIEWS: &str =
    "catalog_import_run_issue_saved_views";
const COACH_COLLECTION_PAYOUT_IMPORT_PREVIEW_SAVED_VIEWS: &str =
    "payout_import_preview_saved_views";
const COACH_COLLECTION_PAYOUT_IMPORT_BATCH_SAVED_VIEWS: &str = "payout_import_batch_saved_views";

fn coach_operator_catalog_import_run_saved_view_payload(
    entry: &CoachCatalogImportRunSavedView,
    viewer_account_id: &str,
    favorite_view_ids: &HashSet<String>,
    usage_by_view_id: &HashMap<String, String>,
) -> Value {
    json!({
        "view_id": entry.view_id.clone(),
        "account_id": entry.account_id.clone(),
        "name": entry.name.clone(),
        "visibility_scope": entry.visibility_scope.clone(),
        "operator_ids": entry.operator_ids.clone(),
        "status": entry.status_filter.clone(),
        "replay_scope": entry.replay_scope_filter.clone(),
        "severity": entry.issue_severity_filter.clone(),
        "stage": entry.issue_stage_filter.clone(),
        "is_default": entry.is_default,
        "is_favorite": favorite_view_ids.contains(&entry.view_id),
        "last_used_at": usage_by_view_id.get(&entry.view_id).cloned(),
        "can_manage": coach_catalog_saved_view_can_manage(&entry.account_id, viewer_account_id),
        "created_at": entry.created_at_iso.clone(),
        "updated_at": entry.updated_at_iso.clone(),
    })
}

fn coach_shared_catalog_import_run_saved_view_owner_summaries_payload(
    saved_views: &[CoachCatalogImportRunSavedView],
) -> Vec<Value> {
    let mut counts = std::collections::BTreeMap::<String, i64>::new();
    for entry in saved_views {
        if entry.visibility_scope != "shared_ops" {
            continue;
        }
        let account_id = entry.account_id.trim();
        if account_id.is_empty() {
            continue;
        }
        *counts.entry(account_id.to_string()).or_insert(0) += 1;
    }
    let mut rows = counts
        .into_iter()
        .map(|(account_id, shared_view_count)| {
            json!({
                "account_id": account_id,
                "shared_view_count": shared_view_count,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        let left_count = left["shared_view_count"].as_i64().unwrap_or_default();
        let right_count = right["shared_view_count"].as_i64().unwrap_or_default();
        right_count.cmp(&left_count).then_with(|| {
            left["account_id"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["account_id"].as_str().unwrap_or_default())
        })
    });
    rows
}

fn coach_shared_catalog_import_run_saved_view_operator_summaries_payload(
    saved_views: &[CoachCatalogImportRunSavedView],
    operator_names: &HashMap<String, String>,
) -> Vec<Value> {
    let mut counts = std::collections::BTreeMap::<String, i64>::new();
    for entry in saved_views {
        if entry.visibility_scope != "shared_ops" {
            continue;
        }
        let operator_ids = entry
            .operator_ids
            .iter()
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
            .collect::<std::collections::BTreeSet<_>>();
        for operator_id in operator_ids {
            *counts.entry(operator_id.to_string()).or_insert(0) += 1;
        }
    }
    let mut rows = counts
        .into_iter()
        .map(|(operator_id, shared_view_count)| {
            json!({
                "operator_id": operator_id,
                "operator_name": operator_names.get(&operator_id).cloned(),
                "shared_view_count": shared_view_count,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        let left_count = left["shared_view_count"].as_i64().unwrap_or_default();
        let right_count = right["shared_view_count"].as_i64().unwrap_or_default();
        right_count.cmp(&left_count).then_with(|| {
            left["operator_id"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["operator_id"].as_str().unwrap_or_default())
        })
    });
    rows
}

