fn coach_shared_catalog_import_run_issue_saved_view_owner_summaries_payload(
    saved_views: &[CoachCatalogImportRunIssueSavedView],
) -> Vec<Value> {
    let mut counts = std::collections::BTreeMap::<String, i64>::new();
    for entry in saved_views {
        if entry.visibility_scope != "shared_ops" {
            continue;
        }
        let account_id = entry.account_id.trim();
        if account_id.is_empty() {
            continue;
        }
        *counts.entry(account_id.to_string()).or_insert(0) += 1;
    }
    let mut rows = counts
        .into_iter()
        .map(|(account_id, shared_view_count)| {
            json!({
                "account_id": account_id,
                "shared_view_count": shared_view_count,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        let left_count = left["shared_view_count"].as_i64().unwrap_or_default();
        let right_count = right["shared_view_count"].as_i64().unwrap_or_default();
        right_count.cmp(&left_count).then_with(|| {
            left["account_id"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["account_id"].as_str().unwrap_or_default())
        })
    });
    rows
}

fn coach_shared_catalog_import_run_issue_saved_view_operator_summaries_payload(
    saved_views: &[CoachCatalogImportRunIssueSavedView],
    operator_names: &HashMap<String, String>,
) -> Vec<Value> {
    let mut counts = std::collections::BTreeMap::<String, i64>::new();
    for entry in saved_views {
        if entry.visibility_scope != "shared_ops" {
            continue;
        }
        let operator_ids = entry
            .operator_ids
            .iter()
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
            .collect::<std::collections::BTreeSet<_>>();
        for operator_id in operator_ids {
            *counts.entry(operator_id.to_string()).or_insert(0) += 1;
        }
    }
    let mut rows = counts
        .into_iter()
        .map(|(operator_id, shared_view_count)| {
            json!({
                "operator_id": operator_id,
                "operator_name": operator_names.get(&operator_id).cloned(),
                "shared_view_count": shared_view_count,
            })
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        let left_count = left["shared_view_count"].as_i64().unwrap_or_default();
        let right_count = right["shared_view_count"].as_i64().unwrap_or_default();
        right_count.cmp(&left_count).then_with(|| {
            left["operator_id"]
                .as_str()
                .unwrap_or_default()
                .cmp(right["operator_id"].as_str().unwrap_or_default())
        })
    });
    rows
}

