fn coach_collect_operator_name_map(operators: &[CoachCatalogOperator]) -> HashMap<String, String> {
    operators
        .iter()
        .map(|entry| {
            (
                entry.operator_id.trim().to_string(),
                entry.display_name.trim().to_string(),
            )
        })
        .filter(|(operator_id, display_name)| !operator_id.is_empty() && !display_name.is_empty())
        .collect()
}

async fn coach_catalog_saved_view_operator_name_map(
    repo: &CoachCatalogRepository,
    operator_ids: impl IntoIterator<Item = String>,
) -> Result<HashMap<String, String>, sqlx::Error> {
    let operator_ids = operator_ids
        .into_iter()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    if operator_ids.is_empty() {
        return Ok(HashMap::new());
    }
    let operators = repo.list_operators_by_ids(&operator_ids).await?;
    Ok(coach_collect_operator_name_map(&operators))
}

