fn coach_operator_catalog_source_artifacts_payload(
    limit: usize,
    all_artifacts: &[CoachCatalogSourceArtifact],
    page_source_artifacts: &[CoachCatalogSourceArtifact],
) -> Value {
    let total_bytes = all_artifacts
        .iter()
        .map(|entry| entry.content_length_bytes)
        .sum::<i64>();
    let latest_created_at = coach_latest_nonempty_rfc3339_iso(
        all_artifacts
            .iter()
            .map(|entry| entry.created_at_iso.as_str()),
    );
    let page = page_source_artifacts.iter().take(limit).collect::<Vec<_>>();
    let next_cursor = if page_source_artifacts.len() > limit {
        page.last()
            .map(|entry| encode_coach_catalog_source_artifact_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "summary": {
            "total_artifacts": all_artifacts.len(),
            "uploaded_bytes_total": total_bytes,
            "latest_created_at": latest_created_at,
        },
        "next_cursor": next_cursor,
        "artifacts": page
            .into_iter()
            .map(coach_operator_catalog_source_artifact_payload)
            .collect::<Vec<_>>(),
    })
}

fn coach_operator_catalog_source_artifact_detail_payload(
    limit: usize,
    entry: &CoachCatalogSourceArtifact,
    all_referencing_import_runs: &[CoachCatalogImportRun],
    page_source_import_runs: &[CoachCatalogImportRun],
) -> Value {
    let failed_runs = all_referencing_import_runs
        .iter()
        .filter(|entry| entry.status == "failed")
        .count();
    let succeeded_runs = all_referencing_import_runs
        .iter()
        .filter(|entry| entry.status == "succeeded")
        .count();
    let running_runs = all_referencing_import_runs
        .iter()
        .filter(|entry| entry.status == "running")
        .count();
    let latest_started_at = coach_latest_nonempty_rfc3339_iso(
        all_referencing_import_runs
            .iter()
            .map(|entry| entry.started_at_iso.as_str()),
    );
    let page = page_source_import_runs
        .iter()
        .take(limit)
        .collect::<Vec<_>>();
    let next_cursor = if page_source_import_runs.len() > limit {
        page.last()
            .map(|entry| encode_coach_catalog_import_run_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "source_artifact": coach_operator_catalog_source_artifact_payload(entry),
        "referencing_import_runs_summary": {
            "total_runs": all_referencing_import_runs.len(),
            "failed_runs": failed_runs,
            "succeeded_runs": succeeded_runs,
            "running_runs": running_runs,
            "latest_started_at": latest_started_at,
        },
        "referencing_import_runs_next_cursor": next_cursor,
        "referencing_import_runs": page
            .into_iter()
            .map(|entry| coach_operator_catalog_import_run_payload(entry, None))
            .collect::<Vec<_>>(),
    })
}

