fn coach_effective_payout_import_preview_status(
    entry: &CoachSettlementPayoutImportPreviewEntry,
) -> &'static str {
    if entry.preview_status == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED {
        COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED
    } else if entry.preview_status == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED {
        COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED
    } else if coach_preview_entry_is_expired(entry) {
        COACH_PAYOUT_IMPORT_PREVIEW_STATUS_EXPIRED
    } else {
        COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE
    }
}

fn coach_operator_payout_import_preview_payload(
    entry: &CoachSettlementPayoutImportPreviewEntry,
) -> Value {
    let effective_status = coach_effective_payout_import_preview_status(entry);
    json!({
        "preview_token": entry.preview_token.clone(),
        "account_id": entry.account_id.clone(),
        "import_source": entry.import_source.clone(),
        "report_name": entry.report_name.clone(),
        "report_format": entry.report_format.clone(),
        "rework_of_batch_id": entry.rework_of_batch_id.clone(),
        "operator_ids": entry.operator_ids.clone(),
        "report_checksum_sha256": entry.report_checksum_sha256.clone(),
        "request_fingerprint": entry.request_fingerprint.clone(),
        "preview_status": effective_status,
        "created_at": entry.created_at.clone(),
        "expires_at": entry.expires_at.clone(),
        "consumed_at": entry.consumed_at.clone(),
        "invalidated_at": entry.invalidated_at.clone(),
        "usable_now": effective_status == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE,
    })
}

