fn coach_filter_payout_import_previews(
    preview_map: &CoachSettlementPayoutImportPreviewMap,
    filters: &CoachOperatorPayoutImportPreviewFilters,
) -> Vec<CoachSettlementPayoutImportPreviewEntry> {
    let mut previews = preview_map
        .values()
        .filter(|entry| {
            if let Some(expected_status) = filters.status.as_deref() {
                if coach_effective_payout_import_preview_status(entry) != expected_status {
                    return false;
                }
            }
            let parsed_created_at = match (
                filters.from_created_at.as_ref(),
                filters.to_created_at.as_ref(),
                filters.cursor.as_ref(),
            ) {
                (None, None, None) => None,
                _ => chrono::DateTime::parse_from_rfc3339(entry.created_at.as_str()).ok(),
            };
            if let Some(from_created_at) = filters.from_created_at.as_ref() {
                let Some(created_at) = parsed_created_at.as_ref() else {
                    return false;
                };
                if created_at < from_created_at {
                    return false;
                }
            }
            if let Some(to_created_at) = filters.to_created_at.as_ref() {
                let Some(created_at) = parsed_created_at.as_ref() else {
                    return false;
                };
                if created_at > to_created_at {
                    return false;
                }
            }
            if let Some(cursor) = filters.cursor.as_ref() {
                let Some(created_at) = parsed_created_at.as_ref() else {
                    return false;
                };
                if created_at > &cursor.created_at {
                    return false;
                }
                if created_at == &cursor.created_at
                    && entry.preview_token.as_str() >= cursor.preview_token.as_str()
                {
                    return false;
                }
            }
            true
        })
        .cloned()
        .collect::<Vec<_>>();
    previews.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| right.preview_token.cmp(&left.preview_token))
    });
    previews
}

fn coach_operator_payout_import_previews_payload(
    limit: usize,
    all_previews: &[CoachSettlementPayoutImportPreviewEntry],
    page_source_previews: &[CoachSettlementPayoutImportPreviewEntry],
) -> Value {
    let active_previews = all_previews
        .iter()
        .filter(|entry| {
            coach_effective_payout_import_preview_status(entry)
                == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE
        })
        .count() as i64;
    let consumed_previews = all_previews
        .iter()
        .filter(|entry| {
            coach_effective_payout_import_preview_status(entry)
                == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED
        })
        .count() as i64;
    let expired_previews = all_previews
        .iter()
        .filter(|entry| {
            coach_effective_payout_import_preview_status(entry)
                == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_EXPIRED
        })
        .count() as i64;
    let invalidated_previews = all_previews
        .iter()
        .filter(|entry| {
            coach_effective_payout_import_preview_status(entry)
                == COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED
        })
        .count() as i64;
    let page = page_source_previews.iter().take(limit).collect::<Vec<_>>();
    let next_cursor = if page_source_previews.len() > limit {
        page.last()
            .map(|entry| encode_coach_payout_import_preview_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "summary": {
            "total_previews": all_previews.len(),
            "active_previews": active_previews,
            "consumed_previews": consumed_previews,
            "expired_previews": expired_previews,
            "invalidated_previews": invalidated_previews,
        },
        "next_cursor": next_cursor,
        "previews": page
            .into_iter()
            .map(coach_operator_payout_import_preview_payload)
            .collect::<Vec<_>>(),
    })
}

fn coach_operator_payout_imports_payload(
    limit: usize,
    all_imports: &[CoachSettlementPayoutImportEntry],
    page_source_imports: &[CoachSettlementPayoutImportEntry],
) -> Value {
    let executed_imports = all_imports
        .iter()
        .filter(|entry| entry.external_status == "executed")
        .count() as i64;
    let failed_imports = all_imports
        .iter()
        .filter(|entry| entry.external_status == "failed")
        .count() as i64;
    let pending_imports = all_imports
        .iter()
        .filter(|entry| entry.external_status == "pending")
        .count() as i64;
    let page = page_source_imports.iter().take(limit).collect::<Vec<_>>();
    let next_cursor = if page_source_imports.len() > limit {
        page.last()
            .map(|entry| encode_coach_payout_import_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "summary": {
            "total_imports": all_imports.len(),
            "executed_imports": executed_imports,
            "failed_imports": failed_imports,
            "pending_imports": pending_imports,
        },
        "next_cursor": next_cursor,
        "imports": page
            .into_iter()
            .map(coach_operator_payout_import_payload)
            .collect::<Vec<_>>(),
    })
}

fn coach_operator_catalog_import_runs_payload(
    limit: usize,
    all_import_runs: &[CoachCatalogImportRun],
    page_source_import_runs: &[CoachCatalogImportRun],
    lineage_import_runs: &[CoachCatalogImportRun],
) -> Value {
    let succeeded_runs = all_import_runs
        .iter()
        .filter(|entry| entry.status == "succeeded")
        .count() as i64;
    let failed_runs = all_import_runs
        .iter()
        .filter(|entry| entry.status == "failed")
        .count() as i64;
    let running_runs = all_import_runs
        .iter()
        .filter(|entry| entry.status == "running")
        .count() as i64;
    let imported_records = all_import_runs
        .iter()
        .filter(|entry| entry.status == "succeeded")
        .map(|entry| entry.counts.total_records())
        .sum::<i64>();
    let latest_succeeded_at = all_import_runs
        .iter()
        .filter(|entry| entry.status == "succeeded")
        .filter_map(|entry| entry.finished_at_iso.as_deref())
        .max()
        .map(str::to_string);
    let page = page_source_import_runs
        .iter()
        .take(limit)
        .collect::<Vec<_>>();
    let next_cursor = if page_source_import_runs.len() > limit {
        page.last()
            .map(|entry| encode_coach_catalog_import_run_cursor(entry))
    } else {
        None
    };
    json!({
        "generated_at": now_rfc3339(),
        "summary": {
            "total_runs": all_import_runs.len(),
            "succeeded_runs": succeeded_runs,
            "failed_runs": failed_runs,
            "running_runs": running_runs,
            "imported_records_total": imported_records,
            "latest_succeeded_at": latest_succeeded_at,
        },
        "next_cursor": next_cursor,
        "import_runs": page
            .into_iter()
            .map(|entry| {
                coach_operator_catalog_import_run_payload(
                    entry,
                    coach_operator_catalog_import_run_replay_lineage_summary_payload(
                        entry,
                        lineage_import_runs,
                    ),
                )
            })
            .collect::<Vec<_>>(),
    })
}

fn coach_filter_payout_imports(
    import_map: &CoachSettlementPayoutImportMap,
    cursor: Option<&CoachOperatorPayoutImportCursor>,
) -> Vec<CoachSettlementPayoutImportEntry> {
    let mut imports = import_map
        .values()
        .filter(|entry| {
            let Some(cursor) = cursor else {
                return true;
            };
            let Ok(imported_at) = chrono::DateTime::parse_from_rfc3339(entry.imported_at.as_str())
            else {
                return false;
            };
            if imported_at > cursor.imported_at {
                return false;
            }
            if imported_at == cursor.imported_at
                && entry.import_id.as_str() >= cursor.import_id.as_str()
            {
                return false;
            }
            true
        })
        .cloned()
        .collect::<Vec<_>>();
    imports.sort_by(|left, right| {
        right
            .imported_at
            .cmp(&left.imported_at)
            .then_with(|| right.import_id.cmp(&left.import_id))
    });
    imports
}

fn coach_catalog_import_run_has_replays(
    entry: &CoachCatalogImportRun,
    lineage_runs: &[CoachCatalogImportRun],
) -> bool {
    lineage_runs.iter().any(|candidate| {
        candidate.replayed_from_import_run_id.as_deref() == Some(entry.import_run_id.as_str())
    })
}

fn coach_catalog_import_run_needs_attention(
    entry: &CoachCatalogImportRun,
    lineage_runs: &[CoachCatalogImportRun],
) -> bool {
    if entry.replayed_from_import_run_id.is_some() && entry.status == "failed" {
        return true;
    }
    lineage_runs.iter().any(|candidate| {
        candidate.replayed_from_import_run_id.as_deref() == Some(entry.import_run_id.as_str())
            && candidate.status == "failed"
    })
}

fn coach_filter_catalog_import_runs(
    import_runs: &[CoachCatalogImportRun],
    lineage_runs: &[CoachCatalogImportRun],
    filters: &CoachOperatorCatalogImportRunFilters,
) -> Vec<CoachCatalogImportRun> {
    let mut filtered = import_runs
        .iter()
        .filter(|entry| {
            if let Some(status) = filters.status.as_deref() {
                if entry.status.as_str() != status {
                    return false;
                }
            }
            if let Some(replay_scope) = filters.replay_scope.as_deref() {
                let include = match replay_scope {
                    "replays_only" => entry.replayed_from_import_run_id.is_some(),
                    "with_replays" => coach_catalog_import_run_has_replays(entry, lineage_runs),
                    "attention" => coach_catalog_import_run_needs_attention(entry, lineage_runs),
                    _ => true,
                };
                if !include {
                    return false;
                }
            }
            if filters.severity.is_some() || filters.stage.is_some() {
                let matches_issue_filters = entry.issues.iter().any(|issue| {
                    if let Some(severity) = filters.severity.as_deref() {
                        if !issue.severity.eq_ignore_ascii_case(severity) {
                            return false;
                        }
                    }
                    if let Some(stage) = filters.stage.as_deref() {
                        if !issue.stage.eq_ignore_ascii_case(stage) {
                            return false;
                        }
                    }
                    true
                });
                if !matches_issue_filters {
                    return false;
                }
            }
            if let Some(cursor) = filters.cursor.as_ref() {
                let Ok(started_at) =
                    chrono::DateTime::parse_from_rfc3339(entry.started_at_iso.as_str())
                else {
                    return false;
                };
                if started_at > cursor.started_at {
                    return false;
                }
                if started_at == cursor.started_at
                    && entry.import_run_id.as_str() >= cursor.import_run_id.as_str()
                {
                    return false;
                }
            }
            true
        })
        .cloned()
        .collect::<Vec<_>>();
    filtered.sort_by(|left, right| {
        right
            .started_at_iso
            .cmp(&left.started_at_iso)
            .then_with(|| right.import_run_id.cmp(&left.import_run_id))
    });
    filtered
}

fn coach_filter_catalog_import_run_issues(
    issues: &[CoachCatalogImportRunIssue],
    filters: &CoachOperatorCatalogImportRunIssueFilters,
) -> Vec<CoachCatalogImportRunIssue> {
    let mut filtered = issues
        .iter()
        .filter(|entry| {
            if let Some(severity) = filters.severity.as_deref() {
                if !entry.severity.eq_ignore_ascii_case(severity) {
                    return false;
                }
            }
            if let Some(stage) = filters.stage.as_deref() {
                if !entry.stage.eq_ignore_ascii_case(stage) {
                    return false;
                }
            }
            if let Some(cursor) = filters.cursor.as_ref() {
                return entry.issue_id.as_str() > cursor.issue_id.as_str();
            }
            true
        })
        .cloned()
        .collect::<Vec<_>>();
    filtered.sort_by(|left, right| left.issue_id.cmp(&right.issue_id));
    filtered
}

fn coach_catalog_import_run_issue_severity_rank(severity: &str) -> i32 {
    match severity.to_ascii_lowercase().as_str() {
        "error" => 0,
        "warning" => 1,
        "info" => 2,
        _ => 3,
    }
}

