fn coach_filter_payout_run_map_by_operator_scope(
    payout_run_map: &CoachSettlementPayoutRunMap,
    allowed_operator_ids: &HashSet<String>,
) -> CoachSettlementPayoutRunMap {
    if allowed_operator_ids.is_empty() {
        return payout_run_map.clone();
    }
    payout_run_map
        .iter()
        .filter(|(_, entry)| {
            coach_operator_scope_allows_operator_ids(&entry.operator_ids, allowed_operator_ids)
        })
        .map(|(payout_run_id, entry)| (payout_run_id.clone(), entry.clone()))
        .collect()
}

