enum CoachSelfServiceReissuePaymentOutcome {
    Authorized(Value),
    Failed {
        payment_payload: Value,
        compensation_payload: Value,
        next_action: &'static str,
    },
}

fn coach_self_service_reissue_payment_outcome(
    booking_id: &str,
    payment_method: &str,
    total_minor_units: i64,
) -> CoachSelfServiceReissuePaymentOutcome {
    if payment_method == "wallet_credit"
        && total_minor_units > COACH_WALLET_CREDIT_SELF_SERVICE_REISSUE_MAX_MINOR_UNITS
    {
        let recovery_reference = coach_scoped_resource_id(
            "recovery",
            &format!("{booking_id}|{payment_method}|{total_minor_units}|ticket_reissue"),
        );
        return CoachSelfServiceReissuePaymentOutcome::Failed {
            payment_payload: coach_payment_failure_payload(
                booking_id,
                payment_method,
                total_minor_units,
            ),
            compensation_payload: coach_compensation_payload(
                "triggered",
                "retry_collection_or_raise_support_case",
                "coach_rebook_queue",
                true,
                Some("wallet_credit_insufficient"),
                Some(&recovery_reference),
            ),
            next_action: "resolve_payment_failure",
        };
    }

    CoachSelfServiceReissuePaymentOutcome::Authorized(coach_payment_authorization_payload(
        booking_id,
        payment_method,
        total_minor_units,
    ))
}

fn coach_compensation_payload(
    state: &str,
    action: &str,
    support_queue: &str,
    triggered: bool,
    reason: Option<&str>,
    recovery_reference: Option<&str>,
) -> Value {
    json!({
        "state": state,
        "action": action,
        "support_queue": support_queue,
        "triggered": triggered,
        "reason": reason,
        "recovery_reference": recovery_reference
    })
}

fn coach_idempotency_payload(
    key: &str,
    scope: &str,
    request_fingerprint: &str,
    derived_keys: &[(&str, String)],
) -> Value {
    let mut derived = Map::new();
    for (label, value) in derived_keys {
        derived.insert((*label).to_string(), Value::String(value.clone()));
    }
    json!({
        "key": key,
        "scope": scope,
        "request_fingerprint": request_fingerprint,
        "replayed": false,
        "derived_keys": derived
    })
}

fn coach_response_with_replay_flag(mut response: Value, replayed: bool) -> Value {
    if let Some(object) = response.as_object_mut() {
        if let Some(idempotency) = object.get_mut("idempotency") {
            if let Some(idempotency_object) = idempotency.as_object_mut() {
                idempotency_object.insert("replayed".to_string(), Value::Bool(replayed));
            }
        }
    }
    response
}

fn coach_mutation_replay_cache_key(
    normalized_account_id: &str,
    command: &str,
    idempotency_key: &str,
) -> String {
    format!("{}|{}|{}", normalized_account_id, command, idempotency_key)
}

fn coach_in_memory_has_cross_command_idempotency_reuse(
    cache: &CoachMutationReplayMap,
    normalized_account_id: &str,
    command: &str,
    idempotency_key: &str,
) -> bool {
    let account_prefix = format!("{}|", normalized_account_id);
    let idempotency_suffix = format!("|{}", idempotency_key);
    cache.keys().any(|cache_key| {
        if !cache_key.starts_with(&account_prefix) || !cache_key.ends_with(&idempotency_suffix) {
            return false;
        }
        let mut parts = cache_key.splitn(3, '|');
        let _ = parts.next();
        let cached_command = parts.next().unwrap_or_default();
        cached_command != command
    })
}

async fn coach_auth_has_cross_command_idempotency_reuse(
    auth_runtime: &auth::AuthRuntime,
    normalized_account_id: &str,
    command: &str,
    idempotency_key: &str,
) -> Result<bool, sqlx::Error> {
    let row = sqlx::query(
        "SELECT 1 \
         FROM auth_coach_mutation_replays \
         WHERE account_id=$1 AND idempotency_key=$2 AND command<>$3 \
         LIMIT 1",
    )
    .bind(normalized_account_id)
    .bind(idempotency_key)
    .bind(command)
    .fetch_optional(auth_runtime.pool())
    .await?;
    Ok(row.is_some())
}

fn coach_auth_mutation_replay_lock_key(
    normalized_account_id: &str,
    idempotency_key: &str,
) -> String {
    format!(
        "coach_mutation_replay:{}:{}",
        normalized_account_id, idempotency_key
    )
}

fn coach_replayed_idempotent_response_from_auth_lookup(
    stored_replay: Option<(&str, &str)>,
    has_cross_command_conflict: bool,
    request_fingerprint: &str,
) -> ApiResult<Option<Response>> {
    if let Some((stored_request_fingerprint, response_json_text)) = stored_replay {
        if stored_request_fingerprint != request_fingerprint {
            return Err(ApiError::bad_request(
                "Idempotency-Key reused with different coach request parameters",
            ));
        }
        let response_json =
            serde_json::from_str::<Value>(response_json_text.trim()).map_err(|error| {
                tracing::error!(error = %error, "coach idempotency replay payload decode failed");
                ApiError::internal("coach idempotency store unavailable")
            })?;
        return Ok(Some(json_no_store_response(
            coach_response_with_replay_flag(response_json, true),
        )));
    }
    if has_cross_command_conflict {
        return Err(ApiError::bad_request(
            "Idempotency-Key reused for a different coach command",
        ));
    }
    Ok(None)
}

async fn coach_find_replayed_idempotent_response(
    state: &AppState,
    account_id: &str,
    command: &str,
    idempotency_key: &str,
    request_fingerprint: &str,
) -> ApiResult<Option<Response>> {
    let normalized_account_id = account_id.trim().to_ascii_lowercase();
    if let Some(auth_runtime) = state.auth.as_ref() {
        let row = sqlx::query(
            "SELECT request_fingerprint, response_json::text AS response_json_text \
             FROM auth_coach_mutation_replays \
             WHERE account_id=$1 AND command=$2 AND idempotency_key=$3 \
             LIMIT 1",
        )
        .bind(normalized_account_id.as_str())
        .bind(command)
        .bind(idempotency_key)
        .fetch_optional(auth_runtime.pool())
        .await
        .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?;
        let has_conflict = coach_auth_has_cross_command_idempotency_reuse(
            auth_runtime,
            normalized_account_id.as_str(),
            command,
            idempotency_key,
        )
        .await
        .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?;
        let stored_replay = row
            .as_ref()
            .map(|existing| {
                let stored_request_fingerprint = existing
                    .try_get::<String, _>("request_fingerprint")
                    .map_err(|error| {
                        coach_storage_error("coach idempotency store unavailable", error)
                    })?;
                let response_json_text = existing
                    .try_get::<String, _>("response_json_text")
                    .map_err(|error| {
                        coach_storage_error("coach idempotency store unavailable", error)
                    })?;
                Ok::<(String, String), ApiError>((stored_request_fingerprint, response_json_text))
            })
            .transpose()?;
        return coach_replayed_idempotent_response_from_auth_lookup(
            stored_replay
                .as_ref()
                .map(|(stored_request_fingerprint, response_json_text)| {
                    (
                        stored_request_fingerprint.as_str(),
                        response_json_text.as_str(),
                    )
                }),
            has_conflict,
            request_fingerprint,
        );
    }

    let cache_key =
        coach_mutation_replay_cache_key(normalized_account_id.as_str(), command, idempotency_key);
    let store = coach_mutation_replay_store();
    let cache = store.read().await;
    if let Some(existing) = cache.get(&cache_key) {
        if existing.request_fingerprint != request_fingerprint {
            return Err(ApiError::bad_request(
                "Idempotency-Key reused with different coach request parameters",
            ));
        }
        return Ok(Some(json_no_store_response(
            coach_response_with_replay_flag(existing.response_json.clone(), true),
        )));
    }
    if coach_in_memory_has_cross_command_idempotency_reuse(
        &cache,
        normalized_account_id.as_str(),
        command,
        idempotency_key,
    ) {
        return Err(ApiError::bad_request(
            "Idempotency-Key reused for a different coach command",
        ));
    }
    Ok(None)
}

async fn coach_store_or_replay_idempotent_response(
    state: &AppState,
    account_id: &str,
    command: &str,
    idempotency_key: &str,
    request_fingerprint: &str,
    response_json: Value,
) -> ApiResult<Response> {
    let normalized_account_id = account_id.trim().to_ascii_lowercase();
    if let Some(auth_runtime) = state.auth.as_ref() {
        let mut tx =
            auth_runtime.pool().begin().await.map_err(|error| {
                coach_storage_error("coach idempotency store unavailable", error)
            })?;
        sqlx::query("SELECT pg_advisory_xact_lock(hashtext($1))")
            .bind(coach_auth_mutation_replay_lock_key(
                normalized_account_id.as_str(),
                idempotency_key,
            ))
            .execute(&mut *tx)
            .await
            .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?;
        let has_conflict = sqlx::query(
            "SELECT 1 \
             FROM auth_coach_mutation_replays \
             WHERE account_id=$1 AND idempotency_key=$2 AND command<>$3 \
             LIMIT 1",
        )
        .bind(normalized_account_id.as_str())
        .bind(idempotency_key)
        .bind(command)
        .fetch_optional(&mut *tx)
        .await
        .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?
        .is_some();
        if has_conflict {
            tx.rollback().await.map_err(|error| {
                coach_storage_error("coach idempotency store unavailable", error)
            })?;
            return Err(ApiError::bad_request(
                "Idempotency-Key reused for a different coach command",
            ));
        }
        let insert_result = sqlx::query(
            "INSERT INTO auth_coach_mutation_replays \
             (account_id, command, idempotency_key, request_fingerprint, response_json) \
             VALUES ($1, $2, $3, $4, $5::jsonb) \
             ON CONFLICT (account_id, command, idempotency_key) DO NOTHING",
        )
        .bind(normalized_account_id.as_str())
        .bind(command)
        .bind(idempotency_key)
        .bind(request_fingerprint)
        .bind(response_json.to_string())
        .execute(&mut *tx)
        .await
        .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?;
        if insert_result.rows_affected() > 0 {
            tx.commit().await.map_err(|error| {
                coach_storage_error("coach idempotency store unavailable", error)
            })?;
            return Ok(json_no_store_response(coach_response_with_replay_flag(
                response_json,
                false,
            )));
        }
        let row = sqlx::query(
            "SELECT request_fingerprint, response_json::text AS response_json_text \
             FROM auth_coach_mutation_replays \
             WHERE account_id=$1 AND command=$2 AND idempotency_key=$3 \
             LIMIT 1",
        )
        .bind(normalized_account_id.as_str())
        .bind(command)
        .bind(idempotency_key)
        .fetch_optional(&mut *tx)
        .await
        .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?
        .ok_or_else(|| ApiError::internal("coach idempotency replay missing"))?;
        let stored_request_fingerprint = row
            .try_get::<String, _>("request_fingerprint")
            .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?;
        if stored_request_fingerprint != request_fingerprint {
            return Err(ApiError::bad_request(
                "Idempotency-Key reused with different coach request parameters",
            ));
        }
        let response_json_text = row
            .try_get::<String, _>("response_json_text")
            .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?;
        let stored_response_json = serde_json::from_str::<Value>(response_json_text.trim())
            .map_err(|error| {
                tracing::error!(error = %error, "coach idempotency replay payload decode failed");
                ApiError::internal("coach idempotency store unavailable")
            })?;
        tx.commit()
            .await
            .map_err(|error| coach_storage_error("coach idempotency store unavailable", error))?;
        return Ok(json_no_store_response(coach_response_with_replay_flag(
            stored_response_json,
            true,
        )));
    }

    let cache_key =
        coach_mutation_replay_cache_key(normalized_account_id.as_str(), command, idempotency_key);
    let store = coach_mutation_replay_store();
    let mut cache = store.write().await;
    if let Some(existing) = cache.get(&cache_key) {
        if existing.request_fingerprint != request_fingerprint {
            return Err(ApiError::bad_request(
                "Idempotency-Key reused with different coach request parameters",
            ));
        }
        return Ok(json_no_store_response(coach_response_with_replay_flag(
            existing.response_json.clone(),
            true,
        )));
    }
    if coach_in_memory_has_cross_command_idempotency_reuse(
        &cache,
        normalized_account_id.as_str(),
        command,
        idempotency_key,
    ) {
        return Err(ApiError::bad_request(
            "Idempotency-Key reused for a different coach command",
        ));
    }
    if cache.len() >= COACH_MUTATION_REPLAY_MAX_ENTRIES {
        if let Some(oldest_key) = cache
            .iter()
            .min_by_key(|(_, entry)| entry.stored_at_epoch_ms)
            .map(|(key, _)| key.clone())
        {
            cache.remove(&oldest_key);
        }
    }
    cache.insert(
        cache_key,
        CoachMutationReplayEntry {
            request_fingerprint: request_fingerprint.to_string(),
            response_json: response_json.clone(),
            stored_at_epoch_ms: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis(),
        },
    );
    Ok(json_no_store_response(response_json))
}

