fn coach_operator_feed_health_payload(feed_health: &CoachCatalogOperatorFeedHealth) -> Value {
    json!({
        "operator_id": feed_health.operator_id,
        "operator_name": feed_health.operator_name,
        "operator_integration_mode": feed_health.operator_integration_mode,
        "feed_kind": feed_health.feed_kind,
        "source_kind": feed_health.source_kind,
        "sync_status": feed_health.sync_status,
        "freshness_status": feed_health.freshness_status,
        "last_attempted_at": feed_health.last_attempted_at_iso,
        "last_succeeded_at": feed_health.last_succeeded_at_iso,
        "freshness_expires_at": feed_health.freshness_expires_at_iso,
        "records_ingested": feed_health.records_ingested,
        "error_message": feed_health.error_message
    })
}

fn coach_operator_feed_health_summary_payload(
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> Value {
    let total_operators = feed_health
        .iter()
        .map(|entry| entry.operator_id.as_str())
        .collect::<HashSet<_>>()
        .len();
    let degraded_feeds = feed_health
        .iter()
        .filter(|entry| !coach_operator_feed_sync_is_healthy(&entry.sync_status))
        .count();
    let stale_feeds = feed_health
        .iter()
        .filter(|entry| coach_partner_feed_has_staleness_risk(entry))
        .count();
    let healthy_operators = feed_health
        .iter()
        .fold(HashMap::<&str, bool>::new(), |mut acc, entry| {
            let healthy = coach_operator_feed_sync_is_healthy(&entry.sync_status)
                && coach_operator_feed_freshness_is_healthy(&entry.freshness_status);
            acc.entry(entry.operator_id.as_str())
                .and_modify(|current| *current = *current && healthy)
                .or_insert(healthy);
            acc
        })
        .values()
        .filter(|healthy| **healthy)
        .count();
    json!({
        "operators_total": total_operators,
        "healthy_operators": healthy_operators,
        "degraded_feeds": degraded_feeds,
        "stale_feeds": stale_feeds
    })
}

fn coach_operator_feed_health_response_payload(
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> Value {
    let mut ordered = feed_health.to_vec();
    ordered.sort_by(coach_operator_feed_health_cmp);
    json!({
        "generated_at": now_rfc3339(),
        "summary": coach_operator_feed_health_summary_payload(feed_health),
        "feeds": ordered
            .iter()
            .map(coach_operator_feed_health_payload)
            .collect::<Vec<_>>(),
    })
}

fn coach_operator_feed_health_sync_rank(status: &str) -> u8 {
    if matches!(status, "error" | "failed") {
        return 3;
    }
    if matches!(status, "running" | "pending" | "warning" | "degraded") {
        return 2;
    }
    if matches!(status, "ok" | "succeeded" | "healthy") {
        return 0;
    }
    1
}

fn coach_operator_feed_health_freshness_rank(status: &str) -> u8 {
    if status == "stale" {
        return 2;
    }
    if matches!(status, "expiring" | "aging") {
        return 1;
    }
    0
}

fn coach_operator_feed_sync_is_healthy(status: &str) -> bool {
    matches!(status.trim(), "ok" | "succeeded" | "healthy")
}

fn coach_operator_feed_freshness_is_healthy(status: &str) -> bool {
    matches!(status.trim(), "fresh" | "missing")
}

fn coach_operator_feed_requires_attention(feed: &CoachCatalogOperatorFeedHealth) -> bool {
    !coach_operator_feed_sync_is_healthy(&feed.sync_status)
        || coach_partner_feed_has_staleness_risk(feed)
}

fn coach_operator_feed_health_cmp(
    left: &CoachCatalogOperatorFeedHealth,
    right: &CoachCatalogOperatorFeedHealth,
) -> std::cmp::Ordering {
    coach_operator_feed_health_sync_rank(&right.sync_status)
        .cmp(&coach_operator_feed_health_sync_rank(&left.sync_status))
        .then_with(|| {
            coach_operator_feed_health_freshness_rank(&right.freshness_status).cmp(
                &coach_operator_feed_health_freshness_rank(&left.freshness_status),
            )
        })
        .then_with(|| right.last_attempted_at_iso.cmp(&left.last_attempted_at_iso))
        .then_with(|| left.operator_name.cmp(&right.operator_name))
        .then_with(|| left.feed_kind.cmp(&right.feed_kind))
        .then_with(|| left.source_kind.cmp(&right.source_kind))
        .then_with(|| left.operator_id.cmp(&right.operator_id))
}

fn coach_top_feed_error_blockers(
    feeds: &[CoachCatalogOperatorFeedHealth],
    limit: usize,
) -> Vec<String> {
    let mut ordered = feeds.iter().collect::<Vec<_>>();
    ordered.sort_by(|left, right| coach_operator_feed_health_cmp(left, right));
    ordered
        .into_iter()
        .filter_map(|feed| feed.error_message.as_deref())
        .take(limit)
        .map(str::to_string)
        .collect()
}

fn coach_collect_admin_partner_base_operators(
    feed_health: &[CoachCatalogOperatorFeedHealth],
) -> Vec<CoachAdminPartnerBaseOperator> {
    if feed_health.is_empty() {
        return vec![
            CoachAdminPartnerBaseOperator {
                operator_id: "op_demo_express".to_string(),
                operator_name: "Demo Express".to_string(),
                integration_mode: "hybrid".to_string(),
                feeds: Vec::new(),
            },
            CoachAdminPartnerBaseOperator {
                operator_id: "op_border_runner".to_string(),
                operator_name: "Border Runner".to_string(),
                integration_mode: "api".to_string(),
                feeds: Vec::new(),
            },
            CoachAdminPartnerBaseOperator {
                operator_id: "op_northern_connector".to_string(),
                operator_name: "Northern Connector".to_string(),
                integration_mode: "feed_only".to_string(),
                feeds: Vec::new(),
            },
        ];
    }
    let mut grouped = BTreeMap::<String, CoachAdminPartnerBaseOperator>::new();
    for feed in feed_health {
        grouped
            .entry(feed.operator_id.clone())
            .and_modify(|entry| entry.feeds.push(feed.clone()))
            .or_insert_with(|| CoachAdminPartnerBaseOperator {
                operator_id: feed.operator_id.clone(),
                operator_name: feed.operator_name.clone(),
                integration_mode: feed.operator_integration_mode.clone(),
                feeds: vec![feed.clone()],
            });
    }
    for operator in grouped.values_mut() {
        operator.feeds.sort_by(coach_operator_feed_health_cmp);
    }
    grouped.into_values().collect()
}

fn coach_admin_partner_default_workflow_status(
    operator: &CoachAdminPartnerBaseOperator,
) -> &'static str {
    if operator.operator_id.contains("demo_express") {
        "approved"
    } else if operator.operator_id.contains("border_runner") {
        "in_review"
    } else if operator.integration_mode == "feed_only"
        || operator
            .feeds
            .iter()
            .any(coach_operator_feed_requires_attention)
    {
        "action_required"
    } else {
        "approved"
    }
}

fn coach_admin_partner_document_payload(
    operator_id: &str,
    document_key: &str,
    label: &str,
    status: &str,
    required: bool,
    expires_at: Option<String>,
) -> Value {
    json!({
        "document_id": coach_scoped_resource_id("partnerdoc", &format!("{operator_id}|{document_key}")),
        "document_key": document_key,
        "label": label,
        "status": status,
        "required": required,
        "expires_at": expires_at,
    })
}

fn coach_partner_document_expiry_at(
    now: chrono::DateTime<chrono::Utc>,
    days_from_now: i64,
) -> String {
    now.date_naive()
        .checked_add_signed(chrono::TimeDelta::days(days_from_now))
        .expect("partner document expiry date should compute")
        .and_hms_opt(0, 0, 0)
        .expect("partner document expiry time should build")
        .and_utc()
        .to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
}

