fn coach_admin_partner_feed_summary_payload(feeds: &[CoachCatalogOperatorFeedHealth]) -> Value {
    let last_succeeded_at = feeds
        .iter()
        .filter_map(|feed| feed.last_succeeded_at_iso.as_deref())
        .max()
        .map(str::to_string);
    let degraded_feeds = feeds
        .iter()
        .filter(|feed| !coach_operator_feed_sync_is_healthy(&feed.sync_status))
        .count();
    let stale_feeds = feeds
        .iter()
        .filter(|feed| !coach_operator_feed_freshness_is_healthy(&feed.freshness_status))
        .count();
    json!({
        "feeds_total": feeds.len(),
        "degraded_feeds": degraded_feeds,
        "stale_feeds": stale_feeds,
        "last_succeeded_at": last_succeeded_at,
    })
}

fn coach_admin_partner_blockers(
    workflow_status: &str,
    documents: &[Value],
    feeds: &[CoachCatalogOperatorFeedHealth],
) -> Vec<String> {
    let mut blockers = Vec::<String>::new();
    if workflow_status == "draft" {
        blockers.push("Owner not assigned yet.".to_string());
    }
    let missing_required_documents = documents
        .iter()
        .filter(|document| {
            document["required"].as_bool().unwrap_or(false)
                && matches!(
                    document["status"].as_str(),
                    Some("missing" | "rejected" | "expired")
                )
        })
        .count();
    if missing_required_documents > 0 {
        blockers.push(format!(
            "{missing_required_documents} required document(s) still missing or rejected."
        ));
    }
    for issue in coach_top_feed_error_blockers(feeds, 2) {
        blockers.push(issue.to_string());
    }
    if workflow_status == "suspended" {
        blockers.push("Operator suspended from coach payouts and ticketing.".to_string());
    }
    blockers
}

fn coach_admin_partner_next_action_label(
    workflow_status: &str,
    blockers: &[String],
) -> &'static str {
    if workflow_status == "approved" && blockers.is_empty() {
        "Monitor feed health and renewal dates"
    } else {
        match workflow_status {
            "draft" => "Claim operator and request onboarding documents",
            "in_review" => "Complete KYB review and certification checks",
            "action_required" => "Request corrected documents and rerun certification",
            "suspended" => "Resolve compliance blockers before reactivation",
            _ => "Request operator remediation",
        }
    }
}

fn coach_admin_partner_onboarding_record_payload(
    operator: &CoachAdminPartnerBaseOperator,
    action_entry: Option<&CoachAdminPartnerOnboardingActionEntry>,
) -> Value {
    let workflow_status = action_entry
        .map(|entry| entry.workflow_status.as_str())
        .unwrap_or_else(|| coach_admin_partner_default_workflow_status(operator));
    let documents = coach_admin_partner_documents(operator, workflow_status);
    let capabilities = coach_admin_partner_capabilities(operator, workflow_status);
    let checklist = coach_admin_partner_checklist(workflow_status);
    let blockers =
        coach_admin_partner_blockers(workflow_status, &documents, operator.feeds.as_slice());
    let missing_documents = documents
        .iter()
        .filter(|document| {
            document["required"].as_bool().unwrap_or(false)
                && matches!(
                    document["status"].as_str(),
                    Some("missing" | "rejected" | "expired")
                )
        })
        .count();
    let expiring_documents = documents
        .iter()
        .filter(|document| matches!(document["status"].as_str(), Some("expiring")))
        .count();
    json!({
        "operator_id": operator.operator_id,
        "operator_name": operator.operator_name,
        "integration_mode": operator.integration_mode,
        "workflow_status": workflow_status,
        "last_action": action_entry
            .map(|entry| entry.last_action.as_str())
            .unwrap_or("seed"),
        "owner_account_id": action_entry.and_then(|entry| entry.owner_account_id.clone()),
        "due_at": action_entry
            .and_then(|entry| entry.due_at.clone())
            .or_else(|| {
                if matches!(workflow_status, "in_review" | "action_required") {
                    Some(default_coach_admin_partner_due_at())
                } else {
                    None
                }
            }),
        "updated_at": action_entry
            .map(|entry| entry.updated_at.clone())
            .unwrap_or_else(now_rfc3339),
        "updated_by_account_id": action_entry
            .map(|entry| entry.updated_by_account_id.clone()),
        "note": action_entry.and_then(|entry| entry.note.clone()),
        "missing_documents": missing_documents,
        "expiring_documents": expiring_documents,
        "feed_summary": coach_admin_partner_feed_summary_payload(operator.feeds.as_slice()),
        "documents": documents,
        "capabilities": capabilities,
        "checklist": checklist,
        "blockers": blockers,
        "next_action": coach_admin_partner_next_action_label(workflow_status, &blockers),
    })
}

fn coach_admin_partner_onboarding_summary_payload(records: &[Value]) -> Value {
    json!({
        "operators_total": records.len(),
        "draft_operators": records.iter().filter(|record| record["workflow_status"].as_str() == Some("draft")).count(),
        "in_review_operators": records.iter().filter(|record| record["workflow_status"].as_str() == Some("in_review")).count(),
        "action_required_operators": records.iter().filter(|record| record["workflow_status"].as_str() == Some("action_required")).count(),
        "approved_operators": records.iter().filter(|record| record["workflow_status"].as_str() == Some("approved")).count(),
        "suspended_operators": records.iter().filter(|record| record["workflow_status"].as_str() == Some("suspended")).count(),
        "missing_documents": records
            .iter()
            .map(|record| record["missing_documents"].as_u64().unwrap_or_default())
            .sum::<u64>(),
        "expiring_documents": records
            .iter()
            .map(|record| record["expiring_documents"].as_u64().unwrap_or_default())
            .sum::<u64>(),
    })
}

fn coach_admin_partner_matches_query(record: &Value, query: &str) -> bool {
    let query = query.trim().to_ascii_lowercase();
    if query.is_empty() {
        return true;
    }
    [
        record["operator_id"].as_str().unwrap_or_default(),
        record["operator_name"].as_str().unwrap_or_default(),
        record["integration_mode"].as_str().unwrap_or_default(),
        record["workflow_status"].as_str().unwrap_or_default(),
        record["note"].as_str().unwrap_or_default(),
    ]
    .iter()
    .any(|candidate| candidate.to_ascii_lowercase().contains(query.as_str()))
}

async fn coach_collect_admin_partner_onboarding_records(state: &AppState) -> ApiResult<Vec<Value>> {
    let feed_health = coach_catalog_feed_health_best_effort(state)
        .await
        .unwrap_or_default();
    let action_map = coach_load_admin_partner_onboarding_action_map(state).await?;
    let records = coach_collect_admin_partner_base_operators(feed_health.as_slice())
        .into_iter()
        .map(|operator| {
            coach_admin_partner_onboarding_record_payload(
                &operator,
                action_map.get(operator.operator_id.as_str()),
            )
        })
        .collect::<Vec<_>>();
    Ok(coach_sort_admin_partner_onboarding_records(records))
}

fn coach_sort_admin_partner_onboarding_records(mut records: Vec<Value>) -> Vec<Value> {
    records.sort_by(|left, right| {
        left["workflow_status"]
            .as_str()
            .unwrap_or_default()
            .cmp(right["workflow_status"].as_str().unwrap_or_default())
            .then_with(|| {
                left["operator_name"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(right["operator_name"].as_str().unwrap_or_default())
            })
            .then_with(|| {
                left["operator_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(right["operator_id"].as_str().unwrap_or_default())
            })
    });
    records
}

fn coach_admin_disruption_feed_issue_count(feeds: &[CoachCatalogOperatorFeedHealth]) -> usize {
    feeds
        .iter()
        .filter(|feed| coach_operator_feed_requires_attention(feed))
        .count()
}

fn coach_admin_disruption_boarding_attention_count(
    denied_count: i64,
    revoked_count: i64,
    no_show_count: i64,
    duplicate_count: i64,
) -> i64 {
    denied_count + revoked_count + no_show_count + duplicate_count
}

fn coach_admin_disruption_default_workflow_status(
    feed_issue_count: usize,
    denied_count: i64,
    revoked_count: i64,
    no_show_count: i64,
    duplicate_count: i64,
) -> &'static str {
    if feed_issue_count > 0
        || coach_admin_disruption_boarding_attention_count(
            denied_count,
            revoked_count,
            no_show_count,
            duplicate_count,
        ) > 0
    {
        "monitoring"
    } else {
        "scheduled"
    }
}

fn coach_admin_disruption_severity(
    disruption_kind: Option<&str>,
    delay_minutes: Option<i64>,
    feed_issue_count: usize,
    denied_count: i64,
    revoked_count: i64,
    no_show_count: i64,
    duplicate_count: i64,
) -> &'static str {
    if disruption_kind == Some("cancelled") {
        return "critical";
    }
    if delay_minutes.unwrap_or_default() >= 60 {
        return "high";
    }
    if delay_minutes.unwrap_or_default() > 0
        || feed_issue_count > 0
        || coach_admin_disruption_boarding_attention_count(
            denied_count,
            revoked_count,
            no_show_count,
            duplicate_count,
        ) > 0
    {
        return "medium";
    }
    "low"
}

fn coach_admin_disruption_next_action_label(
    workflow_status: &str,
    disruption_kind: Option<&str>,
    delay_minutes: Option<i64>,
    queued_reaccommodation_count: i64,
    eligible_booking_count: usize,
    feed_issue_count: usize,
    boarding_attention_count: i64,
) -> &'static str {
    if queued_reaccommodation_count > 0 {
        return "Monitor the reissue queue and operator confirmation";
    }
    if disruption_kind == Some("cancelled") && eligible_booking_count > 0 {
        return "Queue reaccommodation for impacted bookings";
    }
    if disruption_kind == Some("cancelled") {
        return "Resolve impacted bookings manually";
    }
    if delay_minutes.unwrap_or_default() >= 45 && eligible_booking_count > 0 {
        return "Queue reaccommodation if the delay persists";
    }
    if workflow_status == "monitoring" && feed_issue_count > 0 {
        return "Verify operator realtime feed and station comms";
    }
    if workflow_status == "monitoring" && boarding_attention_count > 0 {
        return "Inspect boarding evidence, manifest state and passenger scan exceptions";
    }
    "No action required"
}

fn coach_admin_disruption_record_payload(
    trip: &Value,
    operator_id: &str,
    feeds: &[CoachCatalogOperatorFeedHealth],
    eligible_booking_count: usize,
    affected_booking_count: usize,
    action_entry: Option<&CoachAdminDisruptionActionEntry>,
) -> Value {
    let denied_count = trip
        .get("denied_count")
        .and_then(Value::as_i64)
        .unwrap_or_default();
    let revoked_count = trip
        .get("revoked_count")
        .and_then(Value::as_i64)
        .unwrap_or_default();
    let no_show_count = trip
        .get("no_show_count")
        .and_then(Value::as_i64)
        .unwrap_or_default();
    let duplicate_count = trip
        .get("duplicate_count")
        .and_then(Value::as_i64)
        .unwrap_or_default();
    let feed_issue_count = coach_admin_disruption_feed_issue_count(feeds);
    let boarding_attention_count = coach_admin_disruption_boarding_attention_count(
        denied_count,
        revoked_count,
        no_show_count,
        duplicate_count,
    );
    let default_workflow_status = coach_admin_disruption_default_workflow_status(
        feed_issue_count,
        denied_count,
        revoked_count,
        no_show_count,
        duplicate_count,
    );
    let workflow_status = action_entry
        .map(|entry| entry.workflow_status.as_str())
        .unwrap_or(default_workflow_status);
    let disruption_kind = action_entry.and_then(|entry| entry.disruption_kind.clone());
    let delay_minutes = action_entry.and_then(|entry| entry.delay_minutes);
    let queued_reaccommodation_count = action_entry
        .map(|entry| entry.queued_reaccommodation_count)
        .unwrap_or_default();
    let severity = coach_admin_disruption_severity(
        disruption_kind.as_deref(),
        delay_minutes,
        feed_issue_count,
        denied_count,
        revoked_count,
        no_show_count,
        duplicate_count,
    );
    let blockers = coach_top_feed_error_blockers(feeds, 2);
    let booking_id = (affected_booking_count == 1)
        .then(|| {
            trip.get("booking_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string)
        })
        .flatten();
    json!({
        "trip_id": trip.get("trip_id").and_then(Value::as_str).unwrap_or_default(),
        "journey_id": trip.get("journey_id").and_then(Value::as_str).unwrap_or_default(),
        "booking_id": booking_id,
        "operator_id": operator_id,
        "operator_name": trip.get("operator_name").and_then(Value::as_str).unwrap_or_default(),
        "from": trip.get("from").and_then(Value::as_str).unwrap_or_default(),
        "to": trip.get("to").and_then(Value::as_str).unwrap_or_default(),
        "departure_at": trip.get("departure_at").and_then(Value::as_str).unwrap_or_default(),
        "arrival_at": trip.get("arrival_at").and_then(Value::as_str).unwrap_or_default(),
        "gate_label": trip.get("gate_label").and_then(Value::as_str).unwrap_or_default(),
        "vehicle_label": trip.get("vehicle_label").and_then(Value::as_str).unwrap_or_default(),
        "manifest_count": trip.get("manifest_count").and_then(Value::as_i64).unwrap_or_default(),
        "boarded_count": trip.get("boarded_count").and_then(Value::as_i64).unwrap_or_default(),
        "denied_count": denied_count,
        "revoked_count": revoked_count,
        "no_show_count": no_show_count,
        "duplicate_count": duplicate_count,
        "pending_count": trip.get("pending_count").and_then(Value::as_i64).unwrap_or_default(),
        "workflow_status": workflow_status,
        "disruption_kind": disruption_kind,
        "delay_minutes": delay_minutes,
        "severity": severity,
        "affected_booking_count": affected_booking_count,
        "eligible_reaccommodation_count": eligible_booking_count,
        "queued_reaccommodation_count": queued_reaccommodation_count,
        "feed_issue_count": feed_issue_count,
        "last_action": action_entry
            .map(|entry| entry.last_action.as_str())
            .unwrap_or("seed"),
        "updated_at": action_entry
            .map(|entry| entry.updated_at.clone())
            .unwrap_or_else(now_rfc3339),
        "updated_by_account_id": action_entry
            .map(|entry| entry.updated_by_account_id.clone()),
        "reason": action_entry.and_then(|entry| entry.reason.clone()),
        "note": action_entry.and_then(|entry| entry.note.clone()),
        "blockers": blockers,
        "next_action": coach_admin_disruption_next_action_label(
            workflow_status,
            disruption_kind.as_deref(),
            delay_minutes,
            queued_reaccommodation_count,
            eligible_booking_count,
            feed_issue_count,
            boarding_attention_count,
        ),
    })
}

