async fn coach_collect_admin_disruption_records(state: &AppState) -> ApiResult<Vec<Value>> {
    let feed_health = coach_catalog_feed_health_best_effort(state)
        .await
        .unwrap_or_default();
    let action_map = coach_load_admin_disruption_action_map(state).await?;
    let event_map = coach_load_boarding_event_map(state, None).await?;
    let runtime_aggregates = coach_list_boardable_runtime_booking_aggregates_global(state)
        .await
        .map_err(|error| coach_storage_error("coach admin disruption store unavailable", error))?;

    let records = if runtime_aggregates.is_empty() {
        coach_demo_crew_trip_seeds()
            .into_iter()
            .filter_map(|crew_trip_seed| {
                let booking_seed = coach_demo_booking_seed(crew_trip_seed.booking_id)?;
                let operator_id = coach_demo_booking_operator_id(&booking_seed);
                let trip = coach_demo_crew_trip_payload(&crew_trip_seed, &booking_seed, &event_map);
                let eligible_booking_count =
                    if coach_change_options_for_seed(&booking_seed).is_empty() {
                        0
                    } else {
                        1
                    };
                Some(coach_admin_disruption_record_payload(
                    &trip,
                    operator_id,
                    &coach_filter_operator_feed_health_for_operator_id(&feed_health, operator_id),
                    eligible_booking_count,
                    1,
                    action_map.get(crew_trip_seed.trip_id),
                ))
            })
            .collect::<Vec<_>>()
    } else {
        coach_runtime_trip_groups_for_request(state, runtime_aggregates)
            .await
            .map_err(|error| {
                coach_storage_error("coach admin disruption store unavailable", error)
            })?
            .into_iter()
            .map(|(trip_id, aggregates)| {
                let operator_id = coach_runtime_trip_group_operator_id(&aggregates, &trip_id);
                let eligible_booking_count = aggregates
                    .iter()
                    .filter(|aggregate| !coach_change_options_from_aggregate(aggregate).is_empty())
                    .count();
                let trip = coach_runtime_crew_trip_payload(&aggregates, &trip_id, &event_map);
                coach_admin_disruption_record_payload(
                    &trip,
                    &operator_id,
                    &coach_filter_operator_feed_health_for_operator_id(&feed_health, &operator_id),
                    eligible_booking_count,
                    aggregates.len(),
                    action_map.get(trip_id.as_str()),
                )
            })
            .collect::<Vec<_>>()
    };
    Ok(coach_sort_admin_disruption_records(records))
}

fn coach_sort_admin_disruption_records(mut records: Vec<Value>) -> Vec<Value> {
    records.sort_by(|left, right| {
        right["severity"]
            .as_str()
            .unwrap_or_default()
            .cmp(left["severity"].as_str().unwrap_or_default())
            .then_with(|| {
                left["departure_at"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(right["departure_at"].as_str().unwrap_or_default())
            })
            .then_with(|| {
                left["trip_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(right["trip_id"].as_str().unwrap_or_default())
            })
    });
    records
}

