fn coach_offer_payload(offer_id: &str, passengers: u8) -> Value {
    let normalized_offer_id = offer_id.trim();
    let night_service = coach_offer_is_night_service(normalized_offer_id);
    json!({
        "offer_id": normalized_offer_id,
        "operator_id": coach_offer_operator_id(normalized_offer_id),
        "itinerary_id": coach_offer_itinerary_id(normalized_offer_id),
        "currency": "EUR",
        "total_minor_units": coach_offer_total_minor_units(normalized_offer_id, passengers),
        "seats_requested": passengers,
        "hold_supported": true,
        "changeable": true,
        "refundable": !night_service,
        "expires_at": coach_future_expiry_iso(COACH_OFFER_TTL_SECS),
        "seat_map_available": true,
        "baggage_rule": if night_service {
            "1 cabin bag included, checked bag extra"
        } else {
            "1 cabin bag and 1 checked bag included"
        }
    })
}

async fn coach_offer_payload_for_request(
    state: &AppState,
    account_id: Option<&str>,
    offer_id: &str,
    passengers: u8,
) -> Value {
    if let Some(account_id) = account_id {
        match coach_find_offer_snapshot_for_request(state, account_id, offer_id, passengers).await {
            Ok(Some(snapshot)) => return snapshot.offer_payload,
            Ok(None) => {}
            Err(error) => tracing::warn!(%error, offer_id, "coach offer snapshot lookup failed"),
        }
    }

    let payload = match coach_catalog_offer_payload(state, offer_id, passengers).await {
        Ok(Some(payload)) => payload,
        Ok(None) | Err(_) => coach_offer_payload(offer_id, passengers),
    };
    if let Some(account_id) = account_id {
        if let Err(error) = coach_persist_offer_payload_best_effort(
            state, account_id, offer_id, passengers, &payload, None,
        )
        .await
        {
            tracing::warn!(%error, offer_id, "coach offer snapshot persistence skipped");
        }
    }
    payload
}

async fn coach_catalog_offer_payload(
    state: &AppState,
    offer_id: &str,
    passengers: u8,
) -> Result<Option<Value>, sqlx::Error> {
    let Some(fare_product_id) = coach_catalog_offer_fare_product_id(offer_id) else {
        return Ok(None);
    };
    let Some(auth) = &state.auth else {
        return Ok(None);
    };
    let repo = CoachCatalogRepository::new(auth.pool().clone());
    let Some(basis) = repo
        .find_offer_basis_by_fare_product_id(fare_product_id)
        .await?
    else {
        return Ok(None);
    };
    Ok(Some(coach_catalog_offer_payload_from_basis(
        offer_id, &basis, passengers,
    )))
}

