fn coach_journey_summary_from_offer_snapshot_journey(
    booking_state: &str,
    journey_payload: &Value,
) -> Option<Value> {
    Some(coach_booked_journey_summary_payload_with_trip(
        &CoachBookedJourneySummaryContext {
            trip_id: journey_payload.get("trip_id").and_then(Value::as_str),
            journey_id: journey_payload.get("journey_id").and_then(Value::as_str)?,
            operator_name: journey_payload
                .get("operator_name")
                .and_then(Value::as_str)?,
            from: journey_payload.get("from").and_then(Value::as_str)?,
            to: journey_payload.get("to").and_then(Value::as_str)?,
            departure_at: journey_payload
                .get("departure_at")
                .and_then(Value::as_str)?,
            arrival_at: journey_payload.get("arrival_at").and_then(Value::as_str)?,
            status_label: coach_booking_status_label(booking_state),
        },
    ))
}

async fn coach_booking_journey_summary_payload_for_request(
    state: &AppState,
    account_id: &str,
    booking_id: &str,
    offer_id: &str,
    passengers: u8,
    booking_state: &str,
) -> Result<Value, sqlx::Error> {
    if let Some(snapshot) =
        coach_find_offer_snapshot_for_request(state, account_id, offer_id, passengers).await?
    {
        if let Some(journey_payload) = snapshot.journey_payload.as_ref() {
            if let Some(summary) =
                coach_journey_summary_from_offer_snapshot_journey(booking_state, journey_payload)
            {
                return Ok(summary);
            }
        }
    }

    if let (Some(auth), Some(fare_product_id)) = (
        state.auth.as_ref(),
        coach_catalog_offer_fare_product_id(offer_id),
    ) {
        let repo = CoachCatalogRepository::new(auth.pool().clone());
        if let Some(basis) = repo
            .find_journey_summary_basis_by_fare_product_id(fare_product_id)
            .await?
        {
            let departure_date = chrono::DateTime::<chrono::Utc>::from(SystemTime::now())
                .date_naive()
                .succ_opt()
                .unwrap_or_else(|| {
                    chrono::DateTime::<chrono::Utc>::from(SystemTime::now()).date_naive()
                })
                .format("%Y-%m-%d")
                .to_string();
            let (departure_at, arrival_at) = coach_catalog_departure_arrival_iso(
                &departure_date,
                &basis.departure_time_local,
                basis.duration_minutes,
            )
            .unwrap_or_else(|| {
                (
                    format!("{departure_date}T{}:00Z", basis.departure_time_local.trim()),
                    format!("{departure_date}T{}:00Z", basis.arrival_time_local.trim()),
                )
            });
            let journey_id = coach_catalog_journey_id(&basis.trip_id);
            return Ok(coach_booked_journey_summary_payload_with_trip(
                &CoachBookedJourneySummaryContext {
                    trip_id: Some(basis.trip_id.as_str()),
                    journey_id: &journey_id,
                    operator_name: basis.operator_name.as_str(),
                    from: basis.origin_city_name.as_str(),
                    to: basis.destination_city_name.as_str(),
                    departure_at: &departure_at,
                    arrival_at: &arrival_at,
                    status_label: coach_booking_status_label(booking_state),
                },
            ));
        }
    }

    Ok(coach_generic_journey_summary_payload(
        booking_id,
        offer_id,
        booking_state,
    ))
}

fn coach_hold_payload_with_status(payload: &Value, status: &str) -> Value {
    let mut payload = payload.clone();
    if let Some(object) = payload.as_object_mut() {
        object.insert("status".to_string(), Value::String(status.to_string()));
    }
    payload
}

async fn coach_persist_hold_payload(
    state: &AppState,
    account_id: &str,
    hold_id: &str,
    offer_id: &str,
    passengers: u8,
    request_fingerprint: &str,
    hold_payload: &Value,
) -> Result<(), sqlx::Error> {
    let Some(auth) = &state.auth else {
        return Ok(());
    };
    let operator_reference = hold_payload
        .get("operator_reference")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let expires_at = hold_payload
        .get("expires_at")
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| coach_future_expiry_iso(COACH_HOLD_TTL_SECS));
    let status = hold_payload
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("active");
    let repo = CoachCatalogRepository::new(auth.pool().clone());
    repo.upsert_hold_payload(&CoachHoldPayloadUpsert {
        account_id,
        hold_id,
        offer_id,
        seats_requested: i16::from(passengers),
        operator_reference,
        status,
        request_fingerprint,
        hold_ttl_seconds: COACH_HOLD_TTL_SECS as i32,
        expires_at_iso: expires_at.as_str(),
        hold_payload,
    })
    .await
}

