async fn coach_find_booking_aggregate_for_request(
    state: &AppState,
    account_id: &str,
    booking_id: &str,
) -> Result<Option<CoachStoredBookingAggregate>, sqlx::Error> {
    let Some(snapshot) =
        coach_find_booking_snapshot_for_request(state, account_id, booking_id).await?
    else {
        return Ok(None);
    };
    let tickets =
        coach_list_ticket_payloads_for_booking_request(state, account_id, booking_id).await?;
    Ok(Some(CoachStoredBookingAggregate {
        account_id: snapshot.account_id,
        booking: snapshot.booking_payload,
        offer: snapshot.offer_payload,
        hold: snapshot.hold_payload,
        journey: snapshot.journey_summary_payload,
        passengers_manifest: snapshot.passengers_manifest_payload,
        tickets,
    }))
}

async fn coach_list_booking_aggregates_for_request(
    state: &AppState,
    account_id: &str,
) -> Result<Vec<CoachStoredBookingAggregate>, sqlx::Error> {
    let snapshots = coach_list_booking_snapshots_for_request(state, account_id).await?;
    let mut out = Vec::with_capacity(snapshots.len());
    for snapshot in snapshots {
        let booking_id = snapshot
            .booking_payload
            .get("booking_id")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();
        let tickets = if booking_id.is_empty() {
            Vec::new()
        } else {
            coach_list_ticket_payloads_for_booking_request(state, account_id, &booking_id).await?
        };
        out.push(CoachStoredBookingAggregate {
            account_id: snapshot.account_id,
            booking: snapshot.booking_payload,
            offer: snapshot.offer_payload,
            hold: snapshot.hold_payload,
            journey: snapshot.journey_summary_payload,
            passengers_manifest: snapshot.passengers_manifest_payload,
            tickets,
        });
    }
    Ok(out)
}

async fn coach_list_booking_aggregates_global_for_request(
    state: &AppState,
) -> Result<Vec<CoachStoredBookingAggregate>, sqlx::Error> {
    let snapshots = coach_list_booking_snapshots_global_for_request(state).await?;
    let mut out = Vec::with_capacity(snapshots.len());
    for snapshot in snapshots {
        let booking_id = snapshot
            .booking_payload
            .get("booking_id")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();
        let tickets = if booking_id.is_empty() {
            Vec::new()
        } else {
            coach_list_ticket_payloads_for_booking_any_account_request(state, &booking_id).await?
        };
        out.push(CoachStoredBookingAggregate {
            account_id: snapshot.account_id,
            booking: snapshot.booking_payload,
            offer: snapshot.offer_payload,
            hold: snapshot.hold_payload,
            journey: snapshot.journey_summary_payload,
            passengers_manifest: snapshot.passengers_manifest_payload,
            tickets,
        });
    }
    Ok(out)
}

