fn validate_finite_lat_lon(lat: f64, lon: f64) -> ApiResult<()> {
    if !lat.is_finite() || !lon.is_finite() {
        return Err(ApiError::bad_request("lat/lon must be finite"));
    }
    if !(-90.0..=90.0).contains(&lat) {
        return Err(ApiError::bad_request("lat must be between -90 and 90"));
    }
    if !(-180.0..=180.0).contains(&lon) {
        return Err(ApiError::bad_request("lon must be between -180 and 180"));
    }
    Ok(())
}

fn tomtom_route_summary_metric(route: &Value, key: &str) -> Option<i64> {
    json_number_to_i64(route.get("summary").and_then(|summary| summary.get(key)))
        .map(|value| value.max(0))
}

fn tomtom_route_summary_string<'a>(route: &'a Value, key: &str) -> &'a str {
    route
        .get("summary")
        .and_then(|summary| summary.get(key))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_default()
}

fn select_tomtom_route(routes: &[Value]) -> Option<&Value> {
    routes
        .iter()
        .enumerate()
        .min_by(|left, right| {
            let left_eta = tomtom_route_summary_metric(left.1, "travelTimeInSeconds");
            let right_eta = tomtom_route_summary_metric(right.1, "travelTimeInSeconds");
            match (left_eta, right_eta) {
                (Some(a), Some(b)) => a.cmp(&b),
                (Some(_), None) => std::cmp::Ordering::Less,
                (None, Some(_)) => std::cmp::Ordering::Greater,
                (None, None) => std::cmp::Ordering::Equal,
            }
            .then_with(|| {
                let left_distance = tomtom_route_summary_metric(left.1, "lengthInMeters");
                let right_distance = tomtom_route_summary_metric(right.1, "lengthInMeters");
                match (left_distance, right_distance) {
                    (Some(a), Some(b)) => a.cmp(&b),
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (None, None) => std::cmp::Ordering::Equal,
                }
            })
            .then_with(|| {
                let left_delay = tomtom_route_summary_metric(left.1, "trafficDelayInSeconds");
                let right_delay = tomtom_route_summary_metric(right.1, "trafficDelayInSeconds");
                match (left_delay, right_delay) {
                    (Some(a), Some(b)) => a.cmp(&b),
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (None, None) => std::cmp::Ordering::Equal,
                }
            })
            .then_with(|| {
                tomtom_route_summary_string(left.1, "departureTime")
                    .cmp(tomtom_route_summary_string(right.1, "departureTime"))
            })
            .then_with(|| {
                tomtom_route_summary_string(left.1, "arrivalTime")
                    .cmp(tomtom_route_summary_string(right.1, "arrivalTime"))
            })
            .then_with(|| left.0.cmp(&right.0))
        })
        .map(|(_, route)| route)
}

fn json_number_to_i64(value: Option<&Value>) -> Option<i64> {
    if let Some(v) = value.and_then(Value::as_i64) {
        return Some(v);
    }
    value
        .and_then(Value::as_u64)
        .and_then(|value| i64::try_from(value).ok())
}

fn round_tomtom_coordinate(value: f64) -> f64 {
    (value * 1_000_000.0).round() / 1_000_000.0
}

fn parse_tomtom_position(value: &Value) -> Option<(f64, f64)> {
    let lat = value.get("lat").and_then(Value::as_f64)?;
    let lon = value.get("lon").and_then(Value::as_f64)?;
    if !lat.is_finite() || !lon.is_finite() {
        return None;
    }
    if !(-90.0..=90.0).contains(&lat) || !(-180.0..=180.0).contains(&lon) {
        return None;
    }
    Some((round_tomtom_coordinate(lat), round_tomtom_coordinate(lon)))
}

#[cfg(test)]
fn sanitize_tomtom_search_payload(value: &Value, limit: usize) -> Value {
    let mut out = Vec::new();
    let Some(items) = value.get("results").and_then(Value::as_array) else {
        return Value::Array(out);
    };
    for item in items {
        let Some(position) = item.get("position").and_then(parse_tomtom_position) else {
            continue;
        };
        let Some(display_name) = item
            .get("address")
            .and_then(|address| address.get("freeformAddress"))
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|text| !text.is_empty())
            .or_else(|| {
                item.get("poi")
                    .and_then(|poi| poi.get("name"))
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|text| !text.is_empty())
            })
        else {
            continue;
        };
        out.push(json!({
            "display_name": display_name,
            "lat": position.0,
            "lon": position.1,
        }));
        if out.len() >= limit {
            break;
        }
    }
    Value::Array(out)
}

fn sanitize_tomtom_route_payload(value: &Value) -> Option<Value> {
    let route = value
        .get("routes")
        .and_then(Value::as_array)
        .and_then(|routes| select_tomtom_route(routes))?;
    let summary = route.get("summary").and_then(Value::as_object);
    let distance_m = json_number_to_i64(summary.and_then(|obj| obj.get("lengthInMeters")))
        .unwrap_or_default()
        .max(0);
    let eta_s = json_number_to_i64(summary.and_then(|obj| obj.get("travelTimeInSeconds")))
        .unwrap_or_default()
        .max(0);
    let traffic_delay_s =
        json_number_to_i64(summary.and_then(|obj| obj.get("trafficDelayInSeconds")))
            .unwrap_or_default()
            .max(0);
    let departure_utc = summary
        .and_then(|obj| obj.get("departureTime"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_default()
        .to_string();
    let arrival_utc = summary
        .and_then(|obj| obj.get("arrivalTime"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_default()
        .to_string();

    let mut points = Vec::new();
    if let Some(legs) = route.get("legs").and_then(Value::as_array) {
        for leg in legs {
            let Some(leg_points) = leg.get("points").and_then(Value::as_array) else {
                continue;
            };
            for point in leg_points {
                let Some((lat, lon)) = parse_tomtom_position(point) else {
                    continue;
                };
                points.push(json!({"lat": lat, "lon": lon}));
                if points.len() >= TOMTOM_ROUTE_POINTS_MAX {
                    break;
                }
            }
            if points.len() >= TOMTOM_ROUTE_POINTS_MAX {
                break;
            }
        }
    }

    Some(json!({
        "distance_m": distance_m,
        "eta_s": eta_s,
        "traffic_delay_s": traffic_delay_s,
        "departure_utc": departure_utc,
        "arrival_utc": arrival_utc,
        "points": points,
    }))
}

fn sanitize_tomtom_flow_segment_payload(value: &Value, radius_m: u32) -> Option<Value> {
    let flow = value.get("flowSegmentData")?;
    let current_speed_kmh = json_number_to_i64(flow.get("currentSpeed"))
        .unwrap_or_default()
        .max(0);
    let free_flow_speed_kmh = json_number_to_i64(flow.get("freeFlowSpeed"))
        .unwrap_or_default()
        .max(0);
    let current_travel_time_s = json_number_to_i64(flow.get("currentTravelTime"))
        .unwrap_or_default()
        .max(0);
    let free_flow_travel_time_s = json_number_to_i64(flow.get("freeFlowTravelTime"))
        .unwrap_or_default()
        .max(0);
    let confidence = flow
        .get("confidence")
        .and_then(Value::as_f64)
        .unwrap_or(0.0);

    Some(json!({
        "current_speed_kmh": current_speed_kmh,
        "free_flow_speed_kmh": free_flow_speed_kmh,
        "current_travel_time_s": current_travel_time_s,
        "free_flow_travel_time_s": free_flow_travel_time_s,
        "confidence": confidence,
        "radius_m": radius_m,
    }))
}

async fn fetch_tomtom_json(
    state: &AppState,
    path: &str,
    query: &[(&str, String)],
    cache_ttl_secs: u64,
) -> ApiResult<Value> {
    let Some(api_key) = tomtom_api_key() else {
        tracing::warn!("BFF_TOMTOM_API_KEY not configured");
        return Err(ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "ride mobility unavailable",
        ));
    };

    let cache_key = geo_lookup_cache_key(path, query, "tomtom");
    if let Some(cached) = state.cached_geo_lookup_json(&cache_key).await {
        return Ok(cached);
    }

    let upstream_base = tomtom_base_url();
    let path_hash = auth::hash_prefix(path);
    let mut url = reqwest::Url::parse(&format!("{}{path}", upstream_base.trim_end_matches('/')))
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream_base,
                "invalid tomtom url"
            );
            ApiError::internal("ride mobility unavailable")
        })?;
    {
        let mut pairs = url.query_pairs_mut();
        for (key, value) in query {
            pairs.append_pair(key, value);
        }
        pairs.append_pair("key", &api_key);
    }

    let resp = state
        .http
        .request(Method::GET, url)
        .header(header::ACCEPT, "application/json")
        .timeout(Duration::from_secs(state.upstream_timeout_secs.max(1)))
        .send()
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream_base,
                "tomtom upstream call failed"
            );
            ApiError::internal("ride mobility unavailable")
        })?;
    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let bytes =
        read_response_body_limited(resp, state.max_upstream_body_bytes, "tomtom", path).await?;
    if !status.is_success() {
        tracing::warn!(
            status = %status,
            path_hash,
            upstream_base,
            "tomtom upstream returned non-success"
        );
        return Err(ApiError::upstream(
            StatusCode::BAD_GATEWAY,
            "ride mobility unavailable",
        ));
    }

    let payload = serde_json::from_slice(&bytes).map_err(|e| {
        tracing::error!(
            error = %e,
            path_hash,
            upstream_base,
            "tomtom upstream returned invalid json"
        );
        ApiError::internal("ride mobility unavailable")
    })?;
    state
        .remember_geo_lookup_json(
            &cache_key,
            &payload,
            Duration::from_secs(cache_ttl_secs.max(1)),
            GEO_LOOKUP_CACHE_MAX_ENTRIES,
        )
        .await;
    Ok(payload)
}

async fn fetch_tomtom_tile(
    state: &AppState,
    path: &str,
    query: &[(&str, String)],
) -> ApiResult<Response> {
    let Some(api_key) = tomtom_api_key() else {
        tracing::warn!("BFF_TOMTOM_API_KEY not configured");
        return Err(ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "ride map unavailable",
        ));
    };

    let upstream_base = tomtom_base_url();
    let path_hash = auth::hash_prefix(path);
    let mut url = reqwest::Url::parse(&format!("{}{path}", upstream_base.trim_end_matches('/')))
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream_base,
                "invalid tomtom tile url"
            );
            ApiError::internal("ride map unavailable")
        })?;
    {
        let mut pairs = url.query_pairs_mut();
        for (key, value) in query {
            pairs.append_pair(key, value);
        }
        pairs.append_pair("key", &api_key);
    }

    let resp = state
        .http
        .request(Method::GET, url)
        .header(header::ACCEPT, "image/png")
        .timeout(Duration::from_secs(state.upstream_timeout_secs.max(1)))
        .send()
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream_base,
                "tomtom tile upstream call failed"
            );
            ApiError::internal("ride map unavailable")
        })?;
    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let content_type = resp
        .headers()
        .get(CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .unwrap_or_default()
        .split(';')
        .next()
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase();
    let bytes =
        read_response_body_limited(resp, state.max_upstream_body_bytes, "tomtom", path).await?;
    if !status.is_success() {
        tracing::warn!(
            status = %status,
            path_hash,
            upstream_base,
            "tomtom tile upstream returned non-success"
        );
        return Err(ApiError::upstream(
            StatusCode::BAD_GATEWAY,
            "ride map unavailable",
        ));
    }

    let content_type = match content_type.as_str() {
        "image/png" => "image/png",
        "image/jpeg" => "image/jpeg",
        "image/webp" => "image/webp",
        _ => {
            tracing::warn!(
                content_type,
                path_hash,
                upstream_base,
                "tomtom tile upstream returned unexpected content type"
            );
            return Err(ApiError::internal("ride map unavailable"));
        }
    };

    let mut response = Response::new(Body::from(bytes));
    *response.status_mut() = StatusCode::OK;
    response
        .headers_mut()
        .insert(CONTENT_TYPE, HeaderValue::from_static(content_type));
    response.headers_mut().insert(
        header::CACHE_CONTROL,
        HeaderValue::from_static("private, max-age=300"),
    );
    response
        .headers_mut()
        .insert(header::VARY, HeaderValue::from_static("Cookie"));
    Ok(response)
}

fn sanitize_chat_push_token_response(value: Value) -> Value {
    let mut out = serde_json::Map::new();
    if let Some(obj) = value.as_object() {
        if let Some(ok) = obj.get("ok").and_then(Value::as_bool) {
            out.insert("ok".to_string(), Value::Bool(ok));
        }
        if let Some(noop) = obj.get("noop").and_then(Value::as_bool) {
            out.insert("noop".to_string(), Value::Bool(noop));
        }
        if let Some(platform) = obj.get("platform").and_then(Value::as_str) {
            out.insert("platform".to_string(), Value::String(platform.to_string()));
        }
    }
    Value::Object(out)
}

fn security_alert_log_hash(raw: &str) -> String {
    let trimmed = raw.trim();
    if trimmed.is_empty() || trimmed == "-" {
        return "-".to_string();
    }
    auth::hash_prefix(trimmed)
}

fn security_alert_hash_preview(alerts: &[String]) -> Vec<String> {
    alerts
        .iter()
        .take(8)
        .map(|item| security_alert_log_hash(item))
        .collect()
}

fn security_alert_item_is_valid(raw: &str) -> bool {
    let (action, counts) = match raw.split_once(':') {
        Some(parts) => parts,
        None => return false,
    };
    if action.is_empty() || counts.is_empty() || action.starts_with('.') || action.ends_with('.') {
        return false;
    }
    if !action.split('.').all(|segment| {
        !segment.is_empty()
            && segment
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '_' || ch == '-')
    }) {
        return false;
    }

    let (count_raw, threshold_raw) = match counts.split_once('/') {
        Some(parts) => parts,
        None => return false,
    };
    if count_raw.is_empty() || threshold_raw.is_empty() {
        return false;
    }
    let Ok(count) = count_raw.parse::<u64>() else {
        return false;
    };
    let Ok(threshold) = threshold_raw.parse::<u64>() else {
        return false;
    };
    threshold > 0 && count <= 1_000_000_000 && threshold <= 1_000_000_000
}

fn security_alert_log_token_is_valid(raw: &str, max_len: usize) -> bool {
    let value = raw.trim();
    !value.is_empty()
        && value.len() <= max_len
        && value.chars().all(|ch| {
            ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-' | ':' | '/' | '+' | '@')
        })
}

fn security_alert_request_context_hashes(headers: &HeaderMap) -> (String, String) {
    let request_id = header_value(headers, "x-request-id").unwrap_or_else(|| "-".to_string());
    let client_ip =
        header_value(headers, TRUSTED_CLIENT_IP_HEADER).unwrap_or_else(|| "-".to_string());
    (
        security_alert_log_hash(&request_id),
        security_alert_log_hash(&client_ip),
    )
}

fn security_alert_ingest_caller_log_fields(headers: &HeaderMap) -> (String, String) {
    let caller_raw =
        header_value(headers, "x-internal-service-id").unwrap_or_else(|| "-".to_string());
    (
        security_alert_safe_log_value(&caller_raw, 64).to_string(),
        security_alert_log_hash(&caller_raw),
    )
}

fn security_alert_safe_log_value(raw: &str, max_len: usize) -> &str {
    let trimmed = raw.trim();
    if trimmed.is_empty() || trimmed.len() > max_len {
        "-"
    } else {
        trimmed
    }
}

fn audit_security_alert_ingest_rejected(
    headers: &HeaderMap,
    payload: &SecurityAlertIngestIn,
    reason: &'static str,
) {
    let source = security_alert_safe_log_value(&payload.source, 128);
    let source_hash = security_alert_log_hash(&payload.source);
    let service_raw = payload.service.as_deref().unwrap_or("-");
    let service = security_alert_safe_log_value(service_raw, 64);
    let service_hash = security_alert_log_hash(service_raw);
    let severity_hash = security_alert_log_hash(payload.severity.as_deref().unwrap_or("-"));
    let timestamp_hash = security_alert_log_hash(payload.timestamp.as_deref().unwrap_or("-"));
    let note_hash = payload
        .note
        .as_deref()
        .map(security_alert_log_hash)
        .unwrap_or_else(|| "-".to_string());
    let alert_hashes = security_alert_hash_preview(&payload.alerts);
    let (request_id_hash, client_ip_hash) = security_alert_request_context_hashes(headers);
    let (caller, caller_hash) = security_alert_ingest_caller_log_fields(headers);

    tracing::warn!(
        security_event = "runtime_security_alert_ingest",
        outcome = "rejected",
        reason = reason,
        caller = caller,
        caller_hash = %caller_hash,
        source = source,
        source_hash = %source_hash,
        service = service,
        service_hash = %service_hash,
        severity_hash = %severity_hash,
        timestamp_hash = %timestamp_hash,
        alerts_count = payload.alerts.len(),
        alerts_hashes = ?alert_hashes,
        note_hash = %note_hash,
        request_id_hash = %request_id_hash,
        client_ip_hash = %client_ip_hash,
        "runtime security alert rejected"
    );
}

fn security_alert_ingest_bad_request(
    headers: &HeaderMap,
    payload: &SecurityAlertIngestIn,
    reason: &'static str,
    detail: &'static str,
) -> ApiError {
    audit_security_alert_ingest_rejected(headers, payload, reason);
    ApiError::bad_request(detail)
}

