#[derive(Debug, Clone)]
struct WsPollBackoff {
    min_delay: Duration,
    max_delay: Duration,
    current_delay: Duration,
    jitter_state: u64,
    jitter_basis_points: u16,
}

impl WsPollBackoff {
    fn with_jitter(
        min_delay: Duration,
        max_delay: Duration,
        jitter_seed: u64,
        jitter_basis_points: u16,
    ) -> Self {
        let normalized_min = min_delay.max(Duration::from_millis(250));
        let normalized_max = max_delay.max(normalized_min);
        Self {
            min_delay: normalized_min,
            max_delay: normalized_max,
            current_delay: normalized_min,
            jitter_state: jitter_seed,
            jitter_basis_points,
        }
    }

    fn on_activity(&mut self) -> Duration {
        self.current_delay = self.min_delay;
        self.current_delay
    }

    fn on_idle(&mut self) -> Duration {
        self.current_delay = self
            .current_delay
            .checked_mul(2)
            .map(|delay| delay.min(self.max_delay))
            .unwrap_or(self.max_delay);
        self.current_delay
    }

    fn on_error(&mut self) -> Duration {
        self.on_idle()
    }

    fn next_sleep_delay(&mut self) -> Duration {
        if self.jitter_basis_points == 0 {
            return self.current_delay;
        }
        let state = ws_schedule_advance_state(&mut self.jitter_state);
        let spread = u64::from(self.jitter_basis_points) * 2 + 1;
        let offset = (state % spread) as i64 - i64::from(self.jitter_basis_points);
        let scaled = ((self.current_delay.as_millis() as i128) * i128::from(10_000 + offset)
            / 10_000)
            .max(250);
        Duration::from_millis(scaled.min(i128::from(u64::MAX)) as u64)
    }
}

fn stable_ws_schedule_seed(scope: &str, device_id: &str) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in scope
        .as_bytes()
        .iter()
        .chain(std::iter::once(&b':'))
        .chain(device_id.as_bytes().iter())
    {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

fn ws_schedule_advance_state(state: &mut u64) -> u64 {
    let mut next = if *state == 0 {
        0x9e3779b97f4a7c15
    } else {
        *state
    };
    next ^= next << 13;
    next ^= next >> 7;
    next ^= next << 17;
    *state = next;
    next
}

fn ws_next_jittered_delay(
    base: Duration,
    jitter_state: &mut u64,
    jitter_max_millis: u64,
) -> Duration {
    if jitter_max_millis == 0 {
        return base;
    }
    let jitter = ws_schedule_advance_state(jitter_state) % (jitter_max_millis + 1);
    base + Duration::from_millis(jitter)
}

fn ws_revalidate_interval(scope: &str, device_id: &str) -> tokio::time::Interval {
    let seed = stable_ws_schedule_seed(scope, device_id);
    let initial_jitter_ms = seed % (WS_AUTH_REVALIDATE_JITTER_MAX_MILLIS + 1);
    let mut interval = tokio::time::interval_at(
        Instant::now()
            + Duration::from_secs(WS_AUTH_REVALIDATE_SECS)
            + Duration::from_millis(initial_jitter_ms),
        Duration::from_secs(WS_AUTH_REVALIDATE_SECS),
    );
    interval.set_missed_tick_behavior(MissedTickBehavior::Delay);
    interval
}

