fn coach_storage_error(detail: &'static str, error: sqlx::Error) -> ApiError {
    tracing::error!(error = %error, "{detail}");
    ApiError::internal(detail)
}

async fn coach_load_ops_review_map(state: &AppState) -> ApiResult<CoachOpsReviewMap> {
    let Some(auth_runtime) = state.auth.as_ref() else {
        return Ok(coach_ops_review_store().read().await.clone());
    };
    let rows = sqlx::query(
        "SELECT request_id, decision, queue_status, reviewed_at::text AS reviewed_at, \
         reviewed_by_account_id, review_note \
         FROM auth_coach_ops_reviews",
    )
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
    let mut map = CoachOpsReviewMap::new();
    for row in rows {
        let request_id = row
            .try_get::<String, _>("request_id")
            .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
        let decision = row
            .try_get::<String, _>("decision")
            .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
        let queue_status = row
            .try_get::<String, _>("queue_status")
            .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
        let reviewed_at = row
            .try_get::<String, _>("reviewed_at")
            .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
        let reviewed_by_account_id = row
            .try_get::<String, _>("reviewed_by_account_id")
            .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
        let review_note = row
            .try_get::<Option<String>, _>("review_note")
            .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
        map.insert(
            request_id,
            CoachOpsReviewEntry {
                decision,
                queue_status,
                reviewed_at,
                reviewed_by_account_id,
                review_note,
            },
        );
    }
    Ok(map)
}

async fn coach_insert_ops_review_entry(
    state: &AppState,
    request_id: &str,
    request_kind: &str,
    entry: &CoachOpsReviewEntry,
) -> ApiResult<bool> {
    let Some(auth_runtime) = state.auth.as_ref() else {
        let mut review_map = coach_ops_review_store().write().await;
        if review_map.contains_key(request_id) {
            return Ok(false);
        }
        review_map.insert(request_id.to_string(), entry.clone());
        return Ok(true);
    };
    let result = sqlx::query(
        "INSERT INTO auth_coach_ops_reviews \
         (request_id, request_kind, decision, queue_status, reviewed_at, reviewed_by_account_id, review_note) \
         VALUES ($1, $2, $3, $4, $5::timestamptz, $6, $7) \
         ON CONFLICT (request_id) DO NOTHING",
    )
    .bind(request_id)
    .bind(request_kind)
    .bind(entry.decision.as_str())
    .bind(entry.queue_status.as_str())
    .bind(entry.reviewed_at.as_str())
    .bind(entry.reviewed_by_account_id.as_str())
    .bind(entry.review_note.as_deref())
    .execute(auth_runtime.pool())
    .await
    .map_err(|error| coach_storage_error("coach ops review store unavailable", error))?;
    Ok(result.rows_affected() > 0)
}

