async fn coach_load_boarding_event_map(
    state: &AppState,
    trip_id: Option<&str>,
) -> ApiResult<CoachBoardingEventMap> {
    let Some(auth_runtime) = state.auth.as_ref() else {
        let event_map = coach_boarding_event_store().read().await.clone();
        if let Some(trip_id) = trip_id {
            let filtered = event_map
                .into_iter()
                .filter(|(_, entry)| entry.trip_id == trip_id)
                .collect::<CoachBoardingEventMap>();
            return Ok(filtered);
        }
        return Ok(event_map);
    };
    let rows = if let Some(trip_id) = trip_id {
        sqlx::query(
            "SELECT trip_id, ticket_id, boarding_event_id, scan_status, captured_at::text AS captured_at, \
             offline_captured, device_id, note \
             FROM auth_coach_boarding_events \
             WHERE trip_id=$1",
        )
        .bind(trip_id)
        .fetch_all(auth_runtime.pool())
        .await
    } else {
        sqlx::query(
            "SELECT trip_id, ticket_id, boarding_event_id, scan_status, captured_at::text AS captured_at, \
             offline_captured, device_id, note \
             FROM auth_coach_boarding_events",
        )
        .fetch_all(auth_runtime.pool())
        .await
    }
    .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
    let mut map = CoachBoardingEventMap::new();
    for row in rows {
        let trip_id = row
            .try_get::<String, _>("trip_id")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        let ticket_id = row
            .try_get::<String, _>("ticket_id")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        let boarding_event_id = row
            .try_get::<String, _>("boarding_event_id")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        let scan_status = row
            .try_get::<String, _>("scan_status")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        let captured_at = row
            .try_get::<String, _>("captured_at")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        let offline_captured = row
            .try_get::<bool, _>("offline_captured")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        let device_id = row
            .try_get::<Option<String>, _>("device_id")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        let note = row
            .try_get::<Option<String>, _>("note")
            .map_err(|error| coach_storage_error("coach boarding store unavailable", error))?;
        map.insert(
            coach_boarding_event_store_key(&trip_id, &ticket_id),
            CoachBoardingEventEntry {
                boarding_event_id,
                ticket_id,
                trip_id,
                scan_status,
                captured_at,
                offline_captured,
                device_id,
                note,
            },
        );
    }
    Ok(map)
}

