fn coach_string_array_from_json(raw: Value, field_name: &'static str) -> ApiResult<Vec<String>> {
    let Value::Array(values) = raw else {
        return Err(ApiError::internal(field_name));
    };
    let mut normalized = Vec::with_capacity(values.len());
    for value in values {
        let Some(item) = value
            .as_str()
            .map(str::trim)
            .filter(|item| !item.is_empty())
        else {
            return Err(ApiError::internal(field_name));
        };
        normalized.push(item.to_string());
    }
    Ok(normalized)
}

