async fn coach_insert_settlement_payout_run_entry(
    state: &AppState,
    entry: &CoachSettlementPayoutRunEntry,
) -> ApiResult<bool> {
    let entry = coach_normalize_settlement_payout_run_entry(entry.clone());
    let Some(auth_runtime) = state.auth.as_ref() else {
        let mut payout_runs = coach_settlement_payout_run_store().write().await;
        if payout_runs.contains_key(entry.payout_run_id.as_str()) {
            return Ok(false);
        }
        payout_runs.insert(entry.payout_run_id.clone(), entry.clone());
        return Ok(true);
    };
    let result = sqlx::query(
        "INSERT INTO auth_coach_settlement_payout_runs \
         (payout_run_id, status, currency, statement_ids, operator_ids, operator_names, statement_count, \
          gross_minor_units, reserve_minor_units, net_payable_minor_units, created_at, paid_at, \
          created_by_account_id, paid_by_account_id, payment_reference, note) \
         VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6::jsonb, $7, $8, $9, $10, $11::timestamptz, \
                 $12::timestamptz, $13, $14, $15, $16) \
         ON CONFLICT (payout_run_id) DO NOTHING",
    )
    .bind(entry.payout_run_id.as_str())
    .bind(entry.status.as_str())
    .bind(entry.currency.as_str())
    .bind(json!(entry.statement_ids))
    .bind(json!(entry.operator_ids))
    .bind(json!(entry.operator_names))
    .bind(entry.statement_count)
    .bind(entry.gross_minor_units)
    .bind(entry.reserve_minor_units)
    .bind(entry.net_payable_minor_units)
    .bind(entry.created_at.as_str())
    .bind(entry.paid_at.as_deref())
    .bind(entry.created_by_account_id.as_str())
    .bind(entry.paid_by_account_id.as_deref())
    .bind(entry.payment_reference.as_deref())
    .bind(entry.note.as_deref())
    .execute(auth_runtime.pool())
    .await
    .map_err(|error| coach_storage_error("coach payout run store unavailable", error))?;
    Ok(result.rows_affected() > 0)
}

