fn coach_trim_settlement_payout_import_preview_store(
    previews: &mut CoachSettlementPayoutImportPreviewMap,
) {
    for entry in previews.values_mut() {
        if coach_preview_entry_is_expired(entry) {
            entry.preview_status = COACH_PAYOUT_IMPORT_PREVIEW_STATUS_EXPIRED.to_string();
            entry.invalidated_at = None;
        }
    }
    while previews.len() >= COACH_PAYOUT_IMPORT_PREVIEW_MAX_ENTRIES {
        let Some(oldest_key) = coach_oldest_payout_import_preview_token(previews) else {
            break;
        };
        previews.remove(oldest_key.as_str());
    }
}

fn coach_oldest_payout_import_preview_token(
    previews: &CoachSettlementPayoutImportPreviewMap,
) -> Option<String> {
    previews
        .iter()
        .min_by(|left, right| {
            left.1
                .created_at
                .cmp(&right.1.created_at)
                .then_with(|| left.0.cmp(right.0))
        })
        .map(|(preview_token, _)| preview_token.clone())
}

async fn coach_store_settlement_payout_import_preview_entry(
    state: &AppState,
    entry: &CoachSettlementPayoutImportPreviewEntry,
) -> ApiResult<()> {
    let normalized_account_id = entry.account_id.trim().to_ascii_lowercase();
    if let Some(auth_runtime) = state.auth.as_ref() {
        sqlx::query(
            "INSERT INTO auth_coach_settlement_payout_import_previews \
             (preview_token, account_id, import_source, report_name, report_format, \
              rework_of_batch_id, operator_ids, report_checksum_sha256, request_fingerprint, \
              preview_status, created_at, expires_at, consumed_at, invalidated_at) \
             VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb, $8, $9, $10, $11::timestamptz, \
                     $12::timestamptz, $13::timestamptz, $14::timestamptz) \
             ON CONFLICT (preview_token) DO UPDATE SET \
                 account_id=EXCLUDED.account_id, \
                 import_source=EXCLUDED.import_source, \
                 report_name=EXCLUDED.report_name, \
                 report_format=EXCLUDED.report_format, \
                 rework_of_batch_id=EXCLUDED.rework_of_batch_id, \
                 operator_ids=EXCLUDED.operator_ids, \
                 report_checksum_sha256=EXCLUDED.report_checksum_sha256, \
                 request_fingerprint=EXCLUDED.request_fingerprint, \
                 preview_status=EXCLUDED.preview_status, \
                 created_at=EXCLUDED.created_at, \
                 expires_at=EXCLUDED.expires_at, \
                 consumed_at=EXCLUDED.consumed_at, \
                 invalidated_at=EXCLUDED.invalidated_at",
        )
        .bind(entry.preview_token.as_str())
        .bind(normalized_account_id.as_str())
        .bind(entry.import_source.as_str())
        .bind(entry.report_name.as_str())
        .bind(entry.report_format.as_str())
        .bind(entry.rework_of_batch_id.as_deref())
        .bind(json!(entry.operator_ids))
        .bind(entry.report_checksum_sha256.as_str())
        .bind(entry.request_fingerprint.as_str())
        .bind(entry.preview_status.as_str())
        .bind(entry.created_at.as_str())
        .bind(entry.expires_at.as_str())
        .bind(entry.consumed_at.as_deref())
        .bind(entry.invalidated_at.as_deref())
        .execute(auth_runtime.pool())
        .await
        .map_err(|error| {
            coach_storage_error("coach payout import preview store unavailable", error)
        })?;
        return Ok(());
    }

    let store = coach_settlement_payout_import_preview_store();
    let mut previews = store.write().await;
    coach_trim_settlement_payout_import_preview_store(&mut previews);
    let mut normalized_entry = entry.clone();
    normalized_entry.account_id = normalized_account_id;
    previews.insert(normalized_entry.preview_token.clone(), normalized_entry);
    coach_trim_settlement_payout_import_preview_store(&mut previews);
    Ok(())
}

