fn canonical_chat_optional_device_id(raw: Option<String>) -> ApiResult<Option<String>> {
    let Some(device_id) = canonical_trimmed_field(raw) else {
        return Ok(None);
    };
    if !is_valid_chat_device_id(&device_id) {
        return Err(ApiError::bad_request("invalid device_id"));
    }
    Ok(Some(device_id))
}

fn canonical_chat_feature_text(
    raw: &str,
    field: &'static str,
    min_chars: usize,
    max_chars: usize,
) -> ApiResult<String> {
    let value = raw.trim();
    let len = value.chars().count();
    if len < min_chars || len > max_chars || value.chars().any(|ch| ch.is_ascii_control()) {
        return Err(ApiError::bad_request(format!("invalid {field}")));
    }
    Ok(value.to_string())
}

fn canonical_chat_optional_feature_text(
    raw: Option<String>,
    field: &'static str,
    max_chars: usize,
) -> ApiResult<Option<String>> {
    let Some(value) = canonical_trimmed_field(raw) else {
        return Ok(None);
    };
    canonical_chat_feature_text(&value, field, 1, max_chars).map(Some)
}

fn canonical_chat_message_reaction_payload(body: ChatMessageReactionIn) -> ApiResult<Value> {
    let mut out = Map::new();
    if let Some(device_id) = canonical_chat_optional_device_id(body.device_id)? {
        out.insert("device_id".to_string(), json!(device_id));
    }
    let remove = body.remove.unwrap_or(false);
    if remove {
        out.insert("remove".to_string(), json!(true));
        return Ok(Value::Object(out));
    }
    let emoji = canonical_chat_feature_text(
        body.emoji
            .as_deref()
            .ok_or_else(|| ApiError::bad_request("emoji required"))?,
        "emoji",
        1,
        16,
    )?;
    out.insert("emoji".to_string(), json!(emoji));
    Ok(Value::Object(out))
}

