fn canonical_chat_call_log_payload(body: ChatCallLogIn) -> ApiResult<Value> {
    let mut out = Map::new();
    if let Some(device_id) = canonical_chat_optional_device_id(body.device_id)? {
        out.insert("device_id".to_string(), json!(device_id));
    }
    if let Some(call_id) = canonical_chat_optional_feature_text(body.call_id, "call_id", 64)? {
        if call_id
            .chars()
            .any(|ch| ch.is_ascii_whitespace() || ch.is_ascii_control())
        {
            return Err(ApiError::bad_request("invalid call_id"));
        }
        out.insert("call_id".to_string(), json!(call_id));
    }
    let peer_id = required_trimmed_string(body.peer_id, "peer_id required")?;
    if !is_valid_chat_device_id(&peer_id) {
        return Err(ApiError::bad_request("invalid peer_id"));
    }
    let direction = match body.direction.trim().to_ascii_lowercase().as_str() {
        "in" | "out" => body.direction.trim().to_ascii_lowercase(),
        _ => return Err(ApiError::bad_request("invalid direction")),
    };
    let kind = match body.kind.trim().to_ascii_lowercase().as_str() {
        "voice" | "audio" => "voice".to_string(),
        "video" => "video".to_string(),
        _ => return Err(ApiError::bad_request("invalid kind")),
    };
    out.insert("peer_id".to_string(), json!(peer_id));
    out.insert("direction".to_string(), json!(direction));
    out.insert("kind".to_string(), json!(kind));
    if let Some(accepted) = body.accepted {
        out.insert("accepted".to_string(), json!(accepted));
    }
    if let Some(duration_seconds) = body.duration_seconds {
        if !(0..=86400).contains(&duration_seconds) {
            return Err(ApiError::bad_request("invalid duration_seconds"));
        }
        out.insert("duration_seconds".to_string(), json!(duration_seconds));
    }
    if let Some(started_at) = canonical_trimmed_field(body.started_at) {
        chrono::DateTime::parse_from_rfc3339(&started_at)
            .map_err(|_| ApiError::bad_request("invalid started_at"))?;
        out.insert("started_at".to_string(), json!(started_at));
    }
    Ok(Value::Object(out))
}

fn canonical_chat_voice_transcript_payload(body: ChatVoiceTranscriptIn) -> ApiResult<Value> {
    let mut out = Map::new();
    if let Some(device_id) = canonical_chat_optional_device_id(body.device_id)? {
        out.insert("device_id".to_string(), json!(device_id));
    }
    let message_id = required_path(&body.message_id, "message_id")?;
    out.insert("message_id".to_string(), json!(message_id));
    out.insert(
        "transcript".to_string(),
        json!(canonical_chat_feature_text(
            &body.transcript,
            "transcript",
            1,
            4000
        )?),
    );
    if let Some(language) = canonical_chat_optional_feature_text(body.language, "language", 16)? {
        out.insert("language".to_string(), json!(language));
    }
    if let Some(confidence) = body.confidence {
        if !(0.0..=1.0).contains(&confidence) {
            return Err(ApiError::bad_request("invalid confidence"));
        }
        out.insert("confidence".to_string(), json!(confidence));
    }
    Ok(Value::Object(out))
}

