fn canonical_chat_send_payload(body: ChatSendIn) -> ApiResult<Value> {
    let sender_id = required_trimmed_string(body.sender_id, "sender_id required")?;
    if !is_valid_chat_device_id(&sender_id) {
        return Err(ApiError::bad_request("invalid sender_id"));
    }
    let recipient_id = required_trimmed_string(body.recipient_id, "recipient_id required")?;
    if !is_valid_chat_device_id(&recipient_id) {
        return Err(ApiError::bad_request("invalid recipient_id"));
    }
    let sender_pubkey_b64 =
        required_trimmed_string(body.sender_pubkey_b64, "sender_pubkey_b64 required")?;
    let nonce_b64 = required_trimmed_string(body.nonce_b64, "nonce_b64 required")?;
    let box_b64 = required_trimmed_string(body.box_b64, "box_b64 required")?;
    validate_chat_key_material(
        &sender_pubkey_b64,
        "sender_pubkey_b64",
        CHAT_MESSAGE_SENDER_PUBKEY_MIN_LEN,
        CHAT_MESSAGE_SENDER_PUBKEY_MAX_LEN,
    )?;
    validate_chat_key_material(
        &nonce_b64,
        "nonce_b64",
        CHAT_MESSAGE_NONCE_B64_MIN_LEN,
        CHAT_MESSAGE_NONCE_B64_MAX_LEN,
    )?;
    validate_chat_direct_box_b64(&box_b64)?;

    let mut out = Map::new();
    out.insert("sender_id".to_string(), json!(sender_id));
    out.insert("recipient_id".to_string(), json!(recipient_id));
    out.insert("sender_pubkey_b64".to_string(), json!(sender_pubkey_b64));
    out.insert("nonce_b64".to_string(), json!(nonce_b64));
    out.insert("box_b64".to_string(), json!(box_b64));

    if let Some(protocol_version) = canonical_trimmed_field(body.protocol_version) {
        out.insert("protocol_version".to_string(), json!(protocol_version));
    }
    if let Some(sender_dh_pub_b64) = canonical_trimmed_field(body.sender_dh_pub_b64) {
        validate_chat_key_material(
            &sender_dh_pub_b64,
            "sender_dh_pub_b64",
            CHAT_MESSAGE_SENDER_DH_PUBKEY_MIN_LEN,
            CHAT_MESSAGE_SENDER_DH_PUBKEY_MAX_LEN,
        )?;
        out.insert("sender_dh_pub_b64".to_string(), json!(sender_dh_pub_b64));
    }
    if let Some(expire_after_seconds) = body.expire_after_seconds {
        if !(CHAT_MESSAGE_EXPIRE_AFTER_SECONDS_MIN..=CHAT_MESSAGE_EXPIRE_AFTER_SECONDS_MAX)
            .contains(&expire_after_seconds)
        {
            return Err(ApiError::bad_request("invalid expire_after_seconds"));
        }
        out.insert(
            "expire_after_seconds".to_string(),
            json!(expire_after_seconds),
        );
    }
    if let Some(sealed_sender) = body.sealed_sender {
        out.insert("sealed_sender".to_string(), json!(sealed_sender));
    }
    if let Some(sender_hint) = canonical_trimmed_field(body.sender_hint) {
        validate_chat_key_material(
            &sender_hint,
            "sender_hint",
            CHAT_MESSAGE_HINT_MIN_LEN,
            CHAT_MESSAGE_HINT_MAX_LEN,
        )?;
        out.insert("sender_hint".to_string(), json!(sender_hint));
    }
    if let Some(sender_fingerprint) = canonical_trimmed_field(body.sender_fingerprint) {
        validate_chat_key_material(
            &sender_fingerprint,
            "sender_fingerprint",
            CHAT_MESSAGE_HINT_MIN_LEN,
            CHAT_MESSAGE_HINT_MAX_LEN,
        )?;
        out.insert("sender_fingerprint".to_string(), json!(sender_fingerprint));
    }
    if let Some(key_id) = canonical_trimmed_field(body.key_id) {
        validate_chat_key_material(
            &key_id,
            "key_id",
            CHAT_MESSAGE_KEY_ID_MIN_LEN,
            CHAT_MESSAGE_KEY_ID_MAX_LEN,
        )?;
        out.insert("key_id".to_string(), json!(key_id));
    }
    if let Some(prev_key_id) = canonical_trimmed_field(body.prev_key_id) {
        validate_chat_key_material(
            &prev_key_id,
            "prev_key_id",
            CHAT_MESSAGE_KEY_ID_MIN_LEN,
            CHAT_MESSAGE_KEY_ID_MAX_LEN,
        )?;
        out.insert("prev_key_id".to_string(), json!(prev_key_id));
    }
    Ok(Value::Object(out))
}

fn canonical_chat_prekeys_payload(
    prekeys: Vec<crate::models::ChatOneTimePrekeyIn>,
) -> ApiResult<Vec<Value>> {
    if !(CHAT_PREKEY_BATCH_MIN_ITEMS..=CHAT_PREKEY_BATCH_MAX_ITEMS).contains(&prekeys.len()) {
        return Err(ApiError::bad_request("invalid prekeys"));
    }
    let mut seen_key_ids: HashSet<i64> = HashSet::with_capacity(prekeys.len());
    let mut out = Vec::with_capacity(prekeys.len());
    for prekey in prekeys {
        if prekey.key_id <= 0 || !seen_key_ids.insert(prekey.key_id) {
            return Err(ApiError::bad_request("invalid prekeys"));
        }
        let key_b64 = prekey.key_b64.trim();
        if !is_valid_chat_key_material(
            key_b64,
            CHAT_PREKEY_KEY_B64_MIN_LEN,
            CHAT_PREKEY_KEY_B64_MAX_LEN,
        ) {
            return Err(ApiError::bad_request("invalid prekeys"));
        }
        out.push(json!({
            "key_id": prekey.key_id,
            "key_b64": key_b64,
        }));
    }
    Ok(out)
}

fn canonical_chat_key_register_payload(body: ChatKeyRegisterIn) -> ApiResult<Value> {
    let device_id = required_trimmed_string(body.device_id, "device_id required")?;
    if !is_valid_chat_device_id(&device_id) {
        return Err(ApiError::bad_request("invalid device_id"));
    }
    let identity_key_b64 =
        required_trimmed_string(body.identity_key_b64, "identity_key_b64 required")?;
    validate_chat_key_material(
        &identity_key_b64,
        "identity_key_b64",
        CHAT_IDENTITY_KEY_MIN_LEN,
        CHAT_IDENTITY_KEY_MAX_LEN,
    )?;
    let identity_signing_pubkey_b64 = canonical_trimmed_field(body.identity_signing_pubkey_b64)
        .ok_or_else(|| ApiError::bad_request("identity_signing_pubkey_b64 required"))?;
    validate_chat_key_material(
        &identity_signing_pubkey_b64,
        "identity_signing_pubkey_b64",
        CHAT_IDENTITY_KEY_MIN_LEN,
        CHAT_IDENTITY_KEY_MAX_LEN,
    )?;
    if body.signed_prekey_id <= 0 {
        return Err(ApiError::bad_request("invalid signed_prekey_id"));
    }
    let signed_prekey_b64 =
        required_trimmed_string(body.signed_prekey_b64, "signed_prekey_b64 required")?;
    validate_chat_key_material(
        &signed_prekey_b64,
        "signed_prekey_b64",
        CHAT_SIGNED_PREKEY_MIN_LEN,
        CHAT_SIGNED_PREKEY_MAX_LEN,
    )?;
    let signed_prekey_sig_b64 =
        required_trimmed_string(body.signed_prekey_sig_b64, "signed_prekey_sig_b64 required")?;
    validate_chat_key_material(
        &signed_prekey_sig_b64,
        "signed_prekey_sig_b64",
        CHAT_SIGNED_PREKEY_MIN_LEN,
        CHAT_SIGNED_PREKEY_MAX_LEN,
    )?;
    let signed_prekey_sig_alg = canonical_trimmed_field(body.signed_prekey_sig_alg)
        .ok_or_else(|| ApiError::bad_request("signed_prekey_sig_alg required"))?
        .to_ascii_lowercase();
    if signed_prekey_sig_alg != CHAT_SIGNED_PREKEY_SIG_ALG_ED25519 {
        return Err(ApiError::bad_request(
            "signed_prekey_sig_alg must be ed25519",
        ));
    }
    let mut out = Map::new();
    out.insert("device_id".to_string(), json!(device_id));
    out.insert("identity_key_b64".to_string(), json!(identity_key_b64));
    out.insert(
        "identity_signing_pubkey_b64".to_string(),
        json!(identity_signing_pubkey_b64),
    );
    out.insert("signed_prekey_id".to_string(), json!(body.signed_prekey_id));
    out.insert("signed_prekey_b64".to_string(), json!(signed_prekey_b64));
    out.insert(
        "signed_prekey_sig_b64".to_string(),
        json!(signed_prekey_sig_b64),
    );
    out.insert(
        "signed_prekey_sig_alg".to_string(),
        json!(signed_prekey_sig_alg),
    );
    if let Some(v2_only) = body.v2_only {
        out.insert("v2_only".to_string(), json!(v2_only));
    }
    Ok(Value::Object(out))
}

fn canonical_chat_key_bootstrap_payload(body: ChatKeyBootstrapIn) -> ApiResult<Value> {
    let prekeys = canonical_chat_prekeys_payload(body.prekeys)?;
    let registration = canonical_chat_key_register_payload(ChatKeyRegisterIn {
        device_id: body.device_id,
        identity_key_b64: body.identity_key_b64,
        identity_signing_pubkey_b64: body.identity_signing_pubkey_b64,
        signed_prekey_id: body.signed_prekey_id,
        signed_prekey_b64: body.signed_prekey_b64,
        signed_prekey_sig_b64: body.signed_prekey_sig_b64,
        signed_prekey_sig_alg: body.signed_prekey_sig_alg,
        v2_only: body.v2_only,
    })?;
    let mut obj = registration
        .as_object()
        .cloned()
        .ok_or_else(|| ApiError::internal("invalid key bootstrap canonical payload"))?;
    obj.insert("prekeys".to_string(), Value::Array(prekeys));
    Ok(Value::Object(obj))
}

