fn normalize_chat_member_candidate_ids(
    ids: Vec<String>,
    excluded_device_id: Option<&str>,
) -> Vec<String> {
    let excluded = excluded_device_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or_default();
    let mut seen: HashSet<String> = HashSet::with_capacity(ids.len());
    let mut out = Vec::new();
    for raw in ids {
        let device_id = raw.trim().to_string();
        if device_id.is_empty()
            || device_id == excluded
            || !is_valid_chat_device_id(&device_id)
            || !seen.insert(device_id.clone())
        {
            continue;
        }
        out.push(device_id);
    }
    out
}

fn normalize_chat_group_avatar_mime(value: &str) -> Option<&'static str> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "image/png" => Some("image/png"),
        "image/jpeg" => Some("image/jpeg"),
        "image/webp" => Some("image/webp"),
        _ => None,
    }
}

fn canonical_chat_group_create_payload(body: ChatGroupCreateIn) -> ApiResult<Value> {
    let device_id = required_trimmed_string(body.device_id, "device_id required")?;
    if !is_valid_chat_device_id(&device_id) {
        return Err(ApiError::bad_request("invalid device_id"));
    }
    let name = required_trimmed_string(body.name, "name required")?;
    if name.chars().count() > CHAT_GROUP_NAME_MAX_CHARS
        || name.chars().any(|ch| ch.is_ascii_control())
    {
        return Err(ApiError::bad_request("invalid name"));
    }
    let mut out = Map::new();
    out.insert("device_id".to_string(), json!(device_id));
    out.insert("name".to_string(), json!(name));

    if let Some(group_id) = canonical_trimmed_field(body.group_id) {
        if !is_valid_chat_group_id(&group_id) {
            return Err(ApiError::bad_request("invalid group_id"));
        }
        out.insert("group_id".to_string(), json!(group_id));
    }

    if let Some(member_ids) = body.member_ids {
        if member_ids.len() > CHAT_GROUP_MEMBER_IDS_MAX_ITEMS {
            return Err(ApiError::bad_request("invalid member_ids"));
        }
        let normalized_member_ids = normalize_chat_member_candidate_ids(member_ids, None);
        out.insert("member_ids".to_string(), json!(normalized_member_ids));
    }

    Ok(Value::Object(out))
}

fn canonical_chat_group_update_payload(body: ChatGroupUpdateIn) -> ApiResult<Value> {
    let actor_id = required_trimmed_string(body.actor_id, "actor_id required")?;
    if !is_valid_chat_device_id(&actor_id) {
        return Err(ApiError::bad_request("invalid actor_id"));
    }
    let mut out = Map::new();
    out.insert("actor_id".to_string(), json!(actor_id));

    if let Some(name) = canonical_trimmed_field(body.name) {
        if name.chars().count() > CHAT_GROUP_NAME_MAX_CHARS
            || name.chars().any(|ch| ch.is_ascii_control())
        {
            return Err(ApiError::bad_request("invalid name"));
        }
        out.insert("name".to_string(), json!(name));
    }

    if body.avatar_b64.is_some() || body.avatar_mime.is_some() {
        let avatar_b64 = body.avatar_b64.unwrap_or_default().trim().to_string();
        let avatar_mime = body.avatar_mime.unwrap_or_default().trim().to_string();
        let avatar_b64_non_empty = (!avatar_b64.is_empty()).then_some(avatar_b64.as_str());
        let avatar_mime_non_empty = (!avatar_mime.is_empty()).then_some(avatar_mime.as_str());

        match (avatar_b64_non_empty, avatar_mime_non_empty) {
            (None, None) => {
                out.insert("avatar_b64".to_string(), json!(""));
                out.insert("avatar_mime".to_string(), json!(""));
            }
            (None, Some(_)) => return Err(ApiError::bad_request("avatar_b64 required")),
            (Some(_), None) => return Err(ApiError::bad_request("avatar_mime required")),
            (Some(avatar_b64), Some(avatar_mime)) => {
                if avatar_b64.len() > CHAT_GROUP_AVATAR_MAX_B64_LEN {
                    return Err(ApiError::bad_request("group avatar too large"));
                }
                validate_chat_key_material(
                    avatar_b64,
                    "avatar_b64",
                    4,
                    CHAT_GROUP_AVATAR_MAX_B64_LEN,
                )?;
                let normalized_avatar_mime = normalize_chat_group_avatar_mime(avatar_mime)
                    .ok_or_else(|| ApiError::bad_request("invalid avatar_mime"))?;
                out.insert("avatar_b64".to_string(), json!(avatar_b64));
                out.insert("avatar_mime".to_string(), json!(normalized_avatar_mime));
            }
        }
    }

    Ok(Value::Object(out))
}

fn canonical_chat_group_invite_payload(body: ChatGroupInviteIn) -> ApiResult<Value> {
    let inviter_id = required_trimmed_string(body.inviter_id, "inviter_id required")?;
    if !is_valid_chat_device_id(&inviter_id) {
        return Err(ApiError::bad_request("invalid inviter_id"));
    }
    if body.member_ids.len() > CHAT_GROUP_MEMBER_IDS_MAX_ITEMS {
        return Err(ApiError::bad_request("invalid member_ids"));
    }
    let normalized_member_ids =
        normalize_chat_member_candidate_ids(body.member_ids, Some(&inviter_id));
    Ok(json!({
        "inviter_id": inviter_id,
        "member_ids": normalized_member_ids,
    }))
}

fn canonical_chat_group_leave_payload(body: ChatGroupLeaveIn) -> ApiResult<Value> {
    let device_id = required_trimmed_string(body.device_id, "device_id required")?;
    if !is_valid_chat_device_id(&device_id) {
        return Err(ApiError::bad_request("invalid device_id"));
    }
    Ok(json!({
        "device_id": device_id,
    }))
}

fn canonical_chat_group_set_role_payload(body: ChatGroupSetRoleIn) -> ApiResult<Value> {
    let actor_id = required_trimmed_string(body.actor_id, "actor_id required")?;
    if !is_valid_chat_device_id(&actor_id) {
        return Err(ApiError::bad_request("invalid actor_id"));
    }
    let target_id = required_trimmed_string(body.target_id, "target_id required")?;
    if !is_valid_chat_device_id(&target_id) {
        return Err(ApiError::bad_request("invalid target_id"));
    }
    let role = required_trimmed_string(body.role, "role required")?.to_ascii_lowercase();
    if !matches!(role.as_str(), "admin" | "member") {
        return Err(ApiError::bad_request("invalid role"));
    }
    Ok(json!({
        "actor_id": actor_id,
        "target_id": target_id,
        "role": role,
    }))
}

fn canonical_chat_group_rotate_key_payload(body: ChatGroupRotateKeyIn) -> ApiResult<Value> {
    let actor_id = required_trimmed_string(body.actor_id, "actor_id required")?;
    if !is_valid_chat_device_id(&actor_id) {
        return Err(ApiError::bad_request("invalid actor_id"));
    }
    let mut out = Map::new();
    out.insert("actor_id".to_string(), json!(actor_id));
    if let Some(key_fp) = canonical_trimmed_field(body.key_fp) {
        if key_fp.len() > CHAT_GROUP_KEY_FP_MAX_LEN
            || key_fp.chars().any(|ch| ch.is_ascii_control())
        {
            return Err(ApiError::bad_request("invalid key_fp"));
        }
        out.insert("key_fp".to_string(), json!(key_fp));
    }
    Ok(Value::Object(out))
}

