pub async fn security_alert_ingest(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(payload): axum::Json<SecurityAlertIngestIn>,
) -> ApiResult<(StatusCode, axum::Json<SecurityAlertIngestOut>)> {
    auth::enforce_security_alert_ingest_rate_limit(&state, &headers, &payload.source).await?;

    let source = payload.source.trim();
    if !security_alert_log_token_is_valid(source, 128) {
        return Err(security_alert_ingest_bad_request(
            &headers,
            &payload,
            "invalid_source",
            "source must be a safe token and <= 128 chars",
        ));
    }

    let service = payload
        .service
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty());
    if service.is_some_and(|s| !security_alert_log_token_is_valid(s, 64)) {
        return Err(security_alert_ingest_bad_request(
            &headers,
            &payload,
            "invalid_service",
            "service must be a safe token and <= 64 chars",
        ));
    }

    let severity = payload
        .severity
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .unwrap_or("warning")
        .to_ascii_lowercase();
    if !matches!(severity.as_str(), "info" | "warning" | "high" | "critical") {
        return Err(security_alert_ingest_bad_request(
            &headers,
            &payload,
            "invalid_severity",
            "severity must be one of: info, warning, high, critical",
        ));
    }

    if payload.alerts.is_empty() {
        return Err(security_alert_ingest_bad_request(
            &headers,
            &payload,
            "empty_alerts",
            "alerts must contain at least one item",
        ));
    }
    if payload.alerts.len() > 64 {
        return Err(security_alert_ingest_bad_request(
            &headers,
            &payload,
            "too_many_alerts",
            "alerts must contain at most 64 items",
        ));
    }
    for raw_item in &payload.alerts {
        let item = raw_item.trim();
        if item.is_empty() || item.len() > 256 {
            return Err(security_alert_ingest_bad_request(
                &headers,
                &payload,
                "invalid_alert_item_length",
                "each alert must be present and <= 256 chars",
            ));
        }
        if !security_alert_item_is_valid(item) {
            return Err(security_alert_ingest_bad_request(
                &headers,
                &payload,
                "malformed_alert_item",
                "each alert must match event.outcome:count/threshold",
            ));
        }
    }
    let alerts = payload
        .alerts
        .iter()
        .map(|item| item.trim().to_string())
        .collect::<Vec<_>>();

    let note = payload
        .note
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty());
    if note.is_some_and(|n| n.len() > 1024) {
        return Err(security_alert_ingest_bad_request(
            &headers,
            &payload,
            "invalid_note",
            "note must be <= 1024 chars",
        ));
    }

    let timestamp_raw = payload
        .timestamp
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty());
    if timestamp_raw.is_some_and(|value| !security_alert_log_token_is_valid(value, 64)) {
        return Err(security_alert_ingest_bad_request(
            &headers,
            &payload,
            "invalid_timestamp",
            "timestamp must be a safe token and <= 64 chars",
        ));
    }
    let timestamp = timestamp_raw.unwrap_or("-");
    let window_secs = payload.window_secs.unwrap_or(0);

    let alert_hashes = security_alert_hash_preview(&alerts);
    let note_hash = note
        .map(security_alert_log_hash)
        .unwrap_or_else(|| "-".to_string());
    let (request_id_hash, client_ip_hash) = security_alert_request_context_hashes(&headers);
    let (caller, caller_hash) = security_alert_ingest_caller_log_fields(&headers);

    match severity.as_str() {
        "critical" => tracing::error!(
            security_event = "runtime_security_alert_ingest",
            outcome = "accepted",
            caller = caller,
            caller_hash = %caller_hash,
            source = source,
            service = service.unwrap_or("-"),
            severity = severity,
            timestamp = timestamp,
            window_secs = window_secs,
            alerts_count = alerts.len(),
            alerts_hashes = ?alert_hashes,
            note_hash = %note_hash,
            request_id_hash = %request_id_hash,
            client_ip_hash = %client_ip_hash,
            "runtime security alert received"
        ),
        "high" | "warning" => tracing::warn!(
            security_event = "runtime_security_alert_ingest",
            outcome = "accepted",
            caller = caller,
            caller_hash = %caller_hash,
            source = source,
            service = service.unwrap_or("-"),
            severity = severity,
            timestamp = timestamp,
            window_secs = window_secs,
            alerts_count = alerts.len(),
            alerts_hashes = ?alert_hashes,
            note_hash = %note_hash,
            request_id_hash = %request_id_hash,
            client_ip_hash = %client_ip_hash,
            "runtime security alert received"
        ),
        _ => tracing::info!(
            security_event = "runtime_security_alert_ingest",
            outcome = "accepted",
            caller = caller,
            caller_hash = %caller_hash,
            source = source,
            service = service.unwrap_or("-"),
            severity = severity,
            timestamp = timestamp,
            window_secs = window_secs,
            alerts_count = alerts.len(),
            alerts_hashes = ?alert_hashes,
            note_hash = %note_hash,
            request_id_hash = %request_id_hash,
            client_ip_hash = %client_ip_hash,
            "runtime security alert received"
        ),
    }

    Ok((
        StatusCode::ACCEPTED,
        axum::Json(SecurityAlertIngestOut {
            status: "accepted",
            accepted: alerts.len(),
        }),
    ))
}

pub async fn payments_create_user(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<PaymentsCreateUserIn>,
) -> ApiResult<Response> {
    // Do not resolve wallet context here: `/payments/users` is itself the
    // provisioning path and must not trigger a redundant upstream `/users`
    // call before proxying the authenticated request.
    let principal = auth::require_session_principal(&state, &headers).await?;
    enforce_payment_mutation_device_binding(&headers, &principal, "payments_create_user")?;
    auth::enforce_payment_mutation_rate_limit(&state, &headers, &principal, "payments_create_user")
        .await?;
    let (body, currency) = canonical_payments_create_user_body(&principal.account_id, body)?;
    let resource_id = payment_create_user_attestation_resource_id(&principal.account_id);
    auth::enforce_payment_mutation_attestation(
        &state,
        &headers,
        &principal,
        "payments_create_user",
        &resource_id,
    )
    .await?;
    let headers = payments_headers_with_create_user_idempotency(
        &headers,
        &principal.account_id,
        None,
        currency.as_deref(),
    )?;

    proxy_payments_no_store(
        &state,
        Method::POST,
        "/users",
        Vec::new(),
        Some(body),
        &headers,
        H_PAY_CREATE_USER,
    )
    .await
}

