pub async fn payments_wallet_snapshot(
    Path(wallet_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<WalletSnapshotQuery>,
) -> ApiResult<Response> {
    let wallet_id = required_payments_resource_path(&wallet_id, "wallet_id")?;
    let user = require_user_context(&state, &headers).await?;
    if wallet_id != user.wallet_id {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "wallet_id must match authenticated user",
        ));
    }

    let mut query = Vec::new();
    push_limit_query(&mut query, "limit", q.limit, 50, 1, 200);

    if let Some(dir_raw) = q.dir.as_deref().map(str::trim).filter(|v| !v.is_empty()) {
        let dir = dir_raw.to_ascii_lowercase();
        match dir.as_str() {
            "all" => {}
            "in" | "out" => query.push(("dir".to_string(), dir)),
            _ => return Err(ApiError::bad_request("dir must be one of: all, in, out")),
        }
    }
    if let Some(kind) = normalize_wallet_snapshot_kind_filter(q.kind.as_deref())? {
        query.push(("kind".to_string(), kind));
    }
    push_iso_range_query(&mut query, q.from_iso.as_deref(), q.to_iso.as_deref())?;
    push_before_cursor_query(
        &mut query,
        q.before_created_at.as_deref(),
        q.before_id.as_deref(),
    )?;

    proxy_payments_no_store(
        &state,
        Method::GET,
        &format!("/wallets/{}/snapshot", escaped_path_segment(&wallet_id)),
        query,
        None,
        &headers,
        H_USER_AGENT,
    )
    .await
}

pub async fn payments_transfer(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<PaymentsTransferIn>,
) -> ApiResult<Response> {
    let user = require_payment_mutation_user_context(&state, &headers, "payments_transfer").await?;
    let (body, reference) = canonical_payments_transfer_body(&user.wallet_id, body)?;
    let resource_id = payment_transfer_attestation_resource_id(&body)?;
    auth::enforce_payment_mutation_attestation(
        &state,
        &headers,
        &user.principal,
        "payments_transfer",
        &resource_id,
    )
    .await?;
    let headers = payments_headers_with_reference(&headers, reference.as_deref())?;
    let amount_cents = body
        .get("amount_cents")
        .and_then(Value::as_i64)
        .unwrap_or_default();
    let out = proxy_payments(
        &state,
        Method::POST,
        "/transfer",
        Vec::new(),
        Some(body),
        &headers,
        H_PAY_TRANSFER,
    )
    .await?;
    let response = json_no_store_response(out.0.clone());
    let to_wallet_id = out
        .0
        .get("to_wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    let currency = out.0.get("currency").and_then(Value::as_str);
    if let Some(to_wallet_id) = to_wallet_id.as_deref() {
        if let Err(error) = push_payment_credit_notification_to_wallet_owner(
            &state,
            &headers,
            to_wallet_id,
            amount_cents,
            currency,
        )
        .await
        {
            tracing::warn!(
                error = ?error,
                to_wallet_hash = %auth::hash_prefix(to_wallet_id),
                "transfer credit push failed"
            );
        }
    }
    Ok(response)
}

