pub async fn payments_admin_credit(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<PaymentsAdminCreditIn>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_wallet_credit_principal(&state, &headers).await?;
    let (body, response_shamell_id, amount_cents) =
        canonical_payments_admin_credit_body(&state, &principal.account_id, body).await?;
    let headers = payments_headers_with_idempotency(&headers)?;
    let out = proxy_payments(
        &state,
        Method::POST,
        "/admin/credits",
        Vec::new(),
        Some(body),
        &headers,
        H_PAY_ADMIN_CREDIT,
    )
    .await?;
    let mut response_body = out.0.clone();
    if let Some(shamell_id) = response_shamell_id {
        if let Value::Object(map) = &mut response_body {
            map.insert("shamell_id".to_string(), Value::String(shamell_id));
        }
    }
    let wallet_id = response_body
        .get("wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    let account_id = response_body
        .get("account_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    let credited = response_body
        .get("status")
        .and_then(Value::as_str)
        .map(str::trim)
        .is_none_or(|status| status == "credited");
    if let Some(wallet_id) = wallet_id.as_deref() {
        if credited {
            let currency = response_body.get("currency").and_then(Value::as_str);
            let push_result = if let Some(account_id) = account_id.as_deref() {
                push_payment_credit_notification_to_account(
                    &state,
                    account_id,
                    wallet_id,
                    amount_cents,
                    currency,
                )
                .await
            } else {
                push_payment_credit_notification_to_wallet_owner(
                    &state,
                    &headers,
                    wallet_id,
                    amount_cents,
                    currency,
                )
                .await
            };
            if let Err(error) = push_result {
                tracing::warn!(
                    error = ?error,
                    wallet_hash = %auth::hash_prefix(wallet_id),
                    "admin credit push failed"
                );
            }
        }
    }
    Ok(json_no_store_response(response_body))
}

