pub async fn payments_requests_create(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<PaymentsRequestCreateIn>,
) -> ApiResult<Response> {
    let user =
        require_payment_mutation_user_context(&state, &headers, "payments_requests_create").await?;
    let body = canonical_payments_request_create_body(&user.wallet_id, body)?;
    let resource_id = payment_request_create_attestation_resource_id(&body)?;
    auth::enforce_payment_mutation_attestation(
        &state,
        &headers,
        &user.principal,
        "payments_requests_create",
        &resource_id,
    )
    .await?;
    let headers = payments_headers_with_idempotency(&headers)?;
    let out = proxy_payments(
        &state,
        Method::POST,
        "/requests",
        Vec::new(),
        Some(body),
        &headers,
        H_PAY_TOPUP,
    )
    .await?;
    let response = json_no_store_response(out.0.clone());
    let request_id = out
        .0
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let to_wallet_id = out
        .0
        .get("to_wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let amount_cents = out
        .0
        .get("amount_cents")
        .and_then(Value::as_i64)
        .unwrap_or_default();
    let currency = out.0.get("currency").and_then(Value::as_str);
    if let (Some(request_id), Some(to_wallet_id)) = (request_id, to_wallet_id) {
        if let Err(error) = push_payment_request_notification_to_wallet_owner(
            &state,
            &headers,
            to_wallet_id,
            request_id,
            amount_cents,
            currency,
        )
        .await
        {
            tracing::warn!(
                error = ?error,
                request_id_hash = %auth::hash_prefix(request_id),
                to_wallet_hash = %auth::hash_prefix(to_wallet_id),
                "payment request push failed"
            );
        }
    }
    Ok(response)
}

