pub async fn payments_requests_accept(
    Path(rid): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<PaymentsRequestAcceptIn>,
) -> ApiResult<Response> {
    let rid = required_payments_resource_path(&rid, "request_id")?;
    let user =
        require_payment_mutation_user_context(&state, &headers, "payments_requests_accept").await?;
    // Avoid pre-read TOCTOU: the payments service enforces request ownership
    // and status transitions atomically while preserving idempotent replay.
    let body = canonical_payments_request_accept_body(&user.wallet_id, body)?;
    let resource_id = payment_request_accept_attestation_resource_id(&rid, &user.wallet_id);
    auth::enforce_payment_mutation_attestation(
        &state,
        &headers,
        &user.principal,
        "payments_requests_accept",
        &resource_id,
    )
    .await?;
    let headers = payments_headers_with_idempotency(&headers)?;
    let out = proxy_payments(
        &state,
        Method::POST,
        &format!("/requests/{}/accept", escaped_path_segment(&rid)),
        Vec::new(),
        Some(body),
        &headers,
        H_PAY_TOPUP,
    )
    .await?;
    let response = json_no_store_response(out.0.clone());
    match proxy_payments(
        &state,
        Method::GET,
        &format!("/requests/{}", escaped_path_segment(&rid)),
        vec![("wallet_id".to_string(), user.wallet_id.clone())],
        None,
        &headers,
        H_USER_AGENT,
    )
    .await
    {
        Ok(request_out) => {
            let from_wallet_id = request_out
                .0
                .get("from_wallet_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty());
            let amount_cents = request_out
                .0
                .get("amount_cents")
                .and_then(Value::as_i64)
                .unwrap_or_default();
            let currency = request_out.0.get("currency").and_then(Value::as_str);
            if let Some(from_wallet_id) = from_wallet_id {
                if let Err(error) = push_payment_credit_notification_to_wallet_owner(
                    &state,
                    &headers,
                    from_wallet_id,
                    amount_cents,
                    currency,
                )
                .await
                {
                    tracing::warn!(
                        error = ?error,
                        request_id_hash = %auth::hash_prefix(&rid),
                        from_wallet_hash = %auth::hash_prefix(from_wallet_id),
                        "accepted payment request credit push failed"
                    );
                }
            }
        }
        Err(error) => {
            tracing::warn!(
                error = ?error,
                request_id_hash = %auth::hash_prefix(&rid),
                "accepted payment request detail reload failed"
            );
        }
    }
    Ok(response)
}

