fn payments_body_object(body: Value) -> ApiResult<Map<String, Value>> {
    match body {
        Value::Object(map) => Ok(map),
        _ => Err(ApiError::bad_request("JSON object body required")),
    }
}

fn payments_query_with_wallet(
    wallet_id: String,
    q: HashMap<String, String>,
) -> Vec<(String, String)> {
    let mut query = vec![("wallet_id".to_string(), wallet_id)];
    for key in ["status", "limit", "from_iso", "to_iso", "kind", "dir"] {
        if let Some(value) = q
            .get(key)
            .map(String::as_str)
            .map(str::trim)
            .filter(|v| !v.is_empty())
        {
            query.push((key.to_string(), value.to_string()));
        }
    }
    query
}

fn payments_forward_query(q: HashMap<String, String>, keys: &[&str]) -> Vec<(String, String)> {
    keys.iter()
        .filter_map(|key| {
            q.get(*key)
                .map(String::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(|value| ((*key).to_string(), value.to_string()))
        })
        .collect()
}

#[allow(clippy::too_many_arguments)]
fn payments_wallet_snapshot_query_from_parts(
    limit: Option<i64>,
    dir: Option<&str>,
    kind: Option<&str>,
    from_iso: Option<&str>,
    to_iso: Option<&str>,
    before_created_at: Option<&str>,
    before_id: Option<&str>,
) -> ApiResult<Vec<(String, String)>> {
    let mut query = Vec::new();
    push_limit_query(&mut query, "limit", limit, 50, 1, 200);

    if let Some(dir_raw) = dir.map(str::trim).filter(|v| !v.is_empty()) {
        let dir = dir_raw.to_ascii_lowercase();
        match dir.as_str() {
            "all" => {}
            "in" | "out" => query.push(("dir".to_string(), dir)),
            _ => return Err(ApiError::bad_request("dir must be one of: all, in, out")),
        }
    }
    if let Some(kind) = normalize_wallet_snapshot_kind_filter(kind)? {
        query.push(("kind".to_string(), kind));
    }
    push_iso_range_query(&mut query, from_iso, to_iso)?;
    push_before_cursor_query(&mut query, before_created_at, before_id)?;
    Ok(query)
}

fn json_array_has_id(value: &Value, id: &str) -> bool {
    value.as_array().is_some_and(|items| {
        items.iter().any(|item| {
            item.get("id")
                .and_then(Value::as_str)
                .map(str::trim)
                .is_some_and(|candidate| candidate == id)
        })
    })
}

fn normalize_wallet_statement_format(raw: Option<&str>) -> ApiResult<&'static str> {
    let Some(format_raw) = raw.map(str::trim).filter(|v| !v.is_empty()) else {
        return Ok("json");
    };
    match format_raw.to_ascii_lowercase().as_str() {
        "json" => Ok("json"),
        "csv" => Ok("csv"),
        "pdf" => Ok("pdf"),
        _ => Err(ApiError::bad_request(
            "format must be one of: json, csv, pdf",
        )),
    }
}

fn statement_field(value: Option<&Value>) -> String {
    match value {
        Some(Value::String(text)) => text.clone(),
        Some(Value::Number(number)) => number.to_string(),
        Some(Value::Bool(value)) => value.to_string(),
        Some(Value::Null) | None => String::new(),
        Some(other) => other.to_string(),
    }
}

fn csv_cell(raw: &str) -> String {
    format!("\"{}\"", raw.replace('"', "\"\""))
}

fn wallet_statement_csv(snapshot: &Value) -> String {
    let mut rows = vec![vec![
        "id".to_string(),
        "created_at".to_string(),
        "kind".to_string(),
        "from_wallet_id".to_string(),
        "to_wallet_id".to_string(),
        "amount_cents".to_string(),
        "fee_cents".to_string(),
        "meta".to_string(),
    ]];
    if let Some(txns) = snapshot.get("txns").and_then(Value::as_array) {
        for txn in txns {
            rows.push(vec![
                statement_field(txn.get("id")),
                statement_field(txn.get("created_at")),
                statement_field(txn.get("kind")),
                statement_field(txn.get("from_wallet_id")),
                statement_field(txn.get("to_wallet_id")),
                statement_field(txn.get("amount_cents")),
                statement_field(txn.get("fee_cents")),
                statement_field(txn.get("meta")),
            ]);
        }
    }
    rows.into_iter()
        .map(|row| {
            row.iter()
                .map(|cell| csv_cell(cell))
                .collect::<Vec<_>>()
                .join(",")
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn pdf_string_safe(raw: &str) -> String {
    raw.chars()
        .map(|ch| {
            if ch.is_ascii_graphic() || ch == ' ' {
                ch
            } else {
                '?'
            }
        })
        .collect::<String>()
        .replace('\\', "\\\\")
        .replace('(', "\\(")
        .replace(')', "\\)")
}

fn simple_statement_pdf(lines: &[String]) -> Vec<u8> {
    let mut content = String::from("BT\n/F1 10 Tf\n50 792 Td\n12 TL\n");
    for line in lines.iter().take(58) {
        let mut line = line.clone();
        if line.len() > 105 {
            line.truncate(105);
        }
        content.push('(');
        content.push_str(&pdf_string_safe(&line));
        content.push_str(") Tj\nT*\n");
    }
    content.push_str("ET\n");

    let objects = vec![
        "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n".to_string(),
        "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n".to_string(),
        "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>\nendobj\n".to_string(),
        format!(
            "4 0 obj\n<< /Length {} >>\nstream\n{}endstream\nendobj\n",
            content.len(),
            content
        ),
        "5 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n".to_string(),
    ];

    let mut pdf = String::from("%PDF-1.4\n");
    let mut offsets = Vec::with_capacity(objects.len());
    for object in &objects {
        offsets.push(pdf.len());
        pdf.push_str(object);
    }
    let xref_offset = pdf.len();
    pdf.push_str("xref\n0 6\n0000000000 65535 f \n");
    for offset in offsets {
        pdf.push_str(&format!("{offset:010} 00000 n \n"));
    }
    pdf.push_str(&format!(
        "trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n{xref_offset}\n%%EOF\n"
    ));
    pdf.into_bytes()
}

fn wallet_statement_pdf(snapshot: &Value) -> Vec<u8> {
    let wallet = snapshot.get("wallet");
    let wallet_id = statement_field(wallet.and_then(|value| value.get("id")));
    let currency = statement_field(wallet.and_then(|value| value.get("currency")));
    let balance = statement_field(wallet.and_then(|value| value.get("balance_cents")));
    let mut lines = vec![
        "Shamell wallet statement".to_string(),
        format!("Wallet: {wallet_id}"),
        format!("Currency: {currency}"),
        format!("Balance cents: {balance}"),
        String::new(),
        "Transactions".to_string(),
    ];
    if let Some(txns) = snapshot.get("txns").and_then(Value::as_array) {
        for txn in txns.iter().take(50) {
            lines.push(format!(
                "{} | {} | {} | {} cents | fee {}",
                statement_field(txn.get("created_at")),
                statement_field(txn.get("kind")),
                statement_field(txn.get("id")),
                statement_field(txn.get("amount_cents")),
                statement_field(txn.get("fee_cents")),
            ));
        }
    }
    simple_statement_pdf(&lines)
}

pub async fn payments_wallet_statement(
    Path(wallet_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<WalletStatementQuery>,
) -> ApiResult<Response> {
    let wallet_id = required_payments_resource_path(&wallet_id, "wallet_id")?;
    let user = require_user_context(&state, &headers).await?;
    if wallet_id != user.wallet_id {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "wallet_id must match authenticated user",
        ));
    }
    let format = normalize_wallet_statement_format(q.format.as_deref())?;
    let query = payments_wallet_snapshot_query_from_parts(
        q.limit,
        q.dir.as_deref(),
        q.kind.as_deref(),
        q.from_iso.as_deref(),
        q.to_iso.as_deref(),
        q.before_created_at.as_deref(),
        q.before_id.as_deref(),
    )?;
    let out = proxy_payments(
        &state,
        Method::GET,
        &format!("/wallets/{}/snapshot", escaped_path_segment(&wallet_id)),
        query,
        None,
        &headers,
        H_USER_AGENT,
    )
    .await?;
    match format {
        "json" => Ok(json_no_store_response(out.0)),
        "csv" => Ok(bytes_no_store_attachment_response(
            "text/csv; charset=utf-8",
            "attachment; filename=\"wallet-statement.csv\"",
            wallet_statement_csv(&out.0).into_bytes(),
        )),
        "pdf" => Ok(bytes_no_store_attachment_response(
            "application/pdf",
            "attachment; filename=\"wallet-statement.pdf\"",
            wallet_statement_pdf(&out.0),
        )),
        _ => unreachable!("statement format is normalized"),
    }
}

