pub async fn payments_mini_payment_intents_get(
    Path(intent_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let intent_id = required_payments_resource_path(&intent_id, "intent_id")?;
    let user = require_user_context(&state, &headers).await?;
    let out = proxy_payments(
        &state,
        Method::GET,
        &format!("/mini/payment-intents/{}", escaped_path_segment(&intent_id)),
        Vec::new(),
        None,
        &headers,
        H_USER_AGENT,
    )
    .await?;
    if out
        .0
        .get("wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .is_none_or(|wallet_id| wallet_id != user.wallet_id)
    {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "intent_id must belong to authenticated wallet",
        ));
    }
    Ok(json_no_store_response(out.0))
}

