pub async fn moments_geo_reverse(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<MomentsGeoReverseQuery>,
) -> ApiResult<Response> {
    let principal = auth::require_session_principal(&state, &headers).await?;
    if !q.lat.is_finite() || !q.lon.is_finite() {
        return Err(ApiError::bad_request("lat/lon must be finite"));
    }
    if !(-90.0..=90.0).contains(&q.lat) {
        return Err(ApiError::bad_request("lat must be between -90 and 90"));
    }
    if !(-180.0..=180.0).contains(&q.lon) {
        return Err(ApiError::bad_request("lon must be between -180 and 180"));
    }
    auth::enforce_geo_lookup_rate_limit(&state, &headers, &principal, "reverse").await?;

    let payload = fetch_nominatim_json(
        &state,
        "/reverse",
        &[
            ("lat", format!("{:.4}", round_nominatim_coordinate(q.lat))),
            ("lon", format!("{:.4}", round_nominatim_coordinate(q.lon))),
            ("format", "jsonv2".to_string()),
            ("zoom", "18".to_string()),
        ],
        sanitize_geo_accept_language(&headers),
    )
    .await?;

    Ok(json_no_store_response(sanitize_reverse_geocode_payload(
        &payload,
    )))
}

pub async fn moments_geo_search(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<MomentsGeoSearchQuery>,
) -> ApiResult<Response> {
    let principal = auth::require_session_principal(&state, &headers).await?;
    let query = q.q.trim();
    if query.len() < 2 {
        return Err(ApiError::bad_request("q must be at least 2 characters"));
    }
    if query.chars().count() > 120 {
        return Err(ApiError::bad_request("q must be at most 120 characters"));
    }
    auth::enforce_geo_lookup_rate_limit(&state, &headers, &principal, "search").await?;

    let payload = fetch_nominatim_json(
        &state,
        "/search",
        &[
            ("q", query.to_string()),
            ("format", "jsonv2".to_string()),
            ("limit", NOMINATIM_RESULT_LIMIT.to_string()),
        ],
        sanitize_geo_accept_language(&headers),
    )
    .await?;

    Ok(json_no_store_response(sanitize_search_geocode_payload(
        &payload,
    )))
}

pub async fn rides_search(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideSearchQuery>,
) -> ApiResult<Response> {
    let principal = auth::require_session_principal(&state, &headers).await?;
    let query = q.q.trim();
    if query.len() < 2 {
        return Err(ApiError::bad_request("q must be at least 2 characters"));
    }
    if query.chars().count() > 120 {
        return Err(ApiError::bad_request("q must be at most 120 characters"));
    }
    if q.lat.is_some() ^ q.lon.is_some() {
        return Err(ApiError::bad_request("lat/lon must be provided together"));
    }
    if let (Some(lat), Some(lon)) = (q.lat, q.lon) {
        validate_finite_lat_lon(lat, lon)?;
    }

    auth::enforce_geo_lookup_rate_limit(&state, &headers, &principal, "ride_search").await?;

    let limit = clamp_ride_search_limit(q.limit);
    let query_params = vec![
        ("q", query.to_string()),
        ("format", "jsonv2".to_string()),
        ("limit", limit.to_string()),
        ("countrycodes", RIDE_SEARCH_COUNTRY_CODES.to_string()),
        ("dedupe", "1".to_string()),
    ];
    let near = match (q.lat, q.lon) {
        (Some(lat), Some(lon)) => {
            Some((round_tomtom_coordinate(lat), round_tomtom_coordinate(lon)))
        }
        _ => None,
    };

    let payload = fetch_nominatim_json(
        &state,
        "/search",
        &query_params,
        sanitize_geo_accept_language(&headers),
    )
    .await?;
    Ok(json_no_store_response(
        sanitize_nominatim_ride_search_payload(&payload, limit, near),
    ))
}

