pub async fn coach_journey_live_get(
    Path(journey_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let principal = auth::require_session_principal(&state, &headers).await?;
    let journey_id = validate_coach_resource_id(&journey_id, "journey_id")?;
    let feed_health = coach_catalog_feed_health_best_effort(&state)
        .await
        .unwrap_or_default();
    let aggregates =
        coach_list_booking_aggregates_for_request(&state, principal.account_id.as_str())
            .await
            .map_err(|error| coach_storage_error("coach journey live store unavailable", error))?;
    let runtime_trip_groups = coach_runtime_trip_groups_for_request(&state, aggregates)
        .await
        .map_err(|error| coach_storage_error("coach journey live store unavailable", error))?;
    if let Some((trip_id, trip_aggregates, aggregate)) =
        coach_find_runtime_trip_group_matching_aggregate(&runtime_trip_groups, |candidate| {
            coach_booking_journey_payload_from_aggregate(candidate)
                .get("journey_id")
                .and_then(Value::as_str)
                == Some(journey_id.as_str())
        })
    {
        let event_map = coach_load_boarding_event_map(&state, Some(trip_id)).await?;
        let operator_id = coach_runtime_trip_group_operator_id(trip_aggregates, trip_id);
        let journey = coach_runtime_trip_group_journey_payload(trip_aggregates, trip_id);
        return Ok(json_no_store_response(
            coach_journey_live_payload_from_aggregate(
                aggregate,
                trip_aggregates,
                &journey,
                trip_id,
                &operator_id,
                &event_map,
                &feed_health,
            ),
        ));
    }

    let Some(seed) = coach_demo_booking_seed_by_journey_id(&journey_id) else {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    };
    let trip_id = coach_demo_trip_id_for_booking_seed(&seed);
    let event_map = coach_load_boarding_event_map(&state, Some(&trip_id)).await?;
    Ok(json_no_store_response(
        coach_journey_live_payload_from_seed(&seed, &event_map, &feed_health),
    ))
}

