pub async fn coach_admin_finance_journal(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<CoachAdminFinanceJournalQuery>,
) -> ApiResult<Response> {
    let (_principal, _roles) = auth::require_ride_admin_principal(&state, &headers).await?;
    let limit = coach_operator_queue_limit(q.limit);
    let search_query = normalize_coach_support_case_search_query(q.q.as_deref())?;
    coach_sync_subledger_from_derived_finance_state(&state).await?;
    let mut entries = coach_load_subledger_entry_map(&state)
        .await?
        .into_values()
        .map(|entry| coach_subledger_entry_payload(&entry))
        .collect::<Vec<_>>();
    let admin_risks = coach_collect_admin_risks_with_action_state(&state).await?;
    entries.extend(
        admin_risks
            .iter()
            .filter_map(coach_admin_finance_auto_case_entry_payload),
    );

    entries.retain(|entry| coach_admin_finance_entry_matches_query(entry, search_query.as_deref()));
    entries.sort_by(|left, right| {
        right["occurred_at"]
            .as_str()
            .unwrap_or_default()
            .cmp(left["occurred_at"].as_str().unwrap_or_default())
            .then_with(|| {
                right["entry_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(left["entry_id"].as_str().unwrap_or_default())
            })
    });

    let summary = coach_admin_finance_summary_payload(entries.as_slice());

    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "summary": summary,
        "entries": entries.into_iter().take(limit).collect::<Vec<_>>(),
    })))
}

pub async fn coach_admin_shamell_pay_reconciliation(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<CoachAdminShamellPayReconciliationQuery>,
) -> ApiResult<Response> {
    let (_principal, _roles) = auth::require_ride_admin_principal(&state, &headers).await?;
    let limit = coach_operator_queue_limit(q.limit);
    let search_query = normalize_coach_support_case_search_query(q.q.as_deref())?;
    coach_sync_subledger_from_derived_finance_state(&state).await?;
    let subledger_entries = coach_load_subledger_entry_map(&state)
        .await?
        .into_values()
        .map(|entry| coach_subledger_entry_payload(&entry))
        .collect::<Vec<_>>();
    let shamell_pay_clearing_minor_units =
        coach_admin_finance_summary_account_total(&subledger_entries, "psp_clearing");
    let settlement_in_transit_minor_units =
        coach_admin_finance_summary_account_total(&subledger_entries, "settlement_in_transit");

    let payout_run_map = coach_load_settlement_payout_run_map(&state).await?;
    let payout_import_map = coach_load_settlement_payout_import_map(&state).await?;
    let all_runs = coach_filter_payout_runs(&payout_run_map, None);
    let mut imports_by_run = HashMap::<String, Vec<CoachSettlementPayoutImportEntry>>::new();
    for import in coach_filter_payout_imports(&payout_import_map, None) {
        imports_by_run
            .entry(import.payout_run_id.clone())
            .or_default()
            .push(import);
    }
    for imports in imports_by_run.values_mut() {
        imports.sort_by(|left, right| {
            right
                .imported_at
                .cmp(&left.imported_at)
                .then_with(|| right.import_id.cmp(&left.import_id))
        });
    }

    let mut entries = all_runs
        .iter()
        .map(|run| {
            let shamell_pay_attempts = coach_admin_shamell_pay_imports_for_sources(
                &imports_by_run,
                run.payout_run_id.as_str(),
                &["psp_report"],
            );
            let downstream_attempts = coach_admin_shamell_pay_imports_for_sources(
                &imports_by_run,
                run.payout_run_id.as_str(),
                &["bank_report", "manual_upload"],
            );
            coach_admin_shamell_pay_reconciliation_entry_payload(
                run,
                shamell_pay_attempts.as_slice(),
                downstream_attempts.as_slice(),
            )
        })
        .collect::<Vec<_>>();

    entries.retain(|entry| {
        coach_admin_shamell_pay_reconciliation_entry_matches_query(entry, search_query.as_deref())
    });
    entries.sort_by(|left, right| {
        right["occurred_at"]
            .as_str()
            .unwrap_or_default()
            .cmp(left["occurred_at"].as_str().unwrap_or_default())
            .then_with(|| {
                right["entry_id"]
                    .as_str()
                    .unwrap_or_default()
                    .cmp(left["entry_id"].as_str().unwrap_or_default())
            })
    });
    let summary = coach_admin_shamell_pay_reconciliation_summary_payload(
        entries.as_slice(),
        shamell_pay_clearing_minor_units,
        settlement_in_transit_minor_units,
    );

    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "summary": summary,
        "runs": entries.into_iter().take(limit).collect::<Vec<_>>(),
    })))
}

pub async fn coach_admin_shamell_pay_report_import_create(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachAdminShamellPayReportImportCreateIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let report_name = validate_coach_payout_import_report_name(&body.report_name)?;
    let report_format = canonical_coach_payout_import_report_format(&body.report_format)?;
    let report_body = validate_coach_payout_import_report_body(&body.report_body)?;
    let expected_preview_token =
        validate_coach_optional_preview_token(body.expected_preview_token.as_deref())?;
    let dry_run = body.dry_run.unwrap_or(false);
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    coach_operator_payout_import_batch_create_core(
        CoachOperatorPayoutImportBatchCreateCoreRequest {
            state: &state,
            principal_account_id: principal.account_id.as_str(),
            allowed_operator_scope: &allowed_operator_scope,
            idempotency_key: &idempotency_key,
            import_source: "psp_report",
            report_name,
            report_format,
            report_body,
            rework_of_batch_id: None,
            expected_preview_token,
            dry_run,
            note,
        },
    )
    .await
}

pub async fn coach_admin_shamell_pay_release_operator_rail(
    Path(payout_run_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachAdminShamellPayOperatorRailReleaseIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let payout_run_id = validate_coach_resource_id(&payout_run_id, "payout_run_id")?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let external_reference = validate_coach_external_reference(body.external_reference.as_deref())?
        .or_else(|| {
            Some(
                coach_admin_shamell_pay_release_operator_rail_external_reference(
                    payout_run_id.as_str(),
                ),
            )
        });
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "payout_run_id": payout_run_id.clone(),
        "note": note.clone(),
        "external_reference": external_reference.clone(),
    });
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_admin_shamell_pay_operator_rail_release",
        &command_payload,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_admin_shamell_pay_operator_rail_release",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let payout_run_map = coach_load_settlement_payout_run_map(&state).await?;
    let payout_run = payout_run_map
        .get(payout_run_id.as_str())
        .cloned()
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    let payout_import_map = coach_load_settlement_payout_import_map(&state).await?;
    let mut imports_by_run = HashMap::<String, Vec<CoachSettlementPayoutImportEntry>>::new();
    for import in coach_filter_payout_imports(&payout_import_map, None) {
        imports_by_run
            .entry(import.payout_run_id.clone())
            .or_default()
            .push(import);
    }

    let shamell_pay_import = coach_admin_shamell_pay_latest_import_for_sources(
        &imports_by_run,
        payout_run.payout_run_id.as_str(),
        &["psp_report"],
    );
    let downstream_import = coach_admin_shamell_pay_latest_import_for_sources(
        &imports_by_run,
        payout_run.payout_run_id.as_str(),
        &["bank_report", "manual_upload"],
    );
    let reconciliation_status = coach_admin_shamell_pay_reconciliation_status(
        &payout_run,
        shamell_pay_import,
        downstream_import,
    );
    if reconciliation_status != "operator_rail_pending"
        && !matches!(
            downstream_import.map(|entry| entry.external_status.as_str()),
            Some("pending" | "executed" | "failed")
        )
    {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "operator rail release requires Shamell Pay execution first",
        ));
    }

    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let statement_map = coach_operator_statement_values_by_id_for_request(
        &state,
        principal.account_id.as_str(),
        &review_map,
        &event_map,
        &payout_run_map,
    )
    .await
    .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
    let statements = payout_run
        .statement_ids
        .iter()
        .filter_map(|statement_id| statement_map.get(statement_id.as_str()).cloned())
        .collect::<Vec<_>>();
    if statements.len() != payout_run.statement_ids.len() {
        return Err(ApiError::internal(
            "coach settlement export store unavailable",
        ));
    }

    let mut export_map = coach_load_settlement_export_map(&state).await?;
    let missing_formats =
        coach_operator_payout_run_missing_export_formats(&payout_run, &statement_map, &export_map);
    if !missing_formats.is_empty() {
        let export_note = note
            .clone()
            .or_else(|| Some("Generated during Shamell Pay operator rail release.".to_string()));
        for export_format in missing_formats {
            let export = coach_build_settlement_export_entry(
                coach_scoped_resource_id(
                    "export",
                    &format!(
                        "{}-{}-{}",
                        principal.account_id, payout_run.payout_run_id, export_format
                    ),
                ),
                &payout_run,
                statements.as_slice(),
                export_format.as_str(),
                coach_runtime_settlement_export_created_at().as_str(),
                principal.account_id.as_str(),
                export_note.clone(),
            );
            let inserted = coach_insert_settlement_export_entry(&state, &export).await?;
            if inserted {
                export_map.insert(export.export_id.clone(), export);
            }
        }
        export_map = coach_load_settlement_export_map(&state).await?;
    }

    if let Some(existing_import) = downstream_import {
        if existing_import.external_status != "failed" {
            let next_action = match existing_import.external_status.as_str() {
                "executed" => "downstream_already_confirmed",
                _ => "operator_rail_already_released",
            };
            let response_json = coach_admin_shamell_pay_operator_rail_release_response(
                &idempotency_key,
                &request_fingerprint,
                existing_import,
                &payout_run,
                &statement_map,
                &export_map,
                next_action,
            );
            return coach_store_or_replay_idempotent_response(
                &state,
                principal.account_id.as_str(),
                "coach_admin_shamell_pay_operator_rail_release",
                &idempotency_key,
                &request_fingerprint,
                response_json,
            )
            .await;
        }
    }

    let imported_at = now_rfc3339();
    let planned_import = coach_admin_shamell_pay_operator_rail_import_entry(
        &CoachAdminShamellPayOperatorRailImportRequest {
            principal_account_id: principal.account_id.as_str(),
            payout_run: &payout_run,
            import_status: "pending",
            import_trace_id: request_fingerprint.as_str(),
            imported_at: imported_at.as_str(),
            payment_reference: None,
            external_reference,
            note,
        },
    );
    let inserted = coach_insert_settlement_payout_import_entry(&state, &planned_import).await?;
    let payout_import = if inserted {
        planned_import
    } else {
        coach_load_settlement_payout_import_map(&state)
            .await?
            .remove(planned_import.import_id.as_str())
            .ok_or_else(|| ApiError::internal("coach payout import store unavailable"))?
    };
    coach_sync_subledger_from_derived_finance_state(&state).await?;
    let response_json = coach_admin_shamell_pay_operator_rail_release_response(
        &idempotency_key,
        &request_fingerprint,
        &payout_import,
        &payout_run,
        &statement_map,
        &export_map,
        "await_downstream_payout_confirmation",
    );
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_admin_shamell_pay_operator_rail_release",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

pub async fn coach_admin_shamell_pay_confirm_operator_rail(
    Path(payout_run_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachAdminShamellPayOperatorRailConfirmIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let payout_run_id = validate_coach_resource_id(&payout_run_id, "payout_run_id")?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?
        .or_else(|| Some("Confirmed from Shamell Pay reconciliation.".to_string()));
    let payment_reference = validate_coach_payment_reference(body.payment_reference.as_deref())?
        .or_else(|| {
            Some(
                coach_admin_shamell_pay_confirm_operator_rail_payment_reference(
                    payout_run_id.as_str(),
                ),
            )
        });
    let external_reference = validate_coach_external_reference(body.external_reference.as_deref())?
        .or_else(|| {
            Some(
                coach_admin_shamell_pay_confirm_operator_rail_external_reference(
                    payout_run_id.as_str(),
                ),
            )
        });
    let imported_at = validate_coach_imported_at(body.imported_at.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "payout_run_id": payout_run_id.clone(),
        "payment_reference": payment_reference.clone(),
        "external_reference": external_reference.clone(),
        "imported_at": imported_at.clone(),
        "note": note.clone(),
    });
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_admin_shamell_pay_operator_rail_confirm",
        &command_payload,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_admin_shamell_pay_operator_rail_confirm",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let payout_run_map = coach_load_settlement_payout_run_map(&state).await?;
    let payout_run = payout_run_map
        .get(payout_run_id.as_str())
        .cloned()
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    let payout_import_map = coach_load_settlement_payout_import_map(&state).await?;
    let mut imports_by_run = HashMap::<String, Vec<CoachSettlementPayoutImportEntry>>::new();
    for import in coach_filter_payout_imports(&payout_import_map, None) {
        imports_by_run
            .entry(import.payout_run_id.clone())
            .or_default()
            .push(import);
    }

    let shamell_pay_import = coach_admin_shamell_pay_latest_import_for_sources(
        &imports_by_run,
        payout_run.payout_run_id.as_str(),
        &["psp_report"],
    );
    let downstream_import = coach_admin_shamell_pay_latest_import_for_sources(
        &imports_by_run,
        payout_run.payout_run_id.as_str(),
        &["bank_report", "manual_upload"],
    );
    if !matches!(
        shamell_pay_import.map(|entry| entry.external_status.as_str()),
        Some("executed")
    ) {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "operator rail confirmation requires Shamell Pay execution first",
        ));
    }
    if matches!(
        downstream_import.map(|entry| entry.external_status.as_str()),
        Some("executed")
    ) {
        let review_map = coach_load_ops_review_map(&state).await?;
        let event_map = coach_load_boarding_event_map(&state, None).await?;
        let statement_map = coach_operator_statement_values_by_id_for_request(
            &state,
            principal.account_id.as_str(),
            &review_map,
            &event_map,
            &payout_run_map,
        )
        .await
        .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
        let export_map = coach_load_settlement_export_map(&state).await?;
        let response_json = coach_admin_shamell_pay_operator_rail_confirm_response(
            &idempotency_key,
            &request_fingerprint,
            downstream_import.expect("executed import checked"),
            &payout_run,
            &statement_map,
            &export_map,
            "reconciliation_closed",
        );
        return coach_store_or_replay_idempotent_response(
            &state,
            principal.account_id.as_str(),
            "coach_admin_shamell_pay_operator_rail_confirm",
            &idempotency_key,
            &request_fingerprint,
            response_json,
        )
        .await;
    }
    if matches!(
        downstream_import.map(|entry| entry.external_status.as_str()),
        Some("failed")
    ) {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "operator rail is currently marked failed",
        ));
    }

    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let statement_map = coach_operator_statement_values_by_id_for_request(
        &state,
        principal.account_id.as_str(),
        &review_map,
        &event_map,
        &payout_run_map,
    )
    .await
    .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
    let statements = payout_run
        .statement_ids
        .iter()
        .filter_map(|statement_id| statement_map.get(statement_id.as_str()).cloned())
        .collect::<Vec<_>>();
    if statements.len() != payout_run.statement_ids.len() {
        return Err(ApiError::internal(
            "coach settlement export store unavailable",
        ));
    }

    let mut export_map = coach_load_settlement_export_map(&state).await?;
    let missing_formats =
        coach_operator_payout_run_missing_export_formats(&payout_run, &statement_map, &export_map);
    if !missing_formats.is_empty() {
        let export_note = note.clone().or_else(|| {
            Some("Generated during Shamell Pay operator rail confirmation.".to_string())
        });
        for export_format in missing_formats {
            let export = coach_build_settlement_export_entry(
                coach_scoped_resource_id(
                    "export",
                    &format!(
                        "{}-{}-{}",
                        principal.account_id, payout_run.payout_run_id, export_format
                    ),
                ),
                &payout_run,
                statements.as_slice(),
                export_format.as_str(),
                coach_runtime_settlement_export_created_at().as_str(),
                principal.account_id.as_str(),
                export_note.clone(),
            );
            let inserted = coach_insert_settlement_export_entry(&state, &export).await?;
            if inserted {
                export_map.insert(export.export_id.clone(), export);
            }
        }
        export_map = coach_load_settlement_export_map(&state).await?;
    }

    let planned_import = coach_admin_shamell_pay_operator_rail_import_entry(
        &CoachAdminShamellPayOperatorRailImportRequest {
            principal_account_id: principal.account_id.as_str(),
            payout_run: &payout_run,
            import_status: "executed",
            import_trace_id: request_fingerprint.as_str(),
            imported_at: imported_at.as_str(),
            payment_reference,
            external_reference,
            note,
        },
    );
    let inserted = coach_insert_settlement_payout_import_entry(&state, &planned_import).await?;
    let payout_import = if inserted {
        planned_import
    } else {
        coach_load_settlement_payout_import_map(&state)
            .await?
            .remove(planned_import.import_id.as_str())
            .ok_or_else(|| ApiError::internal("coach payout import store unavailable"))?
    };
    coach_sync_subledger_from_derived_finance_state(&state).await?;
    let response_json = coach_admin_shamell_pay_operator_rail_confirm_response(
        &idempotency_key,
        &request_fingerprint,
        &payout_import,
        &payout_run,
        &statement_map,
        &export_map,
        "reconciliation_closed",
    );
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_admin_shamell_pay_operator_rail_confirm",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

