pub async fn coach_admin_partner_onboarding(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<CoachAdminPartnerOnboardingQuery>,
) -> ApiResult<Response> {
    let (_principal, _roles) = auth::require_ride_admin_principal(&state, &headers).await?;
    let limit = coach_operator_queue_limit(q.limit);
    let search_query = normalize_coach_support_case_search_query(q.q.as_deref())?;
    let workflow_status_filter = q
        .workflow_status
        .as_deref()
        .map(canonical_coach_admin_partner_workflow_status)
        .transpose()?;
    let mut records = coach_collect_admin_partner_onboarding_records(&state).await?;
    if let Some(workflow_status) = workflow_status_filter {
        records.retain(|record| record["workflow_status"].as_str() == Some(workflow_status));
    }
    if let Some(query) = search_query.as_deref() {
        records.retain(|record| coach_admin_partner_matches_query(record, query));
    }
    let summary = coach_admin_partner_onboarding_summary_payload(records.as_slice());
    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "summary": summary,
        "partners": records.into_iter().take(limit).collect::<Vec<_>>(),
    })))
}

pub async fn coach_admin_partner_onboarding_action(
    Path(operator_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachAdminPartnerOnboardingActionIn>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_admin_principal(&state, &headers).await?;
    let operator_id = validate_coach_resource_id(&operator_id, "operator_id")?;
    let action = canonical_coach_admin_partner_onboarding_action(&body.action)?;
    let owner_account_id =
        validate_coach_admin_risk_owner_account_id(body.owner_account_id.as_deref())?;
    let due_at = validate_coach_admin_partner_due_at(body.due_at.as_deref())?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "operator_id": operator_id.clone(),
        "action": action,
        "owner_account_id": owner_account_id.clone(),
        "due_at": due_at.clone(),
        "note": note.clone(),
    });
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_admin_partner_onboarding_action",
        &command_payload,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_admin_partner_onboarding_action",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let feed_health = coach_catalog_feed_health_best_effort(&state)
        .await
        .unwrap_or_default();
    let operators = coach_collect_admin_partner_base_operators(feed_health.as_slice());
    let operator = operators
        .into_iter()
        .find(|candidate| candidate.operator_id == operator_id)
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    let existing_actions = coach_load_admin_partner_onboarding_action_map(&state).await?;
    let existing_entry = existing_actions.get(operator_id.as_str()).cloned();
    let default_workflow_status = coach_admin_partner_default_workflow_status(&operator);
    let updated_at = now_rfc3339();
    let updated_entry = CoachAdminPartnerOnboardingActionEntry {
        workflow_status: match action {
            "claim" => existing_entry
                .as_ref()
                .map(|entry| entry.workflow_status.clone())
                .unwrap_or_else(|| default_workflow_status.to_string()),
            "start_review" => "in_review".to_string(),
            "request_documents" => "action_required".to_string(),
            "approve" => "approved".to_string(),
            "suspend" => "suspended".to_string(),
            _ => "draft".to_string(),
        },
        last_action: action.to_string(),
        owner_account_id: owner_account_id
            .or_else(|| {
                existing_entry
                    .as_ref()
                    .and_then(|entry| entry.owner_account_id.clone())
            })
            .or_else(|| {
                if action == "claim" || action == "start_review" {
                    Some(principal.account_id.to_string())
                } else {
                    None
                }
            }),
        due_at: due_at
            .or_else(|| {
                existing_entry
                    .as_ref()
                    .and_then(|entry| entry.due_at.clone())
            })
            .or_else(|| {
                if matches!(action, "start_review" | "request_documents") {
                    Some(default_coach_admin_partner_due_at())
                } else {
                    None
                }
            }),
        updated_at: updated_at.clone(),
        updated_by_account_id: principal.account_id.to_string(),
        note: note.or_else(|| existing_entry.as_ref().and_then(|entry| entry.note.clone())),
    };
    coach_upsert_admin_partner_onboarding_action_entry(
        &state,
        operator_id.as_str(),
        &updated_entry,
    )
    .await?;
    let updated_partner =
        coach_admin_partner_onboarding_record_payload(&operator, Some(&updated_entry));
    let response_json = json!({
        "operator_id": operator_id,
        "action": action,
        "updated_at": updated_at,
        "partner": updated_partner,
    });
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_admin_partner_onboarding_action",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

