async fn coach_hold_create_response_for_request(
    request: &CoachHoldCreateResponseRequest<'_>,
) -> Value {
    let hold_id = coach_scoped_resource_id(
        "hold",
        &format!("{}|{}", request.offer_id, request.idempotency_key),
    );
    json!({
        "command": "hold_create",
        "idempotency": coach_idempotency_payload(
            request.idempotency_key,
            "coach_hold_create",
            request.request_fingerprint,
            &[(
                "inventory_hold",
                derived_internal_idempotency_key(
                    request.idempotency_key,
                    "coach_hold_inventory",
                ),
            )],
        ),
        "offer": coach_offer_payload_for_request(
            request.state,
            Some(request.account_id),
            request.offer_id,
            request.passengers,
        )
        .await,
        "hold": coach_hold_payload_for_offer(
            &hold_id,
            request.offer_id,
            request.passenger_ids,
            request.preferred_seat_numbers,
            "active",
        ),
        "booking_state": "hold_created",
        "hold_ttl_seconds": COACH_HOLD_TTL_SECS
    })
}

fn coach_booking_create_response_with_offer_payload(
    request: &CoachBookingCreateResponseRequest<'_>,
    offer_payload: Value,
) -> Value {
    let booking_id = coach_scoped_resource_id(
        "booking",
        &format!(
            "{}|{}|{}",
            request.offer_id,
            request.hold_id.unwrap_or("-"),
            request.idempotency_key
        ),
    );
    let total_minor_units = offer_payload["total_minor_units"]
        .as_i64()
        .unwrap_or_else(|| coach_offer_total_minor_units(request.offer_id, request.passengers));
    let hold_payload = request.hold_id.map(|value| {
        coach_hold_payload_for_offer(
            value,
            request.offer_id,
            request.passenger_ids,
            request.preferred_seat_numbers,
            "converted",
        )
    });
    let mut response = Map::new();
    response.insert(
        "command".to_string(),
        Value::String("booking_create".to_string()),
    );
    response.insert(
        "idempotency".to_string(),
        coach_idempotency_payload(
            request.idempotency_key,
            "coach_booking_create",
            request.request_fingerprint,
            &[
                (
                    "payment_authorize",
                    derived_internal_idempotency_key(
                        request.idempotency_key,
                        "coach_payment_authorize",
                    ),
                ),
                (
                    "booking_finalize",
                    derived_internal_idempotency_key(
                        request.idempotency_key,
                        "coach_booking_finalize",
                    ),
                ),
            ],
        ),
    );
    response.insert("offer".to_string(), offer_payload);
    if let Some(hold) = hold_payload {
        response.insert("hold".to_string(), hold);
    }
    if !request.passengers_manifest.is_empty() {
        response.insert(
            "passengers_manifest".to_string(),
            coach_passenger_manifest_payload(request.passengers_manifest),
        );
    }
    response.insert(
        "booking".to_string(),
        coach_booking_payload_for_offer(
            &booking_id,
            request.offer_id,
            request.hold_id,
            request.passengers,
            "booking_pending",
        ),
    );
    response.insert(
        "payment".to_string(),
        coach_payment_authorization_payload(&booking_id, request.payment_method, total_minor_units),
    );
    response.insert(
        "compensation".to_string(),
        coach_compensation_payload(
            "armed",
            "void_payment_or_issue_refund_credit",
            "coach_ticketing_failures",
            false,
            None,
            None,
        ),
    );
    response.insert(
        "next_action".to_string(),
        Value::String("issue_tickets".to_string()),
    );
    Value::Object(response)
}

