fn coach_refund_request_response(
    seed: &CoachDemoBookingSeed,
    idempotency_key: &str,
    request_fingerprint: &str,
    refund_kind: &str,
    ticket_ids: &[String],
    reason: Option<&str>,
) -> Value {
    let (requested_minor_units, fee_minor_units) = if refund_kind == "refund_credit" {
        (seed.refund_credit_minor_units, 0)
    } else {
        (
            seed.original_payment_minor_units,
            seed.original_payment_fee_minor_units,
        )
    };
    json!({
        "command": "refund_request",
        "idempotency": coach_idempotency_payload(
            idempotency_key,
            "coach_refund_request",
            request_fingerprint,
            &[
                (
                    "refund_authorize",
                    derived_internal_idempotency_key(idempotency_key, "coach_refund_authorize"),
                ),
                (
                    "ledger_posting",
                    derived_internal_idempotency_key(idempotency_key, "coach_refund_ledger_posting"),
                ),
            ],
        ),
        "booking": coach_booking_payload_for_offer(
            seed.booking_id,
            seed.offer_id,
            Some(seed.hold_id),
            seed.passengers_manifest.len() as u8,
            "refund_requested",
        ),
        "refund_request": coach_refund_request_payload(
            seed.booking_id,
            refund_kind,
            ticket_ids,
            reason,
            requested_minor_units,
            fee_minor_units,
        ),
        "compensation": coach_compensation_payload(
            "armed",
            "issue_refund_credit_or_raise_finance_case",
            "coach_refund_queue",
            false,
            None,
            None,
        ),
        "next_action": "await_refund_review",
    })
}

