pub async fn coach_operator_reconciliation(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<CoachOperatorQueueQuery>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let limit = coach_operator_queue_limit(q.limit);
    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let payload = if let Some(runtime_payload) =
        coach_operator_runtime_reconciliation_payload_for_request(
            &state,
            principal.account_id.as_str(),
            limit,
            &review_map,
            &event_map,
        )
        .await
        .map_err(|error| coach_storage_error("coach reconciliation store unavailable", error))?
    {
        runtime_payload
    } else {
        coach_operator_reconciliation_payload(limit, &review_map, &event_map)
    };
    Ok(json_no_store_response(payload))
}

pub async fn coach_operator_settlement_statements(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<CoachOperatorCursorQuery>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let limit = coach_operator_queue_limit(q.limit);
    let cursor = q
        .cursor
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(parse_coach_settlement_statement_cursor)
        .transpose()?;
    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let payout_run_map = coach_load_settlement_payout_run_map(&state).await?;
    let all_statements = if let Some(runtime_statements) =
        coach_operator_runtime_settlement_statement_values_for_request(
            &state,
            principal.account_id.as_str(),
            &review_map,
            &event_map,
            &payout_run_map,
        )
        .await
        .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?
    {
        runtime_statements
    } else {
        coach_operator_settlement_statement_values(&review_map, &event_map, &payout_run_map)
    };
    let page_source_statements =
        coach_filter_settlement_statements(&all_statements, cursor.as_ref());
    Ok(json_no_store_response(
        coach_operator_settlement_statements_payload(
            limit,
            &all_statements,
            &page_source_statements,
        ),
    ))
}

