pub async fn coach_operator_catalog_import_source_upload(
    State(state): State<AppState>,
    headers: HeaderMap,
    mut multipart: Multipart,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    if !auth::roles_allow_ride_pricing(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride pricing role required",
        ));
    }
    let Some(auth_runtime) = state.auth.as_ref() else {
        return Err(ApiError::internal("coach catalog runtime unavailable"));
    };

    let mut source_kind: Option<String> = None;
    let mut uploaded_file_name: Option<String> = None;
    let mut uploaded_file_bytes: Option<Vec<u8>> = None;

    while let Some(field) = multipart
        .next_field()
        .await
        .map_err(|_| ApiError::bad_request("invalid multipart form"))?
    {
        let field_name = field.name().unwrap_or_default().trim().to_string();
        match field_name.as_str() {
            "source_kind" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid source_kind field"))?;
                source_kind = Some(value);
            }
            "file" => {
                uploaded_file_name = field.file_name().map(|value| value.to_string());
                let bytes = field
                    .bytes()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid uploaded file"))?;
                uploaded_file_bytes = Some(bytes.to_vec());
            }
            _ => return Err(ApiError::bad_request("unexpected multipart field")),
        }
    }

    let normalized_source_kind = source_kind
        .unwrap_or_else(|| "gtfs".to_string())
        .trim()
        .to_ascii_lowercase();
    if normalized_source_kind != "gtfs" {
        return Err(ApiError::bad_request("source_kind must be gtfs"));
    }

    let file_name = uploaded_file_name
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::bad_request("missing file field"))?;
    let file_bytes = uploaded_file_bytes
        .as_deref()
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::bad_request("uploaded GTFS archive is empty"))?;

    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let mut archive_hasher = Sha256::new();
    archive_hasher.update(file_bytes);
    let archive_checksum = format!("{:x}", archive_hasher.finalize());
    let command_payload = json!({
        "source_kind": normalized_source_kind,
        "file_name": file_name,
        "archive_checksum_sha256": archive_checksum,
    });
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_operator_catalog_import_source_upload",
        &command_payload,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_catalog_import_source_upload",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let uploaded_source = coach_gtfs::upload_gtfs_catalog_archive(
        auth_runtime,
        file_name,
        file_bytes,
        principal.account_id.as_str(),
    )
    .await
    .map_err(|error| ApiError::bad_request(error.to_string()))?;
    coach_require_catalog_resource_operator_scope(
        "coach catalog source artifact",
        &uploaded_source.operator_ids,
        &allowed_operator_scope,
    )?;

    let repo = CoachCatalogRepository::new(auth_runtime.pool().clone());
    let created_at_iso = now_rfc3339();
    repo.upsert_source_artifact(&CoachCatalogSourceArtifact {
        artifact_id: uploaded_source.source_artifact_id.clone(),
        feed_kind: "static_catalog".to_string(),
        source_kind: uploaded_source.source_kind.clone(),
        source_label: uploaded_source.source_label.clone(),
        file_name: uploaded_source.file_name.clone(),
        file_checksum_sha256: uploaded_source.file_checksum_sha256.clone(),
        content_length_bytes: uploaded_source.content_length_bytes,
        extracted_file_count: uploaded_source.extracted_file_count as i64,
        feed_locator: uploaded_source.feed_locator.clone(),
        operator_ids: uploaded_source.operator_ids.clone(),
        created_by_account_id: principal.account_id.clone(),
        created_at_iso: created_at_iso.clone(),
    })
    .await
    .map_err(|error| coach_storage_error("coach catalog source artifact unavailable", error))?;
    repo.upsert_import_config(&CoachCatalogImportConfig {
        feed_kind: "static_catalog".to_string(),
        source_kind: "gtfs".to_string(),
        feed_locator: uploaded_source.feed_locator.clone(),
        source_artifact_id: Some(uploaded_source.source_artifact_id.clone()),
        source_artifact: None,
        updated_by_account_id: principal.account_id.clone(),
        updated_at_iso: created_at_iso,
    })
    .await
    .map_err(|error| coach_storage_error("coach catalog import source unavailable", error))?;
    let persisted_config = repo
        .find_import_config("static_catalog", "gtfs")
        .await
        .map_err(|error| coach_storage_error("coach catalog import source unavailable", error))?;
    let config = coach_gtfs::current_gtfs_feed_config_with_override(
        persisted_config
            .as_ref()
            .map(|entry| entry.feed_locator.as_str()),
    );
    let latest_import_runs = repo
        .list_import_runs()
        .await
        .map_err(|error| coach_storage_error("coach catalog import source unavailable", error))?;
    let latest_import_run = coach_latest_catalog_import_run_for_operator_scope(
        &latest_import_runs,
        &allowed_operator_scope,
    );
    let next_action = if config.status == "ready" {
        "catalog_import_ready"
    } else {
        "verify_catalog_import_source"
    };
    let response_json = coach_operator_catalog_import_source_upload_payload(
        &CoachOperatorCatalogImportSourceUploadContext {
            idempotency_key: &idempotency_key,
            request_fingerprint: &request_fingerprint,
            uploaded_source: &uploaded_source,
            config: &config,
            persisted_config: persisted_config.as_ref(),
            latest_import_run: latest_import_run.as_ref(),
            allowed_operator_ids: &allowed_operator_scope,
            next_action,
        },
    );
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_catalog_import_source_upload",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

