pub async fn coach_operator_catalog_import_config_update(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<CoachOperatorCatalogImportConfigUpdateIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    if !auth::roles_allow_ride_pricing(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride pricing role required",
        ));
    }
    let Some(auth_runtime) = state.auth.as_ref() else {
        return Err(ApiError::internal("coach catalog runtime unavailable"));
    };
    let feed_locator = input.feed_locator.trim();
    if feed_locator.is_empty() {
        return Err(ApiError::bad_request("feed_locator required"));
    }
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "feed_kind": "static_catalog",
        "source_kind": "gtfs",
        "feed_locator": feed_locator,
    });
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_operator_catalog_import_config_update",
        &command_payload,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_catalog_import_config_update",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let repo = CoachCatalogRepository::new(auth_runtime.pool().clone());
    let source_artifact = repo
        .find_source_artifact_by_feed_locator("static_catalog", "gtfs", feed_locator)
        .await
        .map_err(|error| coach_storage_error("coach catalog import config unavailable", error))?;
    match source_artifact.as_ref() {
        Some(source_artifact) => coach_require_catalog_resource_operator_scope(
            "coach catalog source artifact",
            &source_artifact.operator_ids,
            &allowed_operator_scope,
        )?,
        None if !allowed_operator_scope.is_empty() => {
            return Err(ApiError::new(
                StatusCode::FORBIDDEN,
                "coach catalog feed locator requires scoped source artifact for restricted operator account",
            ));
        }
        None => {}
    }
    repo.upsert_import_config(&CoachCatalogImportConfig {
        feed_kind: "static_catalog".to_string(),
        source_kind: "gtfs".to_string(),
        feed_locator: feed_locator.to_string(),
        source_artifact_id: source_artifact
            .as_ref()
            .map(|entry| entry.artifact_id.clone()),
        source_artifact,
        updated_by_account_id: principal.account_id.clone(),
        updated_at_iso: now_rfc3339(),
    })
    .await
    .map_err(|error| coach_storage_error("coach catalog import config unavailable", error))?;
    let persisted_config = repo
        .find_import_config("static_catalog", "gtfs")
        .await
        .map_err(|error| coach_storage_error("coach catalog import config unavailable", error))?;
    let config = coach_gtfs::current_gtfs_feed_config_with_override(
        persisted_config
            .as_ref()
            .map(|entry| entry.feed_locator.as_str()),
    );
    let latest_import_runs = repo
        .list_import_runs()
        .await
        .map_err(|error| coach_storage_error("coach catalog import config unavailable", error))?;
    let latest_import_run = coach_latest_catalog_import_run_for_operator_scope(
        &latest_import_runs,
        &allowed_operator_scope,
    );
    let next_action = if config.status == "ready" {
        "catalog_import_ready"
    } else {
        "verify_catalog_import_source"
    };
    let response_json = coach_operator_catalog_import_config_mutation_payload(
        &idempotency_key,
        &request_fingerprint,
        &config,
        persisted_config.as_ref(),
        latest_import_run.as_ref(),
        &allowed_operator_scope,
        next_action,
    );
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_catalog_import_config_update",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

pub async fn coach_operator_catalog_import_run_trigger(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(input): Json<CoachOperatorCatalogImportRunTriggerIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    if !auth::roles_allow_ride_pricing(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride pricing role required",
        ));
    }
    let Some(auth_runtime) = state.auth.as_ref() else {
        return Err(ApiError::internal("coach catalog runtime unavailable"));
    };
    let repo = CoachCatalogRepository::new(auth_runtime.pool().clone());
    let replay_import_run_id = input
        .replay_import_run_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let artifact_override_id = input
        .source_artifact_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if artifact_override_id.is_some() && replay_import_run_id.is_some() {
        return Err(ApiError::bad_request(
            "source_artifact_id and replay_import_run_id are mutually exclusive",
        ));
    }
    let replay_import_run = match replay_import_run_id {
        Some(import_run_id) => Some(
            repo.find_import_run_head_by_id(import_run_id)
                .await
                .map_err(|error| {
                    coach_storage_error("coach catalog import trigger unavailable", error)
                })?
                .ok_or_else(|| ApiError::bad_request("unknown replay_import_run_id"))?,
        ),
        None => None,
    };
    if let Some(import_run) = replay_import_run.as_ref() {
        coach_require_catalog_resource_operator_scope(
            "coach catalog replay import run",
            &import_run.operator_ids,
            &allowed_operator_scope,
        )?;
    }
    let source_artifact_override = match artifact_override_id {
        Some(artifact_id) => Some(
            repo.find_source_artifact_by_id(artifact_id)
                .await
                .map_err(|error| {
                    coach_storage_error("coach catalog import trigger unavailable", error)
                })?
                .ok_or_else(|| ApiError::bad_request("unknown source_artifact_id"))?,
        ),
        None => match replay_import_run.as_ref() {
            Some(import_run) => match import_run.source_artifact_id.as_deref().or_else(|| {
                import_run
                    .source_artifact
                    .as_ref()
                    .map(|artifact| artifact.artifact_id.as_str())
            }) {
                Some(artifact_id) => Some(
                    repo.find_source_artifact_by_id(artifact_id)
                        .await
                        .map_err(|error| {
                            coach_storage_error("coach catalog import trigger unavailable", error)
                        })?
                        .or_else(|| import_run.source_artifact.clone())
                        .ok_or_else(|| {
                            ApiError::bad_request("replay import run source artifact unavailable")
                        })?,
                ),
                None => None,
            },
            None => None,
        },
    };
    if let Some(source_artifact) = source_artifact_override.as_ref() {
        coach_require_catalog_resource_operator_scope(
            "coach catalog source artifact",
            &source_artifact.operator_ids,
            &allowed_operator_scope,
        )?;
    }
    let persisted_config =
        coach_catalog_import_config_best_effort(&state, "static_catalog", "gtfs")
            .await
            .map_err(|error| {
                coach_storage_error("coach catalog import trigger unavailable", error)
            })?;
    if source_artifact_override.is_none() && replay_import_run.is_none() {
        match persisted_config
            .as_ref()
            .and_then(|entry| entry.source_artifact.as_ref())
        {
            Some(source_artifact) => coach_require_catalog_resource_operator_scope(
                "coach catalog source artifact",
                &source_artifact.operator_ids,
                &allowed_operator_scope,
            )?,
            None if !allowed_operator_scope.is_empty() => {
                return Err(ApiError::new(
                    StatusCode::FORBIDDEN,
                    "coach catalog import trigger requires scoped source artifact for restricted operator account",
                ));
            }
            None => {}
        }
    }
    let feed_dir = source_artifact_override
        .as_ref()
        .map(|entry| entry.feed_locator.as_str())
        .or_else(|| {
            replay_import_run
                .as_ref()
                .and_then(|entry| entry.feed_locator.as_deref())
        })
        .or_else(|| {
            persisted_config
                .as_ref()
                .map(|entry| entry.feed_locator.as_str())
        });
    let config = coach_gtfs::current_gtfs_feed_config_with_override(feed_dir);
    let Some(feed_dir) = config
        .feed_locator
        .as_deref()
        .filter(|_| config.status == "ready")
    else {
        return Err(ApiError::new(StatusCode::CONFLICT, config.detail));
    };
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "feed_kind": "static_catalog",
        "source_kind": "gtfs",
        "feed_locator": feed_dir,
        "source_artifact_id": source_artifact_override
            .as_ref()
            .map(|entry| entry.artifact_id.clone()),
        "replay_import_run_id": replay_import_run
            .as_ref()
            .map(|entry| entry.import_run_id.clone()),
        "trigger_kind": "manual",
    });
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_operator_catalog_import_run_trigger",
        &command_payload,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_catalog_import_run_trigger",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let import_run = coach_gtfs::trigger_gtfs_catalog_import(
        auth_runtime,
        feed_dir,
        "manual",
        source_artifact_override
            .as_ref()
            .map(|entry| entry.artifact_id.as_str())
            .or_else(|| {
                replay_import_run
                    .as_ref()
                    .and_then(|entry| entry.source_artifact_id.as_deref())
            })
            .or_else(|| {
                persisted_config
                    .as_ref()
                    .and_then(|entry| entry.source_artifact_id.as_deref())
            }),
        replay_import_run
            .as_ref()
            .map(|entry| entry.import_run_id.as_str()),
    )
    .await
    .map_err(|error| {
        tracing::warn!(error = %error, feed_dir, "coach catalog import trigger failed");
        ApiError::internal("coach catalog import trigger unavailable")
    })?;
    let next_action = if import_run.status == "succeeded" {
        "catalog_search_ready"
    } else {
        "review_catalog_import_error"
    };
    let response_json = coach_operator_catalog_import_run_trigger_payload(
        &idempotency_key,
        &request_fingerprint,
        &import_run,
        next_action,
    );
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_catalog_import_run_trigger",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

