pub async fn coach_operator_payout_import_batches(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<CoachOperatorCursorQuery>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let limit = coach_operator_queue_limit(q.limit);
    let cursor = q
        .cursor
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(parse_coach_payout_import_batch_cursor)
        .transpose()?;
    let batch_map = coach_filter_payout_import_batch_map_by_operator_scope(
        &coach_load_settlement_payout_import_batch_map(&state).await?,
        &allowed_operator_scope,
    );
    let artifact_map = coach_filter_payout_import_report_artifact_map_by_operator_scope(
        &coach_load_settlement_payout_import_report_artifact_map(&state).await?,
        &allowed_operator_scope,
    );
    let all_batches = coach_filter_payout_import_batches(&batch_map, None);
    let batches = if cursor.is_some() {
        coach_filter_payout_import_batches(&batch_map, cursor.as_ref())
    } else {
        all_batches.clone()
    };
    Ok(json_no_store_response(
        coach_operator_payout_import_batches_payload(
            limit,
            &all_batches,
            &batches,
            &batch_map,
            &artifact_map,
        ),
    ))
}

