    let repo = CoachCatalogRepository::new(auth_runtime.pool().clone());
    let visible_saved_views = repo
        .list_payout_import_batch_saved_views(principal.account_id.as_str())
        .await
        .map_err(|error| {
            coach_storage_error("coach payout import batch saved views unavailable", error)
        })?;
    let visible_saved_views = coach_filter_payout_import_batch_saved_views_by_operator_scope(
        &visible_saved_views,
        &allowed_operator_scope,
    );
