pub async fn coach_operator_payout_run_create(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachOperatorPayoutRunCreateIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let statement_ids = validate_coach_settlement_statement_ids(body.statement_ids)?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "statement_ids": statement_ids.clone(),
        "note": note.clone(),
    });
    let request_fingerprint =
        coach_command_request_fingerprint("coach_operator_payout_run_create", &command_payload);
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_run_create",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let payout_run_map = coach_filter_payout_run_map_by_operator_scope(
        &coach_load_settlement_payout_run_map(&state).await?,
        &allowed_operator_scope,
    );
    let export_map = coach_load_settlement_export_map(&state).await?;
    let statement_map = coach_operator_statement_values_by_id_for_request(
        &state,
        principal.account_id.as_str(),
        &review_map,
        &event_map,
        &payout_run_map,
    )
    .await
    .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
    if let Some(existing_run) =
        coach_latest_settlement_payout_run_for_statement_ids(&payout_run_map, &statement_ids)
    {
        let response_json = coach_operator_payout_run_response(
            "payout_run_create",
            &idempotency_key,
            &request_fingerprint,
            existing_run,
            &statement_map,
            &export_map,
            if existing_run.status == "paid" {
                "statement_exports_ready"
            } else {
                "await_external_payout_execution"
            },
        );
        return coach_store_or_replay_idempotent_response(
            &state,
            principal.account_id.as_str(),
            "coach_operator_payout_run_create",
            &idempotency_key,
            &request_fingerprint,
            response_json,
        )
        .await;
    }
    let mut statements = Vec::with_capacity(statement_ids.len());
    for statement_id in &statement_ids {
        let Some(statement) = statement_map.get(statement_id.as_str()).cloned() else {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        };
        let status = statement["status"].as_str().unwrap_or_default();
        if status != "ready_for_payout" {
            return Err(ApiError::new(
                StatusCode::CONFLICT,
                "statement is not eligible for payout",
            ));
        }
        statements.push(statement);
    }
    let currency = coach_settlement_statement_currency(statements.as_slice())?;
    let created_at = now_rfc3339();

    let payout_run_id = coach_scoped_resource_id(
        "payoutrun",
        &format!("{}-{}", principal.account_id, &request_fingerprint[..12]),
    );
    let payout_run = coach_build_settlement_payout_run_entry(
        payout_run_id.clone(),
        statement_ids.as_slice(),
        statements.as_slice(),
        currency.as_str(),
        created_at.as_str(),
        principal.account_id.as_str(),
        note,
    );
    let inserted = coach_insert_settlement_payout_run_entry(&state, &payout_run).await?;
    let payout_run = if inserted {
        payout_run
    } else {
        let mut payout_runs = coach_load_settlement_payout_run_map(&state).await?;
        payout_runs
            .remove(payout_run_id.as_str())
            .ok_or_else(|| ApiError::internal("coach payout run store unavailable"))?
    };
    let response_json = coach_operator_payout_run_response(
        "payout_run_create",
        &idempotency_key,
        &request_fingerprint,
        &payout_run,
        &statement_map,
        &export_map,
        "await_external_payout_execution",
    );
    coach_sync_subledger_from_derived_finance_state(&state).await?;
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_run_create",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

pub async fn coach_operator_payout_run_import_create(
    Path(payout_run_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachOperatorPayoutImportCreateIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let payout_run_id = validate_coach_resource_id(&payout_run_id, "payout_run_id")?;
    let import_source = canonical_coach_payout_import_source(&body.import_source)?;
    let external_status =
        canonical_coach_payout_import_status_for_source(import_source, &body.external_status)?;
    let payment_reference = validate_coach_payment_reference(body.payment_reference.as_deref())?;
    let external_reference = validate_coach_external_reference(body.external_reference.as_deref())?;
    coach_validate_required_payout_import_fields(
        import_source,
        external_status,
        payment_reference.as_deref(),
        external_reference.as_deref(),
    )?;
    let imported_at = validate_coach_imported_at(body.imported_at.as_deref())?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "payout_run_id": payout_run_id.clone(),
        "import_source": import_source,
        "external_status": external_status,
        "payment_reference": payment_reference.clone(),
        "external_reference": external_reference.clone(),
        "imported_at": imported_at.clone(),
        "note": note.clone(),
    });
    let request_fingerprint =
        coach_command_request_fingerprint("coach_operator_payout_import_create", &command_payload);
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_import_create",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let mut payout_runs = coach_load_settlement_payout_run_map(&state).await?;
    let payout_run = payout_runs
        .get(payout_run_id.as_str())
        .cloned()
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    coach_require_payout_run_operator_scope(&payout_run, &allowed_operator_scope)?;
    let export_map = coach_load_settlement_export_map(&state).await?;
    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let statement_map = coach_operator_statement_values_by_id_for_request(
        &state,
        principal.account_id.as_str(),
        &review_map,
        &event_map,
        &payout_runs,
    )
    .await
    .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
    let applied = coach_apply_payout_import_command(
        &state,
        principal.account_id.as_str(),
        &mut payout_runs,
        &CoachPayoutImportCommand {
            import_trace_id: "single".to_string(),
            import_batch_id: None,
            payout_run_id: payout_run_id.clone(),
            import_source: import_source.to_string(),
            external_status: external_status.to_string(),
            payment_reference: payment_reference.clone(),
            external_reference: external_reference.clone(),
            imported_at: imported_at.clone(),
            note: note.clone(),
        },
    )
    .await?;

    let next_action = match external_status {
        "executed" => "reconciliation_updated",
        "failed" => "retry_or_requeue_payout",
        _ => "await_external_payout_execution",
    };
    let response_json = coach_operator_payout_import_response(
        &idempotency_key,
        &request_fingerprint,
        &applied.payout_import,
        &applied.payout_run,
        &statement_map,
        &export_map,
        next_action,
    );
    coach_sync_subledger_from_derived_finance_state(&state).await?;
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_import_create",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

async fn coach_operator_payout_import_batch_create_core(
    request: CoachOperatorPayoutImportBatchCreateCoreRequest<'_>,
) -> ApiResult<Response> {
    let CoachOperatorPayoutImportBatchCreateCoreRequest {
        state,
        principal_account_id,
        allowed_operator_scope,
        idempotency_key,
        import_source,
        report_name,
        report_format,
        report_body,
        rework_of_batch_id,
        expected_preview_token,
        dry_run,
        note,
    } = request;
    let parsed_rows = coach_parse_payout_import_batch_csv(import_source, &report_body)?;
    let batch_map = coach_load_settlement_payout_import_batch_map(state).await?;
    let rework_of_batch_id = coach_validate_payout_import_rework_source_batch(
        &batch_map,
        rework_of_batch_id.as_deref(),
        import_source,
        report_format,
    )?;
    if let Some(rework_batch_id) = rework_of_batch_id.as_deref() {
        let rework_batch = batch_map
            .get(rework_batch_id)
            .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
        coach_require_payout_import_batch_operator_scope(rework_batch, allowed_operator_scope)?;
    }
    let rework_origin_batch_id = coach_resolve_payout_import_rework_origin_batch_id(
        rework_of_batch_id.as_deref(),
        &batch_map,
    );
    let report_checksum_sha256 = sha256_hex(&report_body);
    let preview_command_payload =
        coach_payout_import_batch_command_payload(&CoachPayoutImportBatchCommand {
            import_source,
            report_name: report_name.as_str(),
            report_format,
            rework_of_batch_id: rework_of_batch_id.as_deref(),
            report_checksum_sha256: report_checksum_sha256.as_str(),
            total_rows: parsed_rows.len(),
            dry_run: true,
            note: note.as_deref(),
        });
    let preview_request_fingerprint = coach_command_request_fingerprint(
        "coach_operator_payout_import_batch_create",
        &preview_command_payload,
    );
    let command_payload = if dry_run {
        preview_command_payload
    } else {
        coach_payout_import_batch_command_payload(&CoachPayoutImportBatchCommand {
            import_source,
            report_name: report_name.as_str(),
            report_format,
            rework_of_batch_id: rework_of_batch_id.as_deref(),
            report_checksum_sha256: report_checksum_sha256.as_str(),
            total_rows: parsed_rows.len(),
            dry_run: false,
            note: note.as_deref(),
        })
    };
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_operator_payout_import_batch_create",
        &command_payload,
    );
    if !dry_run {
        if let Some(replayed) = coach_find_replayed_idempotent_response(
            state,
            principal_account_id,
            "coach_operator_payout_import_batch_create",
            idempotency_key,
            &request_fingerprint,
        )
        .await?
        {
            return Ok(replayed);
        }
    }
    let applied_preview_binding = coach_validate_payout_import_apply_preview_binding(
        state,
        dry_run,
        expected_preview_token.as_deref(),
        principal_account_id,
        preview_request_fingerprint.as_str(),
        report_checksum_sha256.as_str(),
    )
    .await?;
    if let Some(preview_entry) = applied_preview_binding.as_ref() {
        coach_require_payout_import_preview_operator_scope(preview_entry, allowed_operator_scope)?;
    }

    let batch_id = coach_scoped_resource_id(
        if dry_run {
            "payoutbatchpreview"
        } else {
            "payoutbatch"
        },
        &format!("{principal_account_id}-{}", &request_fingerprint[..12]),
    );
    let mut payout_runs = coach_load_settlement_payout_run_map(state).await?;
    coach_validate_payout_import_batch_operator_scope(
        &parsed_rows,
        &payout_runs,
        allowed_operator_scope,
    )?;
    let batch_operator_ids = coach_payout_import_operator_ids_for_rows(
        &parsed_rows,
        &payout_runs,
        allowed_operator_scope,
    );
    let applied = coach_execute_payout_import_batch(CoachExecutePayoutImportBatchRequest {
        state,
        principal_account_id,
        payout_runs: &mut payout_runs,
        parsed_rows,
        operator_ids: batch_operator_ids,
        import_source,
        batch_id: batch_id.clone(),
        report_name,
        report_format,
        rework_of_batch_id,
        report_checksum_sha256,
        note,
        dry_run,
    })
    .await?;
    let CoachPayoutImportBatchMutationApplied {
        batch: preview_batch,
        imports,
        failed_rows,
    } = applied;
    let batch = if dry_run {
        preview_batch
    } else {
        let inserted =
            coach_insert_settlement_payout_import_batch_entry(state, &preview_batch).await?;
        if inserted {
            preview_batch
        } else {
            coach_load_settlement_payout_import_batch_map(state)
                .await?
                .remove(batch_id.as_str())
                .ok_or_else(|| ApiError::internal("coach payout import batch store unavailable"))?
        }
    };
    let report_artifact = if batch.dry_run {
        None
    } else {
        let artifact_id = coach_scoped_resource_id(
            "payoutreport",
            format!("{}-report", batch.batch_id).as_str(),
        );
        let artifact_entry =
            coach_build_payout_import_report_artifact_entry(artifact_id, &batch, &report_body);
        let inserted =
            coach_insert_settlement_payout_import_report_artifact_entry(state, &artifact_entry)
                .await?;
        if inserted {
            Some(artifact_entry)
        } else {
            let artifact_map =
                coach_load_settlement_payout_import_report_artifact_map(state).await?;
            coach_payout_import_report_artifact_entry_for_batch_kind(
                batch.batch_id.as_str(),
                COACH_PAYOUT_IMPORT_ARTIFACT_KIND_SOURCE_REPORT,
                &artifact_map,
            )
        }
    };
    let rework_artifact = if batch.dry_run || failed_rows.is_empty() {
        None
    } else {
        let artifact_id = coach_scoped_resource_id(
            "payoutrework",
            format!("{}-rework", batch.batch_id).as_str(),
        );
        let artifact_entry = coach_build_payout_import_rework_artifact_entry(
            artifact_id,
            &batch,
            &report_body,
            failed_rows.as_slice(),
        )?;
        let inserted =
            coach_insert_settlement_payout_import_report_artifact_entry(state, &artifact_entry)
                .await?;
        if inserted {
            Some(artifact_entry)
        } else {
            let artifact_map =
                coach_load_settlement_payout_import_report_artifact_map(state).await?;
            coach_payout_import_report_artifact_entry_for_batch_kind(
                batch.batch_id.as_str(),
                COACH_PAYOUT_IMPORT_ARTIFACT_KIND_FAILED_ROW_REWORK,
                &artifact_map,
            )
        }
    };
    let next_action = if batch.failed_rows > 0 {
        "review_failed_rows"
    } else if batch.dry_run {
        "apply_ready"
    } else {
        "reconciliation_updated"
    };
    let mut preview_entry = if batch.dry_run {
        let entry = coach_build_payout_import_preview_entry(&CoachPayoutImportPreviewBuild {
            principal_account_id,
            operator_ids: batch.operator_ids.as_slice(),
            request_fingerprint: preview_request_fingerprint.as_str(),
            command: CoachPayoutImportBatchCommand {
                import_source: batch.import_source.as_str(),
                report_name: batch.report_name.as_str(),
                report_format: batch.report_format.as_str(),
                rework_of_batch_id: batch.rework_of_batch_id.as_deref(),
                report_checksum_sha256: batch.report_checksum_sha256.as_str(),
                total_rows: batch.total_rows as usize,
                dry_run: batch.dry_run,
                note: batch.note.as_deref(),
            },
        });
        coach_store_settlement_payout_import_preview_entry(state, &entry).await?;
        Some(entry)
    } else {
        applied_preview_binding
    };
    if batch.dry_run {
        let response_json =
            coach_operator_payout_import_batch_response(&CoachPayoutImportBatchResponseContext {
                idempotency_key,
                request_fingerprint: &request_fingerprint,
                batch: &batch,
                preview_entry: preview_entry.as_ref(),
                report_artifact: report_artifact.as_ref(),
                rework_artifact: rework_artifact.as_ref(),
                rework_origin_batch_id: rework_origin_batch_id.as_deref(),
                imports: imports.as_slice(),
                failed_rows: failed_rows.as_slice(),
                next_action,
            });
        Ok(json_no_store_response(response_json))
    } else {
        coach_sync_subledger_from_derived_finance_state(state).await?;
        let consumed_at = now_rfc3339();
        let preview_token = preview_entry
            .as_ref()
            .map(|entry| entry.preview_token.as_str())
            .ok_or_else(|| ApiError::internal("coach payout import preview missing"))?;
        let transitioned = coach_transition_settlement_payout_import_preview_status(
            state,
            principal_account_id,
            preview_token,
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE,
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED,
            Some(consumed_at.as_str()),
            None,
        )
        .await?;
        if transitioned {
            if let Some(entry) = preview_entry.as_mut() {
                entry.preview_status = COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED.to_string();
                entry.consumed_at = Some(consumed_at);
                entry.invalidated_at = None;
            }
        } else if let Some(current_preview_entry) =
            coach_find_settlement_payout_import_preview_entry(
                state,
                principal_account_id,
                preview_token,
            )
            .await?
        {
            preview_entry = Some(current_preview_entry);
        } else {
            tracing::warn!(
                preview_token,
                batch_id = batch.batch_id,
                "coach payout import preview missing after batch apply transition"
            );
        }
        let response_json =
            coach_operator_payout_import_batch_response(&CoachPayoutImportBatchResponseContext {
                idempotency_key,
                request_fingerprint: &request_fingerprint,
                batch: &batch,
                preview_entry: preview_entry.as_ref(),
                report_artifact: report_artifact.as_ref(),
                rework_artifact: rework_artifact.as_ref(),
                rework_origin_batch_id: rework_origin_batch_id.as_deref(),
                imports: imports.as_slice(),
                failed_rows: failed_rows.as_slice(),
                next_action,
            });
        coach_store_or_replay_idempotent_response(
            state,
            principal_account_id,
            "coach_operator_payout_import_batch_create",
            idempotency_key,
            &request_fingerprint,
            response_json,
        )
        .await
    }
}

