pub async fn coach_operator_payout_import_batch_upload(
    State(state): State<AppState>,
    headers: HeaderMap,
    mut multipart: Multipart,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );

    let mut import_source: Option<String> = None;
    let mut report_name_field: Option<String> = None;
    let mut report_format: Option<String> = None;
    let mut rework_of_batch_id: Option<String> = None;
    let mut expected_preview_token: Option<String> = None;
    let mut dry_run = false;
    let mut note: Option<String> = None;
    let mut uploaded_file_name: Option<String> = None;
    let mut uploaded_report_body: Option<String> = None;

    while let Some(field) = multipart
        .next_field()
        .await
        .map_err(|_| ApiError::bad_request("invalid multipart form"))?
    {
        let field_name = field.name().unwrap_or_default().trim().to_string();
        match field_name.as_str() {
            "import_source" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid import_source field"))?;
                import_source = Some(value);
            }
            "report_name" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid report_name field"))?;
                report_name_field = Some(value);
            }
            "report_format" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid report_format field"))?;
                report_format = Some(value);
            }
            "dry_run" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid dry_run field"))?;
                dry_run = parse_coach_bool_field(&value, "dry_run")?;
            }
            "rework_of_batch_id" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid rework_of_batch_id field"))?;
                rework_of_batch_id = Some(value);
            }
            "expected_preview_token" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid expected_preview_token field"))?;
                expected_preview_token = Some(value);
            }
            "note" => {
                let value = field
                    .text()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid note field"))?;
                note = Some(value);
            }
            "file" => {
                uploaded_file_name = field.file_name().map(|value| value.to_string());
                let bytes = field
                    .bytes()
                    .await
                    .map_err(|_| ApiError::bad_request("invalid uploaded file"))?;
                uploaded_report_body = Some(normalize_coach_uploaded_csv_text(bytes.to_vec())?);
            }
            _ => return Err(ApiError::bad_request("unexpected multipart field")),
        }
    }

    let import_source = canonical_coach_payout_import_source(
        import_source
            .as_deref()
            .ok_or_else(|| ApiError::bad_request("missing import_source field"))?,
    )?;
    let report_format =
        canonical_coach_payout_import_report_format(report_format.as_deref().unwrap_or("csv"))?;
    let report_name_source = report_name_field
        .as_deref()
        .or(uploaded_file_name.as_deref())
        .unwrap_or("payout_import_report.csv");
    let report_name = validate_coach_payout_import_report_name(report_name_source)?;
    let report_body =
        uploaded_report_body.ok_or_else(|| ApiError::bad_request("missing file field"))?;
    let rework_of_batch_id =
        validate_coach_optional_payout_import_batch_id(rework_of_batch_id.as_deref())?;
    let expected_preview_token =
        validate_coach_optional_preview_token(expected_preview_token.as_deref())?;
    let note = validate_coach_operator_review_note(note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    coach_operator_payout_import_batch_create_core(
        CoachOperatorPayoutImportBatchCreateCoreRequest {
            state: &state,
            principal_account_id: principal.account_id.as_str(),
            allowed_operator_scope: &allowed_operator_scope,
            idempotency_key: &idempotency_key,
            import_source,
            report_name,
            report_format,
            report_body,
            rework_of_batch_id,
            expected_preview_token,
            dry_run,
            note,
        },
    )
    .await
}

