pub async fn coach_operator_payout_run_mark_paid(
    Path(payout_run_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachOperatorPayoutRunMarkPaidIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let payout_run_id = validate_coach_resource_id(&payout_run_id, "payout_run_id")?;
    let payment_reference = validate_coach_payment_reference(body.payment_reference.as_deref())?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "payout_run_id": payout_run_id.clone(),
        "payment_reference": payment_reference.clone(),
        "note": note.clone(),
    });
    let request_fingerprint =
        coach_command_request_fingerprint("coach_operator_payout_run_mark_paid", &command_payload);
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_run_mark_paid",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let mut payout_runs = coach_load_settlement_payout_run_map(&state).await?;
    let export_map = coach_load_settlement_export_map(&state).await?;
    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let statement_map = coach_operator_statement_values_by_id_for_request(
        &state,
        principal.account_id.as_str(),
        &review_map,
        &event_map,
        &payout_runs,
    )
    .await
    .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
    let mut payout_run = payout_runs
        .remove(payout_run_id.as_str())
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    coach_require_payout_run_operator_scope(&payout_run, &allowed_operator_scope)?;
    if payout_run.status == "paid" {
        let response_json = coach_operator_payout_run_response(
            "payout_run_mark_paid",
            &idempotency_key,
            &request_fingerprint,
            &payout_run,
            &statement_map,
            &export_map,
            "statement_exports_ready",
        );
        return coach_store_or_replay_idempotent_response(
            &state,
            principal.account_id.as_str(),
            "coach_operator_payout_run_mark_paid",
            &idempotency_key,
            &request_fingerprint,
            response_json,
        )
        .await;
    }
    if payout_run.status != "queued" {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "payout run is not pending execution",
        ));
    }
    payout_run.status = "paid".to_string();
    payout_run.paid_at = Some(coach_runtime_payout_paid_at());
    payout_run.paid_by_account_id = Some(principal.account_id.clone());
    payout_run.payment_reference = payment_reference;
    payout_run.note = note.or(payout_run.note);
    coach_upsert_settlement_payout_run_entry(&state, &payout_run).await?;

    let response_json = coach_operator_payout_run_response(
        "payout_run_mark_paid",
        &idempotency_key,
        &request_fingerprint,
        &payout_run,
        &statement_map,
        &export_map,
        "statement_exports_ready",
    );
    coach_sync_subledger_from_derived_finance_state(&state).await?;
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_run_mark_paid",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

pub async fn coach_operator_payout_run_export_create(
    Path(payout_run_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachOperatorPayoutRunExportCreateIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let payout_run_id = validate_coach_resource_id(&payout_run_id, "payout_run_id")?;
    let export_format = canonical_coach_settlement_export_format(&body.export_format)?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "payout_run_id": payout_run_id.clone(),
        "export_format": export_format,
        "note": note.clone(),
    });
    let request_fingerprint = coach_command_request_fingerprint(
        "coach_operator_payout_run_export_create",
        &command_payload,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_run_export_create",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let payout_run_map = coach_load_settlement_payout_run_map(&state).await?;
    let payout_run = payout_run_map
        .get(payout_run_id.as_str())
        .cloned()
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    coach_require_payout_run_operator_scope(&payout_run, &allowed_operator_scope)?;
    if payout_run.status != "queued" && payout_run.status != "paid" {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "payout run is not exportable",
        ));
    }
    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let statement_map = coach_operator_statement_values_by_id_for_request(
        &state,
        principal.account_id.as_str(),
        &review_map,
        &event_map,
        &payout_run_map,
    )
    .await
    .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
    let available_formats =
        coach_operator_payout_run_available_export_formats(&payout_run, &statement_map);
    if !available_formats.iter().any(|value| value == export_format) {
        return Err(ApiError::bad_request(
            "export_format unavailable for payout run",
        ));
    }
    let export_map = coach_load_settlement_export_map(&state).await?;
    if let Some(existing_export) = export_map
        .values()
        .find(|entry| entry.payout_run_id == payout_run_id && entry.export_format == export_format)
    {
        let response_json = coach_operator_payout_export_response(
            &idempotency_key,
            &request_fingerprint,
            existing_export,
            "download_ready",
        );
        return coach_store_or_replay_idempotent_response(
            &state,
            principal.account_id.as_str(),
            "coach_operator_payout_run_export_create",
            &idempotency_key,
            &request_fingerprint,
            response_json,
        )
        .await;
    }
    let statements = payout_run
        .statement_ids
        .iter()
        .filter_map(|statement_id| statement_map.get(statement_id.as_str()).cloned())
        .collect::<Vec<_>>();
    if statements.len() != payout_run.statement_ids.len() {
        return Err(ApiError::internal(
            "coach settlement export store unavailable",
        ));
    }
    let export_id = coach_scoped_resource_id(
        "export",
        &format!(
            "{}-{}-{}",
            principal.account_id, payout_run_id, export_format
        ),
    );
    let export = coach_build_settlement_export_entry(
        export_id.clone(),
        &payout_run,
        statements.as_slice(),
        export_format,
        coach_runtime_settlement_export_created_at().as_str(),
        principal.account_id.as_str(),
        note,
    );
    let inserted = coach_insert_settlement_export_entry(&state, &export).await?;
    let export = if inserted {
        export
    } else {
        coach_load_settlement_export_map(&state)
            .await?
            .values()
            .find(|entry| {
                entry.payout_run_id == payout_run_id && entry.export_format == export_format
            })
            .cloned()
            .ok_or_else(|| ApiError::internal("coach settlement export store unavailable"))?
    };
    let response_json = coach_operator_payout_export_response(
        &idempotency_key,
        &request_fingerprint,
        &export,
        "download_ready",
    );
    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_operator_payout_run_export_create",
        &idempotency_key,
        &request_fingerprint,
        response_json,
    )
    .await
}

pub async fn coach_operator_settlement_export_download(
    Path(artifact_name): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let artifact_name = validate_coach_download_artifact_name(&artifact_name)?;
    let export_map = coach_load_settlement_export_map(&state).await?;
    let export =
        coach_settlement_export_entry_by_download_name(artifact_name.as_str(), &export_map)
            .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    coach_require_settlement_export_operator_scope(&export, &allowed_operator_scope)?;
    if export.status != "ready" {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "settlement export is not ready",
        ));
    }

    let payout_run_map = coach_load_settlement_payout_run_map(&state).await?;
    let payout_run = payout_run_map
        .get(export.payout_run_id.as_str())
        .cloned()
        .ok_or_else(|| ApiError::internal("coach settlement export artifact unavailable"))?;
    coach_require_payout_run_operator_scope(&payout_run, &allowed_operator_scope)?;
    let review_map = coach_load_ops_review_map(&state).await?;
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let statement_map = coach_operator_statement_values_by_id_for_request(
        &state,
        principal.account_id.as_str(),
        &review_map,
        &event_map,
        &payout_run_map,
    )
    .await
    .map_err(|error| coach_storage_error("coach settlement store unavailable", error))?;
    let mut statements = Vec::with_capacity(export.statement_ids.len());
    for statement_id in &export.statement_ids {
        let Some(statement) = statement_map.get(statement_id.as_str()) else {
            return Err(ApiError::internal(
                "coach settlement export artifact unavailable",
            ));
        };
        statements.push(statement.clone());
    }
    coach_settlement_export_download_response(&export, &payout_run, statements.as_slice())
}

pub async fn coach_operator_refund_request_review(
    Path(refund_request_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachOperatorReviewIn>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let refund_request_id = validate_coach_resource_id(&refund_request_id, "refund_request_id")?;
    let decision = canonical_coach_operator_review_decision(&body.decision)?;
    let note = validate_coach_operator_review_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "refund_request_id": refund_request_id.clone(),
        "decision": decision,
        "note": note.clone(),
    });
    let request_fingerprint =
        coach_command_request_fingerprint("coach_operator_refund_review", &command_payload);
    {
        let review_map = coach_load_ops_review_map(&state).await?;
        let Some(existing_request) =
            coach_operator_refund_queue_entry_by_id(&refund_request_id, &review_map)
        else {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        };
        if let Some(existing_review) = review_map.get(refund_request_id.as_str()) {
            if existing_review.decision != decision {
                return Err(ApiError::bad_request("refund_request already reviewed"));
            }
            let response_json = coach_operator_refund_review_response(
                &idempotency_key,
                &request_fingerprint,
                existing_request,
            );
            return coach_store_or_replay_idempotent_response(
                &state,
                principal.account_id.as_str(),
                "coach_operator_refund_review",
                &idempotency_key,
                &request_fingerprint,
                response_json,
            )
            .await;
        }
    }
    {
        let mut review_map = coach_load_ops_review_map(&state).await?;
        let Some(existing_request) =
            coach_operator_refund_queue_entry_by_id(&refund_request_id, &review_map)
        else {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        };
        let reviewed_at = coach_runtime_reviewed_at();
        let review_entry = CoachOpsReviewEntry {
            decision: decision.to_string(),
            queue_status: coach_queue_status_for_review_decision(decision).to_string(),
            reviewed_at,
            reviewed_by_account_id: principal.account_id.clone(),
            review_note: note,
        };
        let inserted = coach_insert_ops_review_entry(
            &state,
            &refund_request_id,
            "refund_request",
            &review_entry,
        )
        .await?;
        if !inserted {
            let review_map = coach_load_ops_review_map(&state).await?;
            let Some(existing_review) = review_map.get(refund_request_id.as_str()) else {
                return Err(ApiError::internal("coach ops review store unavailable"));
            };
            if existing_review.decision != decision {
                return Err(ApiError::bad_request("refund_request already reviewed"));
            }
            let Some(reviewed_request) =
                coach_operator_refund_queue_entry_by_id(&refund_request_id, &review_map)
            else {
                return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
            };
            let response_json = coach_operator_refund_review_response(
                &idempotency_key,
                &request_fingerprint,
                reviewed_request,
            );
            return coach_store_or_replay_idempotent_response(
                &state,
                principal.account_id.as_str(),
                "coach_operator_refund_review",
                &idempotency_key,
                &request_fingerprint,
                response_json,
            )
            .await;
        }
        review_map.insert(refund_request_id.clone(), review_entry);
        let reviewed_request =
            coach_operator_refund_queue_entry_by_id(&refund_request_id, &review_map)
                .unwrap_or(existing_request);
        let response_json = coach_operator_refund_review_response(
            &idempotency_key,
            &request_fingerprint,
            reviewed_request,
        );
        coach_sync_subledger_from_derived_finance_state(&state).await?;
        return coach_store_or_replay_idempotent_response(
            &state,
            principal.account_id.as_str(),
            "coach_operator_refund_review",
            &idempotency_key,
            &request_fingerprint,
            response_json,
        )
        .await;
    }
}

