pub async fn coach_crew_departures(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<CoachCrewDeparturesQuery>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_driver_principal(&state, &headers).await?;
    let limit = coach_operator_queue_limit(q.limit);
    let event_map = coach_load_boarding_event_map(&state, None).await?;
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let runtime_aggregates = coach_filter_booking_aggregates_by_operator_scope(
        &coach_list_booking_aggregates_global_for_request(&state)
            .await
            .map_err(|error| coach_storage_error("coach crew runtime store unavailable", error))?
            .into_iter()
            .filter(coach_runtime_boardable_booking)
            .collect::<Vec<_>>(),
        &allowed_operator_scope,
    );
    if !runtime_aggregates.is_empty() {
        let departures = coach_runtime_trip_groups_for_request(&state, runtime_aggregates)
            .await
            .map_err(|error| coach_storage_error("coach crew runtime store unavailable", error))?
            .into_iter()
            .map(|(trip_id, aggregates)| {
                coach_runtime_crew_trip_payload(&aggregates, &trip_id, &event_map)
            })
            .take(limit)
            .collect::<Vec<_>>();
        if !departures.is_empty() {
            return Ok(json_no_store_response(json!({
                "generated_at": now_rfc3339(),
                "departures": departures,
            })));
        }
    }
    let departures = coach_demo_crew_trip_seeds()
        .into_iter()
        .filter_map(|crew_trip_seed| {
            let booking_seed = coach_demo_booking_seed(crew_trip_seed.booking_id)?;
            if !coach_operator_scope_allows_demo_booking_seed(
                &booking_seed,
                &allowed_operator_scope,
            ) {
                return None;
            }
            Some(coach_demo_crew_trip_payload(
                &crew_trip_seed,
                &booking_seed,
                &event_map,
            ))
        })
        .take(limit)
        .collect::<Vec<_>>();
    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "departures": departures,
    })))
}

pub async fn coach_crew_manifest_get(
    Path(trip_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_driver_principal(&state, &headers).await?;
    let trip_id = validate_coach_resource_id(&trip_id, "trip_id")?;
    let event_map = coach_load_boarding_event_map(&state, Some(&trip_id)).await?;
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    let runtime_aggregates = coach_filter_booking_aggregates_by_operator_scope(
        &coach_list_booking_aggregates_global_for_request(&state)
            .await
            .map_err(|error| coach_storage_error("coach crew runtime store unavailable", error))?
            .into_iter()
            .filter(coach_runtime_boardable_booking)
            .collect::<Vec<_>>(),
        &allowed_operator_scope,
    );
    if !runtime_aggregates.is_empty() {
        let runtime_groups = coach_runtime_trip_groups_for_request(&state, runtime_aggregates)
            .await
            .map_err(|error| coach_storage_error("coach crew runtime store unavailable", error))?;
        if let Some((_, aggregates)) = runtime_groups
            .into_iter()
            .find(|(candidate_trip_id, _)| candidate_trip_id == &trip_id)
        {
            return Ok(json_no_store_response(
                coach_runtime_crew_manifest_response(&aggregates, &trip_id, &event_map),
            ));
        }
    }
    let Some(crew_trip_seed) = coach_demo_crew_trip_seed(&trip_id) else {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    };
    let Some(booking_seed) = coach_demo_booking_seed(crew_trip_seed.booking_id) else {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    };
    if !coach_operator_scope_allows_demo_booking_seed(&booking_seed, &allowed_operator_scope) {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    Ok(json_no_store_response(coach_crew_manifest_response(
        &crew_trip_seed,
        &booking_seed,
        &event_map,
    )))
}

pub async fn coach_crew_boarding_record(
    Path(trip_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<CoachCrewBoardingIn>,
) -> ApiResult<Response> {
    let (principal, _roles) = auth::require_ride_driver_principal(&state, &headers).await?;
    let trip_id = validate_coach_resource_id(&trip_id, "trip_id")?;
    let ticket_id = validate_coach_resource_id(&body.ticket_id, "ticket_id")?;
    let requested_scan_status = canonical_coach_boarding_scan_status(&body.scan_status)?;
    let offline_captured = body.offline_captured.unwrap_or(false);
    let device_id = validate_coach_device_id(body.device_id.as_deref())?;
    let note = validate_coach_boarding_note(body.note.as_deref())?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let command_payload = json!({
        "trip_id": trip_id.clone(),
        "ticket_id": ticket_id.clone(),
        "scan_status": requested_scan_status,
        "offline_captured": offline_captured,
        "device_id": device_id.clone(),
        "note": note.clone(),
    });
    let request_fingerprint =
        coach_command_request_fingerprint("coach_crew_boarding_record", &command_payload);
    let allowed_operator_scope = coach_allowed_saved_view_operator_scope(
        &auth::coach_operator_ids_for_account_best_effort(&state, principal.account_id.as_str())
            .await,
    );
    if let Some(replayed) = coach_find_replayed_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_crew_boarding_record",
        &idempotency_key,
        &request_fingerprint,
    )
    .await?
    {
        return Ok(replayed);
    }

    let runtime_aggregates = coach_filter_booking_aggregates_by_operator_scope(
        &coach_list_booking_aggregates_global_for_request(&state)
            .await
            .map_err(|error| coach_storage_error("coach crew runtime store unavailable", error))?
            .into_iter()
            .filter(coach_runtime_boardable_booking)
            .collect::<Vec<_>>(),
        &allowed_operator_scope,
    );
    let runtime_groups = if runtime_aggregates.is_empty() {
        Vec::new()
    } else {
        coach_runtime_trip_groups_for_request(&state, runtime_aggregates)
            .await
            .map_err(|error| coach_storage_error("coach crew runtime store unavailable", error))?
    };

    let boarding_response = if let Some((_, mut aggregates)) = runtime_groups
        .into_iter()
        .find(|(candidate_trip_id, _)| candidate_trip_id == &trip_id)
    {
        let mut event_map = coach_load_boarding_event_map(&state, Some(&trip_id)).await?;
        let Some(existing_entry) = coach_runtime_crew_manifest_entry_by_ticket_id(
            &aggregates,
            &trip_id,
            &event_map,
            &ticket_id,
        ) else {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        };
        let existing_scan_status = event_map
            .get(&coach_boarding_event_store_key(&trip_id, &ticket_id))
            .map(|entry| entry.scan_status.as_str());
        let effective_scan_status = if requested_scan_status == "scanned"
            && matches!(existing_scan_status, Some("scanned" | "duplicate"))
        {
            "duplicate"
        } else {
            requested_scan_status
        };
        let boarding_event = CoachBoardingEventEntry {
            boarding_event_id: coach_scoped_resource_id(
                "boardevt",
                &format!("{trip_id}-{ticket_id}-{}", &request_fingerprint[..12]),
            ),
            ticket_id: ticket_id.clone(),
            trip_id: trip_id.clone(),
            scan_status: effective_scan_status.to_string(),
            captured_at: now_rfc3339(),
            offline_captured,
            device_id,
            note,
        };
        coach_upsert_boarding_event_entry(&state, &boarding_event).await?;
        event_map.insert(
            coach_boarding_event_store_key(&trip_id, &ticket_id),
            boarding_event.clone(),
        );
        let persisted_boarding_state = match effective_scan_status {
            "scanned" | "duplicate" => "boarded",
            "denied" => "denied",
            "no_show" => "no_show",
            _ => "not_boarded",
        };
        for aggregate in &mut aggregates {
            let booking_id = aggregate
                .booking
                .get("booking_id")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string();
            let has_ticket = aggregate.tickets.iter().any(|ticket| {
                ticket.get("ticket_id").and_then(Value::as_str) == Some(ticket_id.as_str())
            });
            if booking_id.is_empty() || !has_ticket {
                continue;
            }
            let updated_tickets = aggregate
                .tickets
                .iter()
                .map(|ticket| {
                    if ticket.get("ticket_id").and_then(Value::as_str) == Some(ticket_id.as_str()) {
                        coach_ticket_payload_with_boarding_state(ticket, persisted_boarding_state)
                    } else {
                        ticket.clone()
                    }
                })
                .collect::<Vec<_>>();
            coach_persist_ticket_payloads(
                &state,
                aggregate.account_id.as_str(),
                &booking_id,
                updated_tickets.as_slice(),
            )
            .await
            .map_err(|error| coach_storage_error("coach ticket store unavailable", error))?;
            aggregate.tickets = updated_tickets;
            break;
        }
        let manifest_entry = coach_runtime_crew_manifest_entry_by_ticket_id(
            &aggregates,
            &trip_id,
            &event_map,
            &ticket_id,
        )
        .unwrap_or(existing_entry);
        coach_runtime_crew_boarding_result_response(
            &idempotency_key,
            &request_fingerprint,
            &aggregates,
            &trip_id,
            &event_map,
            manifest_entry,
            &boarding_event,
        )
    } else {
        let Some(crew_trip_seed) = coach_demo_crew_trip_seed(&trip_id) else {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        };
        let Some(booking_seed) = coach_demo_booking_seed(crew_trip_seed.booking_id) else {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        };
        if !coach_operator_scope_allows_demo_booking_seed(&booking_seed, &allowed_operator_scope) {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        }
        let mut event_map = coach_load_boarding_event_map(&state, Some(&trip_id)).await?;
        let Some(existing_entry) = coach_crew_manifest_entry_by_ticket_id(
            &crew_trip_seed,
            &booking_seed,
            &event_map,
            &ticket_id,
        ) else {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        };
        let existing_scan_status = event_map
            .get(&coach_boarding_event_store_key(&trip_id, &ticket_id))
            .map(|entry| entry.scan_status.as_str());
        let effective_scan_status = if requested_scan_status == "scanned"
            && matches!(existing_scan_status, Some("scanned" | "duplicate"))
        {
            "duplicate"
        } else {
            requested_scan_status
        };
        let captured_at = match (crew_trip_seed.trip_id, effective_scan_status) {
            ("trip_demo_express_direct", "scanned") => "2026-04-08T07:41:00Z",
            ("trip_demo_express_direct", "duplicate") => "2026-04-08T07:42:30Z",
            ("trip_demo_express_direct", "denied") => "2026-04-08T07:43:10Z",
            ("trip_demo_express_direct", "no_show") => "2026-04-08T08:01:00Z",
            ("trip_demo_border_runner", "scanned") => "2026-04-10T05:02:00Z",
            ("trip_demo_border_runner", "duplicate") => "2026-04-10T05:03:40Z",
            ("trip_demo_border_runner", "denied") => "2026-04-10T05:05:00Z",
            ("trip_demo_border_runner", "no_show") => "2026-04-10T05:25:00Z",
            _ => "2026-04-07T15:05:00Z",
        };
        let boarding_event = CoachBoardingEventEntry {
            boarding_event_id: coach_scoped_resource_id(
                "boardevt",
                &format!("{trip_id}-{ticket_id}-{}", &request_fingerprint[..12]),
            ),
            ticket_id: ticket_id.clone(),
            trip_id: trip_id.clone(),
            scan_status: effective_scan_status.to_string(),
            captured_at: captured_at.to_string(),
            offline_captured,
            device_id,
            note,
        };
        coach_upsert_boarding_event_entry(&state, &boarding_event).await?;
        event_map.insert(
            coach_boarding_event_store_key(&trip_id, &ticket_id),
            boarding_event.clone(),
        );
        let manifest_entry = coach_crew_manifest_entry_by_ticket_id(
            &crew_trip_seed,
            &booking_seed,
            &event_map,
            &ticket_id,
        )
        .unwrap_or(existing_entry);
        coach_crew_boarding_result_response(
            &idempotency_key,
            &request_fingerprint,
            &crew_trip_seed,
            &booking_seed,
            &event_map,
            manifest_entry,
            &boarding_event,
        )
    };

    coach_store_or_replay_idempotent_response(
        &state,
        principal.account_id.as_str(),
        "coach_crew_boarding_record",
        &idempotency_key,
        &request_fingerprint,
        boarding_response,
    )
    .await
}

pub async fn rides_pricing_preview(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RidePricingPreviewQuery>,
) -> ApiResult<Response> {
    let _principal = auth::require_session_principal(&state, &headers).await?;
    let ride_class = canonical_ride_class(Some(q.ride_class))?;
    if !(100..=500_000).contains(&q.distance_m) {
        return Err(ApiError::bad_request("distance_m out of range"));
    }
    if !(30..=86_400).contains(&q.eta_s) {
        return Err(ApiError::bad_request("eta_s out of range"));
    }
    let traffic_delay_s = q.traffic_delay_s.unwrap_or(0);
    if !(0..=86_400).contains(&traffic_delay_s) {
        return Err(ApiError::bad_request("traffic_delay_s out of range"));
    }
    let policy = load_ride_pricing_policy(&state, ride_class.as_str()).await?;
    let preview = build_ride_pricing_preview_with_rule(
        ride_class.as_str(),
        policy.rule,
        q.distance_m,
        q.eta_s,
        traffic_delay_s.min(q.eta_s),
    );
    Ok(json_no_store_response(preview))
}

pub async fn rides_operator_pricing_policy(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let (_principal, _) = auth::require_ride_pricing_principal(&state, &headers).await?;
    let policies = load_all_ride_pricing_policies(&state).await?;
    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "policies": policies.iter().map(ride_pricing_policy_json).collect::<Vec<_>>(),
    })))
}

pub async fn rides_operator_pricing_policy_upsert(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideOperatorPricingPolicyUpsertIn>,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_pricing_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let ride_class = canonical_ride_class(body.ride_class.clone())?;
    let base_fare_minor_units = body
        .base_fare_minor_units
        .filter(|value| (1..=1_000_000).contains(value))
        .ok_or_else(|| ApiError::bad_request("invalid base_fare_minor_units"))?;
    let per_km_minor_units = body
        .per_km_minor_units
        .filter(|value| (0..=100_000).contains(value))
        .ok_or_else(|| ApiError::bad_request("invalid per_km_minor_units"))?;
    let per_minute_minor_units = body
        .per_minute_minor_units
        .filter(|value| (0..=100_000).contains(value))
        .ok_or_else(|| ApiError::bad_request("invalid per_minute_minor_units"))?;
    let traffic_delay_per_minute_minor_units = body
        .traffic_delay_per_minute_minor_units
        .filter(|value| (0..=100_000).contains(value))
        .ok_or_else(|| ApiError::bad_request("invalid traffic_delay_per_minute_minor_units"))?;
    let booking_fee_minor_units = body
        .booking_fee_minor_units
        .filter(|value| (0..=100_000).contains(value))
        .ok_or_else(|| ApiError::bad_request("invalid booking_fee_minor_units"))?;
    let minimum_fare_minor_units = body
        .minimum_fare_minor_units
        .filter(|value| (1..=1_000_000).contains(value))
        .ok_or_else(|| ApiError::bad_request("invalid minimum_fare_minor_units"))?;
    let driver_share_bps = body
        .driver_share_bps
        .filter(|value| (1_000..=9_900).contains(value))
        .ok_or_else(|| ApiError::bad_request("invalid driver_share_bps"))?;
    let updated_by_account_id = principal.account_id.trim();
    if updated_by_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let row = sqlx::query(
        r#"
        INSERT INTO auth_ride_pricing_policies (
          ride_class,
          base_fare_minor_units,
          per_km_minor_units,
          per_minute_minor_units,
          traffic_delay_per_minute_minor_units,
          booking_fee_minor_units,
          minimum_fare_minor_units,
          driver_share_bps,
          updated_by_account_id,
          updated_at
        ) VALUES (
          $1, $2, $3, $4, $5, $6, $7, $8, $9, NOW()
        )
        ON CONFLICT (ride_class)
        DO UPDATE SET
          base_fare_minor_units = EXCLUDED.base_fare_minor_units,
          per_km_minor_units = EXCLUDED.per_km_minor_units,
          per_minute_minor_units = EXCLUDED.per_minute_minor_units,
          traffic_delay_per_minute_minor_units = EXCLUDED.traffic_delay_per_minute_minor_units,
          booking_fee_minor_units = EXCLUDED.booking_fee_minor_units,
          minimum_fare_minor_units = EXCLUDED.minimum_fare_minor_units,
          driver_share_bps = EXCLUDED.driver_share_bps,
          updated_by_account_id = EXCLUDED.updated_by_account_id,
          updated_at = NOW()
        RETURNING
          ride_class,
          base_fare_minor_units,
          per_km_minor_units,
          per_minute_minor_units,
          traffic_delay_per_minute_minor_units,
          booking_fee_minor_units,
          minimum_fare_minor_units,
          driver_share_bps,
          updated_by_account_id,
          to_char(updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS\"Z\"') AS updated_at
        "#,
    )
    .bind(ride_class.as_str())
    .bind(base_fare_minor_units)
    .bind(per_km_minor_units)
    .bind(per_minute_minor_units)
    .bind(traffic_delay_per_minute_minor_units)
    .bind(booking_fee_minor_units)
    .bind(minimum_fare_minor_units)
    .bind(driver_share_bps)
    .bind(updated_by_account_id)
    .fetch_one(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, ride_class = ride_class.as_str(), "ride pricing policy upsert failed");
        ApiError::internal("ride pricing policy unavailable")
    })?;

    Ok(json_no_store_response(ride_pricing_policy_json(
        &parse_ride_pricing_policy_row(&row)?,
    )))
}

pub async fn rides_map_tile(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path((z, x, y)): Path<(u8, u32, u32)>,
    Query(q): Query<RideMapTileQuery>,
) -> ApiResult<Response> {
    let principal = auth::require_session_principal(&state, &headers).await?;
    validate_tomtom_tile_coordinates(z, x, y)?;

    auth::enforce_map_tile_rate_limit(&state, &headers, &principal).await?;

    let layer = normalize_tomtom_tile_selector(q.layer.as_deref(), "layer", "basic")?;
    let style = normalize_tomtom_tile_selector(q.style.as_deref(), "style", "main")?;
    let tile_size = normalize_tomtom_tile_size(q.tile_size)?;
    let view = normalize_tomtom_tile_view(q.view.as_deref())?;
    let language = normalize_tomtom_tile_language(q.language.as_deref())?;

    let path = format!("/map/1/tile/{layer}/{style}/{z}/{x}/{y}.png");
    let query_params = vec![
        ("tileSize", tile_size.to_string()),
        ("view", view),
        ("language", language),
    ];
    fetch_tomtom_tile(&state, &path, &query_params).await
}

#[derive(Clone, Debug)]
struct RideTripCreateCanonical {
    pickup: String,
    destination: String,
    pickup_label: String,
    destination_label: String,
    pickup_lat: Option<f64>,
    pickup_lon: Option<f64>,
    destination_lat: Option<f64>,
    destination_lon: Option<f64>,
    ride_class: String,
    fare_estimate_cents: i64,
    eta_seconds: i64,
    driver_name: Option<String>,
    car_plate: Option<String>,
}

#[derive(Clone, Debug)]
struct RideTripCommandCanonical {
    command: String,
    driver_account_id: Option<String>,
    driver_name: Option<String>,
    car_plate: Option<String>,
    eta_seconds: Option<i64>,
    reason: Option<String>,
    cancel_reason_code: Option<String>,
}

fn canonical_ride_trip_status(value: &str) -> Option<&'static str> {
    match value.trim().to_ascii_lowercase().as_str() {
        "ride_requested" => Some("ride_requested"),
        "matching" | "searching" => Some("matching"),
        "driver_assigned" => Some("driver_assigned"),
        "driver_arriving" => Some("driver_arriving"),
        "driver_arrived" => Some("driver_arrived"),
        "trip_started" => Some("trip_started"),
        "trip_in_progress" | "in_progress" => Some("trip_in_progress"),
        "payment_failed" => Some("payment_failed"),
        "trip_completed" | "completed" => Some("trip_completed"),
        "cancelled" | "canceled" => Some("cancelled"),
        _ => None,
    }
}

fn canonical_ride_trip_command(raw: Option<String>) -> ApiResult<String> {
    let command_raw =
        canonical_trimmed_field(raw).ok_or_else(|| ApiError::bad_request("command required"))?;
    let canonical = match command_raw.to_ascii_lowercase().as_str() {
        "enter_matching" | "matching" => "enter_matching",
        "assign_driver" | "driver_assigned" => "assign_driver",
        "mark_driver_arriving" | "driver_arriving" => "mark_driver_arriving",
        "mark_driver_arrived" | "driver_arrived" => "mark_driver_arrived",
        "start_trip" | "trip_started" => "start_trip",
        "mark_in_progress" | "in_progress" | "trip_in_progress" => "mark_in_progress",
        "mark_payment_failed" | "payment_failed" => "mark_payment_failed",
        "complete_trip" | "complete" | "trip_completed" => "complete_trip",
        "cancel_trip" | "cancel" | "cancelled" | "canceled" => "cancel_trip",
        "reassign_trip" | "reassign" => "reassign_trip",
        _ => return Err(ApiError::bad_request("invalid ride command")),
    };
    Ok(canonical.to_string())
}

fn canonical_driver_trip_status_command(raw: Option<String>) -> ApiResult<String> {
    let status_raw =
        canonical_trimmed_field(raw).ok_or_else(|| ApiError::bad_request("status required"))?;
    let canonical = match status_raw.to_ascii_lowercase().as_str() {
        "head_to_pickup" | "driver_arriving" | "arriving" => "mark_driver_arriving",
        "arrived_pickup" | "driver_arrived" | "arrived" => "mark_driver_arrived",
        "start_trip" | "trip_started" => "start_trip",
        "in_progress" | "trip_in_progress" => "mark_in_progress",
        "payment_failed" => "mark_payment_failed",
        "complete_trip" | "trip_completed" | "completed" => "complete_trip",
        "cancel_trip" | "cancelled" | "canceled" | "cancel" => "cancel_trip",
        _ => return Err(ApiError::bad_request("invalid ride status command")),
    };
    Ok(canonical.to_string())
}

fn ride_trip_command_target_status(command: &str) -> Option<&'static str> {
    match command {
        "enter_matching" => Some("matching"),
        "reassign_trip" => Some("matching"),
        "assign_driver" => Some("driver_assigned"),
        "mark_driver_arriving" => Some("driver_arriving"),
        "mark_driver_arrived" => Some("driver_arrived"),
        "start_trip" => Some("trip_started"),
        "mark_in_progress" => Some("trip_in_progress"),
        "mark_payment_failed" => Some("payment_failed"),
        "complete_trip" => Some("trip_completed"),
        "cancel_trip" => Some("cancelled"),
        _ => None,
    }
}

fn ride_trip_status_requires_driver_metadata(status: &str) -> bool {
    matches!(
        status,
        "driver_assigned"
            | "driver_arriving"
            | "driver_arrived"
            | "trip_started"
            | "trip_in_progress"
            | "payment_failed"
            | "trip_completed"
    )
}

fn ride_trip_command_allowed_from_status(status: &str, command: &str) -> bool {
    matches!(
        (status, command),
        ("ride_requested", "enter_matching" | "cancel_trip")
            | ("matching", "assign_driver" | "cancel_trip")
            | ("driver_assigned", "reassign_trip")
            | ("driver_assigned", "mark_driver_arriving" | "cancel_trip")
            | ("driver_arriving", "reassign_trip")
            | ("driver_arriving", "mark_driver_arrived" | "cancel_trip")
            | ("driver_arrived", "reassign_trip")
            | ("driver_arrived", "start_trip" | "cancel_trip")
            | ("trip_started", "mark_in_progress" | "cancel_trip")
            | ("trip_in_progress", "mark_payment_failed" | "complete_trip")
            | ("payment_failed", "complete_trip" | "cancel_trip")
            | ("trip_completed", "complete_trip")
            | ("cancelled", "cancel_trip")
    )
}

fn ride_trip_status_allows_operator_reassign(status: &str) -> bool {
    matches!(
        status,
        "driver_assigned" | "driver_arriving" | "driver_arrived"
    )
}

fn canonical_ride_text_field(
    value: Option<String>,
    field_name: &'static str,
    max_chars: usize,
) -> ApiResult<String> {
    let value = canonical_trimmed_field(value)
        .ok_or_else(|| ApiError::bad_request(format!("{field_name} required")))?;
    if value.chars().count() > max_chars || value.chars().any(|ch| ch.is_ascii_control()) {
        return Err(ApiError::bad_request(format!("invalid {field_name}")));
    }
    Ok(value)
}

fn canonical_optional_ride_text_field(
    value: Option<String>,
    field_name: &'static str,
    max_chars: usize,
) -> ApiResult<Option<String>> {
    let Some(value) = canonical_trimmed_field(value) else {
        return Ok(None);
    };
    if value.chars().count() > max_chars || value.chars().any(|ch| ch.is_ascii_control()) {
        return Err(ApiError::bad_request(format!("invalid {field_name}")));
    }
    Ok(Some(value))
}

fn canonical_ride_reason_code(value: Option<String>) -> ApiResult<Option<String>> {
    let Some(value) = canonical_trimmed_field(value) else {
        return Ok(None);
    };
    let lowered = value.to_ascii_lowercase();
    if lowered.chars().count() > RIDE_TRIP_REASON_CODE_MAX_CHARS
        || !lowered
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-'))
    {
        return Err(ApiError::bad_request("invalid cancel_reason_code"));
    }
    Ok(Some(lowered))
}

fn canonical_ride_class(value: Option<String>) -> ApiResult<String> {
    let raw = canonical_trimmed_field(value)
        .ok_or_else(|| ApiError::bad_request("ride_class required"))?;
    let normalized = match raw.to_ascii_lowercase().as_str() {
        "economy" => "economy",
        "comfort" | "xl" | "van" => "xl",
        "premium" => "premium",
        "delivery" => "delivery",
        "corporate" => "corporate",
        _ => return Err(ApiError::bad_request("invalid ride_class")),
    };
    Ok(normalized.to_string())
}

fn canonical_ride_latitude(value: f64) -> ApiResult<f64> {
    if !value.is_finite() || !(-90.0..=90.0).contains(&value) {
        return Err(ApiError::bad_request("invalid latitude"));
    }
    Ok((value * 1_000_000.0).round() / 1_000_000.0)
}

fn canonical_ride_longitude(value: f64) -> ApiResult<f64> {
    if !value.is_finite() || !(-180.0..=180.0).contains(&value) {
        return Err(ApiError::bad_request("invalid longitude"));
    }
    Ok((value * 1_000_000.0).round() / 1_000_000.0)
}

fn canonical_ride_optional_small_i64(
    value: Option<i64>,
    field_name: &'static str,
    min: i64,
    max: i64,
) -> ApiResult<Option<i64>> {
    match value {
        Some(value) if value < min || value > max => {
            Err(ApiError::bad_request(format!("{field_name} out of range")))
        }
        Some(value) => Ok(Some(value)),
        None => Ok(None),
    }
}

fn canonical_ride_optional_point(
    lat: Option<f64>,
    lon: Option<f64>,
    prefix: &'static str,
) -> ApiResult<(Option<f64>, Option<f64>)> {
    match (lat, lon) {
        (Some(lat), Some(lon)) => Ok((
            Some(canonical_ride_latitude(lat)?),
            Some(canonical_ride_longitude(lon)?),
        )),
        (None, None) => Ok((None, None)),
        _ => Err(ApiError::bad_request(format!(
            "{prefix}_lat and {prefix}_lon required together"
        ))),
    }
}

fn canonical_ride_trip_create_input(body: RideTripCreateIn) -> ApiResult<RideTripCreateCanonical> {
    let pickup = canonical_ride_text_field(
        body.pickup.clone().or(body.pickup_label.clone()),
        "pickup",
        RIDE_TRIP_PLACE_MAX_CHARS,
    )?;
    let destination = canonical_ride_text_field(
        body.destination.clone().or(body.destination_label.clone()),
        "destination",
        RIDE_TRIP_PLACE_MAX_CHARS,
    )?;
    if pickup.eq_ignore_ascii_case(destination.as_str()) {
        return Err(ApiError::bad_request("pickup and destination must differ"));
    }
    let pickup_label = canonical_ride_text_field(
        body.pickup_label.or_else(|| Some(pickup.clone())),
        "pickup_label",
        RIDE_TRIP_PLACE_MAX_CHARS,
    )?;
    let destination_label = canonical_ride_text_field(
        body.destination_label.or_else(|| Some(destination.clone())),
        "destination_label",
        RIDE_TRIP_PLACE_MAX_CHARS,
    )?;
    let (pickup_lat, pickup_lon) =
        canonical_ride_optional_point(body.pickup_lat, body.pickup_lon, "pickup")?;
    let (destination_lat, destination_lon) =
        canonical_ride_optional_point(body.destination_lat, body.destination_lon, "destination")?;
    let ride_class = canonical_ride_class(body.ride_class)?;
    let fare_estimate_cents = body
        .fare_estimate_cents
        .ok_or_else(|| ApiError::bad_request("fare_estimate_cents required"))?;
    if !(1..=500_000_000).contains(&fare_estimate_cents) {
        return Err(ApiError::bad_request("fare_estimate_cents out of range"));
    }
    let eta_seconds = body
        .eta_seconds
        .ok_or_else(|| ApiError::bad_request("eta_seconds required"))?;
    if !(30..=86_400).contains(&eta_seconds) {
        return Err(ApiError::bad_request("eta_seconds out of range"));
    }
    let driver_name = canonical_optional_ride_text_field(
        body.driver_name,
        "driver_name",
        RIDE_TRIP_DRIVER_NAME_MAX_CHARS,
    )?;
    let car_plate = canonical_optional_ride_text_field(
        body.car_plate,
        "car_plate",
        RIDE_TRIP_CAR_PLATE_MAX_CHARS,
    )?;
    if driver_name.is_some() || car_plate.is_some() {
        return Err(ApiError::bad_request(
            "driver fields are not allowed on ride create",
        ));
    }
    Ok(RideTripCreateCanonical {
        pickup,
        destination,
        pickup_label,
        destination_label,
        pickup_lat,
        pickup_lon,
        destination_lat,
        destination_lon,
        ride_class,
        fare_estimate_cents,
        eta_seconds,
        driver_name,
        car_plate,
    })
}

fn canonical_ride_trip_command_input(
    body: RideTripCommandIn,
) -> ApiResult<RideTripCommandCanonical> {
    let command = canonical_ride_trip_command(body.command)?;
    let driver_account_id = canonical_optional_ride_text_field(
        body.driver_account_id,
        "driver_account_id",
        PAYMENTS_RESOURCE_ID_MAX_LEN,
    )?;
    let driver_name = canonical_optional_ride_text_field(
        body.driver_name,
        "driver_name",
        RIDE_TRIP_DRIVER_NAME_MAX_CHARS,
    )?;
    let car_plate = canonical_optional_ride_text_field(
        body.car_plate,
        "car_plate",
        RIDE_TRIP_CAR_PLATE_MAX_CHARS,
    )?;
    let reason =
        canonical_optional_ride_text_field(body.reason, "reason", RIDE_TRIP_NOTE_MAX_CHARS)?;
    let cancel_reason_code = canonical_ride_reason_code(body.cancel_reason_code)?;
    if command == "assign_driver" {
        if driver_name.is_none() || car_plate.is_none() {
            return Err(ApiError::bad_request(
                "assign_driver requires driver_name and car_plate",
            ));
        }
    } else if driver_account_id.is_some() || driver_name.is_some() || car_plate.is_some() {
        return Err(ApiError::bad_request(
            "driver fields are only allowed for assign_driver",
        ));
    }
    if !matches!(command.as_str(), "cancel_trip" | "reassign_trip") && reason.is_some() {
        return Err(ApiError::bad_request(
            "reason is only allowed for cancel_trip or reassign_trip",
        ));
    }
    if command != "cancel_trip" && cancel_reason_code.is_some() {
        return Err(ApiError::bad_request(
            "cancel_reason_code is only allowed for cancel_trip",
        ));
    }
    let eta_seconds = match body.eta_seconds {
        Some(value) => {
            if !(30..=86_400).contains(&value) {
                return Err(ApiError::bad_request("eta_seconds out of range"));
            }
            Some(value)
        }
        None => None,
    };
    Ok(RideTripCommandCanonical {
        command,
        driver_account_id,
        driver_name,
        car_plate,
        eta_seconds,
        reason,
        cancel_reason_code,
    })
}

fn canonical_ride_driver_trip_status_input(
    body: RideDriverTripStatusIn,
) -> ApiResult<RideTripCommandCanonical> {
    canonical_ride_trip_command_input(RideTripCommandIn {
        command: Some(canonical_driver_trip_status_command(body.status)?),
        driver_account_id: None,
        driver_name: None,
        car_plate: None,
        eta_seconds: body.eta_seconds,
        reason: body.reason,
        cancel_reason_code: body.cancel_reason_code,
    })
}

