fn canonical_ride_document_review_note(
    decision: &str,
    raw_note: Option<&str>,
) -> ApiResult<Option<String>> {
    let note = raw_note
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    if note
        .as_deref()
        .map(|value| value.chars().count() > RIDE_DRIVER_DOCUMENT_REVIEW_NOTE_MAX_CHARS)
        .unwrap_or(false)
    {
        return Err(ApiError::bad_request("review note too long"));
    }
    if decision == "rejected" && note.is_none() {
        return Err(ApiError::bad_request(
            "review note required for rejected document",
        ));
    }
    Ok(note)
}

struct RideSensitiveMutationAuditEvent<'a> {
    operation: &'static str,
    outcome: &'static str,
    actor_account_id: &'a str,
    actor_roles: &'a [String],
    ride_id: Option<&'a str>,
    document_id: Option<&'a str>,
    request_id: Option<&'a str>,
    subject_account_id: Option<&'a str>,
    reason: Option<&'a str>,
}

fn audit_ride_sensitive_mutation_event(event: RideSensitiveMutationAuditEvent<'_>) {
    let RideSensitiveMutationAuditEvent {
        operation,
        outcome,
        actor_account_id,
        actor_roles,
        ride_id,
        document_id,
        request_id,
        subject_account_id,
        reason,
    } = event;
    let actor_account_hash = auth::hash_prefix(actor_account_id.trim());
    let mut normalized_roles = actor_roles
        .iter()
        .map(|role| role.trim().to_ascii_lowercase())
        .filter(|role| !role.is_empty())
        .collect::<Vec<_>>();
    normalized_roles.sort();
    normalized_roles.dedup();
    let actor_roles = normalized_roles.join(",");
    let ride_id_hash = ride_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(auth::hash_prefix)
        .unwrap_or_default();
    let document_id_hash = document_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(auth::hash_prefix)
        .unwrap_or_default();
    let request_id_hash = request_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(auth::hash_prefix)
        .unwrap_or_default();
    let subject_account_hash = subject_account_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(auth::hash_prefix)
        .unwrap_or_default();
    let reason = reason.unwrap_or("");
    if matches!(outcome, "blocked" | "failed" | "rejected") {
        tracing::warn!(
            security_event = "ride_sensitive_mutation",
            operation,
            outcome,
            reason,
            actor_account_hash,
            actor_roles,
            ride_id_hash,
            document_id_hash,
            request_id_hash,
            subject_account_hash,
            "ride sensitive mutation security event"
        );
    } else {
        tracing::info!(
            security_event = "ride_sensitive_mutation",
            operation,
            outcome,
            actor_account_hash,
            actor_roles,
            ride_id_hash,
            document_id_hash,
            request_id_hash,
            subject_account_hash,
            "ride sensitive mutation security event"
        );
    }
}

