fn now_rfc3339() -> String {
    chrono::DateTime::<chrono::Utc>::from(SystemTime::now()).to_rfc3339()
}

fn now_rfc3339_utc_seconds() -> String {
    chrono::DateTime::<chrono::Utc>::from(SystemTime::now())
        .to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
}

fn coach_runtime_reviewed_at() -> String {
    now_rfc3339_utc_seconds()
}

fn coach_runtime_payout_paid_at() -> String {
    now_rfc3339_utc_seconds()
}

fn coach_runtime_settlement_export_created_at() -> String {
    now_rfc3339_utc_seconds()
}

