fn ride_trip_create_fingerprint(input: &RideTripCreateCanonical) -> String {
    sha256_hex(&format!(
        "{}\n{}\n{}\n{}\n{}\n{}\n{}",
        input.pickup,
        input.destination,
        input.ride_class,
        input.fare_estimate_cents,
        input.eta_seconds,
        input.driver_name.as_deref().unwrap_or_default(),
        input.car_plate.as_deref().unwrap_or_default(),
    ))
}

fn ride_trip_command_fingerprint(ride_id: &str, input: &RideTripCommandCanonical) -> String {
    sha256_hex(&format!(
        "{}\n{}\n{}\n{}\n{}\n{}\n{}",
        ride_id,
        input.command,
        input.driver_account_id.as_deref().unwrap_or_default(),
        input.driver_name.as_deref().unwrap_or_default(),
        input.car_plate.as_deref().unwrap_or_default(),
        input.eta_seconds.unwrap_or_default(),
        input.reason.as_deref().unwrap_or_default(),
    ))
}

fn is_sqlx_unique_violation(error: &sqlx::Error) -> bool {
    matches!(
        error,
        sqlx::Error::Database(db_error)
            if db_error.code().as_deref() == Some("23505")
    )
}

fn ride_trip_i64_column(
    row: &sqlx::postgres::PgRow,
    column: &'static str,
    context: &'static str,
) -> ApiResult<i64> {
    if let Ok(value) = row.try_get::<i64, _>(column) {
        return Ok(value);
    }
    row.try_get::<i32, _>(column)
        .map(i64::from)
        .map_err(|error| {
            tracing::error!(%error, column, context, "ride trip numeric column decode failed");
            ApiError::internal("ride trip unavailable")
        })
}

fn ride_row_has_column(row: &PgRow, column: &str) -> bool {
    row.columns().iter().any(|entry| entry.name() == column)
}

fn ride_trip_optional_text_if_present(
    row: &PgRow,
    column: &'static str,
    context: &'static str,
) -> ApiResult<Option<String>> {
    if !ride_row_has_column(row, column) {
        return Ok(None);
    }
    row.try_get(column).map_err(|error| {
        tracing::error!(%error, column, context, "ride trip optional text column decode failed");
        ApiError::internal("ride trip unavailable")
    })
}

fn ride_trip_optional_f64_if_present(
    row: &PgRow,
    column: &'static str,
    context: &'static str,
) -> ApiResult<Option<f64>> {
    if !ride_row_has_column(row, column) {
        return Ok(None);
    }
    row.try_get(column).map_err(|error| {
        tracing::error!(%error, column, context, "ride trip optional f64 column decode failed");
        ApiError::internal("ride trip unavailable")
    })
}

fn ride_trip_response_from_row(row: &sqlx::postgres::PgRow) -> ApiResult<Value> {
    let ride_id: String = row.try_get("ride_id").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let rider_account_id: String = row.try_get("rider_account_id").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let status: String = row.try_get("status").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let pickup_text: String = row.try_get("pickup_text").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let destination_text: String = row.try_get("destination_text").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let pickup_label =
        ride_trip_optional_text_if_present(row, "pickup_label", "ride_trip_response_from_row")?
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| pickup_text.clone());
    let destination_label = ride_trip_optional_text_if_present(
        row,
        "destination_label",
        "ride_trip_response_from_row",
    )?
    .filter(|value| !value.trim().is_empty())
    .unwrap_or_else(|| destination_text.clone());
    let pickup_lat =
        ride_trip_optional_f64_if_present(row, "pickup_lat", "ride_trip_response_from_row")?;
    let pickup_lon =
        ride_trip_optional_f64_if_present(row, "pickup_lon", "ride_trip_response_from_row")?;
    let destination_lat =
        ride_trip_optional_f64_if_present(row, "destination_lat", "ride_trip_response_from_row")?;
    let destination_lon =
        ride_trip_optional_f64_if_present(row, "destination_lon", "ride_trip_response_from_row")?;
    let ride_class: String = row.try_get("ride_class").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let fare_estimate_cents =
        ride_trip_i64_column(row, "fare_estimate_cents", "ride_trip_response_from_row")?;
    let eta_seconds = ride_trip_i64_column(row, "eta_seconds", "ride_trip_response_from_row")?;
    let driver_account_id: Option<String> = row.try_get("driver_account_id").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let driver_name_raw: Option<String> = row.try_get("driver_name").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let car_plate_raw: Option<String> = row.try_get("car_plate").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let cancel_reason: Option<String> = row.try_get("cancel_reason").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let cancel_reason_code = ride_trip_optional_text_if_present(
        row,
        "cancel_reason_code",
        "ride_trip_response_from_row",
    )?;
    let created_at: String = row.try_get("created_at").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let status_updated_at: String = row.try_get("status_updated_at").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let updated_at: String = row.try_get("updated_at").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let terminal_at: Option<String> = row.try_get("terminal_at").map_err(|error| {
        tracing::error!(%error, "ride trip column decode failed");
        ApiError::internal("ride trip unavailable")
    })?;
    let assigned_at =
        ride_trip_optional_text_if_present(row, "assigned_at", "ride_trip_response_from_row")?;
    let arriving_at =
        ride_trip_optional_text_if_present(row, "arriving_at", "ride_trip_response_from_row")?;
    let arrived_at =
        ride_trip_optional_text_if_present(row, "arrived_at", "ride_trip_response_from_row")?;
    let started_at =
        ride_trip_optional_text_if_present(row, "started_at", "ride_trip_response_from_row")?;
    let completed_at =
        ride_trip_optional_text_if_present(row, "completed_at", "ride_trip_response_from_row")?;
    let offer_id =
        ride_trip_optional_text_if_present(row, "offer_id", "ride_trip_response_from_row")?;
    let driver_name = driver_name_raw
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "Driver pending".to_string());
    let car_plate = car_plate_raw
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "--".to_string());
    let eta_minutes = ((eta_seconds + 59) / 60).clamp(1, 24 * 60);
    Ok(json!({
        "ride_id": ride_id,
        "offer_id": offer_id,
        "rider_account_id": rider_account_id,
        "driver_account_id": driver_account_id,
        "driver_name": driver_name,
        "car_plate": car_plate,
        "pickup": pickup_text,
        "destination": destination_text,
        "pickup_label": pickup_label,
        "destination_label": destination_label,
        "pickup_location": match (pickup_lat, pickup_lon) {
            (Some(lat), Some(lon)) => Some(json!({"lat": lat, "lon": lon})),
            _ => None,
        },
        "destination_location": match (destination_lat, destination_lon) {
            (Some(lat), Some(lon)) => Some(json!({"lat": lat, "lon": lon})),
            _ => None,
        },
        "pickup_lat": pickup_lat,
        "pickup_lon": pickup_lon,
        "destination_lat": destination_lat,
        "destination_lon": destination_lon,
        "ride_class": ride_class,
        "fare_estimate_cents": fare_estimate_cents,
        "eta_seconds": eta_seconds,
        "eta_minutes": eta_minutes,
        "status": status,
        "cancel_reason": cancel_reason,
        "cancel_reason_code": cancel_reason_code,
        "created_at": created_at,
        "status_updated_at": status_updated_at,
        "last_updated_at": status_updated_at,
        "updated_at": updated_at,
        "terminal_at": terminal_at,
        "assigned_at": assigned_at,
        "arriving_at": arriving_at,
        "arrived_at": arrived_at,
        "started_at": started_at,
        "completed_at": completed_at,
    }))
}

fn ride_operator_trip_response(mut trip: Value, allow_precise_location: bool) -> Value {
    let Some(payload) = trip.as_object_mut() else {
        return trip;
    };
    payload.remove("rider_account_id");
    payload.remove("driver_account_id");
    if !allow_precise_location {
        payload.remove("pickup_location");
        payload.remove("destination_location");
        payload.remove("pickup_lat");
        payload.remove("pickup_lon");
        payload.remove("destination_lat");
        payload.remove("destination_lon");
    }
    trip
}

fn ride_operator_case_response(mut case: Value, allow_sensitive_details: bool) -> Value {
    if allow_sensitive_details {
        return case;
    }
    let Some(payload) = case.as_object_mut() else {
        return case;
    };
    payload.insert("pickup".to_string(), json!("Route redacted"));
    payload.insert("destination".to_string(), json!("Route redacted"));
    payload.insert("driver_name".to_string(), json!("Driver redacted"));
    payload.insert("car_plate".to_string(), json!("--"));
    case
}

fn ride_support_ticket_redacted_body(category: &str) -> &'static str {
    match category.trim().to_ascii_lowercase().as_str() {
        "safety" => {
            "Sensitive safety ticket content is restricted to support and compliance reviewers."
        }
        "payment_issue" => {
            "Sensitive payment ticket content is restricted to support and compliance reviewers."
        }
        _ => "Sensitive support ticket content is restricted to support and compliance reviewers.",
    }
}

fn ride_support_ticket_response(mut ticket: Value, allow_sensitive_details: bool) -> Value {
    if allow_sensitive_details {
        return ticket;
    }
    let Some(payload) = ticket.as_object_mut() else {
        return ticket;
    };
    let category = payload
        .get("category")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    payload.insert(
        "body".to_string(),
        json!(ride_support_ticket_redacted_body(&category)),
    );
    payload.insert("resolution_note".to_string(), Value::Null);
    payload.insert("pickup".to_string(), Value::Null);
    payload.insert("destination".to_string(), Value::Null);
    payload.insert("driver_name".to_string(), Value::Null);
    payload.insert("car_plate".to_string(), Value::Null);
    ticket
}

fn ride_push_trimmed_field(value: Option<&str>, max_chars: usize) -> Option<String> {
    let value = value.map(str::trim).filter(|value| !value.is_empty())?;
    Some(value.chars().take(max_chars).collect::<String>())
}

fn ride_push_pickup_summary_from_trip_value(trip: &Value) -> Option<String> {
    let pickup_label = trip.get("pickup_label").and_then(Value::as_str);
    let pickup = trip.get("pickup").and_then(Value::as_str);
    ride_push_trimmed_field(pickup_label.or(pickup), 80)
}

fn ride_driver_dispatch_push_copy(pickup_summary: Option<&str>) -> (String, String) {
    let title = "New ride request".to_string();
    let body = pickup_summary
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.chars().take(120).collect::<String>())
        .unwrap_or_else(|| "Tap to view details.".to_string());
    (title, body)
}

fn ride_rider_update_push_copy(status: &str, pickup_summary: Option<&str>) -> (String, String) {
    let pickup_summary = pickup_summary
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.chars().take(120).collect::<String>());
    match status.trim() {
        "driver_assigned" => (
            "Driver assigned".to_string(),
            pickup_summary.unwrap_or_else(|| "Your driver is heading to pickup.".to_string()),
        ),
        "driver_arriving" => (
            "Driver en route".to_string(),
            pickup_summary.unwrap_or_else(|| "Your driver is on the way to pickup.".to_string()),
        ),
        "driver_arrived" => (
            "Driver arrived".to_string(),
            pickup_summary.unwrap_or_else(|| "Your driver has arrived at pickup.".to_string()),
        ),
        "trip_started" | "trip_in_progress" => (
            "Trip started".to_string(),
            "Your ride is now in progress.".to_string(),
        ),
        "trip_completed" => (
            "Trip completed".to_string(),
            "Thanks for riding with Shamell.".to_string(),
        ),
        "cancelled" => (
            "Trip cancelled".to_string(),
            "This ride was cancelled.".to_string(),
        ),
        "payment_failed" => (
            "Payment needs attention".to_string(),
            "This ride completed, but payment still needs attention.".to_string(),
        ),
        _ => (
            "Ride update".to_string(),
            pickup_summary.unwrap_or_else(|| "Your ride status changed.".to_string()),
        ),
    }
}

fn ride_driver_update_push_copy(status: &str) -> (&'static str, &'static str) {
    match status.trim() {
        "matching" => (
            "Trip returned to matching",
            "This ride was reassigned and is no longer assigned to you.",
        ),
        "cancelled" => (
            "Trip cancelled",
            "This ride was cancelled and is no longer active.",
        ),
        "trip_completed" => ("Trip completed", "This ride has been completed."),
        _ => ("Trip update", "Your active ride was updated."),
    }
}

fn ride_operator_remote_push_copy(status: &str) -> Option<(&'static str, &'static str)> {
    match status.trim() {
        "matching" => Some((
            "New dispatch waiting",
            "A ride request is waiting in matching and may require operator attention.",
        )),
        "cancelled" => Some((
            "Ride cancelled",
            "A live ride was cancelled and may need operator follow-up.",
        )),
        "payment_failed" => Some((
            "Payment failure requires review",
            "A completed trip is blocked in payment_failed and needs finance intervention.",
        )),
        _ => None,
    }
}

