fn ride_round_coordinate(value: f64, decimals: i32) -> f64 {
    let precision = decimals.clamp(0, 6);
    let factor = 10f64.powi(precision);
    (value * factor).round() / factor
}

fn ride_operator_location_json(
    lat: Option<f64>,
    lon: Option<f64>,
    allow_precise_location: bool,
    accuracy_meters: Option<i64>,
    speed_kmh: Option<i64>,
    heading_degrees: Option<i64>,
    last_location_at: Option<&str>,
) -> Option<Value> {
    let (lat, lon) = match (lat, lon) {
        (Some(lat), Some(lon)) => {
            if allow_precise_location {
                (lat, lon)
            } else {
                (ride_round_coordinate(lat, 2), ride_round_coordinate(lon, 2))
            }
        }
        _ => return None,
    };
    let mut payload = serde_json::Map::new();
    payload.insert("lat".to_string(), json!(lat));
    payload.insert("lon".to_string(), json!(lon));
    if allow_precise_location {
        if let Some(value) = accuracy_meters {
            payload.insert("accuracy_meters".to_string(), json!(value));
        }
        if let Some(value) = speed_kmh {
            payload.insert("speed_kmh".to_string(), json!(value));
        }
        if let Some(value) = heading_degrees {
            payload.insert("heading_degrees".to_string(), json!(value));
        }
        if let Some(value) = last_location_at
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            payload.insert("last_location_at".to_string(), json!(value));
        }
    }
    Some(Value::Object(payload))
}

