async fn upsert_ride_driver_presence(
    tx: &mut Transaction<'_, Postgres>,
    driver_account_id: &str,
    online: bool,
    lat: Option<f64>,
    lon: Option<f64>,
    driver_name: Option<&str>,
    car_plate: Option<&str>,
) -> ApiResult<()> {
    let availability_status = if online { "online" } else { "offline" };
    sqlx::query(
        r#"
        INSERT INTO auth_ride_driver_presence
          (
            driver_account_id,
            availability_status,
            last_seen_at,
            last_online_at,
            updated_at,
            location_lat,
            location_lon,
            driver_name,
            car_plate
          )
        VALUES
          ($1, $2, NOW(), CASE WHEN $2 = 'online' THEN NOW() ELSE NULL END, NOW(), $3, $4, $5, $6)
        ON CONFLICT (driver_account_id) DO UPDATE
          SET
            availability_status = EXCLUDED.availability_status,
            last_seen_at = NOW(),
            last_online_at = CASE
              WHEN EXCLUDED.availability_status = 'online' THEN NOW()
              ELSE auth_ride_driver_presence.last_online_at
            END,
            updated_at = NOW(),
            location_lat = EXCLUDED.location_lat,
            location_lon = EXCLUDED.location_lon,
            driver_name = COALESCE(EXCLUDED.driver_name, auth_ride_driver_presence.driver_name),
            car_plate = COALESCE(EXCLUDED.car_plate, auth_ride_driver_presence.car_plate)
        "#,
    )
    .bind(driver_account_id)
    .bind(availability_status)
    .bind(if online { lat } else { None })
    .bind(if online { lon } else { None })
    .bind(driver_name)
    .bind(car_plate)
    .execute(&mut **tx)
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(driver_account_id),
            "ride driver presence upsert failed"
        );
        ApiError::internal("ride driver presence unavailable")
    })?;
    Ok(())
}

async fn expire_stale_ride_driver_presence_in_tx(
    tx: &mut Transaction<'_, Postgres>,
    driver_account_id: Option<&str>,
) -> ApiResult<Vec<String>> {
    let stale_driver_account_ids = sqlx::query_scalar::<_, String>(
        r#"
        UPDATE auth_ride_driver_presence
        SET
          availability_status = 'offline',
          updated_at = NOW()
        WHERE availability_status = 'online'
          AND last_seen_at < NOW() - ($1 * INTERVAL '1 second')
          AND ($2::text IS NULL OR driver_account_id = $2)
        RETURNING driver_account_id
        "#,
    )
    .bind(RIDE_DRIVER_PRESENCE_STALE_SECS)
    .bind(driver_account_id)
    .fetch_all(&mut **tx)
    .await
    .map_err(|error| {
        if let Some(driver_account_id) = driver_account_id {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                "ride driver presence stale expiry failed"
            );
        } else {
            tracing::error!(%error, "ride driver presence stale expiry failed");
        }
        ApiError::internal("ride driver presence unavailable")
    })?;

    for stale_driver_account_id in &stale_driver_account_ids {
        cancel_pending_ride_dispatch_offers_for_driver_in_tx(
            tx,
            stale_driver_account_id,
            "driver_presence_stale",
        )
        .await?;
    }

    Ok(stale_driver_account_ids)
}

async fn expire_stale_ride_driver_presence(
    pool: &PgPool,
    driver_account_id: Option<&str>,
) -> ApiResult<Vec<String>> {
    let mut tx = pool.begin().await.map_err(|error| {
        if let Some(driver_account_id) = driver_account_id {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                "ride driver presence stale expiry tx begin failed"
            );
        } else {
            tracing::error!(%error, "ride driver presence stale expiry tx begin failed");
        }
        ApiError::internal("ride driver presence unavailable")
    })?;
    let stale_driver_account_ids =
        expire_stale_ride_driver_presence_in_tx(&mut tx, driver_account_id).await?;
    tx.commit().await.map_err(|error| {
        if let Some(driver_account_id) = driver_account_id {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                "ride driver presence stale expiry tx commit failed"
            );
        } else {
            tracing::error!(%error, "ride driver presence stale expiry tx commit failed");
        }
        ApiError::internal("ride driver presence unavailable")
    })?;
    Ok(stale_driver_account_ids)
}

async fn driver_has_active_ride_in_tx(
    tx: &mut Transaction<'_, Postgres>,
    driver_account_id: &str,
    excluding_ride_id: Option<&str>,
) -> ApiResult<bool> {
    let row = sqlx::query(
        r#"
        SELECT 1
        FROM auth_ride_trips
        WHERE driver_account_id = $1
          AND status NOT IN ('trip_completed', 'cancelled')
          AND ($2::text IS NULL OR ride_id <> $2)
        LIMIT 1
        "#,
    )
    .bind(driver_account_id)
    .bind(excluding_ride_id)
    .fetch_optional(&mut **tx)
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(driver_account_id),
            "ride driver active trip lookup failed"
        );
        ApiError::internal("ride command unavailable")
    })?;
    Ok(row.is_some())
}

async fn expire_stale_ride_dispatch_offers_in_tx(
    tx: &mut Transaction<'_, Postgres>,
    ride_id: Option<&str>,
    driver_account_id: Option<&str>,
) -> ApiResult<()> {
    sqlx::query(
        r#"
        UPDATE auth_ride_dispatch_offers
        SET
          status = 'expired',
          response_reason = COALESCE(response_reason, 'offer_expired'),
          responded_at = COALESCE(responded_at, NOW()),
          updated_at = NOW()
        WHERE status = 'pending'
          AND expires_at <= NOW()
          AND ($1::text IS NULL OR ride_id = $1)
          AND ($2::text IS NULL OR driver_account_id = $2)
        "#,
    )
    .bind(ride_id)
    .bind(driver_account_id)
    .execute(&mut **tx)
    .await
    .map_err(|error| {
        tracing::error!(%error, "ride dispatch offer expiry failed");
        ApiError::internal("ride command unavailable")
    })?;
    Ok(())
}

