pub async fn rides_driver_location_ping(
    Path(ride_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideDriverLocationPingIn>,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_driver_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let driver_account_id = principal.account_id.trim();
    if driver_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let ride_id = canonical_ride_trip_id_path(&ride_id)?;
    let lat = canonical_ride_latitude(body.lat)?;
    let lon = canonical_ride_longitude(body.lon)?;
    let accuracy_meters =
        canonical_ride_optional_small_i64(body.accuracy_meters, "accuracy_meters", 0, 5000)?;
    let speed_kmh = canonical_ride_optional_small_i64(body.speed_kmh, "speed_kmh", 0, 320)?;
    let heading_degrees =
        canonical_ride_optional_small_i64(body.heading_degrees, "heading_degrees", 0, 360)?;

    let row = sqlx::query(
        r#"
        SELECT
          rider_account_id,
          driver_name,
          car_plate,
          status
        FROM auth_ride_trips
        WHERE ride_id=$1
          AND driver_account_id=$2
          AND status NOT IN ('trip_completed', 'cancelled')
        LIMIT 1
        "#,
    )
    .bind(&ride_id)
    .bind(driver_account_id)
    .fetch_optional(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, ride_id_hash = %auth::hash_prefix(&ride_id), account_hash = %auth::hash_prefix(driver_account_id), "ride driver location lookup failed");
        ApiError::internal("ride tracking unavailable")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    let status: String = row.try_get("status").map_err(|error| {
        tracing::error!(%error, "ride driver location status decode failed");
        ApiError::internal("ride tracking unavailable")
    })?;
    let rider_account_id: String = row.try_get("rider_account_id").map_err(|error| {
        tracing::error!(%error, "ride driver location rider decode failed");
        ApiError::internal("ride tracking unavailable")
    })?;
    let driver_name: Option<String> = row.try_get("driver_name").map_err(|error| {
        tracing::error!(%error, "ride driver location driver_name decode failed");
        ApiError::internal("ride tracking unavailable")
    })?;
    let car_plate: Option<String> = row.try_get("car_plate").map_err(|error| {
        tracing::error!(%error, "ride driver location car_plate decode failed");
        ApiError::internal("ride tracking unavailable")
    })?;
    let last_location_at = now_rfc3339();

    let mut tx = auth_runtime.pool().begin().await.map_err(|error| {
        tracing::error!(%error, ride_id_hash = %auth::hash_prefix(&ride_id), account_hash = %auth::hash_prefix(driver_account_id), "ride driver location tx begin failed");
        ApiError::internal("ride tracking unavailable")
    })?;
    record_ride_tracking_event_in_tx(
        &mut tx,
        RideTrackingEvent {
            ride_id: &ride_id,
            event_kind: "driver_location",
            status: Some(status.trim()),
            actor_account_id: Some(driver_account_id),
            location_lat: Some(lat),
            location_lon: Some(lon),
            accuracy_meters,
            speed_kmh,
            heading_degrees,
            note: None,
            metadata: json!({
                "source": "driver_app",
            }),
        },
    )
    .await?;
    upsert_ride_trip_live_state_in_tx(
        &mut tx,
        RideTripLiveStateUpdate {
            ride_id: &ride_id,
            rider_account_id: rider_account_id.as_str(),
            driver_account_id: Some(driver_account_id),
            driver_name: driver_name.as_deref(),
            car_plate: car_plate.as_deref(),
            stage: status.trim(),
            driver_location: Some((lat, lon)),
            accuracy_meters,
            speed_kmh,
            heading_degrees,
            last_location_at: Some(last_location_at.as_str()),
        },
    )
    .await?;
    upsert_ride_driver_presence(
        &mut tx,
        driver_account_id,
        true,
        Some(lat),
        Some(lon),
        None,
        None,
    )
    .await?;
    tx.commit().await.map_err(|error| {
        tracing::error!(%error, ride_id_hash = %auth::hash_prefix(&ride_id), account_hash = %auth::hash_prefix(driver_account_id), "ride driver location tx commit failed");
        ApiError::internal("ride tracking unavailable")
    })?;

    Ok(json_no_store_response(json!({
        "ride_id": ride_id,
        "status": status,
        "location": {
            "lat": lat,
            "lon": lon,
            "accuracy_meters": accuracy_meters,
            "speed_kmh": speed_kmh,
            "heading_degrees": heading_degrees,
        },
        "ok": true,
    })))
}

async fn load_driver_finance_dashboard_snapshot(
    state: &AppState,
    headers: &HeaderMap,
    principal: &auth::AuthPrincipal,
) -> ApiResult<DriverFinanceDashboardSnapshot> {
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let driver_account_id = principal.account_id.trim();
    if driver_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let wallet_id = resolve_wallet_for_account_cached(
        state,
        headers,
        principal,
        driver_account_id,
        principal.phone.as_deref(),
    )
    .await?;
    let platform_payout_wallet_id = resolve_fee_wallet_id(state, headers, principal, false)
        .await
        .ok();

    let ledger_body = proxy_payments(
        state,
        Method::GET,
        &format!(
            "/wallets/{}/driver-ledger",
            escaped_path_segment(&wallet_id)
        ),
        Vec::new(),
        None,
        headers,
        H_USER_AGENT,
    )
    .await?;
    let ledger = parse_driver_ledger_from_payments(&ledger_body.0)?;
    let recent_reserve_events = match proxy_payments(
        state,
        Method::GET,
        "/driver-ride-fee-holds",
        vec![
            ("wallet_id".to_string(), wallet_id.clone()),
            ("limit".to_string(), "10".to_string()),
        ],
        None,
        headers,
        H_USER_AGENT,
    )
    .await
    {
        Ok(body) => body
            .0
            .as_array()
            .map(|items| {
                items
                    .iter()
                    .filter_map(|item| parse_driver_ride_fee_hold_from_value(item).ok())
                    .map(|item| driver_ride_fee_hold_json(&item, true))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default(),
        Err(error) => {
            tracing::warn!(
                status = %error.status,
                detail = %error.detail,
                account_hash = %auth::hash_prefix(driver_account_id),
                "driver finance hold history unavailable"
            );
            Vec::new()
        }
    };

    let stats_row = sqlx::query(
        r#"
        SELECT
          COUNT(*) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ) AS completed_today_count,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ), 0)::bigint AS completed_today_value_minor_units,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status NOT IN ('idle', 'quote_shown', 'trip_completed', 'cancelled')
          ), 0)::bigint AS active_trip_value_minor_units,
          NOW()::text AS generated_at
        FROM auth_ride_trips
        WHERE driver_account_id = $1
        "#,
    )
    .bind(driver_account_id)
    .fetch_one(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(driver_account_id),
            "driver finance stats lookup failed"
        );
        ApiError::internal("driver finance unavailable")
    })?;

    let completed_today_count: i64 =
        stats_row
            .try_get("completed_today_count")
            .map_err(|error| {
                tracing::error!(%error, "driver finance completed_today_count decode failed");
                ApiError::internal("driver finance unavailable")
            })?;
    let completed_today_value_minor_units: i64 = stats_row
        .try_get("completed_today_value_minor_units")
        .map_err(|error| {
            tracing::error!(%error, "driver finance completed_today_value decode failed");
            ApiError::internal("driver finance unavailable")
        })?;
    let active_trip_value_minor_units: i64 = stats_row
        .try_get("active_trip_value_minor_units")
        .map_err(|error| {
            tracing::error!(%error, "driver finance active_trip_value decode failed");
            ApiError::internal("driver finance unavailable")
        })?;
    let generated_at: String = stats_row.try_get("generated_at").map_err(|error| {
        tracing::error!(%error, "driver finance generated_at decode failed");
        ApiError::internal("driver finance unavailable")
    })?;

    let recent_rows = sqlx::query(
        r#"
        SELECT
          id,
          ride_id,
          rider_account_id,
          driver_account_id,
          driver_name,
          car_plate,
          pickup_text,
          destination_text,
          ride_class,
          fare_estimate_cents,
          eta_seconds,
          status,
          cancel_reason,
          created_at::text AS created_at,
          status_updated_at::text AS status_updated_at,
          updated_at::text AS updated_at,
          terminal_at::text AS terminal_at
        FROM auth_ride_trips
        WHERE driver_account_id = $1
          AND status = 'trip_completed'
        ORDER BY terminal_at DESC NULLS LAST, id DESC
        LIMIT 5
        "#,
    )
    .bind(driver_account_id)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(driver_account_id),
            "driver finance recent trips lookup failed"
        );
        ApiError::internal("driver finance unavailable")
    })?;

    let mut recent_completed_trips = Vec::with_capacity(recent_rows.len());
    for row in &recent_rows {
        recent_completed_trips.push(ride_trip_response_from_row(row)?);
    }

    let recommended_reserve_minor_units = recommended_driver_reserve_minor_units(
        completed_today_value_minor_units,
        active_trip_value_minor_units,
    );
    let reserve_gap_minor_units =
        (recommended_reserve_minor_units - ledger.held_reserve_cents).max(0);
    let pending_settlement_minor_units = ledger
        .debt_cents
        .saturating_add(ledger.cash_collected_cents)
        .saturating_add(ledger.payout_pending_cents);
    let gross_available_minor_units = ledger
        .earnings_available_cents
        .saturating_add(ledger.bonuses_cents);
    let net_available_minor_units =
        gross_available_minor_units.saturating_sub(ledger.held_reserve_cents);
    let reserve_target_minor_units = ledger
        .held_reserve_cents
        .max(recommended_reserve_minor_units);
    let recommended_payout_minor_units = gross_available_minor_units
        .saturating_sub(reserve_target_minor_units)
        .saturating_sub(pending_settlement_minor_units)
        .max(0);
    let reserve_coverage_bps = if recommended_reserve_minor_units <= 0 {
        10_000
    } else {
        ((ledger.held_reserve_cents.saturating_mul(10_000)) / recommended_reserve_minor_units)
            .clamp(0, 10_000)
    };
    let alerts = build_driver_finance_alerts(
        pending_settlement_minor_units,
        reserve_gap_minor_units,
        ledger.payout_pending_cents,
        recommended_payout_minor_units,
    );

    Ok(DriverFinanceDashboardSnapshot {
        generated_at,
        wallet_id,
        platform_payout_wallet_id,
        ledger,
        completed_today_count,
        completed_today_value_minor_units,
        active_trip_value_minor_units,
        net_available_minor_units,
        recommended_reserve_minor_units,
        recommended_payout_minor_units,
        pending_settlement_minor_units,
        reserve_coverage_bps,
        payout_blocked: recommended_payout_minor_units == 0,
        alerts,
        recent_completed_trips,
        recent_reserve_events,
    })
}

