pub async fn rides_driver_shift_summary(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_driver_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let driver_account_id = principal.account_id.trim();
    if driver_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    expire_stale_ride_driver_presence(auth_runtime.pool(), Some(driver_account_id)).await?;

    let presence_row = sqlx::query(
        r#"
        SELECT
          CASE
            WHEN availability_status = 'online'
              AND last_seen_at >= NOW() - ($2 * INTERVAL '1 second')
              THEN TRUE
            ELSE FALSE
          END AS online,
          last_seen_at::text AS last_seen_at,
          last_online_at::text AS last_online_at,
          CASE
            WHEN availability_status = 'online'
              AND last_seen_at >= NOW() - ($2 * INTERVAL '1 second')
              AND last_online_at IS NOT NULL
              THEN GREATEST(ROUND(EXTRACT(EPOCH FROM NOW() - last_online_at)), 0)::bigint
            ELSE 0::bigint
          END AS current_online_duration_seconds
        FROM auth_ride_driver_presence
        WHERE driver_account_id = $1
        "#,
    )
    .bind(driver_account_id)
    .bind(RIDE_DRIVER_PRESENCE_STALE_SECS)
    .fetch_optional(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(driver_account_id),
            "driver shift presence lookup failed"
        );
        ApiError::internal("driver shift summary unavailable")
    })?;

    let online = presence_row
        .as_ref()
        .and_then(|row| row.try_get::<bool, _>("online").ok())
        .unwrap_or(false);
    let last_seen_at = presence_row
        .as_ref()
        .and_then(|row| row.try_get::<Option<String>, _>("last_seen_at").ok())
        .flatten();
    let last_online_at = presence_row
        .as_ref()
        .and_then(|row| row.try_get::<Option<String>, _>("last_online_at").ok())
        .flatten();
    let current_online_duration_seconds = presence_row
        .as_ref()
        .and_then(|row| {
            row.try_get::<i64, _>("current_online_duration_seconds")
                .ok()
        })
        .unwrap_or(0)
        .max(0);

    let stats_row = sqlx::query(
        r#"
        SELECT
          COUNT(*) FILTER (
            WHERE status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress',
              'payment_failed'
            )
          ) AS active_trip_count,
          COUNT(*) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ) AS completed_today_count,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ), 0)::bigint AS completed_today_value_minor_units,
          COUNT(*) FILTER (
            WHERE status = 'payment_failed'
          ) AS payment_failed_count,
          COALESCE(ROUND(AVG(eta_seconds) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          )), 0)::bigint AS avg_completed_eta_seconds,
          MAX(to_char(terminal_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')) FILTER (
            WHERE status = 'trip_completed'
          ) AS last_completed_at
        FROM auth_ride_trips
        WHERE driver_account_id = $1
        "#,
    )
    .bind(driver_account_id)
    .fetch_one(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(driver_account_id),
            "driver shift stats lookup failed"
        );
        ApiError::internal("driver shift summary unavailable")
    })?;

    let active_trip_count: i64 = stats_row.try_get("active_trip_count").map_err(|error| {
        tracing::error!(%error, "driver shift active_trip_count decode failed");
        ApiError::internal("driver shift summary unavailable")
    })?;
    let completed_today_count: i64 =
        stats_row
            .try_get("completed_today_count")
            .map_err(|error| {
                tracing::error!(%error, "driver shift completed_today_count decode failed");
                ApiError::internal("driver shift summary unavailable")
            })?;
    let completed_today_value_minor_units: i64 = stats_row
        .try_get("completed_today_value_minor_units")
        .map_err(|error| {
            tracing::error!(%error, "driver shift completed_today_value decode failed");
            ApiError::internal("driver shift summary unavailable")
        })?;
    let payment_failed_count: i64 = stats_row.try_get("payment_failed_count").map_err(|error| {
        tracing::error!(%error, "driver shift payment_failed_count decode failed");
        ApiError::internal("driver shift summary unavailable")
    })?;
    let avg_completed_eta_seconds: i64 =
        stats_row
            .try_get("avg_completed_eta_seconds")
            .map_err(|error| {
                tracing::error!(%error, "driver shift avg_completed_eta decode failed");
                ApiError::internal("driver shift summary unavailable")
            })?;
    let last_completed_at: Option<String> =
        stats_row.try_get("last_completed_at").map_err(|error| {
            tracing::error!(%error, "driver shift last_completed_at decode failed");
            ApiError::internal("driver shift summary unavailable")
        })?;

    let open_dispatches_visible = if online && active_trip_count == 0 {
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT COUNT(*)
            FROM auth_ride_dispatch_offers
            WHERE driver_account_id = $1
              AND status = 'pending'
              AND expires_at > NOW()
            "#,
        )
        .bind(driver_account_id)
        .fetch_one(auth_runtime.pool())
        .await
        .map_err(|error| {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                "driver shift visible dispatch count failed"
            );
            ApiError::internal("driver shift summary unavailable")
        })?
    } else {
        0
    };

    let snapshot = DriverShiftSummarySnapshot {
        generated_at: now_rfc3339(),
        online,
        last_seen_at,
        last_online_at,
        current_online_duration_seconds,
        open_dispatches_visible,
        active_trip_count,
        completed_today_count,
        completed_today_value_minor_units,
        payment_failed_count,
        avg_completed_eta_seconds,
        last_completed_at,
        alerts: build_driver_shift_alerts(
            online,
            current_online_duration_seconds,
            open_dispatches_visible,
            payment_failed_count,
            completed_today_count,
        ),
    };

    Ok(json_no_store_response(json!({
        "generated_at": snapshot.generated_at,
        "online": snapshot.online,
        "last_seen_at": snapshot.last_seen_at,
        "last_online_at": snapshot.last_online_at,
        "current_online_duration_seconds": snapshot.current_online_duration_seconds,
        "open_dispatches_visible": snapshot.open_dispatches_visible,
        "active_trip_count": snapshot.active_trip_count,
        "completed_today_count": snapshot.completed_today_count,
        "completed_today_value_minor_units": snapshot.completed_today_value_minor_units,
        "payment_failed_count": snapshot.payment_failed_count,
        "avg_completed_eta_seconds": snapshot.avg_completed_eta_seconds,
        "last_completed_at": snapshot.last_completed_at,
        "alerts": snapshot.alerts,
    })))
}

pub async fn rides_driver_documents(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_driver_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let driver_account_id = principal.account_id.trim();
    if driver_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let rows = sqlx::query(
        r#"
        SELECT
          document_id,
          driver_account_id,
          document_type,
          document_number,
          issuing_country,
          status,
          review_note,
          to_char(expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS expires_at,
          to_char(submitted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS submitted_at,
          to_char(reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS reviewed_at
        FROM auth_ride_driver_documents
        WHERE driver_account_id = $1
        ORDER BY updated_at DESC, id DESC
        "#,
    )
    .bind(driver_account_id)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), "driver documents lookup failed");
        ApiError::internal("driver documents unavailable")
    })?;

    let mut by_type = HashMap::<String, ParsedRideDriverDocument>::new();
    for row in rows {
        let parsed = parse_ride_driver_document_row(&row)?;
        by_type
            .entry(parsed.document_type.clone())
            .or_insert(parsed);
    }
    let mut documents = Vec::new();
    for document_type in ride_required_document_types() {
        documents.push(
            by_type
                .remove(document_type)
                .unwrap_or_else(|| missing_ride_driver_document(driver_account_id, document_type)),
        );
    }

    let missing_documents = documents
        .iter()
        .filter(|doc| doc.status == "missing")
        .count() as i64;
    let pending_documents = documents
        .iter()
        .filter(|doc| doc.status == "pending")
        .count() as i64;
    let approved_documents = documents
        .iter()
        .filter(|doc| doc.status == "approved")
        .count() as i64;
    let rejected_documents = documents
        .iter()
        .filter(|doc| doc.status == "rejected")
        .count() as i64;
    let expired_documents = documents
        .iter()
        .filter(|doc| doc.status == "expired")
        .count() as i64;
    let blocking_issues =
        missing_documents + pending_documents + rejected_documents + expired_documents;

    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "driver_account_id": driver_account_id,
        "summary": {
            "missing_documents": missing_documents,
            "pending_documents": pending_documents,
            "approved_documents": approved_documents,
            "rejected_documents": rejected_documents,
            "expired_documents": expired_documents,
            "blocking_issues": blocking_issues,
            "ready_to_drive": blocking_issues == 0,
        },
        "documents": documents
            .iter()
            .map(|document| ride_driver_document_json(document, true))
            .collect::<Vec<_>>(),
    })))
}

pub async fn rides_driver_document_upsert(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideDriverDocumentUpsertIn>,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_driver_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let driver_account_id = principal.account_id.trim();
    if driver_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let document_type =
        canonical_ride_driver_document_type(body.document_type.as_deref().unwrap_or_default())
            .ok_or_else(|| ApiError::bad_request("invalid document_type"))?;
    let document_number = body
        .document_number
        .as_deref()
        .map(str::trim)
        .filter(|value| {
            let len = value.chars().count();
            (4..=RIDE_DRIVER_DOCUMENT_NUMBER_MAX_CHARS).contains(&len)
                && value
                    .chars()
                    .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '/' | '_'))
        })
        .ok_or_else(|| ApiError::bad_request("invalid document_number"))?;
    let issuing_country = body
        .issuing_country
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_ascii_uppercase());
    if let Some(country) = issuing_country.as_deref() {
        if country.len() < 2
            || country.len() > 3
            || !country.chars().all(|ch| ch.is_ascii_alphabetic())
        {
            return Err(ApiError::bad_request("invalid issuing_country"));
        }
    }
    let expires_at = body
        .expires_at
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| {
            chrono::DateTime::parse_from_rfc3339(value)
                .map_err(|_| ApiError::bad_request("invalid expires_at"))
        })
        .transpose()?;
    let expires_at_iso = expires_at
        .as_ref()
        .map(|value| value.to_rfc3339_opts(chrono::SecondsFormat::Secs, true));
    if expires_at
        .as_ref()
        .map(|value| value.timestamp() <= current_unix_timestamp_secs())
        .unwrap_or(false)
    {
        return Err(ApiError::bad_request("expires_at must be in the future"));
    }

    let row = sqlx::query(
        r#"
        INSERT INTO auth_ride_driver_documents (
          document_id,
          driver_account_id,
          document_type,
          document_number,
          issuing_country,
          expires_at,
          status,
          review_note,
          reviewer_account_id,
          submitted_at,
          reviewed_at,
          updated_at
        ) VALUES (
          $1, $2, $3, $4, $5, CAST($6 AS TIMESTAMPTZ), 'pending', NULL, NULL, NOW(), NULL, NOW()
        )
        ON CONFLICT (driver_account_id, document_type)
        DO UPDATE SET
          document_number = EXCLUDED.document_number,
          issuing_country = EXCLUDED.issuing_country,
          expires_at = EXCLUDED.expires_at,
          status = 'pending',
          review_note = NULL,
          reviewer_account_id = NULL,
          submitted_at = NOW(),
          reviewed_at = NULL,
          updated_at = NOW()
        RETURNING
          document_id,
          driver_account_id,
          document_type,
          document_number,
          issuing_country,
          status,
          review_note,
          to_char(expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS expires_at,
          to_char(submitted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS submitted_at,
          to_char(reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS reviewed_at
        "#,
    )
    .bind(new_ride_driver_document_id())
    .bind(driver_account_id)
    .bind(document_type)
    .bind(document_number)
    .bind(issuing_country)
    .bind(expires_at_iso)
    .fetch_one(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), document_type, "driver document upsert failed");
        ApiError::internal("driver documents unavailable")
    })?;

    Ok(json_no_store_response(ride_driver_document_json(
        &parse_ride_driver_document_row(&row)?,
        true,
    )))
}

pub async fn rides_driver_payout_request_create(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideDriverPayoutRequestIn>,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_driver_principal(&state, &headers).await?;
    enforce_payment_mutation_device_binding(&headers, &principal, "payments_requests_create")?;
    auth::enforce_payment_mutation_rate_limit(
        &state,
        &headers,
        &principal,
        "payments_requests_create",
    )
    .await?;

    let finance = load_driver_finance_dashboard_snapshot(&state, &headers, &principal).await?;
    if finance.ledger.payout_pending_cents > 0 {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "payout already pending",
        ));
    }
    let platform_payout_wallet_id = finance
        .platform_payout_wallet_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("platform payout wallet unavailable"))?;
    let requested_amount_minor_units = body
        .amount_minor_units
        .unwrap_or(finance.recommended_payout_minor_units);
    if requested_amount_minor_units <= 0 {
        return Err(ApiError::new(StatusCode::CONFLICT, "payout unavailable"));
    }
    if requested_amount_minor_units > finance.recommended_payout_minor_units {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "amount exceeds recommended payout",
        ));
    }

    let canonical = canonical_payments_request_create_body(
        &finance.wallet_id,
        PaymentsRequestCreateIn {
            from_wallet_id: Some(finance.wallet_id.clone()),
            to_wallet_id: Some(platform_payout_wallet_id.to_string()),
            to_alias: None,
            amount_cents: requested_amount_minor_units,
            message: Some(RIDE_DRIVER_PAYOUT_REQUEST_MESSAGE.to_string()),
            expires_in_secs: body.expires_in_secs,
        },
    )?;
    let resource_id = payment_request_create_attestation_resource_id(&canonical)?;
    auth::enforce_payment_mutation_attestation(
        &state,
        &headers,
        &principal,
        "payments_requests_create",
        &resource_id,
    )
    .await?;
    let headers = payments_headers_with_idempotency(&headers)?;

    proxy_payments_no_store(
        &state,
        Method::POST,
        "/requests",
        Vec::new(),
        Some(canonical),
        &headers,
        H_PAY_TOPUP,
    )
    .await
}

pub async fn rides_operator_finance_queue(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideOperatorFinanceQueueQuery>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    let allow_sensitive_finance_details = auth::roles_allow_ride_finance_sensitive_details(&roles);
    let fee_wallet_id = resolve_fee_wallet_id(&state, &headers, &principal, false).await?;
    let requested_limit = ride_trip_list_limit(q.limit).clamp(1, 50);
    let scan_limit = requested_limit.clamp(50, 200);
    let upstream = proxy_payments(
        &state,
        Method::GET,
        "/requests",
        vec![
            ("wallet_id".to_string(), fee_wallet_id.clone()),
            ("kind".to_string(), "incoming".to_string()),
            ("limit".to_string(), scan_limit.to_string()),
        ],
        None,
        &headers,
        H_USER_AGENT,
    )
    .await?;

    let items = upstream
        .0
        .as_array()
        .ok_or_else(|| ApiError::internal("operator finance queue unavailable"))?;
    let mut filtered = Vec::new();
    let mut pending_requests = 0i64;
    let mut pending_amount_minor_units = 0i64;
    let mut approved_requests = 0i64;
    let mut blocked_requests = 0i64;
    let mut oldest_pending_age_seconds = 0i64;
    for item in items {
        let summary = parse_payment_request_summary_from_value(item)?;
        if summary.message.as_deref() != Some(RIDE_DRIVER_PAYOUT_REQUEST_MESSAGE) {
            continue;
        }
        match summary.status.as_str() {
            "pending" => {
                pending_requests += 1;
                pending_amount_minor_units =
                    pending_amount_minor_units.saturating_add(summary.amount_minor_units);
                oldest_pending_age_seconds = oldest_pending_age_seconds.max(summary.age_seconds);
            }
            "accepted" => {
                approved_requests += 1;
            }
            "canceled" | "expired" => {
                blocked_requests += 1;
            }
            _ => {}
        }
        filtered.push(summary);
    }

    ride_sort_payment_request_summaries(&mut filtered);
    let requests = filtered
        .iter()
        .take(requested_limit as usize)
        .map(|summary| payment_request_summary_json(summary, allow_sensitive_finance_details))
        .collect::<Vec<_>>();
    let mut reserved_fee_events = 0i64;
    let mut released_fee_events = 0i64;
    let mut settled_fee_events = 0i64;
    let recent_reserve_events = match proxy_payments(
        &state,
        Method::GET,
        "/driver-ride-fee-holds",
        vec![("limit".to_string(), requested_limit.to_string())],
        None,
        &headers,
        H_USER_AGENT,
    )
    .await
    {
        Ok(body) => body
            .0
            .as_array()
            .map(|items| {
                items
                    .iter()
                    .filter_map(|item| parse_driver_ride_fee_hold_from_value(item).ok())
                    .inspect(|item| match item.status.as_str() {
                        "reserved" => reserved_fee_events += 1,
                        "released" => released_fee_events += 1,
                        "settled" => settled_fee_events += 1,
                        _ => {}
                    })
                    .map(|item| driver_ride_fee_hold_json(&item, allow_sensitive_finance_details))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default(),
        Err(error) => {
            tracing::warn!(
                status = %error.status,
                detail = %error.detail,
                "operator finance hold history unavailable"
            );
            Vec::new()
        }
    };

    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "fee_wallet_id": allow_sensitive_finance_details.then(|| fee_wallet_id.clone()),
        "totals": {
            "pending_requests": pending_requests,
            "pending_amount_minor_units": pending_amount_minor_units,
            "approved_requests": approved_requests,
            "blocked_requests": blocked_requests,
            "oldest_pending_age_seconds": oldest_pending_age_seconds,
            "reserved_fee_events": reserved_fee_events,
            "released_fee_events": released_fee_events,
            "settled_fee_events": settled_fee_events,
        },
        "requests": requests,
        "recent_reserve_events": recent_reserve_events,
    })))
}

pub async fn rides_operator_document_queue(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideOperatorDocumentQueueQuery>,
) -> ApiResult<Response> {
    let (_principal, roles) = auth::require_ride_compliance_principal(&state, &headers).await?;
    let allow_sensitive_document_details =
        auth::roles_allow_ride_document_sensitive_details(&roles);
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let status_filter = q
        .status
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| {
            canonical_ride_document_review_status(value)
                .map(str::to_string)
                .ok_or_else(|| ApiError::bad_request("invalid status filter"))
        })
        .transpose()?;
    let requested_limit = ride_trip_list_limit(q.limit).clamp(1, 50);

    let rows = sqlx::query(
        r#"
        SELECT
          document_id,
          driver_account_id,
          document_type,
          document_number,
          issuing_country,
          status,
          review_note,
          to_char(expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS expires_at,
          to_char(submitted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS submitted_at,
          to_char(reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS reviewed_at
        FROM auth_ride_driver_documents
        ORDER BY updated_at DESC, id DESC
        LIMIT 200
        "#,
    )
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, "ride operator document queue lookup failed");
        ApiError::internal("ride operator document queue unavailable")
    })?;

    let mut documents = Vec::new();
    let mut pending_documents = 0i64;
    let mut rejected_documents = 0i64;
    let mut expired_documents = 0i64;
    let mut blocked_drivers = HashSet::<String>::new();
    for row in rows {
        let parsed = parse_ride_driver_document_row(&row)?;
        let actionable = parsed.status != "approved";
        if actionable {
            blocked_drivers.insert(parsed.driver_account_id.clone());
        }
        match parsed.status.as_str() {
            "pending" => pending_documents += 1,
            "rejected" => rejected_documents += 1,
            "expired" => expired_documents += 1,
            _ => {}
        }
        let include = if let Some(expected) = status_filter.as_deref() {
            parsed.status == expected
        } else {
            actionable
        };
        if include {
            documents.push(parsed);
        }
    }
    documents.truncate(requested_limit as usize);

    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "totals": {
            "pending_documents": pending_documents,
            "rejected_documents": rejected_documents,
            "expired_documents": expired_documents,
            "blocked_drivers": blocked_drivers.len() as i64,
        },
        "documents": documents
            .iter()
            .map(|document| ride_driver_document_json(document, allow_sensitive_document_details))
            .collect::<Vec<_>>(),
    })))
}

pub async fn rides_operator_document_review(
    Path(document_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideOperatorDocumentReviewIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_compliance_principal(&state, &headers).await?;
    let allow_sensitive_document_details =
        auth::roles_allow_ride_document_sensitive_details(&roles);
    if !allow_sensitive_document_details {
        audit_ride_sensitive_mutation_event(RideSensitiveMutationAuditEvent {
            operation: "ride_operator_document_review",
            outcome: "blocked",
            actor_account_id: principal.account_id.as_str(),
            actor_roles: &roles,
            ride_id: None,
            document_id: Some(document_id.as_str()),
            request_id: None,
            subject_account_id: None,
            reason: Some("ride_compliance_sensitive_role_required"),
        });
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride compliance sensitive role required",
        ));
    }
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let normalized_document_id = document_id.trim();
    if normalized_document_id.is_empty()
        || !normalized_document_id
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_'))
    {
        return Err(ApiError::bad_request("invalid document_id"));
    }
    let decision =
        canonical_ride_document_review_decision(body.decision.as_deref().unwrap_or_default())
            .ok_or_else(|| ApiError::bad_request("invalid decision"))?;
    let note = canonical_ride_document_review_note(decision, body.note.as_deref())?;

    let existing = sqlx::query(
        r#"
        SELECT
          document_id,
          driver_account_id,
          document_type,
          document_number,
          issuing_country,
          status,
          review_note,
          to_char(expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS expires_at,
          to_char(submitted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS submitted_at,
          to_char(reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS reviewed_at
        FROM auth_ride_driver_documents
        WHERE document_id = $1
        LIMIT 1
        "#,
    )
    .bind(normalized_document_id)
    .fetch_optional(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, "ride operator document review lookup failed");
        ApiError::internal("ride driver document unavailable")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;
    let existing_parsed = parse_ride_driver_document_row(&existing)?;
    if decision == "approved" && existing_parsed.status == "expired" {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "document is expired and must be resubmitted",
        ));
    }
    let reviewer_account_id = principal.account_id.trim();
    if reviewer_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let row = sqlx::query(
        r#"
        UPDATE auth_ride_driver_documents
        SET
          status = $2,
          review_note = $3,
          reviewer_account_id = $4,
          reviewed_at = NOW(),
          updated_at = NOW()
        WHERE document_id = $1
        RETURNING
          document_id,
          driver_account_id,
          document_type,
          document_number,
          issuing_country,
          status,
          review_note,
          to_char(expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS expires_at,
          to_char(submitted_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS submitted_at,
          to_char(reviewed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS reviewed_at
        "#,
    )
    .bind(normalized_document_id)
    .bind(decision)
    .bind(note)
    .bind(reviewer_account_id)
    .fetch_optional(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(%error, document_id = normalized_document_id, "ride operator document review update failed");
        ApiError::internal("ride driver document unavailable")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;

    audit_ride_sensitive_mutation_event(RideSensitiveMutationAuditEvent {
        operation: "ride_operator_document_review",
        outcome: "success",
        actor_account_id: principal.account_id.as_str(),
        actor_roles: &roles,
        ride_id: None,
        document_id: Some(normalized_document_id),
        request_id: None,
        subject_account_id: Some(existing_parsed.driver_account_id.as_str()),
        reason: Some(decision),
    });

    Ok(json_no_store_response(ride_driver_document_json(
        &parse_ride_driver_document_row(&row)?,
        allow_sensitive_document_details,
    )))
}

pub async fn rides_operator_payout_request_approve(
    Path(rid): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let rid = required_payments_resource_path(&rid, "request_id")?;
    let (principal, roles) = auth::require_ride_finance_principal(&state, &headers).await?;
    if !auth::roles_allow_ride_finance_sensitive_details(&roles) {
        audit_ride_sensitive_mutation_event(RideSensitiveMutationAuditEvent {
            operation: "ride_operator_payout_request_approve",
            outcome: "blocked",
            actor_account_id: principal.account_id.as_str(),
            actor_roles: &roles,
            ride_id: None,
            document_id: None,
            request_id: Some(rid.as_str()),
            subject_account_id: None,
            reason: Some("ride_finance_sensitive_role_required"),
        });
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "ride finance sensitive role required",
        ));
    }
    enforce_payment_mutation_device_binding(&headers, &principal, "payments_requests_accept")?;
    auth::enforce_payment_mutation_rate_limit(
        &state,
        &headers,
        &principal,
        "payments_requests_accept",
    )
    .await?;
    let fee_wallet_id = resolve_fee_wallet_id(&state, &headers, &principal, false).await?;
    let request_detail = proxy_payments(
        &state,
        Method::GET,
        &format!("/requests/{}", escaped_path_segment(&rid)),
        vec![("wallet_id".to_string(), fee_wallet_id.clone())],
        None,
        &headers,
        H_USER_AGENT,
    )
    .await?;
    let summary = parse_payment_request_summary_from_value(&request_detail.0)?;
    if summary.to_wallet_id != fee_wallet_id
        || summary.message.as_deref() != Some(RIDE_DRIVER_PAYOUT_REQUEST_MESSAGE)
    {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    if summary.status != "pending" {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "payout request is not pending",
        ));
    }

    let resource_id = payment_request_accept_attestation_resource_id(&rid, &fee_wallet_id);
    auth::enforce_payment_mutation_attestation(
        &state,
        &headers,
        &principal,
        "payments_requests_accept",
        &resource_id,
    )
    .await?;
    let headers = payments_headers_with_idempotency(&headers)?;

    let response = proxy_payments_no_store(
        &state,
        Method::POST,
        &format!("/requests/{}/accept", escaped_path_segment(&rid)),
        Vec::new(),
        Some(json!({
            "to_wallet_id": fee_wallet_id,
        })),
        &headers,
        H_PAY_TOPUP,
    )
    .await;
    match &response {
        Ok(_) => audit_ride_sensitive_mutation_event(RideSensitiveMutationAuditEvent {
            operation: "ride_operator_payout_request_approve",
            outcome: "success",
            actor_account_id: principal.account_id.as_str(),
            actor_roles: &roles,
            ride_id: None,
            document_id: None,
            request_id: Some(rid.as_str()),
            subject_account_id: None,
            reason: Some("accepted"),
        }),
        Err(_) => audit_ride_sensitive_mutation_event(RideSensitiveMutationAuditEvent {
            operation: "ride_operator_payout_request_approve",
            outcome: "failed",
            actor_account_id: principal.account_id.as_str(),
            actor_roles: &roles,
            ride_id: None,
            document_id: None,
            request_id: Some(rid.as_str()),
            subject_account_id: None,
            reason: Some("payments_proxy_failed"),
        }),
    }
    response
}

pub async fn rides_driver_trip_accept(
    Path(ride_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideDriverAcceptIn>,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_driver_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let driver_account_id = principal.account_id.trim();
    if driver_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    auth::enforce_geo_lookup_rate_limit(&state, &headers, &principal, "ride_driver_accept").await?;
    let driver_wallet_id = resolve_wallet_for_account_cached(
        &state,
        &headers,
        &principal,
        driver_account_id,
        principal.phone.as_deref(),
    )
    .await?;
    let ride_id = canonical_ride_trip_id_path(&ride_id)?;
    let canonical = canonical_ride_trip_command_input(RideTripCommandIn {
        command: Some("assign_driver".to_string()),
        driver_account_id: Some(driver_account_id.to_string()),
        driver_name: Some(body.driver_name),
        car_plate: Some(body.car_plate),
        eta_seconds: body.eta_seconds,
        reason: None,
        cancel_reason_code: None,
    })?;
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let request_fingerprint = ride_trip_command_fingerprint(&ride_id, &canonical);

    let mut tx = auth_runtime.pool().begin().await.map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "driver accept tx begin failed");
        ApiError::internal("ride command unavailable")
    })?;
    expire_stale_ride_driver_presence_in_tx(&mut tx, Some(driver_account_id)).await?;
    let presence_row = sqlx::query(
        r#"
        SELECT 1
        FROM auth_ride_driver_presence
        WHERE driver_account_id=$1
          AND availability_status='online'
          AND last_seen_at >= NOW() - ($2 * INTERVAL '1 second')
        LIMIT 1
        FOR UPDATE
        "#,
    )
    .bind(driver_account_id)
    .bind(RIDE_DRIVER_PRESENCE_STALE_SECS)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(driver_account_id),
            "driver accept presence gate lookup failed"
        );
        ApiError::internal("ride command unavailable")
    })?;
    if presence_row.is_none() {
        return Err(ApiError::new(StatusCode::CONFLICT, "driver must be online"));
    }
    if driver_has_active_ride_in_tx(&mut tx, driver_account_id, Some(&ride_id)).await? {
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "driver already has an active ride",
        ));
    }
    expire_stale_ride_dispatch_offers_in_tx(&mut tx, Some(&ride_id), Some(driver_account_id))
        .await?;

    let row = sqlx::query(
        r#"
        SELECT
          id,
          ride_id,
          rider_account_id,
          driver_account_id,
          driver_name,
          car_plate,
          pickup_text,
          destination_text,
          ride_class,
          fare_estimate_cents,
          eta_seconds,
          status,
          cancel_reason,
          created_at::text AS created_at,
          status_updated_at::text AS status_updated_at,
          updated_at::text AS updated_at,
          terminal_at::text AS terminal_at
        FROM auth_ride_trips
        WHERE ride_id=$1
        LIMIT 1
        FOR UPDATE
        "#,
    )
    .bind(&ride_id)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "driver accept trip lookup failed");
        ApiError::internal("ride command unavailable")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;

    let existing_driver_account_id: Option<String> =
        row.try_get("driver_account_id").map_err(|error| {
            tracing::error!(%error, "driver accept driver_account_id decode failed");
            ApiError::internal("ride command unavailable")
        })?;
    let existing_driver_account_id = existing_driver_account_id
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    if let Some(existing_driver_account_id) = existing_driver_account_id.as_deref() {
        if existing_driver_account_id != driver_account_id {
            return Err(ApiError::new(
                StatusCode::CONFLICT,
                "ride already assigned to another driver",
            ));
        }
    }
    if existing_driver_account_id.is_none() {
        let offer_row = sqlx::query(
            r#"
            SELECT offer_id
            FROM auth_ride_dispatch_offers
            WHERE ride_id = $1
              AND driver_account_id = $2
              AND status = 'pending'
              AND expires_at > NOW()
            ORDER BY offered_at DESC, id DESC
            LIMIT 1
            FOR UPDATE
            "#,
        )
        .bind(&ride_id)
        .bind(driver_account_id)
        .fetch_optional(&mut *tx)
        .await
        .map_err(|error| {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                ride_id_hash = %auth::hash_prefix(&ride_id),
                "driver accept offer lookup failed"
            );
            ApiError::internal("ride command unavailable")
        })?;
        if offer_row.is_none() {
            return Err(ApiError::new(
                StatusCode::CONFLICT,
                "dispatch offer unavailable",
            ));
        }
    }
    let rider_account_id: String = row.try_get("rider_account_id").map_err(|error| {
        tracing::error!(%error, "driver accept rider_account_id decode failed");
        ApiError::internal("ride command unavailable")
    })?;
    let fare_estimate_cents =
        ride_trip_i64_column(&row, "fare_estimate_cents", "driver_accept_fare_estimate")?;
    let driver_platform_fee_cents = driver_ride_platform_fee_cents(fare_estimate_cents);

    let reserved = reserve_ride_trip_idempotency_in_tx(
        &mut tx,
        &ride_id,
        rider_account_id.as_str(),
        &idempotency_key,
        canonical.command.as_str(),
        &request_fingerprint,
    )
    .await?;
    if !reserved {
        let replay = replay_ride_trip_idempotency_in_tx(
            &mut tx,
            rider_account_id.as_str(),
            &idempotency_key,
            canonical.command.as_str(),
            &request_fingerprint,
        )
        .await?;
        let _ = tx.rollback().await;
        return Ok(json_no_store_response(replay));
    }

    if let Err(err) = mutate_driver_ride_platform_fee(
        &state,
        &headers,
        &driver_wallet_id,
        &ride_id,
        driver_platform_fee_cents,
        "reserve",
    )
    .await
    {
        let _ = tx.rollback().await;
        return Err(err);
    }

    let response = match apply_ride_trip_command_locked_in_tx(
        &mut tx,
        &row,
        &ride_id,
        rider_account_id.as_str(),
        driver_account_id,
        &idempotency_key,
        &canonical,
    )
    .await
    {
        Ok(response) => response,
        Err(err) => {
            let _ = tx.rollback().await;
            if let Some(compensation_action) = inverse_driver_ride_platform_fee_action("reserve") {
                if let Err(compensation_error) = mutate_driver_ride_platform_fee(
                    &state,
                    &headers,
                    &driver_wallet_id,
                    &ride_id,
                    driver_platform_fee_cents,
                    compensation_action,
                )
                .await
                {
                    tracing::error!(
                        error = ?compensation_error,
                        account_hash = %auth::hash_prefix(driver_account_id),
                        ride_id_hash = %auth::hash_prefix(&ride_id),
                        "driver accept fee compensation failed"
                    );
                }
            }
            return Err(err);
        }
    };
    if let Err(err) = async {
        sqlx::query(
            r#"
            UPDATE auth_ride_dispatch_offers
            SET
              status = 'accepted',
              response_reason = NULL,
              responded_at = COALESCE(responded_at, NOW()),
              updated_at = NOW()
            WHERE ride_id = $1
              AND driver_account_id = $2
              AND status = 'pending'
            "#,
        )
        .bind(&ride_id)
        .bind(driver_account_id)
        .execute(&mut *tx)
        .await
        .map_err(|error| {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                ride_id_hash = %auth::hash_prefix(&ride_id),
                "driver accept offer finalize failed"
            );
            ApiError::internal("ride command unavailable")
        })?;
        sqlx::query(
            r#"
            UPDATE auth_ride_dispatch_offers
            SET
              status = 'cancelled',
              response_reason = 'accepted_by_other_driver',
              responded_at = COALESCE(responded_at, NOW()),
              updated_at = NOW()
            WHERE ride_id = $1
              AND driver_account_id <> $2
              AND status = 'pending'
            "#,
        )
        .bind(&ride_id)
        .bind(driver_account_id)
        .execute(&mut *tx)
        .await
        .map_err(|error| {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                ride_id_hash = %auth::hash_prefix(&ride_id),
                "driver accept competing offer cancel failed"
            );
            ApiError::internal("ride command unavailable")
        })?;
        sqlx::query(
            r#"
            UPDATE auth_ride_dispatch_offers
            SET
              status = 'cancelled',
              response_reason = 'driver_became_busy',
              responded_at = COALESCE(responded_at, NOW()),
              updated_at = NOW()
            WHERE ride_id <> $1
              AND driver_account_id = $2
              AND status = 'pending'
            "#,
        )
        .bind(&ride_id)
        .bind(driver_account_id)
        .execute(&mut *tx)
        .await
        .map_err(|error| {
            tracing::error!(
                %error,
                account_hash = %auth::hash_prefix(driver_account_id),
                ride_id_hash = %auth::hash_prefix(&ride_id),
                "driver accept other offer cancel failed"
            );
            ApiError::internal("ride command unavailable")
        })?;
        Ok::<(), ApiError>(())
    }
    .await
    {
        let _ = tx.rollback().await;
        if let Some(compensation_action) = inverse_driver_ride_platform_fee_action("reserve") {
            if let Err(compensation_error) = mutate_driver_ride_platform_fee(
                &state,
                &headers,
                &driver_wallet_id,
                &ride_id,
                driver_platform_fee_cents,
                compensation_action,
            )
            .await
            {
                tracing::error!(
                    error = ?compensation_error,
                    account_hash = %auth::hash_prefix(driver_account_id),
                    ride_id_hash = %auth::hash_prefix(&ride_id),
                    "driver accept fee compensation failed"
                );
            }
        }
        return Err(err);
    }

    tx.commit().await.map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "driver accept tx commit failed");
        ApiError::internal("ride command unavailable")
    })?;

    let pickup_summary = ride_push_pickup_summary_from_trip_value(&response);
    push_ride_rider_update_best_effort(
        &state,
        rider_account_id.as_str(),
        &ride_id,
        "driver_assigned",
        pickup_summary.as_deref(),
    )
    .await;

    Ok(json_no_store_response(response))
}

pub async fn rides_driver_trip_command(
    Path(ride_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideTripCommandIn>,
) -> ApiResult<Response> {
    let (principal, _) = auth::require_ride_driver_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let driver_account_id = principal.account_id.trim();
    if driver_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    auth::enforce_geo_lookup_rate_limit(&state, &headers, &principal, "ride_driver_command")
        .await?;
    let driver_wallet_id = resolve_wallet_for_account_cached(
        &state,
        &headers,
        &principal,
        driver_account_id,
        principal.phone.as_deref(),
    )
    .await?;

    let ride_id = canonical_ride_trip_id_path(&ride_id)?;
    let canonical = canonical_ride_trip_command_input(body)?;
    if canonical.command == "assign_driver" {
        return Err(ApiError::bad_request(
            "assign_driver is only allowed on accept",
        ));
    }
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let request_fingerprint = ride_trip_command_fingerprint(&ride_id, &canonical);

    let mut tx = auth_runtime.pool().begin().await.map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "driver command tx begin failed");
        ApiError::internal("ride command unavailable")
    })?;

    let row = sqlx::query(
        r#"
        SELECT
          id,
          ride_id,
          rider_account_id,
          driver_account_id,
          driver_name,
          car_plate,
          pickup_text,
          destination_text,
          ride_class,
          fare_estimate_cents,
          eta_seconds,
          status,
          cancel_reason,
          created_at::text AS created_at,
          status_updated_at::text AS status_updated_at,
          updated_at::text AS updated_at,
          terminal_at::text AS terminal_at
        FROM auth_ride_trips
        WHERE ride_id=$1 AND driver_account_id=$2
        LIMIT 1
        FOR UPDATE
        "#,
    )
    .bind(&ride_id)
    .bind(driver_account_id)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "driver command trip lookup failed");
        ApiError::internal("ride command unavailable")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;

    let rider_account_id: String = row.try_get("rider_account_id").map_err(|error| {
        tracing::error!(%error, "driver command rider_account_id decode failed");
        ApiError::internal("ride command unavailable")
    })?;
    let fare_estimate_cents =
        ride_trip_i64_column(&row, "fare_estimate_cents", "driver_command_fare_estimate")?;
    let driver_platform_fee_cents = driver_ride_platform_fee_cents(fare_estimate_cents);
    let fee_action = match canonical.command.as_str() {
        "cancel_trip" => Some("release"),
        "complete_trip" => Some("settle"),
        _ => None,
    };
    let reserved = reserve_ride_trip_idempotency_in_tx(
        &mut tx,
        &ride_id,
        rider_account_id.as_str(),
        &idempotency_key,
        canonical.command.as_str(),
        &request_fingerprint,
    )
    .await?;
    if !reserved {
        let replay = replay_ride_trip_idempotency_in_tx(
            &mut tx,
            rider_account_id.as_str(),
            &idempotency_key,
            canonical.command.as_str(),
            &request_fingerprint,
        )
        .await?;
        let _ = tx.rollback().await;
        return Ok(json_no_store_response(replay));
    }

    if let Some(fee_action) = fee_action {
        if let Err(err) = mutate_driver_ride_platform_fee(
            &state,
            &headers,
            &driver_wallet_id,
            &ride_id,
            driver_platform_fee_cents,
            fee_action,
        )
        .await
        {
            let _ = tx.rollback().await;
            return Err(err);
        }
    }

    let response = match apply_ride_trip_command_locked_in_tx(
        &mut tx,
        &row,
        &ride_id,
        rider_account_id.as_str(),
        driver_account_id,
        &idempotency_key,
        &canonical,
    )
    .await
    {
        Ok(response) => response,
        Err(err) => {
            let _ = tx.rollback().await;
            if let Some(fee_action) = fee_action {
                if let Some(compensation_action) =
                    inverse_driver_ride_platform_fee_action(fee_action)
                {
                    if let Err(compensation_error) = mutate_driver_ride_platform_fee(
                        &state,
                        &headers,
                        &driver_wallet_id,
                        &ride_id,
                        driver_platform_fee_cents,
                        compensation_action,
                    )
                    .await
                    {
                        tracing::error!(
                            error = ?compensation_error,
                            account_hash = %auth::hash_prefix(driver_account_id),
                            ride_id_hash = %auth::hash_prefix(&ride_id),
                            fee_action,
                            "driver command fee compensation failed"
                        );
                    }
                }
            }
            return Err(err);
        }
    };

    tx.commit().await.map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(driver_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "driver command tx commit failed");
        ApiError::internal("ride command unavailable")
    })?;

    let response_status = response
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let pickup_summary = ride_push_pickup_summary_from_trip_value(&response);
    match canonical.command.as_str() {
        "mark_driver_arriving"
        | "mark_driver_arrived"
        | "start_trip"
        | "mark_in_progress"
        | "cancel_trip"
        | "complete_trip" => {
            push_ride_rider_update_best_effort(
                &state,
                rider_account_id.as_str(),
                &ride_id,
                response_status.as_str(),
                pickup_summary.as_deref(),
            )
            .await;
        }
        _ => {}
    }
    if let Some((title, body)) = ride_operator_remote_push_copy(response_status.as_str()) {
        push_ride_operator_update_best_effort(
            &state,
            &ride_id,
            response_status.as_str(),
            Some(title),
            Some(body),
            pickup_summary.as_deref(),
            None,
        )
        .await;
    }

    Ok(json_no_store_response(response))
}

pub async fn rides_driver_trip_status(
    Path(ride_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideDriverTripStatusIn>,
) -> ApiResult<Response> {
    let canonical = canonical_ride_driver_trip_status_input(body)?;
    rides_driver_trip_command(
        Path(ride_id),
        State(state),
        headers,
        axum::Json(RideTripCommandIn {
            command: Some(canonical.command),
            driver_account_id: None,
            driver_name: None,
            car_plate: None,
            eta_seconds: canonical.eta_seconds,
            reason: canonical.reason,
            cancel_reason_code: canonical.cancel_reason_code,
        }),
    )
    .await
}

pub async fn rides_operator_trip_command(
    Path(ride_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideTripCommandIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let operator_account_id = principal.account_id.trim();
    if operator_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let ride_id = canonical_ride_trip_id_path(&ride_id)?;
    let canonical = canonical_ride_trip_command_input(body)?;
    if !matches!(canonical.command.as_str(), "cancel_trip" | "reassign_trip") {
        return Err(ApiError::bad_request(
            "operator trip command currently only supports cancel_trip or reassign_trip",
        ));
    }
    let idempotency_raw = headers
        .get("Idempotency-Key")
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let idempotency_key = canonical_idempotency_key(idempotency_raw)?;
    let request_fingerprint = ride_trip_command_fingerprint(&ride_id, &canonical);

    let mut tx = auth_runtime.pool().begin().await.map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(operator_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "operator command tx begin failed");
        ApiError::internal("ride command unavailable")
    })?;

    let row = sqlx::query(
        r#"
        SELECT
          id,
          ride_id,
          rider_account_id,
          driver_account_id,
          driver_name,
          car_plate,
          pickup_text,
          destination_text,
          ride_class,
          fare_estimate_cents,
          eta_seconds,
          status,
          cancel_reason,
          created_at::text AS created_at,
          status_updated_at::text AS status_updated_at,
          updated_at::text AS updated_at,
          terminal_at::text AS terminal_at
        FROM auth_ride_trips
        WHERE ride_id=$1
        LIMIT 1
        FOR UPDATE
        "#,
    )
    .bind(&ride_id)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(operator_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "operator command trip lookup failed");
        ApiError::internal("ride command unavailable")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;

    let rider_account_id: String = row.try_get("rider_account_id").map_err(|error| {
        tracing::error!(%error, "operator command rider_account_id decode failed");
        ApiError::internal("ride command unavailable")
    })?;
    let current_driver_account_id = ride_trip_optional_text_if_present(
        &row,
        "driver_account_id",
        "operator_command_driver_account_id",
    )?;
    let fare_estimate_cents = ride_trip_i64_column(
        &row,
        "fare_estimate_cents",
        "operator_command_fare_estimate",
    )?;
    let driver_platform_fee_cents = driver_ride_platform_fee_cents(fare_estimate_cents);

    let reserved = reserve_ride_trip_idempotency_in_tx(
        &mut tx,
        &ride_id,
        rider_account_id.as_str(),
        &idempotency_key,
        canonical.command.as_str(),
        &request_fingerprint,
    )
    .await?;
    if !reserved {
        let replay = replay_ride_trip_idempotency_in_tx(
            &mut tx,
            rider_account_id.as_str(),
            &idempotency_key,
            canonical.command.as_str(),
            &request_fingerprint,
        )
        .await?;
        let _ = tx.rollback().await;
        return Ok(json_no_store_response(replay));
    }

    let response = if canonical.command == "reassign_trip" {
        operator_reassign_ride_trip_locked_in_tx(
            &mut tx,
            &row,
            &ride_id,
            rider_account_id.as_str(),
            operator_account_id,
            &idempotency_key,
            &canonical,
        )
        .await?
    } else {
        apply_ride_trip_command_locked_in_tx(
            &mut tx,
            &row,
            &ride_id,
            rider_account_id.as_str(),
            operator_account_id,
            &idempotency_key,
            &canonical,
        )
        .await?
    };
    let response_status = response
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if response_status != "matching" {
        cancel_pending_ride_dispatch_offers_for_ride_in_tx(
            &mut tx,
            &ride_id,
            "ride_no_longer_matchable",
        )
        .await?;
    }

    tx.commit().await.map_err(|error| {
        tracing::error!(%error, account_hash = %auth::hash_prefix(operator_account_id), ride_id_hash = %auth::hash_prefix(&ride_id), "operator command tx commit failed");
        ApiError::internal("ride command unavailable")
    })?;

    let response_status = response
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    let pickup_summary = ride_push_pickup_summary_from_trip_value(&response);
    if let Some(driver_account_id) = current_driver_account_id.as_deref() {
        let (title, body) = ride_driver_update_push_copy(response_status.as_str());
        push_ride_driver_update_best_effort(
            &state,
            driver_account_id,
            &ride_id,
            response_status.as_str(),
            Some(title),
            Some(body),
            pickup_summary.as_deref(),
        )
        .await;
    }
    if let Some((title, body)) = ride_operator_remote_push_copy(response_status.as_str()) {
        push_ride_operator_update_best_effort(
            &state,
            &ride_id,
            response_status.as_str(),
            Some(title),
            Some(body),
            pickup_summary.as_deref(),
            Some(operator_account_id),
        )
        .await;
    }
    if canonical.command == "reassign_trip" && response_status == "matching" {
        if let Err(error) = push_ride_dispatch_offers_for_ride_best_effort(&state, &ride_id).await {
            tracing::warn!(
                error = ?error,
                account_hash = %auth::hash_prefix(operator_account_id),
                ride_id_hash = %auth::hash_prefix(&ride_id),
                "post-reassign dispatch push failed"
            );
        }
    }

    if let Some(driver_account_id) = current_driver_account_id.as_deref() {
        match lookup_existing_wallet_id_for_account(&state, &headers, driver_account_id).await {
            Ok(Some(driver_wallet_id)) => {
                if let Err(error) = mutate_driver_ride_platform_fee(
                    &state,
                    &headers,
                    &driver_wallet_id,
                    &ride_id,
                    driver_platform_fee_cents,
                    "release",
                )
                .await
                {
                    tracing::error!(
                        error = ?error,
                        account_hash = %auth::hash_prefix(operator_account_id),
                        driver_account_hash = %auth::hash_prefix(driver_account_id),
                        ride_id_hash = %auth::hash_prefix(&ride_id),
                        "operator trip command fee release failed after commit"
                    );
                }
            }
            Ok(None) => {
                tracing::warn!(
                    account_hash = %auth::hash_prefix(operator_account_id),
                    driver_account_hash = %auth::hash_prefix(driver_account_id),
                    ride_id_hash = %auth::hash_prefix(&ride_id),
                    "operator trip command skipped fee release because driver wallet was missing"
                );
            }
            Err(error) => {
                tracing::error!(
                    error = ?error,
                    account_hash = %auth::hash_prefix(operator_account_id),
                    driver_account_hash = %auth::hash_prefix(driver_account_id),
                    ride_id_hash = %auth::hash_prefix(&ride_id),
                    "operator trip command wallet lookup failed after commit"
                );
            }
        }
    }

    audit_ride_sensitive_mutation_event(RideSensitiveMutationAuditEvent {
        operation: "ride_operator_trip_command",
        outcome: "success",
        actor_account_id: principal.account_id.as_str(),
        actor_roles: &roles,
        ride_id: Some(ride_id.as_str()),
        document_id: None,
        request_id: None,
        subject_account_id: current_driver_account_id.as_deref(),
        reason: Some(canonical.command.as_str()),
    });

    Ok(json_no_store_response(response))
}

pub async fn rides_operator_case_queue(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideOperatorCaseQueueQuery>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let limit = ride_trip_list_limit(q.limit).clamp(1, 50);
    let allow_sensitive_case_details = auth::roles_allow_ride_case_sensitive_details(&roles);

    let totals_row = sqlx::query(
        r#"
        SELECT
          COUNT(*) FILTER (
            WHERE status = 'payment_failed'
          ) AS payment_failed_cases,
          COUNT(*) FILTER (
            WHERE status IN ('ride_requested', 'matching')
              AND driver_account_id IS NULL
              AND status_updated_at <= NOW() - INTERVAL '10 minutes'
          ) AS stalled_dispatch_cases,
          COUNT(*) FILTER (
            WHERE status IN ('driver_assigned', 'driver_arriving')
              AND status_updated_at <= NOW() - INTERVAL '15 minutes'
          ) AS overdue_arrival_cases,
          COUNT(*) FILTER (
            WHERE status IN ('trip_started', 'trip_in_progress')
              AND status_updated_at <= NOW() - INTERVAL '45 minutes'
          ) AS long_running_cases,
          COUNT(*) FILTER (
            WHERE status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress'
            )
              AND driver_account_id IS NOT NULL
              AND status_updated_at <= NOW() - INTERVAL '5 minutes'
              AND NOT EXISTS (
                SELECT 1
                FROM auth_ride_trip_tracking_events events
                WHERE events.ride_id = auth_ride_trips.ride_id
                  AND events.event_kind = 'driver_location'
                  AND events.created_at >= NOW() - INTERVAL '5 minutes'
              )
          ) AS silent_tracking_cases,
          COUNT(*) FILTER (
            WHERE status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress',
              'payment_failed',
              'trip_completed'
            )
              AND (COALESCE(driver_name, '') = '' OR COALESCE(car_plate, '') = '')
          ) AS metadata_gap_cases,
          NOW()::text AS generated_at
        FROM auth_ride_trips
        "#,
    )
    .fetch_one(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator case totals lookup failed"
        );
        ApiError::internal("ride case queue unavailable")
    })?;

    let payment_failed_cases: i64 =
        totals_row
            .try_get("payment_failed_cases")
            .map_err(|error| {
                tracing::error!(%error, "ride operator payment_failed_cases decode failed");
                ApiError::internal("ride case queue unavailable")
            })?;
    let stalled_dispatch_cases: i64 =
        totals_row
            .try_get("stalled_dispatch_cases")
            .map_err(|error| {
                tracing::error!(%error, "ride operator stalled_dispatch_cases decode failed");
                ApiError::internal("ride case queue unavailable")
            })?;
    let overdue_arrival_cases: i64 =
        totals_row
            .try_get("overdue_arrival_cases")
            .map_err(|error| {
                tracing::error!(%error, "ride operator overdue_arrival_cases decode failed");
                ApiError::internal("ride case queue unavailable")
            })?;
    let long_running_cases: i64 = totals_row.try_get("long_running_cases").map_err(|error| {
        tracing::error!(%error, "ride operator long_running_cases decode failed");
        ApiError::internal("ride case queue unavailable")
    })?;
    let silent_tracking_cases: i64 =
        totals_row
            .try_get("silent_tracking_cases")
            .map_err(|error| {
                tracing::error!(%error, "ride operator silent_tracking_cases decode failed");
                ApiError::internal("ride case queue unavailable")
            })?;
    let metadata_gap_cases: i64 = totals_row.try_get("metadata_gap_cases").map_err(|error| {
        tracing::error!(%error, "ride operator metadata_gap_cases decode failed");
        ApiError::internal("ride case queue unavailable")
    })?;
    let generated_at: String = totals_row.try_get("generated_at").map_err(|error| {
        tracing::error!(%error, "ride operator case generated_at decode failed");
        ApiError::internal("ride case queue unavailable")
    })?;

    let candidate_limit = limit.saturating_mul(8).clamp(16, 400);
    let candidate_rows = sqlx::query(
        r#"
        SELECT
          id,
          ride_id,
          rider_account_id,
          driver_account_id,
          driver_name,
          car_plate,
          pickup_text,
          destination_text,
          ride_class,
          fare_estimate_cents,
          eta_seconds,
          status,
          cancel_reason,
          created_at::text AS created_at,
          status_updated_at::text AS status_updated_at,
          updated_at::text AS updated_at,
          terminal_at::text AS terminal_at,
          GREATEST(0, EXTRACT(EPOCH FROM (NOW() - status_updated_at))::bigint) AS age_seconds,
          (
            status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress'
            )
            AND driver_account_id IS NOT NULL
            AND status_updated_at <= NOW() - INTERVAL '5 minutes'
            AND NOT EXISTS (
              SELECT 1
              FROM auth_ride_trip_tracking_events events
              WHERE events.ride_id = auth_ride_trips.ride_id
                AND events.event_kind = 'driver_location'
                AND events.created_at >= NOW() - INTERVAL '5 minutes'
            )
          ) AS tracking_silent
        FROM auth_ride_trips
        WHERE status = 'payment_failed'
           OR (
                status IN ('ride_requested', 'matching')
                AND driver_account_id IS NULL
                AND status_updated_at <= NOW() - INTERVAL '10 minutes'
           )
           OR (
                status IN ('driver_assigned', 'driver_arriving')
                AND status_updated_at <= NOW() - INTERVAL '15 minutes'
           )
           OR (
                status IN ('trip_started', 'trip_in_progress')
                AND status_updated_at <= NOW() - INTERVAL '45 minutes'
           )
           OR (
                status IN (
                  'driver_assigned',
                  'driver_arriving',
                  'driver_arrived',
                  'trip_started',
                  'trip_in_progress'
                )
                AND driver_account_id IS NOT NULL
                AND status_updated_at <= NOW() - INTERVAL '5 minutes'
                AND NOT EXISTS (
                  SELECT 1
                  FROM auth_ride_trip_tracking_events events
                  WHERE events.ride_id = auth_ride_trips.ride_id
                    AND events.event_kind = 'driver_location'
                    AND events.created_at >= NOW() - INTERVAL '5 minutes'
                )
           )
           OR (
                status IN (
                  'driver_assigned',
                  'driver_arriving',
                  'driver_arrived',
                  'trip_started',
                  'trip_in_progress',
                  'payment_failed',
                  'trip_completed'
                )
                AND (COALESCE(driver_name, '') = '' OR COALESCE(car_plate, '') = '')
           )
        ORDER BY status_updated_at ASC, id ASC
        LIMIT $1
        "#,
    )
    .bind(candidate_limit)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator case candidates lookup failed"
        );
        ApiError::internal("ride case queue unavailable")
    })?;

    let mut cases = Vec::new();
    for row in &candidate_rows {
        derive_ride_operator_cases_from_row(&mut cases, row)?;
    }
    for item in &mut cases {
        let sanitized = ride_operator_case_response(item.clone(), allow_sensitive_case_details);
        *item = sanitized;
    }
    cases.sort_by(|left, right| {
        let left_severity = left
            .get("severity")
            .and_then(Value::as_str)
            .map(ride_case_severity_rank)
            .unwrap_or(0);
        let right_severity = right
            .get("severity")
            .and_then(Value::as_str)
            .map(ride_case_severity_rank)
            .unwrap_or(0);
        right_severity
            .cmp(&left_severity)
            .then_with(|| {
                right
                    .get("age_seconds")
                    .and_then(Value::as_i64)
                    .unwrap_or_default()
                    .cmp(
                        &left
                            .get("age_seconds")
                            .and_then(Value::as_i64)
                            .unwrap_or_default(),
                    )
            })
            .then_with(|| {
                left.get("case_id")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .cmp(
                        right
                            .get("case_id")
                            .and_then(Value::as_str)
                            .unwrap_or_default(),
                    )
            })
    });
    cases.truncate(limit as usize);

    let finance_cases = payment_failed_cases;
    let support_cases = stalled_dispatch_cases.saturating_add(overdue_arrival_cases);
    let compliance_cases = long_running_cases
        .saturating_add(silent_tracking_cases)
        .saturating_add(metadata_gap_cases);
    let open_cases = finance_cases
        .saturating_add(support_cases)
        .saturating_add(compliance_cases);
    let critical_cases = payment_failed_cases;
    let high_cases = stalled_dispatch_cases
        .saturating_add(overdue_arrival_cases)
        .saturating_add(long_running_cases)
        .saturating_add(silent_tracking_cases);

    Ok(json_no_store_response(json!({
        "generated_at": generated_at,
        "totals": {
            "open_cases": open_cases,
            "critical_cases": critical_cases,
            "high_cases": high_cases,
            "finance_cases": finance_cases,
            "support_cases": support_cases,
            "compliance_cases": compliance_cases,
        },
        "cases": cases,
    })))
}

pub async fn rides_operator_support_queue(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideSupportTicketsQuery>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_support_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let limit = ride_trip_list_limit(q.limit).clamp(1, 50);
    let allow_sensitive_ticket_details = auth::roles_allow_ride_support_sensitive_details(&roles);

    let totals_row = sqlx::query(
        r#"
        SELECT
          COUNT(*) FILTER (
            WHERE status = 'open'
          ) AS open_tickets,
          COUNT(*) FILTER (
            WHERE status = 'open'
              AND ticket_category IN ('safety', 'payment_issue')
          ) AS urgent_tickets,
          NOW()::text AS generated_at
        FROM auth_ride_support_tickets
        "#,
    )
    .fetch_one(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride support queue totals lookup failed"
        );
        ApiError::internal("ride support queue unavailable")
    })?;

    let open_tickets: i64 = totals_row.try_get("open_tickets").map_err(|error| {
        tracing::error!(%error, "ride support queue open_tickets decode failed");
        ApiError::internal("ride support queue unavailable")
    })?;
    let urgent_tickets: i64 = totals_row.try_get("urgent_tickets").map_err(|error| {
        tracing::error!(%error, "ride support queue urgent_tickets decode failed");
        ApiError::internal("ride support queue unavailable")
    })?;
    let generated_at: String = totals_row.try_get("generated_at").map_err(|error| {
        tracing::error!(%error, "ride support queue generated_at decode failed");
        ApiError::internal("ride support queue unavailable")
    })?;

    let rows = sqlx::query(
        r#"
        SELECT
          tickets.ticket_id,
          tickets.ride_id,
          tickets.rider_account_id,
          tickets.ticket_category,
          tickets.subject,
          tickets.body_text,
          tickets.preferred_contact,
          tickets.status,
          tickets.resolution_note,
          tickets.resolved_by_account_id,
          tickets.created_at::text AS created_at,
          tickets.updated_at::text AS updated_at,
          tickets.resolved_at::text AS resolved_at,
          trips.ride_class,
          trips.status AS trip_status,
          trips.pickup_text,
          trips.destination_text,
          trips.driver_name,
          trips.car_plate
        FROM auth_ride_support_tickets tickets
        LEFT JOIN auth_ride_trips trips
          ON trips.ride_id = tickets.ride_id
        WHERE tickets.status = 'open'
        ORDER BY
          CASE
            WHEN tickets.ticket_category IN ('safety', 'payment_issue') THEN 0
            ELSE 1
          END,
          tickets.updated_at ASC,
          tickets.id ASC
        LIMIT $1
        "#,
    )
    .bind(limit)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride support queue lookup failed"
        );
        ApiError::internal("ride support queue unavailable")
    })?;

    let mut tickets = Vec::with_capacity(rows.len());
    for row in &rows {
        tickets.push(ride_support_ticket_response(
            ride_support_ticket_response_from_row(row)?,
            allow_sensitive_ticket_details,
        ));
    }

    Ok(json_no_store_response(json!({
        "generated_at": generated_at,
        "totals": {
            "open_tickets": open_tickets,
            "urgent_tickets": urgent_tickets,
        },
        "tickets": tickets,
    })))
}

pub async fn rides_operator_support_ticket_resolve(
    Path(ticket_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<RideOperatorSupportTicketResolveIn>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_support_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let ticket_id = canonical_ride_support_ticket_id_path(&ticket_id)?;
    let operator_account_id = principal.account_id.trim();
    if operator_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let note = canonical_ride_text_field(
        body.note,
        "note",
        RIDE_SUPPORT_TICKET_RESOLUTION_NOTE_MAX_CHARS,
    )?;

    let row = sqlx::query(
        r#"
        WITH updated AS (
          UPDATE auth_ride_support_tickets
          SET
            status = 'resolved',
            resolution_note = $2,
            resolved_by_account_id = $3,
            updated_at = NOW(),
            resolved_at = NOW()
          WHERE ticket_id = $1
            AND status = 'open'
          RETURNING ticket_id
        )
        SELECT
          tickets.ticket_id,
          tickets.ride_id,
          tickets.rider_account_id,
          tickets.ticket_category,
          tickets.subject,
          tickets.body_text,
          tickets.preferred_contact,
          tickets.status,
          tickets.resolution_note,
          tickets.resolved_by_account_id,
          tickets.created_at::text AS created_at,
          tickets.updated_at::text AS updated_at,
          tickets.resolved_at::text AS resolved_at,
          trips.ride_class,
          trips.status AS trip_status,
          trips.pickup_text,
          trips.destination_text,
          trips.driver_name,
          trips.car_plate
        FROM auth_ride_support_tickets tickets
        LEFT JOIN auth_ride_trips trips
          ON trips.ride_id = tickets.ride_id
        WHERE tickets.ticket_id = (SELECT ticket_id FROM updated)
        LIMIT 1
        "#,
    )
    .bind(&ticket_id)
    .bind(&note)
    .bind(operator_account_id)
    .fetch_optional(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            ticket_id_hash = %auth::hash_prefix(&ticket_id),
            account_hash = %auth::hash_prefix(operator_account_id),
            "ride support ticket resolve failed"
        );
        ApiError::internal("ride support unavailable")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "not found"))?;

    Ok(json_no_store_response(ride_support_ticket_response(
        ride_support_ticket_response_from_row(&row)?,
        auth::roles_allow_ride_support_sensitive_details(&roles),
    )))
}

