fn ride_sort_payment_request_summaries(summaries: &mut [ParsedPaymentRequestSummary]) {
    summaries.sort_by(|left, right| {
        right
            .age_seconds
            .cmp(&left.age_seconds)
            .then_with(|| left.created_at.cmp(&right.created_at))
            .then_with(|| left.request_id.cmp(&right.request_id))
    });
}

fn mask_ride_driver_document_number(number: &str) -> Option<String> {
    let normalized = number.trim();
    if normalized.is_empty() {
        return None;
    }
    let visible_len = normalized.chars().count().min(4);
    let suffix = normalized
        .chars()
        .rev()
        .take(visible_len)
        .collect::<String>()
        .chars()
        .rev()
        .collect::<String>();
    let masked_len = normalized
        .chars()
        .count()
        .saturating_sub(visible_len)
        .max(2);
    Some(format!("{}{}", "•".repeat(masked_len), suffix))
}

fn effective_ride_driver_document_status(
    stored_status: &str,
    expires_at: Option<&str>,
) -> &'static str {
    if stored_status.eq_ignore_ascii_case("approved") {
        if let Some(expires_at) = expires_at {
            if chrono::DateTime::parse_from_rfc3339(expires_at)
                .ok()
                .map(|value| value.timestamp() <= current_unix_timestamp_secs())
                .unwrap_or(false)
            {
                return "expired";
            }
        }
    }
    match canonical_ride_document_review_status(stored_status) {
        Some("approved") => "approved",
        Some("pending") => "pending",
        Some("rejected") => "rejected",
        Some("missing") => "missing",
        Some("expired") => "expired",
        _ => "missing",
    }
}

fn ride_driver_document_json(
    doc: &ParsedRideDriverDocument,
    allow_sensitive_details: bool,
) -> Value {
    json!({
        "document_id": doc.document_id,
        "driver_account_id": allow_sensitive_details.then(|| doc.driver_account_id.clone()),
        "document_type": doc.document_type,
        "document_number_masked": doc.document_number_masked,
        "issuing_country": doc.issuing_country,
        "status": doc.status,
        "submitted_at": doc.submitted_at,
        "reviewed_at": doc.reviewed_at,
        "expires_at": doc.expires_at,
        "review_note": allow_sensitive_details.then(|| doc.review_note.clone()).flatten(),
    })
}

fn parse_ride_driver_document_row(row: &PgRow) -> ApiResult<ParsedRideDriverDocument> {
    let driver_account_id: String = row
        .try_get("driver_account_id")
        .map_err(|_| ApiError::internal("driver document unavailable"))?;
    let document_type: String = row
        .try_get("document_type")
        .map_err(|_| ApiError::internal("driver document unavailable"))?;
    let document_number: String = row
        .try_get("document_number")
        .map_err(|_| ApiError::internal("driver document unavailable"))?;
    let stored_status: String = row
        .try_get("status")
        .map_err(|_| ApiError::internal("driver document unavailable"))?;
    let expires_at: Option<String> = row.try_get("expires_at").ok().flatten();
    let status = effective_ride_driver_document_status(&stored_status, expires_at.as_deref());
    Ok(ParsedRideDriverDocument {
        document_id: row.try_get("document_id").ok().flatten(),
        driver_account_id,
        document_type,
        document_number_masked: mask_ride_driver_document_number(&document_number),
        issuing_country: row.try_get("issuing_country").ok().flatten(),
        status: status.to_string(),
        submitted_at: row.try_get("submitted_at").ok().flatten(),
        reviewed_at: row.try_get("reviewed_at").ok().flatten(),
        expires_at,
        review_note: row.try_get("review_note").ok().flatten(),
    })
}

fn ride_required_document_types() -> [&'static str; 4] {
    [
        "driver_license",
        "vehicle_registration",
        "insurance",
        "identity_card",
    ]
}

fn missing_ride_driver_document(
    driver_account_id: &str,
    document_type: &str,
) -> ParsedRideDriverDocument {
    ParsedRideDriverDocument {
        document_id: None,
        driver_account_id: driver_account_id.to_string(),
        document_type: document_type.to_string(),
        document_number_masked: None,
        issuing_country: None,
        status: "missing".to_string(),
        submitted_at: None,
        reviewed_at: None,
        expires_at: None,
        review_note: None,
    }
}

fn driver_ledger_i64(value: &Value, field: &'static str) -> ApiResult<i64> {
    value
        .get(field)
        .and_then(Value::as_i64)
        .ok_or_else(|| ApiError::internal("driver ledger unavailable"))
}

fn parse_driver_ledger_from_payments(body: &Value) -> ApiResult<ParsedDriverLedger> {
    let wallet_id = body
        .get("wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("driver ledger missing wallet_id"))?
        .to_string();
    let currency = body
        .get("currency")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| value.len() == 3)
        .ok_or_else(|| ApiError::internal("driver ledger missing currency"))?
        .to_ascii_uppercase();
    let earnings_available_cents = driver_ledger_i64(body, "earnings_available_cents")?;
    let held_reserve_cents = driver_ledger_i64(body, "held_reserve_cents")?;
    let debt_cents = driver_ledger_i64(body, "debt_cents")?;
    let payout_pending_cents = driver_ledger_i64(body, "payout_pending_cents")?;
    let bonuses_cents = driver_ledger_i64(body, "bonuses_cents")?;
    let cash_collected_cents = driver_ledger_i64(body, "cash_collected_cents")?;
    if earnings_available_cents < 0
        || held_reserve_cents < 0
        || debt_cents < 0
        || payout_pending_cents < 0
        || bonuses_cents < 0
        || cash_collected_cents < 0
    {
        return Err(ApiError::internal("driver ledger invariant violated"));
    }
    Ok(ParsedDriverLedger {
        wallet_id,
        currency,
        earnings_available_cents,
        held_reserve_cents,
        debt_cents,
        payout_pending_cents,
        bonuses_cents,
        cash_collected_cents,
    })
}

fn recommended_driver_reserve_minor_units(
    completed_today_value_minor_units: i64,
    active_trip_value_minor_units: i64,
) -> i64 {
    let basis = completed_today_value_minor_units
        .max(active_trip_value_minor_units)
        .max(5_000);
    round_div_i64(basis.saturating_mul(1_000), 10_000).clamp(500, 50_000)
}

fn build_driver_finance_alerts(
    pending_settlement_minor_units: i64,
    reserve_gap_minor_units: i64,
    payout_pending_minor_units: i64,
    recommended_payout_minor_units: i64,
) -> Vec<Value> {
    let mut alerts = Vec::new();
    if pending_settlement_minor_units > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "driver_pending_settlement",
            "high",
            "Cash or debt settlement required",
            format!(
                "{pending_settlement_minor_units} SYP must settle before the next payout window."
            ),
        );
    }
    if reserve_gap_minor_units > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "driver_reserve_gap",
            "medium",
            "Reserve buffer is below recommendation",
            format!(
                "Increase reserve by at least {reserve_gap_minor_units} SYP to protect active trip exposure."
            ),
        );
    }
    if payout_pending_minor_units > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "driver_payout_pending",
            "info",
            "A payout is already pending",
            format!("{payout_pending_minor_units} SYP is already queued for payout settlement."),
        );
    }
    if recommended_payout_minor_units == 0
        && (pending_settlement_minor_units > 0 || reserve_gap_minor_units > 0)
    {
        push_ride_operator_alert(
            &mut alerts,
            "driver_payout_blocked",
            "high",
            "Payout is temporarily blocked",
            "Resolve settlement exposure or restore the reserve buffer before cashing out.",
        );
    }
    alerts
}

fn build_driver_shift_alerts(
    online: bool,
    current_online_duration_seconds: i64,
    open_dispatches_visible: i64,
    payment_failed_count: i64,
    completed_today_count: i64,
) -> Vec<Value> {
    let mut alerts = Vec::new();
    if payment_failed_count > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "driver_shift_payment_failures",
            "high",
            "A completed fare still needs payment recovery",
            format!(
                "{payment_failed_count} rides are still blocked in payment_failed and may delay payout settlement."
            ),
        );
    }
    if online && current_online_duration_seconds >= 10 * 60 * 60 {
        push_ride_operator_alert(
            &mut alerts,
            "driver_shift_long_online",
            if current_online_duration_seconds >= 12 * 60 * 60 {
                "high"
            } else {
                "medium"
            },
            "Driver session has been online for a long time",
            format!(
                "You have been online for {} minutes. Consider taking a break or going offline briefly.",
                current_online_duration_seconds / 60
            ),
        );
    }
    if online && completed_today_count == 0 && open_dispatches_visible == 0 {
        push_ride_operator_alert(
            &mut alerts,
            "driver_shift_low_demand",
            "info",
            "No open dispatches are visible right now",
            "The live queue is currently empty for this driver session.".to_string(),
        );
    }
    alerts
}

fn parsed_payment_request_status(raw: &str) -> Option<&'static str> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "pending" => Some("pending"),
        "accepted" => Some("accepted"),
        "canceled" => Some("canceled"),
        "expired" => Some("expired"),
        _ => None,
    }
}

fn parse_payment_request_summary_from_value(
    item: &Value,
) -> ApiResult<ParsedPaymentRequestSummary> {
    let request_id = item
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("payment request missing id"))?
        .to_string();
    let from_wallet_id = item
        .get("from_wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("payment request missing from_wallet_id"))?
        .to_string();
    let to_wallet_id = item
        .get("to_wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("payment request missing to_wallet_id"))?
        .to_string();
    let amount_minor_units = item
        .get("amount_cents")
        .or_else(|| item.get("amount_minor_units"))
        .and_then(Value::as_i64)
        .ok_or_else(|| ApiError::internal("payment request missing amount"))?;
    let currency = item
        .get("currency")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| value.len() == 3)
        .ok_or_else(|| ApiError::internal("payment request missing currency"))?
        .to_ascii_uppercase();
    let status = item
        .get("status")
        .and_then(Value::as_str)
        .and_then(parsed_payment_request_status)
        .ok_or_else(|| ApiError::internal("payment request missing status"))?
        .to_string();
    let created_at = item
        .get("created_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("payment request missing created_at"))?
        .to_string();
    let created_at_parsed = chrono::DateTime::parse_from_rfc3339(&created_at)
        .map_err(|_| ApiError::internal("payment request created_at invalid"))?;
    let created_at_epoch = created_at_parsed.timestamp();
    let age_seconds = current_unix_timestamp_secs()
        .saturating_sub(created_at_epoch)
        .max(0);
    let message = item
        .get("message")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    if amount_minor_units <= 0 {
        return Err(ApiError::internal("payment request amount invalid"));
    }
    Ok(ParsedPaymentRequestSummary {
        request_id,
        from_wallet_id,
        to_wallet_id,
        amount_minor_units,
        currency,
        message,
        status,
        created_at,
        age_seconds,
    })
}

fn payment_request_summary_json(
    summary: &ParsedPaymentRequestSummary,
    allow_sensitive_details: bool,
) -> Value {
    json!({
        "request_id": allow_sensitive_details.then(|| summary.request_id.clone()),
        "from_wallet_id": allow_sensitive_details.then(|| summary.from_wallet_id.clone()),
        "to_wallet_id": allow_sensitive_details.then(|| summary.to_wallet_id.clone()),
        "amount_minor_units": summary.amount_minor_units,
        "currency": summary.currency,
        "message": summary.message,
        "status": summary.status,
        "created_at": summary.created_at,
        "age_seconds": summary.age_seconds,
    })
}

fn parsed_driver_ride_fee_hold_status(raw: &str) -> Option<&'static str> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "reserved" => Some("reserved"),
        "released" => Some("released"),
        "settled" => Some("settled"),
        _ => None,
    }
}

fn parse_driver_ride_fee_hold_from_value(item: &Value) -> ApiResult<ParsedDriverRideFeeHold> {
    let ride_id = item
        .get("ride_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("driver ride fee hold missing ride_id"))?
        .to_string();
    let wallet_id = item
        .get("wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::internal("driver ride fee hold missing wallet_id"))?
        .to_string();
    let amount_minor_units = item
        .get("amount_cents")
        .or_else(|| item.get("amount_minor_units"))
        .and_then(Value::as_i64)
        .ok_or_else(|| ApiError::internal("driver ride fee hold missing amount"))?;
    if amount_minor_units <= 0 {
        return Err(ApiError::internal("driver ride fee hold amount invalid"));
    }
    let status = item
        .get("status")
        .and_then(Value::as_str)
        .and_then(parsed_driver_ride_fee_hold_status)
        .ok_or_else(|| ApiError::internal("driver ride fee hold missing status"))?
        .to_string();
    let created_at = item
        .get("created_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let updated_at = item
        .get("updated_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let reserved_at = item
        .get("reserved_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let released_at = item
        .get("released_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    let settled_at = item
        .get("settled_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string);
    Ok(ParsedDriverRideFeeHold {
        ride_id,
        wallet_id,
        amount_minor_units,
        status,
        created_at,
        updated_at,
        reserved_at,
        released_at,
        settled_at,
    })
}

fn driver_ride_fee_hold_json(
    hold: &ParsedDriverRideFeeHold,
    allow_sensitive_details: bool,
) -> Value {
    json!({
        "ride_id": hold.ride_id,
        "wallet_id": allow_sensitive_details.then(|| hold.wallet_id.clone()),
        "amount_minor_units": hold.amount_minor_units,
        "status": hold.status,
        "created_at": hold.created_at,
        "updated_at": hold.updated_at,
        "reserved_at": hold.reserved_at,
        "released_at": hold.released_at,
        "settled_at": hold.settled_at,
    })
}

fn ride_case_severity_rank(severity: &str) -> i32 {
    match severity {
        "critical" => 4,
        "high" => 3,
        "medium" => 2,
        _ => 1,
    }
}

struct RideOperatorCasePayload<'a> {
    trip: &'a Value,
    case_code: &'static str,
    category: &'static str,
    severity: &'static str,
    title: &'static str,
    detail: String,
    suggested_action: &'static str,
    age_seconds: i64,
}

fn push_ride_operator_case(cases: &mut Vec<Value>, payload: RideOperatorCasePayload<'_>) {
    let RideOperatorCasePayload {
        trip,
        case_code,
        category,
        severity,
        title,
        detail,
        suggested_action,
        age_seconds,
    } = payload;
    let ride_id = trip
        .get("ride_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    cases.push(json!({
        "case_id": format!("{ride_id}:{case_code}"),
        "category": category,
        "severity": severity,
        "title": title,
        "detail": detail,
        "suggested_action": suggested_action,
        "ride_id": ride_id,
        "ride_class": trip.get("ride_class").cloned().unwrap_or(Value::Null),
        "status": trip.get("status").cloned().unwrap_or(Value::Null),
        "pickup": trip.get("pickup").cloned().unwrap_or(Value::Null),
        "destination": trip.get("destination").cloned().unwrap_or(Value::Null),
        "driver_name": trip.get("driver_name").cloned().unwrap_or(Value::Null),
        "car_plate": trip.get("car_plate").cloned().unwrap_or(Value::Null),
        "fare_estimate_minor_units": trip.get("fare_estimate_cents").cloned().unwrap_or(Value::Null),
        "age_seconds": age_seconds.max(0),
        "created_at": trip.get("created_at").cloned().unwrap_or(Value::Null),
        "last_updated_at": trip.get("last_updated_at").cloned().unwrap_or(Value::Null),
    }));
}

fn derive_ride_operator_cases_from_row(
    cases: &mut Vec<Value>,
    row: &sqlx::postgres::PgRow,
) -> ApiResult<()> {
    let trip = ride_trip_response_from_row(row)?;
    let status = trip
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let age_seconds = ride_trip_i64_column(row, "age_seconds", "ride_case_age_seconds")?;
    let driver_account_id: Option<String> = row.try_get("driver_account_id").map_err(|error| {
        tracing::error!(%error, "ride case driver_account_id decode failed");
        ApiError::internal("ride case queue unavailable")
    })?;
    let driver_name_raw: Option<String> = row.try_get("driver_name").map_err(|error| {
        tracing::error!(%error, "ride case driver_name decode failed");
        ApiError::internal("ride case queue unavailable")
    })?;
    let car_plate_raw: Option<String> = row.try_get("car_plate").map_err(|error| {
        tracing::error!(%error, "ride case car_plate decode failed");
        ApiError::internal("ride case queue unavailable")
    })?;
    let driver_assigned = driver_account_id
        .as_deref()
        .map(str::trim)
        .is_some_and(|value| !value.is_empty());
    let missing_driver_metadata = driver_name_raw
        .as_deref()
        .map(str::trim)
        .is_none_or(|value| value.is_empty())
        || car_plate_raw
            .as_deref()
            .map(str::trim)
            .is_none_or(|value| value.is_empty());
    let tracking_silent: bool = row.try_get("tracking_silent").unwrap_or(false);

    if status == "payment_failed" {
        push_ride_operator_case(
            cases,
            RideOperatorCasePayload {
                trip: &trip,
                case_code: "payment_failed",
                category: "finance",
                severity: "critical",
                title: "Payment failed after trip completion",
                detail: "The ride is blocked in payment_failed and needs finance intervention."
                    .to_string(),
                suggested_action: "Retry collection or move the trip into manual settlement.",
                age_seconds,
            },
        );
    }
    if matches!(status, "ride_requested" | "matching") && !driver_assigned && age_seconds >= 600 {
        push_ride_operator_case(
            cases,
            RideOperatorCasePayload {
                trip: &trip,
                case_code: "stalled_dispatch",
                category: "support",
                severity: "high",
                title: "Dispatch waited too long without assignment",
                detail: format!(
                    "This rider request has been open for {} seconds without a driver assignment.",
                    age_seconds
                ),
                suggested_action: "Rebalance nearby supply or escalate to driver operations.",
                age_seconds,
            },
        );
    }
    if matches!(status, "driver_assigned" | "driver_arriving") && age_seconds >= 900 {
        push_ride_operator_case(
            cases,
            RideOperatorCasePayload {
                trip: &trip,
                case_code: "overdue_arrival",
                category: "support",
                severity: "high",
                title: "Assigned driver is late to pickup",
                detail: format!(
                    "The ride has remained in an arrival state for {} seconds.",
                    age_seconds
                ),
                suggested_action: "Contact rider and driver, then reassign if needed.",
                age_seconds,
            },
        );
    }
    if matches!(status, "trip_started" | "trip_in_progress") && age_seconds >= 2_700 {
        push_ride_operator_case(
            cases,
            RideOperatorCasePayload {
                trip: &trip,
                case_code: "long_running_trip",
                category: "compliance",
                severity: "high",
                title: "Trip duration exceeds the expected window",
                detail: format!(
                    "The trip has stayed active for {} seconds since the last status change.",
                    age_seconds
                ),
                suggested_action: "Check tracking, contact both parties, and verify trip safety.",
                age_seconds,
            },
        );
    }
    if tracking_silent {
        push_ride_operator_case(
            cases,
            RideOperatorCasePayload {
                trip: &trip,
                case_code: "tracking_silent",
                category: "compliance",
                severity: "high",
                title: "Driver tracking went silent",
                detail: "The ride is in a driver-bound active state but no recent driver location ping was received in the last 5 minutes.".to_string(),
                suggested_action: "Contact the driver, verify device health, and confirm rider safety.",
                age_seconds,
            },
        );
    }
    if missing_driver_metadata
        && matches!(
            status,
            "driver_assigned"
                | "driver_arriving"
                | "driver_arrived"
                | "trip_started"
                | "trip_in_progress"
                | "payment_failed"
                | "trip_completed"
        )
    {
        push_ride_operator_case(
            cases,
            RideOperatorCasePayload {
                trip: &trip,
                case_code: "driver_metadata_gap",
                category: "compliance",
                severity: "medium",
                title: "Driver identity metadata is incomplete",
                detail: "The ride entered a driver-bound state without complete driver_name and car_plate data.".to_string(),
                suggested_action: "Repair the missing driver profile fields and keep an audit note.",
                age_seconds,
            },
        );
    }
    Ok(())
}

struct RideOperatorSummaryMetrics {
    open_dispatches: i64,
    active_trips: i64,
    payment_failures: i64,
    stalled_dispatches: i64,
    overdue_arrivals: i64,
    long_running_trips: i64,
    silent_tracking_trips: i64,
    online_drivers: i64,
    active_driver_count: i64,
    idle_online_drivers: i64,
    capacity_gap_dispatches: i64,
    metadata_gaps: i64,
}

const RIDE_OPERATOR_DRIVER_UTILIZATION_HIGH_THRESHOLD_BPS: i64 = 8_000;

fn build_ride_operator_summary_alerts(metrics: RideOperatorSummaryMetrics) -> Vec<Value> {
    let RideOperatorSummaryMetrics {
        open_dispatches,
        active_trips,
        payment_failures,
        stalled_dispatches,
        overdue_arrivals,
        long_running_trips,
        silent_tracking_trips,
        online_drivers,
        active_driver_count,
        idle_online_drivers,
        capacity_gap_dispatches,
        metadata_gaps,
    } = metrics;
    let mut alerts = Vec::new();
    if payment_failures > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "payment_failures",
            "critical",
            "Payment failures require intervention",
            format!("{payment_failures} rides are currently blocked in payment_failed."),
        );
    }
    if stalled_dispatches > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "stalled_dispatches",
            if stalled_dispatches >= 5 {
                "high"
            } else {
                "medium"
            },
            "Dispatch backlog is aging",
            format!(
                "{stalled_dispatches} open ride requests have been waiting more than 10 minutes."
            ),
        );
    }
    if overdue_arrivals > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "overdue_arrivals",
            "medium",
            "Assigned drivers are late to pickup",
            format!(
                "{overdue_arrivals} assigned rides have been stuck in arrival states for more than 15 minutes."
            ),
        );
    }
    if long_running_trips > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "long_running_trips",
            "medium",
            "Trips require operator review",
            format!(
                "{long_running_trips} active rides have been in progress for longer than 45 minutes."
            ),
        );
    }
    if silent_tracking_trips > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "silent_tracking_trips",
            "high",
            "Driver tracking has gone silent",
            format!(
                "{silent_tracking_trips} active rides have no recent driver location ping in the last 5 minutes."
            ),
        );
    }
    if open_dispatches > 0 && online_drivers <= 0 {
        push_ride_operator_alert(
            &mut alerts,
            "no_online_drivers",
            "critical",
            "No drivers are online for open dispatches",
            format!(
                "{open_dispatches} open ride requests are waiting while no drivers have a fresh online heartbeat."
            ),
        );
    }
    if capacity_gap_dispatches > 0 && online_drivers > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "dispatch_capacity_gap",
            if capacity_gap_dispatches >= 3 {
                "high"
            } else {
                "medium"
            },
            "Idle driver capacity is below dispatch demand",
            format!(
                "{capacity_gap_dispatches} open ride requests exceed the {idle_online_drivers} currently idle online drivers."
            ),
        );
    }
    if online_drivers >= 4
        && open_dispatches > 0
        && active_driver_count.saturating_mul(10_000)
            >= online_drivers.saturating_mul(RIDE_OPERATOR_DRIVER_UTILIZATION_HIGH_THRESHOLD_BPS)
    {
        push_ride_operator_alert(
            &mut alerts,
            "driver_utilization_high",
            "medium",
            "Online driver pool is close to saturation",
            format!(
                "{active_driver_count} of {online_drivers} online drivers are already on live trips while {open_dispatches} dispatches remain open."
            ),
        );
    }
    if metadata_gaps > 0 {
        push_ride_operator_alert(
            &mut alerts,
            "driver_metadata_gaps",
            "high",
            "Driver metadata is missing on live trips",
            format!(
                "{metadata_gaps} rides are in driver-bound states without both driver_name and car_plate."
            ),
        );
    }
    if open_dispatches >= 8 && open_dispatches > active_trips.saturating_mul(2) {
        push_ride_operator_alert(
            &mut alerts,
            "capacity_pressure",
            "medium",
            "Dispatch demand exceeds live capacity",
            format!(
                "{open_dispatches} open ride requests are competing with {active_trips} active trips and only {idle_online_drivers} idle online drivers."
            ),
        );
    }
    alerts
}

pub async fn rides_operator_live_board(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideOperatorLiveBoardQuery>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let open_limit = ride_trip_list_limit(q.open_limit);
    let active_limit = ride_trip_list_limit(q.active_limit);
    let allow_precise_trip_location = auth::roles_allow_ride_compliance(&roles);

    expire_stale_ride_driver_presence(auth_runtime.pool(), None).await?;

    let counts_row = sqlx::query(
        r#"
        SELECT
          COUNT(*) FILTER (
            WHERE status IN ('ride_requested', 'matching')
              AND driver_account_id IS NULL
          ) AS open_dispatches,
          COUNT(*) FILTER (
            WHERE status NOT IN ('idle', 'quote_shown', 'trip_completed', 'cancelled')
          ) AS active_trips,
          COUNT(*) FILTER (
            WHERE status IN ('driver_assigned', 'driver_arriving', 'driver_arrived')
          ) AS en_route_trips,
          COUNT(*) FILTER (
            WHERE status IN ('trip_started', 'trip_in_progress')
          ) AS in_progress_trips,
          COUNT(*) FILTER (
            WHERE status = 'payment_failed'
          ) AS payment_failures,
          COUNT(DISTINCT driver_account_id) FILTER (
            WHERE status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress',
              'payment_failed'
            )
              AND driver_account_id IS NOT NULL
          ) AS active_driver_count,
          (
            SELECT COUNT(*)
            FROM auth_ride_driver_presence presence
            WHERE presence.availability_status = 'online'
              AND presence.last_seen_at >= NOW() - ($1 * INTERVAL '1 second')
          ) AS online_drivers,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status IN ('ride_requested', 'matching')
              AND driver_account_id IS NULL
          ), 0)::bigint AS open_dispatch_value_minor_units,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status NOT IN ('idle', 'quote_shown', 'trip_completed', 'cancelled')
          ), 0)::bigint AS active_trip_value_minor_units,
          COUNT(*) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ) AS completed_today_count,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ), 0)::bigint AS completed_today_value_minor_units,
          COALESCE(ROUND(AVG(eta_seconds) FILTER (
            WHERE status IN ('ride_requested', 'matching')
              AND driver_account_id IS NULL
          )), 0)::bigint AS avg_open_eta_seconds,
          COALESCE(ROUND(AVG(eta_seconds) FILTER (
            WHERE status NOT IN ('idle', 'quote_shown', 'trip_completed', 'cancelled')
          )), 0)::bigint AS avg_active_eta_seconds,
          COUNT(*) FILTER (
            WHERE status IN ('ride_requested', 'matching')
              AND driver_account_id IS NULL
              AND status_updated_at <= NOW() - INTERVAL '10 minutes'
          ) AS stalled_dispatches,
          COUNT(*) FILTER (
            WHERE status IN ('driver_assigned', 'driver_arriving')
              AND status_updated_at <= NOW() - INTERVAL '15 minutes'
          ) AS overdue_arrivals,
          COUNT(*) FILTER (
            WHERE status IN ('trip_started', 'trip_in_progress')
              AND status_updated_at <= NOW() - INTERVAL '45 minutes'
          ) AS long_running_trips,
          COUNT(*) FILTER (
            WHERE status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress'
            )
              AND driver_account_id IS NOT NULL
              AND status_updated_at <= NOW() - INTERVAL '5 minutes'
              AND NOT EXISTS (
                SELECT 1
                FROM auth_ride_trip_tracking_events events
                WHERE events.ride_id = auth_ride_trips.ride_id
                  AND events.event_kind = 'driver_location'
                  AND events.created_at >= NOW() - INTERVAL '5 minutes'
              )
          ) AS silent_tracking_trips,
          COUNT(*) FILTER (
            WHERE status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress',
              'payment_failed',
              'trip_completed'
            )
              AND (COALESCE(driver_name, '') = '' OR COALESCE(car_plate, '') = '')
          ) AS metadata_gaps,
          NOW()::text AS generated_at
        FROM auth_ride_trips
        "#,
    )
    .bind(RIDE_DRIVER_PRESENCE_STALE_SECS)
    .fetch_one(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator counts lookup failed"
        );
        ApiError::internal("ride live board unavailable")
    })?;

    let open_rows = sqlx::query(
        r#"
        SELECT
          id,
          ride_id,
          rider_account_id,
          driver_account_id,
          driver_name,
          car_plate,
          pickup_text,
          destination_text,
          ride_class,
          fare_estimate_cents,
          eta_seconds,
          status,
          cancel_reason,
          created_at::text AS created_at,
          status_updated_at::text AS status_updated_at,
          updated_at::text AS updated_at,
          terminal_at::text AS terminal_at
        FROM auth_ride_trips
        WHERE status IN ('ride_requested', 'matching')
          AND driver_account_id IS NULL
        ORDER BY status_updated_at DESC, id DESC
        LIMIT $1
        "#,
    )
    .bind(open_limit)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator open board lookup failed"
        );
        ApiError::internal("ride live board unavailable")
    })?;

    let active_rows = sqlx::query(
        r#"
        SELECT
          id,
          ride_id,
          rider_account_id,
          driver_account_id,
          driver_name,
          car_plate,
          pickup_text,
          destination_text,
          ride_class,
          fare_estimate_cents,
          eta_seconds,
          status,
          cancel_reason,
          created_at::text AS created_at,
          status_updated_at::text AS status_updated_at,
          updated_at::text AS updated_at,
          terminal_at::text AS terminal_at
        FROM auth_ride_trips
        WHERE status NOT IN ('idle', 'quote_shown', 'trip_completed', 'cancelled')
        ORDER BY status_updated_at DESC, id DESC
        LIMIT $1
        "#,
    )
    .bind(active_limit)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator active board lookup failed"
        );
        ApiError::internal("ride live board unavailable")
    })?;

    let mut open_items = Vec::with_capacity(open_rows.len());
    for row in &open_rows {
        open_items.push(ride_operator_trip_response(
            ride_trip_response_from_row(row)?,
            allow_precise_trip_location,
        ));
    }

    let mut active_items = Vec::with_capacity(active_rows.len());
    for row in &active_rows {
        active_items.push(ride_operator_trip_response(
            ride_trip_response_from_row(row)?,
            allow_precise_trip_location,
        ));
    }

    let open_dispatches: i64 = counts_row.try_get("open_dispatches").map_err(|error| {
        tracing::error!(%error, "ride operator open_dispatches decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let active_trips: i64 = counts_row.try_get("active_trips").map_err(|error| {
        tracing::error!(%error, "ride operator active_trips decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let en_route_trips: i64 = counts_row.try_get("en_route_trips").map_err(|error| {
        tracing::error!(%error, "ride operator en_route_trips decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let in_progress_trips: i64 = counts_row.try_get("in_progress_trips").map_err(|error| {
        tracing::error!(%error, "ride operator in_progress_trips decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let payment_failures: i64 = counts_row.try_get("payment_failures").map_err(|error| {
        tracing::error!(%error, "ride operator payment_failures decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let active_driver_count: i64 = counts_row.try_get("active_driver_count").map_err(|error| {
        tracing::error!(%error, "ride operator active_driver_count decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let online_drivers: i64 = counts_row.try_get("online_drivers").map_err(|error| {
        tracing::error!(%error, "ride operator online_drivers decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let idle_online_drivers = online_drivers.saturating_sub(active_driver_count);
    let capacity_gap_dispatches = open_dispatches.saturating_sub(idle_online_drivers);
    let driver_utilization_bps = if online_drivers > 0 {
        active_driver_count.saturating_mul(10_000) / online_drivers
    } else if active_driver_count > 0 {
        10_000
    } else {
        0
    };
    let open_dispatch_value_minor_units: i64 = counts_row
        .try_get("open_dispatch_value_minor_units")
        .map_err(|error| {
            tracing::error!(%error, "ride operator open_dispatch_value decode failed");
            ApiError::internal("ride live board unavailable")
        })?;
    let active_trip_value_minor_units: i64 = counts_row
        .try_get("active_trip_value_minor_units")
        .map_err(|error| {
            tracing::error!(%error, "ride operator active_trip_value decode failed");
            ApiError::internal("ride live board unavailable")
        })?;
    let completed_today_count: i64 =
        counts_row
            .try_get("completed_today_count")
            .map_err(|error| {
                tracing::error!(%error, "ride operator completed_today_count decode failed");
                ApiError::internal("ride live board unavailable")
            })?;
    let completed_today_value_minor_units: i64 = counts_row
        .try_get("completed_today_value_minor_units")
        .map_err(|error| {
            tracing::error!(%error, "ride operator completed_today_value decode failed");
            ApiError::internal("ride live board unavailable")
        })?;
    let avg_open_eta_seconds: i64 =
        counts_row
            .try_get("avg_open_eta_seconds")
            .map_err(|error| {
                tracing::error!(%error, "ride operator avg_open_eta decode failed");
                ApiError::internal("ride live board unavailable")
            })?;
    let avg_active_eta_seconds: i64 =
        counts_row
            .try_get("avg_active_eta_seconds")
            .map_err(|error| {
                tracing::error!(%error, "ride operator avg_active_eta decode failed");
                ApiError::internal("ride live board unavailable")
            })?;
    let stalled_dispatches: i64 = counts_row.try_get("stalled_dispatches").map_err(|error| {
        tracing::error!(%error, "ride operator stalled_dispatches decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let overdue_arrivals: i64 = counts_row.try_get("overdue_arrivals").map_err(|error| {
        tracing::error!(%error, "ride operator overdue_arrivals decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let long_running_trips: i64 = counts_row.try_get("long_running_trips").map_err(|error| {
        tracing::error!(%error, "ride operator long_running_trips decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let silent_tracking_trips: i64 =
        counts_row
            .try_get("silent_tracking_trips")
            .map_err(|error| {
                tracing::error!(%error, "ride operator silent_tracking_trips decode failed");
                ApiError::internal("ride live board unavailable")
            })?;
    let metadata_gaps: i64 = counts_row.try_get("metadata_gaps").map_err(|error| {
        tracing::error!(%error, "ride operator metadata_gaps decode failed");
        ApiError::internal("ride live board unavailable")
    })?;
    let generated_at: String = counts_row.try_get("generated_at").map_err(|error| {
        tracing::error!(%error, "ride operator generated_at decode failed");
        ApiError::internal("ride live board unavailable")
    })?;

    let class_rows = sqlx::query(
        r#"
        SELECT
          ride_class,
          COUNT(*) FILTER (
            WHERE status IN ('ride_requested', 'matching')
              AND driver_account_id IS NULL
          ) AS open_dispatches,
          COUNT(*) FILTER (
            WHERE status NOT IN ('idle', 'quote_shown', 'trip_completed', 'cancelled')
          ) AS active_trips,
          COUNT(*) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ) AS completed_today_count,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status IN ('ride_requested', 'matching')
              AND driver_account_id IS NULL
          ), 0)::bigint AS open_dispatch_value_minor_units,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status NOT IN ('idle', 'quote_shown', 'trip_completed', 'cancelled')
          ), 0)::bigint AS active_trip_value_minor_units,
          COALESCE(SUM(fare_estimate_cents) FILTER (
            WHERE status = 'trip_completed'
              AND terminal_at >= NOW() - INTERVAL '24 hours'
          ), 0)::bigint AS completed_today_value_minor_units
        FROM auth_ride_trips
        GROUP BY ride_class
        ORDER BY completed_today_value_minor_units DESC, active_trip_value_minor_units DESC, ride_class ASC
        "#,
    )
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator class summary lookup failed"
        );
        ApiError::internal("ride live board unavailable")
    })?;

    let mut class_breakdown = Vec::with_capacity(class_rows.len());
    for row in &class_rows {
        let ride_class: String = row.try_get("ride_class").map_err(|error| {
            tracing::error!(%error, "ride operator ride_class decode failed");
            ApiError::internal("ride live board unavailable")
        })?;
        let open_dispatches_for_class: i64 = row.try_get("open_dispatches").map_err(|error| {
            tracing::error!(%error, "ride operator class open_dispatches decode failed");
            ApiError::internal("ride live board unavailable")
        })?;
        let active_trips_for_class: i64 = row.try_get("active_trips").map_err(|error| {
            tracing::error!(%error, "ride operator class active_trips decode failed");
            ApiError::internal("ride live board unavailable")
        })?;
        let completed_today_count_for_class: i64 =
            row.try_get("completed_today_count").map_err(|error| {
                tracing::error!(%error, "ride operator class completed_today_count decode failed");
                ApiError::internal("ride live board unavailable")
            })?;
        let open_dispatch_value_for_class: i64 = row
            .try_get("open_dispatch_value_minor_units")
            .map_err(|error| {
                tracing::error!(
                    %error,
                    "ride operator class open_dispatch_value decode failed"
                );
                ApiError::internal("ride live board unavailable")
            })?;
        let active_trip_value_for_class: i64 = row
            .try_get("active_trip_value_minor_units")
            .map_err(|error| {
                tracing::error!(%error, "ride operator class active_trip_value decode failed");
                ApiError::internal("ride live board unavailable")
            })?;
        let completed_today_value_for_class: i64 = row
            .try_get("completed_today_value_minor_units")
            .map_err(|error| {
                tracing::error!(
                    %error,
                    "ride operator class completed_today_value decode failed"
                );
                ApiError::internal("ride live board unavailable")
            })?;
        class_breakdown.push(json!({
            "ride_class": ride_class,
            "open_dispatches": open_dispatches_for_class,
            "active_trips": active_trips_for_class,
            "completed_today_count": completed_today_count_for_class,
            "open_dispatch_value_minor_units": open_dispatch_value_for_class,
            "active_trip_value_minor_units": active_trip_value_for_class,
            "completed_today_value_minor_units": completed_today_value_for_class,
        }));
    }

    let alerts = build_ride_operator_summary_alerts(RideOperatorSummaryMetrics {
        open_dispatches,
        active_trips,
        payment_failures,
        stalled_dispatches,
        overdue_arrivals,
        long_running_trips,
        silent_tracking_trips,
        online_drivers,
        active_driver_count,
        idle_online_drivers,
        capacity_gap_dispatches,
        metadata_gaps,
    });

    Ok(json_no_store_response(json!({
        "counts": {
            "open_dispatches": open_dispatches,
            "active_trips": active_trips,
            "en_route_trips": en_route_trips,
            "in_progress_trips": in_progress_trips,
            "payment_failures": payment_failures,
            "online_drivers": online_drivers,
        },
        "summary": {
            "generated_at": generated_at,
            "open_dispatch_value_minor_units": open_dispatch_value_minor_units,
            "active_trip_value_minor_units": active_trip_value_minor_units,
            "completed_today_count": completed_today_count,
            "completed_today_value_minor_units": completed_today_value_minor_units,
            "avg_open_eta_seconds": avg_open_eta_seconds,
            "avg_active_eta_seconds": avg_active_eta_seconds,
            "active_driver_count": active_driver_count,
            "idle_online_drivers": idle_online_drivers,
            "driver_utilization_bps": driver_utilization_bps,
            "capacity_gap_dispatches": capacity_gap_dispatches,
            "stalled_dispatches": stalled_dispatches,
            "overdue_arrivals": overdue_arrivals,
            "long_running_trips": long_running_trips,
            "silent_tracking_trips": silent_tracking_trips,
            "metadata_gaps": metadata_gaps,
            "class_breakdown": class_breakdown,
            "alerts": alerts,
        },
        "open_dispatches": open_items,
        "active_trips": active_items,
    })))
}

pub async fn rides_operator_driver_roster(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideOperatorDriverRosterQuery>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let allow_precise_location = auth::roles_allow_ride_compliance(&roles);
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let limit = ride_trip_list_limit(q.limit).clamp(1, 50);
    expire_stale_ride_driver_presence(auth_runtime.pool(), None).await?;
    let rows = sqlx::query(
        r#"
        SELECT
          presence.driver_account_id,
          CASE
            WHEN presence.availability_status = 'online'
              AND presence.last_seen_at >= NOW() - ($1 * INTERVAL '1 second')
              THEN 'online'
            ELSE 'offline'
          END AS availability_status,
          presence.last_seen_at::text AS last_seen_at,
          presence.last_online_at::text AS last_online_at,
          presence.updated_at::text AS updated_at,
          presence.location_lat,
          presence.location_lon,
          COALESCE(NULLIF(presence.driver_name, ''), NULLIF(active.driver_name, ''), NULLIF(profile.driver_name, '')) AS driver_name,
          COALESCE(NULLIF(presence.car_plate, ''), NULLIF(active.car_plate, ''), NULLIF(profile.car_plate, '')) AS car_plate,
          active.ride_id AS active_ride_id,
          active.status AS active_trip_status,
          active.pickup_text AS active_pickup,
          active.destination_text AS active_destination
        FROM auth_ride_driver_presence presence
        LEFT JOIN LATERAL (
          SELECT
            ride_id,
            status,
            pickup_text,
            destination_text,
            driver_name,
            car_plate
          FROM auth_ride_trips trip
          WHERE trip.driver_account_id = presence.driver_account_id
            AND trip.status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress',
              'payment_failed'
            )
          ORDER BY trip.status_updated_at DESC, trip.id DESC
          LIMIT 1
        ) active ON TRUE
        LEFT JOIN LATERAL (
          SELECT
            driver_name,
            car_plate
          FROM auth_ride_trips trip
          WHERE trip.driver_account_id = presence.driver_account_id
            AND (COALESCE(trip.driver_name, '') <> '' OR COALESCE(trip.car_plate, '') <> '')
          ORDER BY trip.status_updated_at DESC, trip.id DESC
          LIMIT 1
        ) profile ON TRUE
        WHERE presence.updated_at >= NOW() - INTERVAL '24 hours'
        ORDER BY
          CASE
            WHEN presence.availability_status = 'online'
              AND presence.last_seen_at >= NOW() - ($1 * INTERVAL '1 second')
              THEN 0
            ELSE 1
          END ASC,
          CASE WHEN active.ride_id IS NULL THEN 0 ELSE 1 END ASC,
          presence.last_seen_at DESC,
          presence.driver_account_id ASC
        LIMIT $2
        "#,
    )
    .bind(RIDE_DRIVER_PRESENCE_STALE_SECS)
    .bind(limit)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator driver roster lookup failed"
        );
        ApiError::internal("ride driver roster unavailable")
    })?;

    let mut drivers = Vec::with_capacity(rows.len());
    for row in &rows {
        drivers.push(ride_operator_driver_roster_entry_from_row(
            row,
            allow_precise_location,
        )?);
    }

    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "drivers": drivers,
    })))
}

pub async fn rides_operator_fleet_live(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideOperatorDriverRosterQuery>,
) -> ApiResult<Response> {
    let (principal, roles) = auth::require_ride_operator_principal(&state, &headers).await?;
    let allow_precise_location = auth::roles_allow_ride_compliance(&roles);
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let limit = ride_trip_list_limit(q.limit).clamp(1, 100);
    expire_stale_ride_driver_presence(auth_runtime.pool(), None).await?;
    let rows = sqlx::query(
        r#"
        SELECT
          presence.driver_account_id,
          'online'::text AS availability_status,
          presence.last_seen_at::text AS last_seen_at,
          presence.last_online_at::text AS last_online_at,
          presence.updated_at::text AS updated_at,
          COALESCE(live.driver_location_lat, presence.location_lat) AS location_lat,
          COALESCE(live.driver_location_lon, presence.location_lon) AS location_lon,
          live.accuracy_meters,
          live.speed_kmh,
          live.heading_degrees,
          live.last_location_at::text AS live_last_location_at,
          COALESCE(NULLIF(live.driver_name, ''), NULLIF(presence.driver_name, ''), NULLIF(active.driver_name, ''), NULLIF(profile.driver_name, '')) AS driver_name,
          COALESCE(NULLIF(live.car_plate, ''), NULLIF(presence.car_plate, ''), NULLIF(active.car_plate, ''), NULLIF(profile.car_plate, '')) AS car_plate,
          active.ride_id AS active_ride_id,
          COALESCE(live.stage, active.status) AS active_trip_status,
          active.pickup_text AS active_pickup,
          active.destination_text AS active_destination
        FROM auth_ride_driver_presence presence
        LEFT JOIN LATERAL (
          SELECT
            ride_id,
            status,
            pickup_text,
            destination_text,
            driver_name,
            car_plate
          FROM auth_ride_trips trip
          WHERE trip.driver_account_id = presence.driver_account_id
            AND trip.status IN (
              'driver_assigned',
              'driver_arriving',
              'driver_arrived',
              'trip_started',
              'trip_in_progress',
              'payment_failed'
            )
          ORDER BY trip.status_updated_at DESC, trip.id DESC
          LIMIT 1
        ) active ON TRUE
        LEFT JOIN auth_ride_trip_live_state live
          ON live.ride_id = active.ride_id
        LEFT JOIN LATERAL (
          SELECT
            driver_name,
            car_plate
          FROM auth_ride_trips trip
          WHERE trip.driver_account_id = presence.driver_account_id
            AND (COALESCE(trip.driver_name, '') <> '' OR COALESCE(trip.car_plate, '') <> '')
          ORDER BY trip.status_updated_at DESC, trip.id DESC
          LIMIT 1
        ) profile ON TRUE
        WHERE presence.availability_status = 'online'
          AND presence.last_seen_at >= NOW() - ($1 * INTERVAL '1 second')
        ORDER BY
          CASE WHEN active.ride_id IS NULL THEN 1 ELSE 0 END ASC,
          COALESCE(live.last_location_at, presence.last_seen_at) DESC,
          presence.driver_account_id ASC
        LIMIT $2
        "#,
    )
    .bind(RIDE_DRIVER_PRESENCE_STALE_SECS)
    .bind(limit)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            %error,
            account_hash = %auth::hash_prefix(principal.account_id.trim()),
            "ride operator fleet live lookup failed"
        );
        ApiError::internal("ride fleet live unavailable")
    })?;

    let mut drivers = Vec::with_capacity(rows.len());
    let mut tracking_online_drivers = 0i64;
    let mut active_trip_drivers = 0i64;
    for row in &rows {
        let driver = ride_operator_fleet_live_entry_from_row(row, allow_precise_location)?;
        if driver.get("location").is_some_and(|value| !value.is_null()) {
            tracking_online_drivers += 1;
        }
        if driver
            .get("active_ride_id")
            .is_some_and(|value| !value.is_null())
        {
            active_trip_drivers += 1;
        }
        drivers.push(driver);
    }

    Ok(json_no_store_response(json!({
        "generated_at": now_rfc3339(),
        "online_drivers": drivers.len() as i64,
        "tracking_online_drivers": tracking_online_drivers,
        "active_trip_drivers": active_trip_drivers,
        "drivers": drivers,
    })))
}

pub async fn rides_route(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideRouteQuery>,
) -> ApiResult<Response> {
    let principal = auth::require_session_principal(&state, &headers).await?;
    validate_finite_lat_lon(q.from_lat, q.from_lon)?;
    validate_finite_lat_lon(q.to_lat, q.to_lon)?;

    auth::enforce_geo_lookup_rate_limit(&state, &headers, &principal, "ride_route").await?;

    let path = format!(
        "/routing/1/calculateRoute/{:.6},{:.6}:{:.6},{:.6}/json",
        round_tomtom_coordinate(q.from_lat),
        round_tomtom_coordinate(q.from_lon),
        round_tomtom_coordinate(q.to_lat),
        round_tomtom_coordinate(q.to_lon),
    );
    let query_params = vec![
        ("traffic", "true".to_string()),
        ("travelMode", "car".to_string()),
        ("routeType", "fastest".to_string()),
        ("language", sanitize_tomtom_language(&headers).to_string()),
    ];
    let payload = fetch_tomtom_json(&state, &path, &query_params, 20).await?;
    let sanitized = sanitize_tomtom_route_payload(&payload)
        .ok_or_else(|| ApiError::internal("ride route unavailable"))?;
    Ok(json_no_store_response(sanitized))
}

pub async fn rides_traffic(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<RideTrafficQuery>,
) -> ApiResult<Response> {
    let principal = auth::require_session_principal(&state, &headers).await?;
    validate_finite_lat_lon(q.lat, q.lon)?;

    auth::enforce_geo_lookup_rate_limit(&state, &headers, &principal, "ride_traffic").await?;

    let radius_m = q.radius_m.unwrap_or(2_000).clamp(
        TOMTOM_TRAFFIC_RADIUS_MIN_METERS,
        TOMTOM_TRAFFIC_RADIUS_MAX_METERS,
    );
    let zoom = if radius_m <= 500 {
        14
    } else if radius_m <= 1_500 {
        13
    } else if radius_m <= 3_500 {
        12
    } else {
        11
    };
    let point = format!(
        "{:.6},{:.6}",
        round_tomtom_coordinate(q.lat),
        round_tomtom_coordinate(q.lon)
    );
    let path = format!("/traffic/services/4/flowSegmentData/absolute/{zoom}/json");
    let query_params = vec![
        ("point", point),
        ("unit", "KMPH".to_string()),
        ("openLr", "false".to_string()),
    ];
    let payload = fetch_tomtom_json(&state, &path, &query_params, 20).await?;
    let sanitized = sanitize_tomtom_flow_segment_payload(&payload, radius_m)
        .ok_or_else(|| ApiError::internal("ride traffic unavailable"))?;
    Ok(json_no_store_response(sanitized))
}

pub async fn chat_register(
    State(state): State<AppState>,
    headers: HeaderMap,
    axum::Json(body): axum::Json<ChatRegisterIn>,
) -> ApiResult<Response> {
    let (body, register_device_id, client_device_id) = canonical_chat_register_payload(body)?;
    let principal = if state.auth.is_some() {
        Some(auth::require_session_principal(&state, &headers).await?)
    } else {
        None
    };
    auth::enforce_chat_register_rate_limit(&state, &headers, Some(&register_device_id)).await?;
    if let Some(principal) = principal.as_ref() {
        auth::ensure_chat_device_binding_allowed(
            &state,
            principal,
            &register_device_id,
            client_device_id.as_deref(),
        )
        .await?;
    }
    let out = proxy_chat(
        &state,
        Method::POST,
        "/devices/register",
        Vec::new(),
        Some(body),
        &headers,
        H_CHAT_AUTH,
    )
    .await?;
    if let Some(principal) = principal.as_ref() {
        if let Err(err) = auth::bind_chat_device_to_principal(
            &state,
            principal,
            &register_device_id,
            client_device_id.as_deref(),
        )
        .await
        {
            if chat_register_should_defer_bind_error(&err) {
                let redacted_detail = auth::redact_sensitive_upstream_error_detail(&err.detail);
                tracing::warn!(
                    security_event = "chat_device_bind_deferred",
                    outcome = "allowed",
                    account_hash = %auth::hash_prefix(principal.account_id.trim()),
                    chat_device_id_hash = %auth::hash_prefix(&register_device_id),
                    status = %err.status,
                    detail = %redacted_detail,
                    "chat register upstream succeeded; deferring recoverable auth-side device bind failure"
                );
                return Ok(json_no_store_response(out.0));
            }
            return Err(err);
        }
    }
    Ok(json_no_store_response(out.0))
}

fn chat_register_should_defer_bind_error(err: &ApiError) -> bool {
    err.status.is_server_error()
}

