pub async fn chat_inbox(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<ChatInboxQuery>,
) -> ApiResult<Response> {
    let device_id = required_chat_device_query(q.device_id.as_deref())?;
    let has_since = q
        .since_iso
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .is_some()
        || q.since_id
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .is_some();
    let has_before = q
        .before_created_at
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .is_some()
        || q.before_id
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .is_some();
    if has_since && has_before {
        return Err(ApiError::bad_request(
            "since_iso/since_id and before_created_at/before_id cannot be combined",
        ));
    }
    let mut query = vec![("device_id".to_string(), device_id)];
    push_since_cursor_query(&mut query, q.since_iso.as_deref(), q.since_id.as_deref())?;
    push_before_cursor_query(
        &mut query,
        q.before_created_at.as_deref(),
        q.before_id.as_deref(),
    )?;
    push_limit_query(&mut query, "limit", q.limit, 50, 1, 200);

    let out = proxy_chat(
        &state,
        Method::GET,
        "/messages/inbox",
        query,
        None,
        &headers,
        H_CHAT_AUTH,
    )
    .await?;
    Ok(json_no_store_response(out.0))
}

pub async fn chat_thread(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<ChatThreadQuery>,
) -> ApiResult<Response> {
    let device_id = required_chat_device_query(q.device_id.as_deref())?;
    let peer_id = required_chat_peer_query(q.peer_id.as_deref())?;
    let mut query = vec![
        ("device_id".to_string(), device_id),
        ("peer_id".to_string(), peer_id),
    ];
    push_before_cursor_query(
        &mut query,
        q.before_created_at.as_deref(),
        q.before_id.as_deref(),
    )?;
    push_limit_query(&mut query, "limit", q.limit, 50, 1, 200);
    // Best practice: never allow clients to downgrade sealed-sender views.
    query.push(("sealed_view".to_string(), "true".to_string()));

    let out = proxy_chat(
        &state,
        Method::GET,
        "/messages/thread",
        query,
        None,
        &headers,
        H_CHAT_AUTH,
    )
    .await?;
    Ok(json_no_store_response(out.0))
}

pub async fn chat_stream(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<ChatStreamQuery>,
) -> ApiResult<Response> {
    let device_id = required_chat_device_query(q.device_id.as_deref())?;
    let mut query = vec![("device_id".to_string(), device_id)];
    push_since_cursor_query(&mut query, q.since_iso.as_deref(), q.since_id.as_deref())?;
    push_limit_query(&mut query, "limit", q.limit, 50, 1, 200);
    // Best practice: never allow clients to downgrade sealed-sender views.
    query.push(("sealed_view".to_string(), "true".to_string()));

    proxy_chat_stream(&state, "/messages/stream", query, &headers, H_CHAT_AUTH).await
}

#[derive(Debug, Deserialize)]
pub struct WsDeviceQuery {
    device_id: Option<String>,
}

fn header_text(headers: &HeaderMap, name: header::HeaderName) -> Option<&str> {
    headers
        .get(name)?
        .to_str()
        .ok()
        .map(str::trim)
        .filter(|v| !v.is_empty())
}

fn has_cookie_session(headers: &HeaderMap, accept_legacy_session_cookie: bool) -> bool {
    let Some(raw) = header_text(headers, header::COOKIE) else {
        return false;
    };
    raw.split(';').map(str::trim).any(|part| {
        part.strip_prefix(SESSION_COOKIE_NAME)
            .or_else(|| {
                if accept_legacy_session_cookie {
                    part.strip_prefix(LEGACY_SESSION_COOKIE_NAME)
                } else {
                    None
                }
            })
            .and_then(|tail| tail.strip_prefix('='))
            .map(str::trim)
            .is_some_and(|value| !value.is_empty())
    })
}

fn normalize_origin(raw: &str) -> Option<String> {
    let value = raw.trim();
    if value.is_empty() || value.eq_ignore_ascii_case("null") {
        return None;
    }
    let url = reqwest::Url::parse(value).ok()?;
    let scheme = url.scheme().to_ascii_lowercase();
    if !matches!(scheme.as_str(), "http" | "https") {
        return None;
    }
    let host = url.host_str()?.trim().to_ascii_lowercase();
    if host.is_empty() {
        return None;
    }
    if scheme == "http" && !matches!(host.as_str(), "localhost" | "127.0.0.1" | "::1") {
        // Fail closed: browser origins for cookie-authenticated sessions must
        // be HTTPS except explicit local-dev loopback hosts.
        return None;
    }
    Some(match url.port() {
        Some(port) => format!("{scheme}://{host}:{port}"),
        None => format!("{scheme}://{host}"),
    })
}

fn parse_host_authority(raw: &str) -> Option<(String, Option<u16>)> {
    let authority = raw.split(',').next()?.trim();
    if authority.is_empty() {
        return None;
    }
    if let Some(host) = authority.strip_prefix('[') {
        let end = host.find(']')?;
        let host_name = host[..end].trim().to_ascii_lowercase();
        if host_name.is_empty() {
            return None;
        }
        let remainder = host[end + 1..].trim();
        let port = if remainder.is_empty() {
            None
        } else {
            remainder
                .strip_prefix(':')
                .and_then(|value| value.parse::<u16>().ok())
        };
        return Some((host_name, port));
    }

    if let Some((host, port_raw)) = authority.rsplit_once(':') {
        if !host.contains(':') {
            let host = host.trim().to_ascii_lowercase();
            if host.is_empty() {
                return None;
            }
            return Some((host, port_raw.trim().parse::<u16>().ok()));
        }
    }

    let host = authority.trim().to_ascii_lowercase();
    if host.is_empty() {
        None
    } else {
        Some((host, None))
    }
}

fn origin_uses_default_port(origin: &reqwest::Url) -> bool {
    match origin.scheme() {
        "http" => origin.port().unwrap_or(80) == 80,
        "https" => origin.port().unwrap_or(443) == 443,
        _ => false,
    }
}

fn origin_matches_host(origin: &str, headers: &HeaderMap) -> bool {
    let origin = match reqwest::Url::parse(origin) {
        Ok(origin) => origin,
        Err(_) => return false,
    };
    let origin_host = origin
        .host_str()
        .map(str::trim)
        .filter(|host| !host.is_empty())
        .map(str::to_ascii_lowercase)
        .unwrap_or_default();
    if origin_host.is_empty() {
        return false;
    }
    let Some((host, host_port)) =
        parse_host_authority(header_text(headers, header::HOST).unwrap_or(""))
    else {
        return false;
    };
    if host != origin_host {
        return false;
    }
    match host_port {
        Some(port) => origin.port_or_known_default() == Some(port),
        None => origin_uses_default_port(&origin),
    }
}

fn origin_is_allowed(origin: &str, state: &AppState) -> bool {
    state.allowed_origins.iter().any(|allowed| {
        let allowed = allowed.trim();
        allowed == "*" || normalize_origin(allowed).as_deref() == Some(origin)
    })
}

fn enforce_ws_origin_for_cookie_session(
    state: &AppState,
    headers: &HeaderMap,
    route: &'static str,
) -> ApiResult<()> {
    if !has_cookie_session(headers, state.accept_legacy_session_cookie) {
        return Ok(());
    }

    let Some(origin_raw) = header_text(headers, header::ORIGIN) else {
        if header_text(
            headers,
            axum::http::header::HeaderName::from_static("sec-fetch-site"),
        )
        .is_some_and(|value| value.eq_ignore_ascii_case("cross-site"))
        {
            tracing::warn!(
                security_event = "websocket_origin_rejected",
                outcome = "blocked",
                route,
                reason = "cross_site_fetch_without_origin",
                "blocked websocket upgrade with cross-site fetch metadata and no origin"
            );
            return Err(ApiError::new(StatusCode::FORBIDDEN, "forbidden"));
        }
        return Ok(());
    };
    let Some(origin) = normalize_origin(origin_raw) else {
        tracing::warn!(
            security_event = "websocket_origin_rejected",
            outcome = "blocked",
            route,
            reason = "invalid_origin",
            "blocked websocket upgrade with invalid origin"
        );
        return Err(ApiError::new(StatusCode::FORBIDDEN, "forbidden"));
    };
    if origin_is_allowed(&origin, state) || origin_matches_host(&origin, headers) {
        return Ok(());
    }

    tracing::warn!(
        security_event = "websocket_origin_rejected",
        outcome = "blocked",
        route,
        origin,
        "blocked websocket upgrade from untrusted origin"
    );
    Err(ApiError::new(StatusCode::FORBIDDEN, "forbidden"))
}

pub async fn ws_chat_inbox(
    ws: WebSocketUpgrade,
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<WsDeviceQuery>,
) -> ApiResult<impl IntoResponse> {
    let device_id = required_chat_device_query(q.device_id.as_deref())?;
    if state.auth.is_some() {
        enforce_ws_origin_for_cookie_session(&state, &headers, "/ws/chat/inbox")?;
        let principal = auth::require_session_principal(&state, &headers).await?;
        auth::require_chat_device_owned_by_principal(&state, &principal, &device_id).await?;
        auth::enforce_ws_upgrade_rate_limit(&state, &headers, &device_id, "chat_inbox").await?;
    }
    Ok(ws.on_upgrade(move |socket| ws_chat_inbox_loop(socket, state, headers, device_id)))
}

