async fn ws_chat_inbox_loop(
    mut socket: WebSocket,
    state: AppState,
    headers: HeaderMap,
    device_id: String,
) {
    let mut primed = false;
    let mut since_cursor: Option<MessageCursor> = None;
    let mut poll_backoff = WsPollBackoff::with_jitter(
        Duration::from_secs(1),
        Duration::from_secs(12),
        stable_ws_schedule_seed("chat_inbox_poll", &device_id),
        WS_POLL_JITTER_BASIS_POINTS,
    );
    let next_poll = tokio::time::sleep(poll_backoff.next_sleep_delay());
    tokio::pin!(next_poll);

    loop {
        tokio::select! {
            inbound = socket.recv() => {
                match inbound {
                    Some(Ok(Message::Ping(payload))) => {
                        if socket.send(Message::Pong(payload)).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(Message::Close(_))) | None | Some(Err(_)) => break,
                    _ => {}
                }
            }
            _ = &mut next_poll => {
                match fetch_direct_inbox_pages(
                    &state,
                    &headers,
                    &device_id,
                    since_cursor.clone(),
                    200,
                    25,
                )
                .await
                {
                    Ok(raw_messages) => {
                        let previous_cursor = since_cursor.clone();
                        let latest_cursor = max_message_cursor(&raw_messages);
                        let messages =
                            filter_messages_after_cursor(raw_messages, previous_cursor.as_ref());
                        if let Some(last) = latest_cursor {
                            since_cursor = Some(last);
                        }
                        if !primed {
                            primed = true;
                            poll_backoff.on_idle();
                        } else if messages.is_empty() {
                            poll_backoff.on_idle();
                        } else {
                            let payload = json!({
                                "type": "inbox",
                                "messages": messages,
                            })
                            .to_string();
                            if socket.send(Message::Text(payload)).await.is_err() {
                                break;
                            }
                            poll_backoff.on_activity();
                        }
                    }
                    Err(err) => {
                        let payload = ws_error_payload(&err.detail);
                        let _ = socket.send(Message::Text(payload)).await;
                        if err.status == StatusCode::UNAUTHORIZED
                            || err.status == StatusCode::FORBIDDEN
                            || err.status == StatusCode::NOT_FOUND
                        {
                            break;
                        }
                        poll_backoff.on_error();
                    }
                };
                let next_delay = poll_backoff.next_sleep_delay();
                next_poll.as_mut().reset(Instant::now() + next_delay);
            }
        }
    }
}

async fn ws_chat_groups_loop(
    mut socket: WebSocket,
    state: AppState,
    headers: HeaderMap,
    device_id: String,
) {
    let mut group_ids: Vec<String> = Vec::new();
    let mut since_by_group: HashMap<String, MessageCursor> = HashMap::new();
    let mut primed_groups: HashSet<String> = HashSet::new();
    let mut poll_backoff = WsPollBackoff::with_jitter(
        Duration::from_secs(2),
        Duration::from_secs(20),
        stable_ws_schedule_seed("chat_groups_poll", &device_id),
        WS_POLL_JITTER_BASIS_POINTS,
    );
    let mut membership_refresh_state =
        stable_ws_schedule_seed("chat_groups_membership_refresh", &device_id);
    let next_poll = tokio::time::sleep(poll_backoff.next_sleep_delay());
    let next_group_refresh = tokio::time::sleep(Duration::ZERO);
    tokio::pin!(next_poll);
    tokio::pin!(next_group_refresh);

    loop {
        tokio::select! {
            inbound = socket.recv() => {
                match inbound {
                    Some(Ok(Message::Ping(payload))) => {
                        if socket.send(Message::Pong(payload)).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(Message::Close(_))) | None | Some(Err(_)) => break,
                    _ => {}
                }
            }
            _ = &mut next_group_refresh => {
                let list_response = proxy_chat(
                    &state,
                    Method::GET,
                    "/groups/list",
                    vec![("device_id".to_string(), device_id.clone())],
                    None,
                    &headers,
                    H_CHAT_AUTH,
                )
                .await;
                let next_group_delay = ws_next_jittered_delay(
                    Duration::from_secs(WS_GROUP_MEMBERSHIP_REFRESH_SECS),
                    &mut membership_refresh_state,
                    WS_GROUP_MEMBERSHIP_REFRESH_JITTER_MAX_MILLIS,
                );

                match list_response {
                    Ok(axum::Json(v)) => {
                        let refreshed_group_ids = extract_group_ids(&v);
                        let previous_groups: HashSet<String> =
                            group_ids.iter().cloned().collect();
                        let refreshed_group_set: HashSet<String> =
                            refreshed_group_ids.iter().cloned().collect();
                        let membership_changed = refreshed_group_set != previous_groups;
                        since_by_group.retain(|gid, _| refreshed_group_set.contains(gid));
                        primed_groups.retain(|gid| refreshed_group_set.contains(gid));
                        group_ids = refreshed_group_ids;
                        if membership_changed {
                            poll_backoff.on_activity();
                            let next_delay = poll_backoff.next_sleep_delay();
                            next_poll.as_mut().reset(Instant::now() + next_delay);
                        }
                    }
                    Err(err) => {
                        let payload = ws_error_payload(&err.detail);
                        let _ = socket.send(Message::Text(payload)).await;
                        if err.status == StatusCode::UNAUTHORIZED
                            || err.status == StatusCode::FORBIDDEN
                            || err.status == StatusCode::NOT_FOUND
                        {
                            break;
                        }
                    }
                };
                next_group_refresh
                    .as_mut()
                    .reset(Instant::now() + next_group_delay);
            }
            _ = &mut next_poll => {
                if group_ids.is_empty() {
                    poll_backoff.on_idle();
                    let next_delay = poll_backoff.next_sleep_delay();
                    next_poll.as_mut().reset(Instant::now() + next_delay);
                    continue;
                }

                let mut saw_updates = false;
                let mut saw_transient_error = false;
                let inbox_pages = match fetch_group_inbox_batch_pages(
                    &state,
                    &headers,
                    &device_id,
                    &group_ids,
                    &since_by_group,
                    200,
                    25,
                )
                .await
                {
                    Ok(items) => items,
                    Err(err) => {
                        if err.status == StatusCode::UNAUTHORIZED
                            || err.status == StatusCode::FORBIDDEN
                            || err.status == StatusCode::NOT_FOUND
                        {
                            let payload = ws_error_payload(&err.detail);
                            let _ = socket.send(Message::Text(payload)).await;
                            break;
                        }
                        saw_transient_error = true;
                        HashMap::new()
                    }
                };

                for gid in &group_ids {
                    let raw_messages = inbox_pages.get(gid).cloned().unwrap_or_default();
                    let previous_cursor = since_by_group.get(gid).cloned();
                    let latest_cursor = max_message_cursor(&raw_messages);
                    let messages =
                        filter_messages_after_cursor(raw_messages, previous_cursor.as_ref());
                    if let Some(last) = latest_cursor {
                        since_by_group.insert(gid.clone(), last);
                    }
                    let was_primed = primed_groups.contains(gid);
                    primed_groups.insert(gid.clone());
                    if !was_primed || messages.is_empty() {
                        continue;
                    }

                    let payload = json!({
                        "type": "group_inbox",
                        "group_id": gid,
                        "messages": messages,
                    })
                    .to_string();
                    if socket.send(Message::Text(payload)).await.is_err() {
                        break;
                    }
                    saw_updates = true;
                }

                if saw_updates {
                    poll_backoff.on_activity();
                } else if saw_transient_error {
                    poll_backoff.on_error();
                } else {
                    poll_backoff.on_idle();
                }
                let next_delay = poll_backoff.next_sleep_delay();
                next_poll.as_mut().reset(Instant::now() + next_delay);
            }
        }
    }
}

async fn ws_call_signaling_loop(
    mut socket: WebSocket,
    state: AppState,
    headers: HeaderMap,
    principal: Option<auth::AuthPrincipal>,
    device_id: String,
) {
    let sender = ensure_call_signal_sender(&device_id).await;
    let mut rx = sender.subscribe();
    let mut auth_revalidate = ws_revalidate_interval("call_signaling_auth", &device_id);

    loop {
        tokio::select! {
            inbound = socket.recv() => {
                match inbound {
                    Some(Ok(Message::Text(text))) => {
                        if !revalidate_ws_authenticated_chat_device(
                            &mut socket,
                            &state,
                            &headers,
                            &device_id,
                        )
                        .await
                        {
                            break;
                        }
                        if let Err(err) =
                            auth::enforce_ws_call_signaling_rate_limit(
                                &state,
                                &headers,
                                Some(&device_id),
                            )
                            .await
                        {
                            if send_ws_error(&mut socket, &err.detail).await.is_err() {
                                break;
                            }
                            continue;
                        }
                        if let Some((target, payload)) =
                            normalize_call_signal_payload(&device_id, text.as_ref())
                        {
                            if let Err(err) = require_direct_peer_signal_guardrail(
                                &state,
                                &headers,
                                &device_id,
                                principal.as_ref(),
                                &target,
                            )
                            .await
                            {
                                if send_ws_error(&mut socket, &err.detail).await.is_err() {
                                    break;
                                }
                                continue;
                            }
                            dispatch_call_signal(&target, payload.clone()).await;
                            push_call_invite_notification_best_effort(&state, &target, &payload)
                                .await;
                        }
                    }
                    Some(Ok(Message::Ping(payload))) => {
                        if socket.send(Message::Pong(payload)).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(Message::Close(_))) | None | Some(Err(_)) => break,
                    _ => {}
                }
            }
            _ = auth_revalidate.tick() => {
                if !revalidate_ws_authenticated_chat_device(
                    &mut socket,
                    &state,
                    &headers,
                    &device_id,
                )
                .await
                {
                    break;
                }
            }
            outbound = rx.recv() => {
                match outbound {
                    Ok(payload) => {
                        if socket.send(Message::Text(payload)).await.is_err() {
                            break;
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
        }
    }

    prune_call_signal_sender(&device_id).await;
}

async fn ws_chat_typing_loop(
    mut socket: WebSocket,
    state: AppState,
    headers: HeaderMap,
    principal: Option<auth::AuthPrincipal>,
    device_id: String,
) {
    let sender = ensure_chat_typing_sender(&device_id).await;
    let mut rx = sender.subscribe();
    let mut auth_revalidate = ws_revalidate_interval("chat_typing_auth", &device_id);

    loop {
        tokio::select! {
            inbound = socket.recv() => {
                match inbound {
                    Some(Ok(Message::Text(text))) => {
                        if !revalidate_ws_authenticated_chat_device(
                            &mut socket,
                            &state,
                            &headers,
                            &device_id,
                        )
                        .await
                        {
                            break;
                        }
                        if let Err(err) =
                            auth::enforce_ws_chat_typing_rate_limit(
                                &state,
                                &headers,
                                Some(&device_id),
                            )
                            .await
                        {
                            if send_ws_error(&mut socket, &err.detail).await.is_err() {
                                break;
                            }
                            continue;
                        }
                        if let Some(dispatch) =
                            normalize_typing_signal_payload(&device_id, text.as_ref())
                        {
                            match dispatch {
                                TypingDispatch::Direct {
                                    target_device_id,
                                    payload,
                                } => {
                                    if let Err(err) = require_direct_peer_signal_guardrail(
                                        &state,
                                        &headers,
                                        &device_id,
                                        principal.as_ref(),
                                        &target_device_id,
                                    )
                                    .await
                                    {
                                        if send_ws_error(&mut socket, &err.detail).await.is_err() {
                                            break;
                                        }
                                        continue;
                                    }
                                    dispatch_chat_typing(&target_device_id, payload).await;
                                }
                                TypingDispatch::Group { group_id, payload } => {
                                    let targets = resolve_group_typing_targets(
                                        &state,
                                        &headers,
                                        &group_id,
                                        &device_id,
                                    )
                                    .await;
                                    for target in targets {
                                        dispatch_chat_typing(&target, payload.clone()).await;
                                    }
                                }
                            }
                        }
                    }
                    Some(Ok(Message::Ping(payload))) => {
                        if socket.send(Message::Pong(payload)).await.is_err() {
                            break;
                        }
                    }
                    Some(Ok(Message::Close(_))) | None | Some(Err(_)) => break,
                    _ => {}
                }
            }
            _ = auth_revalidate.tick() => {
                if !revalidate_ws_authenticated_chat_device(
                    &mut socket,
                    &state,
                    &headers,
                    &device_id,
                )
                .await
                {
                    break;
                }
            }
            outbound = rx.recv() => {
                match outbound {
                    Ok(payload) => {
                        if socket.send(Message::Text(payload)).await.is_err() {
                            break;
                        }
                    }
                    Err(broadcast::error::RecvError::Lagged(_)) => continue,
                    Err(broadcast::error::RecvError::Closed) => break,
                }
            }
        }
    }

    prune_chat_typing_sender(&device_id).await;
}

async fn ensure_call_signal_sender(device_id: &str) -> broadcast::Sender<String> {
    let buses = call_signal_bus();
    if let Some(tx) = buses.read().await.get(device_id).cloned() {
        return tx;
    }
    let mut guard = buses.write().await;
    guard
        .entry(device_id.to_string())
        .or_insert_with(|| {
            let (tx, _) = broadcast::channel(256);
            tx
        })
        .clone()
}

async fn prune_call_signal_sender(device_id: &str) {
    let buses = call_signal_bus();
    let mut guard = buses.write().await;
    if guard
        .get(device_id)
        .is_some_and(|sender| sender.receiver_count() == 0)
    {
        guard.remove(device_id);
    }
}

async fn dispatch_call_signal(target_device_id: &str, payload: String) {
    let buses = call_signal_bus();
    let sender = buses.read().await.get(target_device_id).cloned();
    if let Some(tx) = sender {
        let _ = tx.send(payload);
    }
}

async fn call_signal_target_has_live_listener(target_device_id: &str) -> bool {
    let buses = call_signal_bus();
    buses
        .read()
        .await
        .get(target_device_id)
        .is_some_and(|sender| sender.receiver_count() > 0)
}

fn call_push_title_and_body(mode: &str) -> (&'static str, &'static str, &'static str) {
    match mode {
        "audio" => (
            CHAT_PUSH_TYPE_CALL_AUDIO,
            "Incoming voice call",
            "Tap to answer.",
        ),
        _ => (
            CHAT_PUSH_TYPE_CALL_VIDEO,
            "Incoming video call",
            "Tap to answer.",
        ),
    }
}

async fn push_call_invite_notification_best_effort(
    state: &AppState,
    target_device_id: &str,
    payload: &str,
) {
    if call_signal_target_has_live_listener(target_device_id).await {
        return;
    }
    let parsed = match serde_json::from_str::<Value>(payload) {
        Ok(value) => value,
        Err(error) => {
            tracing::warn!(
                error = %error,
                target_device_hash = %auth::hash_prefix(target_device_id),
                "call invite push parse failed"
            );
            return;
        }
    };
    let call_id = parsed
        .get("call_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let from_device_id = parsed
        .get("from")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let Some(call_id) = call_id else {
        return;
    };
    let Some(from_device_id) = from_device_id else {
        return;
    };
    if !is_valid_chat_device_id(target_device_id) || !is_valid_chat_device_id(from_device_id) {
        return;
    }
    let mode = parsed
        .get("mode")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or("video");
    let mode = if mode.eq_ignore_ascii_case("audio") {
        "audio"
    } else {
        "video"
    };
    let (push_type, title, body) = call_push_title_and_body(mode);
    let device_ids = vec![target_device_id.to_string()];
    if let Err(error) = push_remote_notification_to_device_ids(
        state,
        GenericRemoteNotificationPayload {
            device_ids: &device_ids,
            push_type,
            ride_id: None,
            ride_status: None,
            title: Some(title),
            body: Some(body),
            pickup_summary: None,
            request_id: None,
            wallet_id: None,
            call_id: Some(call_id),
            from_device_id: Some(from_device_id),
            mode: Some(mode),
        },
    )
    .await
    {
        tracing::warn!(
            error = ?error,
            target_device_hash = %auth::hash_prefix(target_device_id),
            call_id_hash = %auth::hash_prefix(call_id),
            "incoming call push dispatch failed"
        );
    }
}

