fn ws_error_payload(detail: &str) -> String {
    let redacted_detail = auth::redact_sensitive_upstream_error_detail(detail);
    json!({"type": "error", "detail": redacted_detail}).to_string()
}

async fn send_ws_error(socket: &mut WebSocket, detail: &str) -> Result<(), ()> {
    let payload = ws_error_payload(detail);
    socket.send(Message::Text(payload)).await.map_err(|_| ())
}

async fn revalidate_ws_authenticated_chat_device(
    socket: &mut WebSocket,
    state: &AppState,
    headers: &HeaderMap,
    device_id: &str,
) -> bool {
    if state.auth.is_none() {
        return true;
    }
    match auth::require_session_principal(state, headers).await {
        Ok(principal) => {
            if let Err(err) =
                auth::require_chat_device_owned_by_principal(state, &principal, device_id).await
            {
                let _ = send_ws_error(socket, &err.detail).await;
                return false;
            }
            true
        }
        Err(err) => {
            let _ = send_ws_error(socket, &err.detail).await;
            false
        }
    }
}

async fn require_direct_peer_signal_guardrail(
    state: &AppState,
    headers: &HeaderMap,
    sender_device_id: &str,
    principal: Option<&auth::AuthPrincipal>,
    recipient_device_id: &str,
) -> ApiResult<()> {
    require_fail_closed_direct_send_guardrail(
        "recipient_block",
        require_direct_peer_upstream_guardrail(
            state,
            headers,
            sender_device_id,
            recipient_device_id,
        )
        .await,
    )?;
    if !auth::chat_send_requires_contacts(state) {
        return Ok(());
    }
    let principal =
        principal.ok_or_else(|| ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"))?;
    require_fail_closed_direct_send_guardrail(
        "contact",
        auth::require_chat_contact_allowed_for_direct_send(state, principal, recipient_device_id)
            .await,
    )?;
    Ok(())
}

async fn require_direct_peer_discovery_guardrail(
    state: &AppState,
    headers: &HeaderMap,
    sender_device_id: &str,
    recipient_device_id: &str,
) -> ApiResult<()> {
    require_fail_closed_direct_send_guardrail(
        "recipient_block",
        require_direct_peer_upstream_guardrail(
            state,
            headers,
            sender_device_id,
            recipient_device_id,
        )
        .await,
    )?;
    if !auth::chat_send_requires_contacts(state) {
        return Ok(());
    }
    let principal = auth::require_session_principal(state, headers).await?;
    require_fail_closed_direct_send_guardrail(
        "contact",
        auth::require_chat_contact_allowed_for_direct_send(state, &principal, recipient_device_id)
            .await,
    )?;
    Ok(())
}

async fn require_direct_peer_upstream_guardrail(
    state: &AppState,
    headers: &HeaderMap,
    sender_device_id: &str,
    recipient_device_id: &str,
) -> ApiResult<()> {
    let sender_device_id_hash = auth::hash_prefix(sender_device_id);
    let recipient_device_id_hash = auth::hash_prefix(recipient_device_id);
    let sender_device_id_path = auth::url_escape_component(sender_device_id);
    let path = format!("/devices/{sender_device_id_path}/guardrails/direct_peer");
    let body_bytes = serde_json::to_vec(&json!({"peer_id": recipient_device_id})).map_err(|e| {
        tracing::error!(
            error = %e,
            sender_device_id_hash,
            recipient_device_id_hash,
            "encode direct peer guardrail request"
        );
        ApiError::internal("chat upstream unavailable")
    })?;
    let (url, path_and_query) = state
        .build_upstream_url(&state.chat_base_url, &path, &[])
        .map_err(|e| {
            tracing::error!(
                error = %e,
                sender_device_id_hash,
                recipient_device_id_hash,
                "invalid direct peer guardrail url"
            );
            ApiError::internal("chat upstream unavailable")
        })?;
    let mut req = state
        .http
        .request(Method::POST, url)
        .timeout(Duration::from_secs(state.upstream_timeout_secs.max(1)));
    if state.should_send_legacy_internal_secret() {
        if let Some(secret) = state.chat_internal_secret.as_deref() {
            let secret = secret.trim();
            if !secret.is_empty() {
                req = req.header("X-Internal-Secret", secret);
            }
        }
    }
    req = state
        .apply_internal_identity_headers(req, &Method::POST, "chat", &path_and_query, &body_bytes)
        .map_err(|e| {
            tracing::error!(
                error = %e,
                sender_device_id_hash,
                recipient_device_id_hash,
                "sign direct peer guardrail request"
            );
            ApiError::internal("chat upstream unavailable")
        })?;
    for h in H_CHAT_AUTH
        .iter()
        .copied()
        .chain(std::iter::once("X-Request-ID"))
    {
        if let Some(v) = headers.get(h) {
            if let Ok(vs) = v.to_str() {
                let vv = vs.trim();
                if !vv.is_empty() {
                    req = req.header(h, vv);
                }
            }
        }
    }
    req = req
        .header(header::CONTENT_TYPE, "application/json")
        .body(body_bytes);

    let resp = req.send().await.map_err(|e| {
        let status = if e.is_timeout() {
            StatusCode::GATEWAY_TIMEOUT
        } else {
            StatusCode::BAD_GATEWAY
        };
        tracing::error!(
            error = %e,
            timeout = e.is_timeout(),
            sender_device_id_hash,
            recipient_device_id_hash,
            "chat direct-peer guardrail call failed"
        );
        ApiError::upstream(status, "chat direct-peer guardrail unavailable")
    })?;
    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    if status.is_success() {
        return Ok(());
    }

    let is_json = resp
        .headers()
        .get(CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .map(|ct| ct.to_ascii_lowercase().starts_with("application/json"))
        .unwrap_or(false);
    let bytes =
        read_response_body_limited(resp, state.max_upstream_body_bytes, "chat", &path).await?;
    let detail = if is_json {
        let parsed: Value = serde_json::from_slice(&bytes)
            .unwrap_or_else(|_| json!({"detail":"chat direct-peer guardrail invalid json"}));
        extract_detail(&parsed).unwrap_or_else(|| parsed.to_string())
    } else {
        String::from_utf8_lossy(&bytes).trim().to_string()
    };
    if status.is_server_error() {
        return Err(ApiError::internal("chat direct-peer guardrail unavailable"));
    }
    if status == StatusCode::FORBIDDEN && detail.eq_ignore_ascii_case("blocked by recipient") {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    if status == StatusCode::NOT_FOUND {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    Err(ApiError::new(
        status,
        if detail.is_empty() {
            status
                .canonical_reason()
                .unwrap_or("request failed")
                .to_string()
        } else {
            detail
        },
    ))
}

async fn resolve_group_typing_targets(
    state: &AppState,
    headers: &HeaderMap,
    group_id: &str,
    sender_device_id: &str,
) -> Vec<String> {
    let response = proxy_chat(
        state,
        Method::GET,
        &format!("/groups/{}/members", escaped_path_segment(group_id)),
        vec![("device_id".to_string(), sender_device_id.to_string())],
        None,
        headers,
        H_CHAT_AUTH,
    )
    .await;

    let axum::Json(value) = match response {
        Ok(v) => v,
        Err(_) => return Vec::new(),
    };
    let Value::Array(items) = value else {
        return Vec::new();
    };

    let mut out = Vec::new();
    for item in items {
        let Value::Object(obj) = item else {
            continue;
        };
        let Some(device_id) = obj
            .get("device_id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty() && *s != sender_device_id)
        else {
            continue;
        };
        out.push(device_id.to_string());
    }
    out
}

fn normalize_call_signal_payload(from_device_id: &str, raw: &str) -> Option<(String, String)> {
    if raw.len() > CALL_SIGNAL_MAX_PAYLOAD_BYTES {
        return None;
    }

    let mut value: Value = serde_json::from_str(raw).ok()?;
    let obj = value.as_object_mut()?;

    let msg_type = obj
        .get("type")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|v| !v.is_empty())?;
    if msg_type.len() > 64 {
        return None;
    }

    let target = obj
        .get("to")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .filter(|v| is_valid_chat_device_id(v))
        .map(ToString::to_string)?;
    if target == from_device_id {
        return None;
    }

    obj.insert("from".to_string(), json!(from_device_id));
    Some((target, value.to_string()))
}

fn normalize_typing_signal_payload(from_device_id: &str, raw: &str) -> Option<TypingDispatch> {
    if raw.len() > CHAT_TYPING_MAX_PAYLOAD_BYTES {
        return None;
    }

    let value: Value = serde_json::from_str(raw).ok()?;
    let Value::Object(obj) = value else {
        return None;
    };

    let event_type = obj
        .get("type")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or("typing")
        .to_lowercase();
    if event_type != "typing" {
        return None;
    }

    let is_typing = match obj.get("is_typing") {
        Some(Value::Bool(v)) => *v,
        Some(Value::String(v)) => matches!(v.trim().to_lowercase().as_str(), "true" | "1"),
        Some(Value::Number(v)) => v.as_i64().is_some_and(|n| n != 0),
        None => true,
        _ => return None,
    };
    let scope = obj
        .get("scope")
        .and_then(Value::as_str)
        .map(str::trim)
        .unwrap_or("")
        .to_lowercase();

    match scope.as_str() {
        "direct" => {
            let peer_id = obj
                .get("peer_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty() && *s != from_device_id && is_valid_chat_device_id(s))?;
            let payload = json!({
                "type": "typing",
                "scope": "direct",
                "from_device_id": from_device_id,
                "peer_id": peer_id,
                "is_typing": is_typing,
            })
            .to_string();
            Some(TypingDispatch::Direct {
                target_device_id: peer_id.to_string(),
                payload,
            })
        }
        "group" => {
            let group_id = obj
                .get("group_id")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|s| !s.is_empty() && is_valid_chat_group_id(s))?;
            let payload = json!({
                "type": "typing",
                "scope": "group",
                "from_device_id": from_device_id,
                "group_id": group_id,
                "is_typing": is_typing,
            })
            .to_string();
            Some(TypingDispatch::Group {
                group_id: group_id.to_string(),
                payload,
            })
        }
        _ => None,
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct MessageCursor {
    created_at: String,
    message_id: String,
}

#[derive(Debug, Serialize)]
struct ChatGroupInboxBatchCursorReq {
    group_id: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    since_iso: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    since_id: Option<String>,
}

#[derive(Debug, Serialize)]
struct ChatDirectInboxWindowReq {
    device_id: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    since_iso: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    since_id: Option<String>,
    limit: i64,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ChatGroupInboxBatchItemOut {
    group_id: String,
    #[serde(default)]
    messages: Vec<Value>,
}

fn message_cursor_from_value(message: &Value) -> Option<MessageCursor> {
    let created_at = message
        .get("created_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let message_id = message
        .get("id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    Some(MessageCursor {
        created_at: created_at.to_string(),
        message_id: message_id.to_string(),
    })
}

fn max_message_cursor(messages: &[Value]) -> Option<MessageCursor> {
    let mut latest: Option<MessageCursor> = None;
    for message in messages {
        let Some(cursor) = message_cursor_from_value(message) else {
            continue;
        };
        let replace = latest.as_ref().is_none_or(|current| {
            cursor.created_at > current.created_at
                || (cursor.created_at == current.created_at
                    && cursor.message_id > current.message_id)
        });
        if replace {
            latest = Some(cursor);
        }
    }
    latest
}

fn filter_messages_after_cursor(
    messages: Vec<Value>,
    cursor: Option<&MessageCursor>,
) -> Vec<Value> {
    let Some(cursor) = cursor else {
        return messages;
    };
    messages
        .into_iter()
        .filter(|message| {
            let Some(message_cursor) = message_cursor_from_value(message) else {
                return false;
            };
            message_cursor.created_at > cursor.created_at
                || (message_cursor.created_at == cursor.created_at
                    && message_cursor.message_id > cursor.message_id)
        })
        .collect()
}

#[cfg(test)]
fn push_message_cursor_query(query: &mut Vec<(String, String)>, cursor: Option<&MessageCursor>) {
    let Some(cursor) = cursor else {
        return;
    };
    query.push(("since_iso".to_string(), cursor.created_at.clone()));
    if !cursor.message_id.trim().is_empty() {
        query.push(("since_id".to_string(), cursor.message_id.clone()));
    }
}

async fn fetch_direct_inbox_pages(
    state: &AppState,
    headers: &HeaderMap,
    device_id: &str,
    since_cursor: Option<MessageCursor>,
    limit: i64,
    max_pages: usize,
) -> ApiResult<Vec<Value>> {
    let normalized_limit = limit.clamp(1, 200);
    let normalized_max_pages = max_pages.max(1);
    let window_limit = if since_cursor.is_some() {
        normalized_limit
            .saturating_mul(normalized_max_pages as i64)
            .clamp(1, DIRECT_INBOX_WINDOW_MAX_LIMIT)
    } else {
        normalized_limit
    };
    let body = json!(ChatDirectInboxWindowReq {
        device_id: device_id.to_string(),
        since_iso: since_cursor
            .as_ref()
            .map(|cursor| cursor.created_at.clone()),
        since_id: since_cursor
            .as_ref()
            .map(|cursor| cursor.message_id.trim().to_string())
            .filter(|value| !value.is_empty()),
        limit: window_limit,
    });

    match proxy_chat(
        state,
        Method::POST,
        "/messages/inbox/window",
        Vec::new(),
        Some(body),
        headers,
        H_CHAT_AUTH,
    )
    .await?
    {
        axum::Json(Value::Array(items)) => Ok(items),
        _ => Ok(Vec::new()),
    }
}

async fn fetch_group_inbox_batch_pages(
    state: &AppState,
    headers: &HeaderMap,
    device_id: &str,
    group_ids: &[String],
    since_by_group: &HashMap<String, MessageCursor>,
    limit: i64,
    max_pages: usize,
) -> ApiResult<HashMap<String, Vec<Value>>> {
    let normalized_limit = limit.clamp(1, 200);
    let normalized_max_pages = max_pages.max(1);
    let mut cursors: HashMap<String, Option<MessageCursor>> = group_ids
        .iter()
        .cloned()
        .map(|group_id| {
            let cursor = since_by_group.get(&group_id).cloned();
            (group_id, cursor)
        })
        .collect();
    let mut active_groups = group_ids.to_vec();
    let mut collected: HashMap<String, Vec<Value>> = HashMap::new();
    let mut seen_ids: HashMap<String, HashSet<String>> = HashMap::new();

    for _ in 0..normalized_max_pages {
        if active_groups.is_empty() {
            break;
        }
        let groups = active_groups
            .iter()
            .map(|group_id| {
                let cursor = cursors.get(group_id).cloned().flatten();
                ChatGroupInboxBatchCursorReq {
                    group_id: group_id.clone(),
                    since_iso: cursor.as_ref().map(|value| value.created_at.clone()),
                    since_id: cursor
                        .as_ref()
                        .map(|value| value.message_id.trim().to_string())
                        .filter(|value| !value.is_empty()),
                }
            })
            .collect::<Vec<_>>();
        let body = json!({
            "device_id": device_id,
            "limit": normalized_limit,
            "groups": groups,
        });

        let batch_items = match proxy_chat(
            state,
            Method::POST,
            "/groups/inbox/batch",
            Vec::new(),
            Some(body),
            headers,
            H_CHAT_AUTH,
        )
        .await?
        {
            axum::Json(Value::Array(items)) => {
                serde_json::from_value::<Vec<ChatGroupInboxBatchItemOut>>(Value::Array(items))
                    .map_err(|_| ApiError::internal("invalid upstream response"))?
            }
            _ => Vec::new(),
        };
        let mut batch_by_group: HashMap<String, Vec<Value>> = HashMap::new();
        for item in batch_items {
            let group_id = item.group_id.trim().to_string();
            if group_id.is_empty() {
                continue;
            }
            batch_by_group.insert(group_id, item.messages);
        }

        let mut next_active_groups = Vec::new();
        for group_id in active_groups {
            let raw_messages = batch_by_group.remove(&group_id).unwrap_or_default();
            if raw_messages.is_empty() {
                continue;
            }

            let previous_cursor = cursors.get(&group_id).cloned().flatten();
            let latest_cursor = max_message_cursor(&raw_messages);
            let seen_for_group = seen_ids.entry(group_id.clone()).or_default();
            for message in
                filter_messages_after_cursor(raw_messages.clone(), previous_cursor.as_ref())
            {
                let should_push = message
                    .get("id")
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|id| !id.is_empty())
                    .is_none_or(|id| seen_for_group.insert(id.to_string()));
                if should_push {
                    collected.entry(group_id.clone()).or_default().push(message);
                }
            }
            let Some(next_cursor) = latest_cursor else {
                continue;
            };
            if previous_cursor.as_ref() == Some(&next_cursor) {
                continue;
            }
            cursors.insert(group_id.clone(), Some(next_cursor));
            if raw_messages.len() >= normalized_limit as usize {
                next_active_groups.push(group_id);
            }
        }
        active_groups = next_active_groups;
    }

    Ok(collected)
}

fn extract_group_ids(v: &Value) -> Vec<String> {
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    let Some(items) = v.as_array() else {
        return out;
    };
    for item in items {
        let Some(raw) = item
            .get("group_id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
        else {
            continue;
        };
        let Ok(gid) = required_path(raw, "group_id") else {
            continue;
        };
        if seen.insert(gid.clone()) {
            out.push(gid);
        }
    }
    out
}

