pub async fn chat_group_inbox(
    Path(group_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<ChatGroupInboxQuery>,
) -> ApiResult<Response> {
    let group_id = required_chat_group_path(&group_id)?;
    let device_id = required_chat_device_query(q.device_id.as_deref())?;
    let has_since = q
        .since_iso
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .is_some()
        || q.since_id
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .is_some();
    let has_before = q
        .before_created_at
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .is_some()
        || q.before_id
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .is_some();
    if has_since && has_before {
        return Err(ApiError::bad_request(
            "since_iso/since_id and before_created_at/before_id cannot be combined",
        ));
    }
    let mut query = vec![("device_id".to_string(), device_id)];
    push_since_cursor_query(&mut query, q.since_iso.as_deref(), q.since_id.as_deref())?;
    push_before_cursor_query(
        &mut query,
        q.before_created_at.as_deref(),
        q.before_id.as_deref(),
    )?;
    push_limit_query(&mut query, "limit", q.limit, 50, 1, 200);

    let out = proxy_chat(
        &state,
        Method::GET,
        &format!("/groups/{}/messages/inbox", escaped_path_segment(&group_id)),
        query,
        None,
        &headers,
        H_CHAT_AUTH,
    )
    .await
    .map_err(normalize_group_visibility_error)?;
    Ok(json_no_store_response(out.0))
}

