pub async fn admin_roles_check(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<AdminRolesCheckQuery>,
) -> ApiResult<Response> {
    let actor_principal = auth::require_session_principal(&state, &headers).await.ok();
    let target_role = q
        .role
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_ascii_lowercase());
    let target_account_id = q
        .account_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    let target_phone = q
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);

    if let Some(principal) = actor_principal.as_ref() {
        if let Err(err) =
            auth::enforce_admin_role_read_rate_limit(&state, &headers, principal, "check").await
        {
            auth::audit_admin_role_read_event(
                "check",
                "blocked",
                Some(principal),
                target_role.as_deref(),
                target_account_id.as_deref(),
                target_phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    }

    let (role_filter, _caller_is_superadmin) =
        match validated_public_admin_role_read(&state, &headers, q.role.as_deref()) {
            Ok(value) => value,
            Err(err) => {
                auth::audit_admin_role_read_event(
                    "check",
                    "blocked",
                    actor_principal.as_ref(),
                    target_role.as_deref(),
                    target_account_id.as_deref(),
                    target_phone.as_deref(),
                    Some(err.detail.as_str()),
                );
                return Err(err);
            }
        };
    let role = match role_filter {
        Some(role) => role,
        None => {
            let err = ApiError::bad_request("role required");
            auth::audit_admin_role_read_event(
                "check",
                "blocked",
                actor_principal.as_ref(),
                target_role.as_deref(),
                target_account_id.as_deref(),
                target_phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    };
    let account_id = q
        .account_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string);
    let phone = q
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string);
    if account_id.is_none() && phone.is_none() {
        let err = ApiError::bad_request("account_id or phone required");
        auth::audit_admin_role_read_event(
            "check",
            "blocked",
            actor_principal.as_ref(),
            target_role.as_deref(),
            target_account_id.as_deref(),
            target_phone.as_deref(),
            Some(err.detail.as_str()),
        );
        return Err(err);
    }
    if let Some(auth_runtime) = state.auth.as_ref() {
        let canonical_role_id_filter = auth::resolved_access_assignment_from_legacy_role(&role)
            .map(|resolved| resolved.role_id)
            .ok_or_else(|| ApiError::bad_request("invalid role"))?;
        let assignments = auth::list_access_assignments_from_auth_store(
            auth_runtime,
            account_id.as_deref(),
            phone.as_deref(),
            Some(canonical_role_id_filter.as_str()),
            100,
            None,
            None,
        )
        .await
        .map_err(|error| {
            tracing::error!(error = ?error, "admin roles auth-store check failed");
            ApiError::internal("failed to check admin role")
        })?;
        let ok = assignments
            .iter()
            .filter_map(admin_role_list_entry_from_access_assignment)
            .any(|item| {
                item.get("role")
                    .and_then(Value::as_str)
                    .map(|actual_role| public_admin_role_matches_filter(role.as_str(), actual_role))
                    .unwrap_or(false)
            });
        auth::audit_admin_role_read_event(
            "check",
            "applied",
            actor_principal.as_ref(),
            target_role.as_deref(),
            target_account_id.as_deref(),
            target_phone.as_deref(),
            None,
        );
        return Ok(json_no_store_response(json!({ "ok": ok })));
    }
    let err = ApiError::new(
        StatusCode::SERVICE_UNAVAILABLE,
        "admin role auth store unavailable",
    );
    auth::audit_admin_role_read_event(
        "check",
        "failed",
        actor_principal.as_ref(),
        target_role.as_deref(),
        target_account_id.as_deref(),
        target_phone.as_deref(),
        Some(err.detail.as_str()),
    );
    Err(err)
}

async fn proxy_payments(
    state: &AppState,
    method: Method,
    path: &str,
    query: Vec<(String, String)>,
    body: Option<Value>,
    headers: &HeaderMap,
    forward_headers: &[&str],
) -> ApiResult<axum::Json<Value>> {
    let spec = ProxySpec {
        method,
        path,
        query,
        body,
        headers,
        forward_headers,
    };
    proxy_upstream(state, Upstream::Payments, spec).await
}

