async fn internal_chat_post_json(state: &AppState, path: &str, body: Value) -> ApiResult<Value> {
    let path_hash = auth::hash_prefix(path);
    let (url, path_and_query) = state
        .build_upstream_url(&state.chat_base_url, path, &[])
        .map_err(|error| {
            tracing::error!(error = %error, path_hash, upstream = "chat", "invalid upstream url");
            ApiError::internal("chat upstream unavailable")
        })?;
    let body_bytes = serde_json::to_vec(&body).map_err(|error| {
        tracing::error!(error = %error, path_hash, upstream = "chat", "encode upstream body");
        ApiError::internal("chat upstream unavailable")
    })?;

    let mut req = state
        .http
        .request(Method::POST, url)
        .timeout(Duration::from_secs(state.upstream_timeout_secs.max(1)));
    if state.should_send_legacy_internal_secret() {
        if let Some(secret) = state.chat_internal_secret.as_deref() {
            let secret = secret.trim();
            if !secret.is_empty() {
                req = req.header("X-Internal-Secret", secret);
            }
        }
    }
    req = state
        .apply_internal_identity_headers(req, &Method::POST, "chat", &path_and_query, &body_bytes)
        .map_err(|error| {
            tracing::error!(error = %error, path_hash, upstream = "chat", "sign upstream request");
            ApiError::internal("chat upstream unavailable")
        })?;
    let resp = req
        .header(CONTENT_TYPE, "application/json")
        .body(body_bytes)
        .send()
        .await
        .map_err(|error| {
            let status = if error.is_timeout() {
                StatusCode::GATEWAY_TIMEOUT
            } else {
                StatusCode::BAD_GATEWAY
            };
            tracing::error!(
                error = %error,
                timeout = error.is_timeout(),
                path_hash,
                upstream = "chat",
                "chat internal call failed"
            );
            ApiError::upstream(status, "chat upstream unavailable")
        })?;

    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let response_text = resp.text().await.map_err(|error| {
        tracing::error!(error = %error, path_hash, upstream = "chat", "chat response read failed");
        ApiError::internal("chat upstream unavailable")
    })?;
    if !status.is_success() {
        tracing::warn!(
            status = %status,
            path_hash,
            upstream = "chat",
            body = response_text,
            "chat internal push request rejected"
        );
        return Err(ApiError::upstream(status, "chat upstream unavailable"));
    }
    serde_json::from_str::<Value>(&response_text).map_err(|error| {
        tracing::error!(error = %error, path_hash, upstream = "chat", "chat response json decode failed");
        ApiError::internal("chat upstream unavailable")
    })
}

async fn active_chat_device_ids_for_account(
    state: &AppState,
    account_id: &str,
) -> ApiResult<Vec<String>> {
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let rows = sqlx::query(
        r#"
        SELECT chat_device_id
        FROM auth_chat_devices
        WHERE account_id=$1
          AND revoked_at IS NULL
        ORDER BY last_seen_at DESC, id DESC
        LIMIT $2
        "#,
    )
    .bind(account_id)
    .bind(RIDE_PUSH_ACCOUNT_DEVICE_LIMIT)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            account_hash = %auth::hash_prefix(account_id),
            "active chat device lookup failed"
        );
        ApiError::internal("chat device lookup unavailable")
    })?;

    let mut out = Vec::with_capacity(rows.len());
    for row in rows {
        let device_id: String = row.try_get("chat_device_id").map_err(|error| {
            tracing::error!(error = %error, "active chat device decode failed");
            ApiError::internal("chat device lookup unavailable")
        })?;
        let device_id = device_id.trim().to_string();
        if !device_id.is_empty() && is_valid_chat_device_id(&device_id) && !out.contains(&device_id)
        {
            out.push(device_id);
        }
    }
    Ok(out)
}

async fn active_operator_account_ids_for_push(state: &AppState) -> ApiResult<Vec<String>> {
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let rows = sqlx::query(
        r#"
        SELECT account_id
        FROM (
          SELECT DISTINCT ON (account_id)
            account_id,
            last_seen_at,
            id
          FROM auth_chat_devices
          WHERE revoked_at IS NULL
            AND account_id IS NOT NULL
            AND btrim(account_id) <> ''
          ORDER BY account_id, last_seen_at DESC, id DESC
        ) recent_accounts
        ORDER BY last_seen_at DESC, id DESC
        LIMIT $1
        "#,
    )
    .bind(RIDE_PUSH_OPERATOR_ACCOUNT_LIMIT)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(error = %error, "operator push account lookup failed");
        ApiError::internal("ride push unavailable")
    })?;

    let headers = HeaderMap::new();
    let candidate_count = rows.len();
    let mut out = Vec::new();
    let mut role_lookup_errors = 0usize;
    let mut skipped_by_role = 0usize;
    for row in rows {
        let account_id: String = row.try_get("account_id").map_err(|error| {
            tracing::error!(error = %error, "operator push account decode failed");
            ApiError::internal("ride push unavailable")
        })?;
        let account_id = account_id.trim().to_string();
        if account_id.is_empty() || out.contains(&account_id) {
            continue;
        }
        match auth::fetch_roles_for_account(state, &headers, &account_id).await {
            Ok(roles) if auth::roles_allow_ride_operator(&roles) => out.push(account_id),
            Ok(_) => skipped_by_role += 1,
            Err(error) => {
                role_lookup_errors += 1;
                tracing::warn!(
                    error = ?error,
                    account_hash = %auth::hash_prefix(&account_id),
                    "operator push role lookup failed"
                );
            }
        }
    }
    tracing::info!(
        candidate_accounts = candidate_count,
        eligible_operator_accounts = out.len(),
        skipped_by_role,
        role_lookup_errors,
        "operator push account fanout resolved"
    );
    Ok(out)
}

struct RemoteNotificationPayload<'a> {
    account_id: &'a str,
    push_type: &'a str,
    ride_id: &'a str,
    ride_status: Option<&'a str>,
    title: Option<&'a str>,
    body: Option<&'a str>,
    pickup_summary: Option<&'a str>,
}

struct GenericRemoteNotificationPayload<'a> {
    device_ids: &'a [String],
    push_type: &'a str,
    ride_id: Option<&'a str>,
    ride_status: Option<&'a str>,
    title: Option<&'a str>,
    body: Option<&'a str>,
    pickup_summary: Option<&'a str>,
    request_id: Option<&'a str>,
    wallet_id: Option<&'a str>,
    call_id: Option<&'a str>,
    from_device_id: Option<&'a str>,
    mode: Option<&'a str>,
}

async fn push_remote_notification_to_device_ids(
    state: &AppState,
    payload: GenericRemoteNotificationPayload<'_>,
) -> ApiResult<(u64, u64)> {
    let GenericRemoteNotificationPayload {
        device_ids,
        push_type,
        ride_id,
        ride_status,
        title,
        body,
        pickup_summary,
        request_id,
        wallet_id,
        call_id,
        from_device_id,
        mode,
    } = payload;
    if device_ids.is_empty() {
        return Ok((0, 0));
    }

    let mut payload = Map::new();
    payload.insert("device_ids".to_string(), json!(device_ids));
    payload.insert("type".to_string(), json!(push_type));
    if let Some(ride_id) = ride_id.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("ride_id".to_string(), json!(ride_id));
    }
    if let Some(ride_status) = ride_status.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("ride_status".to_string(), json!(ride_status));
    }
    if let Some(title) = title.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("title".to_string(), json!(title));
    }
    if let Some(body) = body.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("body".to_string(), json!(body));
    }
    if let Some(pickup_summary) = pickup_summary
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        payload.insert("pickup_summary".to_string(), json!(pickup_summary));
    }
    if let Some(request_id) = request_id.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("request_id".to_string(), json!(request_id));
    }
    if let Some(wallet_id) = wallet_id.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("wallet_id".to_string(), json!(wallet_id));
    }
    if let Some(call_id) = call_id.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("call_id".to_string(), json!(call_id));
    }
    if let Some(from_device_id) = from_device_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        payload.insert("from_device_id".to_string(), json!(from_device_id));
    }
    if let Some(mode) = mode.map(str::trim).filter(|value| !value.is_empty()) {
        payload.insert("mode".to_string(), json!(mode));
    }

    let response = internal_chat_post_json(state, "/push/notify", Value::Object(payload)).await?;
    Ok((
        response
            .get("targeted_devices")
            .and_then(Value::as_u64)
            .unwrap_or(0),
        response
            .get("targeted_tokens")
            .and_then(Value::as_u64)
            .unwrap_or(0),
    ))
}

async fn push_remote_notification_to_account(
    state: &AppState,
    payload: RemoteNotificationPayload<'_>,
) -> ApiResult<bool> {
    let RemoteNotificationPayload {
        account_id,
        push_type,
        ride_id,
        ride_status,
        title,
        body,
        pickup_summary,
    } = payload;
    let device_ids = active_chat_device_ids_for_account(state, account_id).await?;
    if device_ids.is_empty() {
        if push_type == RIDE_PUSH_TYPE_OPERATOR_ALERT {
            tracing::info!(
                operator_account_hash = %auth::hash_prefix(account_id),
                ride_id_hash = %auth::hash_prefix(ride_id),
                "operator push skipped because account has no active chat devices"
            );
        }
        return Ok(false);
    }

    let (targeted_devices, targeted_tokens) = push_remote_notification_to_device_ids(
        state,
        GenericRemoteNotificationPayload {
            device_ids: &device_ids,
            push_type,
            ride_id: Some(ride_id),
            ride_status,
            title,
            body,
            pickup_summary,
            request_id: None,
            wallet_id: None,
            call_id: None,
            from_device_id: None,
            mode: None,
        },
    )
    .await?;
    if push_type == RIDE_PUSH_TYPE_OPERATOR_ALERT {
        tracing::info!(
            operator_account_hash = %auth::hash_prefix(account_id),
            ride_id_hash = %auth::hash_prefix(ride_id),
            requested_device_ids = device_ids.len(),
            targeted_devices,
            targeted_tokens,
            ride_status = ride_status.unwrap_or_default(),
            "operator push fanout dispatched"
        );
    } else if push_type == RIDE_PUSH_TYPE_DRIVER_DISPATCH {
        tracing::info!(
            driver_account_hash = %auth::hash_prefix(account_id),
            ride_id_hash = %auth::hash_prefix(ride_id),
            requested_device_ids = device_ids.len(),
            targeted_devices,
            targeted_tokens,
            ride_status = ride_status.unwrap_or_default(),
            "driver dispatch push fanout dispatched"
        );
    }
    Ok(true)
}

fn format_notification_amount_cents(amount_cents: i64, currency: Option<&str>) -> String {
    let sign = if amount_cents < 0 { "-" } else { "" };
    let abs = amount_cents.saturating_abs();
    let amount = format!("{sign}{}.{:02}", abs / 100, abs % 100);
    match currency.map(str::trim).filter(|value| !value.is_empty()) {
        Some(currency) => format!("{amount} {currency}"),
        None => amount,
    }
}

async fn push_payment_request_notification_to_wallet_owner(
    state: &AppState,
    headers: &HeaderMap,
    wallet_id: &str,
    request_id: &str,
    amount_cents: i64,
    currency: Option<&str>,
) -> ApiResult<bool> {
    let Some(account_id) = lookup_existing_account_id_for_wallet(state, headers, wallet_id).await?
    else {
        return Ok(false);
    };
    let device_ids = active_chat_device_ids_for_account(state, &account_id).await?;
    if device_ids.is_empty() {
        return Ok(false);
    }
    let amount = format_notification_amount_cents(amount_cents, currency);
    let body = format!("Amount: {amount}");
    let (_targeted_devices, targeted_tokens) = push_remote_notification_to_device_ids(
        state,
        GenericRemoteNotificationPayload {
            device_ids: &device_ids,
            push_type: CHAT_PUSH_TYPE_PAYMENT_REQUEST,
            ride_id: None,
            ride_status: None,
            title: Some("New payment request"),
            body: Some(body.as_str()),
            pickup_summary: None,
            request_id: Some(request_id),
            wallet_id: None,
            call_id: None,
            from_device_id: None,
            mode: None,
        },
    )
    .await?;
    Ok(targeted_tokens > 0)
}

