async fn push_remote_notification_to_operator_accounts(
    state: &AppState,
    ride_id: &str,
    ride_status: Option<&str>,
    title: Option<&str>,
    body: Option<&str>,
    pickup_summary: Option<&str>,
    exclude_account_id: Option<&str>,
) -> ApiResult<usize> {
    let operator_account_ids = active_operator_account_ids_for_push(state).await?;
    if operator_account_ids.is_empty() {
        tracing::info!(
            ride_id_hash = %auth::hash_prefix(ride_id),
            ride_status = ride_status.unwrap_or_default(),
            "operator push skipped because no eligible operator accounts were found"
        );
        return Ok(0);
    }

    let excluded = exclude_account_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_ascii_lowercase());
    let mut sent = 0usize;
    for account_id in operator_account_ids {
        if excluded
            .as_deref()
            .is_some_and(|value| value == account_id.to_ascii_lowercase())
        {
            continue;
        }
        match push_remote_notification_to_account(
            state,
            RemoteNotificationPayload {
                account_id: &account_id,
                push_type: RIDE_PUSH_TYPE_OPERATOR_ALERT,
                ride_id,
                ride_status,
                title,
                body,
                pickup_summary,
            },
        )
        .await
        {
            Ok(true) => sent += 1,
            Ok(false) => {}
            Err(error) => {
                tracing::warn!(
                    error = ?error,
                    ride_id_hash = %auth::hash_prefix(ride_id),
                    operator_account_hash = %auth::hash_prefix(&account_id),
                    "operator remote push failed"
                );
            }
        }
    }
    tracing::info!(
        ride_id_hash = %auth::hash_prefix(ride_id),
        ride_status = ride_status.unwrap_or_default(),
        targeted_operator_accounts = sent,
        excluded_account = excluded.is_some(),
        "operator push fanout completed"
    );
    Ok(sent)
}

async fn push_ride_dispatch_offers_for_ride_best_effort(
    state: &AppState,
    ride_id: &str,
) -> ApiResult<()> {
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let rows = sqlx::query(
        r#"
        SELECT
          offers.driver_account_id,
          COALESCE(NULLIF(trip.pickup_label, ''), trip.pickup_text) AS pickup_summary
        FROM auth_ride_dispatch_offers offers
        JOIN auth_ride_trips trip
          ON trip.ride_id = offers.ride_id
        WHERE offers.ride_id = $1
          AND offers.status = 'pending'
          AND offers.expires_at > NOW()
          AND trip.status = 'matching'
          AND trip.driver_account_id IS NULL
        ORDER BY offers.offered_at DESC, offers.id DESC
        "#,
    )
    .bind(ride_id)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(error = %error, ride_id_hash = %auth::hash_prefix(ride_id), "dispatch offer push lookup failed");
        ApiError::internal("ride push unavailable")
    })?;

    let mut seen = HashSet::new();
    for row in rows {
        let driver_account_id: String = row.try_get("driver_account_id").map_err(|error| {
            tracing::error!(error = %error, "dispatch offer push driver decode failed");
            ApiError::internal("ride push unavailable")
        })?;
        let driver_account_id = driver_account_id.trim().to_string();
        if driver_account_id.is_empty() || !seen.insert(driver_account_id.clone()) {
            continue;
        }
        let pickup_summary: Option<String> = row.try_get("pickup_summary").ok().flatten();
        let (title, body) = ride_driver_dispatch_push_copy(pickup_summary.as_deref());
        if let Err(error) = push_remote_notification_to_account(
            state,
            RemoteNotificationPayload {
                account_id: &driver_account_id,
                push_type: RIDE_PUSH_TYPE_DRIVER_DISPATCH,
                ride_id,
                ride_status: Some("matching"),
                title: Some(title.as_str()),
                body: Some(body.as_str()),
                pickup_summary: pickup_summary.as_deref(),
            },
        )
        .await
        {
            tracing::warn!(
                error = ?error,
                ride_id_hash = %auth::hash_prefix(ride_id),
                driver_account_hash = %auth::hash_prefix(&driver_account_id),
                "driver dispatch push failed"
            );
        }
    }
    Ok(())
}

async fn push_recent_dispatches_for_driver_best_effort(
    state: &AppState,
    driver_account_id: &str,
) -> ApiResult<()> {
    let auth_runtime = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))?;
    let rows = sqlx::query(
        r#"
        SELECT
          offers.ride_id,
          COALESCE(NULLIF(trip.pickup_label, ''), trip.pickup_text) AS pickup_summary
        FROM auth_ride_dispatch_offers offers
        JOIN auth_ride_trips trip
          ON trip.ride_id = offers.ride_id
        WHERE offers.driver_account_id = $1
          AND offers.status = 'pending'
          AND offers.expires_at > NOW()
          AND offers.offered_at >= NOW() - INTERVAL '3 seconds'
          AND trip.status = 'matching'
          AND trip.driver_account_id IS NULL
        ORDER BY offers.offered_at DESC, offers.id DESC
        LIMIT 5
        "#,
    )
    .bind(driver_account_id)
    .fetch_all(auth_runtime.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            driver_account_hash = %auth::hash_prefix(driver_account_id),
            "recent driver dispatch push lookup failed"
        );
        ApiError::internal("ride push unavailable")
    })?;

    let mut seen = HashSet::new();
    for row in rows {
        let ride_id: String = row.try_get("ride_id").map_err(|error| {
            tracing::error!(error = %error, "recent driver dispatch ride decode failed");
            ApiError::internal("ride push unavailable")
        })?;
        if !seen.insert(ride_id.clone()) {
            continue;
        }
        let pickup_summary: Option<String> = row.try_get("pickup_summary").ok().flatten();
        let (title, body) = ride_driver_dispatch_push_copy(pickup_summary.as_deref());
        if let Err(error) = push_remote_notification_to_account(
            state,
            RemoteNotificationPayload {
                account_id: driver_account_id,
                push_type: RIDE_PUSH_TYPE_DRIVER_DISPATCH,
                ride_id: &ride_id,
                ride_status: Some("matching"),
                title: Some(title.as_str()),
                body: Some(body.as_str()),
                pickup_summary: pickup_summary.as_deref(),
            },
        )
        .await
        {
            tracing::warn!(
                error = ?error,
                ride_id_hash = %auth::hash_prefix(&ride_id),
                driver_account_hash = %auth::hash_prefix(driver_account_id),
                "recent driver dispatch push failed"
            );
        }
    }
    Ok(())
}

