fn trusted_client_ip_header_value(headers: &HeaderMap) -> Option<String> {
    headers
        .get(TRUSTED_CLIENT_IP_ATTESTED_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| *value == "1")?;
    headers
        .get(TRUSTED_CLIENT_IP_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .and_then(|value| value.parse::<IpAddr>().ok())
        .map(|value| value.to_string())
}

fn attach_trusted_client_ip_headers(
    mut req: reqwest::RequestBuilder,
    headers: &HeaderMap,
) -> reqwest::RequestBuilder {
    if let Some(client_ip) = trusted_client_ip_header_value(headers) {
        req = req.header(TRUSTED_CLIENT_IP_HEADER, client_ip);
        req = req.header(TRUSTED_CLIENT_IP_ATTESTED_HEADER, "1");
    }
    req
}

async fn proxy_chat_stream(
    state: &AppState,
    path: &str,
    query: Vec<(String, String)>,
    headers: &HeaderMap,
    forward_headers: &[&str],
) -> ApiResult<Response> {
    require_chat_guardrails_if_configured(state, headers, path, &query, None).await?;
    let path_hash = auth::hash_prefix(path);
    let (url, path_and_query) = state
        .build_upstream_url(&state.chat_base_url, path, &query)
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream = "chat",
                "invalid upstream url"
            );
            ApiError::internal("chat upstream unavailable")
        })?;
    let mut req = state
        .http
        .request(Method::GET, url)
        .timeout(Duration::from_secs(state.upstream_timeout_secs.max(1)));
    if state.should_send_legacy_internal_secret() {
        if let Some(secret) = state.chat_internal_secret.as_deref() {
            let secret = secret.trim();
            if !secret.is_empty() {
                req = req.header("X-Internal-Secret", secret);
            }
        }
    }
    req = state
        .apply_internal_identity_headers(req, &Method::GET, "chat", &path_and_query, &[])
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream = "chat",
                "sign upstream request"
            );
            ApiError::internal("chat upstream unavailable")
        })?;
    req = attach_trusted_client_ip_headers(req, headers);
    for h in forward_headers
        .iter()
        .copied()
        .chain(std::iter::once("X-Request-ID"))
    {
        if let Some(v) = headers.get(h) {
            if let Ok(vs) = v.to_str() {
                let vv = vs.trim();
                if !vv.is_empty() {
                    req = req.header(h, vv);
                }
            }
        }
    }

    let resp = req.send().await.map_err(|e| {
        let status = if e.is_timeout() {
            StatusCode::GATEWAY_TIMEOUT
        } else {
            StatusCode::BAD_GATEWAY
        };
        tracing::error!(
            error = %e,
            timeout = e.is_timeout(),
            path_hash,
            upstream = "chat",
            "upstream call failed"
        );
        ApiError::upstream(status, "chat upstream unavailable")
    })?;

    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    if !status.is_success() {
        let is_json = resp
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|v| v.to_str().ok())
            .map(|ct| ct.to_ascii_lowercase().starts_with("application/json"))
            .unwrap_or(false);
        let bytes =
            read_response_body_limited(resp, state.max_upstream_body_bytes, "chat", path).await?;
        let detail = if is_json {
            let parsed: Value = serde_json::from_slice(&bytes)
                .unwrap_or_else(|_| json!({"detail": "chat upstream returned invalid json"}));
            extract_detail(&parsed).unwrap_or_else(|| parsed.to_string())
        } else {
            String::from_utf8_lossy(&bytes).to_string()
        };
        let detail = sanitize_upstream_detail(state, status, "chat", detail);
        return Err(ApiError::upstream(status, detail));
    }

    let content_type = resp.headers().get(CONTENT_TYPE).cloned();
    let stream = resp.bytes_stream();
    let mut out = Response::new(Body::from_stream(stream));
    *out.status_mut() = status;
    if let Some(ct) = content_type {
        out.headers_mut().insert(CONTENT_TYPE, ct);
    } else {
        out.headers_mut().insert(
            CONTENT_TYPE,
            axum::http::HeaderValue::from_static("text/event-stream"),
        );
    }
    out.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        axum::http::HeaderValue::from_static("no-store"),
    );
    Ok(out)
}

struct ProxySpec<'a> {
    method: Method,
    path: &'a str,
    query: Vec<(String, String)>,
    body: Option<Value>,
    headers: &'a HeaderMap,
    forward_headers: &'a [&'a str],
}

async fn proxy_upstream(
    state: &AppState,
    upstream: Upstream,
    spec: ProxySpec<'_>,
) -> ApiResult<axum::Json<Value>> {
    let ProxySpec {
        method,
        path,
        query,
        body,
        headers,
        forward_headers,
    } = spec;

    let (base_url, upstream_name, secret) = match upstream {
        Upstream::Payments => (
            state.payments_base_url.as_str(),
            "payments",
            state.payments_internal_secret.as_deref(),
        ),
        Upstream::Chat => (
            state.chat_base_url.as_str(),
            "chat",
            state.chat_internal_secret.as_deref(),
        ),
    };
    let path_hash = auth::hash_prefix(path);
    let (url, path_and_query) = state
        .build_upstream_url(base_url, path, &query)
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream = upstream_name,
                "invalid upstream url"
            );
            ApiError::internal(format!("{upstream_name} upstream unavailable"))
        })?;
    let body_bytes = body
        .map(|b| serde_json::to_vec(&b))
        .transpose()
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream = upstream_name,
                "encode upstream body"
            );
            ApiError::internal(format!("{upstream_name} upstream unavailable"))
        })?;

    let mut req = state
        .http
        .request(method.clone(), url)
        .timeout(Duration::from_secs(state.upstream_timeout_secs.max(1)));

    if state.should_send_legacy_internal_secret() {
        if let Some(secret) = secret.map(str::trim).filter(|s| !s.is_empty()) {
            req = req.header("X-Internal-Secret", secret);
        }
    }
    req = state
        .apply_internal_identity_headers(
            req,
            &method,
            upstream_name,
            &path_and_query,
            body_bytes.as_deref().unwrap_or(&[]),
        )
        .map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream = upstream_name,
                "sign upstream request"
            );
            ApiError::internal(format!("{upstream_name} upstream unavailable"))
        })?;
    req = attach_trusted_client_ip_headers(req, headers);

    for h in forward_headers
        .iter()
        .copied()
        .chain(std::iter::once("X-Request-ID"))
    {
        if let Some(v) = headers.get(h) {
            if let Ok(vs) = v.to_str() {
                let vv = vs.trim();
                if !vv.is_empty() {
                    req = req.header(h, vv);
                }
            }
        }
    }

    if let Some(body_bytes) = body_bytes {
        req = req
            .header(header::CONTENT_TYPE, "application/json")
            .body(body_bytes);
    }

    let resp = req.send().await.map_err(|e| {
        let status = if e.is_timeout() {
            StatusCode::GATEWAY_TIMEOUT
        } else {
            StatusCode::BAD_GATEWAY
        };
        tracing::error!(
            error = %e,
            timeout = e.is_timeout(),
            path_hash,
            upstream = upstream_name,
            "upstream call failed"
        );
        ApiError::upstream(status, format!("{upstream_name} upstream unavailable"))
    })?;

    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let is_json = resp
        .headers()
        .get(CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .map(|ct| ct.to_ascii_lowercase().starts_with("application/json"))
        .unwrap_or(false);
    let bytes =
        read_response_body_limited(resp, state.max_upstream_body_bytes, upstream_name, path)
            .await?;

    if is_json {
        let parsed: Value = serde_json::from_slice(&bytes).unwrap_or_else(
            |_| json!({"detail": format!("{upstream_name} upstream returned invalid json")}),
        );
        if status.is_success() {
            return Ok(axum::Json(parsed));
        }
        let detail = extract_detail(&parsed).unwrap_or_else(|| parsed.to_string());
        let detail = sanitize_upstream_detail(state, status, upstream_name, detail);
        return Err(ApiError::upstream(status, detail));
    }

    let text = String::from_utf8_lossy(&bytes).to_string();
    if status.is_success() {
        return Ok(axum::Json(json!({"raw": text})));
    }

    let detail = sanitize_upstream_detail(state, status, upstream_name, text);
    Err(ApiError::upstream(status, detail))
}

async fn read_response_body_limited(
    resp: reqwest::Response,
    max_bytes: usize,
    upstream_name: &str,
    path: &str,
) -> ApiResult<Vec<u8>> {
    let path_hash = auth::hash_prefix(path);
    if let Some(cl) = resp.content_length() {
        if cl as usize > max_bytes {
            tracing::warn!(
                upstream = upstream_name,
                path_hash,
                content_length = cl,
                max_bytes,
                "upstream response exceeds configured limit"
            );
            return Err(ApiError::upstream(
                StatusCode::BAD_GATEWAY,
                format!("{upstream_name} upstream response too large"),
            ));
        }
    }

    let mut out: Vec<u8> = Vec::new();
    let mut total = 0usize;
    let mut stream = resp.bytes_stream();
    while let Some(next) = stream.next().await {
        let chunk = next.map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream = upstream_name,
                "upstream body read failed"
            );
            ApiError::internal(format!("{upstream_name} upstream body read failed"))
        })?;
        total += chunk.len();
        if total > max_bytes {
            tracing::warn!(
                upstream = upstream_name,
                path_hash,
                total_bytes = total,
                max_bytes,
                "upstream response exceeded configured limit while streaming"
            );
            return Err(ApiError::upstream(
                StatusCode::BAD_GATEWAY,
                format!("{upstream_name} upstream response too large"),
            ));
        }
        out.extend_from_slice(&chunk);
    }
    Ok(out)
}

fn sanitize_upstream_detail(
    state: &AppState,
    status: StatusCode,
    upstream_name: &str,
    detail: String,
) -> String {
    let redacted_detail = auth::redact_sensitive_upstream_error_detail(&detail);
    if !state.expose_upstream_errors && (status.is_client_error() || status.is_server_error()) {
        if upstream_name == "payments"
            && status == StatusCode::CONFLICT
            && redacted_detail.starts_with("driver balance must cover the 10% platform fee")
        {
            return redacted_detail;
        }
        return format!("{upstream_name} upstream error");
    }
    redacted_detail
}

#[cfg(test)]
async fn ensure_favorite_owned(
    state: &AppState,
    headers: &HeaderMap,
    fid: &str,
    owner_wallet_id: &str,
) -> ApiResult<()> {
    let fid_path = escaped_path_segment(fid);
    let out = proxy_payments(
        state,
        Method::GET,
        &format!("/favorites/{fid_path}"),
        vec![("owner_wallet_id".to_string(), owner_wallet_id.to_string())],
        None,
        headers,
        H_USER_AGENT,
    )
    .await?;
    let owned = out
        .0
        .get("owner_wallet_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .is_some_and(|value| value == owner_wallet_id);
    if !owned {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    Ok(())
}

#[cfg(test)]
async fn ensure_request_owned_by_kind(
    state: &AppState,
    headers: &HeaderMap,
    rid: &str,
    wallet_id: &str,
    kind: &str,
) -> ApiResult<()> {
    let out = proxy_payments(
        state,
        Method::GET,
        &format!("/requests/{}", escaped_path_segment(rid)),
        vec![("wallet_id".to_string(), wallet_id.to_string())],
        None,
        headers,
        H_USER_AGENT,
    )
    .await?;
    let owner_field = match kind {
        "incoming" => "to_wallet_id",
        "outgoing" => "from_wallet_id",
        _ => return Err(ApiError::bad_request("invalid request ownership kind")),
    };
    let owned = out
        .0
        .get(owner_field)
        .and_then(Value::as_str)
        .map(str::trim)
        .is_some_and(|owner_wallet_id| owner_wallet_id == wallet_id);
    if !owned {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    Ok(())
}

async fn require_chat_guardrails_if_configured(
    state: &AppState,
    headers: &HeaderMap,
    path: &str,
    query: &[(String, String)],
    body: Option<&Value>,
) -> ApiResult<()> {
    let norm_path = path.trim_end_matches('/');
    if norm_path == "/messages/send" {
        // Best practice: direct messages must use sealed-sender; never allow a client-driven
        // metadata downgrade, even in dev builds.
        let sealed_sender = body
            .and_then(|v| v.as_object())
            .and_then(|o| o.get("sealed_sender"))
            .and_then(Value::as_bool)
            .unwrap_or(false);
        if !sealed_sender {
            return Err(ApiError::bad_request("sealed_sender required"));
        }
    }
    if norm_path.starts_with("/admin/")
        || (norm_path.starts_with("/voice/transcript_jobs/") && norm_path.ends_with("/complete"))
    {
        return Ok(());
    }
    if state.auth.is_some() {
        let principal = auth::require_session_principal(state, headers).await?;
        // Allow device registration before ownership can be established.
        // Subsequent chat calls are bound to the authenticated user via auth_chat_devices.
        if norm_path == "/devices/register" {
            return Ok(());
        }
        let path_device_id = require_chat_device_path_consistency(path, headers)?;
        require_chat_actor_device_consistency(path, headers, query, body)?;
        let device_id = path_device_id
            .or_else(|| extract_chat_device_id(headers, path, query, body))
            .ok_or_else(|| ApiError::bad_request("chat device_id required"))?;
        if !is_valid_chat_device_id(&device_id) {
            return Err(ApiError::bad_request("invalid device_id"));
        }
        let ownership_result =
            auth::require_chat_device_owned_by_principal(state, &principal, &device_id).await;
        let device_id = if norm_path == "/messages/send" {
            require_fail_closed_direct_send_guardrail("ownership", ownership_result)?
        } else {
            ownership_result?
        };

        // Rate limits: apply only after AuthN/AuthZ has succeeded to avoid allowing
        // unauthenticated callers to burn rate-limit buckets.
        let sender_device_id = Some(device_id.as_str());
        if norm_path == "/messages/send" {
            require_fail_closed_direct_send_guardrail(
                "rate_limit",
                auth::enforce_chat_send_rate_limit(state, headers, sender_device_id).await,
            )?;
            if auth::chat_send_requires_contacts(state) {
                let recipient_id = body
                    .and_then(|v| v.as_object())
                    .and_then(|o| o.get("recipient_id"))
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                    .ok_or_else(|| ApiError::bad_request("recipient_id required"))?;
                if !is_valid_chat_device_id(recipient_id) {
                    return Err(ApiError::bad_request("invalid recipient_id"));
                }
                require_fail_closed_direct_send_guardrail(
                    "contact",
                    auth::require_chat_contact_allowed_for_direct_send(
                        state,
                        &principal,
                        recipient_id,
                    )
                    .await,
                )?;
            }
        } else if norm_path.starts_with("/groups/") && norm_path.ends_with("/messages/send") {
            auth::enforce_chat_group_send_rate_limit(state, headers, sender_device_id).await?;
        }
    }
    Ok(())
}

fn require_fail_closed_direct_send_guardrail<T>(
    guardrail: &'static str,
    result: ApiResult<T>,
) -> ApiResult<T> {
    if let Err(err) = &result {
        if err.status.is_server_error() {
            let redacted_detail = auth::redact_sensitive_upstream_error_detail(&err.detail);
            tracing::warn!(
                status = %err.status,
                detail = %redacted_detail,
                guardrail,
                "chat direct-send guardrail unavailable; blocking send"
            );
        }
    }
    result
}

fn extract_chat_device_id(
    headers: &HeaderMap,
    path: &str,
    query: &[(String, String)],
    body: Option<&Value>,
) -> Option<String> {
    header_value(headers, "x-chat-device-id")
        .or_else(|| {
            query
                .iter()
                .find(|(k, v)| k == "device_id" && !v.trim().is_empty())
                .map(|(_, v)| v.trim().to_string())
        })
        .or_else(|| extract_chat_device_id_from_path(path))
        .or_else(|| body.and_then(extract_chat_device_id_from_body))
}

fn require_chat_device_path_consistency(
    path: &str,
    headers: &HeaderMap,
) -> ApiResult<Option<String>> {
    let path_device_id = extract_chat_device_id_from_path(path);
    let Some(path_device_id) = path_device_id.as_deref() else {
        return Ok(None);
    };
    if !chat_device_path_binds_actor(path) {
        return Ok(None);
    }
    if let Some(header_device_id) = header_value(headers, "x-chat-device-id") {
        if header_device_id != path_device_id {
            return Err(ApiError::new(
                StatusCode::FORBIDDEN,
                "chat device path/header mismatch",
            ));
        }
    }
    Ok(Some(path_device_id.to_string()))
}

fn require_chat_actor_device_consistency(
    path: &str,
    headers: &HeaderMap,
    query: &[(String, String)],
    body: Option<&Value>,
) -> ApiResult<()> {
    let mut observed: Vec<(&'static str, String)> = Vec::new();
    if let Some(device_id) = header_value(headers, "x-chat-device-id") {
        observed.push(("header", device_id.to_string()));
    }
    if let Some(device_id) = query
        .iter()
        .find_map(|(key, value)| {
            (key == "device_id")
                .then_some(value.trim())
                .filter(|v| !v.is_empty())
        })
        .map(ToString::to_string)
    {
        observed.push(("query", device_id));
    }
    if chat_device_path_binds_actor(path) {
        if let Some(device_id) = extract_chat_device_id_from_path(path) {
            observed.push(("path", device_id));
        }
    }
    if let Some(device_id) = body.and_then(extract_chat_device_id_from_body) {
        observed.push(("body", device_id));
    }

    let Some((reference_source, reference_device_id)) = observed.first() else {
        return Ok(());
    };
    for (source, device_id) in observed.iter().skip(1) {
        if device_id != reference_device_id {
            tracing::warn!(
                security_event = "chat_actor_device_mismatch",
                path_hash = %auth::hash_prefix(path),
                reference_source,
                source,
                reference_device_id_hash = %auth::hash_prefix(reference_device_id),
                observed_device_id_hash = %auth::hash_prefix(device_id),
                "chat actor device id mismatch across request surfaces"
            );
            return Err(ApiError::new(
                StatusCode::FORBIDDEN,
                "chat actor device mismatch",
            ));
        }
    }
    Ok(())
}

fn chat_device_path_binds_actor(path: &str) -> bool {
    let Some(rest) = path.strip_prefix("/devices/") else {
        return false;
    };
    let mut parts = rest.split('/');
    let device_id = parts.next().unwrap_or("").trim();
    if device_id.is_empty() || device_id.eq_ignore_ascii_case("register") {
        return false;
    }
    parts.next().is_some()
}

fn extract_chat_device_id_from_path(path: &str) -> Option<String> {
    let rest = path.strip_prefix("/devices/")?;
    let device_id = rest.split('/').next().unwrap_or("").trim();
    // "/devices/register" is an action route, not a device resource path.
    if device_id.is_empty() || device_id.eq_ignore_ascii_case("register") {
        None
    } else {
        Some(device_id.to_string())
    }
}

fn extract_chat_device_id_from_body(body: &Value) -> Option<String> {
    let obj = body.as_object()?;
    for key in [
        "device_id",
        "from_device_id",
        "sender_device_id",
        "actor_device_id",
        "sender_id",
        "actor_id",
        "inviter_id",
    ] {
        if let Some(v) = obj
            .get(key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
        {
            return Some(v.to_string());
        }
    }
    None
}

fn normalize_chat_protocol_version(raw: &str) -> Option<&'static str> {
    let v = raw.trim().to_ascii_lowercase();
    match v.as_str() {
        "1" | "v1" | "v1_legacy" => Some("v1_legacy"),
        "2" | "v2" | "v2_libsignal" => Some("v2_libsignal"),
        _ => None,
    }
}

fn normalize_chat_body_for_proxy(path: &str, body: Option<Value>) -> Option<Value> {
    let norm_path = path.trim_end_matches('/');
    let should_normalize_protocol = norm_path == "/messages/send"
        || (norm_path.starts_with("/groups/") && norm_path.ends_with("/messages/send"));
    if !should_normalize_protocol {
        return body;
    }

    let mut body = body?;
    let obj = body.as_object_mut()?;
    let Some(raw_protocol) = obj.get("protocol_version").and_then(Value::as_str) else {
        return Some(body);
    };
    if let Some(normalized) = normalize_chat_protocol_version(raw_protocol) {
        obj.insert(
            "protocol_version".to_string(),
            Value::String(normalized.to_string()),
        );
    }
    Some(body)
}

fn required_path(raw: &str, field: &str) -> ApiResult<String> {
    let v = raw.trim().to_string();
    if v.is_empty() {
        return Err(ApiError::bad_request(format!("{field} required")));
    }
    if v.len() > 200 {
        return Err(ApiError::bad_request(format!("{field} too long")));
    }
    // Keep upstream path construction safe: never allow reserved path/query
    // delimiters in path parameters.
    if v.contains(['/', '\\', '?', '#', '%']) {
        return Err(ApiError::bad_request(format!("{field} invalid")));
    }
    if v.chars()
        .any(|ch| ch.is_ascii_whitespace() || ch.is_ascii_control())
    {
        return Err(ApiError::bad_request(format!("{field} invalid")));
    }
    Ok(v)
}

fn required_payments_resource_path(raw: &str, field: &'static str) -> ApiResult<String> {
    let value = required_path(raw, field)?;
    validate_payments_resource_identifier(&value, field)?;
    Ok(value)
}

fn required_chat_device_path(raw: &str) -> ApiResult<String> {
    let device_id = required_path(raw, "device_id")?;
    if !is_valid_chat_device_id(&device_id) {
        return Err(ApiError::bad_request("invalid device_id"));
    }
    Ok(device_id)
}

fn required_chat_group_path(raw: &str) -> ApiResult<String> {
    let group_id = required_path(raw, "group_id")?;
    if !is_valid_chat_group_id(&group_id) {
        return Err(ApiError::bad_request("invalid group_id"));
    }
    Ok(group_id)
}

fn escaped_path_segment(raw: &str) -> String {
    auth::url_escape_component(raw)
}

fn required_query(raw: Option<&str>, detail: &str, _field: &str) -> ApiResult<String> {
    let v = raw
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .ok_or_else(|| ApiError::bad_request(detail))?;
    Ok(v.to_string())
}

fn required_chat_device_query(raw: Option<&str>) -> ApiResult<String> {
    let device_id = required_query(raw, "device_id required", "device_id")?;
    if !is_valid_chat_device_id(&device_id) {
        return Err(ApiError::bad_request("invalid device_id"));
    }
    Ok(device_id)
}

fn required_chat_peer_query(raw: Option<&str>) -> ApiResult<String> {
    let peer_id = required_query(raw, "peer_id required", "peer_id")?;
    if !is_valid_chat_device_id(&peer_id) {
        return Err(ApiError::bad_request("invalid peer_id"));
    }
    Ok(peer_id)
}

fn header_value(headers: &HeaderMap, name: &str) -> Option<String> {
    headers
        .get(name)
        .and_then(|v| v.to_str().ok())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string)
}

#[allow(dead_code)]
fn push_opt_query(query: &mut Vec<(String, String)>, key: &str, raw: Option<&str>) {
    if let Some(v) = raw.map(str::trim).filter(|s| !s.is_empty()) {
        query.push((key.to_string(), v.to_string()));
    }
}

fn push_iso_range_query(
    query: &mut Vec<(String, String)>,
    raw_from_iso: Option<&str>,
    raw_to_iso: Option<&str>,
) -> ApiResult<()> {
    let from_iso = raw_from_iso
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let to_iso = raw_to_iso.map(str::trim).filter(|value| !value.is_empty());

    let parsed_from = match from_iso {
        Some(value) => Some(
            chrono::DateTime::parse_from_rfc3339(value)
                .map_err(|_| ApiError::bad_request("invalid from_iso"))?,
        ),
        None => None,
    };
    let parsed_to = match to_iso {
        Some(value) => Some(
            chrono::DateTime::parse_from_rfc3339(value)
                .map_err(|_| ApiError::bad_request("invalid to_iso"))?,
        ),
        None => None,
    };

    if let (Some(from), Some(to)) = (parsed_from.as_ref(), parsed_to.as_ref()) {
        if from > to {
            return Err(ApiError::bad_request("from_iso must be <= to_iso"));
        }
    }

    if let Some(from_iso) = from_iso {
        query.push(("from_iso".to_string(), from_iso.to_string()));
    }
    if let Some(to_iso) = to_iso {
        query.push(("to_iso".to_string(), to_iso.to_string()));
    }
    Ok(())
}

fn normalize_wallet_snapshot_kind_filter(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(kind_raw) = raw.map(str::trim).filter(|s| !s.is_empty()) else {
        return Ok(None);
    };
    let kind = kind_raw.to_ascii_lowercase();
    match kind.as_str() {
        "topup" | "transfer" | "exchange_debit" | "exchange_credit" | "refund" => Ok(Some(kind)),
        _ => Err(ApiError::bad_request(
            "kind must be one of: topup, transfer, exchange_debit, exchange_credit, refund",
        )),
    }
}

fn normalize_requests_list_kind_filter(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(kind_raw) = raw.map(str::trim).filter(|s| !s.is_empty()) else {
        return Ok(None);
    };
    let kind = kind_raw.to_ascii_lowercase();
    match kind.as_str() {
        "all" => Ok(None),
        "incoming" | "outgoing" => Ok(Some(kind)),
        _ => Err(ApiError::bad_request(
            "kind must be one of: all, incoming, outgoing",
        )),
    }
}

fn push_before_cursor_query(
    query: &mut Vec<(String, String)>,
    raw_created_at: Option<&str>,
    raw_id: Option<&str>,
) -> ApiResult<()> {
    match (
        raw_created_at
            .map(str::trim)
            .filter(|value| !value.is_empty()),
        raw_id.map(str::trim).filter(|value| !value.is_empty()),
    ) {
        (None, None) => Ok(()),
        (Some(_), None) | (None, Some(_)) => Err(ApiError::bad_request(
            "before_created_at and before_id required together",
        )),
        (Some(created_at), Some(id)) => {
            validate_rfc3339_query_timestamp(created_at, "before_created_at")?;
            let before_id = validate_query_token(id, "before_id")?;
            query.push(("before_created_at".to_string(), created_at.to_string()));
            query.push(("before_id".to_string(), before_id));
            Ok(())
        }
    }
}

fn push_since_cursor_query(
    query: &mut Vec<(String, String)>,
    raw_since_iso: Option<&str>,
    raw_since_id: Option<&str>,
) -> ApiResult<()> {
    let since_iso = raw_since_iso
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let since_id = raw_since_id
        .map(str::trim)
        .filter(|value| !value.is_empty());
    match (since_iso, since_id) {
        (None, None) => Ok(()),
        (None, Some(_)) => Err(ApiError::bad_request("since_id requires since_iso")),
        (Some(since_iso), since_id) => {
            validate_rfc3339_query_timestamp(since_iso, "since_iso")?;
            query.push(("since_iso".to_string(), since_iso.to_string()));
            if let Some(since_id) = since_id {
                let since_id = validate_query_token(since_id, "since_id")?;
                query.push(("since_id".to_string(), since_id));
            }
            Ok(())
        }
    }
}

fn push_after_cursor_query(
    query: &mut Vec<(String, String)>,
    raw_joined_at: Option<&str>,
    raw_id: Option<&str>,
) -> ApiResult<()> {
    match (
        raw_joined_at
            .map(str::trim)
            .filter(|value| !value.is_empty()),
        raw_id.map(str::trim).filter(|value| !value.is_empty()),
    ) {
        (None, None) => Ok(()),
        (Some(_), None) | (None, Some(_)) => Err(ApiError::bad_request(
            "after_joined_at and after_device_id required together",
        )),
        (Some(joined_at), Some(id)) => {
            validate_rfc3339_query_timestamp(joined_at, "after_joined_at")?;
            let after_device_id = validate_query_token(id, "after_device_id")?;
            query.push(("after_joined_at".to_string(), joined_at.to_string()));
            query.push(("after_device_id".to_string(), after_device_id));
            Ok(())
        }
    }
}

fn validate_rfc3339_query_timestamp(value: &str, field: &str) -> ApiResult<()> {
    chrono::DateTime::parse_from_rfc3339(value.trim())
        .map(|_| ())
        .map_err(|_| ApiError::bad_request(format!("invalid {field}")))
}

fn validate_query_token(raw: &str, field: &str) -> ApiResult<String> {
    let value = raw.trim();
    if value.is_empty() {
        return Err(ApiError::bad_request(format!("{field} required")));
    }
    if value.chars().count() > QUERY_TOKEN_MAX_LEN {
        return Err(ApiError::bad_request(format!("{field} too long")));
    }
    if value
        .chars()
        .any(|ch| ch.is_ascii_control() || ch.is_ascii_whitespace())
    {
        return Err(ApiError::bad_request(format!("{field} invalid")));
    }
    Ok(value.to_string())
}

fn push_limit_query(
    query: &mut Vec<(String, String)>,
    key: &str,
    raw: Option<i64>,
    default: i64,
    min: i64,
    max: i64,
) {
    let v = raw.unwrap_or(default).clamp(min, max);
    query.push((key.to_string(), v.to_string()));
}

#[allow(dead_code)]
fn admin_role_list_entry_from_upstream(item: &Value) -> Option<Value> {
    let role = item
        .get("role")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string)?;
    let account_id = item
        .get("account_id")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    let phone = item
        .get("phone")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    if account_id.is_none() && phone.is_none() {
        return None;
    }
    let created_at = item
        .get("created_at")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    let cursor_id = item
        .get("cursor_id")
        .or_else(|| item.get("id"))
        .and_then(Value::as_i64)
        .filter(|value| *value > 0);
    Some(json!({
        "cursor_id": cursor_id,
        "account_id": account_id,
        "phone": phone,
        "role": role,
        "created_at": created_at,
    }))
}

fn public_admin_role_alias_key(raw: &str) -> String {
    let role = raw.trim().to_ascii_lowercase();
    match role.as_str() {
        "merchant" | "qr_seller" => "wallet.operator".to_string(),
        "driver" | "ride_driver" => "rides.driver".to_string(),
        _ => role,
    }
}

fn public_admin_role_matches_filter(requested: &str, actual: &str) -> bool {
    public_admin_role_alias_key(requested) == public_admin_role_alias_key(actual)
}

fn admin_role_list_entry_from_access_assignment(item: &AccessAssignmentOut) -> Option<Value> {
    let role = item.legacy_role.trim().to_ascii_lowercase();
    if !is_valid_public_admin_role_value(&role) {
        return None;
    }
    let account_id = item
        .account_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    let phone = item
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(str::to_string);
    if account_id.is_none() && phone.is_none() {
        return None;
    }
    Some(json!({
        "cursor_id": item.cursor_id,
        "account_id": account_id,
        "phone": phone,
        "role": role,
        "created_at": item.created_at,
    }))
}

fn validate_public_admin_before_cursor(
    raw_created_at: Option<&str>,
    raw_id: Option<i64>,
) -> ApiResult<()> {
    match (
        raw_created_at
            .map(str::trim)
            .filter(|value| !value.is_empty()),
        raw_id,
    ) {
        (None, None) => Ok(()),
        (Some(_), None) | (None, Some(_)) => Err(ApiError::bad_request(
            "before_created_at and before_id must be provided together",
        )),
        (Some(created_at), Some(before_id)) => {
            validate_rfc3339_query_timestamp(created_at, "before_created_at")?;
            if before_id <= 0 {
                return Err(ApiError::bad_request("before_id invalid"));
            }
            Ok(())
        }
    }
}

fn normalize_public_admin_role(raw: &str) -> ApiResult<String> {
    let role = raw.trim().to_ascii_lowercase();
    if role.is_empty() {
        return Err(ApiError::bad_request("role required"));
    }
    if !is_valid_public_admin_role_value(&role) {
        return Err(ApiError::bad_request("invalid role"));
    }
    Ok(role)
}

fn is_valid_scoped_official_owner_role(role: &str) -> bool {
    let Some(scope) = role.strip_prefix("official_owner:") else {
        return false;
    };
    if scope == "*" {
        return true;
    }
    if scope.is_empty() || scope.len() > 64 {
        return false;
    }
    scope.bytes().all(|byte| {
        byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(byte, b'_' | b'.' | b'-')
    })
}

fn is_valid_public_admin_role_value(role: &str) -> bool {
    PUBLIC_ADMIN_ALLOWED_ROLES.contains(&role) || is_valid_scoped_official_owner_role(role)
}

fn public_admin_role_visible_to_admin(raw: &str) -> bool {
    let role = raw.trim().to_ascii_lowercase();
    !matches!(role.as_str(), "admin" | "superadmin") && !role.starts_with("official_owner:")
}

fn validated_public_admin_role_read(
    state: &AppState,
    headers: &HeaderMap,
    role: Option<&str>,
) -> ApiResult<(Option<String>, bool)> {
    let caller_roles = authz::trusted_roles(state, headers);
    let caller_is_superadmin = caller_roles.contains("superadmin");
    let Some(role) = role else {
        return Ok((None, caller_is_superadmin));
    };

    let role = normalize_public_admin_role(role)?;
    if !caller_is_superadmin
        && (matches!(role.as_str(), "admin" | "superadmin") || role.starts_with("official_owner:"))
    {
        tracing::warn!(
            target_role = %role,
            "blocked public admin role read requiring superadmin"
        );
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "superadmin role required",
        ));
    }
    Ok((Some(role), caller_is_superadmin))
}

fn validated_public_admin_role_mutation(
    state: &AppState,
    headers: &HeaderMap,
    body: AdminRoleMutationIn,
) -> ApiResult<Value> {
    let account_id = body
        .account_id
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string);
    let phone = body
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string);
    if account_id.is_none() && phone.is_none() {
        return Err(ApiError::bad_request("account_id or phone required"));
    }

    let role = normalize_public_admin_role(&body.role)?;
    let caller_roles = authz::trusted_roles(state, headers);
    let caller_is_superadmin = caller_roles.contains("superadmin");
    if role.starts_with("official_owner:") {
        tracing::warn!(
            caller_is_superadmin,
            account_id_present = account_id.is_some(),
            phone_present = phone.is_some(),
            "blocked public admin role mutation for scoped official owner role"
        );
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "use official owner scoped routes",
        ));
    }
    if matches!(role.as_str(), "admin" | "superadmin") && !caller_is_superadmin {
        tracing::warn!(
            target_role = %role,
            account_id_present = account_id.is_some(),
            phone_present = phone.is_some(),
            "blocked public admin role mutation requiring superadmin"
        );
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "superadmin role required",
        ));
    }

    let mut payload = serde_json::Map::new();
    payload.insert("role".to_string(), Value::String(role));
    if let Some(account_id) = account_id {
        payload.insert("account_id".to_string(), Value::String(account_id));
    }
    if let Some(phone) = phone {
        payload.insert("phone".to_string(), Value::String(phone));
    }
    Ok(Value::Object(payload))
}

fn extract_detail(v: &Value) -> Option<String> {
    v.get("detail")
        .and_then(|d| d.as_str())
        .map(ToString::to_string)
}

