    #[derive(Clone, Default)]
    struct CaptureState {
        path: Arc<Mutex<Option<String>>>,
        query: Arc<Mutex<Option<String>>>,
        headers: Arc<Mutex<Option<HeaderMap>>>,
        body: Arc<Mutex<Option<Value>>>,
        calls: Arc<Mutex<usize>>,
    }

    const TEST_CHAT_REGISTER_PUBLIC_KEY_B64: &str = "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
    const TEST_CHAT_SENDER_PUBKEY_B64: &str = "BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB";
    const TEST_CHAT_NONCE_B64: &str = "CCCCCCCCCCCCCCCC";
    const TEST_CHAT_BOX_B64: &str = "DDDDDDDDDDDDDDDD";
    const TEST_CHAT_MAILBOX_TOKEN: &str =
        "abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789";

    async fn capture_sse(AxumState(state): AxumState<CaptureState>, uri: Uri) -> impl IntoResponse {
        let mut path_lock = state.path.lock().expect("capture path lock");
        *path_lock = Some(uri.path().to_string());
        let mut lock = state.query.lock().expect("capture lock");
        *lock = uri.query().map(ToString::to_string);
        (
            [(CONTENT_TYPE.as_str(), "text/event-stream")],
            "data: {\"ok\":true}\n\n",
        )
    }

    async fn capture_json(
        AxumState(state): AxumState<CaptureState>,
        uri: Uri,
    ) -> impl IntoResponse {
        let mut path_lock = state.path.lock().expect("capture path lock");
        *path_lock = Some(uri.path().to_string());
        let mut lock = state.query.lock().expect("capture lock");
        *lock = uri.query().map(ToString::to_string);
        let mut calls = state.calls.lock().expect("capture calls lock");
        *calls += 1;
        Json(json!([{"id": "m1"}]))
    }

    async fn capture_redacted_thread_json(
        AxumState(state): AxumState<CaptureState>,
        uri: Uri,
    ) -> impl IntoResponse {
        let mut path_lock = state.path.lock().expect("capture path lock");
        *path_lock = Some(uri.path().to_string());
        let mut lock = state.query.lock().expect("capture lock");
        *lock = uri.query().map(ToString::to_string);
        let mut calls = state.calls.lock().expect("capture calls lock");
        *calls += 1;
        Json(json!([{
            "id": "m-thread-1",
            "sender_id": null,
            "recipient_id": "peer_9",
            "protocol_version": "v2_libsignal",
            "sender_pubkey_b64": null,
            "nonce_b64": "AQ==",
            "box_b64": "Ag==",
            "created_at": "2026-03-18T10:00:00Z",
            "sealed_sender": true,
            "sender_hint": "fp-me",
            "sender_fingerprint": "fp-me"
        }]))
    }

    async fn capture_post_json(
        AxumState(state): AxumState<CaptureState>,
        axum::Json(body): axum::Json<Value>,
    ) -> impl IntoResponse {
        let mut captured_body = state.body.lock().expect("capture body lock");
        *captured_body = Some(body);
        let mut calls = state.calls.lock().expect("capture calls lock");
        *calls += 1;
        Json(json!([{"id": "m1"}]))
    }

    async fn capture_sse_with_headers(
        AxumState(state): AxumState<CaptureState>,
        uri: Uri,
        headers: HeaderMap,
    ) -> impl IntoResponse {
        let mut query_lock = state.query.lock().expect("capture query lock");
        *query_lock = uri.query().map(ToString::to_string);
        let mut headers_lock = state.headers.lock().expect("capture headers lock");
        *headers_lock = Some(headers);
        (
            [(CONTENT_TYPE.as_str(), "text/event-stream")],
            "data: {\"ok\":true}\n\n",
        )
    }

    async fn capture_payments_request(
        AxumState(state): AxumState<CaptureState>,
        headers: HeaderMap,
    ) -> impl IntoResponse {
        let mut lock = state.headers.lock().expect("capture headers lock");
        *lock = Some(headers);
        Json(json!({"ok": true}))
    }

    #[derive(Clone, Default)]
    struct WalletUserCaptureState {
        get_calls: Arc<Mutex<usize>>,
        post_calls: Arc<Mutex<usize>>,
        lookup_miss: bool,
        provision_headers: Arc<Mutex<Option<HeaderMap>>>,
    }

    #[derive(Clone, Default)]
    struct GeoLookupCaptureState {
        calls: Arc<Mutex<usize>>,
    }

    async fn capture_wallet_user_lookup(
        AxumState(state): AxumState<WalletUserCaptureState>,
        _uri: Uri,
    ) -> impl IntoResponse {
        let mut calls = state
            .get_calls
            .lock()
            .expect("wallet user lookup capture lock");
        *calls += 1;
        if state.lookup_miss {
            return (
                StatusCode::NOT_FOUND,
                Json(json!({"detail": "User not found"})),
            )
                .into_response();
        }
        let wallet_id = "wallet_cached_1";
        Json(json!({
            "user_id": "user-1",
            "wallet_id": wallet_id,
            "account_id": "a".repeat(64),
            "phone": "+963111111111",
            "balance_cents": 0,
            "currency": "SYP",
        }))
        .into_response()
    }

    async fn capture_wallet_user_provision(
        AxumState(state): AxumState<WalletUserCaptureState>,
        headers: HeaderMap,
    ) -> impl IntoResponse {
        let mut calls = state
            .post_calls
            .lock()
            .expect("wallet user provision capture lock");
        *calls += 1;
        let mut captured_headers = state
            .provision_headers
            .lock()
            .expect("wallet user provision headers capture lock");
        *captured_headers = Some(headers);
        Json(json!({
            "user_id": "user-1",
            "wallet_id": "wallet_cached_1",
            "account_id": "a".repeat(64),
            "phone": "+963111111111",
            "balance_cents": 0,
            "currency": "SYP",
        }))
    }

    async fn capture_geo_lookup(
        AxumState(state): AxumState<GeoLookupCaptureState>,
        uri: Uri,
        headers: HeaderMap,
    ) -> impl IntoResponse {
        let mut calls = state.calls.lock().expect("geo lookup capture lock");
        *calls += 1;
        Json(json!({
            "display_name": format!(
                "{}?{}",
                uri.path(),
                uri.query().unwrap_or_default(),
            ),
            "accept_language": headers
                .get(header::ACCEPT_LANGUAGE)
                .and_then(|value| value.to_str().ok())
                .unwrap_or_default(),
        }))
    }

    async fn spawn_test_server(app: Router) -> (String, tokio::task::JoinHandle<()>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind");
        let addr = listener.local_addr().expect("local addr");
        let handle = tokio::spawn(async move {
            axum::serve(listener, app).await.expect("serve");
        });
        (format!("http://{addr}"), handle)
    }

