    #[test]
    fn ws_poll_backoff_doubles_until_cap_when_idle() {
        let mut backoff =
            WsPollBackoff::with_jitter(Duration::from_secs(1), Duration::from_secs(8), 0, 0);
        assert_eq!(backoff.on_idle(), Duration::from_secs(2));
        assert_eq!(backoff.on_idle(), Duration::from_secs(4));
        assert_eq!(backoff.on_idle(), Duration::from_secs(8));
        assert_eq!(backoff.on_idle(), Duration::from_secs(8));
    }

    #[test]
    fn ws_poll_backoff_resets_to_min_after_activity() {
        let mut backoff =
            WsPollBackoff::with_jitter(Duration::from_secs(2), Duration::from_secs(16), 0, 0);
        assert_eq!(backoff.on_idle(), Duration::from_secs(4));
        assert_eq!(backoff.on_idle(), Duration::from_secs(8));
        assert_eq!(backoff.on_activity(), Duration::from_secs(2));
        assert_eq!(backoff.next_sleep_delay(), Duration::from_secs(2));
    }

