    #[test]
    fn ws_poll_backoff_uses_idle_growth_for_errors() {
        let mut backoff =
            WsPollBackoff::with_jitter(Duration::from_secs(1), Duration::from_secs(8), 0, 0);
        assert_eq!(backoff.on_error(), Duration::from_secs(2));
        assert_eq!(backoff.on_error(), Duration::from_secs(4));
        assert_eq!(backoff.on_activity(), Duration::from_secs(1));
    }

    #[test]
    fn ws_poll_backoff_jittered_sleep_stays_within_configured_bounds() {
        let mut backoff = WsPollBackoff::with_jitter(
            Duration::from_secs(1),
            Duration::from_secs(8),
            42,
            WS_POLL_JITTER_BASIS_POINTS,
        );
        let first = backoff.next_sleep_delay();
        assert!(first >= Duration::from_millis(850));
        assert!(first <= Duration::from_millis(1150));

        assert_eq!(backoff.on_idle(), Duration::from_secs(2));
        let second = backoff.next_sleep_delay();
        assert!(second >= Duration::from_millis(1700));
        assert!(second <= Duration::from_millis(2300));
    }

    #[test]
    fn stable_ws_schedule_seed_varies_by_scope_and_device() {
        assert_eq!(
            stable_ws_schedule_seed("chat_inbox_poll", "dev_a"),
            stable_ws_schedule_seed("chat_inbox_poll", "dev_a")
        );
        assert_ne!(
            stable_ws_schedule_seed("chat_inbox_poll", "dev_a"),
            stable_ws_schedule_seed("chat_inbox_poll", "dev_b")
        );
        assert_ne!(
            stable_ws_schedule_seed("chat_inbox_poll", "dev_a"),
            stable_ws_schedule_seed("chat_groups_poll", "dev_a")
        );
    }

    #[test]
    fn ws_next_jittered_delay_stays_within_additive_bounds() {
        let base = Duration::from_secs(15);
        let mut state = 123u64;
        let delayed = ws_next_jittered_delay(
            base,
            &mut state,
            WS_GROUP_MEMBERSHIP_REFRESH_JITTER_MAX_MILLIS,
        );
        assert!(delayed >= base);
        assert!(
            delayed <= base + Duration::from_millis(WS_GROUP_MEMBERSHIP_REFRESH_JITTER_MAX_MILLIS)
        );

        let no_jitter = ws_next_jittered_delay(base, &mut state, 0);
        assert_eq!(no_jitter, base);
    }

