    #[test]
    fn sanitize_tomtom_language_maps_to_supported_tags() {
        let mut headers = HeaderMap::new();
        headers.insert(header::ACCEPT_LANGUAGE, "ar-TN,ar;q=0.9".parse().unwrap());
        assert_eq!(sanitize_tomtom_language(&headers), "ar");

        headers.insert(header::ACCEPT_LANGUAGE, "de-DE,de;q=0.9".parse().unwrap());
        assert_eq!(sanitize_tomtom_language(&headers), "de-DE");

        headers.insert(header::ACCEPT_LANGUAGE, "fr-FR,fr;q=0.9".parse().unwrap());
        assert_eq!(sanitize_tomtom_language(&headers), "fr-FR");

        headers.insert(header::ACCEPT_LANGUAGE, "es-ES,es;q=0.9".parse().unwrap());
        assert_eq!(sanitize_tomtom_language(&headers), "es-ES");

        headers.insert(header::ACCEPT_LANGUAGE, "it-IT,it;q=0.9".parse().unwrap());
        assert_eq!(sanitize_tomtom_language(&headers), "it-IT");

        headers.insert(header::ACCEPT_LANGUAGE, "tr-TR,tr;q=0.9".parse().unwrap());
        assert_eq!(sanitize_tomtom_language(&headers), "tr-TR");

        headers.insert(header::ACCEPT_LANGUAGE, "en-GB,en;q=0.9".parse().unwrap());
        assert_eq!(sanitize_tomtom_language(&headers), "en-US");
    }

