    #[tokio::test]
    async fn fetch_nominatim_json_reuses_cached_payload_without_second_upstream_call() {
        let capture = GeoLookupCaptureState::default();
        let app = Router::new()
            .route("/reverse", get(capture_geo_lookup))
            .with_state(capture.clone());
        let (geo_base, handle) = spawn_test_server(app).await;

        let state = mk_state_full_with_geo_base(
            "http://127.0.0.1".to_string(),
            "http://127.0.0.1".to_string(),
            geo_base,
            1024 * 1024,
            true,
        );
        let query = vec![
            ("lat", "33.5138".to_string()),
            ("lon", "36.2765".to_string()),
            ("format", "jsonv2".to_string()),
        ];

        let first = fetch_nominatim_json(&state, "/reverse", &query, "en")
            .await
            .expect("first geo lookup");
        let second = fetch_nominatim_json(&state, "/reverse", &query, "en")
            .await
            .expect("second geo lookup");

        assert_eq!(first, second);
        assert_eq!(
            *capture.calls.lock().expect("geo lookup calls lock"),
            1,
            "identical geo lookups should hit upstream once within ttl"
        );
        assert_eq!(
            first.get("accept_language"),
            Some(&Value::String("en".to_string()))
        );

        handle.abort();
    }

