    #[tokio::test]
    async fn fetch_group_inbox_batch_pages_batches_groups_and_paginates_only_full_pages() {
        let requests: Arc<Mutex<Vec<Value>>> = Arc::new(Mutex::new(Vec::new()));
        let requests_for_route = requests.clone();
        let app = Router::new().route(
            "/groups/inbox/batch",
            post(move |axum::Json(body): axum::Json<Value>| {
                let requests = requests_for_route.clone();
                async move {
                    requests
                        .lock()
                        .expect("batch requests lock")
                        .push(body.clone());
                    let groups = body
                        .get("groups")
                        .and_then(Value::as_array)
                        .cloned()
                        .unwrap_or_default();
                    let second_page = groups.len() == 1
                        && groups[0].get("group_id").and_then(Value::as_str) == Some("group_1")
                        && groups[0].get("since_id").and_then(Value::as_str) == Some("msg-002");
                    let response = if second_page {
                        json!([
                            {
                                "group_id": "group_1",
                                "messages": [
                                    {
                                        "id": "msg-003",
                                        "group_id": "group_1",
                                        "sender_id": "dev_2",
                                        "text": "third",
                                        "created_at": "2026-03-18T10:00:02Z"
                                    }
                                ]
                            }
                        ])
                    } else {
                        json!([
                            {
                                "group_id": "group_1",
                                "messages": [
                                    {
                                        "id": "msg-001",
                                        "group_id": "group_1",
                                        "sender_id": "dev_2",
                                        "text": "first",
                                        "created_at": "2026-03-18T10:00:00Z"
                                    },
                                    {
                                        "id": "msg-002",
                                        "group_id": "group_1",
                                        "sender_id": "dev_2",
                                        "text": "second",
                                        "created_at": "2026-03-18T10:00:01Z"
                                    }
                                ]
                            },
                            {
                                "group_id": "group_2",
                                "messages": [
                                    {
                                        "id": "grp2-msg-001",
                                        "group_id": "group_2",
                                        "sender_id": "dev_3",
                                        "text": "hello",
                                        "created_at": "2026-03-18T10:00:00Z"
                                    }
                                ]
                            }
                        ])
                    };
                    Json(response)
                }
            }),
        );
        let (chat_base, handle) = spawn_test_server(app).await;
        let state = mk_state(chat_base, 1024 * 1024, true);
        let group_ids = vec!["group_1".to_string(), "group_2".to_string()];

        let messages = fetch_group_inbox_batch_pages(
            &state,
            &HeaderMap::new(),
            "dev_1",
            &group_ids,
            &HashMap::new(),
            2,
            5,
        )
        .await
        .expect("fetch batched group inbox");
        handle.abort();

        let group_1_ids: Vec<&str> = messages
            .get("group_1")
            .into_iter()
            .flatten()
            .filter_map(|message| message.get("id").and_then(Value::as_str))
            .collect();
        let group_2_ids: Vec<&str> = messages
            .get("group_2")
            .into_iter()
            .flat_map(|items| items.iter())
            .filter_map(|message| message.get("id").and_then(Value::as_str))
            .collect();
        let recorded = requests.lock().expect("batch requests lock").clone();

        assert_eq!(group_1_ids, vec!["msg-001", "msg-002", "msg-003"]);
        assert_eq!(group_2_ids, vec!["grp2-msg-001"]);
        assert_eq!(recorded.len(), 2);
        assert_eq!(
            recorded[0]
                .get("groups")
                .and_then(Value::as_array)
                .map(Vec::len),
            Some(2)
        );
        assert_eq!(
            recorded[1]
                .get("groups")
                .and_then(Value::as_array)
                .map(Vec::len),
            Some(1)
        );
        assert_eq!(
            recorded[1]["groups"][0]["group_id"].as_str(),
            Some("group_1")
        );
        assert_eq!(
            recorded[1]["groups"][0]["since_id"].as_str(),
            Some("msg-002")
        );
    }

