    #[test]
    fn chat_register_defers_only_server_side_bind_failures() {
        let server_err = ApiError::internal("failed to register chat device");
        assert!(chat_register_should_defer_bind_error(&server_err));

        let forbidden = ApiError::new(StatusCode::FORBIDDEN, "device id already in use");
        assert!(!chat_register_should_defer_bind_error(&forbidden));

        let bad_request = ApiError::bad_request("client_device_id mismatch");
        assert!(!chat_register_should_defer_bind_error(&bad_request));
    }

