    fn security_headers(raw: &[(&str, &str)]) -> HeaderMap {
        let mut headers = HeaderMap::new();
        for (name, value) in raw {
            headers.insert(
                axum::http::header::HeaderName::from_bytes(name.as_bytes()).expect("header name"),
                axum::http::HeaderValue::from_str(value).expect("header value"),
            );
        }
        headers
    }

    #[test]
    fn websocket_origin_guard_rejects_cross_site_cookie_session() {
        let state = mk_state("http://127.0.0.1".to_string(), 1024 * 1024, true);
        let headers = security_headers(&[
            (
                "cookie",
                "__Host-sa_session=0123456789abcdef0123456789abcdef",
            ),
            ("origin", "https://evil.example"),
            ("host", "api.shamell.online"),
        ]);

        let err = enforce_ws_origin_for_cookie_session(&state, &headers, "/ws/chat/inbox")
            .expect_err("cross-site browser websocket must be rejected");
        assert_eq!(err.status, StatusCode::FORBIDDEN);
    }

