    #[tokio::test]
    async fn resolve_wallet_for_account_cached_reuses_cached_wallet_without_second_upstream_call() {
        let capture = WalletUserCaptureState::default();
        let app = Router::new()
            .route(
                "/users",
                get(capture_wallet_user_lookup).post(capture_wallet_user_provision),
            )
            .with_state(capture.clone());
        let (payments_base, handle) = spawn_test_server(app).await;

        let state = mk_state_full(
            payments_base,
            "http://127.0.0.1".to_string(),
            1024 * 1024,
            true,
        );
        let headers = HeaderMap::new();
        let account_id = "a".repeat(64);
        let principal = auth::AuthPrincipal {
            account_id: account_id.clone(),
            phone: Some("+963111111111".to_string()),
            device_id: None,
        };

        let first = resolve_wallet_for_account_cached(
            &state,
            &headers,
            &principal,
            &account_id,
            Some("+963111111111"),
        )
        .await
        .expect("first wallet resolution");
        let second = resolve_wallet_for_account_cached(
            &state,
            &headers,
            &principal,
            &account_id,
            Some("+963111111111"),
        )
        .await
        .expect("second wallet resolution");

        assert_eq!(first, "wallet_cached_1");
        assert_eq!(second, "wallet_cached_1");
        let get_calls = *capture
            .get_calls
            .lock()
            .expect("wallet user get capture lock");
        let post_calls = *capture
            .post_calls
            .lock()
            .expect("wallet user post capture lock");
        assert_eq!(get_calls, 1, "wallet lookup should be cached per account");
        assert_eq!(post_calls, 0, "read-only lookup must not provision users");

        handle.abort();
    }

