    #[tokio::test]
    async fn resolve_wallet_for_account_cached_falls_back_to_provisioning_after_lookup_miss() {
        let capture = WalletUserCaptureState {
            lookup_miss: true,
            ..Default::default()
        };
        let app = Router::new()
            .route(
                "/users",
                get(capture_wallet_user_lookup).post(capture_wallet_user_provision),
            )
            .with_state(capture.clone());
        let (payments_base, handle) = spawn_test_server(app).await;

        let state = mk_state_full(
            payments_base,
            "http://127.0.0.1".to_string(),
            1024 * 1024,
            true,
        );
        let mut headers = HeaderMap::new();
        headers.insert("X-Device-ID", "dev-bound-1".parse().expect("header"));
        let account_id = "a".repeat(64);
        let principal = auth::AuthPrincipal {
            account_id: account_id.clone(),
            phone: Some("+963111111111".to_string()),
            device_id: Some("dev-bound-1".to_string()),
        };

        let wallet_id = resolve_wallet_for_account_cached(
            &state,
            &headers,
            &principal,
            &account_id,
            Some("+963111111111"),
        )
        .await
        .expect("wallet resolution after lookup miss");

        assert_eq!(wallet_id, "wallet_cached_1");
        let get_calls = *capture
            .get_calls
            .lock()
            .expect("wallet user get capture lock");
        let post_calls = *capture
            .post_calls
            .lock()
            .expect("wallet user post capture lock");
        assert_eq!(get_calls, 1, "first resolution should try read-only lookup");
        assert_eq!(
            post_calls, 1,
            "lookup miss should fall back to provisioning"
        );
        let provision_headers = capture
            .provision_headers
            .lock()
            .expect("wallet user provision headers capture lock");
        let forwarded_idempotency = provision_headers
            .as_ref()
            .and_then(|headers| headers.get("Idempotency-Key"))
            .and_then(|value| value.to_str().ok());
        assert!(
            forwarded_idempotency
                .map(|value| value.starts_with("auto.create_user."))
                .unwrap_or(false),
            "wallet provisioning fallback must forward deterministic idempotency key"
        );

        handle.abort();
    }

