        headers.insert(
            "Idempotency-Key",
            "wallet-provision-42".parse().expect("header"),
        );
        headers.insert("X-Device-ID", "dev-bound-1".parse().expect("header"));
        let principal = auth::AuthPrincipal {
            account_id: "a".repeat(64),
            phone: Some("+963111111111".to_string()),
            device_id: Some("dev-bound-1".to_string()),
        };

        let wallet_id = ensure_wallet_for_account(
            &state,
            &headers,
            &principal,
            &"a".repeat(64),
            Some("+963111111111"),
        )
        .await
        .expect("wallet provisioning after lookup miss");
        assert_eq!(wallet_id, "wallet_cached_1");

