    #[test]
    fn normalize_typing_signal_payload_accepts_direct_dispatch() {
        let dispatch = normalize_typing_signal_payload(
            "dev_sender",
            r#"{"type":"typing","scope":"direct","peer_id":"dev_peer","is_typing":true}"#,
        )
        .expect("direct typing dispatch");

        match dispatch {
            TypingDispatch::Direct {
                target_device_id,
                payload,
            } => {
                assert_eq!(target_device_id, "dev_peer");
                let parsed: Value = serde_json::from_str(&payload).expect("payload json");
                assert_eq!(parsed["type"], "typing");
                assert_eq!(parsed["scope"], "direct");
                assert_eq!(parsed["from_device_id"], "dev_sender");
                assert_eq!(parsed["peer_id"], "dev_peer");
                assert_eq!(parsed["is_typing"], true);
            }
            TypingDispatch::Group { .. } => panic!("expected direct dispatch"),
        }
    }

    #[test]
    fn normalize_typing_signal_payload_accepts_group_dispatch() {
        let dispatch = normalize_typing_signal_payload(
            "dev_sender",
            r#"{"scope":"group","group_id":"grp_demo","is_typing":"1"}"#,
        )
        .expect("group typing dispatch");

        match dispatch {
            TypingDispatch::Group { group_id, payload } => {
                assert_eq!(group_id, "grp_demo");
                let parsed: Value = serde_json::from_str(&payload).expect("payload json");
                assert_eq!(parsed["type"], "typing");
                assert_eq!(parsed["scope"], "group");
                assert_eq!(parsed["from_device_id"], "dev_sender");
                assert_eq!(parsed["group_id"], "grp_demo");
                assert_eq!(parsed["is_typing"], true);
            }
            TypingDispatch::Direct { .. } => panic!("expected group dispatch"),
        }
    }

    #[test]
    fn normalize_typing_signal_payload_rejects_invalid_targets() {
        assert!(normalize_typing_signal_payload(
            "dev_same",
            r#"{"scope":"direct","peer_id":"dev_same","is_typing":true}"#,
        )
        .is_none());
        assert!(normalize_typing_signal_payload(
            "dev_sender",
            r#"{"type":"call_signal","scope":"direct","peer_id":"dev_peer"}"#,
        )
        .is_none());
        assert!(normalize_typing_signal_payload(
            "dev_sender",
            r#"{"scope":"group","group_id":"","is_typing":true}"#,
        )
        .is_none());
        assert!(normalize_typing_signal_payload(
            "dev_sender",
            r#"{"scope":"direct","peer_id":"register","is_typing":true}"#,
        )
        .is_none());
        assert!(normalize_typing_signal_payload(
            "dev_sender",
            r#"{"scope":"group","group_id":"grp/demo","is_typing":true}"#,
        )
        .is_none());
    }

