    #[tokio::test]
    async fn upstream_detail_redacts_sensitive_fields_when_exposed() {
        let app = Router::new().route("/favorites", get(error_401_sensitive_json));
        let (payments_base, handle) = spawn_test_server(app).await;

        let state = mk_state_full(
            payments_base,
            "http://127.0.0.1".to_string(),
            1024 * 1024,
            true,
        );
        let err = proxy_payments(
            &state,
            Method::GET,
            "/favorites",
            Vec::new(),
            None,
            &HeaderMap::new(),
            H_USER_AGENT,
        )
        .await
        .expect_err("expected upstream 401");

        handle.abort();
        assert_eq!(err.status, StatusCode::UNAUTHORIZED);
        assert!(err.detail.contains("Authorization: [redacted]"));
        assert!(err.detail.contains("cookie=[redacted]"));
        assert!(err.detail.contains("message=keep-visible"));
        assert!(!err.detail.contains("Bearer secret-token"));
        assert!(!err.detail.contains("session123"));
    }

    #[test]
    fn ws_error_payload_redacts_sensitive_fields() {
        let payload = ws_error_payload(
            "Authorization: Bearer super-secret\ncookie=session-token\nmessage=keep-visible",
        );
        let value: Value = serde_json::from_str(&payload).expect("ws error payload json");
        let detail = value["detail"].as_str().expect("detail as string");
        assert!(detail.contains("Authorization: [redacted]"));
        assert!(detail.contains("cookie=[redacted]"));
        assert!(detail.contains("message=keep-visible"));
        assert!(!detail.contains("super-secret"));
        assert!(!detail.contains("session-token"));
    }

    async fn request_detail(Path(rid): Path<String>, uri: Uri) -> impl IntoResponse {
        let wallet_id = uri
            .query()
            .and_then(|query| {
                query
                    .split('&')
                    .find_map(|part| part.strip_prefix("wallet_id=").map(ToString::to_string))
            })
            .unwrap_or_default();
        match rid.as_str() {
            "req-visible" if wallet_id == "wallet-in" || wallet_id == "wallet-out" => (
                StatusCode::OK,
                axum::Json(json!({
                    "id": rid,
                    "from_wallet_id": "wallet-out",
                    "to_wallet_id": "wallet-in",
                })),
            )
                .into_response(),
            _ => StatusCode::NOT_FOUND.into_response(),
        }
    }

    async fn request_detail_capture_path(
        AxumState(state): AxumState<CaptureState>,
        Path(rid): Path<String>,
        uri: Uri,
    ) -> impl IntoResponse {
        let mut path_lock = state.path.lock().expect("capture path lock");
        *path_lock = Some(uri.path().to_string());
        let mut query_lock = state.query.lock().expect("capture query lock");
        *query_lock = uri.query().map(ToString::to_string);
        let mut calls = state.calls.lock().expect("capture calls lock");
        *calls += 1;
        (
            StatusCode::OK,
            axum::Json(json!({
                "id": rid,
                "from_wallet_id": "wallet-out",
                "to_wallet_id": "wallet-in",
            })),
        )
            .into_response()
    }

    async fn favorite_detail(Path(fid): Path<String>, uri: Uri) -> impl IntoResponse {
        let owner_wallet_id = uri
            .query()
            .and_then(|query| {
                query.split('&').find_map(|part| {
                    part.strip_prefix("owner_wallet_id=")
                        .map(ToString::to_string)
                })
            })
            .unwrap_or_default();
        match fid.as_str() {
            "fav-visible" if owner_wallet_id == "wallet-owner" => (
                StatusCode::OK,
                axum::Json(json!({
                    "id": fid,
                    "owner_wallet_id": "wallet-owner",
                    "favorite_wallet_id": "wallet-favorite",
                })),
            )
                .into_response(),
            _ => StatusCode::NOT_FOUND.into_response(),
        }
    }

    async fn favorite_detail_capture_path(
        AxumState(state): AxumState<CaptureState>,
        Path(fid): Path<String>,
        uri: Uri,
    ) -> impl IntoResponse {
        let mut path_lock = state.path.lock().expect("capture path lock");
        *path_lock = Some(uri.path().to_string());
        let mut query_lock = state.query.lock().expect("capture query lock");
        *query_lock = uri.query().map(ToString::to_string);
        let mut calls = state.calls.lock().expect("capture calls lock");
        *calls += 1;
        (
            StatusCode::OK,
            axum::Json(json!({
                "id": fid,
                "owner_wallet_id": "wallet-owner",
                "favorite_wallet_id": "wallet-favorite",
            })),
        )
            .into_response()
    }

