    #[tokio::test]
    async fn ensure_favorite_owned_escapes_favorite_id_path_segment() {
        let capture = CaptureState::default();
        let app = Router::new()
            .route("/favorites/:fid", get(favorite_detail_capture_path))
            .with_state(capture.clone());
        let (payments_base, handle) = spawn_test_server(app).await;
        let state = mk_state_full(
            payments_base,
            "http://127.0.0.1".to_string(),
            1024 * 1024,
            true,
        );

        ensure_favorite_owned(&state, &HeaderMap::new(), "fav/../../admin", "wallet-owner")
            .await
            .expect("favorite owner path check should succeed");

        handle.abort();
        let captured_path = capture
            .path
            .lock()
            .expect("capture path lock")
            .clone()
            .expect("captured path");
        let captured_query = capture
            .query
            .lock()
            .expect("capture query lock")
            .clone()
            .expect("captured query");
        let captured_calls = *capture.calls.lock().expect("capture calls lock");

        assert_eq!(captured_path, "/favorites/fav%2F..%2F..%2Fadmin");
        assert_eq!(captured_query, "owner_wallet_id=wallet-owner");
        assert_eq!(captured_calls, 1);
    }

