    #[test]
    fn payments_create_user_idempotency_key_derives_stable_fallback() {
        let headers = HeaderMap::new();
        let account_id = "a".repeat(64);
        let key_a = payments_create_user_idempotency_key(
            &headers,
            &account_id,
            Some("+963111111111"),
            Some("SYP"),
        )
        .expect("fallback idempotency key");
        let key_b = payments_create_user_idempotency_key(
            &headers,
            &account_id,
            Some("+963111111111"),
            Some("SYP"),
        )
        .expect("fallback idempotency key");
        let key_c = payments_create_user_idempotency_key(
            &headers,
            &account_id,
            Some("+963222222222"),
            Some("SYP"),
        )
        .expect("fallback idempotency key");
        let key_d = payments_create_user_idempotency_key(
            &headers,
            &account_id,
            Some("+963111111111"),
            Some("USD"),
        )
        .expect("currency-scoped fallback idempotency key");
        assert_eq!(key_a, key_b, "fallback key must be stable");
        assert_ne!(key_a, key_c, "phone-scoped fallback key must differ");
        assert_ne!(key_a, key_d, "currency-scoped fallback key must differ");
        assert!(key_a.starts_with("auto.create_user."));
        assert!(key_a.len() <= PAYMENT_IDEMPOTENCY_KEY_MAX_LEN);
    }

