    #[test]
    fn normalize_chat_body_for_proxy_rewrites_numeric_protocol_versions() {
        let direct = normalize_chat_body_for_proxy(
            "/messages/send",
            Some(json!({
                "sender_id": "dev-1",
                "recipient_id": "dev-2",
                "protocol_version": "2",
                "sealed_sender": true
            })),
        )
        .expect("direct body");
        assert_eq!(
            direct
                .get("protocol_version")
                .and_then(Value::as_str)
                .unwrap_or(""),
            "v2_libsignal"
        );

        let group = normalize_chat_body_for_proxy(
            "/groups/g-1/messages/send",
            Some(json!({
                "sender_id": "dev-1",
                "protocol_version": "1"
            })),
        )
        .expect("group body");
        assert_eq!(
            group
                .get("protocol_version")
                .and_then(Value::as_str)
                .unwrap_or(""),
            "v1_legacy"
        );
    }

    #[test]
    fn normalize_call_signal_payload_sets_from_and_preserves_type() {
        let raw = r#"{"type":"invite","to":"dev-target","from":"spoof","call_id":"call-1"}"#;
        let (target, payload) =
            normalize_call_signal_payload("dev-self", raw).expect("normalized payload");
        assert_eq!(target, "dev-target");
        let v: Value = serde_json::from_str(&payload).expect("json");
        assert_eq!(v.get("type").and_then(Value::as_str), Some("invite"));
        assert_eq!(v.get("from").and_then(Value::as_str), Some("dev-self"));
    }

