        let large_blob = "x".repeat(CALL_SIGNAL_MAX_PAYLOAD_BYTES + 1);
        let raw =
            format!("{{\"type\":\"invite\",\"to\":\"dev-target\",\"blob\":\"{large_blob}\"}}");
        assert!(normalize_call_signal_payload("dev-self", &raw).is_none());
