    #[test]
    fn security_alert_log_hash_redacts_raw_values() {
        let hashed = security_alert_log_hash("req-live-123");
        assert_ne!(hashed, "req-live-123");
        assert_eq!(hashed.len(), 12);
        assert_eq!(security_alert_log_hash("-"), "-");
        assert_eq!(security_alert_log_hash("   "), "-");
    }

    #[test]
    fn security_alert_hash_preview_hashes_and_caps_items() {
        let alerts = (0..12)
            .map(|idx| format!("alert-{idx}-secret"))
            .collect::<Vec<_>>();
        let preview = security_alert_hash_preview(&alerts);
        assert_eq!(preview.len(), 8);
        assert!(preview.iter().all(|value| value.len() == 12));
        assert!(!preview.iter().any(|value| value.contains("secret")));
    }

