    #[test]
    fn security_alert_item_validator_rejects_malformed_values() {
        assert!(!security_alert_item_is_valid("free text"));
        assert!(!security_alert_item_is_valid("event"));
        assert!(!security_alert_item_is_valid("event:1"));
        assert!(!security_alert_item_is_valid("event:one/1"));
        assert!(!security_alert_item_is_valid("event.:1/1"));
        assert!(!security_alert_item_is_valid(".event:1/1"));
        assert!(!security_alert_item_is_valid("event:1/0"));
        assert!(!security_alert_item_is_valid("event :1/1"));
    }

    #[test]
    fn security_alert_log_token_validator_enforces_safe_ascii_contract() {
        assert!(security_alert_log_token_is_valid(
            "shamell-security-events-report",
            128
        ));
        assert!(security_alert_log_token_is_valid("chat/api_v2", 64));
        assert!(!security_alert_log_token_is_valid("has space", 64));
        assert!(!security_alert_log_token_is_valid("line\nbreak", 64));
        assert!(!security_alert_log_token_is_valid("", 64));
    }

