    #[tokio::test(flavor = "current_thread")]
    async fn security_alert_ingest_logs_rejected_invalid_severity_without_raw_values() {
        let logs = SharedLogBuffer::default();
        let subscriber = tracing_subscriber::fmt()
            .json()
            .with_ansi(false)
            .without_time()
            .with_target(false)
            .with_current_span(false)
            .with_writer(logs.clone())
            .finish();
        let _sub_guard = tracing::subscriber::set_default(subscriber);

        let headers = security_headers(&[
            ("x-internal-service-id", "security-reporter"),
            ("x-request-id", "req-live-secret"),
            ("x-shamell-client-ip", "203.0.113.77"),
        ]);
        let err = security_alert_ingest(
            State(mk_state("http://127.0.0.1".to_string(), 1024 * 1024, true)),
            headers,
            Json(SecurityAlertIngestIn {
                source: "shamell-security-events-report".to_string(),
                service: Some("bff".to_string()),
                timestamp: Some("2026-03-27T14:05:00Z".to_string()),
                window_secs: Some(300),
                alerts: vec!["chat_prekey_inventory.low:3/3".to_string()],
                severity: Some("urgent-secret".to_string()),
                note: Some("token=top-secret".to_string()),
            }),
        )
        .await
        .expect_err("invalid severity must fail");

        assert_eq!(err.status, StatusCode::BAD_REQUEST);
        let log_text = logs.as_string();
        assert!(
            log_text.contains("\"security_event\":\"runtime_security_alert_ingest\""),
            "missing security_event log: {log_text}"
        );
        assert!(
            log_text.contains("\"outcome\":\"rejected\""),
            "missing rejected outcome log: {log_text}"
        );
        assert!(
            log_text.contains("\"reason\":\"invalid_severity\""),
            "missing invalid_severity reason log: {log_text}"
        );
        assert!(
            log_text.contains("\"caller\":\"security-reporter\""),
            "missing caller attribution log: {log_text}"
        );
        assert!(
            !log_text.contains("urgent-secret")
                && !log_text.contains("token=top-secret")
                && !log_text.contains("chat_prekey_inventory.low:3/3")
                && !log_text.contains("req-live-secret")
                && !log_text.contains("203.0.113.77"),
            "raw rejected values must stay redacted: {log_text}"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn security_alert_ingest_logs_rejected_malformed_alert_items() {
        let logs = SharedLogBuffer::default();
        let subscriber = tracing_subscriber::fmt()
            .json()
            .with_ansi(false)
            .without_time()
            .with_target(false)
            .with_current_span(false)
            .with_writer(logs.clone())
            .finish();
        let _sub_guard = tracing::subscriber::set_default(subscriber);

        let err = security_alert_ingest(
            State(mk_state("http://127.0.0.1".to_string(), 1024 * 1024, true)),
            HeaderMap::new(),
            Json(SecurityAlertIngestIn {
                source: "shamell-security-events-report".to_string(),
                service: Some("chat".to_string()),
                timestamp: Some("2026-03-27T14:05:00Z".to_string()),
                window_secs: Some(300),
                alerts: vec!["free text alert".to_string()],
                severity: Some("warning".to_string()),
                note: Some("cookie=session-secret".to_string()),
            }),
        )
        .await
        .expect_err("malformed alert items must fail");

        assert_eq!(err.status, StatusCode::BAD_REQUEST);
        let log_text = logs.as_string();
        assert!(
            log_text.contains("\"security_event\":\"runtime_security_alert_ingest\""),
            "missing security_event log: {log_text}"
        );
        assert!(
            log_text.contains("\"outcome\":\"rejected\""),
            "missing rejected outcome log: {log_text}"
        );
        assert!(
            log_text.contains("\"reason\":\"malformed_alert_item\""),
            "missing malformed_alert_item reason log: {log_text}"
        );
        assert!(
            !log_text.contains("free text alert") && !log_text.contains("cookie=session-secret"),
            "raw malformed values must stay redacted: {log_text}"
        );
    }

