    #[test]
    fn coach_runtime_reviewed_at_returns_recent_utc_timestamp() {
        let before = chrono::DateTime::<chrono::Utc>::from(SystemTime::now());
        let reviewed_at = coach_runtime_reviewed_at();
        let after = chrono::DateTime::<chrono::Utc>::from(SystemTime::now());
        let parsed = chrono::DateTime::parse_from_rfc3339(reviewed_at.as_str())
            .expect("reviewed_at should parse as rfc3339")
            .with_timezone(&chrono::Utc);
        assert!(parsed >= before - chrono::TimeDelta::seconds(1));
        assert!(parsed <= after + chrono::TimeDelta::seconds(1));
        assert!(reviewed_at.ends_with('Z'));
    }

