    #[test]
    fn nonempty_timestamp_or_now_falls_back_to_recent_utc_timestamp() {
        let fallback = nonempty_timestamp_or_now(None);
        assert_recent_utc_timestamp(fallback.as_str(), "nonempty_timestamp_or_now(None)");

        let blank = nonempty_timestamp_or_now(Some("   "));
        assert_recent_utc_timestamp(blank.as_str(), "nonempty_timestamp_or_now(blank)");

        let explicit = nonempty_timestamp_or_now(Some("2026-04-19T09:30:00Z"));
        assert_eq!(explicit, "2026-04-19T09:30:00Z");
    }

    fn assert_recent_utc_timestamp(value: &str, label: &str) {
        let before = chrono::DateTime::<chrono::Utc>::from(SystemTime::now());
        let parsed = chrono::DateTime::parse_from_rfc3339(value)
            .unwrap_or_else(|_| panic!("{label} should parse as rfc3339"))
            .with_timezone(&chrono::Utc);
        let after = chrono::DateTime::<chrono::Utc>::from(SystemTime::now());
        assert!(
            parsed >= before - chrono::TimeDelta::seconds(1),
            "{label} should not be stale"
        );
        assert!(
            parsed <= after + chrono::TimeDelta::seconds(1),
            "{label} should not be in the future"
        );
    }

    #[test]
    fn coach_operator_generated_at_payloads_use_runtime_timestamps() {
        let review_map = CoachOpsReviewMap::new();
        let event_map = CoachBoardingEventMap::new();
        let export_map = CoachSettlementExportMap::new();
        let statement_map = HashMap::<String, Value>::new();
        let statements = Vec::<Value>::new();
        let payout_runs = Vec::<CoachSettlementPayoutRunEntry>::new();

        let payloads = [
            (
                "refund_queue.generated_at",
                coach_operator_refund_queue_payload(10, &review_map),
            ),
            (
                "change_queue.generated_at",
                coach_operator_change_queue_payload(10, &review_map),
            ),
            (
                "reconciliation.generated_at",
                coach_operator_reconciliation_payload(10, &review_map, &event_map),
            ),
            (
                "settlement_statements.generated_at",
                coach_operator_settlement_statements_payload(10, &statements, &statements),
            ),
            (
                "payout_reconciliation.generated_at",
                coach_operator_payout_reconciliation_payload_with_statement_map(
                    10,
                    &payout_runs,
                    &payout_runs,
                    &statement_map,
                    &export_map,
                ),
            ),
            (
                "payout_runs.generated_at",
                coach_operator_payout_runs_payload_with_statement_map(
                    10,
                    &payout_runs,
                    &payout_runs,
                    &statement_map,
                    &export_map,
                ),
            ),
        ];

        for (label, payload) in payloads {
            let generated_at = payload["generated_at"]
                .as_str()
                .unwrap_or_else(|| panic!("{label} should contain generated_at"));
            assert_recent_utc_timestamp(generated_at, label);
        }
    }

