    #[test]
    fn ride_sensitive_mutation_audit_redacts_raw_identifiers() {
        let logs = SharedLogBuffer::default();
        let subscriber = tracing_subscriber::fmt()
            .json()
            .with_ansi(false)
            .without_time()
            .with_target(false)
            .with_current_span(false)
            .with_writer(logs.clone())
            .finish();
        let _sub_guard = tracing::subscriber::set_default(subscriber);

        audit_ride_sensitive_mutation_event(RideSensitiveMutationAuditEvent {
            operation: "ride_operator_trip_command",
            outcome: "success",
            actor_account_id: "acct_live_sensitive_123",
            actor_roles: &["ops".to_string(), "admin".to_string()],
            ride_id: Some("RIDESECRET123456"),
            document_id: Some("DOCSECRET123456"),
            request_id: Some("REQSECRET123456"),
            subject_account_id: Some("DRIVERSECRET123456"),
            reason: Some("cancel_trip"),
        });

        let log_text = logs.as_string();
        assert!(
            log_text.contains("\"security_event\":\"ride_sensitive_mutation\""),
            "missing security_event log: {log_text}"
        );
        assert!(
            log_text.contains("\"operation\":\"ride_operator_trip_command\""),
            "missing operation log: {log_text}"
        );
        assert!(
            log_text.contains("\"actor_roles\":\"admin,ops\""),
            "missing normalized role list: {log_text}"
        );
        assert!(
            !log_text.contains("acct_live_sensitive_123")
                && !log_text.contains("RIDESECRET123456")
                && !log_text.contains("DOCSECRET123456")
                && !log_text.contains("REQSECRET123456")
                && !log_text.contains("DRIVERSECRET123456"),
            "raw identifiers must stay redacted: {log_text}"
        );
    }

