    #[test]
    fn coach_ticket_issue_response_exposes_qr_pdf_and_wallet_artifacts() {
        let payload = coach_ticket_issue_response(&CoachTicketIssueResponseRequest {
            booking_id: "booking_demo",
            idempotency_key: "coach-ticket-test-1",
            request_fingerprint: "fp_ticket_issue_1",
            offer_id: "offer_demo_express_direct",
            hold_id: Some("hold_demo"),
            passenger_ids: &[String::from("adult_1")],
            passengers_manifest: &[CoachPassengerManifestNormalized {
                passenger_id: "adult_1".to_string(),
                given_name: "Lina".to_string(),
                family_name: "Haddad".to_string(),
                rider_category: "adult".to_string(),
                nationality_code: Some("SY".to_string()),
            }],
            delivery_channels: &[String::from("wallet_pass"), String::from("pdf")],
        });

        let tickets = payload["tickets"].as_array().expect("tickets array");
        let artifacts = tickets[0]["artifacts"].as_array().expect("artifacts array");
        assert_eq!(artifacts.len(), 3);
        assert_eq!(artifacts[0]["artifact_kind"], "qr");
        assert_eq!(artifacts[1]["artifact_kind"], "wallet_pass");
        assert_eq!(artifacts[2]["artifact_kind"], "pdf");
        assert_eq!(artifacts[1]["mime_type"], "application/vnd.apple.pkpass");
        assert_eq!(artifacts[2]["mime_type"], "application/pdf");
        assert!(artifacts[0]["download_path"]
            .as_str()
            .expect("qr download path")
            .ends_with(".svg"));
    }

