    #[test]
    fn coach_ticket_reissue_payment_failure_response_triggers_compensation() {
        let seed =
            coach_demo_booking_seed("booking_demo_express_direct").expect("demo paid reissue seed");
        let change_request = coach_change_request_payload_with_status(
            seed.booking_id,
            "offer_demo_express_midday",
            800,
            500,
            1_300,
            "payment_failed",
            Some("move to midday departure"),
        );
        let payment = coach_payment_failure_payload(seed.booking_id, "wallet_credit", 1_300);
        let compensation = coach_compensation_payload(
            "triggered",
            "retry_collection_or_raise_support_case",
            "coach_rebook_queue",
            true,
            Some("wallet_credit_insufficient"),
            Some("recovery_demo_change_payment"),
        );
        let payload = coach_ticket_reissue_payment_failed_response(
            &CoachTicketReissuePaymentFailedDefaultResponseContext {
                booking_payload: &coach_booking_payload_for_offer(
                    seed.booking_id,
                    seed.offer_id,
                    Some(seed.hold_id),
                    seed.passengers_manifest.len() as u8,
                    seed.booking_state,
                ),
                idempotency_key: "coach-reissue-wallet-failed-1",
                request_fingerprint: "fp_ticket_reissue_wallet_failed_1",
                passengers_manifest: &seed.passengers_manifest,
                tickets: &coach_demo_booking_tickets_payload(&seed),
                delivery_channels: &[String::from("wallet_pass"), String::from("pdf")],
                payment_payload: &payment,
                change_request: &change_request,
                compensation_payload: &compensation,
                next_action: "resolve_payment_failure",
            },
        );

        assert_eq!(payload["payment"]["status"], "failed");
        assert_eq!(payload["change_request"]["status"], "payment_failed");
        assert_eq!(payload["compensation"]["triggered"], true);
        assert_eq!(
            payload["compensation"]["action"],
            "retry_collection_or_raise_support_case"
        );
        assert_eq!(payload["next_action"], "resolve_payment_failure");
    }

    #[test]
    fn coach_persisted_booking_aggregate_drives_runtime_shelf_refund_and_change_payloads() {
        let aggregate = CoachStoredBookingAggregate {
            account_id: "acct_runtime".to_string(),
            booking: coach_booking_payload_for_offer(
                "booking_runtime_direct",
                "offer_runtime_direct",
                Some("hold_runtime_direct"),
                1,
                "ticketed",
            ),
            offer: Some(json!({
                "offer_id": "offer_runtime_direct",
                "currency": "EUR",
                "total_minor_units": 4590,
                "seats_requested": 1,
                "hold_supported": true,
                "changeable": true,
                "refundable": true,
                "expires_at": now_rfc3339(),
                "seat_map_available": true,
                "baggage_rule": "1 cabin bag and 1 checked bag included"
            })),
            hold: Some(coach_hold_payload_for_offer(
                "hold_runtime_direct",
                "offer_runtime_direct",
                &[String::from("pax_1")],
                &[String::from("4A")],
                "converted",
            )),
            journey: Some(json!({
                "journey_id": "journey_runtime_direct",
                "operator_name": "Runtime Express",
                "from": "Damascus",
                "to": "Aleppo",
                "departure_at": "2026-04-11T08:00:00Z",
                "arrival_at": "2026-04-11T12:30:00Z",
            })),
            passengers_manifest: json!([{
                "passenger_id": "pax_1",
                "given_name": "Lina",
                "family_name": "Haddad",
                "rider_category": "adult",
                "nationality_code": "SY"
            }]),
            tickets: vec![coach_ticket_payload_for_booking(
                "ticket_runtime_direct_1",
                "booking_runtime_direct",
                "pax_1",
                0,
            )],
        };

        let shelf = coach_booking_shelf_payload_from_aggregates(std::slice::from_ref(&aggregate));
        assert_eq!(shelf["summary"]["upcoming_count"], 1);
        assert_eq!(
            shelf["bookings"][0]["journey"]["operator_name"],
            "Runtime Express"
        );
        assert_eq!(
            shelf["bookings"][0]["tickets"][0]["ticket_id"],
            "ticket_runtime_direct_1"
        );

        let refund = coach_refund_eligibility_response_from_aggregate(&aggregate);
        assert_eq!(refund["eligibility"]["recommended_kind"], "refund_credit");
        assert_eq!(refund["eligibility"]["options"][1]["fee_minor_units"], 46);

        let change = coach_change_options_response_from_aggregate(&aggregate);
        assert_eq!(change["eligibility"]["changeable"], true);
        assert_eq!(
            change["eligibility"]["options"].as_array().map(Vec::len),
            Some(2)
        );

        let target_offer_id = change["eligibility"]["options"][0]["target_offer_id"]
            .as_str()
            .expect("target offer id present");
        let rebook = coach_rebook_request_response_from_aggregate(
            &aggregate,
            "coach-rebook-runtime-1",
            "fp_rebook_request_runtime_1",
            target_offer_id,
            Some("switch to later coach"),
        )
        .expect("persisted aggregate rebook request");
        assert_eq!(rebook["command"], "rebook_request");
        assert_eq!(rebook["change_request"]["target_offer_id"], target_offer_id);
    }

