    #[test]
    fn coach_operator_review_history_payload_uses_request_tiebreak_for_equal_reviewed_at() {
        let mut review_map = CoachOpsReviewMap::new();
        let refund_request_id = coach_demo_refund_queue_entries_payload(&review_map)[0]
            ["refund_request_id"]
            .as_str()
            .expect("refund request id present")
            .to_string();
        let change_request_id = coach_demo_change_queue_entries_payload(&review_map)[1]
            ["change_request_id"]
            .as_str()
            .expect("change request id present")
            .to_string();
        let reviewed_at = "2026-04-07T14:20:00Z".to_string();
        review_map.insert(
            refund_request_id.clone(),
            CoachOpsReviewEntry {
                decision: "approve".to_string(),
                queue_status: "approved".to_string(),
                reviewed_at: reviewed_at.clone(),
                reviewed_by_account_id: "acct_ops_demo".to_string(),
                review_note: Some("approved by finance ops".to_string()),
            },
        );
        review_map.insert(
            change_request_id.clone(),
            CoachOpsReviewEntry {
                decision: "reject".to_string(),
                queue_status: "rejected".to_string(),
                reviewed_at,
                reviewed_by_account_id: "acct_ops_demo".to_string(),
                review_note: Some("capacity unavailable".to_string()),
            },
        );

        let history = coach_operator_review_history_payload(10, &review_map);
        let mut expected_request_ids = [refund_request_id, change_request_id];
        expected_request_ids.sort_by(|left, right| right.cmp(left));

        assert_eq!(history.len(), 2);
        assert_eq!(history[0]["request_id"], expected_request_ids[0]);
        assert_eq!(history[1]["request_id"], expected_request_ids[1]);
    }

