    #[tokio::test]
    async fn coach_collect_admin_risks_with_action_state_includes_no_show_boarding_risk() {
        static TEST_LOCK: OnceLock<Arc<tokio::sync::Mutex<()>>> = OnceLock::new();
        let _guard = TEST_LOCK
            .get_or_init(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone()
            .lock_owned()
            .await;

        coach_ops_review_store().write().await.clear();
        coach_admin_risk_action_store().write().await.clear();
        coach_boarding_event_store().write().await.clear();
        coach_settlement_payout_run_store().write().await.clear();
        coach_settlement_payout_import_store().write().await.clear();

        let state = mk_state("http://127.0.0.1".to_string(), 64 * 1024, false);
        let risk_event_id = "boardevt_demo_no_show_risk";
        coach_boarding_event_store().write().await.insert(
            coach_boarding_event_store_key(
                "trip_demo_border_runner",
                "ticket_booking_demo_border_runner_1",
            ),
            CoachBoardingEventEntry {
                boarding_event_id: risk_event_id.to_string(),
                ticket_id: "ticket_booking_demo_border_runner_1".to_string(),
                trip_id: "trip_demo_border_runner".to_string(),
                scan_status: "no_show".to_string(),
                captured_at: "2026-04-20T08:30:00Z".to_string(),
                offline_captured: false,
                device_id: Some("crew_device_demo".to_string()),
                note: Some("passenger did not board".to_string()),
            },
        );

        let risks = coach_collect_admin_risks_with_action_state(&state)
            .await
            .expect("admin risks should build");
        let risk = risks
            .iter()
            .find(|risk| {
                risk["risk_id"].as_str() == Some("risk_boarding_boardevt_demo_no_show_risk")
            })
            .expect("no-show boarding risk should exist");

        assert_eq!(risk["category"], "boarding");
        assert_eq!(risk["severity"], "medium");
        assert_eq!(risk["status"], "no_show");
        assert_eq!(risk["title"], "Passenger no-show recorded");
        assert_eq!(risk["suggested_team"], "live_ops");
        assert_eq!(risk["routing_source"], "boarding_console");
        assert_eq!(
            risk["routing_reason"],
            "Boarding misuse and boarding exceptions should route to live operations."
        );
        assert_eq!(
            risk["follow_up_task_detail"],
            "Inspect boarding evidence, manifest state and any boarding exceptions before escalating support."
        );

        coach_ops_review_store().write().await.clear();
        coach_admin_risk_action_store().write().await.clear();
        coach_boarding_event_store().write().await.clear();
        coach_settlement_payout_run_store().write().await.clear();
        coach_settlement_payout_import_store().write().await.clear();
    }

