    #[test]
    fn coach_admin_risk_summary_payload_counts_workflow_states() {
        let now = chrono::DateTime::<chrono::Utc>::from(SystemTime::now());
        let overdue_detected_at =
            (now - chrono::Duration::hours(5)).to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        let due_soon_detected_at = (now - chrono::Duration::minutes(150))
            .to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        let snoozed_until =
            (now + chrono::Duration::hours(24)).to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        let updated_at = now.to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
        let active = coach_admin_risk_payload_with_action_state(
            coach_admin_risk_item_payload(
                "risk_active".to_string(),
                "finance",
                "critical",
                "Payout run failed".to_string(),
                "failed".to_string(),
                overdue_detected_at,
                None,
                Some("Demo Express".to_string()),
                None,
                None,
                None,
                None,
                Some("Payout run demo".to_string()),
                Some("EUR".to_string()),
                Some(7_350),
                None,
                vec![],
            ),
            None,
        );
        let acknowledged = coach_admin_risk_payload_with_action_state(
            coach_admin_risk_item_payload(
                "risk_ack".to_string(),
                "support",
                "high",
                "Urgent refund review pending".to_string(),
                "pending_review".to_string(),
                due_soon_detected_at.clone(),
                None,
                Some("Support Operator".to_string()),
                Some("booking_demo".to_string()),
                None,
                None,
                None,
                Some("Refund request demo".to_string()),
                Some("EUR".to_string()),
                Some(2_100),
                None,
                vec![],
            ),
            Some(&CoachAdminRiskActionEntry {
                workflow_status: "acknowledged".to_string(),
                owner_account_id: Some("acct_support_ops".to_string()),
                owner_team: Some("support_ops".to_string()),
                snoozed_until: None,
                snooze_reason: None,
                updated_at: updated_at.clone(),
                updated_by_account_id: "acct_support_ops".to_string(),
                note: None,
            }),
        );
        let snoozed = coach_admin_risk_payload_with_action_state(
            coach_admin_risk_item_payload(
                "risk_snoozed".to_string(),
                "partner_feed",
                "medium",
                "Partner feed degraded".to_string(),
                "degraded".to_string(),
                due_soon_detected_at,
                Some("op_demo_feed".to_string()),
                Some("Feed Runner".to_string()),
                None,
                None,
                None,
                None,
                Some("Feed Runner siri".to_string()),
                None,
                None,
                None,
                vec![],
            ),
            Some(&CoachAdminRiskActionEntry {
                workflow_status: "snoozed".to_string(),
                owner_account_id: None,
                owner_team: Some("partner_ops".to_string()),
                snoozed_until: Some(snoozed_until),
                snooze_reason: Some("Waiting for operator remediation window.".to_string()),
                updated_at,
                updated_by_account_id: "acct_feed_ops".to_string(),
                note: None,
            }),
        );

        let summary = coach_admin_risk_summary_payload(&[active, acknowledged, snoozed]);

        assert_eq!(summary["open_risks"], 3);
        assert_eq!(summary["active_risks"], 1);
        assert_eq!(summary["acknowledged_risks"], 1);
        assert_eq!(summary["snoozed_risks"], 1);
        assert_eq!(summary["owned_risks"], 1);
        assert_eq!(summary["critical_risks"], 1);
        assert_eq!(summary["overdue_risks"], 1);
        assert_eq!(summary["due_soon_risks"], 1);
        assert_eq!(summary["finance_alerts"], 1);
        assert_eq!(summary["support_alerts"], 1);
        assert_eq!(summary["partner_alerts"], 1);
    }

    #[test]
    fn coach_partner_feed_risk_id_uses_source_kind_to_disambiguate_duplicate_feed_kind() {
        let base = CoachCatalogOperatorFeedHealth {
            operator_id: "op_demo_express".to_string(),
            operator_name: "Demo Express".to_string(),
            operator_integration_mode: "hybrid".to_string(),
            feed_kind: "availability".to_string(),
            source_kind: "api".to_string(),
            sync_status: "failed".to_string(),
            freshness_status: "stale".to_string(),
            last_attempted_at_iso: Some("2026-04-20T08:30:00Z".to_string()),
            last_succeeded_at_iso: Some("2026-04-20T07:40:00Z".to_string()),
            freshness_expires_at_iso: Some("2026-04-20T09:00:00Z".to_string()),
            records_ingested: 0,
            error_message: Some("availability failed".to_string()),
        };
        let mut alternate = base.clone();
        alternate.source_kind = "sftp".to_string();

        let api_risk_id = coach_partner_feed_risk_id(&base);
        let sftp_risk_id = coach_partner_feed_risk_id(&alternate);

        assert_ne!(api_risk_id, sftp_risk_id);
        assert!(api_risk_id.starts_with("riskfeed_"));
        assert!(sftp_risk_id.starts_with("riskfeed_"));
    }

