    #[test]
    fn coach_admin_partner_documents_use_relative_runtime_expiry_dates() {
        let now = chrono::DateTime::parse_from_rfc3339("2026-04-19T12:00:00Z")
            .expect("fixed now should parse")
            .with_timezone(&chrono::Utc);
        let operator = CoachAdminPartnerBaseOperator {
            operator_id: "op_demo_express".to_string(),
            operator_name: "Demo Express".to_string(),
            integration_mode: "hybrid".to_string(),
            feeds: Vec::new(),
        };

        let approved_docs = coach_admin_partner_documents_at(&operator, "approved", now);
        let contract = approved_docs
            .iter()
            .find(|entry| entry["document_key"].as_str() == Some("commercial_contract"))
            .expect("commercial contract document should exist");
        let insurance = approved_docs
            .iter()
            .find(|entry| entry["document_key"].as_str() == Some("insurance_certificate"))
            .expect("insurance document should exist");

        assert_eq!(
            contract["expires_at"].as_str(),
            Some(coach_partner_document_expiry_at(now, 240).as_str())
        );
        assert_eq!(insurance["status"].as_str(), Some("expiring"));
        assert_eq!(
            insurance["expires_at"].as_str(),
            Some(coach_partner_document_expiry_at(now, 30).as_str())
        );

        let action_required_docs =
            coach_admin_partner_documents_at(&operator, "action_required", now);
        let rejected_insurance = action_required_docs
            .iter()
            .find(|entry| entry["document_key"].as_str() == Some("insurance_certificate"))
            .expect("rejected insurance document should exist");
        assert_eq!(rejected_insurance["status"].as_str(), Some("rejected"));
        assert_eq!(
            rejected_insurance["expires_at"].as_str(),
            Some(coach_partner_document_expiry_at(now, -30).as_str())
        );
    }

    #[test]
