    #[test]
    fn coach_operator_catalog_source_artifacts_payload_uses_latest_created_at_from_unsorted_artifacts(
    ) {
        let latest_artifact = CoachCatalogSourceArtifact {
            artifact_id: "catalogsourceartifact_demo_latest".to_string(),
            feed_kind: "static_catalog".to_string(),
            source_kind: "gtfs".to_string(),
            source_label: "Latest upload".to_string(),
            file_name: "latest.zip".to_string(),
            file_checksum_sha256: "b".repeat(64),
            content_length_bytes: 8192,
            extracted_file_count: 9,
            feed_locator: "/srv/feeds/demo_latest".to_string(),
            operator_ids: vec!["op_demo_manual".to_string()],
            created_by_account_id: "acct_ops_demo".to_string(),
            created_at_iso: "2026-04-16T08:00:00Z".to_string(),
        };
        let older_artifact = CoachCatalogSourceArtifact {
            artifact_id: "catalogsourceartifact_demo_older".to_string(),
            feed_kind: "static_catalog".to_string(),
            source_kind: "gtfs".to_string(),
            source_label: "Older upload".to_string(),
            file_name: "older.zip".to_string(),
            file_checksum_sha256: "c".repeat(64),
            content_length_bytes: 4096,
            extracted_file_count: 7,
            feed_locator: "/srv/feeds/demo_older".to_string(),
            operator_ids: vec!["op_demo_manual".to_string()],
            created_by_account_id: "acct_ops_demo".to_string(),
            created_at_iso: "2026-04-15T08:00:00Z".to_string(),
        };
        let all_artifacts = vec![older_artifact.clone(), latest_artifact.clone()];
        let page_artifacts = vec![latest_artifact, older_artifact];

        let payload =
            coach_operator_catalog_source_artifacts_payload(1, &all_artifacts, &page_artifacts);

        assert_eq!(payload["summary"]["total_artifacts"], 2);
        assert_eq!(payload["summary"]["uploaded_bytes_total"], 12_288);
        assert_eq!(
            payload["summary"]["latest_created_at"],
            "2026-04-16T08:00:00Z"
        );
        assert_eq!(
            payload["next_cursor"],
            "2026-04-16T08:00:00Z|catalogsourceartifact_demo_latest"
        );
    }

