    #[test]
    fn coach_operator_catalog_import_config_payload_for_scope_redacts_out_of_scope_config() {
        let config = CoachGtfsFeedConfig {
            source_kind: "gtfs".to_string(),
            configured: true,
            feed_locator: Some("/srv/feeds/demo_manual".to_string()),
            status: "ready".to_string(),
            detail: "GTFS feed directory is configured.".to_string(),
            config_origin: "database".to_string(),
        };
        let persisted_config = CoachCatalogImportConfig {
            feed_kind: "static_catalog".to_string(),
            source_kind: "gtfs".to_string(),
            feed_locator: "/srv/feeds/demo_manual".to_string(),
            source_artifact_id: Some("catalogsourceartifact_demo_manual".to_string()),
            source_artifact: Some(CoachCatalogSourceArtifact {
                feed_locator: "/srv/feeds/demo_manual".to_string(),
                ..sample_coach_catalog_source_artifact(
                    "catalogsourceartifact_demo_manual",
                    &["op_border_runner"],
                )
            }),
            updated_by_account_id: "acct_ops_demo".to_string(),
            updated_at_iso: "2026-04-15T08:05:00Z".to_string(),
        };
        let latest_import_run =
            sample_coach_catalog_import_run("catalogimportrun_demo_manual", &["op_border_runner"]);
        let allowed_operator_scope =
            coach_allowed_saved_view_operator_scope(&["op_demo_express".to_string()]);

        let payload = coach_operator_catalog_import_config_payload_for_scope(
            &config,
            Some(&persisted_config),
            Some(&latest_import_run),
            &allowed_operator_scope,
        );

        assert_eq!(payload["configured"], false);
        assert_eq!(payload["status"], "missing");
        assert_eq!(payload["config_origin"], "operator_scope");
        assert_eq!(payload["source_artifact"], Value::Null);
        assert_eq!(payload["latest_import_run"], Value::Null);
    }

