    #[test]
    fn coach_operator_feed_health_response_payload_exposes_summary_and_rows() {
        let payload = coach_operator_feed_health_response_payload(&[
            CoachCatalogOperatorFeedHealth {
                operator_id: "op_demo_a".to_string(),
                operator_name: "Demo A".to_string(),
                operator_integration_mode: "feed".to_string(),
                feed_kind: "static_catalog".to_string(),
                source_kind: "gtfs".to_string(),
                sync_status: "ok".to_string(),
                freshness_status: "fresh".to_string(),
                last_attempted_at_iso: Some("2026-04-15T08:00:00Z".to_string()),
                last_succeeded_at_iso: Some("2026-04-15T08:00:00Z".to_string()),
                freshness_expires_at_iso: Some("2026-04-16T08:00:00Z".to_string()),
                records_ingested: 12,
                error_message: None,
            },
            CoachCatalogOperatorFeedHealth {
                operator_id: "op_demo_b".to_string(),
                operator_name: "Demo B".to_string(),
                operator_integration_mode: "hybrid".to_string(),
                feed_kind: "gtfs_rt_trip_updates".to_string(),
                source_kind: "gtfs_rt".to_string(),
                sync_status: "error".to_string(),
                freshness_status: "stale".to_string(),
                last_attempted_at_iso: Some("2026-04-15T08:05:00Z".to_string()),
                last_succeeded_at_iso: None,
                freshness_expires_at_iso: None,
                records_ingested: 0,
                error_message: Some("upstream timeout".to_string()),
            },
        ]);

        assert_eq!(payload["summary"]["operators_total"], 2);
        assert_eq!(payload["summary"]["healthy_operators"], 1);
        assert_eq!(payload["summary"]["degraded_feeds"], 1);
        assert_eq!(payload["summary"]["stale_feeds"], 1);
        assert_eq!(payload["feeds"][0]["operator_id"], "op_demo_b");
        assert_eq!(payload["feeds"][1]["records_ingested"], 12);
    }

    #[test]
    fn coach_operator_feed_sync_is_healthy_accepts_known_healthy_aliases() {
        assert!(coach_operator_feed_sync_is_healthy("ok"));
        assert!(coach_operator_feed_sync_is_healthy("succeeded"));
        assert!(coach_operator_feed_sync_is_healthy("healthy"));
        assert!(!coach_operator_feed_sync_is_healthy("degraded"));
        assert!(!coach_operator_feed_sync_is_healthy("failed"));
    }

    #[test]
    fn coach_operator_feed_freshness_is_healthy_accepts_missing() {
        assert!(coach_operator_feed_freshness_is_healthy("fresh"));
        assert!(coach_operator_feed_freshness_is_healthy("missing"));
        assert!(!coach_operator_feed_freshness_is_healthy("aging"));
        assert!(!coach_operator_feed_freshness_is_healthy("stale"));
    }

