    #[test]
    fn parse_coach_catalog_import_run_cursor_accepts_started_at_and_run_id() {
        let cursor =
            parse_coach_catalog_import_run_cursor("2026-04-15T06:00:00Z|catalogimportrun_demo_ok")
                .expect("cursor should parse");
        assert_eq!(cursor.started_at.to_rfc3339(), "2026-04-15T06:00:00+00:00");
        assert_eq!(cursor.import_run_id, "catalogimportrun_demo_ok");
    }

    #[test]
    fn parse_coach_catalog_import_run_filters_accepts_status_replay_scope_and_issue_filters() {
        let filters =
            parse_coach_catalog_import_run_filters(&CoachOperatorCatalogImportRunsQuery {
                limit: Some(8),
                cursor: Some("2026-04-15T06:00:00Z|catalogimportrun_demo_ok".to_string()),
                status: Some("failed".to_string()),
                replay_scope: Some("attention".to_string()),
                severity: Some("error".to_string()),
                stage: Some("load_feed".to_string()),
            })
            .expect("filters should parse");

        assert_eq!(filters.status.as_deref(), Some("failed"));
        assert_eq!(filters.replay_scope.as_deref(), Some("attention"));
        assert_eq!(filters.severity.as_deref(), Some("error"));
        assert_eq!(filters.stage.as_deref(), Some("load_feed"));
        assert_eq!(
            filters
                .cursor
                .as_ref()
                .map(|cursor| cursor.import_run_id.as_str()),
            Some("catalogimportrun_demo_ok")
        );
    }

    #[test]
    fn parse_coach_catalog_import_run_filters_rejects_invalid_replay_scope() {
        let error = parse_coach_catalog_import_run_filters(&CoachOperatorCatalogImportRunsQuery {
            limit: Some(8),
            cursor: None,
            status: None,
            replay_scope: Some("broken".to_string()),
            severity: None,
            stage: None,
        })
        .expect_err("invalid replay scope should fail");

        assert_eq!(
            error.detail,
            "replay_scope must be one of: all, replays_only, with_replays, attention"
        );
    }

