    #[test]
    fn normalize_coach_catalog_import_run_saved_view_owner_account_id_filter_accepts_safe_tokens() {
        let owner_account_id =
            normalize_coach_catalog_import_run_saved_view_owner_account_id_filter(Some(
                "acct_ops_shared",
            ))
            .expect("owner account id filter should parse");
        assert_eq!(owner_account_id.as_deref(), Some("acct_ops_shared"));

        let empty =
            normalize_coach_catalog_import_run_saved_view_owner_account_id_filter(Some("   "))
                .expect("blank owner account id should be treated as empty");
        assert_eq!(empty, None);
        let all =
            normalize_coach_catalog_import_run_saved_view_owner_account_id_filter(Some("all"))
                .expect("'all' owner account id should be treated as empty");
        assert_eq!(all, None);
    }

    #[test]
    fn normalize_coach_catalog_import_run_saved_view_owner_account_id_filter_rejects_unsafe_tokens()
    {
        let err = normalize_coach_catalog_import_run_saved_view_owner_account_id_filter(Some(
            "acct ops shared",
        ))
        .expect_err("unsafe owner account id should fail");
        assert!(err.detail.contains("owner_account_id must be a safe token"));
    }

    #[test]
    fn coach_filter_payout_imports_respects_cursor_boundary() {
        let mut import_map = CoachSettlementPayoutImportMap::new();
        for (import_id, imported_at) in [
            ("payoutimport_demo_c", "2026-04-14T10:08:00Z"),
            ("payoutimport_demo_b", "2026-04-13T10:08:00Z"),
            ("payoutimport_demo_a", "2026-04-12T10:08:00Z"),
        ] {
            import_map.insert(
                import_id.to_string(),
                CoachSettlementPayoutImportEntry {
                    import_id: import_id.to_string(),
                    import_batch_id: None,
                    payout_run_id: format!("run_{import_id}"),
                    import_source: "bank_report".to_string(),
                    external_status: "executed".to_string(),
                    payment_reference: Some(format!("payment_{import_id}")),
                    external_reference: Some("bank_file_2026w15".to_string()),
                    imported_at: imported_at.to_string(),
                    imported_by_account_id: "acct_finance_demo".to_string(),
                    previous_run_status: "queued".to_string(),
                    applied_run_status: "paid".to_string(),
                    note: None,
                },
            );
        }

        let filtered = coach_filter_payout_imports(
            &import_map,
            Some(&CoachOperatorPayoutImportCursor {
                imported_at: chrono::DateTime::parse_from_rfc3339("2026-04-13T10:08:00Z")
                    .expect("cursor imported_at should parse"),
                import_id: "payoutimport_demo_b".to_string(),
            }),
        );

        assert_eq!(filtered.len(), 1);
        assert_eq!(filtered[0].import_id, "payoutimport_demo_a");
    }

