    #[test]
    fn coach_validate_payout_import_rework_source_batch_enforces_parent_rules() {
        let mut batch_map = CoachSettlementPayoutImportBatchMap::new();
        batch_map.insert(
            "payoutbatch_demo_origin".to_string(),
            CoachSettlementPayoutImportBatchEntry {
                batch_id: "payoutbatch_demo_origin".to_string(),
                dry_run: false,
                import_source: "bank_report".to_string(),
                report_name: "bank_report_2026w15.csv".to_string(),
                report_format: "csv".to_string(),
                rework_of_batch_id: None,
                report_checksum_sha256: "sha256_demo_report".to_string(),
                total_rows: 2,
                applied_rows: 1,
                failed_rows: 1,
                payout_run_ids: vec!["payoutrun_demo_express".to_string()],
                operator_ids: vec!["op_demo_express".to_string()],
                failure_messages: vec!["line 3 (payoutrun_demo_failed): not found".to_string()],
                created_at: "2026-04-14T10:08:00Z".to_string(),
                created_by_account_id: "acct_finance_demo".to_string(),
                note: Some("uploaded from coach ops console".to_string()),
            },
        );
        batch_map.insert(
            "payoutbatch_demo_rework".to_string(),
            CoachSettlementPayoutImportBatchEntry {
                batch_id: "payoutbatch_demo_rework".to_string(),
                dry_run: false,
                import_source: "bank_report".to_string(),
                report_name: "coach-payout-import-rework-payoutbatch_demo_origin.csv".to_string(),
                report_format: "csv".to_string(),
                rework_of_batch_id: Some("payoutbatch_demo_origin".to_string()),
                report_checksum_sha256: "sha256_demo_rework".to_string(),
                total_rows: 1,
                applied_rows: 1,
                failed_rows: 0,
                payout_run_ids: vec!["payoutrun_demo_failed".to_string()],
                operator_ids: vec!["op_demo_express".to_string()],
                failure_messages: vec![],
                created_at: "2026-04-14T11:08:00Z".to_string(),
                created_by_account_id: "acct_finance_demo".to_string(),
                note: Some("rework upload".to_string()),
            },
        );

        assert_eq!(
            coach_validate_payout_import_rework_source_batch(
                &batch_map,
                Some("payoutbatch_demo_origin"),
                "bank_report",
                "csv",
            )
            .expect("matching rework parent should validate"),
            Some("payoutbatch_demo_origin".to_string())
        );
        assert_eq!(
            coach_resolve_payout_import_rework_origin_batch_id(
                Some("payoutbatch_demo_rework"),
                &batch_map,
            ),
            Some("payoutbatch_demo_origin".to_string())
        );
        assert!(coach_validate_payout_import_rework_source_batch(
            &batch_map,
            Some("payoutbatch_demo_rework"),
            "psp_report",
            "csv",
        )
        .is_err());
        assert_eq!(
            coach_collect_payout_import_follow_up_batch_ids("payoutbatch_demo_origin", &batch_map),
            vec!["payoutbatch_demo_rework".to_string()]
        );
    }

    #[tokio::test]
    async fn coach_payout_import_report_download_response_serves_attachment_bytes() {
        let report_body = "payout_run_id,external_status\npayoutrun_demo_express,executed";
        let artifact = CoachSettlementPayoutImportReportArtifactEntry {
            artifact_id: "payoutreport_demo_download".to_string(),
            batch_id: "payoutbatch_demo_download".to_string(),
            artifact_kind: COACH_PAYOUT_IMPORT_ARTIFACT_KIND_SOURCE_REPORT.to_string(),
            import_source: "bank_report".to_string(),
            report_name: "bank_report_2026w15.csv".to_string(),
            report_format: "csv".to_string(),
            file_name: "coach-payout-import-payoutbatch_demo_download.csv".to_string(),
            mime_type: "text/csv; charset=utf-8".to_string(),
            download_path: "/downloads/coach/payout_import_reports/payoutreport_demo_download.csv"
                .to_string(),
            checksum_sha256: sha256_hex(report_body),
            content_length_bytes: report_body.len() as i64,
            report_body: report_body.to_string(),
            operator_ids: vec!["op_demo_express".to_string()],
            created_at: "2026-04-14T10:08:00Z".to_string(),
            created_by_account_id: "acct_finance_demo".to_string(),
            note: Some("uploaded from coach ops console".to_string()),
        };

        let response = coach_payout_import_report_download_response(&artifact)
            .expect("report artifact download should succeed");
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(
            response
                .headers()
                .get(CONTENT_TYPE)
                .and_then(|value| value.to_str().ok()),
            Some("text/csv; charset=utf-8")
        );
        assert_eq!(
            response
                .headers()
                .get(header::CONTENT_DISPOSITION)
                .and_then(|value| value.to_str().ok()),
            Some("attachment; filename=\"coach-payout-import-payoutbatch_demo_download.csv\"")
        );
    }

