    #[test]
    fn coach_parse_payout_import_batch_csv_supports_bank_and_psp_profile_rules() {
        let bank_rows = coach_parse_payout_import_batch_csv(
            "bank_report",
            "merchant_reference;bank_status;transfer_reference;bank_file_reference;executed_at;comment\n\
             payoutrun_demo_express;completed;bank_ref_1;bank_file_2026w15;2026-04-14T10:06:00Z;bank row",
        )
        .expect("bank report aliases should parse");
        assert_eq!(bank_rows[0].payout_run_id, "payoutrun_demo_express");
        assert_eq!(bank_rows[0].external_status, "completed");
        assert_eq!(
            bank_rows[0].payment_reference.as_deref(),
            Some("bank_ref_1")
        );

        let psp_rows = coach_parse_payout_import_batch_csv(
            "psp_report",
            "merchant_reference\tpsp_status\tpsp_reference\tsettlement_reference\tbooked_at\tdescription\n\
             payoutrun_demo_express\tsucceeded\tpsp_ref_1\tpsp_batch_2026w15\t2026-04-14T10:06:00Z\tpsp row",
        )
        .expect("psp report aliases should parse");
        assert_eq!(psp_rows[0].payout_run_id, "payoutrun_demo_express");
        assert_eq!(psp_rows[0].external_status, "succeeded");
        assert_eq!(
            psp_rows[0].external_reference.as_deref(),
            Some("psp_batch_2026w15")
        );

        assert_eq!(
            canonical_coach_payout_import_status_for_source("bank_report", "completed")
                .expect("bank status should normalize"),
            "executed"
        );
        assert_eq!(
            canonical_coach_payout_import_status_for_source("psp_report", "succeeded")
                .expect("psp status should normalize"),
            "executed"
        );
        assert!(
            canonical_coach_payout_import_status_for_source("manual_upload", "booked").is_err()
        );
        assert!(coach_validate_required_payout_import_fields(
            "bank_report",
            "executed",
            None,
            Some("bank_file_2026w15"),
        )
        .is_err());
        assert!(coach_validate_required_payout_import_fields(
            "psp_report",
            "executed",
            Some("psp_ref_1"),
            None,
        )
        .is_err());
        assert!(coach_validate_required_payout_import_fields(
            "manual_upload",
            "pending",
            None,
            None,
        )
        .is_ok());
    }

    #[tokio::test]
    async fn coach_operator_payout_import_apply_requires_matching_preview_binding() {
        let state = mk_state("http://127.0.0.1".to_string(), 8 * 1024, false);
        let preview_command = CoachPayoutImportBatchCommand {
            import_source: "bank_report",
            report_name: "bank_report_2026w15.csv",
            report_format: "csv",
            rework_of_batch_id: Some("payoutbatch_demo_1"),
            report_checksum_sha256: "sha256_demo_report",
            total_rows: 2,
            dry_run: true,
            note: Some("uploaded from coach ops console"),
        };
        let preview_payload = coach_payout_import_batch_command_payload(&preview_command);
        let preview_fingerprint = coach_command_request_fingerprint(
            "coach_operator_payout_import_batch_create",
            &preview_payload,
        );
        let preview_entry =
            coach_build_payout_import_preview_entry(&CoachPayoutImportPreviewBuild {
                principal_account_id: "acct_finance_demo",
                operator_ids: &["op_demo_express".to_string()],
                request_fingerprint: preview_fingerprint.as_str(),
                command: preview_command,
            });
        let preview_token = preview_entry.preview_token.clone();
        coach_store_settlement_payout_import_preview_entry(&state, &preview_entry)
            .await
            .expect("preview entry should store");

        assert!(coach_validate_payout_import_apply_preview_binding(
            &state,
            false,
            Some(preview_token.as_str()),
            "acct_finance_demo",
            preview_fingerprint.as_str(),
            "sha256_demo_report",
        )
        .await
        .is_ok());

        let missing = coach_validate_payout_import_apply_preview_binding(
            &state,
            false,
            None,
            "acct_finance_demo",
            preview_fingerprint.as_str(),
            "sha256_demo_report",
        )
        .await
        .expect_err("apply without preview confirmation must fail");
        assert_eq!(
            missing.detail,
            "preview confirmation required before applying payout report"
        );

        let stale_preview = coach_validate_payout_import_apply_preview_binding(
            &state,
            false,
            Some("previewtoken_stale_demo_1"),
            "acct_finance_demo",
            preview_fingerprint.as_str(),
            "sha256_demo_report",
        )
        .await
        .expect_err("stale preview token must fail");
        assert_eq!(
            stale_preview.detail,
            "payout import preview token is stale; run preview again before apply"
        );

        coach_update_settlement_payout_import_preview_status(
            &state,
            "acct_finance_demo",
            preview_token.as_str(),
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED,
            Some("2026-04-14T10:09:00Z"),
            None,
        )
        .await
        .expect("preview should be markable as consumed");
        let consumed = coach_validate_payout_import_apply_preview_binding(
            &state,
            false,
            Some(preview_token.as_str()),
            "acct_finance_demo",
            preview_fingerprint.as_str(),
            "sha256_demo_report",
        )
        .await
        .expect_err("consumed preview token must fail");
        assert_eq!(
            consumed.detail,
            "payout import preview already used; run preview again before apply"
        );

        let mut invalidated_preview_entry =
            coach_build_payout_import_preview_entry(&CoachPayoutImportPreviewBuild {
                principal_account_id: "acct_finance_demo",
                operator_ids: &["op_demo_express".to_string()],
                request_fingerprint: preview_fingerprint.as_str(),
                command: preview_command,
            });
        invalidated_preview_entry.preview_token = "previewtoken_invalidated_demo_1".to_string();
        invalidated_preview_entry.preview_status =
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED.to_string();
        invalidated_preview_entry.invalidated_at = Some("2026-04-14T10:10:00Z".to_string());
        coach_store_settlement_payout_import_preview_entry(&state, &invalidated_preview_entry)
            .await
            .expect("invalidated preview entry should store");
        let invalidated = coach_validate_payout_import_apply_preview_binding(
            &state,
            false,
            Some(invalidated_preview_entry.preview_token.as_str()),
            "acct_finance_demo",
            preview_fingerprint.as_str(),
            "sha256_demo_report",
        )
        .await
        .expect_err("invalidated preview token must fail");
        assert_eq!(
            invalidated.detail,
            "payout import preview was invalidated; run preview again before apply"
        );

        let mut expired_preview_entry =
            coach_build_payout_import_preview_entry(&CoachPayoutImportPreviewBuild {
                principal_account_id: "acct_finance_demo",
                operator_ids: &["op_demo_express".to_string()],
                request_fingerprint: preview_fingerprint.as_str(),
                command: preview_command,
            });
        expired_preview_entry.preview_token = "previewtoken_expired_demo_1".to_string();
        expired_preview_entry.preview_status =
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_EXPIRED.to_string();
        expired_preview_entry.expires_at = "2026-04-01T09:58:00Z".to_string();
        coach_store_settlement_payout_import_preview_entry(&state, &expired_preview_entry)
            .await
            .expect("expired preview entry should store");
        let expired = coach_validate_payout_import_apply_preview_binding(
            &state,
            false,
            Some(expired_preview_entry.preview_token.as_str()),
            "acct_finance_demo",
            preview_fingerprint.as_str(),
            "sha256_demo_report",
        )
        .await
        .expect_err("expired preview token must fail");
        assert_eq!(
            expired.detail,
            "payout import preview expired; run preview again before apply"
        );
    }

    #[tokio::test]
    async fn coach_transition_settlement_payout_import_preview_status_requires_expected_state() {
        let state = mk_state("http://127.0.0.1".to_string(), 8 * 1024, false);
        let preview_command = CoachPayoutImportBatchCommand {
            import_source: "bank_report",
            report_name: "bank_report_2026w15.csv",
            report_format: "csv",
            rework_of_batch_id: Some("payoutbatch_demo_1"),
            report_checksum_sha256: "sha256_demo_report",
            total_rows: 2,
            dry_run: true,
            note: Some("uploaded from coach ops console"),
        };
        let preview_payload = coach_payout_import_batch_command_payload(&preview_command);
        let preview_fingerprint = coach_command_request_fingerprint(
            "coach_operator_payout_import_batch_create",
            &preview_payload,
        );
        let preview_entry =
            coach_build_payout_import_preview_entry(&CoachPayoutImportPreviewBuild {
                principal_account_id: "acct_finance_demo",
                operator_ids: &["op_demo_express".to_string()],
                request_fingerprint: preview_fingerprint.as_str(),
                command: preview_command,
            });
        let preview_token = preview_entry.preview_token.clone();
        coach_store_settlement_payout_import_preview_entry(&state, &preview_entry)
            .await
            .expect("preview entry should store");

        assert!(coach_transition_settlement_payout_import_preview_status(
            &state,
            "acct_finance_demo",
            preview_token.as_str(),
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE,
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED,
            None,
            Some("2026-04-14T10:10:00Z"),
        )
        .await
        .expect("active preview should transition once"));
        assert!(!coach_transition_settlement_payout_import_preview_status(
            &state,
            "acct_finance_demo",
            preview_token.as_str(),
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_ACTIVE,
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_CONSUMED,
            Some("2026-04-14T10:11:00Z"),
            None,
        )
        .await
        .expect("terminal preview state must not be overwritten"));

        let stored = coach_find_settlement_payout_import_preview_entry(
            &state,
            "acct_finance_demo",
            preview_token.as_str(),
        )
        .await
        .expect("preview lookup should succeed")
        .expect("preview entry should exist");
        assert_eq!(
            stored.preview_status,
            COACH_PAYOUT_IMPORT_PREVIEW_STATUS_INVALIDATED
        );
        assert_eq!(stored.consumed_at, None);
        assert_eq!(
            stored.invalidated_at.as_deref(),
            Some("2026-04-14T10:10:00Z")
        );
    }

