    fn coach_admin_disruption_record_payload_omits_ambiguous_booking_id_for_multi_booking_trip() {
        let trip = json!({
            "trip_id": "trip_runtime_disruption_shared",
            "journey_id": "journey_runtime_disruption_shared",
            "booking_id": "booking_runtime_disruption_primary",
            "operator_name": "Runtime Disruption Operator",
            "from": "Damascus",
            "to": "Homs",
            "departure_at": "2026-04-12T08:00:00Z",
            "arrival_at": "2026-04-12T10:00:00Z",
            "manifest_count": 2,
            "boarded_count": 0,
            "denied_count": 0,
            "no_show_count": 0,
            "pending_count": 2,
        });

        let grouped = coach_admin_disruption_record_payload(
            &trip,
            "op_runtime_runtime_disruption_operator",
            &[],
            2,
            2,
            None,
        );
        let singleton = coach_admin_disruption_record_payload(
            &trip,
            "op_runtime_runtime_disruption_operator",
            &[],
            1,
            1,
            None,
        );

        assert!(grouped["booking_id"].is_null());
        assert_eq!(grouped["affected_booking_count"], 2);
        assert_eq!(
            singleton["booking_id"],
            "booking_runtime_disruption_primary"
        );
    }

