    #[test]
    fn coach_filter_booking_aggregates_by_operator_scope_uses_persisted_operator_ids() {
        let aggregates = vec![
            CoachStoredBookingAggregate {
                account_id: "acct_demo_express".to_string(),
                booking: coach_booking_payload_for_offer(
                    "booking_scope_a",
                    "offer_scope_a",
                    Some("hold_scope_a"),
                    1,
                    "ticketed",
                ),
                offer: Some(json!({
                    "offer_id": "offer_scope_a",
                    "operator_id": "op_demo_express",
                })),
                hold: None,
                journey: None,
                passengers_manifest: json!([]),
                tickets: vec![coach_ticket_payload_for_booking(
                    "ticket_scope_a",
                    "booking_scope_a",
                    "pax_scope_a",
                    0,
                )],
            },
            CoachStoredBookingAggregate {
                account_id: "acct_border_runner".to_string(),
                booking: coach_booking_payload_for_offer(
                    "booking_scope_b",
                    "offer_scope_b",
                    Some("hold_scope_b"),
                    1,
                    "ticketed",
                ),
                offer: Some(json!({
                    "offer_id": "offer_scope_b",
                    "operator_id": "op_border_runner",
                })),
                hold: None,
                journey: None,
                passengers_manifest: json!([]),
                tickets: vec![coach_ticket_payload_for_booking(
                    "ticket_scope_b",
                    "booking_scope_b",
                    "pax_scope_b",
                    0,
                )],
            },
        ];
        let allowed_operator_scope =
            coach_allowed_saved_view_operator_scope(&["op_demo_express".to_string()]);

        let filtered =
            coach_filter_booking_aggregates_by_operator_scope(&aggregates, &allowed_operator_scope);

        assert_eq!(filtered.len(), 1);
        assert_eq!(
            filtered[0]
                .booking
                .get("booking_id")
                .and_then(Value::as_str),
            Some("booking_scope_a")
        );
    }

