    fn coach_stored_mutation_replay_entry_for_test(
        command: &str,
        idempotency_key: &str,
        created_at: &str,
        response_json: Value,
    ) -> CoachStoredMutationReplayEntry {
        CoachStoredMutationReplayEntry {
            command: command.to_string(),
            idempotency_key: idempotency_key.to_string(),
            response_json,
            created_at: created_at.to_string(),
        }
    }

    #[test]
    fn coach_build_mutation_replay_index_prefers_later_idempotency_key_when_created_at_ties() {
        let booking_id = "booking_replay_tie";
        let earlier = coach_stored_mutation_replay_entry_for_test(
            "coach_booking_create",
            "idem_a",
            "2026-04-20T10:00:00Z",
            json!({
                "booking": {"booking_id": booking_id},
                "payment": {"authorization_reference": "auth_early"},
            }),
        );
        let later = coach_stored_mutation_replay_entry_for_test(
            "coach_booking_create",
            "idem_b",
            "2026-04-20T10:00:00Z",
            json!({
                "booking": {"booking_id": booking_id},
                "payment": {"authorization_reference": "auth_late"},
            }),
        );

        let index = coach_build_mutation_replay_index(&[later.clone(), earlier]);
        let latest = index
            .booking_creates
            .get(booking_id)
            .expect("booking replay");

        assert_eq!(latest.idempotency_key, "idem_b");
        assert_eq!(
            latest.response_json["payment"]["authorization_reference"],
            "auth_late"
        );
    }

