    #[test]
    fn coach_latest_change_request_replay_uses_idempotency_tiebreak_for_equal_timestamps() {
        let earlier = coach_stored_mutation_replay_entry_for_test(
            "coach_rebook_request",
            "idem_a",
            "2026-04-20T10:00:00Z",
            json!({
                "booking": {"booking_id": "booking_replay_tie"},
                "change_request": {"status": "requested", "change_request_id": "chg_early"},
            }),
        );
        let later = coach_stored_mutation_replay_entry_for_test(
            "coach_rebook_request",
            "idem_b",
            "2026-04-20T10:00:00Z",
            json!({
                "booking": {"booking_id": "booking_replay_tie"},
                "change_request": {"status": "approved", "change_request_id": "chg_late"},
            }),
        );

        let replays = [earlier, later];
        let latest = coach_latest_change_request_replay(&replays).expect("latest change replay");

        assert_eq!(latest.idempotency_key, "idem_b");
        assert_eq!(
            coach_change_request_payload_from_replay(latest)
                .and_then(|payload| payload["change_request_id"].as_str().map(str::to_string))
                .as_deref(),
            Some("chg_late")
        );
        assert_eq!(
            coach_change_request_status_from_replay(latest).as_deref(),
            Some("approved")
        );
    }

