    #[test]
    fn coach_support_timeline_uses_latest_change_resolution_audit_for_equal_timestamps() {
        let booking = json!({
            "booking_id": "booking_replay_tie",
            "created_at": "2026-04-20T09:00:00Z",
            "state": "ticketed",
            "currency": "EUR",
            "total_minor_units": 4200,
        });
        let change_request = json!({
            "change_request_id": "chg_late",
            "created_at": "2026-04-20T10:00:00Z",
            "status": "payment_failed",
            "target_offer_id": "offer_runtime_change",
            "currency": "EUR",
            "fare_difference_minor_units": 500,
            "change_fee_minor_units": 100,
            "total_due_minor_units": 600,
        });
        let compensation = json!({
            "status": "payment_failed",
            "reason": "card_declined",
            "recovery_reference": "recovery_ref_late",
        });
        let earlier = coach_stored_mutation_replay_entry_for_test(
            "coach_ticket_reissue_recovery",
            "idem_a",
            "2026-04-20T10:00:00Z",
            json!({
                "booking": {"booking_id": "booking_replay_tie"},
                "resolution_audit": {
                    "payment_method": "wallet",
                    "resolved_by_account_id": "acct_early",
                    "note": "early note",
                },
            }),
        );
        let later = coach_stored_mutation_replay_entry_for_test(
            "coach_ticket_reissue_recovery_admin",
            "idem_b",
            "2026-04-20T10:00:00Z",
            json!({
                "booking": {"booking_id": "booking_replay_tie"},
                "resolution_audit": {
                    "payment_method": "cash",
                    "resolved_by_account_id": "acct_late",
                    "note": "late note",
                },
            }),
        );
        let replays = [earlier, later];
        let latest_change_replay =
            coach_latest_change_request_replay(&replays).expect("latest change replay");

        let timeline = coach_support_case_timeline_from_runtime(&CoachSupportCaseTimelineContext {
            booking: &booking,
            payment_payload: None,
            compensation_payload: Some(&compensation),
            tickets: &[],
            refund_request: None,
            refund_review: None,
            change_request: Some(&change_request),
            latest_change_replay: Some(latest_change_replay),
            change_review: None,
            recent_events: &[],
        });

        let change_event = timeline
            .iter()
            .find(|entry| entry["event_type"].as_str() == Some("change_payment_failed"))
            .expect("change payment failed event");
        assert_eq!(change_event["title"], "Change recovery follow-up");
        assert_eq!(change_event["status_label"], "recovery_follow_up");
        let detail_lines = change_event["detail_lines"]
            .as_array()
            .expect("detail_lines");

        assert!(detail_lines
            .iter()
            .filter_map(Value::as_str)
            .any(|line| line == "Recovery method cash"));
        assert!(detail_lines
            .iter()
            .filter_map(Value::as_str)
            .any(|line| line == "Actor acct_late"));
        assert!(detail_lines
            .iter()
            .filter_map(Value::as_str)
            .any(|line| line == "Ops note late note"));
        assert!(detail_lines
            .iter()
            .filter_map(Value::as_str)
            .all(|line| line != "Recovery method wallet"));
    }

