    async fn coach_mutation_replay_test_guard() -> tokio::sync::OwnedMutexGuard<()> {
        static TEST_LOCK: OnceLock<Arc<tokio::sync::Mutex<()>>> = OnceLock::new();
        TEST_LOCK
            .get_or_init(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone()
            .lock_owned()
            .await
    }

    #[tokio::test]
    async fn coach_idempotent_response_replays_and_rejects_conflicting_reuse() {
        let _guard = coach_mutation_replay_test_guard().await;
        coach_mutation_replay_store().write().await.clear();
        let state = mk_state("http://127.0.0.1".to_string(), 1024, false);
        let response = coach_hold_create_response(
            "coach-hold-test-1",
            "fp_hold_create_1",
            "offer_demo_express_direct",
            1,
            &[String::from("pax_1")],
            &[String::from("4A")],
        );
        let first = coach_store_or_replay_idempotent_response(
            &state,
            "acct_demo",
            "coach_hold_create",
            "coach-hold-test-1",
            "fp_hold_create_1",
            response,
        )
        .await
        .expect("first response");
        let first_body = to_bytes(first.into_body(), usize::MAX)
            .await
            .expect("first body");
        let first_value: Value = serde_json::from_slice(&first_body).expect("first json");
        assert_eq!(first_value["idempotency"]["replayed"], false);

        let replay = coach_store_or_replay_idempotent_response(
            &state,
            "acct_demo",
            "coach_hold_create",
            "coach-hold-test-1",
            "fp_hold_create_1",
            json!({"unexpected": true}),
        )
        .await
        .expect("replay response");
        let replay_body = to_bytes(replay.into_body(), usize::MAX)
            .await
            .expect("replay body");
        let replay_value: Value = serde_json::from_slice(&replay_body).expect("replay json");
        assert_eq!(replay_value["idempotency"]["replayed"], true);
        assert_eq!(replay_value["command"], "hold_create");

        let err = coach_store_or_replay_idempotent_response(
            &state,
            "acct_demo",
            "coach_hold_create",
            "coach-hold-test-1",
            "fp_hold_create_conflict",
            json!({"unexpected": true}),
        )
        .await
        .expect_err("conflicting fingerprint must fail");
        assert_eq!(err.status, StatusCode::BAD_REQUEST);
        assert_eq!(
            err.detail,
            "Idempotency-Key reused with different coach request parameters"
        );
    }

    #[tokio::test]
    async fn coach_idempotent_response_preflight_rejects_cross_command_reuse() {
        let _guard = coach_mutation_replay_test_guard().await;
        coach_mutation_replay_store().write().await.clear();
        let state = mk_state("http://127.0.0.1".to_string(), 1024, false);
        coach_store_or_replay_idempotent_response(
            &state,
            "acct_demo",
            "coach_hold_create",
            "coach-idempo-cross-command",
            "fp_hold_create_1",
            coach_hold_create_response(
                "coach-idempo-cross-command",
                "fp_hold_create_1",
                "offer_demo_express_direct",
                1,
                &[String::from("pax_1")],
                &[String::from("4A")],
            ),
        )
        .await
        .expect("initial command should store");

        let err = coach_find_replayed_idempotent_response(
            &state,
            "acct_demo",
            "coach_booking_create",
            "coach-idempo-cross-command",
            "fp_booking_create_1",
        )
        .await
        .expect_err("cross-command preflight reuse must fail");
        assert_eq!(err.status, StatusCode::BAD_REQUEST);
        assert_eq!(
            err.detail,
            "Idempotency-Key reused for a different coach command"
        );
    }

